grant select, insert, update, delete on public.document_extractions to authenticated;
grant select, insert, update, delete on public.document_replies     to authenticated;
grant select, insert                 on public.analysis_corrections to authenticated;
grant select, insert                 on public.ai_request_log       to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  0007_subsidy_programs  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- SwissAI Suite — 0007 SUBSIDY: catalogo programmi di incentivo (dati reali)
--
-- Sposta i programmi dal dataset hardcoded (demo) a una TABELLA gestibile, così
-- si aggiornano senza deploy del frontend e ogni voce porta con sé la fonte
-- ufficiale + la data di revisione (§ verificabilità: nessun dato inventato).
--
-- È un CATALOGO condiviso (non dati per-azienda): lettura per tutti gli utenti
-- autenticati, scrittura solo server-side (service_role) previa verifica umana.
-- Il motore di matching resta invariato: il service ricostruisce il ProgramModel.
-- ============================================================================

create table if not exists public.subsidy_programs (
  id                            text primary key,            -- slug stabile (es. 'innosuisse'); referenziato da subsidy_matches/cases
  name                          text not null,
  authority                     text not null,
  support_type                  text not null default 'grant',   -- grant | tax_relief | guarantee | loan | reimbursement | advisory | other
  geography                     text[] not null default '{}',    -- es. {'ALL'} oppure {'Ticino'}
  target_sectors                text[] not null default '{}',    -- id settori ammessi, oppure {'ALL'}
  company_size_min              integer not null default 0,
  company_size_max              integer not null default 100000,
  project_types                 text[] not null default '{}',    -- id tipi progetto pertinenti
  -- [{ "id","text","question","mustBe":"si","hard":true|false }]
  requirements                  jsonb not null default '[]'::jsonb,
  -- [{ "id","text","question":null|string,"triggeringAnswer":null|string,"evaluable":bool }]
  exclusions                    jsonb not null default '[]'::jsonb,
  contribution_description      text,
  application_window            text,
  must_apply_before_start       boolean not null default false,
  must_apply_before_start_text  text,
  documents_required            text[] not null default '{}',
  -- Provenienza e verificabilità (§)
  official_source_url           text not null,
  source_title                  text,
  last_checked_at               date,
  data_status                   text not null default 'verified',  -- verified | recheck | demo
  active                        boolean not null default true,
  created_at                    timestamptz not null default now(),
  updated_at                    timestamptz not null default now()
);

create index if not exists idx_subsidy_programs_active on public.subsidy_programs (active);

-- RLS: catalogo condiviso. Lettura ai membri autenticati; scrittura solo service_role.
alter table public.subsidy_programs enable row level security;

drop policy if exists subsidy_programs_select on public.subsidy_programs;
create policy subsidy_programs_select on public.subsidy_programs
  for select to authenticated using (active = true);

grant select on public.subsidy_programs to authenticated;

drop trigger if exists trg_subsidy_programs_updated on public.subsidy_programs;
create trigger trg_subsidy_programs_updated before update on public.subsidy_programs
  for each row execute function public.set_updated_at();

-- >>>>>>>>>>>>>>>>>>>>  0008_analysis_truth  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0008 — "verità dell'analisi": correzioni di correttezza e sicurezza.
--
-- 1) ai_request_log: chiudere la falla per cui un membro poteva falsificare il
--    log e bloccare l'AI dell'intera azienda (rate limit avvelenato).
-- 2) document_analyses.amount_type: il tipo dell'importo principale, per non
--    presentare mai una multa come "importo dovuto" (§12).
-- 3) document_extractions.truncated: dichiarare quando il testo inviato al
--    modello è stato tagliato, invece di spacciare l'analisi per completa (§28).
--
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1) ai_request_log — un membro poteva inserire righe a nome di ALTRI utenti e
--    con `created_at` arbitrario (anche futuro). Con 12 righe nella finestra si
--    rendeva il rate limit un 429 permanente per tutti i colleghi, e l'audit
--    diventava inaffidabile perché `user_id` non era attribuibile.
--    Le policy gemelle (replies, corrections) vincolavano già l'identità: qui
--    mancava. Si allinea, e si impedisce di retrodatare/postdatare la riga.
-- ---------------------------------------------------------------------------
alter table public.ai_request_log
  alter column created_at set default now();

drop policy if exists ai_log_insert_member on public.ai_request_log;
create policy ai_log_insert_member on public.ai_request_log
  for insert to authenticated
  with check (
    public.is_company_member(company_id)
    and user_id = auth.uid()                                   -- non si scrive a nome d'altri
    and created_at between now() - interval '5 minutes'        -- niente righe retrodatate
                       and now() + interval '1 minute'         -- né postdatate (rate limit avvelenato)
  );

-- La colonna `created_at` non deve poter essere scelta liberamente dal client:
-- il default `now()` vale quando non viene passata, la policy blocca il resto.
comment on policy ai_log_insert_member on public.ai_request_log is
  'Un membro può registrare solo le PROPRIE chiamate, con timestamp coerente: impedisce di avvelenare il rate limit altrui e mantiene il log attribuibile.';

-- ---------------------------------------------------------------------------
-- 2) Tipo dell'importo principale (§12).
--    `amount` conserva l'importo "di testa": se il documento non contiene un
--    importo DOVUTO si ripiega sul più rilevante, ma il tipo va dichiarato
--    perché una multa non è una richiesta di pagamento.
-- ---------------------------------------------------------------------------
alter table public.document_analyses
  add column if not exists amount_type text;

comment on column public.document_analyses.amount_type is
  'Tipo dell''importo in `amount`: due | fine | fee | contribution | other. NULL = nessun importo rilevato.';

-- ---------------------------------------------------------------------------
-- 3) Troncamento del testo dichiarato (§28).
--    Oltre il limite di caratteri il modello vede solo l'inizio del documento:
--    va registrato, altrimenti un'analisi parziale sembra completa.
-- ---------------------------------------------------------------------------
alter table public.document_extractions
  add column if not exists truncated boolean not null default false;

comment on column public.document_extractions.truncated is
  'true = il testo inviato al modello è stato tagliato al limite: l''analisi può non coprire la parte finale del documento.';

-- >>>>>>>>>>>>>>>>>>>>  0009_quota_and_upload_limits  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0009 — Controllo abusi e costi: quota AI atomica + limiti di upload reali.
--
-- 1) Rate limit §50: oggi è "leggi-poi-agisci" (si conta prima del lavoro e si
--    scrive dopo), quindi N richieste concorrenti leggono lo stesso conteggio e
--    passano TUTTE. Qui la verifica e la prenotazione dello slot diventano una
--    sola operazione serializzata per azienda.
-- 2) Il limite di dimensione file si fidava di `documents.file_size`, colonna
--    scritta dal browser: si impone il limite sul BUCKET, dove il client non
--    può mentire, insieme ai tipi MIME ammessi.
--
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1) Quota AI atomica.
--    `pg_advisory_xact_lock` serializza le richieste della STESSA azienda per la
--    durata della transazione: due chiamate concorrenti non possono più leggere
--    lo stesso conteggio e passare entrambe. Aziende diverse non si bloccano a
--    vicenda (il lock è sull'id dell'azienda).
--    La riga viene PRENOTATA subito con stato 'pending': una richiesta in corso
--    occupa la sua quota, che è la semantica corretta. `finalize_ai_request` la
--    completa con l'esito reale.
-- ---------------------------------------------------------------------------
create or replace function public.try_consume_ai_quota(
  p_company_id uuid,
  p_kind text,
  p_limit int,
  p_document_id uuid default null,
  p_provider text default null,
  p_model text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count int;
  v_id uuid;
begin
  -- Autorizzazione esplicita: SECURITY DEFINER scavalca la RLS, quindi la
  -- membership va verificata qui dentro, non darla per scontata.
  if auth.uid() is null or not public.is_company_member(p_company_id) then
    raise exception 'not a member of company %', p_company_id using errcode = '42501';
  end if;

  -- Serializza le richieste concorrenti della stessa azienda.
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text, 0));

  select count(*) into v_count
    from public.ai_request_log
   where company_id = p_company_id
     and created_at > now() - interval '1 minute';

  if v_count >= p_limit then
    return null;                      -- quota esaurita: il chiamante risponde 429
  end if;

  insert into public.ai_request_log (company_id, user_id, document_id, kind, provider, model, status)
  values (p_company_id, auth.uid(), p_document_id, p_kind, p_provider, p_model, 'pending')
  returning id into v_id;

  return v_id;
end;
$$;

comment on function public.try_consume_ai_quota is
  'Verifica e consuma in modo ATOMICO uno slot di quota AI per l''azienda. Ritorna l''id della riga di log prenotata, oppure NULL se il limite è già stato raggiunto.';

-- Completa la riga prenotata con l'esito. SECURITY DEFINER perché al client non
-- viene concesso UPDATE diretto sul log (resta append-only dal suo punto di vista).
create or replace function public.finalize_ai_request(
  p_id uuid,
  p_status text,
  p_duration_ms int default null,
  p_input_tokens int default null,
  p_output_tokens int default null,
  p_error_code text default null,
  p_model text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.ai_request_log
     set status        = coalesce(p_status, status),
         duration_ms   = coalesce(p_duration_ms, duration_ms),
         input_tokens  = coalesce(p_input_tokens, input_tokens),
         output_tokens = coalesce(p_output_tokens, output_tokens),
         error_code    = coalesce(p_error_code, error_code),
         model         = coalesce(p_model, model)
   where id = p_id
     and user_id = auth.uid();        -- si completa solo la PROPRIA riga
end;
$$;

comment on function public.finalize_ai_request is
  'Completa con l''esito una riga di ai_request_log prenotata da try_consume_ai_quota. Un utente può aggiornare solo le proprie righe.';

revoke all on function public.try_consume_ai_quota(uuid, text, int, uuid, text, text) from public;
revoke all on function public.finalize_ai_request(uuid, text, int, int, int, text, text) from public;
grant execute on function public.try_consume_ai_quota(uuid, text, int, uuid, text, text) to authenticated;
grant execute on function public.finalize_ai_request(uuid, text, int, int, int, text, text) to authenticated;

-- ---------------------------------------------------------------------------
-- 2) Limiti di upload imposti dal BUCKET (il client non può aggirarli).
--    `documents.file_size` è scritto dal browser: usarlo come unico controllo
--    significa fidarsi di un valore che l'utente decide. Il bucket invece rifiuta
--    l'oggetto a monte.
--    15 MB = lo stesso tetto già applicato lato Edge Function (MAX_FILE_BYTES).
-- ---------------------------------------------------------------------------
update storage.buckets
   set file_size_limit = 15728640,             -- 15 MB
       allowed_mime_types = array[
         'application/pdf',
         'image/png', 'image/jpeg', 'image/jpg', 'image/webp', 'image/heic', 'image/tiff',
         'text/plain', 'message/rfc822'
       ]
 where id = 'company-documents';

-- >>>>>>>>>>>>>>>>>>>>  0010_analysis_immutability  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- SwissAI Suite — 0010 IMMUTABILITÀ DELL'ANALISI
--
-- Il problema che chiude. `document_analyses` era insieme due cose:
--   · lo SNAPSHOT dell'analisi AI, che il README dichiara immutabile;
--   · lo STATO MUTABILE dell'utente (spunte della checklist, bozza di risposta).
-- Per permettere la seconda, la 0002 concedeva update e delete sull'INTERA
-- tabella a ogni membro. Conseguenza: chiunque, con la sola chiave anon e una
-- sessione valida, poteva riscrivere via API scadenza, mittente e importi di
-- un'analisi — cioè proprio i campi su cui poggia la promessa di verificabilità.
-- L'immutabilità era un'affermazione della documentazione, non un vincolo.
--
-- Cosa fa questa migrazione:
--   1. action_progress — lo stato della checklist esce dall'analisi e va in una
--      tabella propria;
--   2. le bozze di risposta vivono solo in document_replies (che esiste dalla
--      0006); reply_draft/reply_language/reply_tone diventano deprecate;
--   3. MIGRA i dati esistenti e SOLO DOPO revoca update e delete;
--   4. l'insert dal client resta, ma vincolato al motore locale: un membro non
--      può più fabbricare una riga che si spaccia per analisi AI;
--   5. document_extractions torna in sola lettura per il client, che non l'ha
--      mai scritta (la scrive la pipeline con service role).
--
-- ORDINE DI MESSA IN OPERA — questa migrazione va applicata PRIMA di deployare
-- il codice che la accompagna, non dopo. Nell'intervallo il frontend vecchio,
-- che scrive ancora sull'analisi, riceve un errore esplicito sulla spunta della
-- checklist: un guasto visibile, non un salvataggio che sembra riuscito. Il
-- percorso inverso (codice nuovo su schema vecchio) darebbe lo stesso errore su
-- una tabella inesistente. Non esiste un ordine indolore: si sceglie quello che
-- fallisce in modo dichiarato, coerente con §60 (nessun fallback silenzioso).
--
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. action_progress — la checklist dell'utente, separata dallo snapshot
--
-- Perché una tabella nuova e non un'estensione di `tasks`: sono due oggetti
-- diversi. Un task dello scadenziario è creato deliberatamente dall'utente,
-- ha titolo, priorità e scadenza proprie e SOPRAVVIVE all'analisi (resta anche
-- se il documento viene rianalizzato). La spunta di una checklist è invece
-- legata a UNA specifica analisi, identificata dalla posizione dell'azione in
-- quello snapshot: usare `tasks` significherebbe o creare una voce di
-- scadenziario a ogni spunta — inquinando la lista delle scadenze vere — o
-- aggiungere a `tasks` colonne che valgono solo per le azioni. Le due cose
-- restano collegate dal pulsante "aggiungi allo scadenziario", che continua a
-- creare un task vero.
--
-- Chiave (analysis_id, action_index): `action_index` è la posizione dell'azione
-- nell'array `document_analyses.actions`, che coincide sempre con il campo `id`
-- dell'oggetto perché entrambi i motori rinumerano le azioni dopo l'ordinamento
-- finale (engine.ts e _shared/persist.ts). Poiché ogni rianalisi crea una NUOVA
-- riga in document_analyses, il progresso non può mai riferirsi a un'azione
-- diversa da quella spuntata.
-- ---------------------------------------------------------------------------
create table if not exists public.action_progress (
  id            uuid primary key default gen_random_uuid(),
  analysis_id   uuid not null references public.document_analyses (id) on delete cascade,
  company_id    uuid not null references public.companies (id) on delete cascade,
  action_index  integer not null check (action_index >= 0),
  -- Copia del testo dell'azione al momento della spunta. Non è usata per
  -- leggere il progresso: serve a poter DIMOSTRARE, rileggendo lo snapshot, che
  -- l'indice punta ancora all'azione che l'utente aveva davanti. Se un giorno
  -- l'ordinamento cambiasse, la divergenza sarebbe rilevabile invece che muta.
  action_text   text,
  done          boolean not null default false,
  -- NULL quando `done` è false, e anche per le righe importate da questa
  -- migrazione: di quelle spunte non conosciamo né autore né momento, e un
  -- valore di ripiego sarebbe un dato inventato (§60).
  done_by       uuid references auth.users (id) on delete set null,
  done_at       timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (analysis_id, action_index)
);
create index if not exists idx_action_progress_analysis on public.action_progress (analysis_id);
create index if not exists idx_action_progress_company  on public.action_progress (company_id);

comment on table public.action_progress is
  'Stato della checklist per singola azione di una analisi. Separata da document_analyses, che è uno snapshot immutabile.';
comment on column public.action_progress.action_index is
  'Posizione dell''azione in document_analyses.actions, uguale al campo id dell''oggetto azione.';
comment on column public.action_progress.done_at is
  'NULL = spunta importata dalla 0010 (momento reale ignoto) oppure azione non spuntata. Mai un valore di ripiego.';

-- ---------------------------------------------------------------------------
-- 2. Attribuzione decisa dal database, non dal client
--
-- `done_by` e `done_at` non vengono letti dalla richiesta: li imposta questo
-- trigger. Così un membro non può attribuire una spunta a un collega né datarla
-- a piacere, e il client non deve ricordarsi di farlo.
--
-- Quando `auth.uid()` è NULL (migrazione dei dati, service role) i valori
-- passati NON vengono sovrascritti: è il caso delle righe storiche, che restano
-- con done_at NULL invece di ricevere il timestamp della migrazione.
-- ---------------------------------------------------------------------------
create or replace function public.set_action_progress_actor()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();

  if not new.done then
    new.done_by := null;
    new.done_at := null;
    return new;
  end if;

  if auth.uid() is null then
    return new;                                    -- import/service role: nessuna attribuzione inventata
  end if;

  -- NB: su INSERT il record OLD non esiste, e in plpgsql non si può contare sulla
  -- valutazione pigra di un OR per evitarlo: i due casi restano separati.
  if tg_op = 'INSERT' then
    new.done_by := auth.uid();
    new.done_at := now();
  elsif not coalesce(old.done, false) then
    new.done_by := auth.uid();                     -- transizione a "fatto": chi la compie è chi la firma
    new.done_at := now();
  else
    new.done_by := coalesce(old.done_by, auth.uid());
    new.done_at := coalesce(old.done_at, now());   -- già spuntata: si conserva la prima firma
  end if;
  return new;
end $$;

drop trigger if exists trg_action_progress_actor on public.action_progress;
create trigger trg_action_progress_actor
  before insert or update on public.action_progress
  for each row execute function public.set_action_progress_actor();

-- ---------------------------------------------------------------------------
-- 3. RLS di action_progress
--
-- Oltre alla membership si verifica che l'analisi appartenga alla STESSA
-- azienda indicata nella riga: senza questo controllo un membro potrebbe
-- agganciare righe di progresso ad analisi di un'altra azienda passando il
-- proprio company_id. La sottoquery è a sua volta soggetta alla RLS di
-- document_analyses, quindi non rivela nulla di ciò che l'utente non può già
-- leggere: se l'analisi non è sua, l'exists è semplicemente falso.
--
-- Nessuna policy di DELETE: per togliere una spunta si aggiorna `done` a false.
-- Le righe spariscono solo in cascata con l'analisi.
-- ---------------------------------------------------------------------------
alter table public.action_progress enable row level security;

drop policy if exists action_progress_select_member on public.action_progress;
create policy action_progress_select_member on public.action_progress
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists action_progress_insert_member on public.action_progress;
create policy action_progress_insert_member on public.action_progress
  for insert to authenticated
  with check (
    public.is_company_member(company_id)
    and exists (
      select 1 from public.document_analyses a
      where a.id = action_progress.analysis_id
        and a.company_id = action_progress.company_id
    )
  );

drop policy if exists action_progress_update_member on public.action_progress;
create policy action_progress_update_member on public.action_progress
  for update to authenticated
  using (public.is_company_member(company_id))
  with check (
    public.is_company_member(company_id)
    and exists (
      select 1 from public.document_analyses a
      where a.id = action_progress.analysis_id
        and a.company_id = action_progress.company_id
    )
  );

grant select, insert, update on public.action_progress to authenticated;

-- ---------------------------------------------------------------------------
-- 4. Bozze di risposta: document_replies è l'unica sede
--
-- Le colonne restano in tabella per non perdere i dati storici già copiati
-- sotto, ma nessuno le scrive più e nessuno le legge più.
-- ---------------------------------------------------------------------------
comment on column public.document_analyses.reply_draft is
  'DEPRECATA (0010): la bozza corrente vive in document_replies. Conservata per i dati storici, non più scritta né letta.';
comment on column public.document_analyses.reply_language is
  'DEPRECATA (0010): vedi document_replies.language.';
comment on column public.document_analyses.reply_tone is
  'DEPRECATA (0010): vedi document_replies.tone.';

-- ---------------------------------------------------------------------------
-- 5. MIGRAZIONE DEI DATI — prima di togliere qualunque permesso
-- ---------------------------------------------------------------------------

-- 5a. Spunte della checklist → action_progress.
--     Si importano solo le azioni realmente spuntate: una riga per ogni `done`
--     a true. Le azioni non spuntate non hanno bisogno di riga (assenza = non
--     fatta). `action_index` viene dal campo `id` dell'oggetto quando è un
--     intero, altrimenti dalla posizione nell'array: i due valori coincidono
--     per costruzione, ma non si dà per scontato un dato storico.
insert into public.action_progress (analysis_id, company_id, action_index, action_text, done, done_by, done_at)
select
  a.id,
  a.company_id,
  case when elem->>'id' ~ '^[0-9]+$' then (elem->>'id')::int else (ord - 1)::int end,
  nullif(elem->>'text', ''),
  true,
  null,                                            -- autore ignoto: non si inventa
  null                                             -- momento ignoto: non si inventa
from public.document_analyses a
cross join lateral jsonb_array_elements(a.actions) with ordinality as t(elem, ord)
where jsonb_typeof(a.actions) = 'array'
  and coalesce(elem->>'done', 'false') = 'true'
on conflict (analysis_id, action_index) do nothing;

-- 5b. Bozze → document_replies, una sola per documento (la più recente), e solo
--     se quel documento non ha già una bozza propria: le bozze generate dall'AI
--     sono la fonte migliore e non vanno scavalcate da una copia legacy.
--     `created_by` NULL identifica le righe importate: nessun utente le ha
--     scritte, e la policy che impone created_by = auth.uid() vale solo per gli
--     insert fatti dal client.
insert into public.document_replies
  (document_id, company_id, analysis_id, created_by, language, tone, content, provider, model, prompt_version, is_edited)
select distinct on (a.document_id)
  a.document_id,
  a.company_id,
  a.id,
  null,
  coalesce(nullif(a.reply_language, ''), nullif(a.language, ''), 'it'),
  coalesce(nullif(a.reply_tone, ''), 'formale'),
  a.reply_draft,
  a.engine,                                        -- provenienza reale: il motore che l'ha prodotta
  null,
  null,
  false                                            -- non sappiamo se fu modificata a mano: non lo si afferma
from public.document_analyses a
where coalesce(a.reply_draft, '') <> ''
  and not exists (
    select 1 from public.document_replies r where r.document_id = a.document_id
  )
order by a.document_id, a.created_at desc;

-- ---------------------------------------------------------------------------
-- 6. SOLO ORA: lo snapshot diventa davvero immutabile
--
-- Restano select e insert. L'insert serve al motore locale, che analizza nel
-- browser (§60) — ma viene vincolato: engine deve essere quello deterministico
-- e i campi di provenienza AI devono restare vuoti. Un membro non può quindi
-- creare una riga che, riletta, sembrerebbe prodotta dal modello.
--
-- ⚠️ PREREQUISITO: la Edge Function `analyze-document` va RIDEPLOYATA insieme a
-- questa migrazione. Fino alla 0009 persisteva l'analisi usando il JWT
-- dell'utente (chiave anon), quindi come ruolo `authenticated`: con queste
-- restrizioni fallirebbe. La versione aggiornata usa un secondo client con
-- service role per le sole scritture, mantenendo il client utente per le letture
-- di autorizzazione, così il controllo cross-tenant (§49) resta dov'era.
--   npx supabase functions deploy analyze-document --project-ref <ref>
-- ---------------------------------------------------------------------------
drop policy if exists analyses_update_member on public.document_analyses;
drop policy if exists analyses_delete_member on public.document_analyses;
revoke update, delete on public.document_analyses from authenticated;

drop policy if exists analyses_insert_member on public.document_analyses;
create policy analyses_insert_member on public.document_analyses
  for insert to authenticated
  with check (
    public.is_company_member(company_id)
    and engine like 'deterministic-%'              -- niente righe che si spacciano per AI
    and provider is null
    and model is null
    and prompt_version is null
  );

comment on policy analyses_insert_member on public.document_analyses is
  'Il client può inserire solo analisi del motore locale, senza campi di provenienza AI. Le analisi AI le scrive la Edge Function con service role.';
comment on table public.document_analyses is
  'Snapshot immutabile dell''analisi. Dalla 0010 il client ha solo select e insert vincolato: niente update, niente delete. Lo stato dell''utente sta in action_progress e document_replies.';

-- ---------------------------------------------------------------------------
-- 7. document_extractions — sola lettura per il client
--
-- Il testo estratto lo scrive la pipeline (supabase/functions/_shared/persist.ts),
-- che dalla versione rideployata insieme a questa migrazione usa il service role;
-- il client fa solo select (documentService.getExtraction).
-- I permessi di insert/update/delete concessi dalla 0006 non sono mai serviti al
-- browser — li usava solo la Edge Function, che ora scrive con service role — e
-- permettevano di riscrivere il testo su cui le citazioni vengono verificate:
-- alterandolo si potrebbe far "verificare" una citazione che il documento non
-- contiene, che è il contrario della garanzia §20.
-- ---------------------------------------------------------------------------
drop policy if exists extractions_insert_member on public.document_extractions;
drop policy if exists extractions_update_member on public.document_extractions;
drop policy if exists extractions_delete_member on public.document_extractions;
revoke insert, update, delete on public.document_extractions from authenticated;

comment on table public.document_extractions is
  'Testo estratto, base della verifica delle citazioni (§20). Scritta solo dalla pipeline con service role; dalla 0010 il client ha la sola select.';

-- >>>>>>>>>>>>>>>>>>>>  0011_program_availability  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- SwissAI Suite — 0011 DISPONIBILITÀ DEI PROGRAMMI
--
-- Il problema che chiude. Un programma di incentivo può esistere, essere
-- documentato e corretto in ogni suo dettaglio, e ciononostante NON essere
-- ottenibile: la legge lo subordina a una condizione che oggi non ricorre.
--
-- È il caso dell'incentivo ticinese all'assunzione di disoccupati (L-rilocc,
-- RL 857.100): l'art. 3 lo attiva solo se il tasso di disoccupazione medio
-- dell'anno civile precedente raggiunge il tasso di riferimento fissato dal
-- Consiglio di Stato, con massimale del 4%. Il tasso ticinese è oggi intorno al
-- 2,4–3%, e il Cantone dichiara la misura sospesa.
--
-- Finora il catalogo aveva solo `active` (booleano) e `data_status`
-- (verified/recheck/demo). Nessuno dei due esprime «esiste ma non è
-- concedibile»: spegnere `active` lo fa sparire — l'utente non sa che esiste e
-- che potrebbe tornare — mentre lasciarlo attivo lo presenta come disponibile,
-- che è un dato falso. Un requisito "soft" non è la sede giusta: la condizione
-- non riguarda l'azienda e l'imprenditore non può valutarla.
--
-- Da qui una terza informazione, separata dalle altre due: la DISPONIBILITÀ,
-- con il motivo e la fonte che lo attesta, così l'app può dire «questo esiste,
-- ecco cos'è, oggi non è ottenibile e questo è il perché» invece di tacere o
-- di promettere.
--
-- ORDINE: applicare PRIMA di deployare il codice che la accompagna, poi
-- rieseguire il seed del catalogo (`npm run subsidy:seed -- --write`).
--
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

alter table public.subsidy_programs
  add column if not exists availability text not null default 'available';

-- Il vincolo è ricreato ogni volta per restare idempotente senza dipendere
-- dall'esistenza pregressa (non esiste `add constraint if not exists`).
alter table public.subsidy_programs
  drop constraint if exists subsidy_programs_availability_check;
alter table public.subsidy_programs
  add constraint subsidy_programs_availability_check
  check (availability in ('available', 'suspended'));

-- Perché non è concedibile, in linguaggio comprensibile. In italiano come il
-- resto dei contenuti del catalogo (i testi dei programmi non sono tradotti:
-- lo sono le etichette dell'interfaccia).
alter table public.subsidy_programs
  add column if not exists availability_note text;

-- La fonte che attesta la sospensione. Senza questa, «sospeso» sarebbe
-- un'affermazione dell'app anziché un fatto verificabile: la stessa regola che
-- vale per le analisi documentali vale per il catalogo.
alter table public.subsidy_programs
  add column if not exists availability_source_url text;

-- Quando lo stato è stato verificato l'ultima volta. Distinto da
-- `last_checked_at`, che riguarda il CONTENUTO del programma: il contenuto può
-- restare valido per anni mentre la disponibilità cambia ogni anno, perché
-- dipende da una statistica annuale.
alter table public.subsidy_programs
  add column if not exists availability_checked_at date;

comment on column public.subsidy_programs.availability is
  'available = concedibile; suspended = esiste ed è documentato ma oggi non è ottenibile (condizione di legge non soddisfatta). Diverso da `active`, che nasconde del tutto il programma.';
comment on column public.subsidy_programs.availability_note is
  'Motivo della sospensione, in linguaggio comprensibile. Obbligatorio nei fatti quando availability = suspended: senza motivo, «sospeso» non è verificabile.';
comment on column public.subsidy_programs.availability_source_url is
  'Fonte che attesta lo stato di disponibilità (può differire da official_source_url).';
comment on column public.subsidy_programs.availability_checked_at is
  'Data dell''ultima verifica dello STATO. Distinta da last_checked_at, che riguarda il contenuto del programma.';

-- >>>>>>>>>>>>>>>>>>>>  0012_program_translations  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- SwissAI Suite — 0012 TRADUZIONI DEL CATALOGO INCENTIVI
--
-- L'interfaccia è trilingue dal 2026-07, ma i CONTENUTI dei programmi no: nomi,
-- requisiti, descrizione del contributo e finestra di domanda vivono in questa
-- tabella e venivano mostrati in italiano anche in tedesco e francese. Per una
-- PMI germanofona o romanda è il testo che conta davvero — i requisiti da
-- soddisfare — a restare in una lingua che non è la sua.
--
-- Perché QUI e non nei dizionari `src/i18n/`: il catalogo è un DATO, aggiornabile
-- senza un deploy. Spostare i suoi testi nel codice avrebbe legato ogni
-- correzione di un requisito a una nuova pubblicazione dell'applicazione.
--
-- Struttura: una sola colonna JSONB, niente tabella separata né una colonna per
-- lingua. Le join non servono (si legge sempre l'intero programma) e aggiungere
-- una lingua non richiede una migrazione.
--
--   {
--     "de": {
--       "name": "...", "authority": "...", "contribution_description": "...",
--       "application_window": "...", "must_apply_before_start_text": "...",
--       "source_title": "...", "availability_note": "...",
--       "documents_required": ["...", "..."],
--       "requirements": { "<id>": { "text": "...", "question": "..." } },
--       "exclusions":   { "<id>": { "text": "...", "question": "..." } }
--     },
--     "fr": { ... }
--   }
--
-- Requisiti ed esclusioni sono indicizzati per ID, non per posizione: se un
-- domani se ne aggiunge uno o cambia l'ordine, le traduzioni restano agganciate
-- a ciò che traducono invece di scivolare sulla voce sbagliata.
--
-- Cosa NON viene tradotto, di proposito: le sigle e le denominazioni ufficiali
-- (LInn, FER, L-Rilocc, ProKilowatt, Innosuisse, Pronovo) e gli URL delle fonti.
-- Dove una denominazione ufficiale esiste già nelle tre lingue si usa quella —
-- "Il Programma Edifici" è "Das Gebäudeprogramm", non una traduzione letterale.
--
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

alter table public.subsidy_programs
  add column if not exists translations jsonb not null default '{}'::jsonb;

comment on column public.subsidy_programs.translations is
  'Traduzioni dei contenuti per lingua ("de", "fr"); l''italiano resta nelle colonne base. Requisiti ed esclusioni sono indicizzati per id, non per posizione. Una lingua assente o un campo mancante ricadono sull''italiano, e l''app lo DICHIARA invece di far passare il testo per tradotto.';

-- >>>>>>>>>>>>>>>>>>>>  0013_inbox  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0013 INBOX
--
-- Acquisizione della posta aziendale (Google Workspace / Microsoft 365) come
-- punto d'ingresso del back-office. NON è un secondo motore di analisi: una
-- email amministrativamente rilevante diventa un `documents` normale e passa
-- dalla pipeline Admin AI già esistente. Qui si modella solo ciò che la posta
-- ha in più: la connessione al provider, il messaggio, i suoi allegati e la
-- RELAZIONE fra messaggio e documento.
--
-- Le tre separazioni che reggono lo schema
--   1. CONNESSIONE ≠ SEGRETI. `email_connections` contiene metadati che un
--      membro può vedere; i token OAuth stanno in `email_connection_secrets`,
--      che NON ha alcuna policy e a cui il ruolo `authenticated` non ha alcun
--      permesso. Un client con la chiave anon non può leggerli in nessun modo,
--      nemmeno per errore di programmazione lato applicazione.
--   2. STATO DELLA MACCHINA ≠ STATO DELL'UTENTE. `processing_status` racconta
--      dove è arrivata la pipeline; `attention_status` racconta cosa deve fare
--      una persona. Confonderli significa che un guasto tecnico si traveste da
--      «niente da fare» — esattamente il falso negativo che qui è più pericoloso
--      del falso positivo.
--   3. STATO LOCALE ≠ STATO DEL PROVIDER. Niente in questo schema descrive
--      Gmail o Outlook: `handled_at` significa «tolto dalla vista operativa di
--      AI-Swisse», non «archiviato su Gmail». La versione 1 è in sola lettura
--      verso il provider e lo schema non offre nemmeno il posto dove annotare
--      il contrario.
--
-- Cancellazioni (§79). `email_messages.connection_id` cascata sulla connessione,
-- ma **disconnettere non cancella**: `email-disconnect` porta la connessione a
-- `disconnected` e distrugge i segreti, senza toccare una riga di posta. La
-- cascata esiste solo per la cancellazione dell'azienda, dove tutto deve sparire.
-- Un eventuale «elimina dati importati» sarà un'azione separata e dichiarata.
--
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

-- Ricerca testuale server-side (§10): trigram, così `ilike '%…%'` usa un indice
-- invece di scaricare la Inbox nel browser per filtrarla lì.
create extension if not exists pg_trgm;

-- ---------------------------------------------------------------------------
-- 1. Enum
--
-- Enum e non testo libero dove il valore governa una decisione (routing della
-- pipeline, visibilità in Inbox, autorizzazioni): un refuso in una stringa
-- libera diventerebbe una categoria nuova e silenziosa. Restano testo i campi
-- puramente descrittivi (error_code, importance), dove il valore arriva dal
-- provider e inventarne un enum significherebbe rifiutare valori legittimi.
-- ---------------------------------------------------------------------------
do $$ begin create type public.email_provider as enum ('google', 'microsoft');
exception when duplicate_object then null; end $$;

do $$ begin create type public.email_connection_status as enum
  ('active', 'reauth_required', 'error', 'disconnected');
exception when duplicate_object then null; end $$;

do $$ begin create type public.email_sync_type as enum
  ('initial', 'incremental', 'manual', 'reconciliation');
exception when duplicate_object then null; end $$;

do $$ begin create type public.email_sync_status as enum
  ('running', 'ok', 'partial', 'failed');
exception when duplicate_object then null; end $$;

-- Stato della PIPELINE su un messaggio. Descrive il lavoro della macchina.
do $$ begin create type public.email_processing_status as enum
  ('pending', 'classifying', 'importing', 'analyzing', 'done', 'failed');
exception when duplicate_object then null; end $$;

-- Stato di ATTENZIONE per una persona. Descrive cosa c'è da fare.
-- `ignored` = il classificatore l'ha giudicata non amministrativa: la riga
-- resta e resta recuperabile, non viene nascosta per sempre.
do $$ begin create type public.email_attention_status as enum
  ('needs_attention', 'to_verify', 'informational', 'ignored', 'handled');
exception when duplicate_object then null; end $$;

-- Esito del classificatore. Deliberatamente CONSERVATIVO: `clearly_irrelevant`
-- richiede segnali forti e concordi, perché una comunicazione amministrativa
-- persa costa molto più di una newsletter mostrata di troppo.
do $$ begin create type public.email_relevance as enum
  ('likely_actionable', 'possibly_actionable', 'informational', 'clearly_irrelevant');
exception when duplicate_object then null; end $$;

do $$ begin create type public.email_document_relation as enum ('body', 'attachment');
exception when duplicate_object then null; end $$;

-- Perché un allegato non è stato importato: la ragione è un dato, non un log.
-- L'utente deve poter capire che quel PDF non è stato letto e perché.
do $$ begin create type public.email_attachment_import_status as enum
  ('pending', 'imported', 'skipped_inline', 'skipped_unsupported', 'skipped_too_large', 'failed');
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 2. email_connections — la casella collegata
--
-- `provider_account_id` è l'identità STABILE del provider (Google `sub`,
-- Microsoft `id` della mailbox), non l'indirizzo: un indirizzo può essere un
-- alias o cambiare, e usarlo come identità farebbe apparire lo stesso account
-- come due connessioni diverse dopo una rinomina (§127). L'indirizzo resta,
-- perché è ciò che l'utente riconosce.
--
-- Il vincolo è per AZIENDA, non globale: una fiduciaria può legittimamente
-- collegare la stessa casella a due mandati, e vietarlo qui significherebbe
-- decidere un modello commerciale dentro uno schema (§74).
-- ---------------------------------------------------------------------------
create table if not exists public.email_connections (
  id                        uuid primary key default gen_random_uuid(),
  company_id                uuid not null references public.companies (id) on delete cascade,
  connected_by              uuid references auth.users (id) on delete set null,
  provider                  public.email_provider not null,
  provider_account_id       text not null,
  email_address             text not null,
  display_name              text,
  status                    public.email_connection_status not null default 'active',
  -- Scope realmente concessi dal provider, così la schermata «Account email»
  -- può dire cosa AI-Swisse può fare invece di quello che ha chiesto.
  scopes                    text[] not null default '{}',
  sync_enabled              boolean not null default true,

  -- Cursore di sincronizzazione incrementale: `historyId` per Gmail, `deltaLink`
  -- per Microsoft Graph. Opaco per l'applicazione, che non lo interpreta mai.
  sync_cursor               text,
  -- Confine inferiore dell'import iniziale (§44): oltre questa data non si
  -- risale. Serve alla riconciliazione per sapere cosa NON è un buco.
  history_floor_at          timestamptz,

  initial_sync_completed_at timestamptz,
  last_sync_at              timestamptz,
  last_successful_sync_at   timestamptz,
  last_error_code           text,
  last_error_at             timestamptz,

  -- Push: `watch_resource_id` è la subscription Graph o il topic watch Gmail.
  watch_resource_id         text,
  watch_expires_at          timestamptz,
  watch_last_renewed_at     timestamptz,
  watch_last_error_code     text,

  -- §125 — lock di sincronizzazione a SCADENZA, non booleano. Un `is_syncing`
  -- senza scadenza resta true per sempre se il processo muore, e la casella non
  -- si sincronizza più senza che nessuno sappia perché.
  sync_lease_id             uuid,
  sync_lease_until          timestamptz,

  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now(),

  unique (company_id, provider, provider_account_id)
);
create index if not exists idx_email_conn_company on public.email_connections (company_id);
-- Selezione delle connessioni da rinnovare/riconciliare, per il job periodico.
create index if not exists idx_email_conn_due on public.email_connections (status, sync_enabled, watch_expires_at)
  where status = 'active' and sync_enabled;

comment on table public.email_connections is
  'Casella di posta collegata a un''azienda. I token NON stanno qui: vedi email_connection_secrets.';
comment on column public.email_connections.sync_lease_until is
  'Scadenza del lock di sincronizzazione. A scadenza, non booleano: un processo morto non deve bloccare la casella per sempre.';
comment on column public.email_connections.history_floor_at is
  'Data più antica importata. La riconciliazione non cerca buchi prima di questo istante: là non c''è un buco, c''è un confine dichiarato.';

-- ---------------------------------------------------------------------------
-- 3. email_connection_secrets — token OAuth, SOLO server
--
-- MODELLO DI MINACCIA (§18), esplicito perché la sicurezza di questa tabella è
-- l'unica cosa che separa un bug applicativo dalla lettura della posta altrui.
--
--   · Client con chiave anon e sessione valida — bloccato due volte: nessun
--     GRANT al ruolo `authenticated` e RLS attiva senza policy. Anche un
--     `select('*')` scritto per errore in un service non restituisce nulla:
--     PostgREST risponde 42501, non una riga vuota.
--   · Chiave anon rubata — identico al caso sopra: la chiave anon non conferisce
--     alcun accesso a questa tabella.
--   · Dump del database — i token sono cifrati con AES-256-GCM e la chiave NON
--     è nel database: vive come secret della Edge Function (EMAIL_TOKEN_KEY).
--     Un dump da solo non basta per leggere la posta.
--   · Service role compromessa — NON è mitigato da questo schema: chi ha la
--     service role E la chiave di cifratura ha i token. È il limite dichiarato,
--     e vale già oggi per l'intero database.
--
-- Sono `bytea` e non `text` perché sono byte, non testo: nessuna codifica
-- intermedia da sbagliare, e nessuna tentazione di leggerli «tanto per vedere».
-- ---------------------------------------------------------------------------
create table if not exists public.email_connection_secrets (
  connection_id             uuid primary key references public.email_connections (id) on delete cascade,
  company_id                uuid not null references public.companies (id) on delete cascade,

  access_token_ct           bytea,
  access_token_iv           bytea,
  access_token_expires_at   timestamptz,
  refresh_token_ct          bytea,
  refresh_token_iv          bytea,
  -- Microsoft: `clientState` con cui si autentica la notifica in arrivo. È un
  -- segreto condiviso, quindi sta qui e non nella tabella dei metadati.
  webhook_state_ct          bytea,
  webhook_state_iv          bytea,

  -- Versione della chiave di cifratura: permette una rotazione futura senza
  -- dover indovinare con quale chiave è stato cifrato ogni record.
  key_version               integer not null default 1,

  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now()
);

comment on table public.email_connection_secrets is
  'Token OAuth cifrati (AES-256-GCM). Nessuna policy e nessun GRANT: irraggiungibile dal ruolo authenticated. La chiave di cifratura è un secret della Edge Function, non sta nel database.';

-- ---------------------------------------------------------------------------
-- 4. email_oauth_states — stato anti-CSRF del flusso OAuth (§72)
--
-- Lo `state` non viaggia firmato ma OPACO: il client riceve un valore casuale e
-- il server ritrova qui il contesto. Così il callback non si fida mai di un
-- `company_id` arrivato dalla query string — che sarebbe la via più diretta per
-- collegare la casella di qualcun altro alla propria azienda.
--
-- In tabella sta lo SHA-256 del valore, non il valore: chi leggesse questa
-- tabella non otterrebbe uno state utilizzabile. Il `code_verifier` PKCE è
-- cifrato come i token, perché è a tutti gli effetti un segreto di sessione.
-- ---------------------------------------------------------------------------
create table if not exists public.email_oauth_states (
  id                uuid primary key default gen_random_uuid(),
  state_hash        text not null unique,
  company_id        uuid not null references public.companies (id) on delete cascade,
  user_id           uuid not null references auth.users (id) on delete cascade,
  provider          public.email_provider not null,
  code_verifier_ct  bytea,
  code_verifier_iv  bytea,
  key_version       integer not null default 1,
  redirect_path     text,
  created_at        timestamptz not null default now(),
  expires_at        timestamptz not null,
  consumed_at       timestamptz
);
create index if not exists idx_email_oauth_states_expiry on public.email_oauth_states (expires_at);

comment on table public.email_oauth_states is
  'Stato OAuth monouso e a scadenza breve. Contiene lo SHA-256 dello state, non lo state: leggere questa tabella non permette di fabbricarne uno valido.';

-- ---------------------------------------------------------------------------
-- 5. email_messages — il messaggio normalizzato
--
-- Non si conserva l'HTML del provider. Il corpo viene ridotto server-side a
-- TESTO con un tokenizzatore che scarta script, stile, gestori di evento e
-- risorse remote; i collegamenti vengono estratti a parte, con la loro
-- destinazione reale. Conseguenze volute:
--   · non esiste HTML non fidato da sanificare al momento del render, quindi
--     non esiste il bug in cui la sanificazione viene dimenticata (§54);
--   · nessun pixel di tracciamento può partire, perché non c'è nulla da
--     caricare: la privacy non dipende da un'opzione lasciata spenta (§55);
--   · il testo su cui l'AI ragiona è lo stesso che l'utente legge, quindi una
--     citazione resta verificabile.
-- Il prezzo è che la posta non si vede impaginata. In una Inbox che serve a
-- decidere cosa richiede attenzione, è un prezzo che vale la pena pagare.
-- ---------------------------------------------------------------------------
create table if not exists public.email_messages (
  id                     uuid primary key default gen_random_uuid(),
  company_id             uuid not null references public.companies (id) on delete cascade,
  connection_id          uuid not null references public.email_connections (id) on delete cascade,

  provider_message_id    text not null,
  provider_thread_id     text,
  internet_message_id    text,

  subject                text,
  sender_name            text,
  sender_email           text,
  -- To/CC come jsonb: [{ "name": "...", "email": "..." }]. Normalizzarli in
  -- tabelle separate darebbe la possibilità di interrogarli, che qui non serve
  -- a nessuna schermata; il costo sarebbero due join per ogni riga di lista.
  to_recipients          jsonb not null default '[]'::jsonb,
  cc_recipients          jsonb not null default '[]'::jsonb,

  received_at            timestamptz not null,
  sent_at                timestamptz,

  body_text              text,
  body_preview           text,
  -- Collegamenti estratti dal corpo: [{ "url": "...", "label": "...", "host": "..." }].
  -- Solo http/https, validati server-side: l'interfaccia mostra il dominio vero,
  -- non il testo che il mittente ha scelto di far vedere (§56).
  body_links             jsonb not null default '[]'::jsonb,
  body_char_count        integer,
  -- Il corpo depurato di firme e storico citato, usato per la classificazione.
  -- Deriva da `body_text`, che resta intatto: quando il taglio è dubbio non si
  -- taglia, e in nessun caso si perde l'originale normalizzato (§115/§116).
  body_clean             text,
  quoted_removed         boolean not null default false,

  has_attachments        boolean not null default false,
  attachment_count       integer not null default 0,
  importance             text,
  -- Segnale di posta di massa (List-Unsubscribe, Precedence: bulk). È un FATTO
  -- letto dagli header, non un giudizio: il giudizio è `relevance`.
  is_bulk                boolean not null default false,

  processing_status      public.email_processing_status not null default 'pending',
  attention_status       public.email_attention_status not null default 'to_verify',
  relevance              public.email_relevance,
  relevance_confidence   numeric(4,3),
  relevance_reason       text,
  -- §118 — riproducibilità della decisione: con quale regola e quale modello è
  -- stata presa. Senza questi campi, «perché questa email è finita fra le
  -- irrilevanti?» non ha risposta.
  classifier_version     text,
  classifier_provider    text,
  classifier_model       text,
  classifier_prompt_version text,
  classified_at          timestamptz,

  error_code             text,
  error_message_safe     text,

  seen_at                timestamptz,
  handled_at             timestamptz,
  handled_by             uuid references auth.users (id) on delete set null,

  -- §117 — impronta della fonte al momento dell'acquisizione. Una
  -- risincronizzazione che trovasse un contenuto diverso NON riscrive in
  -- silenzio ciò che è già stato analizzato: la divergenza è rilevabile.
  source_fingerprint     text,

  -- COPIA della scadenza trovata dall'analisi collegata, al solo scopo di
  -- filtrare e ordinare la lista senza join (§9/§104). La fonte di verità
  -- resta `document_analyses`: qui non c'è la citazione, non c'è la fiducia,
  -- non c'è il tipo di scadenza, e la schermata di dettaglio legge sempre
  -- dall'analisi. La scrive solo la pipeline, dopo un'analisi riuscita.
  analysis_deadline      date,

  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),

  -- §26 — l'idempotenza non è una condizione nel codice applicativo ma un
  -- vincolo del database: un webhook consegnato due volte non può creare due
  -- righe, qualunque cosa faccia il codice.
  unique (connection_id, provider_message_id)
);

-- Ricerca (§10). Colonna generata + indice trigram: la ricerca resta sul
-- server anche con decine di migliaia di messaggi.
alter table public.email_messages
  add column if not exists search_text text
  generated always as (
    lower(coalesce(subject, '') || ' ' || coalesce(sender_name, '') || ' '
          || coalesce(sender_email, '') || ' ' || coalesce(body_preview, ''))
  ) stored;

-- Ordinamento stabile della lista e paginazione keyset (§76).
create index if not exists idx_email_msg_company_recv
  on public.email_messages (company_id, received_at desc, id desc);
create index if not exists idx_email_msg_company_attention
  on public.email_messages (company_id, attention_status, received_at desc, id desc);
create index if not exists idx_email_msg_connection on public.email_messages (connection_id);
create index if not exists idx_email_msg_thread on public.email_messages (company_id, provider_thread_id)
  where provider_thread_id is not null;
create index if not exists idx_email_msg_search on public.email_messages using gin (search_text gin_trgm_ops);
-- Ripresa del lavoro rimasto indietro: poche righe, quindi indice parziale.
create index if not exists idx_email_msg_pending on public.email_messages (company_id, processing_status, received_at)
  where processing_status in ('pending', 'failed');
create index if not exists idx_email_msg_internet_id on public.email_messages (company_id, internet_message_id)
  where internet_message_id is not null;
-- Filtro «con una scadenza vicina»: poche righe, indice parziale.
create index if not exists idx_email_msg_deadline on public.email_messages (company_id, analysis_deadline)
  where analysis_deadline is not null;

comment on column public.email_messages.body_text is
  'Testo normalizzato del messaggio. L''HTML del provider non viene conservato: viene ridotto a testo server-side, quindi non esiste HTML non fidato da rendere.';
comment on column public.email_messages.attention_status is
  'Stato per una persona. Indipendente da processing_status: un guasto tecnico non deve mai apparire come "niente da fare".';

-- ---------------------------------------------------------------------------
-- 6. email_attachments
--
-- `declared_mime_type` è quello che DICE il provider, `mime_type` quello che il
-- server ha accettato dopo la validazione. Tenerli separati permette di non
-- fidarsi del primo (§15) senza perderlo: se un giorno la politica cambia, si
-- sa cosa era stato dichiarato.
-- ---------------------------------------------------------------------------
create table if not exists public.email_attachments (
  id                      uuid primary key default gen_random_uuid(),
  company_id              uuid not null references public.companies (id) on delete cascade,
  email_message_id        uuid not null references public.email_messages (id) on delete cascade,
  provider_attachment_id  text not null,

  filename                text,
  safe_filename           text,
  declared_mime_type      text,
  mime_type               text,
  size_bytes              bigint,
  content_id              text,
  is_inline               boolean not null default false,

  storage_path            text,
  file_hash               text,
  import_status           public.email_attachment_import_status not null default 'pending',
  skip_reason             text,
  error_code              text,

  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),

  unique (email_message_id, provider_attachment_id)
);
create index if not exists idx_email_att_message on public.email_attachments (email_message_id);
create index if not exists idx_email_att_company on public.email_attachments (company_id);
create index if not exists idx_email_att_hash on public.email_attachments (company_id, file_hash)
  where file_hash is not null;

-- ---------------------------------------------------------------------------
-- 7. email_message_documents — la relazione email ↔ documento (§16/§59/§60)
--
-- Tabella di relazione e non colonne email dentro `documents`: la stessa email
-- può generare più documenti (corpo + allegati) e lo STESSO documento può
-- essere raggiunto da più email — è precisamente ciò che succede quando la
-- deduplicazione per hash riconosce un PDF già caricato a mano. Deduplicare il
-- documento non deve far perdere la traccia che quel PDF era allegato anche a
-- QUEL messaggio.
--
-- Due indici unici parziali invece di un unique con colonna nullable: in SQL
-- due NULL non sono uguali, quindi `unique (message, relation, attachment_id)`
-- non impedirebbe affatto due righe `body`.
-- ---------------------------------------------------------------------------
create table if not exists public.email_message_documents (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies (id) on delete cascade,
  email_message_id  uuid not null references public.email_messages (id) on delete cascade,
  document_id       uuid not null references public.documents (id) on delete cascade,
  relation          public.email_document_relation not null,
  attachment_id     uuid references public.email_attachments (id) on delete cascade,
  created_at        timestamptz not null default now(),

  -- Un allegato genera un documento, non due; un corpo non ha allegato.
  constraint email_msg_doc_shape check (
    (relation = 'body' and attachment_id is null)
    or (relation = 'attachment' and attachment_id is not null)
  )
);
create unique index if not exists uq_email_msg_doc_body
  on public.email_message_documents (email_message_id) where relation = 'body';
create unique index if not exists uq_email_msg_doc_attachment
  on public.email_message_documents (email_message_id, attachment_id) where relation = 'attachment';
create index if not exists idx_email_msg_doc_document on public.email_message_documents (document_id);
create index if not exists idx_email_msg_doc_company on public.email_message_documents (company_id);

-- ---------------------------------------------------------------------------
-- 8. email_sync_runs — perché questa casella non si aggiorna (§47/§48)
--
-- Audit tecnico, non contenuto: identificatori, conteggi, esito. Mai un oggetto,
-- mai un mittente, mai un token. Serve a rispondere a una domanda di esercizio,
-- e per rispondere non serve sapere cosa c'era scritto nelle email.
-- ---------------------------------------------------------------------------
create table if not exists public.email_sync_runs (
  id                     uuid primary key default gen_random_uuid(),
  company_id             uuid not null references public.companies (id) on delete cascade,
  connection_id          uuid not null references public.email_connections (id) on delete cascade,
  sync_type              public.email_sync_type not null,
  status                 public.email_sync_status not null default 'running',
  triggered_by           text,                       -- user | webhook | schedule | oauth_callback
  started_at             timestamptz not null default now(),
  completed_at           timestamptz,
  duration_ms            integer,
  messages_seen          integer not null default 0,
  messages_new           integer not null default 0,
  messages_updated       integer not null default 0,
  attachments_imported   integer not null default 0,
  documents_created      integer not null default 0,
  analyses_started       integer not null default 0,
  cursor_before          text,
  cursor_after           text,
  error_code             text,
  error_detail_safe      text,
  created_at             timestamptz not null default now()
);
create index if not exists idx_email_sync_runs_conn on public.email_sync_runs (connection_id, started_at desc);
create index if not exists idx_email_sync_runs_company on public.email_sync_runs (company_id, started_at desc);

-- ---------------------------------------------------------------------------
-- 9. email_webhook_events — idempotenza delle notifiche (§26/§49)
--
-- Si conserva un'IMPRONTA dell'evento, non il suo payload: per riconoscere un
-- duplicato basta sapere che quell'evento è già passato. Il vincolo unico fa il
-- lavoro; il codice applicativo non deve ricordarsi di controllare.
-- ---------------------------------------------------------------------------
create table if not exists public.email_webhook_events (
  id                 uuid primary key default gen_random_uuid(),
  provider           public.email_provider not null,
  connection_id      uuid references public.email_connections (id) on delete cascade,
  event_fingerprint  text not null unique,
  received_at        timestamptz not null default now(),
  processed_at       timestamptz,
  status             text not null default 'received',   -- received | processed | ignored | failed
  error_code         text
);
create index if not exists idx_email_webhook_received on public.email_webhook_events (received_at desc);

-- ---------------------------------------------------------------------------
-- 10. email_audit_log — chi ha collegato questa casella (§81)
--
-- Non è un SIEM. Sono le poche azioni per cui «chi è stato» è una domanda
-- legittima: collegare, riconnettere, disconnettere, forzare una sincronizzazione.
-- ---------------------------------------------------------------------------
create table if not exists public.email_audit_log (
  id             uuid primary key default gen_random_uuid(),
  company_id     uuid not null references public.companies (id) on delete cascade,
  connection_id  uuid references public.email_connections (id) on delete set null,
  actor_user_id  uuid references auth.users (id) on delete set null,
  action         text not null,          -- connected | reconnected | disconnected | sync_requested
  detail         jsonb not null default '{}'::jsonb,
  created_at     timestamptz not null default now()
);
create index if not exists idx_email_audit_company on public.email_audit_log (company_id, created_at desc);

-- ---------------------------------------------------------------------------
-- 11. Trigger updated_at
-- ---------------------------------------------------------------------------
drop trigger if exists trg_email_conn_updated on public.email_connections;
create trigger trg_email_conn_updated before update on public.email_connections
  for each row execute function public.set_updated_at();

drop trigger if exists trg_email_secrets_updated on public.email_connection_secrets;
create trigger trg_email_secrets_updated before update on public.email_connection_secrets
  for each row execute function public.set_updated_at();

drop trigger if exists trg_email_msg_updated on public.email_messages;
create trigger trg_email_msg_updated before update on public.email_messages
  for each row execute function public.set_updated_at();

drop trigger if exists trg_email_att_updated on public.email_attachments;
create trigger trg_email_att_updated before update on public.email_attachments
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 12. Il client può cambiare solo lo stato UMANO del messaggio
--
-- I permessi di colonna (punto 14) impediscono già di scrivere altrove. Questo
-- trigger aggiunge le due cose che un GRANT non sa esprimere:
--   · verso quali valori `attention_status` può muoversi da un'azione manuale —
--     un membro può dire «gestita» o rimetterla in lista, non può promuovere a
--     `needs_attention` una email che il classificatore ha giudicato altrimenti,
--     perché quella è una conclusione, non una preferenza;
--   · chi e quando, scritti dal database e non dalla richiesta, come già fa
--     `action_progress` (0010).
-- ---------------------------------------------------------------------------
-- Dove va un messaggio quando NON è stato messo via: lo decide la
-- classificazione, non la richiesta. Un'unica funzione, usata sia dalla
-- pipeline sia dal ripristino, così le due strade non possono divergere.
create or replace function public.email_attention_for_relevance(p_rel public.email_relevance)
returns public.email_attention_status
language sql
immutable
as $$
  select case p_rel
    when 'likely_actionable'   then 'needs_attention'
    when 'possibly_actionable' then 'to_verify'
    when 'informational'       then 'informational'
    when 'clearly_irrelevant'  then 'ignored'
    else 'to_verify'                       -- non ancora classificata: si mostra
  end::public.email_attention_status;
$$;

create or replace function public.set_email_message_handled_actor()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();

  if new.attention_status is distinct from old.attention_status then
    if new.attention_status = 'handled' then
      -- «Metti via»: chi e quando li scrive il database, non la richiesta.
      if auth.uid() is not null then
        new.handled_by := auth.uid();
        new.handled_at := now();
      end if;
    elsif old.attention_status = 'handled' then
      -- «Rimetti in lista»: il messaggio torna dove lo aveva messo la
      -- classificazione. Il valore inviato dal client viene IGNORATO — un
      -- ripristino è un annullamento, non l'occasione per riscrivere una
      -- conclusione dell'analisi.
      new.attention_status := public.email_attention_for_relevance(new.relevance);
      new.handled_by := null;
      new.handled_at := null;
    elsif auth.uid() is not null then
      -- Ogni altro cambio è una conclusione della pipeline, non una preferenza:
      -- dal client si può solo mettere via o rimettere in lista.
      raise exception 'attention_status: dal client sono ammessi solo "handled" e il ripristino'
        using errcode = '22023';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_email_msg_handled on public.email_messages;
create trigger trg_email_msg_handled before update on public.email_messages
  for each row execute function public.set_email_message_handled_actor();

-- ---------------------------------------------------------------------------
-- 13. RLS
--
-- Regola invariata dal 0001: si accede solo ai dati della propria azienda. Le
-- tabelle di servizio (segreti, stati OAuth, eventi webhook) non hanno policy
-- perché non devono avere accesso, e una policy assente è più difficile da
-- allentare per sbaglio di una policy restrittiva.
-- ---------------------------------------------------------------------------
alter table public.email_connections        enable row level security;
alter table public.email_connection_secrets enable row level security;
alter table public.email_oauth_states       enable row level security;
alter table public.email_messages           enable row level security;
alter table public.email_attachments        enable row level security;
alter table public.email_message_documents  enable row level security;
alter table public.email_sync_runs          enable row level security;
alter table public.email_webhook_events     enable row level security;
alter table public.email_audit_log          enable row level security;

-- Connessioni: i membri leggono. Creare e disconnettere passa dalle Edge
-- Function, che verificano il ruolo: al client non serve nessun permesso di
-- scrittura, e non averlo è più solido che averlo e controllarlo altrove.
drop policy if exists email_conn_select_member on public.email_connections;
create policy email_conn_select_member on public.email_connections
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists email_msg_select_member on public.email_messages;
create policy email_msg_select_member on public.email_messages
  for select to authenticated using (public.is_company_member(company_id));
drop policy if exists email_msg_update_member on public.email_messages;
create policy email_msg_update_member on public.email_messages
  for update to authenticated
  using (public.is_company_member(company_id))
  with check (public.is_company_member(company_id));

drop policy if exists email_att_select_member on public.email_attachments;
create policy email_att_select_member on public.email_attachments
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists email_msg_doc_select_member on public.email_message_documents;
create policy email_msg_doc_select_member on public.email_message_documents
  for select to authenticated using (public.is_company_member(company_id));

-- Diagnostica: la legge chi può agire sulla connessione, non ogni membro.
drop policy if exists email_sync_runs_select_admin on public.email_sync_runs;
create policy email_sync_runs_select_admin on public.email_sync_runs
  for select to authenticated using (public.is_company_admin(company_id));

drop policy if exists email_audit_select_admin on public.email_audit_log;
create policy email_audit_select_admin on public.email_audit_log
  for select to authenticated using (public.is_company_admin(company_id));

-- ---------------------------------------------------------------------------
-- 14. GRANT — permessi di COLONNA, non di tabella
--
-- La RLS decide QUALI righe; il grant decide QUALI COLONNE. Sulla connessione
-- il client non ha bisogno di vedere il cursore di sincronizzazione né
-- l'identificativo della subscription: non sono segreti, ma non servono a
-- nessuna schermata, e ciò che non viene concesso non può essere esposto da una
-- `select('*')` scritta distrattamente.
--
-- Sul messaggio, l'unico UPDATE concesso riguarda due colonne: il resto della
-- riga è il verbale di ciò che è arrivato, e non si riscrive.
-- ---------------------------------------------------------------------------
grant select (
  id, company_id, connected_by, provider, provider_account_id, email_address, display_name,
  status, scopes, sync_enabled, initial_sync_completed_at, last_sync_at, last_successful_sync_at,
  last_error_code, last_error_at, watch_expires_at, sync_lease_until, created_at, updated_at
) on public.email_connections to authenticated;

grant select on public.email_messages to authenticated;
grant update (seen_at, attention_status) on public.email_messages to authenticated;
grant select on public.email_attachments to authenticated;
grant select on public.email_message_documents to authenticated;
grant select on public.email_sync_runs to authenticated;
grant select on public.email_audit_log to authenticated;

-- Esplicito, anche se è già il default: queste tabelle non sono raggiungibili.
revoke all on public.email_connection_secrets from authenticated, anon;
revoke all on public.email_oauth_states       from authenticated, anon;
revoke all on public.email_webhook_events     from authenticated, anon;

-- ---------------------------------------------------------------------------
-- 15. Quota AI per il lavoro SENZA utente
--
-- `try_consume_ai_quota` (0009) pretende `auth.uid()` e verifica la membership:
-- è giusto, perché nasce per una richiesta fatta da una persona. La
-- sincronizzazione della posta però non ha una persona dietro — è un webhook o
-- un job — e con quella funzione fallirebbe.
--
-- La tentazione sarebbe contare le righe e poi inserirne una: è esattamente
-- l'errore che la 0009 è stata scritta per riparare, perché due sincronizzazioni
-- concorrenti leggono lo stesso conteggio e passano entrambe. Qui si riusa lo
-- STESSO lock consultivo per azienda, e si lascia cadere solo il controllo che
-- non ha senso senza un utente. Il ruolo `service_role` è l'unico che può
-- eseguirla, quindi la verifica di appartenenza è già stata fatta a monte da
-- chi possiede la connessione.
-- ---------------------------------------------------------------------------
create or replace function public.try_consume_ai_quota_system(
  p_company_id uuid,
  p_kind text,
  p_limit int,
  p_document_id uuid default null,
  p_provider text default null,
  p_model text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count int;
  v_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text, 0));

  select count(*) into v_count
    from public.ai_request_log
   where company_id = p_company_id
     and created_at > now() - interval '1 minute';

  if v_count >= p_limit then
    return null;
  end if;

  -- `user_id` resta NULL: nessuna persona ha chiesto questo lavoro, e
  -- attribuirlo a chi ha collegato la casella sarebbe un dato inventato (§80).
  insert into public.ai_request_log (company_id, user_id, document_id, kind, provider, model, status)
  values (p_company_id, null, p_document_id, p_kind, p_provider, p_model, 'pending')
  returning id into v_id;

  return v_id;
end;
$$;

create or replace function public.finalize_ai_request_system(
  p_id uuid,
  p_status text,
  p_duration_ms int default null,
  p_input_tokens int default null,
  p_output_tokens int default null,
  p_error_code text default null,
  p_model text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Solo righe di sistema: `finalize_ai_request` non potrebbe toccarle
  -- (confronta con auth.uid(), che qui è NULL), e questa non può toccare quelle
  -- di un utente. Le due funzioni restano disgiunte.
  update public.ai_request_log
     set status        = coalesce(p_status, status),
         duration_ms   = coalesce(p_duration_ms, duration_ms),
         input_tokens  = coalesce(p_input_tokens, input_tokens),
         output_tokens = coalesce(p_output_tokens, output_tokens),
         error_code    = coalesce(p_error_code, error_code),
         model         = coalesce(p_model, model)
   where id = p_id
     and user_id is null;
end;
$$;

revoke all on function public.try_consume_ai_quota_system(uuid, text, int, uuid, text, text) from public, anon, authenticated;
revoke all on function public.finalize_ai_request_system(uuid, text, int, int, int, text, text) from public, anon, authenticated;
grant execute on function public.try_consume_ai_quota_system(uuid, text, int, uuid, text, text) to service_role;
grant execute on function public.finalize_ai_request_system(uuid, text, int, int, int, text, text) to service_role;

comment on function public.try_consume_ai_quota_system is
  'Quota AI per il lavoro server-side senza utente (sincronizzazione Inbox). Stesso lock per azienda della 0009; eseguibile solo da service_role.';

-- ---------------------------------------------------------------------------
-- 16. Deduplicazione documentale (§59)
--
-- La ricerca per hash esiste già come indice dalla 0006
-- (`idx_documents_company_hash`): l'import da Inbox la riusa così com'è, senza
-- aggiungere una seconda nozione di «documento uguale». Qui si aggiunge solo
-- l'indice che serve alla provenienza inversa — «da quale email arriva questo
-- documento?» — che l'archivio userà per mostrarne l'origine.
-- ---------------------------------------------------------------------------
create index if not exists idx_documents_company_source on public.documents (company_id, source_type)
  where source_type = 'email';

-- >>>>>>>>>>>>>>>>>>>>  0014_inbox_grants  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0014 INBOX: i permessi di colonna diventano davvero restrittivi
--
-- COSA È ANDATO STORTO NELLA 0013
-- La 0013 concedeva `grant select (colonne…)` e `grant update (seen_at,
-- attention_status)` convinta di RESTRINGERE. Non restringeva nulla: un GRANT
-- aggiunge privilegi, non li toglie, e su Supabase ogni tabella nuova dello
-- schema `public` nasce già con i permessi di TABELLA completi per `anon` e
-- `authenticated` — è l'effetto di
--     alter default privileges in schema public grant all on tables to …
-- che il progetto imposta una volta e che si applica a ogni tabella creata da
-- lì in avanti. I permessi di colonna della 0013 erano quindi ridondanti.
--
-- Conseguenza concreta, misurata da `npm run test:inbox` sul database reale:
-- un membro dell'azienda poteva eseguire
--     update email_messages set subject = '…', body_text = '…', relevance = '…'
-- sui messaggi della PROPRIA azienda. La policy RLS lo autorizzava (è pensata
-- per far passare `seen_at`) e nessun permesso di colonna lo fermava. La riga
-- di posta non era il verbale immutabile di ciò che era arrivato: era un campo
-- libero. E poiché il ripristino di un messaggio «messo via» ricalcola lo stato
-- da `relevance`, riscrivere la classificazione permetteva anche di spostare un
-- messaggio in una categoria a piacere — aggirando il controllo che il trigger
-- fa proprio per impedirlo.
--
-- Perché per i segreti aveva funzionato: là la 0013 scriveva `revoke all`
-- prima. Mancava dappertutto altrove.
--
-- LA REGOLA CHE NE DERIVA
-- Su questo progetto, un permesso di colonna non significa niente finché non è
-- preceduto da un `revoke all` sulla stessa tabella. Vale per ogni tabella
-- futura dello schema `public`.
--
-- Perché una migrazione nuova e non una correzione della 0013: la 0013 è già
-- stata applicata in produzione. Un file di migrazione è il verbale di ciò che
-- è stato eseguito; riscriverlo dopo l'applicazione significherebbe che il
-- repository e il database raccontano due storie diverse.
--
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Prima si toglie tutto
--
-- `service_role` NON compare: è il ruolo con cui scrivono le Edge Function, e
-- deve conservare i suoi permessi. Si revoca anche da `public` (lo pseudo-ruolo
-- che comprende tutti) per non lasciare una via laterale.
-- ---------------------------------------------------------------------------
revoke all on public.email_connections        from anon, authenticated, public;
revoke all on public.email_connection_secrets from anon, authenticated, public;
revoke all on public.email_oauth_states       from anon, authenticated, public;
revoke all on public.email_messages           from anon, authenticated, public;
revoke all on public.email_attachments        from anon, authenticated, public;
revoke all on public.email_message_documents  from anon, authenticated, public;
revoke all on public.email_sync_runs          from anon, authenticated, public;
revoke all on public.email_webhook_events     from anon, authenticated, public;
revoke all on public.email_audit_log          from anon, authenticated, public;

-- ---------------------------------------------------------------------------
-- 2. Poi si concede esattamente quello che serve
--
-- CONNESSIONI — sola lettura, e solo le colonne che una schermata mostra.
-- `sync_cursor`, `history_floor_at`, `watch_resource_id`, `watch_last_error_code`
-- e `sync_lease_id` restano fuori: non sono segreti, ma non servono a nessuna
-- vista, e ciò che non è concesso non può essere esposto da una `select('*')`
-- scritta distrattamente.
--
-- ⚠️ Da qui in avanti `select('*')` su questa tabella FALLISCE con «permission
-- denied for column». È voluto, ed è il motivo per cui `emailConnectionService`
-- elenca le colonne una per una.
-- ---------------------------------------------------------------------------
grant select (
  id, company_id, connected_by, provider, provider_account_id, email_address, display_name,
  status, scopes, sync_enabled, initial_sync_completed_at, last_sync_at, last_successful_sync_at,
  last_error_code, last_error_at, watch_expires_at, sync_lease_until, created_at, updated_at
) on public.email_connections to authenticated;

-- MESSAGGI — lettura completa (non c'è nulla di riservato in una riga di posta
-- che il membro non possa già leggere), ma scrittura sulle sole due colonne
-- che rappresentano una decisione UMANA: «l'ho visto» e «l'ho messo via».
-- Tutto il resto — oggetto, mittente, corpo, classificazione, stato della
-- pipeline, impronta della fonte — è il verbale di ciò che è arrivato, e da
-- qui in avanti il client non ha alcun modo di riscriverlo.
grant select on public.email_messages to authenticated;
grant update (seen_at, attention_status) on public.email_messages to authenticated;

-- ALLEGATI, RELAZIONI, REGISTRI — sola lettura. Le righe visibili le decide la
-- RLS (membri per gli allegati e le relazioni, owner/admin per i registri).
grant select on public.email_attachments       to authenticated;
grant select on public.email_message_documents to authenticated;
grant select on public.email_sync_runs         to authenticated;
grant select on public.email_audit_log         to authenticated;

-- SEGRETI, STATI OAUTH, EVENTI WEBHOOK — nessun permesso, per nessuno.
-- Il `revoke` del punto 1 è già sufficiente; non si concede nulla qui.

-- ---------------------------------------------------------------------------
-- 3. Verifica in migrazione
--
-- Il controllo sta QUI dentro e non solo nella suite di test: se un domani
-- qualcuno riapplicasse per errore un `grant all`, questa migrazione rieseguita
-- lo direbbe subito. Un permesso di scrittura su una colonna del verbale è il
-- genere di regressione che non produce alcun sintomo visibile finché qualcuno
-- non la sfrutta.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
begin
  select string_agg(format('%s.%s (%s)', table_name, column_name, privilege_type), ', ')
    into v_bad
    from information_schema.column_privileges
   where table_schema = 'public'
     and grantee in ('anon', 'authenticated')
     and table_name = 'email_messages'
     and privilege_type in ('INSERT', 'UPDATE')
     and column_name not in ('seen_at', 'attention_status');

  if v_bad is not null then
    raise exception 'Permessi di scrittura inattesi su email_messages: %', v_bad;
  end if;

  select string_agg(format('%s (%s)', table_name, privilege_type), ', ')
    into v_bad
    from information_schema.table_privileges
   where table_schema = 'public'
     and grantee in ('anon', 'authenticated')
     and table_name in ('email_connection_secrets', 'email_oauth_states', 'email_webhook_events');

  if v_bad is not null then
    raise exception 'Le tabelle di servizio non devono avere alcun permesso: %', v_bad;
  end if;

  raise notice 'Permessi Inbox verificati: il verbale non è riscrivibile dal client.';
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0015_inbox_awaiting_analysis  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0015 INBOX: lo stato «analisi in coda»
--
-- COSA HA MOSTRATO IL PRIMO COLLEGAMENTO REALE (2026-07-26)
-- L'import iniziale di una casella vera ha promosso 14 messaggi a
-- `likely_actionable` in pochi secondi e ha lanciato per ciascuno l'analisi
-- documentale completa. Il limite di quota AI — 12 al minuto per azienda — è
-- stato superato al quarto, e i restanti 14 sono finiti in `failed` con
-- `PROVIDER_RATE_LIMITED`.
--
-- Il risultato era che «Da gestire», la lista più importante del prodotto, si
-- presentava piena di «Esame non riuscito». Non un guasto: una taratura
-- sbagliata. Quel limite protegge dall'utente che carica documenti a mano, ma
-- l'import iniziale non è un utente — è un processo che promuove decine di
-- messaggi tutti insieme. Il limite pensato per proteggere è diventato la causa.
--
-- PERCHÉ SERVE UNO STATO NUOVO E NON BASTA RITENTARE
-- La correzione è scaglionare: durante l'import iniziale si classifica (costa
-- poco) e si RINVIA l'analisi documentale, che verrà smaltita a lotti dalla
-- manutenzione periodica. Ma un messaggio classificato e in attesa di analisi
-- non è né `pending` (non ancora esaminato) né `done` (esaminato) né `failed`
-- (qualcosa è andato storto). È uno stato suo, e senza un nome proprio
-- finirebbe per essere rappresentato da uno degli altri tre — cioè da una
-- descrizione falsa. È la stessa ragione per cui la 0013 tiene separati lo
-- stato della macchina e quello della persona.
--
-- ⚠️ IL VINCOLO CHE HA ROTTO LA PRIMA STESURA DI QUESTA MIGRAZIONE
-- `alter type … add value` si può eseguire dentro una transazione, ma
-- l'etichetta aggiunta NON è utilizzabile finché quella transazione non è
-- chiusa (Postgres, 55P04 «unsafe use of new value»). Il SQL editor di Supabase
-- esegue l'intero script in un'unica transazione, quindi qualunque riga più
-- sotto che nomini 'awaiting_analysis' fa fallire tutto.
--
-- La prima stesura creava un indice parziale con
--   where processing_status = 'awaiting_analysis'
-- e falliva esattamente lì. Spezzare in due migrazioni NON avrebbe risolto:
-- `supabase/full-setup.sql` concatena tutte le migrazioni in un solo script, e
-- un'installazione da zero sarebbe fallita allo stesso punto — un guasto che si
-- sarebbe visto solo al primo cliente nuovo.
--
-- Quindi: in questo file l'etichetta nuova NON compare più da nessuna parte
-- oltre alla riga che la crea. L'indice qui sotto usa `relevance`, il cui
-- valore esiste dalla 0013, e tiene `processing_status` come COLONNA indicizzata
-- invece che come confronto con l'etichetta. Copre la stessa interrogazione —
-- «i messaggi azionabili di questa connessione, in ordine di data» — che è ciò
-- che lo smaltimento della coda esegue.
--
-- Regola generale: in una migrazione che aggiunge un valore a un enum, quel
-- valore non può comparire in nessun'altra istruzione dello stesso file.
--
-- Idempotente.
-- ============================================================================

alter type public.email_processing_status add value if not exists 'awaiting_analysis';

comment on type public.email_processing_status is
  'Stato della pipeline su un messaggio. «awaiting_analysis» = classificato come azionabile, analisi documentale rinviata a un lotto successivo: non è un errore e non è un lavoro concluso.';

-- Selezione dei lotti da smaltire. Il predicato usa solo valori enum esistenti
-- dalla 0013; `processing_status` è una colonna dell'indice, non un confronto.
create index if not exists idx_email_msg_actionable
  on public.email_messages (connection_id, processing_status, received_at desc)
  where relevance = 'likely_actionable';

-- >>>>>>>>>>>>>>>>>>>>  0016_work_hub  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0016 WORK HUB (Attività)
--
-- Lo Scadenziario diventa il posto in cui il lavoro viene assegnato, seguito e
-- concluso. Non è un task manager generico: è il punto in cui ciò che
-- AI-Swisse ha capito — da un documento, da una comunicazione, da un incentivo
-- — diventa lavoro di qualcuno, con una scadenza e una traccia.
--
-- SI EVOLVE `tasks`, NON SI CREA UNA TABELLA PARALLELA. Le attività esistenti
-- restano valide senza toccarle: una task legacy ha assegnatario nullo,
-- nessuna checklist e nessun commento, e questo è uno stato legittimo.
--
-- QUATTRO GARANZIE, TUTTE IMPOSTE DAL DATABASE E NON DAL BROWSER
--   1. L'ASSEGNATARIO è un membro della stessa azienda. Non un dropdown
--      filtrato lato client: un trigger che rifiuta l'inserimento.
--   2. CHI HA COMPLETATO e QUANDO li scrive il database da `auth.uid()` e
--      `now()`. Il client può mandare quello che vuole: viene sovrascritto.
--   3. L'AUTORE DI UN COMMENTO è `auth.uid()`: la policy lo impone in scrittura
--      e il trigger RIFIUTA — non corregge in silenzio — chi prova a firmare a
--      nome di un collega.
--   4. LO STORICO lo scrivono i trigger. `task_events` non è scrivibile dal
--      client — un registro che l'interessato può riscrivere non è un registro.
--
-- Questa migrazione è RIESEGUIBILE: ogni oggetto viene ricreato in modo
-- idempotente (`if not exists`, `create or replace`, `drop … if exists` prima
-- di policy e trigger). Applicarla due volte non fa danni e non duplica nulla.
--
-- ⚠️ VINCOLO SUI VALORI ENUM NUOVI (lezione della 0015)
-- `alter type … add value` non rende l'etichetta utilizzabile finché la
-- transazione non è chiusa, e il SQL editor esegue tutto in una transazione;
-- `full-setup.sql` concatena le migrazioni, quindi spezzare in due file non
-- risolverebbe — romperebbe ogni installazione da zero. Per questo
-- `in_progress` e `waiting` sono AGGIUNTI qui e non compaiono in nessun'altra
-- istruzione di questo file: trigger e indici parlano solo di `completed`, che
-- esiste dalla 0004.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Stati nuovi. Nessun'altra istruzione di questo file può nominarli.
-- ---------------------------------------------------------------------------
alter type public.task_status add value if not exists 'in_progress';
alter type public.task_status add value if not exists 'waiting';

comment on type public.task_status is
  'Stato di un''attività. «open» = da fare (nome storico, mostrato come «Da fare»), '
  '«in_progress» = qualcuno ci sta lavorando, «waiting» = dipende da terzi o da un evento '
  'esterno, «completed» = conclusa. L''archiviazione NON è uno stato: è `archived_at`, '
  'perché un''attività archiviata conserva lo stato che aveva.';

-- ---------------------------------------------------------------------------
-- 2. Tipi di evento dello storico.
--    Dichiarati con CREATE TYPE, quindi utilizzabili subito in questo file.
-- ---------------------------------------------------------------------------
do $$ begin
  create type public.task_event_kind as enum (
    'created', 'status_changed', 'assignee_changed', 'priority_changed',
    'due_date_changed', 'completed', 'reopened', 'archived', 'restored',
    'checklist_item_completed', 'comment_added'
  );
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 3. Colonne nuove su `tasks`
-- ---------------------------------------------------------------------------
alter table public.tasks
  add column if not exists assignee_user_id uuid references auth.users (id) on delete set null,
  add column if not exists completed_at     timestamptz,
  add column if not exists completed_by     uuid references auth.users (id) on delete set null,
  add column if not exists archived_at      timestamptz,
  add column if not exists archived_by      uuid references auth.users (id) on delete set null;

comment on column public.tasks.assignee_user_id is
  'Chi è responsabile. NULL = non assegnata, che è uno stato legittimo e non un dato mancante. '
  'L''appartenenza all''azienda la verifica il trigger `trg_tasks_guard`, non il client.';
comment on column public.tasks.completed_at is
  'Scritto dal database quando lo stato passa a «completed». Un valore mandato dal client viene ignorato.';
comment on column public.tasks.archived_at is
  'Archiviata: fuori dalle viste correnti, ancora nello storico. Sostituisce la cancellazione '
  'a un clic, che su un prodotto B2B faceva sparire il lavoro senza lasciare traccia.';

-- Un'attività si può assegnare solo a chi ha un utente: se l'assegnatario viene
-- rimosso dall'azienda la riga resta, con `assignee_user_id` che punta a un
-- utente non più membro. Lo si scopre in lettura (il nome non si risolve) e lo
-- si corregge riassegnando — cancellare l'attività sarebbe peggio.

-- ---------------------------------------------------------------------------
-- 4. Checklist: i sotto-passaggi operativi di un'attività.
--
--    ⚠️ NON è `action_progress`, e la distinzione è deliberata:
--      · `action_progress` (0010) sono le azioni ESTRATTE dall'analisi di un
--        documento. Appartengono all'analisi, che è immutabile, e dicono cosa
--        il documento chiede. Non si inventano e non si riscrivono.
--      · `task_checklist_items` sono i passaggi che una persona decide per
--        portare a termine un'attività. Si aggiungono, si riordinano, si
--        cancellano.
--    Convertendo un'analisi in attività le azioni ancora APERTE vengono copiate
--    come passaggi: è una DERIVAZIONE UNA TANTUM, non una sincronizzazione. Da
--    quel momento le due liste vivono separate e nessuna insegue l'altra —
--    spuntare un passaggio non tocca l'analisi, che resta immutabile.
--    Le azioni già completate NON si copiano: ricopiarle come «da fare» sarebbe
--    falso, e copiarle già spuntate lo sarebbe di più, perché il trigger
--    riscriverebbe «chi» e «quando» con l'utente e l'ora di adesso.
--    (Questo commento non descrive alcun oggetto del database: cambiarlo non
--    richiede di riapplicare la migrazione.)
-- ---------------------------------------------------------------------------
create table if not exists public.task_checklist_items (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid not null references public.companies (id) on delete cascade,
  task_id     uuid not null references public.tasks (id) on delete cascade,
  text        text not null check (length(btrim(text)) between 1 and 500),
  position    integer not null default 0,
  done        boolean not null default false,
  done_at     timestamptz,
  done_by     uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists idx_checklist_task on public.task_checklist_items (task_id, position, created_at);
create index if not exists idx_checklist_company on public.task_checklist_items (company_id);

-- ---------------------------------------------------------------------------
-- 5. Commenti. Testo semplice: il corpo non viene mai interpretato come markup,
--    né qui né alla lettura. Non esiste HTML da sanificare perché non esiste
--    HTML — la stessa scelta fatta per il corpo delle email (§54/§98).
-- ---------------------------------------------------------------------------
create table if not exists public.task_comments (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies (id) on delete cascade,
  task_id         uuid not null references public.tasks (id) on delete cascade,
  author_user_id  uuid not null references auth.users (id) on delete cascade,
  body            text not null check (length(btrim(body)) between 1 and 4000),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index if not exists idx_comments_task on public.task_comments (task_id, created_at desc);
create index if not exists idx_comments_company on public.task_comments (company_id);

-- ---------------------------------------------------------------------------
-- 6. Storico. Lo scrivono i trigger; il client può solo leggerlo.
-- ---------------------------------------------------------------------------
create table if not exists public.task_events (
  id             uuid primary key default gen_random_uuid(),
  company_id     uuid not null references public.companies (id) on delete cascade,
  task_id        uuid not null references public.tasks (id) on delete cascade,
  actor_user_id  uuid references auth.users (id) on delete set null,
  kind           public.task_event_kind not null,
  -- Solo ciò che serve a raccontare il cambiamento: valori da/a, mai testi
  -- liberi provenienti dal client.
  detail         jsonb not null default '{}'::jsonb,
  created_at     timestamptz not null default now()
);
create index if not exists idx_events_task on public.task_events (task_id, created_at desc);
create index if not exists idx_events_company on public.task_events (company_id);

-- ---------------------------------------------------------------------------
-- 7. Indici sulle interrogazioni che la lista fa davvero
-- ---------------------------------------------------------------------------
-- «Cosa c'è da fare»: tutto ciò che non è concluso, per scadenza.
create index if not exists idx_tasks_open_due
  on public.tasks (company_id, due_date, id)
  where status <> 'completed' and archived_at is null;
-- «Le mie attività».
create index if not exists idx_tasks_assignee
  on public.tasks (company_id, assignee_user_id, due_date);
-- Ricerca testuale su titolo e descrizione (stessa estensione già usata dalla 0013).
create index if not exists idx_tasks_search
  on public.tasks using gin ((coalesce(title, '') || ' ' || coalesce(description, '') || ' ' || coalesce(authority, '')) gin_trgm_ops);

-- ---------------------------------------------------------------------------
-- 8. Il guardiano di `tasks`: assegnatario valido, completamento e archiviazione
--    scritti dal server.
-- ---------------------------------------------------------------------------
create or replace function public.tasks_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- (a) L'assegnatario deve essere membro DELL'AZIENDA DELLA TASK. Senza questo
  --     controllo un membro potrebbe assegnare lavoro a un utente di un'altra
  --     azienda, e quel nome comparirebbe in una schermata che non gli
  --     appartiene. Non è un vincolo esprimibile con un CHECK: serve la lettura
  --     di un'altra tabella.
  if new.assignee_user_id is not null and not exists (
    select 1 from public.company_members m
    where m.company_id = new.company_id and m.user_id = new.assignee_user_id
  ) then
    raise exception 'assignee_not_member'
      using errcode = '23514',
            hint = 'La persona selezionata non appartiene a questa azienda.';
  end if;

  -- (b) Completamento: lo timbra il database. Se l'attività era già conclusa e
  --     resta tale, i valori originali non si toccano — chi ha completato una
  --     cosa non cambia perché qualcuno ha corretto il titolo.
  if new.status = 'completed' then
    if tg_op = 'INSERT' or old.status is distinct from 'completed' then
      new.completed_at := now();
      new.completed_by := auth.uid();
    else
      new.completed_at := old.completed_at;
      new.completed_by := old.completed_by;
    end if;
  else
    -- Riaperta: il completamento non è più un fatto, e i suoi campi si svuotano.
    -- Che sia stata completata in passato resta scritto in `task_events`, che è
    -- il posto giusto per la storia.
    new.completed_at := null;
    new.completed_by := null;
  end if;

  -- (c) Archiviazione: stesso principio. Il client dichiara l'intenzione
  --     valorizzando `archived_at`; il valore vero lo mette il database.
  if new.archived_at is not null then
    if tg_op = 'INSERT' or old.archived_at is null then
      new.archived_at := now();
      new.archived_by := auth.uid();
    else
      new.archived_at := old.archived_at;
      new.archived_by := old.archived_by;
    end if;
  else
    new.archived_by := null;
  end if;

  return new;
end $$;

drop trigger if exists trg_tasks_guard on public.tasks;
create trigger trg_tasks_guard
  before insert or update on public.tasks
  for each row execute function public.tasks_guard();

-- ---------------------------------------------------------------------------
-- 9. Storico automatico su `tasks`
-- ---------------------------------------------------------------------------
create or replace function public.tasks_record_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := auth.uid();
begin
  if tg_op = 'INSERT' then
    insert into public.task_events (company_id, task_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, v_actor, 'created',
            jsonb_build_object('source', new.source, 'priority', new.priority));
    return new;
  end if;

  if new.status is distinct from old.status then
    insert into public.task_events (company_id, task_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, v_actor,
            case
              when new.status = 'completed' then 'completed'::public.task_event_kind
              when old.status = 'completed' then 'reopened'::public.task_event_kind
              else 'status_changed'::public.task_event_kind
            end,
            jsonb_build_object('from', old.status, 'to', new.status));
  end if;

  if new.assignee_user_id is distinct from old.assignee_user_id then
    insert into public.task_events (company_id, task_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, v_actor, 'assignee_changed',
            jsonb_build_object('from', old.assignee_user_id, 'to', new.assignee_user_id));
  end if;

  if new.priority is distinct from old.priority then
    insert into public.task_events (company_id, task_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, v_actor, 'priority_changed',
            jsonb_build_object('from', old.priority, 'to', new.priority));
  end if;

  if new.due_date is distinct from old.due_date then
    insert into public.task_events (company_id, task_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, v_actor, 'due_date_changed',
            jsonb_build_object('from', old.due_date, 'to', new.due_date));
  end if;

  if (new.archived_at is not null) is distinct from (old.archived_at is not null) then
    insert into public.task_events (company_id, task_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, v_actor,
            case when new.archived_at is not null then 'archived'::public.task_event_kind
                 else 'restored'::public.task_event_kind end,
            '{}'::jsonb);
  end if;

  return new;
end $$;

drop trigger if exists trg_tasks_events on public.tasks;
create trigger trg_tasks_events
  after insert or update on public.tasks
  for each row execute function public.tasks_record_events();

-- ---------------------------------------------------------------------------
-- 10. Checklist: spunta timbrata dal server + evento
-- ---------------------------------------------------------------------------
create or replace function public.checklist_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
begin
  -- La riga deve appartenere all'azienda della propria attività: senza questo
  -- controllo un membro potrebbe agganciare una voce a una task altrui
  -- dichiarando la PROPRIA company_id, e la RLS non se ne accorgerebbe.
  select t.company_id into v_company from public.tasks t where t.id = new.task_id;
  if v_company is null or v_company is distinct from new.company_id then
    raise exception 'checklist_company_mismatch'
      using errcode = '23514', hint = 'La voce non appartiene all''attività indicata.';
  end if;

  if new.done then
    if tg_op = 'INSERT' or not old.done then
      new.done_at := now();
      new.done_by := auth.uid();
    else
      new.done_at := old.done_at;
      new.done_by := old.done_by;
    end if;
  else
    new.done_at := null;
    new.done_by := null;
  end if;

  return new;
end $$;

drop trigger if exists trg_checklist_guard on public.task_checklist_items;
create trigger trg_checklist_guard
  before insert or update on public.task_checklist_items
  for each row execute function public.checklist_guard();

drop trigger if exists trg_checklist_updated on public.task_checklist_items;
create trigger trg_checklist_updated
  before update on public.task_checklist_items
  for each row execute function public.set_updated_at();

create or replace function public.checklist_record_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.done and (tg_op = 'INSERT' or not old.done) then
    insert into public.task_events (company_id, task_id, actor_user_id, kind, detail)
    values (new.company_id, new.task_id, auth.uid(), 'checklist_item_completed',
            jsonb_build_object('item_id', new.id));
  end if;
  return new;
end $$;

drop trigger if exists trg_checklist_events on public.task_checklist_items;
create trigger trg_checklist_events
  after insert or update on public.task_checklist_items
  for each row execute function public.checklist_record_event();

-- ---------------------------------------------------------------------------
-- 11. Commenti: stessa verifica di appartenenza + evento
-- ---------------------------------------------------------------------------
create or replace function public.comments_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
begin
  select t.company_id into v_company from public.tasks t where t.id = new.task_id;
  if v_company is null or v_company is distinct from new.company_id then
    raise exception 'comment_company_mismatch'
      using errcode = '23514', hint = 'Il commento non appartiene all''attività indicata.';
  end if;
  -- L'autore è chi sta scrivendo, sempre.
  --
  -- ⚠️ Qui la prima versione RISCRIVEVA il campo con `auth.uid()`. Il risultato
  -- era sicuro — nessun commento è mai stato firmato a nome d'altri — ma era un
  -- fallback silenzioso: chi provava a firmare come un collega riceveva un
  -- «inserito» e non sapeva che il sistema aveva corretto. Su questo progetto un
  -- guasto si dichiara, non si aggiusta di nascosto. Ora si rifiuta.
  --
  -- La condizione lascia passare il service role (`auth.uid()` nullo), che è
  -- come lavorano le funzioni server e gli script di manutenzione.
  if auth.uid() is not null and new.author_user_id is distinct from auth.uid() then
    raise exception 'comment_author_mismatch'
      using errcode = '42501',
            hint = 'Un commento si firma con la propria identità.';
  end if;
  return new;
end $$;

drop trigger if exists trg_comments_guard on public.task_comments;
create trigger trg_comments_guard
  before insert or update on public.task_comments
  for each row execute function public.comments_guard();

drop trigger if exists trg_comments_updated on public.task_comments;
create trigger trg_comments_updated
  before update on public.task_comments
  for each row execute function public.set_updated_at();

create or replace function public.comments_record_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.task_events (company_id, task_id, actor_user_id, kind, detail)
  values (new.company_id, new.task_id, auth.uid(), 'comment_added',
          jsonb_build_object('comment_id', new.id));
  return new;
end $$;

drop trigger if exists trg_comments_events on public.task_comments;
create trigger trg_comments_events
  after insert on public.task_comments
  for each row execute function public.comments_record_event();

-- ---------------------------------------------------------------------------
-- 11bis. Rubrica dei membri: chi si può assegnare, e come si chiama.
--
-- Serve perché `profiles` è leggibile SOLO dal proprietario
-- (`profiles_select_own`, 0001): senza questa funzione un membro non potrebbe
-- vedere il nome di un collega, e l'interfaccia mostrerebbe identificativi al
-- posto delle persone. Non si allarga la policy di `profiles` — esporrebbe
-- l'intera riga, email compresa, a chiunque condivida un'azienda: si espone
-- solo ciò che serve, cioè come si chiama chi può ricevere un'attività.
--
-- `security definer` legge le tabelle, ma la prima condizione è che il
-- CHIAMANTE sia membro dell'azienda richiesta: senza quella riga la funzione
-- sarebbe una rubrica aperta di tutto il database.
-- ---------------------------------------------------------------------------
create or replace function public.company_member_directory(p_company_id uuid)
returns table (user_id uuid, display_name text, role public.member_role)
language sql
security definer
set search_path = ''
stable
as $$
  select
    m.user_id,
    -- Il nome se c'è; altrimenti l'email, che per un collega della stessa
    -- azienda è comunque un modo di riconoscerlo. Mai una stringa inventata.
    nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), '')
      as display_name,
    m.role
  from public.company_members m
  left join public.profiles p on p.id = m.user_id
  where m.company_id = p_company_id
    and public.is_company_member(p_company_id)
  order by 2 nulls last;
$$;

revoke all on function public.company_member_directory(uuid) from public, anon;
grant execute on function public.company_member_directory(uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 11ter. La lista delle attività: filtri, ordinamento e paginazione nel database.
--
-- Perché una funzione e non tre `.order()` dal client: l'ordine che serve —
-- prima le scadute, poi la priorità alta, poi la scadenza più vicina, in fondo
-- quelle senza scadenza — non è esprimibile con una sequenza di colonne, e
-- ordinare in memoria richiederebbe di scaricare tutte le attività prima di
-- sapere quali contano. Con mille attività sarebbe un'applicazione che si
-- ferma; qui la pagina la compone il database.
--
-- `security invoker` (il default): la RLS di `tasks` continua ad applicarsi
-- riga per riga. Il filtro esplicito su `company_id` non la sostituisce — la
-- accompagna, com'è disciplina di questo progetto.
-- ---------------------------------------------------------------------------
create or replace function public.list_tasks(
  p_company_id  uuid,
  p_view        text default 'todo',      -- todo | mine | overdue | completed | archived | all
  p_status      public.task_status default null,
  p_priority    public.task_priority default null,
  p_source      public.task_source default null,
  p_assignee    uuid default null,
  p_search      text default null,
  p_limit       integer default 25,
  p_offset      integer default 0
)
returns table (
  id uuid, company_id uuid, created_by uuid, document_id uuid, subsidy_case_id uuid,
  title text, description text, authority text, due_date date,
  priority public.task_priority, status public.task_status, source public.task_source,
  assignee_user_id uuid, completed_at timestamptz, completed_by uuid,
  archived_at timestamptz, archived_by uuid, created_at timestamptz, updated_at timestamptz,
  assignee_name text, email_message_id uuid, total_count bigint
)
language sql
stable
set search_path = ''
as $$
  with filtered as (
    select t.*
    from public.tasks t
    where t.company_id = p_company_id
      -- Le viste. «archived» è l'unica che mostra le archiviate: ovunque
      -- altrove restano fuori, che è il senso dell'archiviazione.
      and case p_view
            when 'todo'      then t.status <> 'completed' and t.archived_at is null
            when 'mine'      then t.assignee_user_id = auth.uid() and t.status <> 'completed' and t.archived_at is null
            when 'overdue'   then t.status <> 'completed' and t.archived_at is null
                                  and t.due_date is not null and t.due_date < current_date
            when 'completed' then t.status = 'completed' and t.archived_at is null
            when 'archived'  then t.archived_at is not null
            else t.archived_at is null
          end
      and (p_status   is null or t.status = p_status)
      and (p_priority is null or t.priority = p_priority)
      and (p_source   is null or t.source = p_source)
      and (p_assignee is null or t.assignee_user_id = p_assignee)
      and (
        p_search is null or btrim(p_search) = ''
        or t.title ilike '%' || btrim(p_search) || '%'
        or coalesce(t.description, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(t.authority, '') ilike '%' || btrim(p_search) || '%'
      )
  )
  select
    f.id, f.company_id, f.created_by, f.document_id, f.subsidy_case_id,
    f.title, f.description, f.authority, f.due_date,
    f.priority, f.status, f.source,
    f.assignee_user_id, f.completed_at, f.completed_by,
    f.archived_at, f.archived_by, f.created_at, f.updated_at,
    nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), '') as assignee_name,
    -- La comunicazione da cui nasce, quando il documento collegato viene dalla
    -- posta. Non serve una colonna su `tasks`: la relazione esiste già.
    (select d.email_message_id
       from public.email_message_documents d
      where d.document_id = f.document_id
      order by d.created_at asc
      limit 1) as email_message_id,
    count(*) over () as total_count
  from filtered f
  left join public.profiles p on p.id = f.assignee_user_id
  order by
    -- 1. scadute
    case when f.status <> 'completed' and f.due_date is not null and f.due_date < current_date
         then 0 else 1 end,
    -- 2. priorità alta
    case f.priority when 'high' then 0 when 'medium' then 1 else 2 end,
    -- 3. scadenza più vicina, 4. senza scadenza in fondo
    f.due_date asc nulls last,
    -- 5. a parità di tutto, le più recenti
    f.created_at desc
  limit greatest(1, least(coalesce(p_limit, 25), 100))
  offset greatest(0, coalesce(p_offset, 0));
$$;

revoke all on function public.list_tasks(uuid, text, public.task_status, public.task_priority, public.task_source, uuid, text, integer, integer) from public, anon;
grant execute on function public.list_tasks(uuid, text, public.task_status, public.task_priority, public.task_source, uuid, text, integer, integer) to authenticated;

-- ---------------------------------------------------------------------------
-- 12. RLS
--
-- ⚠️ `revoke all` PRIMA dei grant, su ogni tabella nuova: su Supabase una
-- tabella di `public` nasce con i permessi di tabella completi per `anon` e
-- `authenticated` (`alter default privileges … grant all on tables`), quindi un
-- grant scritto dopo AGGIUNGE privilegi invece di restringerli. È la lezione
-- della 0014, dove i permessi di colonna della 0013 non restringevano nulla.
-- ---------------------------------------------------------------------------
alter table public.task_checklist_items enable row level security;
alter table public.task_comments        enable row level security;
alter table public.task_events          enable row level security;

revoke all on public.task_checklist_items from anon, authenticated, public;
revoke all on public.task_comments        from anon, authenticated, public;
revoke all on public.task_events          from anon, authenticated, public;

grant select, insert, update, delete on public.task_checklist_items to authenticated;
-- I commenti non si cancellano: una conversazione con dei buchi è peggio di una
-- conversazione con un errore. Si possono correggere entro i limiti della policy.
grant select, insert, update on public.task_comments to authenticated;
-- Lo storico è in SOLA LETTURA per il client: lo scrivono i trigger, che girano
-- come `security definer` e non passano da questi permessi.
grant select on public.task_events to authenticated;

drop policy if exists checklist_select_member on public.task_checklist_items;
create policy checklist_select_member on public.task_checklist_items
  for select to authenticated using (public.is_company_member(company_id));
drop policy if exists checklist_insert_member on public.task_checklist_items;
create policy checklist_insert_member on public.task_checklist_items
  for insert to authenticated with check (public.is_company_member(company_id));
drop policy if exists checklist_update_member on public.task_checklist_items;
create policy checklist_update_member on public.task_checklist_items
  for update to authenticated using (public.is_company_member(company_id))
  with check (public.is_company_member(company_id));
drop policy if exists checklist_delete_member on public.task_checklist_items;
create policy checklist_delete_member on public.task_checklist_items
  for delete to authenticated using (public.is_company_member(company_id));

drop policy if exists comments_select_member on public.task_comments;
create policy comments_select_member on public.task_comments
  for select to authenticated using (public.is_company_member(company_id));
-- `author_user_id = auth.uid()` nella WITH CHECK: nessuno può firmare a nome
-- d'altri, e non è una convenzione del servizio ma una regola del database.
drop policy if exists comments_insert_author on public.task_comments;
create policy comments_insert_author on public.task_comments
  for insert to authenticated
  with check (public.is_company_member(company_id) and author_user_id = auth.uid());
drop policy if exists comments_update_author on public.task_comments;
create policy comments_update_author on public.task_comments
  for update to authenticated
  using (public.is_company_member(company_id) and author_user_id = auth.uid())
  with check (public.is_company_member(company_id) and author_user_id = auth.uid());

drop policy if exists events_select_member on public.task_events;
create policy events_select_member on public.task_events
  for select to authenticated using (public.is_company_member(company_id));

-- ---------------------------------------------------------------------------
-- 13. Autoverifica: la migrazione controlla di aver ottenuto ciò che dichiara.
--     Se domani qualcuno concede per sbaglio la scrittura sullo storico, questa
--     migrazione fallisce all'applicazione invece di lasciar passare la falla.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
begin
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name = 'task_events'
    and grantee in ('anon', 'authenticated', 'public')
    and privilege_type in ('INSERT', 'UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'lo storico delle attività risulta scrivibile dal client: %', v_bad;
  end if;

  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name = 'task_comments'
    and grantee in ('anon', 'authenticated', 'public')
    and privilege_type = 'DELETE';
  if v_bad is not null then
    raise exception 'i commenti risultano cancellabili dal client: %', v_bad;
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0017_document_hub  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0017 SMART DOCUMENT HUB (Documenti)
--
-- L'Archivio diventa «Documenti»: non una cartella di file, ma il posto in cui
-- si ritrova ciò che l'azienda sa. Le domande a cui deve rispondere sono
-- concrete — «dov'è il contratto Swisscom?», «cosa ci ha mandato l'AFC
-- quest'anno?», «da quale email è arrivato questo PDF?» — e nessuna di esse si
-- risponde con un elenco ordinato per data.
--
-- ⚠️ QUESTA MIGRAZIONE NON CREA UNA SECONDA VERITÀ SUI DOCUMENTI.
-- Mittente, tipo, scadenza, importi, citazioni e incertezze restano dove sono:
-- in `document_analyses`, che è immutabile dalla 0010, e in
-- `analysis_corrections` per ciò che una persona ha corretto. Qui si aggiunge
-- SOLO l'organizzazione aziendale — categoria, etichette, archiviazione, note —
-- che è l'unica cosa che l'azienda può cambiare liberamente senza toccare
-- l'analisi. La lettura combinata la fa `list_documents`, che compone; non
-- copia.
--
-- COSA CONTIENE
--   1. Due tipi nuovi: `document_category` e `document_category_source`.
--   2. Colonne di organizzazione su `documents` (categoria, archiviazione, note).
--   3. Etichette aziendali: `document_tags` + `document_tag_links`.
--   4. Ricerca full-text sul testo estratto (configurazione `simple`).
--   5. Classificazione DETERMINISTICA da tipo documento e tipo di ente.
--   6. `list_documents` / `document_category_counts` / le tre azioni di gruppo.
--   7. RLS, permessi e autoverifica.
--
-- ⚠️ VINCOLO SUI VALORI ENUM (lezione della 0015, ricordata dalla 0016)
-- `alter type … add value` rende l'etichetta inutilizzabile fino alla fine
-- della transazione, e `full-setup.sql` concatena tutto in una transazione
-- sola. Qui NON si aggiungono valori a enum esistenti: i due tipi nuovi
-- nascono con `create type … as enum (…)`, e quelli sono utilizzabili subito.
-- `npm run db:bundle` lo verifica.
--
-- Riesecuzione: sicura. Ogni oggetto è idempotente.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Categoria documentale
--
-- ⚠️ LA CATEGORIA NON È IL TIPO DI DOCUMENTO. `document_type` dice CHE COSA è
-- un documento (un sollecito, una decisione, una fattura); la categoria dice
-- DOVE STA nell'organizzazione dell'azienda. Un sollecito dell'AFC è di tipo
-- «sollecito» e di categoria «imposte»: chi lo cerca fra sei mesi lo cerca
-- fra le imposte, non fra i solleciti.
--
-- Perché `social_insurance` è una categoria a sé e non sta dentro
-- «assicurazioni» né dentro «personale»: in Svizzera AVS/AI/IPG, LPP e LAINF
-- sono il flusso amministrativo più regolare di una PMI, arrivano da enti
-- diversi dalle assicurazioni private e si conservano separati. Metterli
-- altrove avrebbe significato decidere al posto dell'utente una cosa che il
-- dominio non decide.
--
-- Nessun valore «da classificare»: quello è l'ASSENZA di categoria (NULL).
-- Un documento che il sistema non sa classificare non è «altro» — «altro» è
-- una scelta che una persona può fare, NULL è il fatto che nessuno ha ancora
-- scelto. Confonderli farebbe sparire dalla vista ciò che va sistemato.
-- ---------------------------------------------------------------------------
do $$ begin
  create type public.document_category as enum (
    'administration',     -- autorità, permessi, decisioni, controlli
    'taxes',              -- imposte dirette e IVA
    'social_insurance',   -- AVS/AI/IPG, LPP, LAINF
    'invoices',           -- fatture e richieste di pagamento
    'contracts',          -- contratti e documenti contrattuali
    'insurance',          -- polizze private
    'banking',            -- banche e mezzi di pagamento
    'employees',          -- personale, salari, certificati
    'clients',            -- documenti riferiti a un cliente
    'suppliers',          -- documenti riferiti a un fornitore
    'subsidies',          -- incentivi e sussidi
    'other'               -- scelta esplicita di una persona, non un ripiego
  );
exception when duplicate_object then null; end $$;

-- Da dove viene la categoria. Due valori soli, e non tre: non esiste `ai`
-- perché nessuna chiamata AI viene fatta per classificare — dichiarare un
-- valore che il codice non produce sarebbe descrivere una funzione che non c'è.
do $$ begin
  create type public.document_category_source as enum ('rule', 'manual');
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 2. Organizzazione aziendale sul documento
--
-- Colonne su `documents` e non una tabella `document_catalog` a fianco: sono
-- attributi DEL documento, non di un'altra entità, e ogni riga della lista li
-- filtra e li ordina. Una tabella uno-a-uno avrebbe aggiunto un join a ogni
-- interrogazione e una riga da creare per ogni documento, in cambio di niente.
-- ---------------------------------------------------------------------------
alter table public.documents
  add column if not exists category           public.document_category,
  add column if not exists category_source    public.document_category_source,
  add column if not exists category_set_by    uuid references auth.users (id) on delete set null,
  add column if not exists category_set_at    timestamptz,
  add column if not exists archived_at        timestamptz,
  add column if not exists archived_by        uuid references auth.users (id) on delete set null,
  add column if not exists internal_notes     text,
  add column if not exists notes_updated_at   timestamptz,
  add column if not exists notes_updated_by   uuid references auth.users (id) on delete set null;

do $$ begin
  alter table public.documents
    add constraint documents_internal_notes_len check (length(internal_notes) <= 4000);
exception when duplicate_object then null; end $$;

comment on column public.documents.category is
  'Dove il documento sta nell''organizzazione aziendale. NULL = nessuno ha ancora '
  'classificato, che è diverso da «other» (scelta esplicita di una persona).';
comment on column public.documents.category_source is
  'Chi ha deciso la categoria: «rule» una regola deterministica sul tipo di documento '
  'e sul tipo di ente, «manual» una persona. Lo scrive il trigger, non il client.';
comment on column public.documents.archived_at is
  'Archiviato: fuori dalle viste correnti, ancora nel sistema con analisi, email '
  'di provenienza e attività intatte. Non è la cancellazione.';
comment on column public.documents.internal_notes is
  'Annotazione interna dell''azienda («verificato con la fiduciaria il 12 agosto»). '
  'Testo semplice, mai interpretato come markup, e mai confuso con l''analisi AI.';

-- ---------------------------------------------------------------------------
-- 3. Etichette aziendali
--
-- Categoria e etichette rispondono a domande diverse: la categoria è una sola
-- e dice dove sta il documento, le etichette sono molte e dicono a cosa si
-- riferisce («IVA», «2026», «Sede Lugano», «Veicoli»). Per questo non si è
-- fatto un albero di cartelle: una gerarchia costringe a scegliere un solo
-- ramo e produce lavoro amministrativo invece di ridurlo.
-- ---------------------------------------------------------------------------
create table if not exists public.document_tags (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid not null references public.companies (id) on delete cascade,
  name        text not null check (length(btrim(name)) between 1 and 40),
  created_by  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now()
);

-- Unicità senza distinzione di maiuscole: «IVA» e «Iva» sono la stessa
-- etichetta, e vederle entrambe nell'elenco farebbe dubitare di quale usare.
create unique index if not exists uq_document_tags_name
  on public.document_tags (company_id, lower(btrim(name)));

create table if not exists public.document_tag_links (
  company_id   uuid not null references public.companies (id) on delete cascade,
  document_id  uuid not null references public.documents (id) on delete cascade,
  tag_id       uuid not null references public.document_tags (id) on delete cascade,
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),
  primary key (document_id, tag_id)
);
create index if not exists idx_tag_links_tag on public.document_tag_links (tag_id);
create index if not exists idx_tag_links_company on public.document_tag_links (company_id);

-- ---------------------------------------------------------------------------
-- 4. Indici sulle interrogazioni che la lista fa DAVVERO
--
-- Non si aggiungono indici «per sicurezza»: ognuno di questi corrisponde a una
-- clausola che `list_documents` scrive sempre o quasi sempre.
-- ---------------------------------------------------------------------------
-- La lista predefinita: documenti non archiviati di un'azienda, dal più recente.
create index if not exists idx_documents_active
  on public.documents (company_id, created_at desc, id desc)
  where archived_at is null;
-- La barra laterale delle categorie e il filtro per categoria.
create index if not exists idx_documents_category
  on public.documents (company_id, category)
  where archived_at is null;
-- La vista «archiviati».
create index if not exists idx_documents_archived
  on public.documents (company_id, archived_at desc)
  where archived_at is not null;
-- Ricerca sui metadati del documento (titolo e nome del file originale).
create index if not exists idx_documents_text_trgm
  on public.documents using gin (
    (coalesce(title, '') || ' ' || coalesce(original_filename, '')) gin_trgm_ops
  );
-- «L'ultima analisi di questo documento», che la lista chiede per ogni riga.
create index if not exists idx_analyses_document_created
  on public.document_analyses (document_id, created_at desc);
-- Ricerca su mittente e oggetto, che stanno sull'analisi e non sul documento.
create index if not exists idx_analyses_text_trgm
  on public.document_analyses using gin (
    (coalesce(sender, '') || ' ' || coalesce(subject, '') || ' ' || coalesce(recipient, '')) gin_trgm_ops
  );
-- Le correzioni umane di un documento, lette per ogni riga della lista.
create index if not exists idx_corrections_document
  on public.analysis_corrections (document_id, corrected_at);
-- Le attività collegate a un documento.
create index if not exists idx_tasks_document
  on public.tasks (document_id) where document_id is not null;

-- ---------------------------------------------------------------------------
-- 5. Ricerca nel testo estratto
--
-- ⚠️ CONFIGURAZIONE `simple`, E LA RAGIONE VA DICHIARATA.
-- I documenti di una PMI svizzera arrivano in italiano, tedesco e francese,
-- spesso nella stessa settimana. Una configurazione con radici (`italian`,
-- `german`…) migliora una lingua e PEGGIORA le altre due, perché applica a
-- tutti i testi le regole di una sola. `simple` non taglia le desinenze e non
-- toglie parole comuni: cerca esattamente le parole scritte.
--
-- IL PREZZO, dichiarato qui e nel README: cercando «Rechnung» non si trovano i
-- documenti che dicono «Rechnungen». È un limite reale, ed è preferibile a una
-- ricerca che funziona bene in una lingua e male nelle altre due. La ricerca
-- sui metadati resta a sottostringa (trigram), quindi «Rechnung» trova
-- comunque «Rechnungen» in titolo, mittente e oggetto.
--
-- ⚠️ IL TESTO INDICIZZATO È TRONCATO A 500'000 CARATTERI. Non è un
-- arrotondamento: un `tsvector` non può superare 1 MB, e una colonna generata
-- che solleva un'eccezione farebbe fallire il salvataggio dell'ESTRAZIONE,
-- cioè spegnerebbe l'analisi dei documenti molto lunghi. Cinquecentomila
-- caratteri sono circa duecentocinquanta pagine di testo; oltre quella soglia
-- la ricerca full-text non copre la coda del documento, e questo è scritto
-- anche in `docs/document-hub.md`.
-- ---------------------------------------------------------------------------
alter table public.document_extractions
  add column if not exists search_tsv tsvector
  generated always as (
    to_tsvector('simple'::regconfig, left(coalesce(full_text, ''), 500000))
  ) stored;

create index if not exists idx_extractions_search
  on public.document_extractions using gin (search_tsv);

comment on column public.document_extractions.search_tsv is
  'Indice di ricerca del testo estratto, configurazione «simple» (nessuna radice, '
  'nessuna parola esclusa): i documenti arrivano in tre lingue e le regole di una '
  'sola peggiorerebbero le altre due. Copre i primi 500''000 caratteri.';

-- ---------------------------------------------------------------------------
-- 6. Conversioni difensive
--
-- Le correzioni umane sono salvate come JSON dal browser: una data corretta è
-- una stringa. Convertirla con `::date` dentro la lista significherebbe che una
-- sola correzione malformata fa fallire l'INTERA ricerca dell'azienda — un
-- guasto totale causato da un campo secondario. Queste due funzioni tornano
-- NULL invece di sollevare: il valore non convertibile viene ignorato e resta
-- quello dell'analisi, che è un dato vero.
-- ---------------------------------------------------------------------------
create or replace function public.try_date(p_text text)
returns date
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_text is null or btrim(p_text) = '' then return null; end if;
  return btrim(p_text)::date;
exception when others then
  return null;
end $$;

create or replace function public.try_numeric(p_text text)
returns numeric
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_text is null or btrim(p_text) = '' then return null; end if;
  return btrim(p_text)::numeric;
exception when others then
  return null;
end $$;

-- ---------------------------------------------------------------------------
-- 7. Classificazione deterministica
--
-- Nessuna chiamata AI: il documento è GIÀ stato analizzato, e da quell'analisi
-- si ricava la categoria quando il segnale è forte. Dove non lo è si torna
-- NULL, e il documento compare fra quelli da classificare — che è la verità.
-- Assegnare «altro» per non lasciare un vuoto sarebbe inventare una certezza.
--
-- L'ordine conta: il tipo di documento vince sul tipo di ente, perché una
-- fattura è una fattura anche se la manda un Comune. Il ripiego sull'ente
-- interviene solo quando il tipo non dice abbastanza.
--
-- Deliberatamente NON classificati: `declaration_request`,
-- `request_for_documents` e `information`. Una dichiarazione da presentare può
-- essere fiscale, sociale o statistica; una richiesta di documenti può venire
-- da chiunque. Il segnale non basta, e chi usa il prodotto se ne accorge
-- subito se la macchina indovina male.
-- ---------------------------------------------------------------------------
create or replace function public.document_category_from_analysis(
  p_document_type text,
  p_authority_type text
)
returns public.document_category
language sql
immutable
set search_path = ''
as $$
  select case
    -- (a) il tipo di documento, quando è già una collocazione
    when p_document_type = 'tax_document'      then 'taxes'::public.document_category
    when p_document_type = 'social_insurance'  then 'social_insurance'::public.document_category
    when p_document_type = 'employment'        then 'employees'::public.document_category
    when p_document_type = 'contract_related'  then 'contracts'::public.document_category
    when p_document_type = 'invoice'           then 'invoices'::public.document_category
    when p_document_type = 'permit'            then 'administration'::public.document_category
    when p_document_type = 'official_decision' then 'administration'::public.document_category
    when p_document_type = 'inspection_notice' then 'administration'::public.document_category

    -- (b) una richiesta di pagamento o un sollecito da un privato è una fattura;
    --     dallo Stato può essere un'imposta, una tassa o un canone, e quale
    --     delle tre non lo dice il tipo.
    when p_document_type in ('payment_request', 'reminder') and p_authority_type = 'private'
      then 'invoices'::public.document_category

    -- (c) il tipo di ente, quando il tipo di documento non ha deciso
    when p_authority_type = 'social_insurance' then 'social_insurance'::public.document_category
    when p_authority_type = 'pension'          then 'social_insurance'::public.document_category
    when p_authority_type = 'insurance'        then 'insurance'::public.document_category
    when p_authority_type in ('federal', 'cantonal', 'municipal')
      then 'administration'::public.document_category

    else null
  end;
$$;

comment on function public.document_category_from_analysis(text, text) is
  'Categoria ricavata da tipo di documento e tipo di ente. Torna NULL quando il '
  'segnale non basta: un documento non classificato è un fatto, una categoria '
  'plausibile ma sbagliata è un errore che nessuno nota.';

-- ---------------------------------------------------------------------------
-- 8. Il guardiano di `documents`
--
-- Come per le attività (0016), i timbri li mette il database. Il client può
-- mandare quello che vuole: chi ha archiviato, chi ha scelto la categoria e
-- quando lo decide `auth.uid()` e `now()`.
--
-- ⚠️ COME SI DISTINGUE UNA PERSONA DAL SISTEMA, e perché serve.
-- Due segnali, entrambi non falsificabili da un browser:
--   · `pg_trigger_depth() > 1` — l'aggiornamento arriva da un altro trigger,
--     cioè dalla classificazione automatica che scatta quando nasce un'analisi;
--   · `auth.uid() is null` — sta scrivendo il service role o una migrazione,
--     che è come lavorano le funzioni server e gli script (stessa condizione
--     già usata dal guardiano dei commenti nella 0016).
-- In quei due casi l'origine dichiarata viene rispettata; in tutti gli altri
-- chi cambia la categoria è una persona, e l'origine diventa «manual» con il
-- suo nome sopra. Così nessun client può spacciare una scelta propria per una
-- classificazione automatica, e viceversa.
-- ---------------------------------------------------------------------------
create or replace function public.documents_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor  uuid := auth.uid();
  v_system boolean := v_actor is null or pg_trigger_depth() > 1;
begin
  -- (a) Categoria
  if new.category is null then
    -- Nessuna categoria: non c'è nulla da attribuire a nessuno, né quando la
    -- si toglie né quando non c'è mai stata.
    new.category_source := null;
    new.category_set_by := null;
    new.category_set_at := null;
  elsif v_system then
    -- Il sistema scrive ciò che dichiara. Se ha messo una categoria senza dire
    -- da dove viene, viene dalla regola: è l'unico modo in cui il sistema
    -- classifica.
    if new.category_source is null then
      new.category_source := 'rule';
      new.category_set_at := coalesce(new.category_set_at, now());
    end if;
  elsif tg_op = 'INSERT' or new.category is distinct from old.category then
    new.category_source := 'manual';
    new.category_set_by := v_actor;
    new.category_set_at := now();
  else
    -- Categoria invariata: i timbri restano quelli. Chi ha classificato non
    -- cambia perché qualcuno ha corretto il titolo.
    new.category_source := old.category_source;
    new.category_set_by := old.category_set_by;
    new.category_set_at := old.category_set_at;
  end if;

  -- (b) Archiviazione. Il client dichiara l'intenzione valorizzando
  --     `archived_at`; il valore vero lo mette il database.
  if new.archived_at is not null then
    if tg_op = 'INSERT' or old.archived_at is null then
      new.archived_at := now();
      new.archived_by := v_actor;
    else
      new.archived_at := old.archived_at;
      new.archived_by := old.archived_by;
    end if;
  else
    new.archived_by := null;
  end if;

  -- (c) Nota interna: chi l'ha scritta e quando.
  if tg_op = 'INSERT' then
    if new.internal_notes is not null then
      new.notes_updated_at := now();
      new.notes_updated_by := v_actor;
    else
      new.notes_updated_at := null;
      new.notes_updated_by := null;
    end if;
  elsif new.internal_notes is distinct from old.internal_notes then
    new.notes_updated_at := now();
    new.notes_updated_by := v_actor;
  else
    new.notes_updated_at := old.notes_updated_at;
    new.notes_updated_by := old.notes_updated_by;
  end if;

  return new;
end $$;

drop trigger if exists trg_documents_guard on public.documents;
create trigger trg_documents_guard
  before insert or update on public.documents
  for each row execute function public.documents_guard();

-- ---------------------------------------------------------------------------
-- 9. Classificazione automatica quando arriva un'analisi
--
-- Si applica SOLO se nessuno ha ancora classificato il documento: una scelta
-- fatta da una persona non viene mai sovrascritta da una rianalisi. È
-- deliberatamente un trigger e non una colonna calcolata, perché la categoria
-- deve poter essere cambiata a mano e restare cambiata.
-- ---------------------------------------------------------------------------
create or replace function public.documents_autoclassify()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_category public.document_category;
begin
  -- Un'analisi fallita non descrive niente: non se ne ricava una collocazione.
  if new.analysis_status = 'failed' then return new; end if;

  v_category := public.document_category_from_analysis(new.document_type, new.sender_authority_type);
  if v_category is null then return new; end if;

  -- ⚠️ `d.company_id = new.company_id` NON è ridondante, ed è la riga più
  -- importante di questa funzione.
  --
  -- Questa funzione è `security definer`: scrive su `documents` SENZA passare
  -- dalla RLS. La policy di inserimento delle analisi (0010) verifica che chi
  -- inserisce sia membro dell'azienda dichiarata, ma NON che il documento
  -- indicato appartenga a quella stessa azienda. Senza questo confronto, un
  -- membro dell'azienda A potrebbe inserire un'analisi con la PROPRIA
  -- `company_id` e il `document_id` di un documento dell'azienda B, e questo
  -- trigger avrebbe scritto una categoria su un documento di B.
  -- (La falla di partenza viene chiusa qui sotto, al punto 9bis; questa riga
  -- resta comunque, perché una funzione che scavalca la RLS deve difendersi da
  -- sola e non fidarsi di una policy scritta altrove.)
  update public.documents d
     set category = v_category
   where d.id = new.document_id
     and d.company_id = new.company_id
     and d.category is null
     and d.category_source is distinct from 'manual';

  return new;
end $$;

drop trigger if exists trg_documents_autoclassify on public.document_analyses;
create trigger trg_documents_autoclassify
  after insert on public.document_analyses
  for each row execute function public.documents_autoclassify();

-- ---------------------------------------------------------------------------
-- 9bis. Un'analisi appartiene al documento della PROPRIA azienda
--
-- Falla trovata rileggendo la 0010 con l'occhio di chi vuole abusarne, mentre
-- si scriveva la classificazione automatica. La policy di inserimento verifica
-- che chi scrive sia membro dell'azienda DICHIARATA nella riga, ma nessuno
-- verificava che il `document_id` appartenesse a quella azienda: un membro di A
-- poteva creare righe di analisi agganciate ai documenti di B.
--
-- Da sola non era una fuga di dati — la RLS in lettura filtra per `company_id`,
-- quindi B non vedeva quelle righe e A non vedeva i documenti di B — ma era
-- scrittura in casa d'altri, e la classificazione automatica l'avrebbe resa
-- visibile. Si chiude qui, dove è stata trovata, invece di lasciarla aperta
-- perché «non è di questa migrazione».
-- ---------------------------------------------------------------------------
drop policy if exists analyses_insert_member on public.document_analyses;
create policy analyses_insert_member on public.document_analyses
  for insert to authenticated
  with check (
    public.is_company_member(company_id)
    and engine like 'deterministic-%'              -- niente righe che si spacciano per AI
    and provider is null
    and model is null
    and prompt_version is null
    and exists (
      select 1 from public.documents d
      where d.id = document_id and d.company_id = company_id
    )
  );

comment on policy analyses_insert_member on public.document_analyses is
  'Il client può inserire solo analisi del motore locale, senza provenienza AI, '
  'e SOLO su documenti della stessa azienda dichiarata nella riga.';

-- ---------------------------------------------------------------------------
-- 10. Etichette: appartenenza verificata dal database
--
-- Il caso obliquo è lo stesso già visto con la checklist delle attività: un
-- membro dichiara la PROPRIA azienda e aggancia l'etichetta a un documento di
-- un'altra. La RLS da sola lascerebbe passare — la company dichiarata è
-- davvero la sua — e per questo il controllo confronta le tre appartenenze.
-- ---------------------------------------------------------------------------
create or replace function public.document_tag_link_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc_company uuid;
  v_tag_company uuid;
  v_count integer;
begin
  select d.company_id into v_doc_company from public.documents d where d.id = new.document_id;
  select g.company_id into v_tag_company from public.document_tags g where g.id = new.tag_id;

  if v_doc_company is null or v_tag_company is null
     or v_doc_company is distinct from new.company_id
     or v_tag_company is distinct from new.company_id then
    raise exception 'tag_company_mismatch'
      using errcode = '23514',
            hint = 'Etichetta e documento devono appartenere alla stessa azienda.';
  end if;

  -- Un tetto al numero di etichette per documento: venti sono già molte, e
  -- oltre quella soglia le etichette smettono di aiutare a ritrovare qualcosa.
  select count(*) into v_count from public.document_tag_links l where l.document_id = new.document_id;
  if v_count >= 20 then
    raise exception 'too_many_tags'
      using errcode = '23514', hint = 'Un documento può avere al massimo venti etichette.';
  end if;

  new.created_by := auth.uid();
  return new;
end $$;

drop trigger if exists trg_tag_link_guard on public.document_tag_links;
create trigger trg_tag_link_guard
  before insert on public.document_tag_links
  for each row execute function public.document_tag_link_guard();

create or replace function public.document_tag_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.name := btrim(new.name);
  if tg_op = 'INSERT' then new.created_by := auth.uid(); end if;
  return new;
end $$;

drop trigger if exists trg_document_tag_guard on public.document_tags;
create trigger trg_document_tag_guard
  before insert or update on public.document_tags
  for each row execute function public.document_tag_guard();

-- ---------------------------------------------------------------------------
-- 11. La lista: ricerca, filtri, ordinamento e paginazione nel database
--
-- Perché una funzione e non query dal client: una riga della lista mette
-- insieme il documento, l'ultima analisi, le correzioni umane, le etichette,
-- le attività collegate e le comunicazioni di provenienza. Fatto dal browser
-- sarebbe una query per documento per relazione — venticinque righe, cento
-- interrogazioni — e per sapere quali venticinque righe mostrare bisognerebbe
-- averle scaricate tutte.
--
-- `security invoker` (il default): la RLS di ogni tabella continua ad
-- applicarsi riga per riga. Il filtro esplicito su `company_id` e il controllo
-- di appartenenza NON la sostituiscono, la accompagnano. Una funzione di
-- ricerca è il posto più facile del mondo per aggirare per sbaglio l'isolamento
-- fra aziende, e qui gli strati sono tre.
--
-- PAGINAZIONE A SCORRIMENTO (offset) e non a cursore, con motivazione: la
-- pagina mostra «venticinque di duecentodiciotto», la barra laterale mostra i
-- conteggi per categoria e l'ordinamento cambia con un menu. Un cursore
-- keyset — che nell'Inbox è la scelta giusta, perché lì si scorre una sola
-- lista sempre nello stesso ordine — qui impedirebbe di dire quanti sono e di
-- saltare avanti. L'ordinamento porta SEMPRE `id` come ultimo criterio: senza,
-- due documenti creati nello stesso istante si scambierebbero di posto fra una
-- pagina e l'altra, e uno dei due non comparirebbe mai.
-- ---------------------------------------------------------------------------
create or replace function public.list_documents(
  p_company_id      uuid,
  p_query           text default null,
  p_category        public.document_category default null,
  p_uncategorized   boolean default false,
  p_source          public.document_source_type default null,
  p_state           text default null,      -- to_verify | analyzed | failed | processing | none
  p_tag_ids         uuid[] default null,
  p_date_from       date default null,
  p_date_to         date default null,
  p_has_deadline    boolean default false,
  p_archived        boolean default false,
  p_sort            text default 'recent',  -- recent | oldest | document_date | title | deadline
  p_limit           integer default 25,
  p_offset          integer default 0,
  -- Un solo documento. Serve al DETTAGLIO, e non è una comodità: la riga della
  -- lista e la testata del dettaglio devono dire la stessa cosa sullo stesso
  -- documento — stessa analisi scelta, stesse correzioni applicate. Con due
  -- implementazioni diverse prima o poi divergono, e a divergere sarebbero
  -- proprio mittente e scadenza.
  p_document_id     uuid default null
)
returns table (
  id uuid,
  title text,
  original_filename text,
  mime_type text,
  file_size bigint,
  storage_path text,
  source_type public.document_source_type,
  status public.document_status,
  page_count integer,
  created_at timestamptz,
  archived_at timestamptz,
  category public.document_category,
  category_source public.document_category_source,
  analysis_id uuid,
  analysis_status public.analysis_status,
  last_attempt_failed boolean,
  error_code text,
  document_type text,
  document_type_corrected boolean,
  sender text,
  sender_corrected boolean,
  sender_authority_type text,
  document_date date,
  deadline date,
  deadline_corrected boolean,
  deadline_requires_verification boolean,
  amount numeric,
  amount_currency text,
  amount_corrected boolean,
  confidence text,
  tags jsonb,
  open_task_count bigint,
  task_count bigint,
  email_count bigint,
  snippet text,
  total_count bigint
)
language sql
stable
set search_path = ''
as $$
  with params as (
    select
      -- I caratteri jolly digitati da una persona devono cercare sé stessi:
      -- un `%` in una ricerca è un per cento, non «qualsiasi cosa».
      nullif(btrim(left(coalesce(p_query, ''), 120)), '') as q,
      replace(replace(replace(
        btrim(left(coalesce(p_query, ''), 120)), '\', '\\'), '%', '\%'), '_', '\_') as q_like
  ),
  base as (
    select
      d.*,
      -- L'ULTIMO tentativo: dice lo STATO, anche quando è un fallimento.
      last_try.id            as try_id,
      last_try.analysis_status as try_status,
      last_try.error_code    as try_error,
      -- L'ultima analisi VALIDA: dice il CONTENUTO. Se l'ultimo tentativo è
      -- fallito ma prima esisteva un risultato buono, quel risultato non
      -- scompare — è la stessa regola di `analysisService.getForDocument`,
      -- e averne due diverse farebbe dire due cose alla stessa schermata.
      good.id                as good_id,
      good.document_type     as a_document_type,
      good.sender            as a_sender,
      good.sender_authority_type as a_authority,
      good.document_date     as a_document_date,
      good.deadline          as a_deadline,
      good.deadline_requires_verification as a_deadline_verify,
      good.amount            as a_amount,
      good.amount_currency   as a_currency,
      good.confidence        as a_confidence,
      corr.v                 as corrections,
      count(*) over ()       as n_total
    from public.documents d
    left join lateral (
      select a.id, a.analysis_status, a.error_code
      from public.document_analyses a
      -- Il confronto sull'azienda accompagna la RLS, non la sostituisce: è la
      -- disciplina di questo progetto, e qui evita anche che un'analisi
      -- agganciata per errore a un documento altrui possa mai essere letta.
      where a.document_id = d.id and a.company_id = d.company_id
      order by a.created_at desc, a.id desc
      limit 1
    ) last_try on true
    left join lateral (
      select a.*
      from public.document_analyses a
      where a.document_id = d.id and a.company_id = d.company_id
        and a.analysis_status <> 'failed'
      order by a.created_at desc, a.id desc
      limit 1
    ) good on true
    left join lateral (
      -- Un solo passaggio sulle correzioni del documento: le più recenti
      -- sovrascrivono le precedenti perché `jsonb_object_agg` tiene l'ultimo
      -- valore di ogni chiave.
      select jsonb_object_agg(c.field, c.corrected_value) as v
      from (
        select c2.field, c2.corrected_value
        from public.analysis_corrections c2
        where c2.document_id = d.id and c2.company_id = d.company_id
        order by c2.corrected_at asc
      ) c
    ) corr on true
    where d.company_id = p_company_id
      -- Sottointerrogazione scalare: l'appartenenza si verifica UNA volta per
      -- interrogazione e non una volta per riga.
      and (select public.is_company_member(p_company_id))
      and (p_document_id is null or d.id = p_document_id)
      -- Chiedendo UN documento non si applica il filtro di archiviazione: il suo
      -- indirizzo deve funzionare anche dopo che è stato archiviato, altrimenti
      -- «archivia» diventerebbe indistinguibile da «fai sparire».
      and (p_document_id is not null
           or (case when p_archived then d.archived_at is not null else d.archived_at is null end))
      and (p_category is null or d.category = p_category)
      and (not p_uncategorized or d.category is null)
      and (p_source is null or d.source_type = p_source)
      and (p_tag_ids is null or array_length(p_tag_ids, 1) is null or exists (
            select 1 from public.document_tag_links l
            where l.document_id = d.id and l.company_id = d.company_id
              and l.tag_id = any (p_tag_ids)
          ))
      and (not p_has_deadline or coalesce(
            public.try_date(corr.v ->> 'deadline'), good.deadline) is not null)
      and (p_date_from is null or coalesce(
            public.try_date(corr.v ->> 'document_date'), good.document_date,
            d.created_at::date) >= p_date_from)
      and (p_date_to is null or coalesce(
            public.try_date(corr.v ->> 'document_date'), good.document_date,
            d.created_at::date) <= p_date_to)
      and (
        p_state is null
        or (p_state = 'failed'     and last_try.analysis_status = 'failed')
        or (p_state = 'to_verify'  and last_try.analysis_status = 'needs_review')
        or (p_state = 'analyzed'   and last_try.analysis_status = 'completed')
        -- «In elaborazione» è uno stato del DOCUMENTO, non dell'analisi: fra il
        -- caricamento e la prima riga di analisi non esiste ancora nulla da
        -- interrogare, ed è proprio il momento in cui una persona si chiede
        -- dove sia finito il suo file.
        or (p_state = 'processing' and d.status in ('extracting', 'analyzing', 'processing'))
        or (p_state = 'none'       and last_try.id is null
              and d.status not in ('extracting', 'analyzing', 'processing'))
      )
      and (
        (select q from params) is null
        or d.title ilike '%' || (select q_like from params) || '%'
        or coalesce(d.original_filename, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.sender, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.subject, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.recipient, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.document_type, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.reference_numbers::text, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(corr.v::text, '') ilike '%' || (select q_like from params) || '%'
        or exists (
             select 1 from public.document_tag_links l
             join public.document_tags g on g.id = l.tag_id and g.company_id = l.company_id
             where l.document_id = d.id and l.company_id = d.company_id
               and g.name ilike '%' || (select q_like from params) || '%'
           )
        or exists (
             select 1 from public.document_extractions e
             where e.document_id = d.id and e.company_id = d.company_id
               and e.search_tsv @@ plainto_tsquery('simple'::regconfig, (select q from params))
           )
      )
    order by
      case when p_sort = 'oldest' then d.created_at end asc nulls last,
      case when p_sort = 'title' then lower(d.title) end asc nulls last,
      case when p_sort = 'document_date'
           then coalesce(public.try_date(corr.v ->> 'document_date'), good.document_date) end desc nulls last,
      case when p_sort = 'deadline'
           then coalesce(public.try_date(corr.v ->> 'deadline'), good.deadline) end asc nulls last,
      case when p_sort in ('oldest', 'title', 'document_date', 'deadline')
           then null else d.created_at end desc nulls last,
      -- Ultimo criterio SEMPRE presente: senza, due righe uguali possono
      -- scambiarsi di posto fra una pagina e l'altra.
      d.id desc
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    offset greatest(0, coalesce(p_offset, 0))
  )
  select
    b.id, b.title, b.original_filename, b.mime_type, b.file_size, b.storage_path,
    b.source_type, b.status, b.page_count, b.created_at, b.archived_at,
    b.category, b.category_source,
    coalesce(b.good_id, b.try_id) as analysis_id,
    b.try_status as analysis_status,
    -- `coalesce` fino in fondo: senza analisi queste espressioni valgono NULL, e
    -- un NULL che arriva al posto di un «no» diventa, nel browser, un «forse».
    coalesce(b.try_status = 'failed' and b.good_id is not null, false) as last_attempt_failed,
    b.try_error as error_code,
    -- Valore EFFETTIVO: la correzione umana se c'è, altrimenti il dato
    -- dell'analisi. Il valore originale dell'AI non viene toccato e resta
    -- leggibile nel dettaglio: qui si mostra ciò che l'azienda ritiene vero.
    coalesce(b.corrections ->> 'document_type', b.a_document_type) as document_type,
    coalesce(b.corrections ? 'document_type', false) as document_type_corrected,
    coalesce(b.corrections ->> 'sender', b.a_sender) as sender,
    coalesce(b.corrections ? 'sender', false) as sender_corrected,
    b.a_authority as sender_authority_type,
    coalesce(public.try_date(b.corrections ->> 'document_date'), b.a_document_date) as document_date,
    coalesce(public.try_date(b.corrections ->> 'deadline'), b.a_deadline) as deadline,
    coalesce(b.corrections ? 'deadline', false) as deadline_corrected,
    coalesce(b.a_deadline_verify, false) as deadline_requires_verification,
    coalesce(public.try_numeric(b.corrections ->> 'amount'), b.a_amount) as amount,
    b.a_currency as amount_currency,
    coalesce(b.corrections ? 'amount', false) as amount_corrected,
    b.a_confidence as confidence,
    coalesce(tg.v, '[]'::jsonb) as tags,
    coalesce(tk.open_count, 0) as open_task_count,
    coalesce(tk.all_count, 0) as task_count,
    coalesce(em.n, 0) as email_count,
    -- L'estratto si calcola SOLO sulle righe che si mostrano davvero, ed è
    -- testo semplice: i due delimitatori li interpreta React costruendo
    -- elementi, non inserendo HTML. Nel Document Hub non esiste markup
    -- proveniente da un documento.
    case
      when (select q from params) is null then null
      else (
        -- I delimitatori sono fra virgolette perché l'elenco delle opzioni è
        -- separato da virgole: un valore non quotato che contiene caratteri
        -- speciali verrebbe interpretato male.
        select ts_headline('simple'::regconfig, left(coalesce(e.full_text, ''), 500000),
                 plainto_tsquery('simple'::regconfig, (select q from params)),
                 'StartSel="[[", StopSel="]]", MaxWords=22, MinWords=8, MaxFragments=1')
        from public.document_extractions e
        where e.document_id = b.id and e.company_id = b.company_id
          and e.search_tsv @@ plainto_tsquery('simple'::regconfig, (select q from params))
        limit 1
      )
    end as snippet,
    b.n_total as total_count
  from base b
  left join lateral (
    select jsonb_agg(jsonb_build_object('id', g.id, 'name', g.name) order by g.name) as v
    from public.document_tag_links l
    join public.document_tags g on g.id = l.tag_id and g.company_id = l.company_id
    where l.document_id = b.id and l.company_id = b.company_id
  ) tg on true
  left join lateral (
    select
      count(*) filter (where t.status <> 'completed' and t.archived_at is null) as open_count,
      count(*) as all_count
    from public.tasks t where t.document_id = b.id and t.company_id = b.company_id
  ) tk on true
  left join lateral (
    select count(*) as n
    from public.email_message_documents m
    where m.document_id = b.id and m.company_id = b.company_id
  ) em on true
  -- Lo stesso ordine della selezione, espressione per espressione. Ordinare
  -- l'esterno in modo diverso dall'interno vorrebbe dire scegliere venticinque
  -- righe secondo un criterio e mostrarle secondo un altro: la pagina due non
  -- verrebbe dopo la pagina uno.
  order by
    case when p_sort = 'oldest' then b.created_at end asc nulls last,
    case when p_sort = 'title' then lower(b.title) end asc nulls last,
    case when p_sort = 'document_date'
         then coalesce(public.try_date(b.corrections ->> 'document_date'), b.a_document_date) end desc nulls last,
    case when p_sort = 'deadline'
         then coalesce(public.try_date(b.corrections ->> 'deadline'), b.a_deadline) end asc nulls last,
    case when p_sort in ('oldest', 'title', 'document_date', 'deadline')
         then null else b.created_at end desc nulls last,
    b.id desc;
$$;

revoke all on function public.list_documents(uuid, text, public.document_category, boolean, public.document_source_type, text, uuid[], date, date, boolean, boolean, text, integer, integer, uuid) from public, anon;
grant execute on function public.list_documents(uuid, text, public.document_category, boolean, public.document_source_type, text, uuid[], date, date, boolean, boolean, text, integer, integer, uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 12. Conteggi per categoria
--
-- Una aggregazione sola invece di dodici interrogazioni. I conteggi seguono lo
-- stesso filtro di archiviazione della lista: mostrare «Imposte 18» accanto a
-- una lista che ne contiene 12 perché sei sono archiviate sarebbe un numero
-- che non corrisponde a niente di visibile.
-- ---------------------------------------------------------------------------
create or replace function public.document_category_counts(
  p_company_id uuid,
  p_archived   boolean default false
)
returns table (category public.document_category, n bigint)
language sql
stable
set search_path = ''
as $$
  select d.category, count(*)
  from public.documents d
  where d.company_id = p_company_id
    and (select public.is_company_member(p_company_id))
    and (case when p_archived then d.archived_at is not null else d.archived_at is null end)
  group by d.category;
$$;

revoke all on function public.document_category_counts(uuid, boolean) from public, anon;
grant execute on function public.document_category_counts(uuid, boolean) to authenticated;

-- ---------------------------------------------------------------------------
-- 13. Azioni di gruppo: tutte o nessuna
--
-- ⚠️ Un'azione su più documenti che ne trova uno di un'altra azienda NON deve
-- fare metà lavoro. La RLS impedirebbe comunque di toccare il documento altrui,
-- ma il risultato sarebbe «fatto» su quattro righe su cinque, senza che nessuno
-- sappia quale è rimasta indietro. Qui il conteggio viene confrontato PRIMA di
-- scrivere: se non torna, non si scrive niente e si dice perché.
--
-- `security invoker`: la RLS resta in vigore, quindi il conteggio vede solo i
-- documenti che il chiamante può davvero vedere.
-- ---------------------------------------------------------------------------
create or replace function public.documents_assert_all_mine(p_company_id uuid, p_ids uuid[])
returns void
language plpgsql
set search_path = ''
as $$
declare
  v_found integer;
  v_asked integer := coalesce(array_length(p_ids, 1), 0);
begin
  if v_asked = 0 then
    raise exception 'no_documents_selected'
      using errcode = '23514', hint = 'Nessun documento selezionato.';
  end if;
  if v_asked > 200 then
    raise exception 'too_many_documents'
      using errcode = '23514', hint = 'Al massimo duecento documenti per volta.';
  end if;
  if not public.is_company_member(p_company_id) then
    raise exception 'not_a_member' using errcode = '42501';
  end if;

  select count(*) into v_found
  from public.documents d
  where d.id = any (p_ids) and d.company_id = p_company_id;

  if v_found <> v_asked then
    raise exception 'documents_not_all_visible'
      using errcode = '42501',
            hint = 'Alcuni documenti selezionati non appartengono a questa azienda.';
  end if;
end $$;

create or replace function public.documents_bulk_set_category(
  p_company_id uuid,
  p_ids        uuid[],
  p_category   public.document_category
)
returns integer
language plpgsql
set search_path = ''
as $$
declare v_n integer;
begin
  perform public.documents_assert_all_mine(p_company_id, p_ids);
  update public.documents set category = p_category
   where id = any (p_ids) and company_id = p_company_id;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

create or replace function public.documents_bulk_archive(
  p_company_id uuid,
  p_ids        uuid[],
  p_archived   boolean
)
returns integer
language plpgsql
set search_path = ''
as $$
declare v_n integer;
begin
  perform public.documents_assert_all_mine(p_company_id, p_ids);
  update public.documents
     set archived_at = case when p_archived then now() else null end
   where id = any (p_ids) and company_id = p_company_id;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

create or replace function public.documents_bulk_add_tag(
  p_company_id uuid,
  p_ids        uuid[],
  p_tag_id     uuid
)
returns integer
language plpgsql
set search_path = ''
as $$
declare v_n integer;
begin
  perform public.documents_assert_all_mine(p_company_id, p_ids);
  insert into public.document_tag_links (company_id, document_id, tag_id)
  select p_company_id, x, p_tag_id from unnest(p_ids) as x
  on conflict (document_id, tag_id) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

revoke all on function public.documents_assert_all_mine(uuid, uuid[]) from public, anon;
revoke all on function public.documents_bulk_set_category(uuid, uuid[], public.document_category) from public, anon;
revoke all on function public.documents_bulk_archive(uuid, uuid[], boolean) from public, anon;
revoke all on function public.documents_bulk_add_tag(uuid, uuid[], uuid) from public, anon;
grant execute on function public.documents_assert_all_mine(uuid, uuid[]) to authenticated;
grant execute on function public.documents_bulk_set_category(uuid, uuid[], public.document_category) to authenticated;
grant execute on function public.documents_bulk_archive(uuid, uuid[], boolean) to authenticated;
grant execute on function public.documents_bulk_add_tag(uuid, uuid[], uuid) to authenticated;

-- ---------------------------------------------------------------------------
-- 14. RLS e permessi
--
-- ⚠️ `revoke all` PRIMA dei grant sulle tabelle nuove. Su Supabase una tabella
-- di `public` nasce con i permessi di tabella completi per `anon` e
-- `authenticated`, quindi un grant scritto dopo AGGIUNGE privilegi invece di
-- restringerli: è la lezione della 0014, dove i permessi di colonna della 0013
-- non restringevano nulla.
-- ---------------------------------------------------------------------------
alter table public.document_tags       enable row level security;
alter table public.document_tag_links  enable row level security;

revoke all on public.document_tags      from anon, authenticated, public;
revoke all on public.document_tag_links from anon, authenticated, public;

grant select, insert, update, delete on public.document_tags to authenticated;
grant select, insert, delete on public.document_tag_links to authenticated;

drop policy if exists document_tags_select on public.document_tags;
create policy document_tags_select on public.document_tags
  for select to authenticated using (public.is_company_member(company_id));
drop policy if exists document_tags_insert on public.document_tags;
create policy document_tags_insert on public.document_tags
  for insert to authenticated with check (public.is_company_member(company_id));
drop policy if exists document_tags_update on public.document_tags;
create policy document_tags_update on public.document_tags
  for update to authenticated using (public.is_company_member(company_id))
  with check (public.is_company_member(company_id));
-- Cancellare un'etichetta la toglie da tutti i documenti (cascade sui
-- collegamenti): è una modifica che riguarda l'intera azienda, quindi resta a
-- chi la amministra.
drop policy if exists document_tags_delete on public.document_tags;
create policy document_tags_delete on public.document_tags
  for delete to authenticated using (public.is_company_admin(company_id));

drop policy if exists document_tag_links_select on public.document_tag_links;
create policy document_tag_links_select on public.document_tag_links
  for select to authenticated using (public.is_company_member(company_id));
drop policy if exists document_tag_links_insert on public.document_tag_links;
create policy document_tag_links_insert on public.document_tag_links
  for insert to authenticated with check (public.is_company_member(company_id));
drop policy if exists document_tag_links_delete on public.document_tag_links;
create policy document_tag_links_delete on public.document_tag_links
  for delete to authenticated using (public.is_company_member(company_id));

-- ---------------------------------------------------------------------------
-- 15. Cancellazione definitiva: chi può
--
-- Fino alla 0016 qualunque membro poteva cancellare qualunque documento
-- dell'azienda, e la cancellazione era l'unico modo di togliere qualcosa dalla
-- lista. Ora togliere si fa ARCHIVIANDO — che non perde niente — e la
-- cancellazione definitiva diventa rara e distruttiva: porta via con sé
-- analisi, estrazioni, correzioni, collegamenti alle email e alle attività.
--
-- La regola: la amministra chi amministra l'azienda (owner o admin). Un membro
-- può cancellare soltanto ciò che ha caricato lui — che comprende il caso in
-- cui l'upload del file fallisce e il servizio deve rimuovere il record appena
-- creato. I documenti arrivati dalla posta hanno `uploaded_by` nullo, quindi
-- restano cancellabili solo da un amministratore.
-- ---------------------------------------------------------------------------
drop policy if exists documents_delete_member on public.documents;
drop policy if exists documents_delete_admin_or_owner on public.documents;
create policy documents_delete_admin_or_owner on public.documents
  for delete to authenticated
  using (
    public.is_company_admin(company_id)
    or (public.is_company_member(company_id) and uploaded_by = auth.uid())
  );

comment on policy documents_delete_admin_or_owner on public.documents is
  'La cancellazione definitiva è degli amministratori; un membro può cancellare solo '
  'i documenti che ha caricato. Per togliere un documento dalle viste si archivia.';

-- ---------------------------------------------------------------------------
-- 16. Classificazione dei documenti già presenti
--
-- Derivazione UNA TANTUM: i documenti che hanno già un'analisi ricevono la
-- categoria che la regola sa dedurre, con origine «rule». Quelli su cui la
-- regola non decide restano senza categoria e compaiono fra i documenti da
-- classificare. Nessuna categoria viene inventata per riempire un vuoto.
--
-- ⚠️ L'aggiornamento passa dal trigger `documents_guard`. Qui `auth.uid()` è
-- nullo — la migrazione la esegue chi amministra il database, non un utente —
-- quindi il guardiano riconosce una scrittura di sistema e registra l'origine
-- «rule» invece di attribuire la classificazione a una persona. Se non fosse
-- così, duecento documenti risulterebbero classificati a mano da nessuno.
-- ---------------------------------------------------------------------------
do $$
declare
  v_touched integer;
begin
  with latest as (
    select distinct on (a.document_id)
      a.document_id, a.document_type, a.sender_authority_type
    from public.document_analyses a
    where a.analysis_status <> 'failed'
    order by a.document_id, a.created_at desc, a.id desc
  ),
  guessed as (
    select l.document_id,
           public.document_category_from_analysis(l.document_type, l.sender_authority_type) as cat
    from latest l
  )
  update public.documents d
     set category = g.cat
    from guessed g
   where d.id = g.document_id
     and g.cat is not null
     and d.category is null;
  get diagnostics v_touched = row_count;
  raise notice 'Documenti classificati dalla regola: %', v_touched;
end $$;

-- ---------------------------------------------------------------------------
-- 17. Autoverifica: la migrazione controlla di aver ottenuto ciò che dichiara.
--
-- Non è un ornamento. La 0013 dichiarava nei commenti una garanzia che non
-- esisteva, e lo si è scoperto solo eseguendo i test sul database vero: da
-- allora ogni migrazione che promette qualcosa la verifica prima di dirsi
-- riuscita.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
  v_cat public.document_category;
begin
  -- (a) Le tabelle nuove non devono essere scrivibili oltre quanto concesso.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name = 'document_tag_links'
    and grantee in ('anon', 'authenticated', 'public')
    and privilege_type = 'UPDATE';
  if v_bad is not null then
    raise exception 'i collegamenti delle etichette risultano modificabili: %', v_bad;
  end if;

  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name in ('document_tags', 'document_tag_links')
    and grantee = 'anon';
  if v_bad is not null then
    raise exception 'le etichette risultano accessibili senza autenticazione: %', v_bad;
  end if;

  -- (b) La regola di classificazione fa quello che dice, sui casi che contano.
  v_cat := public.document_category_from_analysis('tax_document', 'federal');
  if v_cat is distinct from 'taxes' then
    raise exception 'la regola non classifica un documento fiscale fra le imposte (ha detto %)', v_cat;
  end if;
  v_cat := public.document_category_from_analysis('reminder', 'private');
  if v_cat is distinct from 'invoices' then
    raise exception 'la regola non classifica un sollecito privato fra le fatture (ha detto %)', v_cat;
  end if;
  v_cat := public.document_category_from_analysis('information', 'unknown');
  if v_cat is not null then
    raise exception 'la regola inventa una categoria dove non ha elementi (ha detto %)', v_cat;
  end if;

  -- (c) Le conversioni difensive non devono sollevare su un valore sbagliato.
  if public.try_date('non è una data') is not null then
    raise exception 'try_date non torna NULL su un testo non convertibile';
  end if;
  if public.try_numeric('12,50 CHF') is not null then
    raise exception 'try_numeric non torna NULL su un testo non convertibile';
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0018_calendar_notifications  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0018 CALENDARIO E NOTIFICHE
--
-- Il Work Hub sa CHE COSA c'è da fare. Questa migrazione aggiunge QUANDO lo si
-- vede nel tempo e CHE COSA non si può permettere di dimenticare.
--
-- IL PRINCIPIO, E CIÒ CHE NE DERIVA PER LO SCHEMA
-- La fonte di verità del lavoro resta `tasks`. Il calendario è una PROIEZIONE:
-- qui non esiste nessuna tabella che contenga titolo, scadenza o stato di
-- un'attività. `calendar_event_links` contiene solo la CORRISPONDENZA fra una
-- task e l'evento che la rappresenta presso un provider — un identificativo e
-- un'impronta, non una copia. Se domani qualcuno volesse leggere «quali
-- scadenze ha l'azienda» da queste tabelle non ci riuscirebbe, ed è voluto:
-- due posti in cui vive una scadenza sono due scadenze che possono divergere.
--
-- LE GARANZIE CHE STANNO QUI E NON NEL BROWSER
--   1. I TOKEN del calendario sono irraggiungibili dal client: nessun GRANT e
--      nessuna policy su `calendar_connection_secrets`, esattamente come per la
--      posta (0013).
--   2. UNA NOTIFICA È PERSONALE. La RLS filtra per `user_id = auth.uid()`, non
--      per azienda: due colleghi della stessa azienda non si leggono le
--      notifiche a vicenda.
--   3. LE PREFERENZE SONO PERSONALI E LE SCRIVE SOLO IL LORO PROPRIETARIO. Un
--      amministratore non può accendere le email a un collega: il consenso a
--      essere contattati non è delegabile, e qui non lo è tecnicamente.
--   4. NESSUNO SI FABBRICA UNA NOTIFICA. Il client non ha alcun permesso di
--      scrittura su `notifications`: le creano i trigger e il worker. «Segna
--      come letta» passa da una funzione, non da un update.
--   5. LA CODA DI SINCRONIZZAZIONE È DEL SERVER. Il client non la vede e non la
--      scrive: la riempiono i trigger su `tasks`, la svuota una Edge Function.
--   6. L'IDEMPOTENZA È UN VINCOLO, NON UNA CONDIZIONE NEL CODICE.
--      `unique (connection_id, task_id)` su `calendar_event_links` e
--      `unique (task_id)` su `calendar_sync_queue`: un worker eseguito due
--      volte non può creare due eventi, qualunque cosa faccia il codice.
--
-- ⚠️ VINCOLO SUI VALORI ENUM (lezione della 0015, sorvegliata da `db:bundle`)
-- Tutti gli enum di questo file nascono con `create type … as enum (…)`, quindi
-- sono utilizzabili subito. NESSUN `alter type … add value` compare qui: un
-- valore aggiunto non sarebbe usabile nella stessa transazione, e `full-setup.sql`
-- concatena le migrazioni in una transazione sola.
--
-- ⚠️ REVOKE PRIMA DEI GRANT (lezione della 0014)
-- Su Supabase ogni tabella nuova di `public` nasce con i permessi di TABELLA
-- completi per `anon` e `authenticated`. Un grant scritto dopo AGGIUNGE
-- privilegi: non ne toglie. Ogni tabella qui sotto passa da `revoke all`.
--
-- Questa migrazione è RIESEGUIBILE.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Enum
-- ---------------------------------------------------------------------------

-- Provider di calendario. Enum PROPRIO e non riuso di `email_provider`: sono
-- due domini diversi che oggi hanno gli stessi due valori per coincidenza.
-- Legarli significherebbe che aggiungere CalDAV al calendario aggiunge CalDAV
-- anche alla posta.
do $$ begin create type public.calendar_provider as enum ('google', 'microsoft');
exception when duplicate_object then null; end $$;

do $$ begin create type public.calendar_connection_status as enum
  ('active', 'reauth_required', 'error', 'disconnected');
exception when duplicate_object then null; end $$;

-- Stato della corrispondenza fra una task e il suo evento presso il provider.
-- `pending` = la task è cambiata e l'evento non è ancora allineato; è uno stato
-- normale, non un guasto.
do $$ begin create type public.calendar_link_status as enum ('pending', 'synced', 'failed');
exception when duplicate_object then null; end $$;

-- I tipi di notifica della versione 1. Sette, non cinquanta: ognuno corrisponde
-- a una frase che una persona può leggere e a un'azione che può compiere.
do $$ begin create type public.notification_type as enum (
  'task_assigned',
  'task_due_soon',
  'task_due_today',
  'task_overdue',
  'unassigned_task_due_soon',
  'calendar_sync_failed',
  'calendar_reauth_required'
);
exception when duplicate_object then null; end $$;

-- Canali di CONSEGNA. L'in-app non compare: l'in-app È la notifica, la riga di
-- `notifications`. Elencarlo come canale creerebbe una consegna che non ha
-- niente da consegnare.
do $$ begin create type public.notification_channel as enum ('email');
exception when duplicate_object then null; end $$;

do $$ begin create type public.notification_delivery_status as enum
  ('pending', 'sending', 'sent', 'failed', 'cancelled');
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 2. notifications — il segnale
--
-- `payload` contiene SOLO ciò che serve a scrivere la frase: titolo
-- dell'attività, scadenza, priorità. Mai il corpo di un documento, mai il testo
-- di una email, mai un allegato, mai un prompt. La regola non è una convenzione
-- del codice: una notifica finisce in un'email, e un'email esce dal perimetro.
--
-- `dedupe_key` è NULLABILE, e l'unicità è un indice PARZIALE. Le due famiglie
-- di notifiche hanno bisogni opposti:
--   · quelle generate da un CRON (i promemoria) devono poter essere ritentate
--     senza duplicare: hanno una chiave, e l'unicità la impone il database;
--   · quelle generate da un EVENTO (una riassegnazione) non si ritentano mai —
--     il trigger scatta una volta per UPDATE — e due assegnazioni successive
--     sono due fatti distinti che meritano due notifiche.
-- Dare una chiave finta anche alle seconde avrebbe significato inventarla con
-- un timestamp, cioè scrivere un vincolo che non vincola niente.
-- ---------------------------------------------------------------------------
create table if not exists public.notifications (
  id           uuid primary key default gen_random_uuid(),
  company_id   uuid not null references public.companies (id) on delete cascade,
  -- Il DESTINATARIO. Una notifica appartiene a una persona, non a un'azienda:
  -- è la ragione per cui la RLS qui filtra su `user_id` e non su membership.
  user_id      uuid not null references auth.users (id) on delete cascade,
  type         public.notification_type not null,
  -- A che cosa si riferisce. Testo e non enum: `entity_type` non governa alcuna
  -- decisione di autorizzazione, serve solo a comporre il collegamento.
  entity_type  text not null check (entity_type in ('task', 'calendar_connection')),
  entity_id    uuid not null,
  payload      jsonb not null default '{}'::jsonb,
  dedupe_key   text,
  read_at      timestamptz,
  created_at   timestamptz not null default now()
);

-- L'idempotenza dei promemoria. Un job eseguito due volte non crea due righe.
create unique index if not exists uq_notifications_dedupe
  on public.notifications (user_id, dedupe_key) where dedupe_key is not null;
-- La lista della campanella: le mie, di questa azienda, dalla più recente.
create index if not exists idx_notifications_inbox
  on public.notifications (user_id, company_id, created_at desc);
-- Il conteggio del badge, che si fa a ogni caricamento di pagina.
create index if not exists idx_notifications_unread
  on public.notifications (user_id, company_id) where read_at is null;

comment on table public.notifications is
  'Notifiche PERSONALI. La RLS filtra per user_id: due colleghi della stessa azienda non si leggono le notifiche a vicenda. Il client non ha alcun permesso di scrittura.';
comment on column public.notifications.payload is
  'Solo metadati per comporre la frase (titolo, scadenza, priorità). MAI corpo di documenti o email: una notifica può uscire dal perimetro via email.';
comment on column public.notifications.dedupe_key is
  'Chiave di deduplicazione per le notifiche generate da un job periodico. NULL per quelle generate da un evento, che non si ritentano e non vanno deduplicate.';

-- ---------------------------------------------------------------------------
-- 3. notification_preferences — il consenso, per persona e per azienda
--
-- Chiave composta (company_id, user_id): la stessa persona può volere le email
-- per il mandato che segue da vicino e non per l'altro. È lo stesso principio
-- per cui una connessione di calendario è personale E aziendale.
--
-- Il default è dichiarato QUI e non nel codice applicativo: in-app acceso,
-- email SPENTA. L'email è un canale che esce dal prodotto e richiede una scelta
-- esplicita; accenderla per impostazione predefinita significherebbe decidere
-- al posto di qualcuno.
-- ---------------------------------------------------------------------------
create table if not exists public.notification_preferences (
  company_id            uuid not null references public.companies (id) on delete cascade,
  user_id               uuid not null references auth.users (id) on delete cascade,

  in_app_enabled        boolean not null default true,
  email_enabled         boolean not null default false,

  remind_7_days         boolean not null default true,
  remind_1_day          boolean not null default true,
  remind_due_day        boolean not null default true,
  remind_overdue        boolean not null default true,

  -- Fuso IANA. Il default è quello del mercato, ma è un DEFAULT e non una
  -- costante sparsa nel codice: chi lavora da altrove lo cambia qui, e tutto il
  -- motore dei promemoria lo legge da questa colonna.
  timezone              text not null default 'Europe/Zurich',

  -- La lingua in cui il SERVER scrive ciò che esce dal prodotto: la descrizione
  -- dell'evento sul calendario esterno e il testo delle email di promemoria.
  -- Non è una preferenza in più da compilare — la imposta l'interfaccia con la
  -- lingua in uso — ma deve stare nel database: un worker che gira alle 8 del
  -- mattino non ha una sessione da cui dedurla, e scrivere in italiano a un
  -- cliente germanofono perché «l'italiano è la lingua di riferimento» sarebbe
  -- un ripiego silenzioso.
  locale                text not null default 'it' check (locale in ('it', 'de', 'fr')),

  -- §96 — il titolo dell'attività nel calendario ESTERNO. Acceso: un evento che
  -- non dice cosa c'è da fare non serve a niente. Chi tiene il calendario
  -- condiviso con un assistente può spegnerlo, e l'evento diventa generico.
  show_task_title       boolean not null default true,

  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),

  primary key (company_id, user_id)
);

comment on table public.notification_preferences is
  'Preferenze PERSONALI per azienda. Solo il proprietario le scrive: un amministratore non può accendere le email a un collega, perché il consenso a essere contattati non è delegabile.';
comment on column public.notification_preferences.timezone is
  'Fuso orario IANA. I promemoria si generano al mattino LOCALE di questa zona, non a un''ora fissa UTC.';

-- ---------------------------------------------------------------------------
-- 4. notification_deliveries — la consegna, separata dal segnale
--
-- Perché due tabelle e non una colonna `email_sent`: una notifica È un fatto
-- avvenuto, una consegna è un tentativo che può fallire, essere ritentato e
-- fallire di nuovo. Metterli nella stessa riga significa o perdere la storia
-- dei tentativi o riscrivere il fatto ogni volta che il tentativo cambia stato.
--
-- Il vincolo unico (notification_id, channel) è l'idempotenza: un worker
-- eseguito tre volte non produce tre email.
-- ---------------------------------------------------------------------------
create table if not exists public.notification_deliveries (
  id                  uuid primary key default gen_random_uuid(),
  notification_id     uuid not null references public.notifications (id) on delete cascade,
  channel             public.notification_channel not null,
  status              public.notification_delivery_status not null default 'pending',
  attempts            integer not null default 0,
  next_attempt_at     timestamptz not null default now(),
  -- Identificativo restituito dal provider: è ciò che permette di rispondere a
  -- «questa email è davvero partita?» senza indovinare.
  provider_message_id text,
  error_code          text,
  sent_at             timestamptz,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  unique (notification_id, channel)
);
create index if not exists idx_deliveries_due
  on public.notification_deliveries (next_attempt_at)
  where status in ('pending', 'sending');

comment on table public.notification_deliveries is
  'Tentativi di consegna su un canale esterno. Separata da `notifications` perché un fatto avvenuto e un tentativo che può fallire sono cose diverse.';

-- ---------------------------------------------------------------------------
-- 5. calendar_connections — il calendario collegato, di UNA persona
--
-- ⚠️ La differenza più importante rispetto a `email_connections`: là la
-- connessione è dell'AZIENDA (una casella aziendale la collega un
-- amministratore e serve a tutti), qui è della PERSONA. Andrea collega il
-- proprio Google, Marco il proprio Outlook, e ognuno riceve sul proprio
-- calendario le attività di cui è responsabile. Da qui il vincolo unico su
-- (company_id, user_id, provider) e una RLS che filtra su `user_id`.
--
-- `provider_calendar_id` NON è un dettaglio recuperabile: con lo scope a
-- privilegio minimo di Google (`calendar.app.created`) l'applicazione NON può
-- elencare i calendari dell'utente — `calendarList.list` non è fra i metodi che
-- quello scope autorizza. L'unico modo di ritrovare il proprio calendario è
-- averne conservato l'identificativo. Se questa colonna si perdesse, il
-- calendario resterebbe nell'account dell'utente e AI-Swisse ne creerebbe un
-- secondo: è la ragione per cui non è una colonna «di comodo».
-- ---------------------------------------------------------------------------
create table if not exists public.calendar_connections (
  id                       uuid primary key default gen_random_uuid(),
  company_id               uuid not null references public.companies (id) on delete cascade,
  user_id                  uuid not null references auth.users (id) on delete cascade,
  provider                 public.calendar_provider not null,
  -- Identità STABILE dell'account presso il provider (Google `sub`, Microsoft
  -- `id`), non l'indirizzo: un indirizzo può essere un alias o cambiare.
  provider_account_id      text not null,
  email_address            text not null,

  -- Il calendario dedicato. NULL finché non è stato creato: uno stato legittimo
  -- fra il consenso e la prima sincronizzazione, non un dato mancante.
  provider_calendar_id     text,
  calendar_name            text,

  status                   public.calendar_connection_status not null default 'active',
  scopes                   text[] not null default '{}',
  sync_enabled             boolean not null default true,

  initial_sync_completed_at timestamptz,
  last_sync_at             timestamptz,
  last_successful_sync_at  timestamptz,
  last_error_code          text,
  last_error_at            timestamptz,

  -- Lock a SCADENZA, non booleano (stessa lezione della 0013): un processo
  -- morto non deve bloccare la sincronizzazione per sempre.
  sync_lease_id            uuid,
  sync_lease_until         timestamptz,

  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),

  unique (company_id, user_id, provider)
);
create index if not exists idx_cal_conn_user on public.calendar_connections (user_id, company_id);
create index if not exists idx_cal_conn_active on public.calendar_connections (company_id)
  where status = 'active' and sync_enabled;

comment on table public.calendar_connections is
  'Calendario esterno collegato da UNA persona per UNA azienda. I token non stanno qui: vedi calendar_connection_secrets.';
comment on column public.calendar_connections.provider_calendar_id is
  'Identificativo del calendario dedicato presso il provider. Con lo scope calendar.app.created di Google l''applicazione non può elencare i calendari: senza questo valore il calendario non è più ritrovabile e ne verrebbe creato un secondo.';

-- ---------------------------------------------------------------------------
-- 6. calendar_connection_secrets — token OAuth, SOLO server
--
-- Stesso modello di minaccia della 0013, e stessa conclusione: nessun GRANT,
-- nessuna policy, RLS attiva. Un `select('*')` scritto per errore in un service
-- non restituisce una riga vuota: fallisce con 42501.
-- I token sono cifrati con AES-256-GCM e la chiave vive in un secret della Edge
-- Function, non nel database. L'AAD è l'id della connessione: un ciphertext
-- copiato su un'altra riga non si decifra.
-- ---------------------------------------------------------------------------
create table if not exists public.calendar_connection_secrets (
  connection_id           uuid primary key references public.calendar_connections (id) on delete cascade,
  company_id              uuid not null references public.companies (id) on delete cascade,

  access_token_ct         bytea,
  access_token_iv         bytea,
  access_token_expires_at timestamptz,
  refresh_token_ct        bytea,
  refresh_token_iv        bytea,

  key_version             integer not null default 1,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now()
);

comment on table public.calendar_connection_secrets is
  'Token OAuth del calendario, cifrati. Nessuna policy e nessun GRANT: irraggiungibile dal ruolo authenticated. La chiave di cifratura è un secret della Edge Function.';

-- ---------------------------------------------------------------------------
-- 7. calendar_oauth_states — stato anti-CSRF, con TRIPLO legame
--
-- Rispetto alla 0013 c'è un legame in più che qui è indispensabile: l'UTENTE.
-- Una connessione di calendario è personale, quindi il callback deve sapere non
-- solo per quale azienda ma per quale PERSONA è stato dato il consenso — e non
-- può leggerlo dalla query string, che la decide chi chiama.
--
-- In tabella sta lo SHA-256 dello state, non lo state.
-- ---------------------------------------------------------------------------
create table if not exists public.calendar_oauth_states (
  id                uuid primary key default gen_random_uuid(),
  state_hash        text not null unique,
  company_id        uuid not null references public.companies (id) on delete cascade,
  user_id           uuid not null references auth.users (id) on delete cascade,
  provider          public.calendar_provider not null,
  code_verifier_ct  bytea,
  code_verifier_iv  bytea,
  key_version       integer not null default 1,
  redirect_path     text,
  created_at        timestamptz not null default now(),
  expires_at        timestamptz not null,
  consumed_at       timestamptz
);
create index if not exists idx_cal_oauth_states_expiry on public.calendar_oauth_states (expires_at);

-- ---------------------------------------------------------------------------
-- 8. calendar_event_links — la corrispondenza, non una copia
--
-- Contiene un identificativo e un'impronta. NON contiene il titolo, la scadenza
-- né la priorità: quelli stanno in `tasks` e da lì si leggono ogni volta.
--
-- `content_hash` è l'impronta di ciò che è stato scritto PRESSO IL PROVIDER
-- l'ultima volta. Serve a non riscrivere un evento identico a ogni giro della
-- riconciliazione: senza, un controllo periodico su cinquanta attività
-- diventerebbe cinquanta chiamate all'API ogni volta.
--
-- `unique (connection_id, task_id)` è l'idempotenza locale: la stessa attività
-- non può avere due eventi sullo stesso calendario, qualunque cosa faccia il
-- codice del worker.
-- ---------------------------------------------------------------------------
create table if not exists public.calendar_event_links (
  id                   uuid primary key default gen_random_uuid(),
  company_id           uuid not null references public.companies (id) on delete cascade,
  -- Ridondante rispetto alla connessione, ma la RLS deve poter filtrare per
  -- persona senza un join: la ridondanza qui è una scelta di sicurezza.
  user_id              uuid not null references auth.users (id) on delete cascade,
  connection_id        uuid not null references public.calendar_connections (id) on delete cascade,
  task_id              uuid not null references public.tasks (id) on delete cascade,

  provider_event_id    text not null,
  provider_calendar_id text not null,

  sync_status          public.calendar_link_status not null default 'pending',
  content_hash         text,
  last_synced_at       timestamptz,
  error_code           text,

  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),

  unique (connection_id, task_id)
);
create index if not exists idx_cal_links_task on public.calendar_event_links (task_id);
create index if not exists idx_cal_links_conn on public.calendar_event_links (connection_id, sync_status);

comment on table public.calendar_event_links is
  'Corrispondenza fra un''attività e l''evento che la rappresenta presso un provider. Contiene un identificativo e un''impronta, mai una copia del titolo o della scadenza.';

-- ---------------------------------------------------------------------------
-- 9. calendar_sync_queue — l'outbox
--
-- Perché una coda e non una chiamata dentro il salvataggio della task: se la
-- seconda metà di `await updateTask(); await googleUpdate();` fallisce, la task
-- è salvata e il calendario no, e nessuno lo sa. Con la coda la task è salvata
-- SEMPRE e la sincronizzazione è un lavoro che può essere ritentato.
--
-- `unique (task_id)` è la COALESCENZA: un'attività modificata otto volte in un
-- minuto non produce otto chiamate all'API. Non conta quante volte è cambiata,
-- conta com'è adesso.
-- ---------------------------------------------------------------------------
create table if not exists public.calendar_sync_queue (
  task_id         uuid primary key references public.tasks (id) on delete cascade,
  company_id      uuid not null references public.companies (id) on delete cascade,
  requested_at    timestamptz not null default now(),
  attempts        integer not null default 0,
  next_attempt_at timestamptz not null default now(),
  -- Lease a scadenza, come per le connessioni: un worker ucciso a metà non
  -- blocca la riga per sempre.
  locked_until    timestamptz,
  lock_id         uuid,
  last_error      text
);
create index if not exists idx_cal_queue_due on public.calendar_sync_queue (next_attempt_at)
  where locked_until is null;

comment on table public.calendar_sync_queue is
  'Outbox della sincronizzazione. Una riga per attività: chiave primaria su task_id, quindi otto modifiche rapide diventano una sola sincronizzazione.';

-- ---------------------------------------------------------------------------
-- 10. calendar_sync_runs — osservabilità
--
-- Serve a rispondere a «funziona?» con dei numeri invece che con un'impressione.
-- Non contiene titoli di attività né identificativi di evento: contiene conteggi.
-- ---------------------------------------------------------------------------
create table if not exists public.calendar_sync_runs (
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid references public.companies (id) on delete cascade,
  connection_id uuid references public.calendar_connections (id) on delete set null,
  provider      public.calendar_provider,
  trigger       text not null,
  status        text not null,
  upserted      integer not null default 0,
  deleted       integer not null default 0,
  failures      integer not null default 0,
  started_at    timestamptz not null default now(),
  completed_at  timestamptz,
  duration_ms   integer,
  error_code    text
);
create index if not exists idx_cal_runs_conn on public.calendar_sync_runs (connection_id, started_at desc);

-- ---------------------------------------------------------------------------
-- 11. Indice per il motore dei promemoria
--
-- Gli indici della 0016 iniziano tutti con `company_id`, perché servono alle
-- liste di UNA azienda. Il worker dei promemoria fa la domanda opposta — «quali
-- attività di CHIUNQUE scadono in questa finestra» — e su quegli indici non
-- potrebbe appoggiarsi. Non è un duplicato: cambia la colonna guida.
-- `assignee_user_id` è nell'indice e non nella condizione perché servono
-- entrambi i casi: il promemoria a chi è responsabile, e l'allarme su
-- un'attività urgente che responsabile non ne ha (§32).
-- ---------------------------------------------------------------------------
create index if not exists idx_tasks_due_global
  on public.tasks (due_date, assignee_user_id)
  where status <> 'completed' and archived_at is null and due_date is not null;

-- ---------------------------------------------------------------------------
-- 12. Il guardiano delle notifiche
--
-- Due cose che il database non può lasciar decidere a chi scrive:
--   · il destinatario dev'essere MEMBRO dell'azienda della notifica. Senza
--     questo controllo una notifica potrebbe raccontare a un estraneo il titolo
--     di un'attività altrui — che è esattamente il dato che il payload contiene;
--   · `read_at` non si sposta all'indietro. «L'ho già letta» è un fatto.
-- ---------------------------------------------------------------------------
create or replace function public.notifications_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.company_members m
    where m.company_id = new.company_id and m.user_id = new.user_id
  ) then
    raise exception 'notification_recipient_not_member'
      using errcode = '23514',
            hint = 'Il destinatario non appartiene a questa azienda.';
  end if;

  if tg_op = 'UPDATE' and old.read_at is not null then
    new.read_at := old.read_at;
  end if;

  return new;
end $$;

drop trigger if exists trg_notifications_guard on public.notifications;
create trigger trg_notifications_guard
  before insert or update on public.notifications
  for each row execute function public.notifications_guard();

-- ---------------------------------------------------------------------------
-- 13. Il guardiano delle preferenze
--
-- Il fuso orario si VALIDA, non si spera. Una stringa come «Europa/Zurigo»
-- passerebbe un check di formato e farebbe fallire ogni calcolo del worker con
-- un errore che nessuno collegherebbe a un campo di testo compilato mesi prima.
-- Qui il database prova a usarla: se non è un fuso IANA, la riga non entra.
--
-- L'identità la impone anche la policy, ma il trigger RIFIUTA invece di
-- correggere in silenzio: è la lezione di `comments_guard` (0016). La
-- condizione lascia passare il service role (`auth.uid()` nullo).
-- ---------------------------------------------------------------------------
create or replace function public.notification_preferences_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_probe timestamp;
begin
  if auth.uid() is not null and new.user_id is distinct from auth.uid() then
    raise exception 'preferences_not_own'
      using errcode = '42501',
            hint = 'Le preferenze di notifica le imposta solo il loro proprietario.';
  end if;

  if not exists (
    select 1 from public.company_members m
    where m.company_id = new.company_id and m.user_id = new.user_id
  ) then
    raise exception 'preferences_not_member'
      using errcode = '23514',
            hint = 'La persona non appartiene a questa azienda.';
  end if;

  begin
    v_probe := now() at time zone new.timezone;
  exception when others then
    raise exception 'invalid_timezone'
      using errcode = '23514',
            hint = 'Il fuso orario deve essere un identificativo IANA, per esempio Europe/Zurich.';
  end;

  return new;
end $$;

drop trigger if exists trg_notification_preferences_guard on public.notification_preferences;
create trigger trg_notification_preferences_guard
  before insert or update on public.notification_preferences
  for each row execute function public.notification_preferences_guard();

drop trigger if exists trg_notification_preferences_updated on public.notification_preferences;
create trigger trg_notification_preferences_updated
  before update on public.notification_preferences
  for each row execute function public.set_updated_at();

drop trigger if exists trg_deliveries_updated on public.notification_deliveries;
create trigger trg_deliveries_updated
  before update on public.notification_deliveries
  for each row execute function public.set_updated_at();

drop trigger if exists trg_cal_conn_updated on public.calendar_connections;
create trigger trg_cal_conn_updated
  before update on public.calendar_connections
  for each row execute function public.set_updated_at();

drop trigger if exists trg_cal_secrets_updated on public.calendar_connection_secrets;
create trigger trg_cal_secrets_updated
  before update on public.calendar_connection_secrets
  for each row execute function public.set_updated_at();

drop trigger if exists trg_cal_links_updated on public.calendar_event_links;
create trigger trg_cal_links_updated
  before update on public.calendar_event_links
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 14. Il guardiano dei collegamenti evento
--
-- Un collegamento deve appartenere all'azienda E alla persona della propria
-- connessione. Senza questo controllo, chi potesse scrivere qui potrebbe
-- agganciare l'evento di una task altrui alla propria connessione — e il worker,
-- che gira con il service role, lo scriverebbe sul proprio calendario.
-- È la stessa disciplina della 0017: una funzione che scavalca la RLS deve
-- difendersi da sola, non fidarsi di una policy scritta altrove.
-- ---------------------------------------------------------------------------
create or replace function public.calendar_links_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_conn record;
  v_task_company uuid;
begin
  select c.company_id, c.user_id into v_conn
  from public.calendar_connections c where c.id = new.connection_id;

  if v_conn.company_id is null
     or v_conn.company_id is distinct from new.company_id
     or v_conn.user_id is distinct from new.user_id then
    raise exception 'calendar_link_connection_mismatch'
      using errcode = '23514',
            hint = 'Il collegamento non appartiene alla connessione indicata.';
  end if;

  select t.company_id into v_task_company from public.tasks t where t.id = new.task_id;
  if v_task_company is null or v_task_company is distinct from new.company_id then
    raise exception 'calendar_link_task_mismatch'
      using errcode = '23514',
            hint = 'L''attività non appartiene a questa azienda.';
  end if;

  return new;
end $$;

drop trigger if exists trg_cal_links_guard on public.calendar_event_links;
create trigger trg_cal_links_guard
  before insert or update on public.calendar_event_links
  for each row execute function public.calendar_links_guard();

-- ---------------------------------------------------------------------------
-- 15. Il trigger che riempie la coda
--
-- Scatta sui soli campi che cambiano ciò che il calendario deve mostrare.
-- `description` non c'è: la descrizione dell'evento esterno non la contiene
-- (§95 — nel calendario finisce il minimo indispensabile), quindi modificarla
-- non richiede una chiamata all'API.
--
-- Non si accoda nulla per le aziende che non hanno alcun calendario collegato:
-- sarebbero righe che il worker prenderebbe solo per scoprire che non c'è
-- niente da fare. La condizione è una lettura di un indice parziale.
--
-- ⚠️ Il cambio di ASSEGNATARIO produce UNA sola riga, non due. La coda è
-- indicizzata per attività e il worker guarda TUTTI i collegamenti esistenti di
-- quella task più la connessione che dovrebbe averne uno: l'evento del vecchio
-- responsabile viene rimosso e quello del nuovo creato nello stesso passaggio.
-- Una coda per (task, utente) avrebbe richiesto di sapere già qui chi perde
-- l'evento, cioè di duplicare nel trigger la logica dello stato desiderato.
-- ---------------------------------------------------------------------------
create or replace function public.calendar_enqueue_task()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_relevant boolean;
begin
  if tg_op = 'INSERT' then
    v_relevant := true;
  else
    v_relevant :=
      new.title            is distinct from old.title
      or new.due_date      is distinct from old.due_date
      or new.assignee_user_id is distinct from old.assignee_user_id
      or new.status        is distinct from old.status
      or new.priority      is distinct from old.priority
      or (new.archived_at is not null) is distinct from (old.archived_at is not null);
  end if;

  if not v_relevant then return new; end if;

  if not exists (
    select 1 from public.calendar_connections c
    where c.company_id = new.company_id and c.status = 'active' and c.sync_enabled
  ) then
    return new;
  end if;

  insert into public.calendar_sync_queue (task_id, company_id, requested_at, attempts, next_attempt_at)
  values (new.id, new.company_id, now(), 0, now())
  on conflict (task_id) do update
    set requested_at    = now(),
        -- I tentativi ripartono da zero: il contenuto è cambiato, quindi il
        -- fallimento precedente riguardava una versione che non esiste più.
        attempts        = 0,
        next_attempt_at = now(),
        last_error      = null;

  return new;
end $$;

drop trigger if exists trg_tasks_calendar_enqueue on public.tasks;
create trigger trg_tasks_calendar_enqueue
  after insert or update on public.tasks
  for each row execute function public.calendar_enqueue_task();

-- ---------------------------------------------------------------------------
-- 16. Il trigger che avvisa chi riceve un'attività
--
-- Scatta solo quando il responsabile CAMBIA e diventa qualcuno. Non avvisa chi
-- si assegna un'attività da sé: sa già di averlo fatto, e una notifica per una
-- cosa che si è appena fatti da soli insegna a ignorare la campanella.
--
-- Il `payload` porta titolo e scadenza. Il collegamento lo compone la
-- schermata: mettere qui un URL significherebbe conservare un dominio che
-- domani potrebbe cambiare.
-- ---------------------------------------------------------------------------
create or replace function public.tasks_notify_assignment()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_prefs boolean;
begin
  if new.assignee_user_id is null then return new; end if;
  if tg_op = 'UPDATE' and new.assignee_user_id is not distinct from old.assignee_user_id then
    return new;
  end if;
  if auth.uid() is not null and auth.uid() = new.assignee_user_id then return new; end if;
  -- Un'attività già conclusa o archiviata non genera lavoro per nessuno.
  if new.status = 'completed' or new.archived_at is not null then return new; end if;

  -- Le preferenze possono non esistere: in quel caso valgono i default, e il
  -- default dell'in-app è ACCESO. `coalesce` su una riga assente, non su un
  -- valore nullo — sono due assenze diverse.
  select p.in_app_enabled into v_prefs
  from public.notification_preferences p
  where p.company_id = new.company_id and p.user_id = new.assignee_user_id;
  if v_prefs is not null and v_prefs = false then return new; end if;

  insert into public.notifications (company_id, user_id, type, entity_type, entity_id, payload)
  values (
    new.company_id, new.assignee_user_id, 'task_assigned', 'task', new.id,
    jsonb_build_object(
      'title', new.title,
      'dueDate', new.due_date,
      'priority', new.priority
    )
  );

  return new;
end $$;

drop trigger if exists trg_tasks_notify_assignment on public.tasks;
create trigger trg_tasks_notify_assignment
  after insert or update on public.tasks
  for each row execute function public.tasks_notify_assignment();

-- ---------------------------------------------------------------------------
-- 17. Il modello di lettura del calendario interno
--
-- Restituisce SOLO ciò che una griglia mensile mostra: niente checklist, niente
-- commenti, niente storico, niente analisi. Una vista mensile con quaranta
-- attività non deve scaricare quaranta analisi documentali per disegnare
-- quaranta righe di testo.
--
-- Le SCADUTE entrano sempre, anche quando cadono fuori dall'intervallo
-- richiesto: un'attività in ritardo non smette di esserlo perché si è girata
-- pagina al mese. È la stessa ragione per cui la Home mostra sempre le priorità
-- alte (§ dedup della 0016): nascondere un problema perché sta in un'altra
-- casella non è filtrare, è perderlo.
--
-- `security invoker` (il default): la RLS di `tasks` continua ad applicarsi.
-- Il filtro esplicito su `company_id` la accompagna, non la sostituisce.
-- ---------------------------------------------------------------------------
create or replace function public.calendar_tasks(
  p_company_id      uuid,
  p_from            date,
  p_to              date,
  p_mine            boolean default true,
  p_status          public.task_status default null,
  p_priority        public.task_priority default null,
  p_assignee        uuid default null,
  p_include_overdue boolean default true,
  p_limit           integer default 500
)
returns table (
  id uuid, title text, due_date date,
  priority public.task_priority, status public.task_status, source public.task_source,
  assignee_user_id uuid, assignee_name text, document_id uuid
)
language sql
stable
set search_path = ''
as $$
  select
    t.id, t.title, t.due_date, t.priority, t.status, t.source,
    t.assignee_user_id,
    nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), '') as assignee_name,
    t.document_id
  from public.tasks t
  left join public.profiles p on p.id = t.assignee_user_id
  where t.company_id = p_company_id
    and t.archived_at is null
    and t.due_date is not null
    and (
      (t.due_date >= p_from and t.due_date <= p_to)
      -- ⚠️ `<=` e non `<`. Il database vive in UTC, l'utente in Europe/Zurich:
      -- alle 00:30 locali di giovedì, per Postgres è ancora mercoledì, e
      -- un'attività scaduta mercoledì non rientrerebbe in `due_date < current_date`.
      -- Un giorno di margine costa una riga in più e chiude la finestra.
      -- Qui si SELEZIONA soltanto: che cosa sia «in ritardo» lo decide
      -- `isOverdue()` in `taskFormat`, la stessa funzione che usano Attività e
      -- Panoramica. Due definizioni di «scaduta» sono due schermate che prima o
      -- poi si contraddicono.
      or (coalesce(p_include_overdue, true)
          and t.status <> 'completed'
          and t.due_date <= current_date)
    )
    and (not coalesce(p_mine, false) or t.assignee_user_id = auth.uid())
    and (p_status   is null or t.status = p_status)
    and (p_priority is null or t.priority = p_priority)
    and (p_assignee is null or t.assignee_user_id = p_assignee)
  order by t.due_date asc, case t.priority when 'high' then 0 when 'medium' then 1 else 2 end, t.created_at desc
  limit greatest(1, least(coalesce(p_limit, 500), 1000));
$$;

revoke all on function public.calendar_tasks(uuid, date, date, boolean, public.task_status, public.task_priority, uuid, boolean, integer) from public, anon;
grant execute on function public.calendar_tasks(uuid, date, date, boolean, public.task_status, public.task_priority, uuid, boolean, integer) to authenticated;

-- Quante attività non hanno scadenza (§21). Si mostra il numero e si rimanda
-- ad Attività: non si inventa una data per farle stare in una casella.
create or replace function public.calendar_undated_count(
  p_company_id uuid,
  p_mine       boolean default true
)
returns integer
language sql
stable
set search_path = ''
as $$
  select count(*)::integer
  from public.tasks t
  where t.company_id = p_company_id
    and t.archived_at is null
    and t.due_date is null
    and t.status <> 'completed'
    and (not coalesce(p_mine, false) or t.assignee_user_id = auth.uid());
$$;

revoke all on function public.calendar_undated_count(uuid, boolean) from public, anon;
grant execute on function public.calendar_undated_count(uuid, boolean) to authenticated;

-- ---------------------------------------------------------------------------
-- 18. Notifiche: lettura e conteggio
--
-- «Segna come letta» passa da una funzione e non da un `update`: così il client
-- non ha alcun permesso di scrittura sulla tabella, e non esiste un percorso in
-- cui una notifica venga alterata in qualcosa di diverso da «letta».
-- `security invoker`: la RLS filtra già per utente. Il filtro su `auth.uid()`
-- scritto qui dentro la accompagna — un'ora spesa a scrivere due volte la stessa
-- condizione costa meno di un pomeriggio a capire perché non c'era.
-- ---------------------------------------------------------------------------
create or replace function public.notifications_mark_read(p_ids uuid[])
returns integer
language sql
volatile
set search_path = ''
as $$
  with updated as (
    update public.notifications n
       set read_at = now()
     where n.id = any(coalesce(p_ids, '{}'::uuid[]))
       and n.user_id = auth.uid()
       and n.read_at is null
    returning n.id
  )
  select count(*)::integer from updated;
$$;

create or replace function public.notifications_mark_all_read(p_company_id uuid)
returns integer
language sql
volatile
set search_path = ''
as $$
  with updated as (
    update public.notifications n
       set read_at = now()
     where n.company_id = p_company_id
       and n.user_id = auth.uid()
       and n.read_at is null
    returning n.id
  )
  select count(*)::integer from updated;
$$;

create or replace function public.notifications_unread_count(p_company_id uuid)
returns integer
language sql
stable
set search_path = ''
as $$
  select count(*)::integer
  from public.notifications n
  where n.company_id = p_company_id
    and n.user_id = auth.uid()
    and n.read_at is null;
$$;

revoke all on function public.notifications_mark_read(uuid[])     from public, anon;
revoke all on function public.notifications_mark_all_read(uuid)   from public, anon;
revoke all on function public.notifications_unread_count(uuid)    from public, anon;
grant execute on function public.notifications_mark_read(uuid[])   to authenticated;
grant execute on function public.notifications_mark_all_read(uuid) to authenticated;
grant execute on function public.notifications_unread_count(uuid)  to authenticated;

-- ---------------------------------------------------------------------------
-- 19. La coda: prenotazione atomica di un lotto
--
-- `for update skip locked` è ciò che permette a due esecuzioni sovrapposte del
-- worker di lavorare senza pestarsi i piedi e senza che una resti ferma ad
-- aspettare l'altra. Il `locked_until` sopravvive alla transazione: se
-- l'isolate viene ucciso a metà (i 150 secondi di Supabase), la riga si libera
-- da sola alla scadenza invece di restare presa per sempre.
--
-- `security definer` perché la tabella non ha alcun permesso per il client, e
-- l'esecuzione è concessa al solo `service_role`.
-- ---------------------------------------------------------------------------
create or replace function public.calendar_queue_claim(
  p_limit        integer default 20,
  p_lock_seconds integer default 120,
  -- Restringe la prenotazione a un insieme di attività. Serve al pulsante
  -- «Sincronizza ora»: senza, prenoterebbe le righe più VECCHIE della coda —
  -- che possono essere di chiunque — e il messaggio «N eventi aggiornati»
  -- conterebbe il lavoro di qualcun altro. NULL = tutta la coda, che è ciò che
  -- serve allo scheduler.
  p_task_ids     uuid[] default null
)
returns table (task_id uuid, company_id uuid, attempts integer, lock_id uuid)
language sql
security definer
set search_path = ''
as $$
  with candidati as (
    select q.task_id as tid
    from public.calendar_sync_queue q
    where q.next_attempt_at <= now()
      and (q.locked_until is null or q.locked_until < now())
      and (p_task_ids is null or q.task_id = any(p_task_ids))
    order by q.next_attempt_at asc
    limit greatest(1, least(coalesce(p_limit, 20), 100))
    for update skip locked
  ),
  aggiornati as (
    update public.calendar_sync_queue q
       set locked_until = now() + make_interval(secs => greatest(30, least(coalesce(p_lock_seconds, 120), 600))),
           -- Un lock per RIGA, non per lotto: chi rilascia una riga non può
           -- liberare per sbaglio quelle che un'altra esecuzione sta trattando.
           lock_id      = gen_random_uuid()
      from candidati c
     where q.task_id = c.tid
    returning q.task_id, q.company_id, q.attempts, q.lock_id
  )
  select a.task_id, a.company_id, a.attempts, a.lock_id from aggiornati a;
$$;

revoke all on function public.calendar_queue_claim(integer, integer, uuid[]) from public, anon, authenticated;
grant execute on function public.calendar_queue_claim(integer, integer, uuid[]) to service_role;

-- ---------------------------------------------------------------------------
-- 20. RLS
-- ---------------------------------------------------------------------------
alter table public.notifications                enable row level security;
alter table public.notification_preferences     enable row level security;
alter table public.notification_deliveries      enable row level security;
alter table public.calendar_connections         enable row level security;
alter table public.calendar_connection_secrets  enable row level security;
alter table public.calendar_oauth_states        enable row level security;
alter table public.calendar_event_links         enable row level security;
alter table public.calendar_sync_queue          enable row level security;
alter table public.calendar_sync_runs           enable row level security;

-- Prima si toglie TUTTO. `service_role` non compare: è il ruolo con cui
-- scrivono le Edge Function e deve conservare i propri permessi.
revoke all on public.notifications               from anon, authenticated, public;
revoke all on public.notification_preferences    from anon, authenticated, public;
revoke all on public.notification_deliveries     from anon, authenticated, public;
revoke all on public.calendar_connections        from anon, authenticated, public;
revoke all on public.calendar_connection_secrets from anon, authenticated, public;
revoke all on public.calendar_oauth_states       from anon, authenticated, public;
revoke all on public.calendar_event_links        from anon, authenticated, public;
revoke all on public.calendar_sync_queue         from anon, authenticated, public;
revoke all on public.calendar_sync_runs          from anon, authenticated, public;

-- NOTIFICHE — sola lettura. La marcatura passa dalle funzioni del punto 18.
grant select on public.notifications to authenticated;

drop policy if exists notifications_select_own on public.notifications;
create policy notifications_select_own on public.notifications
  for select to authenticated
  using (user_id = auth.uid() and public.is_company_member(company_id));
-- L'UPDATE esiste per far passare `read_at` scritto dalle funzioni, che girano
-- `security invoker`. Resta inutilizzabile dal client: non c'è alcun GRANT di
-- UPDATE sulla tabella, quindi la policy da sola non basta ad aprire nulla.
drop policy if exists notifications_update_own on public.notifications;
create policy notifications_update_own on public.notifications
  for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- PREFERENZE — lettura e scrittura delle PROPRIE. Nessun DELETE: cancellare le
-- preferenze significherebbe tornare ai default senza dirlo; si modificano.
grant select, insert, update on public.notification_preferences to authenticated;

drop policy if exists prefs_select_own on public.notification_preferences;
create policy prefs_select_own on public.notification_preferences
  for select to authenticated
  using (user_id = auth.uid() and public.is_company_member(company_id));
drop policy if exists prefs_insert_own on public.notification_preferences;
create policy prefs_insert_own on public.notification_preferences
  for insert to authenticated
  with check (user_id = auth.uid() and public.is_company_member(company_id));
drop policy if exists prefs_update_own on public.notification_preferences;
create policy prefs_update_own on public.notification_preferences
  for update to authenticated
  using (user_id = auth.uid() and public.is_company_member(company_id))
  with check (user_id = auth.uid() and public.is_company_member(company_id));

-- CONNESSIONI — solo le PROPRIE, e solo le colonne che una schermata mostra.
-- Un collega non vede la connessione di un altro: nulla nell'interfaccia ne ha
-- bisogno, e ciò che non serve non si espone (§85).
-- ⚠️ Da qui in avanti `select('*')` su questa tabella FALLISCE con «permission
-- denied for column»: è voluto, ed è il motivo per cui il service elenca le
-- colonne una per una.
grant select (
  id, company_id, user_id, provider, email_address, provider_calendar_id, calendar_name,
  status, scopes, sync_enabled, initial_sync_completed_at, last_sync_at,
  last_successful_sync_at, last_error_code, last_error_at, created_at, updated_at
) on public.calendar_connections to authenticated;

drop policy if exists cal_conn_select_own on public.calendar_connections;
create policy cal_conn_select_own on public.calendar_connections
  for select to authenticated
  using (user_id = auth.uid() and public.is_company_member(company_id));

-- COLLEGAMENTI EVENTO — sola lettura, e solo i propri: servono a dire «questa
-- attività è sul tuo calendario» e nient'altro.
grant select on public.calendar_event_links to authenticated;

drop policy if exists cal_links_select_own on public.calendar_event_links;
create policy cal_links_select_own on public.calendar_event_links
  for select to authenticated
  using (user_id = auth.uid() and public.is_company_member(company_id));

-- SEGRETI, STATI OAUTH, CODA, ESECUZIONI, CONSEGNE — nessun permesso, per
-- nessuno. Il `revoke` di sopra è già sufficiente; qui non si concede nulla.
-- Le consegne email restano fuori dalla portata del client di proposito: sapere
-- che un'email è stata inviata è un dato di esercizio, non una schermata.

-- ---------------------------------------------------------------------------
-- 21. Autoverifica
--
-- La migrazione controlla di aver ottenuto ciò che dichiara. Se un domani
-- qualcuno concedesse per sbaglio la scrittura sulle notifiche o un permesso
-- qualsiasi sui token, questa migrazione rieseguita lo direbbe subito — invece
-- di lasciar passare una falla che non produce alcun sintomo visibile finché
-- qualcuno non la sfrutta. È la lezione della 0014.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
begin
  select string_agg(format('%s (%s)', table_name, privilege_type), ', ')
    into v_bad
    from information_schema.table_privileges
   where table_schema = 'public'
     and grantee in ('anon', 'authenticated', 'public')
     and table_name in (
       'calendar_connection_secrets', 'calendar_oauth_states',
       'calendar_sync_queue', 'calendar_sync_runs', 'notification_deliveries'
     );
  if v_bad is not null then
    raise exception 'Le tabelle di servizio del calendario non devono avere alcun permesso: %', v_bad;
  end if;

  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
    from information_schema.table_privileges
   where table_schema = 'public'
     and grantee in ('anon', 'authenticated', 'public')
     and table_name in ('notifications', 'calendar_event_links')
     and privilege_type in ('INSERT', 'UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'Notifiche e collegamenti evento non devono essere scrivibili dal client: %', v_bad;
  end if;

  select string_agg(format('calendar_connections.%s (%s)', column_name, privilege_type), ', ')
    into v_bad
    from information_schema.column_privileges
   where table_schema = 'public'
     and grantee in ('anon', 'authenticated')
     and table_name = 'calendar_connections'
     and privilege_type in ('INSERT', 'UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'Le connessioni di calendario non devono essere scrivibili dal client: %', v_bad;
  end if;

  raise notice 'Permessi 0018 verificati: token irraggiungibili, notifiche non fabbricabili, coda del solo server.';
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0019_notifications_mark_read  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0019 «SEGNA COME LETTA» NON FUNZIONAVA
--
-- COSA È ANDATO STORTO NELLA 0018
-- `notifications_mark_read` e `notifications_mark_all_read` erano `security
-- invoker`, cioè giravano con i permessi di CHI LE CHIAMA. Sulla tabella
-- `notifications` il ruolo `authenticated` ha soltanto `SELECT` — di proposito,
-- perché una notifica non deve essere riscrivibile dal browser — quindi l'UPDATE
-- dentro la funzione veniva respinto:
--
--     42501: permission denied for table notifications
--
-- Il risultato era che la campanella non riusciva a segnare niente come letto e
-- il badge non scendeva mai.
--
-- IL RAGIONAMENTO SBAGLIATO, PERCHÉ È LA PARTE CHE VALE LA PENA RICORDARE
-- Nella 0018 c'era scritto: «l'UPDATE esiste per far passare `read_at` scritto
-- dalle funzioni, che girano security invoker. Resta inutilizzabile dal client:
-- non c'è alcun GRANT di UPDATE sulla tabella, quindi la policy da sola non
-- basta ad aprire nulla.» La seconda metà è vera. La prima no: se la funzione
-- gira come il chiamante, allora la funzione È il chiamante, e il permesso che
-- manca al client manca anche a lei. Una policy senza il GRANT corrispondente
-- non apre niente — nemmeno a chi vorremmo che aprisse.
--
-- COME È EMERSO: `npm run test:calendar` alla PRIMA esecuzione sul database
-- reale, 3 fallimenti su 57. Non leggendo il codice e non facendo la revisione:
-- eseguendo. È la stessa lezione della 0014, dove i permessi di colonna della
-- 0013 dichiaravano nei commenti una garanzia che non era in vigore.
--
-- ⚠️ E IL TEST LO AVEVA QUASI NASCOSTO. Il controllo «Andrea non può segnare
-- come letta una notifica di Marco» PASSAVA — ma per il motivo sbagliato: la
-- chiamata falliva con 42501, `data` tornava `null`, e `Number(null)` è zero.
-- Un test che scarta l'errore e guarda solo il risultato non distingue «zero
-- righe» da «non ho potuto provarci». Corretto anche quello.
--
-- LA CORREZIONE
-- Le due funzioni diventano `security definer`. Da quel momento la RLS non le
-- filtra più, quindi la condizione `user_id = auth.uid()` scritta dentro non è
-- più una ridondanza: è L'UNICA difesa, ed è esattamente la disciplina già
-- fissata nella 0017 — una funzione che scavalca la RLS deve difendersi da sola
-- e non fidarsi di una policy scritta altrove.
--
-- Il client continua a NON avere alcun permesso di scrittura su `notifications`.
--
-- Perché una migrazione nuova e non una correzione della 0018: la 0018 è già
-- stata applicata. Un file di migrazione è il verbale di ciò che è stato
-- eseguito; riscriverlo dopo l'applicazione significherebbe che il repository e
-- il database raccontano due storie diverse. È la stessa ragione per cui la
-- 0014 esiste accanto alla 0013 invece di sostituirla.
--
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Le due funzioni, ora `security definer`
--
-- `set search_path = ''` resta indispensabile: una funzione `security definer`
-- gira con i privilegi del proprietario, e un search_path manipolabile dal
-- chiamante le farebbe eseguire codice altrui con quei privilegi.
--
-- Ogni condizione ha una ragione:
--   · `n.id = any(…)`      soltanto le righe indicate;
--   · `n.user_id = auth.uid()`  soltanto le PROPRIE. Senza questa riga la
--     funzione segnerebbe come lette le notifiche di chiunque, perché in
--     `security definer` la RLS non c'è più;
--   · `n.read_at is null`  «già letta» non si conta due volte, e il valore
--     originale non si sposta.
-- ---------------------------------------------------------------------------
create or replace function public.notifications_mark_read(p_ids uuid[])
returns integer
language sql
volatile
security definer
set search_path = ''
as $$
  with updated as (
    update public.notifications n
       set read_at = now()
     where n.id = any(coalesce(p_ids, '{}'::uuid[]))
       and n.user_id = auth.uid()
       and n.read_at is null
    returning n.id
  )
  select count(*)::integer from updated;
$$;

create or replace function public.notifications_mark_all_read(p_company_id uuid)
returns integer
language sql
volatile
security definer
set search_path = ''
as $$
  with updated as (
    update public.notifications n
       set read_at = now()
     where n.company_id = p_company_id
       and n.user_id = auth.uid()
       and n.read_at is null
    returning n.id
  )
  select count(*)::integer from updated;
$$;

-- `security definer` con `auth.uid()` nullo — cioè chiamata dal service role o
-- da uno script — non aggiorna nulla, perché nessuna riga ha `user_id` nullo.
-- È il comportamento voluto: non esiste un modo di segnare come lette le
-- notifiche «di tutti».

revoke all on function public.notifications_mark_read(uuid[])   from public, anon;
revoke all on function public.notifications_mark_all_read(uuid) from public, anon;
grant execute on function public.notifications_mark_read(uuid[])   to authenticated;
grant execute on function public.notifications_mark_all_read(uuid) to authenticated;

-- `notifications_unread_count` resta `security invoker` e NON si tocca: legge
-- soltanto, e per una lettura la RLS è la difesa giusta — è già in vigore e
-- filtra riga per riga. Renderla `definer` sposterebbe quella difesa dentro una
-- condizione scritta a mano, senza guadagnarci niente.

-- ---------------------------------------------------------------------------
-- 2. Via la policy che non apriva niente
--
-- `notifications_update_own` era stata scritta per far passare l'UPDATE delle
-- funzioni. Non serviva già allora — senza GRANT una policy non apre nulla — e
-- ora che le funzioni sono `security definer` la RLS non le riguarda affatto.
-- Si toglie invece di lasciarla: una policy che sembra concedere una scrittura
-- che non esiste è un invito a concedere, un domani, anche il GRANT che la
-- renderebbe vera.
-- ---------------------------------------------------------------------------
drop policy if exists notifications_update_own on public.notifications;

-- ---------------------------------------------------------------------------
-- 3. Autoverifica
--
-- Due affermazioni, entrambe controllate qui e non solo nella suite di test:
-- le funzioni sono davvero `security definer`, e il client continua a non avere
-- alcuna scrittura sulla tabella. La seconda è la garanzia che la prima non
-- deve costare.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
begin
  select string_agg(p.proname, ', ')
    into v_bad
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname in ('notifications_mark_read', 'notifications_mark_all_read')
     and not p.prosecdef;
  if v_bad is not null then
    raise exception 'Queste funzioni devono essere security definer, altrimenti l''UPDATE viene respinto: %', v_bad;
  end if;

  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
    from information_schema.table_privileges
   where table_schema = 'public'
     and table_name = 'notifications'
     and grantee in ('anon', 'authenticated', 'public')
     and privilege_type in ('INSERT', 'UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'Le notifiche non devono essere scrivibili dal client: %', v_bad;
  end if;

  raise notice '0019 verificata: «segna come letta» funziona e le notifiche restano non riscrivibili dal client.';
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0020_workflow_automation  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0020 WORKFLOW AUTOMATION (Automazioni)
--
-- QUANDO succede X, SE valgono le condizioni Y, ALLORA esegui Z.
--
-- Non è un agente autonomo e non è un costruttore di flussi generici: è il
-- motore di REGOLE OPERATIVE dell'azienda. Le regole sono DATI, mai codice —
-- nessun `eval`, nessuna espressione da interpretare, nessun SQL costruito a
-- stringhe. Il motore legge una configurazione dichiarativa e la confronta con
-- un insieme CHIUSO di campi che ogni evento dichiara.
--
-- ⚠️ QUESTA MIGRAZIONE NON CREA UNA SECONDA VERITÀ SU NIENTE.
-- Le automazioni non copiano analisi, non copiano documenti, non copiano
-- attività: leggono ciò che esiste e producono attività, categorie, etichette e
-- notifiche PASSANDO DALLE STESSE TABELLE E DAGLI STESSI TRIGGER che usa una
-- persona. Un'attività creata da una regola è un'attività normale, con lo stesso
-- storico, le stesse garanzie e la stessa sincronizzazione di calendario.
--
-- COSA CONTIENE
--   1.  Enum del dominio (tutti nuovi: utilizzabili subito).
--   2.  Due valori aggiunti a enum esistenti — e MAI nominati altrove qui.
--   3.  `automation_events`: l'outbox. Lo scrivono i TRIGGER, non il browser.
--   4.  `workflow_definitions`: la regola.
--   5.  `workflow_runs` + `workflow_action_runs`: cosa è stato fatto e perché.
--   6.  `workflow_events`: chi ha creato, attivato, messo in pausa, archiviato.
--   7.  Provenienza: `tasks.workflow_run_id`, `documents.category_workflow_run_id`.
--   8.  `automation_emit()` — il punto UNICO da cui nasce un evento.
--   9.  I trigger che lo chiamano (analisi, categoria, posta, attività).
--   10. La coda: prenotazione atomica con lease, come il calendario (0018).
--   11. RLS, permessi e autoverifica.
--
-- ⚠️ VINCOLO SUI VALORI ENUM NUOVI (lezione della 0015, ricordata da 0016/0017)
-- `alter type … add value` non rende l'etichetta utilizzabile finché la
-- transazione non è chiusa, e `full-setup.sql` concatena tutto in una
-- transazione sola. Qui si aggiungono DUE valori a due enum esistenti
-- (`notification_type` e `document_category_source`) e NESSUNA altra istruzione
-- di questo file li nomina: li scrive soltanto il codice del worker, a runtime.
-- `npm run db:bundle` lo verifica.
--
-- ⚠️ REVOKE PRIMA DEI GRANT (lezione della 0014)
-- Su Supabase ogni tabella nuova di `public` nasce con i permessi di TABELLA
-- completi per `anon` e `authenticated`. Un grant scritto dopo AGGIUNGE
-- privilegi: non ne toglie. Ogni tabella qui sotto passa da `revoke all`.
--
-- Questa migrazione è RIESEGUIBILE.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Enum del dominio
-- ---------------------------------------------------------------------------

-- I tipi di evento della versione 1. Sei, e ognuno corrisponde a un fatto che il
-- prodotto PRODUCE GIÀ: non si dichiara un innesco che nessuno scriverebbe mai.
-- «Fattura ricevuta», «contratto in scadenza», «cliente creato» non ci sono
-- perché non esistono le sorgenti: elencarli qui li farebbe comparire in un
-- menu a tendina che non scatterebbe mai.
do $$ begin create type public.automation_event_type as enum (
  'document_analysis_completed',   -- un'analisi valida è stata scritta
  'document_category_changed',     -- la categoria organizzativa è cambiata
  'email_attention_ready',         -- una comunicazione ha finito il processamento
  'task_created',                  -- è nata un'attività
  'task_status_changed',           -- un'attività ha cambiato stato
  'task_became_overdue'            -- un'attività ha superato la propria scadenza
);
exception when duplicate_object then null; end $$;

comment on type public.automation_event_type is
  'Fatti del dominio che possono innescare una regola. Solo eventi che il prodotto '
  'produce davvero: un innesco dichiarato e mai emesso sarebbe una funzione finta.';

-- Stato di un evento nella coda. `dead_letter` è distinto da `failed`: il primo
-- è «ho smesso di riprovare», il secondo «non c'era niente da riprovare».
do $$ begin create type public.automation_event_status as enum
  ('pending', 'processing', 'done', 'failed', 'dead_letter');
exception when duplicate_object then null; end $$;

-- Stato di una regola. L'archiviazione È uno stato qui — a differenza delle
-- attività, dove è una data — perché una regola archiviata non deve poter
-- comparire in nessun elenco operativo e lo stato è il campo su cui filtra ogni
-- interrogazione del motore.
do $$ begin create type public.workflow_status as enum
  ('draft', 'active', 'paused', 'archived');
exception when duplicate_object then null; end $$;

do $$ begin create type public.workflow_run_status as enum
  ('pending', 'running', 'succeeded', 'partial', 'failed', 'skipped');
exception when duplicate_object then null; end $$;

do $$ begin create type public.workflow_action_status as enum
  ('pending', 'succeeded', 'skipped', 'failed');
exception when duplicate_object then null; end $$;

-- Le voci dello storico di una regola. Sono gesti di PERSONE (più due decisioni
-- del sistema che vanno dichiarate: la pausa automatica e il taglio della
-- catena), non risultati di esecuzione: quelli stanno in `workflow_runs`.
-- §125 — «domain events» alimentano l'automazione, «audit events» raccontano
-- chi ha fatto cosa. Condividere una tabella confonderebbe le due cose.
do $$ begin create type public.workflow_audit_kind as enum (
  'created', 'updated', 'activated', 'paused', 'archived', 'restored',
  'retried', 'auto_paused', 'chain_depth_exceeded'
);
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 2. Due valori aggiunti a enum ESISTENTI
--
-- ⚠️ NESSUNA ALTRA ISTRUZIONE DI QUESTO FILE PUÒ NOMINARLI, nemmeno dentro il
-- corpo di una funzione: Postgres li rifiuterebbe con 55P04 finché la
-- transazione non è chiusa. Li usa soltanto il worker, a runtime, quando la
-- migrazione è ormai applicata da un pezzo.
--
--   · notification_type      riceve il tipo delle notifiche prodotte da una
--                            regola. Riusare `task_assigned` avrebbe
--                            significato far dire alla campanella una cosa
--                            falsa; creare una tabella di notifiche parallela
--                            avrebbe significato due campanelle (§91).
--   · document_category_source riceve l'origine «regola aziendale». Non è
--                            «rule»: quella è la classificazione deterministica
--                            per tipo di documento ed ente (0017), che il
--                            prodotto fa da sé. Una categoria scelta da una
--                            regola dell'AZIENDA è una terza cosa, e chi guarda
--                            il documento ha diritto di sapere quale delle due
--                            l'ha messa.
-- ---------------------------------------------------------------------------
--   · task_source             riceve la provenienza «regola aziendale». Le tre
--                            esistenti dicono da quale MODULO nasce il lavoro
--                            (analisi documentale, incentivi, mano di una
--                            persona): nessuna delle tre descrive un'attività
--                            che non ha deciso nessuno sul momento. Chi la
--                            riceve ha diritto di saperlo, e
--                            `tasks.workflow_run_id` dice anche QUALE regola.
alter type public.notification_type add value if not exists 'workflow_alert';
alter type public.document_category_source add value if not exists 'workflow';
alter type public.task_source add value if not exists 'workflow';

-- ---------------------------------------------------------------------------
-- 3. automation_events — l'outbox
--
-- IL PATTERN, E PERCHÉ NON SE NE PUÒ FARE A MENO.
-- Un'analisi che finisce e una regola che parte sono due cose che devono
-- succedere insieme o non succedere affatto. Se la seconda vivesse dentro la
-- richiesta della prima — `await salvaAnalisi(); await eseguiRegole();` — un
-- guasto in mezzo lascerebbe l'analisi scritta e le regole perse, e nessuno lo
-- saprebbe. Qui l'evento nasce nella STESSA TRANSAZIONE del fatto, scritto da
-- un trigger: o ci sono entrambi o non c'è nessuno dei due. Poi un worker
-- asincrono lo consuma, e il processo di partenza è già finito da un pezzo
-- (§11/§58).
--
-- ⚠️ IL CLIENT NON PUÒ SCRIVERE QUI, E NON PUÒ NEMMENO LEGGERE.
-- Nessun GRANT, per nessun ruolo diverso da `service_role`. Un browser che
-- potesse dichiarare `document_analysis_completed` con un payload inventato
-- potrebbe far creare attività, cambiare categorie e mandare notifiche a nome
-- di regole che non ha scritto lui (§12/§151).
--
-- ⚠️ IL PAYLOAD È MINIMO (§13/§117).
-- Identificativi e pochissimi metadati. MAI il corpo di una email, mai il testo
-- estratto di un documento, mai un allegato, mai un JSON di analisi. Chi esegue
-- la regola ha il service role e può rileggere ciò che gli serve dalle tabelle
-- vere: conservarne una copia qui significherebbe soltanto moltiplicare i posti
-- da cui un dato personale può uscire.
-- ---------------------------------------------------------------------------
create table if not exists public.automation_events (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies (id) on delete cascade,
  event_type        public.automation_event_type not null,
  -- Testo e non enum: `entity_type` non governa nessuna decisione di
  -- autorizzazione — quella la fa `company_id` — e serve solo a sapere in quale
  -- tabella andare a rileggere. Stessa scelta di `notifications` (0018).
  entity_type       text not null check (entity_type in ('document', 'email_message', 'task')),
  entity_id         uuid not null,
  -- La versione del CONTRATTO dell'evento. Serve il giorno in cui un evento
  -- cambia forma: le regole scritte per la versione 1 devono continuare a
  -- essere interpretabili, e un worker deve poter rifiutare ciò che non capisce
  -- invece di indovinare.
  event_version     integer not null default 1 check (event_version >= 1),
  payload           jsonb not null default '{}'::jsonb,
  occurred_at       timestamptz not null default now(),
  created_at        timestamptz not null default now(),

  -- ---- Provenienza e catena causale (§68/§69/§71/§72) --------------------
  -- `system` = il fatto è successo perché qualcuno ha caricato un documento,
  -- ricevuto una email, creato un'attività. `automation` = l'ha prodotto una
  -- regola. Senza questa distinzione una regola che crea attività e una regola
  -- che reagisce alle attività si inseguirebbero all'infinito.
  origin            text not null default 'system' check (origin in ('system', 'automation')),
  origin_run_id     uuid,          -- FK a workflow_runs: aggiunta più sotto (dipendenza circolare)
  -- L'identità della CATENA. Tutti gli eventi discendenti da uno stesso fatto
  -- iniziale condividono questo valore, ed è ciò che permette la regola
  -- fondamentale: una regola gira AL PIÙ UNA VOLTA per catena.
  correlation_id    uuid not null default gen_random_uuid(),
  causation_id      uuid references public.automation_events (id) on delete set null,
  root_event_id     uuid references public.automation_events (id) on delete set null,
  chain_depth       integer not null default 0 check (chain_depth >= 0),

  -- ---- Coda ---------------------------------------------------------------
  processing_status public.automation_event_status not null default 'pending',
  attempts          integer not null default 0,
  next_attempt_at   timestamptz not null default now(),
  -- Lease a SCADENZA e non booleano: un worker ucciso dai 150 secondi di
  -- Supabase non deve bloccare una riga per sempre (§61). È la stessa forma
  -- della coda del calendario, e per la stessa ragione.
  locked_until      timestamptz,
  lock_id           uuid,
  processed_at      timestamptz,
  error_code        text,
  -- Idempotenza dell'EMISSIONE. Serve agli eventi che nascono da una scansione
  -- periodica («questa attività è scaduta»), che senza chiave si ripeterebbero
  -- a ogni giro. Gli eventi che nascono da un cambiamento di stato non ne hanno
  -- bisogno — il trigger scatta una volta per UPDATE — e dargliene una finta
  -- con dentro un timestamp sarebbe scrivere un vincolo che non vincola nulla.
  -- È esattamente la scelta già fatta per `notifications.dedupe_key` (0018).
  dedupe_key        text
);

create unique index if not exists uq_automation_events_dedupe
  on public.automation_events (company_id, dedupe_key) where dedupe_key is not null;
-- La domanda del worker: «cosa c'è da fare adesso». Indice parziale, perché le
-- righe già trattate sono la maggioranza e non interessano più.
create index if not exists idx_automation_events_due
  on public.automation_events (next_attempt_at, company_id)
  where processing_status in ('pending', 'processing');
-- La diagnostica: cosa è successo a questa azienda, e cosa è finito male.
create index if not exists idx_automation_events_company
  on public.automation_events (company_id, occurred_at desc);
create index if not exists idx_automation_events_dead
  on public.automation_events (company_id, occurred_at desc)
  where processing_status = 'dead_letter';
-- La regola «una volta per catena» interroga per correlazione.
create index if not exists idx_automation_events_chain
  on public.automation_events (correlation_id);

comment on table public.automation_events is
  'Outbox dei fatti del dominio. Lo scrivono i trigger nella stessa transazione del '
  'fatto; il client non ha alcun permesso, né di lettura né di scrittura. Append-only: '
  'nessuno può riscrivere un evento già avvenuto.';
comment on column public.automation_events.payload is
  'Solo identificativi e metadati minimi. Mai corpi di email, testi estratti o allegati: '
  'chi esegue rilegge dalle tabelle vere con il service role.';
comment on column public.automation_events.correlation_id is
  'Identità della catena causale. Una regola gira al più una volta per catena: è ciò '
  'che impedisce sia il ciclo su sé stessa sia il ciclo A→B→A.';

-- ---------------------------------------------------------------------------
-- 4. workflow_definitions — la regola
--
-- `conditions` e `actions` sono JSONB e la scelta è motivata (§127/§128): una
-- configurazione è per natura una struttura variabile, e normalizzarla in
-- `workflow_condition_rows` + `workflow_condition_values` avrebbe prodotto tre
-- tabelle da ricomporre a ogni lettura per rappresentare quello che è, di
-- fatto, un documento. Il prezzo del JSONB è che il database non ne conosce la
-- forma: si paga con i vincoli strutturali qui sotto (tipo, dimensione,
-- numero di elementi) e con la validazione SEMANTICA nel registro tipizzato,
-- che è l'unico posto in cui esistono i campi e le azioni ammesse.
--
-- ⚠️ NESSUN PERMESSO DI SCRITTURA PER IL CLIENT. Si crea, si modifica, si
-- attiva e si archivia SOLO passando dalla Edge Function `automation-admin`,
-- che verifica il ruolo e valida la configurazione contro il registro prima di
-- scrivere. È la stessa disciplina delle connessioni di posta (0013): «al
-- client non serve nessun permesso di scrittura, e non averlo è più solido che
-- averlo e controllarlo altrove».
-- ---------------------------------------------------------------------------
create table if not exists public.workflow_definitions (
  id               uuid primary key default gen_random_uuid(),
  company_id       uuid not null references public.companies (id) on delete cascade,
  name             text not null check (length(btrim(name)) between 1 and 80),
  description      text check (length(description) <= 500),
  status           public.workflow_status not null default 'draft',
  trigger_type     public.automation_event_type not null,
  -- `all` = tutte le condizioni devono valere, `any` = ne basta una (§22).
  -- Due valori e non un albero ricorsivo: un costruttore di espressioni
  -- annidate è una cosa che si scrive in una settimana e si spiega in un'ora,
  -- e nessun titolare di PMI ne ha mai chiesto uno.
  condition_match  text not null default 'all' check (condition_match in ('all', 'any')),
  conditions       jsonb not null default '[]'::jsonb,
  actions          jsonb not null default '[]'::jsonb,

  -- La versione cresce a ogni modifica della configurazione, e ogni esecuzione
  -- registra quale versione ha eseguito: le run di ieri restano interpretabili
  -- anche dopo che la regola è cambiata (§46/§47).
  version          integer not null default 1 check (version >= 1),

  -- ⚠️ §163 — ATTIVARE UNA REGOLA NON PROCESSA IL PASSATO.
  -- Non è un filtro nel worker che qualcuno può dimenticare: il motore confronta
  -- `occurred_at` dell'evento con questa data. Una regola attivata oggi non può
  -- reagire a un documento di marzo, e la garanzia sta in un solo posto.
  activated_at     timestamptz,

  -- «Attiva, ma richiede attenzione» (§103): la configurazione è diventata
  -- invalida — il responsabile non è più in azienda, l'etichetta è stata
  -- cancellata. Non è uno stato, perché la regola resta quella che è: è un
  -- CODICE, e la schermata lo traduce in una frase che dice cosa fare.
  attention_code   text,
  attention_at     timestamptz,
  -- Fallimenti PERMANENTI consecutivi. Oltre la soglia la regola si mette in
  -- pausa da sé (§104): fallire diecimila volte non è resilienza, è rumore.
  consecutive_failures integer not null default 0 check (consecutive_failures >= 0),

  last_run_at      timestamptz,
  last_run_status  public.workflow_run_status,

  created_by       uuid references auth.users (id) on delete set null,
  updated_by       uuid references auth.users (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  archived_at      timestamptz,
  archived_by      uuid references auth.users (id) on delete set null,

  -- Vincoli STRUTTURALI: ciò che il database può verificare da solo su un
  -- JSONB. La semantica — questo campo esiste? questa azione esiste? questo
  -- segnaposto è valido? — la verifica il registro, e senza quella validazione
  -- la regola non può essere attivata.
  constraint workflow_conditions_is_array check (jsonb_typeof(conditions) = 'array'),
  constraint workflow_actions_is_array    check (jsonb_typeof(actions) = 'array'),
  constraint workflow_conditions_max      check (jsonb_array_length(conditions) <= 10),
  constraint workflow_actions_max         check (jsonb_array_length(actions) <= 5)
);

-- ⚠️ §154 — l'indice che rende il motore indipendente dal numero di aziende.
-- La domanda del worker è sempre la stessa: «quali regole ATTIVE di QUESTA
-- azienda ascoltano QUESTO tipo di evento». Senza questo indice parziale,
-- ogni evento costerebbe una scansione di tutte le regole del database.
create index if not exists idx_workflows_active
  on public.workflow_definitions (company_id, trigger_type)
  where status = 'active';
-- L'elenco della schermata: tutte quelle non archiviate, dalla più recente.
create index if not exists idx_workflows_company
  on public.workflow_definitions (company_id, created_at desc)
  where status <> 'archived';

comment on table public.workflow_definitions is
  'Una regola operativa dell''azienda: QUANDO / SE / ALLORA. La configurazione è un '
  'DATO, mai codice: nessuna espressione viene interpretata, nessun SQL viene costruito.';
comment on column public.workflow_definitions.activated_at is
  'Da quando la regola è in vigore. Il motore ignora gli eventi precedenti: attivare '
  'una regola non fa ripartire il passato, e la garanzia sta qui e non in un filtro '
  'sparso nel worker.';
comment on column public.workflow_definitions.attention_code is
  'Configurazione diventata invalida a regola già attiva (responsabile uscito, etichetta '
  'cancellata). Codice, non frase: la frase la scrive l''interfaccia nella lingua di chi legge.';

-- ---------------------------------------------------------------------------
-- 5. workflow_runs — che cosa è successo, e con quale versione della regola
--
-- ⚠️ `unique (workflow_id, trigger_event_id)` È L'IDEMPOTENZA DI PIÙ ALTO
-- LIVELLO, e non è un indice «per sicurezza»: è la ragione per cui lo stesso
-- evento consegnato due volte non produce due esecuzioni. Un ritentativo
-- RIUSA la riga esistente invece di crearne una nuova, e le azioni già
-- riuscite non vengono rifatte (§43/§65/§135).
--
-- ⚠️ NON SI SCRIVE UNA RUN PER OGNI EVENTO CHE NON CORRISPONDE (§101).
-- Una regola su «categoria = Imposte» vedrebbe passare ogni documento
-- dell'azienda: con novecentonovanta documenti l'anno significherebbe
-- novecentonovanta righe «saltata» che nessuno leggerà mai, e la storia utile
-- — le venti volte in cui ha agito — sarebbe sepolta. Si scrive una run quando
-- le condizioni CORRISPONDONO, oppure quando qualcosa è andato storto: i non
-- corrispondenti diventano un contatore sull'evento, non una riga.
-- ---------------------------------------------------------------------------
create table if not exists public.workflow_runs (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies (id) on delete cascade,
  workflow_id       uuid not null references public.workflow_definitions (id) on delete cascade,
  workflow_version  integer not null,
  -- Fotografia della configurazione USATA. Senza, una run di ieri letta domani
  -- racconterebbe la regola di domani: si vedrebbero azioni che non sono mai
  -- state eseguite e non si vedrebbero quelle che lo sono state (§46).
  config_snapshot   jsonb not null default '{}'::jsonb,
  trigger_event_id  uuid references public.automation_events (id) on delete set null,

  -- L'entità su cui la regola ha agito. Solo tipo e identificativo: il titolo
  -- lo rilegge la schermata dalle tabelle vere, passando dalla RLS. Conservarne
  -- una copia qui significherebbe sia un dato in più da proteggere sia un
  -- titolo che invecchia (§117).
  entity_type       text check (entity_type in ('document', 'email_message', 'task')),
  entity_id         uuid,

  status            public.workflow_run_status not null default 'pending',
  -- Le condizioni, una per una, con l'esito. È ciò che permette alla schermata
  -- di dire «✓ Categoria = Imposte» invece di «ha funzionato» (§49). Contiene
  -- il campo, l'operatore, il valore ATTESO e l'esito: NON il valore osservato
  -- quando è un testo libero, per non trascinare qui il mittente di ogni
  -- documento dell'azienda.
  condition_results jsonb not null default '[]'::jsonb,
  started_at        timestamptz not null default now(),
  completed_at      timestamptz,
  duration_ms       integer,
  error_code        text,
  created_at        timestamptz not null default now(),

  unique (workflow_id, trigger_event_id)
);
create index if not exists idx_workflow_runs_wf
  on public.workflow_runs (workflow_id, started_at desc);
create index if not exists idx_workflow_runs_company
  on public.workflow_runs (company_id, started_at desc);
-- «Quante esecuzioni e quanti errori negli ultimi trenta giorni» (§102).
create index if not exists idx_workflow_runs_problem
  on public.workflow_runs (workflow_id, started_at desc)
  where status in ('failed', 'partial');

comment on table public.workflow_runs is
  'Un''esecuzione. Immutabile per il client: la scrive il worker con il service role. '
  'Il vincolo unico (workflow, evento) è ciò che impedisce a un evento consegnato due '
  'volte di produrre due esecuzioni.';

-- Ora che `workflow_runs` esiste, si può chiudere la dipendenza circolare: un
-- evento può essere stato prodotto da una run, e una run nasce da un evento.
do $$ begin
  alter table public.automation_events
    add constraint automation_events_origin_run_fk
    foreign key (origin_run_id) references public.workflow_runs (id) on delete set null;
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 6. workflow_action_runs — ogni azione, con la sua chiave di idempotenza
--
-- ⚠️ LA CHIAVE UNICA È NEL DATABASE, NON NEL CODICE (§66).
-- «Guarda se esiste, poi inserisci» non è una garanzia: fra il guardare e
-- l'inserire ci sta un'altra esecuzione del worker. Qui la seconda insert
-- fallisce con 23505 e l'esecutore lo interpreta per quello che è — «l'ho già
-- fatto» — invece di creare una seconda attività identica.
-- ---------------------------------------------------------------------------
create table if not exists public.workflow_action_runs (
  id                 uuid primary key default gen_random_uuid(),
  company_id         uuid not null references public.companies (id) on delete cascade,
  workflow_run_id    uuid not null references public.workflow_runs (id) on delete cascade,
  action_key         text not null check (length(action_key) between 1 and 60),
  action_position    integer not null check (action_position >= 0),
  status             public.workflow_action_status not null default 'pending',
  -- `<evento>:<regola>:<posizione>`. L'identificativo dell'evento è già unico,
  -- quindi la chiave lo è; averla in chiaro invece che come impronta permette
  -- di capire, guardando una riga, quale esecuzione l'ha prodotta.
  idempotency_key    text not null,
  -- Che cosa ha prodotto: l'attività creata, il documento toccato, la notifica.
  output_entity_type text check (output_entity_type in ('task', 'document', 'notification', 'document_tag')),
  output_entity_id   uuid,
  -- Perché è stata saltata o è fallita. Codice, mai frase: la frase la scrive
  -- l'interfaccia nella lingua di chi legge (§50).
  error_code         text,
  started_at         timestamptz,
  completed_at       timestamptz,
  created_at         timestamptz not null default now(),

  unique (idempotency_key),
  unique (workflow_run_id, action_position)
);
create index if not exists idx_action_runs_run
  on public.workflow_action_runs (workflow_run_id, action_position);

comment on column public.workflow_action_runs.idempotency_key is
  'Chiave di idempotenza «evento:regola:posizione». L''unicità la impone il database: '
  'un controllo applicativo non regge fra due esecuzioni sovrapposte del worker.';

-- ---------------------------------------------------------------------------
-- 7. workflow_events — chi ha fatto cosa alla regola
--
-- §124/§125 — È UN ALTRO REGISTRO, non lo stesso di `automation_events`.
-- Quello è la coda che alimenta il motore; questo racconta le decisioni delle
-- persone: chi ha creato, attivato, messo in pausa, archiviato, ritentato. Lo
-- scrivono i trigger, e il client non può scriverlo — un registro che
-- l'interessato può riscrivere non è un registro (0016).
-- ---------------------------------------------------------------------------
create table if not exists public.workflow_events (
  id             uuid primary key default gen_random_uuid(),
  company_id     uuid not null references public.companies (id) on delete cascade,
  workflow_id    uuid not null references public.workflow_definitions (id) on delete cascade,
  actor_user_id  uuid references auth.users (id) on delete set null,
  kind           public.workflow_audit_kind not null,
  detail         jsonb not null default '{}'::jsonb,
  created_at     timestamptz not null default now()
);
create index if not exists idx_workflow_events_wf
  on public.workflow_events (workflow_id, created_at desc);
create index if not exists idx_workflow_events_company
  on public.workflow_events (company_id, created_at desc);

-- ---------------------------------------------------------------------------
-- 8. Provenienza sulle entità prodotte
--
-- §42 — «serve sapere: questa attività è stata creata automaticamente dalla
-- regola X». Una relazione esplicita, NON una frase infilata nella descrizione:
-- una descrizione è testo per una persona, e scriverci dentro un dato
-- strutturato significa non poterlo più interrogare e doverlo leggere con
-- un'espressione regolare.
--
-- Le due colonne servono anche alla PROTEZIONE DEI CICLI: sono il modo in cui
-- il trigger che emette l'evento successivo sa di essere dentro una catena
-- avviata da un'automazione, e non all'inizio di una nuova storia (§68).
-- ---------------------------------------------------------------------------
alter table public.tasks
  add column if not exists workflow_run_id uuid references public.workflow_runs (id) on delete set null;

alter table public.documents
  add column if not exists category_workflow_run_id uuid references public.workflow_runs (id) on delete set null;

create index if not exists idx_tasks_workflow_run
  on public.tasks (workflow_run_id) where workflow_run_id is not null;

-- ⚠️ Una notifica prodotta da una regola può riferirsi a un DOCUMENTO o a una
-- COMUNICAZIONE, non solo a un'attività. Il vincolo della 0018 ammetteva due
-- soli valori perché due erano i casi che esistevano allora; lasciarlo com'era
-- avrebbe fatto fallire l'azione «notifica» su ogni innesco documentale con un
-- errore di vincolo, cioè con un guasto tecnico al posto di una funzione.
-- Si allarga l'elenco, non si toglie il controllo: un `entity_type` libero
-- permetterebbe di scrivere qualsiasi cosa e la campanella comporrebbe
-- collegamenti verso rotte inesistenti.
alter table public.notifications drop constraint if exists notifications_entity_type_check;
do $$ begin
  alter table public.notifications
    add constraint notifications_entity_type_check
    check (entity_type in ('task', 'calendar_connection', 'document', 'email_message'));
exception when duplicate_object then null; end $$;

comment on column public.tasks.workflow_run_id is
  'L''esecuzione che ha creato questa attività, quando è nata da una regola. Si scrive '
  'solo all''inserimento: una modifica successiva non è una creazione, e riscriverlo '
  'farebbe dire alla schermata una cosa falsa.';
comment on column public.documents.category_workflow_run_id is
  'L''esecuzione che ha impostato la categoria, quando l''ha impostata una regola. '
  'Accompagna category_source: dice QUALE regola, non solo che ce n''è stata una.';

-- ---------------------------------------------------------------------------
-- 9. I limiti, dichiarati dal database
--
-- Esistono in due posti — qui e nel contratto TypeScript del motore — perché il
-- database li APPLICA e l'interfaccia li DICHIARA. Quando le due copie
-- divergono, la schermata promette una cosa e il sistema ne fa un'altra: è già
-- successo con `INITIAL_SYNC_DAYS` dell'Inbox, e da allora un test verifica che
-- coincidano. Questa funzione esiste perché quel test possa farlo.
-- ---------------------------------------------------------------------------
create or replace function public.automation_limits()
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select jsonb_build_object(
    'maxActiveWorkflows', 10,
    'maxConditions', 10,
    'maxActions', 5,
    'maxChainDepth', 5,
    'maxEventAttempts', 5,
    'maxRunsPerCompanyPerPass', 50,
    'maxTemplateLength', 200
  );
$$;

revoke all on function public.automation_limits() from public, anon;
grant execute on function public.automation_limits() to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 10. automation_emit — il punto UNICO da cui nasce un evento
--
-- Tutti i trigger passano di qui. Una funzione sola perché le decisioni
-- delicate — non emettere se nessuno ascolta, ereditare la catena, fermarsi
-- alla profondità massima — devono esistere in un posto solo: scritte cinque
-- volte, prima o poi quattro sono giuste e una no.
--
-- ⚠️ NON SI EMETTE SE NESSUNA REGOLA ATTIVA ASCOLTA QUESTO TIPO DI EVENTO.
-- È la stessa scelta di `calendar_enqueue_task`, che non accoda nulla per le
-- aziende senza calendario collegato. Senza, l'importazione iniziale di una
-- casella di posta scriverebbe ottanta righe che nessuno consumerà mai. La
-- conseguenza va detta: gli eventi accaduti PRIMA che una regola esistesse non
-- si trovano da nessuna parte — ed è coerente con §163, perché una regola
-- appena attivata non deve comunque processare il passato.
--
-- `security definer` perché i trigger che la chiamano girano per conto di
-- chiunque stia scrivendo, e questa tabella non ha permessi per nessuno.
-- ---------------------------------------------------------------------------
create or replace function public.automation_emit(
  p_company_id  uuid,
  p_event_type  public.automation_event_type,
  p_entity_type text,
  p_entity_id   uuid,
  p_payload     jsonb default '{}'::jsonb,
  p_dedupe_key  text default null,
  -- Valorizzato SOLO quando il fatto è stato prodotto da un'automazione: è il
  -- filo che tiene insieme la catena causale.
  p_run_id      uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_parent       record;
  v_depth        integer := 0;
  v_correlation  uuid;
  v_root         uuid;
  v_causation    uuid;
  v_origin       text := 'system';
  v_max_depth    integer := (public.automation_limits() ->> 'maxChainDepth')::integer;
  v_id           uuid;
begin
  if p_company_id is null or p_entity_id is null then return null; end if;

  -- Nessuno ascolta: non si scrive niente.
  if not exists (
    select 1 from public.workflow_definitions w
    where w.company_id = p_company_id
      and w.trigger_type = p_event_type
      and w.status = 'active'
  ) then
    return null;
  end if;

  if p_run_id is not null then
    select r.id as run_id, r.workflow_id, e.id as event_id,
           e.correlation_id, e.root_event_id, e.chain_depth
      into v_parent
      from public.workflow_runs r
      left join public.automation_events e on e.id = r.trigger_event_id
     where r.id = p_run_id;

    if v_parent.run_id is not null then
      v_origin      := 'automation';
      v_causation   := v_parent.event_id;
      v_correlation := v_parent.correlation_id;
      v_root        := coalesce(v_parent.root_event_id, v_parent.event_id);
      v_depth       := coalesce(v_parent.chain_depth, 0) + 1;

      -- §70 — oltre la profondità massima si SMETTE, e lo si scrive. Un taglio
      -- silenzioso sarebbe indistinguibile da «non c'era altro da fare», che è
      -- proprio la confusione che questo progetto evita ovunque.
      if v_depth > v_max_depth then
        insert into public.workflow_events (company_id, workflow_id, actor_user_id, kind, detail)
        values (p_company_id, v_parent.workflow_id, null, 'chain_depth_exceeded',
                jsonb_build_object('depth', v_depth, 'max', v_max_depth,
                                   'correlationId', v_correlation, 'eventType', p_event_type));
        return null;
      end if;
    end if;
  end if;

  insert into public.automation_events (
    company_id, event_type, entity_type, entity_id, payload,
    origin, origin_run_id, correlation_id, causation_id, root_event_id, chain_depth,
    dedupe_key
  ) values (
    p_company_id, p_event_type, p_entity_type, p_entity_id, coalesce(p_payload, '{}'::jsonb),
    v_origin, p_run_id, coalesce(v_correlation, gen_random_uuid()), v_causation, v_root, v_depth,
    p_dedupe_key
  )
  on conflict (company_id, dedupe_key) where dedupe_key is not null do nothing
  returning id into v_id;

  return v_id;
end $$;

revoke all on function public.automation_emit(uuid, public.automation_event_type, text, uuid, jsonb, text, uuid)
  from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 11. I trigger che emettono
--
-- ⚠️ Ognuno emette dalla TABELLA che possiede il fatto, e non da un servizio:
-- così l'evento e il fatto stanno nella stessa transazione qualunque sia il
-- percorso che ha scritto il fatto — l'interfaccia, una Edge Function, uno
-- script di manutenzione o una migrazione. Un evento emesso dal codice
-- applicativo avrebbe coperto solo i percorsi a cui qualcuno ha pensato.
-- ---------------------------------------------------------------------------

-- (a) Un'analisi valida è stata scritta.
--     Le analisi FALLITE non emettono: un'analisi fallita non descrive niente,
--     e far scattare una regola su un fallimento significherebbe classificare o
--     assegnare lavoro sulla base di un dato che non esiste (§140).
create or replace function public.automation_on_analysis()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc record;
begin
  if new.analysis_status = 'failed' then return new; end if;

  select d.id, d.company_id, d.category, d.source_type
    into v_doc
    from public.documents d
   where d.id = new.document_id;

  -- Il confronto sull'azienda NON è ridondante: questa funzione è
  -- `security definer` e una funzione che scavalca la RLS deve difendersi da
  -- sola, senza fidarsi di una policy scritta altrove (lezione della 0017).
  if v_doc.id is null or v_doc.company_id is distinct from new.company_id then
    return new;
  end if;

  perform public.automation_emit(
    new.company_id, 'document_analysis_completed', 'document', new.document_id,
    jsonb_build_object('analysisId', new.id, 'analysisStatus', new.analysis_status),
    -- Una rianalisi dello stesso documento È un fatto nuovo (il contenuto
    -- capito può essere cambiato), quindi nessuna deduplicazione: la si
    -- otterrebbe solo inventando una chiave con dentro l'ora.
    null, null
  );
  return new;
end $$;

drop trigger if exists trg_automation_analysis on public.document_analyses;
create trigger trg_automation_analysis
  after insert on public.document_analyses
  for each row execute function public.automation_on_analysis();

-- (b) La categoria organizzativa è cambiata.
--     Solo il CAMBIO, non ogni salvataggio del documento: rinominare un file
--     non è un fatto per cui una regola debba muoversi.
create or replace function public.automation_on_category()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.category is not distinct from old.category then return new; end if;
  if new.category is null then return new; end if;

  perform public.automation_emit(
    new.company_id, 'document_category_changed', 'document', new.id,
    jsonb_build_object(
      'category', new.category,
      'previousCategory', old.category,
      'categorySource', new.category_source
    ),
    null,
    -- Se la categoria l'ha messa una regola, l'evento eredita la catena: è il
    -- filo che impedisce a due regole di rincorrersi sulla stessa categoria.
    new.category_workflow_run_id
  );
  return new;
end $$;

drop trigger if exists trg_automation_category on public.documents;
create trigger trg_automation_category
  after update on public.documents
  for each row execute function public.automation_on_category();

-- (c) Una comunicazione ha finito il processamento ed è pronta per una persona.
--     Si emette al passaggio a `done`, che è lo stato terminale riuscito. Non
--     su `failed`: là non c'è una comunicazione capita, c'è un guasto — e
--     l'Inbox lo mostra già come tale.
create or replace function public.automation_on_email_ready()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.processing_status <> 'done' then return new; end if;
  if old.processing_status = 'done' then return new; end if;

  perform public.automation_emit(
    new.company_id, 'email_attention_ready', 'email_message', new.id,
    jsonb_build_object(
      'attentionStatus', new.attention_status,
      'relevance', new.relevance,
      'hasAttachments', new.has_attachments
    ),
    -- Un messaggio raggiunge `done` una volta sola nella pratica, ma la chiave
    -- lo rende un fatto: una riesecuzione della pipeline non produce due
    -- eventi, e quindi non due attività.
    'email:' || new.id::text || ':ready',
    null
  );
  return new;
end $$;

drop trigger if exists trg_automation_email_ready on public.email_messages;
create trigger trg_automation_email_ready
  after update on public.email_messages
  for each row execute function public.automation_on_email_ready();

-- (d) Attività: creazione e cambio di stato.
create or replace function public.automation_on_task()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform public.automation_emit(
      new.company_id, 'task_created', 'task', new.id,
      jsonb_build_object('source', new.source, 'priority', new.priority,
                         'status', new.status, 'hasAssignee', new.assignee_user_id is not null),
      null,
      -- ⚠️ Qui si chiude il cerchio della protezione dei cicli: un'attività
      -- creata da una regola porta con sé l'esecuzione che l'ha creata, quindi
      -- l'evento che ne nasce sa di essere dentro una catena e ne eredita la
      -- profondità. Senza questa riga, «quando nasce un'attività, crea
      -- un'attività» girerebbe per sempre.
      new.workflow_run_id
    );
    return new;
  end if;

  if new.status is distinct from old.status then
    perform public.automation_emit(
      new.company_id, 'task_status_changed', 'task', new.id,
      jsonb_build_object('from', old.status, 'to', new.status,
                         'priority', new.priority,
                         'hasAssignee', new.assignee_user_id is not null),
      null, new.workflow_run_id
    );
  end if;

  return new;
end $$;

drop trigger if exists trg_automation_task on public.tasks;
create trigger trg_automation_task
  after insert or update on public.tasks
  for each row execute function public.automation_on_task();

-- ---------------------------------------------------------------------------
-- 12. «È diventata scaduta»: un fatto che non ha un UPDATE
--
-- Nessuno scrive niente quando un'attività supera la propria scadenza: passa il
-- tempo, e basta. Serve quindi una scansione — ma NON un secondo rilevatore di
-- scadenze (§9): la definizione di «scaduta» è quella che il prodotto già usa
-- nella vista «Scadute» di `list_tasks`, cioè `due_date < current_date` con
-- l'attività né conclusa né archiviata. Averne due significherebbe una
-- schermata che dice «in ritardo» e una regola che non scatta.
--
-- La finestra all'indietro è deliberata: si guardano solo le attività scadute
-- di recente. Senza, la prima esecuzione dopo l'attivazione di una regola
-- rovescerebbe addosso all'azienda tutto l'arretrato — che è esattamente il
-- backfill che §164 vieta.
--
-- La chiave di deduplicazione rende l'emissione idempotente: un'attività
-- diventa scaduta UNA volta. Se viene completata e riaperta oltre la scadenza,
-- non riparte: «scaduta» descrive il superamento della data, non lo stato del
-- lavoro, e ripeterlo ogni mattina addestrerebbe a ignorare l'avviso — la
-- stessa scelta già fatta per il promemoria «scaduta» dei calendari (0018).
-- ---------------------------------------------------------------------------
create or replace function public.automation_emit_overdue(
  p_lookback_days integer default 3,
  p_limit         integer default 200
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_task  record;
  v_count integer := 0;
  v_id    uuid;
begin
  for v_task in
    select t.id, t.company_id, t.priority, t.status, t.due_date,
           t.assignee_user_id is not null as has_assignee
      from public.tasks t
     where t.status <> 'completed'
       and t.archived_at is null
       and t.due_date is not null
       and t.due_date < current_date
       and t.due_date >= current_date - greatest(1, least(coalesce(p_lookback_days, 3), 30))
     order by t.due_date desc
     limit greatest(1, least(coalesce(p_limit, 200), 1000))
  loop
    v_id := public.automation_emit(
      v_task.company_id, 'task_became_overdue', 'task', v_task.id,
      jsonb_build_object('priority', v_task.priority, 'status', v_task.status,
                         'dueDate', v_task.due_date, 'hasAssignee', v_task.has_assignee),
      'task:' || v_task.id::text || ':overdue',
      null
    );
    if v_id is not null then v_count := v_count + 1; end if;
  end loop;
  return v_count;
end $$;

revoke all on function public.automation_emit_overdue(integer, integer) from public, anon, authenticated;
grant execute on function public.automation_emit_overdue(integer, integer) to service_role;

-- ---------------------------------------------------------------------------
-- 13. La coda: prenotazione atomica di un lotto
--
-- `for update skip locked`, come la coda del calendario e per la stessa
-- ragione: due esecuzioni sovrapposte del worker lavorano su eventi diversi
-- senza aspettarsi a vicenda. Il `locked_until` sopravvive alla transazione,
-- quindi un isolate ucciso a metà libera la riga alla scadenza invece di
-- tenerla presa per sempre (§61/§133).
--
-- ⚠️ IL TETTO PER AZIENDA (§73) non è prudenza teorica: un'importazione
-- iniziale di posta o un caricamento massivo di documenti possono produrre
-- centinaia di eventi in un minuto, e senza tetto una sola azienda occuperebbe
-- ogni esecuzione del worker mentre le altre aspettano. `row_number()` per
-- azienda risolve con una riga di SQL ciò che nel worker sarebbe stato un
-- contatore da ricordarsi.
-- ---------------------------------------------------------------------------
create or replace function public.automation_events_claim(
  p_limit        integer default 40,
  p_lock_seconds integer default 120,
  p_per_company  integer default 50
)
returns table (
  id uuid, company_id uuid, event_type public.automation_event_type,
  entity_type text, entity_id uuid, payload jsonb, occurred_at timestamptz,
  origin text, correlation_id uuid, root_event_id uuid, chain_depth integer,
  attempts integer, lock_id uuid
)
language sql
security definer
set search_path = ''
as $$
  with candidati as (
    select e.id as eid
    from (
      select ev.id, ev.next_attempt_at,
             row_number() over (partition by ev.company_id order by ev.next_attempt_at asc, ev.occurred_at asc) as rn
      from public.automation_events ev
      where ev.processing_status in ('pending', 'processing')
        and ev.next_attempt_at <= now()
        and (ev.locked_until is null or ev.locked_until < now())
    ) e
    where e.rn <= greatest(1, least(coalesce(p_per_company, 50), 200))
    order by e.next_attempt_at asc
    limit greatest(1, least(coalesce(p_limit, 40), 200))
  ),
  bloccati as (
    select q.id as eid
    from public.automation_events q
    where q.id in (select c.eid from candidati c)
      and q.processing_status in ('pending', 'processing')
      and q.next_attempt_at <= now()
      and (q.locked_until is null or q.locked_until < now())
    for update skip locked
  ),
  aggiornati as (
    update public.automation_events ev
       set processing_status = 'processing',
           locked_until = now() + make_interval(secs => greatest(30, least(coalesce(p_lock_seconds, 120), 600))),
           -- Un lock per RIGA e non per lotto: chi rilascia una riga non può
           -- liberare per sbaglio quelle che un'altra esecuzione sta trattando.
           lock_id = gen_random_uuid(),
           -- ⚠️ IL TENTATIVO SI CONTA QUANDO SI PRENDE, NON QUANDO SI FALLISCE.
           -- Se lo si contasse al fallimento, un worker ucciso a metà (i 150
           -- secondi di Supabase) lascerebbe la riga con lo stesso numero di
           -- tentativi di prima: alla scadenza del lease verrebbe ripresa, e
           -- riuccisa, e ripresa — per sempre, senza che il contatore arrivi
           -- mai al tetto. Contando qui, anche un evento che fa morire il
           -- worker finisce in `dead_letter` e diventa visibile.
           attempts = ev.attempts + 1
      from bloccati b
     where ev.id = b.eid
    returning ev.id, ev.company_id, ev.event_type, ev.entity_type, ev.entity_id,
              ev.payload, ev.occurred_at, ev.origin, ev.correlation_id,
              ev.root_event_id, ev.chain_depth, ev.attempts, ev.lock_id
  )
  select a.id, a.company_id, a.event_type, a.entity_type, a.entity_id, a.payload,
         a.occurred_at, a.origin, a.correlation_id, a.root_event_id, a.chain_depth,
         a.attempts, a.lock_id
  from aggiornati a;
$$;

revoke all on function public.automation_events_claim(integer, integer, integer) from public, anon, authenticated;
grant execute on function public.automation_events_claim(integer, integer, integer) to service_role;

-- L'età dell'evento più vecchio ancora da trattare (§169). È la misura che
-- risponde a «il worker sta girando?» con un numero invece che con
-- un'impressione: se cresce, qualcosa è fermo.
--
-- ⚠️ `security definer` PER FORZA, e la ragione va scritta: `automation_events`
-- non ha alcun GRANT per `authenticated`, quindi una funzione `security
-- invoker` fallirebbe con «permission denied» per chiunque la chiamasse. La
-- difesa è la prima riga del WHERE — solo un amministratore dell'azienda
-- richiesta ottiene dei numeri — ed è l'unica difesa che c'è, esattamente come
-- in `company_member_directory` (0016). Escono CONTEGGI, mai una riga.
--
-- ⚠️ E RIFIUTA, NON RISPONDE ZERO. Un'aggregazione senza `group by` restituisce
-- SEMPRE una riga: con un semplice `and is_company_admin(...)` nel WHERE, chi
-- non è amministratore otterrebbe «nessun arretrato» invece di «non ti è
-- permesso» — cioè una risposta rassicurante a una domanda che non aveva il
-- diritto di fare. È la forma di fallback silenzioso che questo progetto
-- considera il difetto peggiore, e qui costa tre righe evitarla.
create or replace function public.automation_backlog(p_company_id uuid)
returns table (pending integer, dead_letter integer, oldest_pending_seconds integer)
language plpgsql
security definer
stable
set search_path = ''
as $$
begin
  if not public.is_company_admin(p_company_id) then
    raise exception 'automation_backlog_forbidden'
      using errcode = '42501',
            hint = 'Lo stato del motore lo legge chi amministra l''azienda.';
  end if;

  return query
  select
    count(*) filter (where e.processing_status in ('pending', 'processing'))::integer,
    count(*) filter (where e.processing_status = 'dead_letter')::integer,
    coalesce(extract(epoch from (now() - min(e.occurred_at)
      filter (where e.processing_status in ('pending', 'processing'))))::integer, 0)
  from public.automation_events e
  where e.company_id = p_company_id;
end $$;

revoke all on function public.automation_backlog(uuid) from public, anon;
grant execute on function public.automation_backlog(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 14. Il guardiano delle regole
--
-- Quattro cose che il database non lascia decidere a chi scrive:
--   · l'AUTORE e chi MODIFICA devono essere membri dell'azienda della regola;
--   · la VERSIONE cresce quando cambia la configurazione, e non quando cambia
--     il nome: una run che dichiara «versione 3» deve riferirsi a una
--     configurazione diversa dalla 2, altrimenti il numero non significa nulla;
--   · `activated_at` lo scrive il database, e una regola non si può attivare
--     senza almeno un'azione — una regola che non fa niente, attiva, è solo un
--     modo di credere che qualcosa stia succedendo;
--   · il TETTO di regole attive per azienda (§166/§73).
--
-- La validazione SEMANTICA — questo campo esiste? questa azione esiste? questo
-- segnaposto è valido? — non è qui: sta nel registro tipizzato, che è l'unico
-- posto in cui quei nomi esistono. Duplicarla in SQL avrebbe creato due elenchi
-- destinati a divergere, ed è la stessa ragione per cui la scrittura passa da
-- una Edge Function e non dal browser.
-- ---------------------------------------------------------------------------
create or replace function public.workflows_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor  uuid := auth.uid();
  v_active integer;
  v_max    integer := (public.automation_limits() ->> 'maxActiveWorkflows')::integer;
  v_changed boolean;
begin
  new.name := btrim(new.name);

  -- (a) Appartenenza. Vale anche per il service role: la Edge Function scrive
  --     `created_by` con l'utente che ha premuto il pulsante, e se quella
  --     persona non è dell'azienda la riga non entra.
  if new.created_by is not null and not exists (
    select 1 from public.company_members m
    where m.company_id = new.company_id and m.user_id = new.created_by
  ) then
    raise exception 'workflow_author_not_member'
      using errcode = '23514', hint = 'L''autore non appartiene a questa azienda.';
  end if;
  if new.updated_by is not null and not exists (
    select 1 from public.company_members m
    where m.company_id = new.company_id and m.user_id = new.updated_by
  ) then
    raise exception 'workflow_editor_not_member'
      using errcode = '23514', hint = 'Chi modifica non appartiene a questa azienda.';
  end if;

  -- (b) Versione: cresce solo quando cambia ciò che il motore esegue.
  if tg_op = 'UPDATE' then
    v_changed :=
      new.trigger_type    is distinct from old.trigger_type
      or new.condition_match is distinct from old.condition_match
      or new.conditions   is distinct from old.conditions
      or new.actions      is distinct from old.actions;
    if v_changed then
      new.version := old.version + 1;
    else
      new.version := old.version;
    end if;
  end if;

  -- (c) Attivazione.
  if new.status = 'active' then
    if jsonb_array_length(new.actions) < 1 then
      raise exception 'workflow_no_actions'
        using errcode = '23514', hint = 'Una regola attiva deve avere almeno un''azione.';
    end if;
    if tg_op = 'INSERT' or old.status is distinct from 'active' then
      new.activated_at := now();
      select count(*) into v_active
        from public.workflow_definitions w
       where w.company_id = new.company_id and w.status = 'active' and w.id <> new.id;
      if v_active >= v_max then
        raise exception 'workflow_too_many_active'
          using errcode = '23514',
                hint = 'È stato raggiunto il numero massimo di automazioni attive.';
      end if;
    end if;
    -- Una regola che torna attiva riparte pulita: i fallimenti contati
    -- riguardavano una configurazione che chi ha riattivato ha già rivisto.
    if tg_op = 'UPDATE' and old.status is distinct from 'active' then
      new.consecutive_failures := 0;
      new.attention_code := null;
      new.attention_at := null;
    end if;
  end if;

  -- (d) Il codice di attenzione porta sempre la propria data: un avviso senza
  --     quando è un avviso di cui non si sa se è di oggi o di marzo.
  if new.attention_code is null then
    new.attention_at := null;
  elsif tg_op = 'INSERT' or old.attention_code is distinct from new.attention_code then
    new.attention_at := now();
  else
    new.attention_at := coalesce(old.attention_at, now());
  end if;

  -- (e) Archiviazione: il timbro lo mette il database.
  if new.status = 'archived' then
    if tg_op = 'INSERT' or old.status is distinct from 'archived' then
      new.archived_at := now();
      new.archived_by := coalesce(v_actor, new.updated_by);
    else
      new.archived_at := old.archived_at;
      new.archived_by := old.archived_by;
    end if;
  else
    new.archived_at := null;
    new.archived_by := null;
  end if;

  return new;
end $$;

drop trigger if exists trg_workflows_guard on public.workflow_definitions;
create trigger trg_workflows_guard
  before insert or update on public.workflow_definitions
  for each row execute function public.workflows_guard();

drop trigger if exists trg_workflows_updated on public.workflow_definitions;
create trigger trg_workflows_updated
  before update on public.workflow_definitions
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- 15. Lo storico delle regole, scritto dai trigger
-- ---------------------------------------------------------------------------
create or replace function public.workflows_record_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- L'attore è chi ha premuto il pulsante. Con il service role `auth.uid()` è
  -- nullo, e allora vale `updated_by`, che la Edge Function ha già verificato
  -- essere l'utente autenticato: è l'unico modo per non attribuire al «sistema»
  -- ciò che ha deciso una persona.
  --
  -- ⚠️ NESSUN RIPIEGO SU `created_by`, e la ragione è una riga di storico che
  -- avrebbe detto il falso. Quando il motore mette in pausa una regola da sé
  -- dopo errori ripetuti (§104), scrive `updated_by = null` proprio perché non
  -- l'ha decisa nessuno: con il ripiego su `created_by` lo storico avrebbe
  -- attribuito la pausa a chi la regola l'aveva SCRITTA, magari mesi prima.
  -- Un registro che attribuisce a una persona una decisione del sistema è la
  -- stessa classe di difetto del «Non assegnata ha creato l'attività» trovato
  -- nel Work Hub: non rompe niente, dice una cosa che non è vera.
  v_actor uuid := coalesce(auth.uid(), new.updated_by);
begin
  if tg_op = 'INSERT' then
    insert into public.workflow_events (company_id, workflow_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, coalesce(auth.uid(), new.created_by), 'created',
            jsonb_build_object('trigger', new.trigger_type, 'status', new.status));
    return new;
  end if;

  if new.status is distinct from old.status then
    insert into public.workflow_events (company_id, workflow_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, v_actor,
            case
              when new.status = 'active'   then 'activated'::public.workflow_audit_kind
              when new.status = 'paused'   then 'paused'::public.workflow_audit_kind
              when new.status = 'archived' then 'archived'::public.workflow_audit_kind
              when old.status = 'archived' then 'restored'::public.workflow_audit_kind
              else 'updated'::public.workflow_audit_kind
            end,
            jsonb_build_object('from', old.status, 'to', new.status,
                               'reason', new.attention_code));
  elsif new.version is distinct from old.version then
    insert into public.workflow_events (company_id, workflow_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, v_actor, 'updated',
            jsonb_build_object('version', new.version));
  end if;

  return new;
end $$;

drop trigger if exists trg_workflows_events on public.workflow_definitions;
create trigger trg_workflows_events
  after insert or update on public.workflow_definitions
  for each row execute function public.workflows_record_events();

-- ---------------------------------------------------------------------------
-- 16. Il guardiano delle esecuzioni
--
-- Le scrive solo il worker con il service role, ma la disciplina di questo
-- progetto è che una tabella si difenda comunque da sola: azienda della run =
-- azienda della regola, azienda dell'azione = azienda della run. Senza,
-- un'esecuzione potrebbe dichiarare l'azienda sbagliata e comparire nello
-- storico di chi non c'entra.
-- ---------------------------------------------------------------------------
create or replace function public.workflow_runs_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
begin
  select w.company_id into v_company
    from public.workflow_definitions w where w.id = new.workflow_id;
  if v_company is null or v_company is distinct from new.company_id then
    raise exception 'workflow_run_company_mismatch'
      using errcode = '23514', hint = 'L''esecuzione non appartiene all''azienda della regola.';
  end if;

  if new.trigger_event_id is not null and not exists (
    select 1 from public.automation_events e
    where e.id = new.trigger_event_id and e.company_id = new.company_id
  ) then
    raise exception 'workflow_run_event_mismatch'
      using errcode = '23514', hint = 'L''evento non appartiene a questa azienda.';
  end if;

  if new.completed_at is not null and new.started_at is not null then
    new.duration_ms := greatest(0, (extract(epoch from (new.completed_at - new.started_at)) * 1000)::integer);
  end if;

  return new;
end $$;

drop trigger if exists trg_workflow_runs_guard on public.workflow_runs;
create trigger trg_workflow_runs_guard
  before insert or update on public.workflow_runs
  for each row execute function public.workflow_runs_guard();

create or replace function public.workflow_action_runs_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
begin
  select r.company_id into v_company
    from public.workflow_runs r where r.id = new.workflow_run_id;
  if v_company is null or v_company is distinct from new.company_id then
    raise exception 'workflow_action_company_mismatch'
      using errcode = '23514', hint = 'L''azione non appartiene all''azienda dell''esecuzione.';
  end if;
  return new;
end $$;

drop trigger if exists trg_workflow_action_runs_guard on public.workflow_action_runs;
create trigger trg_workflow_action_runs_guard
  before insert or update on public.workflow_action_runs
  for each row execute function public.workflow_action_runs_guard();

-- ---------------------------------------------------------------------------
-- 17. Le regole che ascoltano un evento
--
-- ⚠️ QUI VIVONO DUE GARANZIE, E NESSUNA DELLE DUE È NEL WORKER.
--
--   §163 — `w.activated_at <= p_occurred_at`: una regola attivata alle 15
--   non reagisce a un documento analizzato alle 14. Attivare non fa ripartire
--   il passato, e la garanzia non è un `if` che qualcuno può dimenticare.
--
--   §69/§72 — una regola gira AL PIÙ UNA VOLTA per catena causale. È la riga
--   `not exists (… same correlation_id …)`, e da sola chiude tre casi:
--   il ciclo di una regola su sé stessa («quando nasce un'attività, crea
--   un'attività»), il ciclo A→B→A, e la ripetizione di una regola già eseguita
--   più in alto nella stessa storia. Le catene UTILI restano possibili: A che
--   causa B che causa C funziona, perché sono regole diverse.
-- ---------------------------------------------------------------------------
create or replace function public.workflows_for_event(
  p_company_id     uuid,
  p_event_type     public.automation_event_type,
  p_occurred_at    timestamptz,
  p_correlation_id uuid
)
returns table (
  id uuid, name text, version integer, trigger_type public.automation_event_type,
  condition_match text, conditions jsonb, actions jsonb
)
language sql
security definer
stable
set search_path = ''
as $$
  select w.id, w.name, w.version, w.trigger_type, w.condition_match, w.conditions, w.actions
  from public.workflow_definitions w
  where w.company_id = p_company_id
    and w.trigger_type = p_event_type
    and w.status = 'active'
    and w.activated_at is not null
    and w.activated_at <= p_occurred_at
    and not exists (
      select 1
      from public.workflow_runs r
      join public.automation_events e on e.id = r.trigger_event_id
      where r.workflow_id = w.id
        and e.correlation_id = p_correlation_id
    )
  order by w.created_at asc;
$$;

revoke all on function public.workflows_for_event(uuid, public.automation_event_type, timestamptz, uuid)
  from public, anon, authenticated;
grant execute on function public.workflows_for_event(uuid, public.automation_event_type, timestamptz, uuid)
  to service_role;

-- ---------------------------------------------------------------------------
-- 18. Le metriche di una regola (§102)
--
-- Numeri veri, non metriche di vanità: quante volte ha agito, quante azioni
-- sono andate a buon fine, quanti errori. Nessun conteggio delle volte in cui
-- non è scattata, perché quelle non sono righe (§101).
-- ---------------------------------------------------------------------------
create or replace function public.workflow_metrics(p_workflow_id uuid, p_days integer default 30)
returns table (runs integer, actions_done integer, actions_failed integer, errors integer)
language sql
stable
set search_path = ''
as $$
  with r as (
    select run.id, run.status
    from public.workflow_runs run
    join public.workflow_definitions w on w.id = run.workflow_id
    where run.workflow_id = p_workflow_id
      and (select public.is_company_member(w.company_id))
      and run.started_at >= now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 365)))
  )
  select
    (select count(*) from r)::integer,
    (select count(*) from public.workflow_action_runs a
      where a.workflow_run_id in (select id from r) and a.status = 'succeeded')::integer,
    (select count(*) from public.workflow_action_runs a
      where a.workflow_run_id in (select id from r) and a.status = 'failed')::integer,
    (select count(*) from r where r.status in ('failed', 'partial'))::integer;
$$;

revoke all on function public.workflow_metrics(uuid, integer) from public, anon;
grant execute on function public.workflow_metrics(uuid, integer) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- 19. RLS e permessi
--
-- La forma è quella di tutto il progetto: `revoke all` PRIMA dei grant, perché
-- su Supabase una tabella nuova nasce con i permessi di tabella completi per
-- `anon` e `authenticated` e un grant scritto dopo AGGIUNGE privilegi invece di
-- toglierne (lezione della 0014).
--
-- CHI LEGGE COSA
--   · `workflow_definitions`, `workflow_runs`, `workflow_action_runs`: ogni
--     MEMBRO. Non c'è niente di riservato — una regola dice cosa fa l'azienda,
--     e chi riceve un'attività creata da una regola ha diritto di sapere quale.
--   · `workflow_events` (chi ha attivato, chi ha messo in pausa): solo
--     AMMINISTRATORI, come `email_audit_log`. È informazione di governo.
--   · `automation_events`: NESSUNO oltre al service role. È la coda del motore,
--     non un dato di prodotto, e contiene la struttura della catena causale.
--
-- CHI SCRIVE: nessuno dal client, mai, su nessuna di queste tabelle.
-- ---------------------------------------------------------------------------
alter table public.automation_events     enable row level security;
alter table public.workflow_definitions  enable row level security;
alter table public.workflow_runs         enable row level security;
alter table public.workflow_action_runs  enable row level security;
alter table public.workflow_events       enable row level security;

revoke all on public.automation_events     from anon, authenticated, public;
revoke all on public.workflow_definitions  from anon, authenticated, public;
revoke all on public.workflow_runs         from anon, authenticated, public;
revoke all on public.workflow_action_runs  from anon, authenticated, public;
revoke all on public.workflow_events       from anon, authenticated, public;

grant select on public.workflow_definitions to authenticated;
grant select on public.workflow_runs        to authenticated;
grant select on public.workflow_action_runs to authenticated;
grant select on public.workflow_events      to authenticated;
-- `automation_events` NON compare: nessun grant, quindi nessuna policy potrebbe
-- comunque aprirla. È voluto — un permesso assente è più difficile da allentare
-- per sbaglio di una policy restrittiva (0013).

drop policy if exists workflows_select_member on public.workflow_definitions;
create policy workflows_select_member on public.workflow_definitions
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists workflow_runs_select_member on public.workflow_runs;
create policy workflow_runs_select_member on public.workflow_runs
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists workflow_action_runs_select_member on public.workflow_action_runs;
create policy workflow_action_runs_select_member on public.workflow_action_runs
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists workflow_events_select_admin on public.workflow_events;
create policy workflow_events_select_admin on public.workflow_events
  for select to authenticated using (public.is_company_admin(company_id));

-- ---------------------------------------------------------------------------
-- 20. Autoverifica: la migrazione controlla di aver ottenuto ciò che dichiara
--
-- Le due volte in cui questo progetto ha creduto a una garanzia senza provarla
-- — i permessi di colonna della 0013, `full-setup.sql` «rieseguibile» — la
-- garanzia non c'era. Qui la migrazione fallisce all'applicazione invece di
-- lasciar passare la falla.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
begin
  -- (a) Nessuna scrittura dal client su nessuna tabella dell'automazione.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name in ('automation_events', 'workflow_definitions', 'workflow_runs',
                       'workflow_action_runs', 'workflow_events')
    and grantee in ('anon', 'authenticated', 'public')
    and privilege_type in ('INSERT', 'UPDATE', 'DELETE', 'TRUNCATE');
  if v_bad is not null then
    raise exception 'le automazioni risultano scrivibili dal client: %', v_bad;
  end if;

  -- (b) La coda non è nemmeno leggibile: contiene la struttura delle catene
  --     causali e non serve a nessuna schermata.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name = 'automation_events'
    and grantee in ('anon', 'authenticated', 'public');
  if v_bad is not null then
    raise exception 'la coda degli eventi risulta accessibile dal client: %', v_bad;
  end if;

  -- (c) Le funzioni del solo server non sono eseguibili da un utente collegato.
  if exists (
    select 1
    from information_schema.routine_privileges
    where routine_schema = 'public'
      and routine_name in ('automation_events_claim', 'automation_emit',
                           'automation_emit_overdue', 'workflows_for_event')
      and grantee in ('anon', 'authenticated', 'public')
  ) then
    raise exception 'una funzione del motore risulta eseguibile dal client';
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0021_finance_operations  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0021 — FINANCE OPERATIONS
--
-- Fatture fornitori, ricevute e note di credito: acquisire, capire, verificare,
-- organizzare. NON è una contabilità, e la differenza non è di ambizione ma di
-- responsabilità: una contabilità afferma, questo modulo PREPARA.
--
-- ⚠️ CIÒ CHE QUESTA MIGRAZIONE NON FA, E NON PER MANCANZA DI TEMPO:
-- nessun pagamento, nessun file di pagamento, nessuna chiamata a una banca,
-- nessuna scrittura in partita doppia, nessun piano dei conti, nessuna
-- dichiarazione IVA, nessuna riconciliazione bancaria, nessuna determinazione
-- fiscale («questa spesa è deducibile»). Finché non esistono approvazioni
-- mature, integrazione bancaria, permessi granulari e riconciliazione, il
-- prodotto non deve poter muovere denaro. Comprendere e preparare, non muovere.
--
-- ⚠️ NON CREA UNA SECONDA VERITÀ SUI DOCUMENTI.
-- Il file resta del documento (Storage), il testo resta dell'estrazione, la
-- lettura amministrativa resta dell'analisi immutabile, la provenienza resta
-- dell'Inbox, il lavoro resta delle attività. Qui si aggiunge SOLO la lettura
-- finanziaria specializzata e lo stato operativo che ne deriva.
--
--   DOCUMENTO → ESTRAZIONE TESTO → ANALISI (Admin AI) → ESTRAZIONE FINANCE
--             → VERIFICA UMANA → ATTIVITÀ / AUTOMAZIONI
--
-- Requisiti: 0001–0020 applicate.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- 1. I tipi
--
-- Tutti creati con `create type … as enum (…)`: i valori dichiarati alla
-- creazione sono utilizzabili SUBITO, anche nella stessa transazione. È la
-- differenza con `alter type … add value`, che invece rende l'etichetta
-- inservibile fino al commit (55P04) — vedi il punto 2.
-- ---------------------------------------------------------------------------

-- Che cosa è il documento, dal punto di vista finanziario.
-- TRE valori e nessun «altro documento finanziario»: nel dubbio il documento
-- resta FUORI da Finance e lo si dice, invece di creare una fattura incerta che
-- poi qualcuno tratterà come certa.
do $$ begin
  create type public.finance_item_type as enum ('supplier_invoice', 'receipt', 'credit_note');
exception when duplicate_object then null; end $$;

-- A che punto è la MACCHINA. Non dice niente su che cosa debba fare una persona.
do $$ begin
  create type public.finance_processing_status as enum ('pending', 'processing', 'completed', 'failed');
exception when duplicate_object then null; end $$;

-- Che cosa deve fare una PERSONA. Deliberatamente separato dal precedente
-- (§109): «l'estrazione è fallita» e «i dati vanno verificati» sono due cose
-- diverse, e fonderle renderebbe un guasto tecnico indistinguibile dal lavoro.
--
-- ⚠️ `archived` NON è qui, benché il capitolato lo elenchi fra gli stati.
-- L'archiviazione è un `archived_at`, come su `documents` e su `tasks`: se
-- fosse anche uno stato di verifica, archiviare una fattura verificata
-- cancellerebbe l'informazione che era stata verificata.
do $$ begin
  create type public.finance_review_status as enum ('needs_review', 'ready');
exception when duplicate_object then null; end $$;

-- Chi ha deciso che questo documento è un documento finanziario.
-- Stessa forma di `document_category_source`: `rule` è la regola deterministica
-- del prodotto, `manual` una persona, `workflow` una regola scritta dall'azienda.
do $$ begin
  create type public.finance_origin as enum ('rule', 'manual', 'workflow');
exception when duplicate_object then null; end $$;

-- Da dove viene UN SINGOLO CAMPO (§101/§38). Non è una curiosità tecnica: è la
-- differenza fra «l'IBAN è scritto nel codice QR» e «l'ho letto nel testo», e
-- una persona che verifica un pagamento ha diritto di sapere quale delle due.
do $$ begin
  create type public.finance_field_source as enum ('qr', 'deterministic', 'ai', 'human');
exception when duplicate_object then null; end $$;

-- Il tipo di riferimento di pagamento secondo lo standard svizzero:
-- riferimento QR (27 cifre), riferimento creditore ISO 11649, oppure nessuno.
do $$ begin
  create type public.finance_reference_type as enum ('qrr', 'scor', 'non');
exception when duplicate_object then null; end $$;

-- Organizzazione di una spesa (§57). ⚠️ NON è un conto contabile e l'etichetta
-- nell'interfaccia dice «Categoria spesa»: chiamarla «conto» significherebbe
-- promettere una contabilità che non c'è.
do $$ begin
  create type public.finance_expense_category as enum
    ('travel', 'meals', 'office', 'software', 'vehicle', 'other');
exception when duplicate_object then null; end $$;

-- Come è stata pagata una spesa, SE il documento lo dice (§59). Fatto
-- facoltativo: non si deduce, non si presume.
do $$ begin
  create type public.finance_payment_method as enum ('card', 'cash', 'other');
exception when duplicate_object then null; end $$;

-- Esito di un tentativo di estrazione. Due valori: o ha prodotto un verbale
-- leggibile o non l'ha prodotto. Un'estrazione con campi mancanti è
-- `completed` con le sue incertezze — «incompleto» non è «fallito».
do $$ begin
  create type public.finance_extraction_status as enum ('completed', 'failed');
exception when duplicate_object then null; end $$;

-- Le bandiere di qualità (§150). Sono CHIAVI: la frase la scrive l'interfaccia
-- nella lingua di chi legge. Ognuna corrisponde a una verifica che il codice
-- esegue davvero — non esiste una bandiera che nessuno alza.
do $$ begin
  create type public.finance_quality_flag as enum (
    'amount_mismatch',        -- netto + IVA ≠ lordo oltre l'arrotondamento
    'vat_mismatch',           -- il dettaglio IVA non somma al totale IVA
    'qr_text_mismatch',       -- il codice QR e il testo dicono cose diverse
    'missing_currency',
    'missing_total',
    'missing_supplier',
    'duplicate_suspected',
    'low_ocr_confidence',
    'invalid_iban',           -- la cifra di controllo dell'IBAN non torna
    'invalid_reference',      -- il riferimento non supera il proprio controllo
    'reference_type_mismatch',-- QR-IBAN senza riferimento QR, o viceversa
    'inconsistent_due_date',  -- scadenza prima della data fattura, o diversa
                              -- da quella letta dall'analisi generale (§47)
    'ambiguous_date',         -- gg.mm o mm.gg: entrambe ≤ 12 (§118)
    'qr_not_read',            -- c'è un codice QR ma non è stato decodificato
    'negative_amount'         -- importo negativo su un documento che non è
                              -- una nota di credito
  );
exception when duplicate_object then null; end $$;

-- Lo storico (§87). Non si registra ogni visualizzazione: solo ciò che cambia.
do $$ begin
  create type public.finance_event_kind as enum (
    'created', 'extraction_completed', 'extraction_failed', 'corrected',
    'reviewed', 'reopened', 'archived', 'restored', 'type_changed',
    'category_changed', 'retry_requested'
  );
exception when duplicate_object then null; end $$;


-- ---------------------------------------------------------------------------
-- 2. I due inneschi nuovi del motore delle automazioni
--
-- ⚠️⚠️ LEGGERE PRIMA DI TOCCARE QUESTE DUE RIGHE.
--
-- `alter type … add value` si esegue dentro una transazione, ma l'etichetta NON
-- è utilizzabile finché quella transazione non è chiusa (Postgres 55P04,
-- «unsafe use of new value»). Il SQL editor di Supabase esegue tutto in
-- un'unica transazione, e `full-setup.sql` concatena TUTTE le migrazioni:
-- basta una riga che VALUTI l'etichetta appena aggiunta per far fallire ogni
-- installazione da zero. È successo con la 0015.
--
-- Qui i due valori compaiono altrove nel file, ma SOLTANTO dentro il corpo di
-- `create function`. Un corpo plpgsql viene depositato come TESTO: Postgres non
-- risolve le etichette che vi compaiono finché la funzione non viene chiamata,
-- cioè dopo il commit. Applicare questo file non le valuta mai.
--
-- ⚠️ LA 0020 SI ERA DATA UNA REGOLA PIÙ SEVERA («nemmeno dentro il corpo di una
-- funzione»), e le costava zero: i suoi tre valori nuovi li scrive il worker in
-- TypeScript, non il SQL. Qui non è possibile — un trigger che emette un evento
-- deve per forza nominare il tipo di quell'evento — e la regola va quindi presa
-- per quello che è: una precauzione prudente, non una legge di Postgres.
--
-- `npm run db:bundle` distingue ora i due casi, e la distinzione è messa alla
-- prova in ENTRAMBE le direzioni (`npm run db:bundle -- --self-test`): un
-- valore nuovo dentro un corpo di funzione passa, lo stesso valore in un indice
-- parziale, in un `insert` o in un blocco `do $$` continua a far fallire.
--
-- ⚠️ CIÒ CHE IL CONTROLLO NON PUÒ VEDERE: un blocco `do $$` che CHIAMA una
-- funzione il cui corpo nomina l'etichetta la valuterebbe comunque. Nessun
-- blocco `do $$` di questo file lo fa, e il blocco di autoverifica in fondo lo
-- rispetta deliberatamente.
--
-- ⚠️ RESTA UNA COSA DA VERIFICARE SUL DATABASE VERO, e non è verificabile qui:
-- che l'applicazione della 0021 non sollevi 55P04. `npm run test:finance`
-- controlla, subito dopo, che le due etichette esistano e che la catena
-- innesco → evento → regola funzioni davvero.
--
-- Entità: `document`. NON `finance_item`, e non per pigrizia — `automation_events`
-- e `workflow_runs` hanno un `check (entity_type in ('document','email_message',
-- 'task'))`, e un'entità nuova andrebbe cambiata in sei punti coordinati.
-- È anche la scelta giusta nel merito: una fattura è una LETTURA di un
-- documento, e una regola che parla di fatture vuole poter guardare anche la
-- categoria, il mittente e la scadenza di quel documento.
-- ---------------------------------------------------------------------------
alter type public.automation_event_type add value if not exists 'finance_item_ready';
alter type public.automation_event_type add value if not exists 'finance_item_needs_review';


-- ---------------------------------------------------------------------------
-- 3. finance_items — LO STATO OPERATIVO
--
-- Che cosa sta qui e che cosa no: qui sta ciò che una PERSONA decide (l'ho
-- verificata, l'ho archiviata, è una spesa di viaggio) e ciò che serve per
-- FILTRARE, ORDINARE e SOMMARE. I FATTI letti dal documento stanno in
-- `finance_extractions`, che è immutabile.
--
-- ⚠️ LE COLONNE `eff_*` SONO UNA PROIEZIONE, NON UNA SECONDA VERITÀ.
-- Le scrive soltanto il trigger `finance_refresh_effective`, ricalcolandole per
-- intero dall'ultima estrazione più le correzioni umane. Il client non ha alcun
-- permesso di scrittura su di esse.
--
-- Perché esistono invece di essere ricomposte in lettura come fa
-- `list_documents`: i totali per valuta (§113) sono un `sum() group by`, e
-- l'ordinamento per scadenza e il riconoscimento dei duplicati hanno bisogno di
-- indici. Su un jsonb ricomposto riga per riga non si indicizza niente e ogni
-- KPI diventerebbe una scansione di tutte le fatture dell'azienda.
-- Il precedente nel progetto è dichiarato: `email_messages.analysis_deadline` è
-- «una COPIA sulla riga del messaggio, tenuta per poter filtrare e ordinare
-- senza join». La differenza fra una proiezione e una seconda verità è che la
-- proiezione si ricalcola da sola e qualcuno lo verifica: lo fa `test:finance`.
-- ---------------------------------------------------------------------------
create table if not exists public.finance_items (
  id                    uuid primary key default gen_random_uuid(),
  company_id            uuid not null references public.companies(id) on delete cascade,
  -- Il legame forte con il documento. `on delete cascade`: se il documento
  -- sparisce non deve restare una fattura che rimanda al nulla (§90/§91).
  document_id           uuid not null references public.documents(id) on delete cascade,

  type                  public.finance_item_type not null,
  processing_status     public.finance_processing_status not null default 'pending',
  review_status         public.finance_review_status not null default 'needs_review',
  origin                public.finance_origin not null default 'rule',

  -- L'ultima estrazione RIUSCITA. La chiave esterna verso `finance_extractions`
  -- si aggiunge più sotto, quando quella tabella esiste: qui non si può.
  current_extraction_id uuid,
  extraction_attempts   integer not null default 0,
  error_code            text,

  -- Organizzazione, modificabile liberamente da una persona.
  expense_category      public.finance_expense_category,
  expense_category_set_by uuid references auth.users(id) on delete set null,
  expense_category_set_at timestamptz,
  payment_method        public.finance_payment_method,

  quality_flags         public.finance_quality_flag[] not null default '{}',

  reviewed_at           timestamptz,
  reviewed_by           uuid references auth.users(id) on delete set null,
  archived_at           timestamptz,
  archived_by           uuid references auth.users(id) on delete set null,

  created_by            uuid references auth.users(id) on delete set null,
  -- Valorizzato SOLO se l'elemento nasce lungo una catena causale prodotta da
  -- una regola aziendale. È il filo che impedisce a una catena di girare su sé
  -- stessa: senza, l'evento emesso da qui aprirebbe una catena NUOVA.
  workflow_run_id       uuid references public.workflow_runs(id) on delete set null,

  -- ---- PROIEZIONE (vedi sopra) --------------------------------------------
  eff_supplier_name     text,
  eff_supplier_norm     text,
  eff_invoice_number    text,
  eff_invoice_number_norm text,
  eff_invoice_date      date,
  eff_due_date          date,
  eff_currency          text,
  eff_gross_amount      numeric,
  eff_net_amount        numeric,
  eff_vat_amount        numeric,
  eff_iban              text,
  eff_reference_type    public.finance_reference_type,
  eff_payment_reference text,
  eff_merchant          text,
  eff_expense_date      date,
  -- Impronta per il duplicato SOSPETTO: fornitore normalizzato, numero
  -- normalizzato, importo lordo, valuta. `null` quando manca un pezzo — e in
  -- quel caso non si sospetta niente, perché sospettare su due campi su quattro
  -- produrrebbe accuse a caso.
  dup_key               text,

  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),

  -- §6 — in V1 un documento produce AL PIÙ un elemento finanziario. Se un
  -- giorno servisse spezzare un PDF con dieci fatture dentro, questo vincolo è
  -- il punto in cui la decisione andrà presa esplicitamente.
  constraint uq_finance_items_document unique (company_id, document_id),
  -- Una fattura verificata deve avere un'estrazione: «pronta» senza dati letti
  -- sarebbe una dichiarazione a vuoto.
  constraint finance_ready_needs_extraction
    check (review_status <> 'ready' or current_extraction_id is not null)
);

comment on table public.finance_items is
  'Stato operativo di un documento finanziario. I FATTI stanno in '
  'finance_extractions (immutabile) e in finance_corrections; le colonne eff_* '
  'sono una proiezione ricalcolata dal trigger, non una seconda verità.';
comment on column public.finance_items.dup_key is
  'Impronta per il duplicato sospetto. NULL quando i dati non bastano: un '
  'sospetto su informazioni parziali è un''accusa a caso.';
comment on column public.finance_items.quality_flags is
  'Che cosa non torna. Chiavi, non frasi: la frase la scrive l''interfaccia.';


-- ---------------------------------------------------------------------------
-- 4. finance_extractions — IL VERBALE, IMMUTABILE E VERSIONATO
--
-- Stessa disciplina di `document_analyses` dalla 0010: uno snapshot non si
-- corregge, si affianca. Un secondo tentativo produce la versione 2 e la 1
-- resta leggibile — è ciò che permette di rispondere a «prima diceva un altro
-- importo?» con un fatto invece che con un'impressione.
--
-- La CORREZIONE UMANA non tocca questa tabella: vive in `finance_corrections`
-- e vince in lettura (§11). Il valore originariamente letto resta sempre
-- visibile nel dettaglio.
-- ---------------------------------------------------------------------------
create table if not exists public.finance_extractions (
  id                 uuid primary key default gen_random_uuid(),
  company_id         uuid not null references public.companies(id) on delete cascade,
  finance_item_id    uuid not null references public.finance_items(id) on delete cascade,
  document_id        uuid not null references public.documents(id) on delete cascade,
  extraction_version integer not null default 1,
  status             public.finance_extraction_status not null default 'completed',

  -- Come è stato ottenuto il verbale nel suo insieme. Il dettaglio campo per
  -- campo sta in `field_sources`: un'estrazione «ibrida» è la norma, non
  -- l'eccezione — l'IBAN dal codice, il fornitore dal testo, l'IVA dal modello.
  method             text not null default 'ai',
  provider           text,
  model              text,
  prompt_version     text,
  schema_version     integer not null default 1,

  -- ---- I fatti della fattura ----------------------------------------------
  invoice_number     text,
  supplier_name      text,
  supplier_address   text,
  supplier_vat_id    text,          -- IDI/UID, quando presente e valido
  supplier_country   text,
  invoice_date       date,
  due_date           date,
  currency           text,
  -- `numeric` SENZA precisione dichiarata: esatto e senza arrotondamenti
  -- imposti dallo schema. Un `numeric(18,2)` arrotonderebbe IN SILENZIO un
  -- importo con tre decimali, che è esattamente il tipo di modifica invisibile
  -- che questo progetto non fa (§48).
  gross_amount       numeric,
  net_amount         numeric,
  vat_amount         numeric,
  -- [{ "rate": 8.1, "taxableBase": "100.00", "taxAmount": "8.10", "source": "ai" }]
  -- Gli importi sono STRINGHE decimali: passare da un numero JSON
  -- significherebbe farli transitare per un double (§48).
  vat_breakdown      jsonb not null default '[]'::jsonb,

  -- ---- Dati di pagamento ---------------------------------------------------
  -- ⚠️ Si conservano perché servono a PREPARARE il pagamento, che una persona
  -- eseguirà altrove. Non esiste, e non deve esistere, alcun percorso che li
  -- trasformi in un ordine (§43/§123).
  creditor_iban      text,
  iban_is_qr         boolean,       -- QR-IBAN (QR-IID 30000–31999): non è un
                                    -- formato diverso, è un istituto diverso,
                                    -- e determina quale riferimento è ammesso
  reference_type     public.finance_reference_type,
  payment_reference  text,

  -- ---- Codice QR svizzero --------------------------------------------------
  qr_present         boolean not null default false,
  qr_valid           boolean,
  qr_spec_version    text,          -- la versione dichiarata DAL codice letto
  qr_errors          text[] not null default '{}',

  -- ---- Ricevute / spese ----------------------------------------------------
  merchant           text,
  expense_date       date,
  payment_method_detected public.finance_payment_method,

  -- ---- Provenienza, fiducia, citazioni, incertezze -------------------------
  field_sources      jsonb not null default '{}'::jsonb,  -- campo → qr|deterministic|ai
  field_confidence   jsonb not null default '{}'::jsonb,  -- campo → 0..1 (§67)
  evidence           jsonb not null default '{}'::jsonb,  -- campo → {quote,start,end,page}
  uncertainties      jsonb not null default '[]'::jsonb,
  quality_flags      public.finance_quality_flag[] not null default '{}',
  document_language  text,

  error_code         text,
  input_tokens       integer,
  output_tokens      integer,
  duration_ms        integer,
  created_at         timestamptz not null default now(),

  constraint uq_finance_extraction_version unique (finance_item_id, extraction_version)
);

-- ⚠️ Il collegamento all'estrazione corrente si dichiara QUI e non nella
-- definizione di `finance_items`: le due tabelle si riferiscono a vicenda, e
-- alla creazione della prima la seconda non esiste ancora. `set null` e non
-- `cascade`: se un giorno si potassero i verbali vecchi, l'elemento operativo
-- deve sopravvivere alla potatura, non sparire con essa.
do $$ begin
  alter table public.finance_items
    add constraint finance_items_current_extraction_fkey
    foreign key (current_extraction_id) references public.finance_extractions(id)
    on delete set null;
exception when duplicate_object then null; end $$;

comment on table public.finance_extractions is
  'Verbale IMMUTABILE della lettura finanziaria di un documento. Un nuovo '
  'tentativo produce una versione nuova; le correzioni umane vivono altrove.';
comment on column public.finance_extractions.field_sources is
  'Da dove viene ogni campo: qr | deterministic | ai. Mescolare le origini '
  'toglierebbe a chi verifica l''unica cosa che gli serve sapere.';


-- ---------------------------------------------------------------------------
-- 5. finance_corrections — LE CORREZIONI UMANE, IN AGGIUNTA
--
-- ⚠️ PERCHÉ NON SI RIUSA `analysis_corrections`, e non è una preferenza di
-- stile. `list_documents` (0017) aggrega TUTTE le correzioni di un documento in
-- una mappa `jsonb_object_agg(field, corrected_value)` e poi fa
-- `coalesce(corrections->>'amount', a_amount)`. Una correzione finanziaria
-- salvata là con `field = 'amount'` cambierebbe l'importo che il Document Hub
-- mostra per quel documento — un campo che descrive l'analisi amministrativa,
-- non la fattura. Lo stesso vale per `deadline` (termine del documento) contro
-- `due_date` (scadenza di pagamento), che il capitolato vuole esplicitamente
-- distinti e confrontabili fra loro.
--
-- Append-only: si aggiunge, non si riscrive. L'ordine cronologico decide, e
-- l'ultima correzione di un campo vince.
-- ---------------------------------------------------------------------------
create table if not exists public.finance_corrections (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  finance_item_id uuid not null references public.finance_items(id) on delete cascade,
  document_id     uuid not null references public.documents(id) on delete cascade,
  -- Quale verbale era in vigore quando la persona ha corretto. Serve a
  -- distinguere «ha corretto ciò che vedeva» da «ha corretto una versione
  -- precedente»: `set null` perché la correzione sopravvive comunque.
  extraction_id   uuid references public.finance_extractions(id) on delete set null,
  field           text not null,
  original_value  jsonb,
  corrected_value jsonb,
  corrected_by    uuid references auth.users(id) on delete set null,
  corrected_at    timestamptz not null default now(),

  -- I campi correggibili sono un elenco CHIUSO (§152). Un campo fuori elenco
  -- non è «un campo che non conosciamo»: è una scrittura che non deve avvenire,
  -- perché la proiezione non saprebbe che farsene e il dato resterebbe invisibile.
  constraint finance_correction_field_known check (field in (
    'supplier_name', 'supplier_vat_id', 'supplier_address',
    'invoice_number', 'invoice_date', 'due_date',
    'currency', 'gross_amount', 'net_amount', 'vat_amount',
    'creditor_iban', 'payment_reference', 'reference_type',
    'merchant', 'expense_date'
  ))
);

comment on table public.finance_corrections is
  'Correzioni umane, append-only. NON riusa analysis_corrections: là il campo '
  '«amount» descrive l''analisi amministrativa del documento, e scriverci un '
  'importo di fattura cambierebbe ciò che il Document Hub mostra.';


-- ---------------------------------------------------------------------------
-- 6. finance_events — LO STORICO
--
-- Lo scrivono i trigger. Il client non può inserirlo: uno storico che una
-- schermata può fabbricare non è uno storico. Non si registra la lettura: §87
-- chiede espressamente di non tracciare ogni visualizzazione.
-- ---------------------------------------------------------------------------
create table if not exists public.finance_events (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  finance_item_id uuid not null references public.finance_items(id) on delete cascade,
  actor_user_id   uuid references auth.users(id) on delete set null,
  kind            public.finance_event_kind not null,
  detail          jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now()
);


-- ---------------------------------------------------------------------------
-- 7. finance_vat_rates — LE ALIQUOTE COME DATO, NON COME CODICE
--
-- §53: le aliquote ufficiali sono una configurazione aggiornata e versionata,
-- non una costante dentro un componente. Un'aliquota cambia per decisione
-- politica, e il giorno in cui cambierà nessuno dovrà ricompilare niente.
--
-- ⚠️ SONO SUGGERIMENTI, NON UN VALIDATORE. Un'aliquota che non compare qui —
-- una fattura del 2023, una fattura estera — è perfettamente valida e viene
-- accettata così com'è. §52 lo dice esplicitamente: non si trattano le aliquote
-- svizzere correnti come gli unici valori ammessi.
--
-- ⚠️ Le aliquote STORICHE non sono state seminate perché non sono state
-- verificate su una fonte primaria in questa sessione: la pagina dell'AFC che
-- le elenca non era leggibile. Seminarle a memoria avrebbe messo nel database
-- dei numeri fiscali non verificati, che è peggio di non averli.
-- ---------------------------------------------------------------------------
create table if not exists public.finance_vat_rates (
  id            uuid primary key default gen_random_uuid(),
  country_code  text not null,
  kind          text not null,        -- standard | reduced | special
  rate          numeric not null,
  valid_from    date not null,
  valid_to      date,
  source_url    text not null,
  source_title  text,
  checked_at    date not null,
  created_at    timestamptz not null default now(),
  constraint uq_vat_rate unique (country_code, kind, valid_from)
);

insert into public.finance_vat_rates (country_code, kind, rate, valid_from, valid_to, source_url, source_title, checked_at)
values
  ('CH', 'standard', 8.1, date '2024-01-01', null,
   'https://www.estv.admin.ch/estv/de/home/mehrwertsteuer/mwst-steuersaetze.html',
   'Eidgenössische Steuerverwaltung — Schweizer Mehrwertsteuersätze', date '2026-07-27'),
  ('CH', 'reduced', 2.6, date '2024-01-01', null,
   'https://www.estv.admin.ch/estv/de/home/mehrwertsteuer/mwst-steuersaetze.html',
   'Eidgenössische Steuerverwaltung — Schweizer Mehrwertsteuersätze', date '2026-07-27'),
  ('CH', 'special', 3.8, date '2024-01-01', null,
   'https://www.estv.admin.ch/estv/de/home/mehrwertsteuer/mwst-steuersaetze.html',
   'Eidgenössische Steuerverwaltung — Schweizer Mehrwertsteuersätze', date '2026-07-27')
on conflict (country_code, kind, valid_from) do nothing;

comment on table public.finance_vat_rates is
  'Aliquote IVA ufficiali con validità e fonte. Sono SUGGERIMENTI per la '
  'correzione manuale: un''aliquota fuori elenco è accettata, non rifiutata.';


-- ---------------------------------------------------------------------------
-- 8. Indici
--
-- Ognuno corrisponde a una clausola che le funzioni di questo file scrivono
-- davvero. Nessun indice «per sicurezza»: un indice che nessuna query usa è
-- solo scrittura più lenta.
-- ---------------------------------------------------------------------------

-- La lista predefinita: elementi non archiviati di un'azienda, per tipo.
create index if not exists idx_finance_active
  on public.finance_items (company_id, type, created_at desc)
  where archived_at is null;

-- «Che cosa scade nei prossimi sette giorni» e «che cosa è già scaduto»: sono
-- i due numeri della dashboard, e girano su ogni caricamento della pagina.
create index if not exists idx_finance_due
  on public.finance_items (company_id, eff_due_date)
  where archived_at is null;

-- «Che cosa devo ancora verificare»: il primo KPI e il filtro rapido.
create index if not exists idx_finance_review
  on public.finance_items (company_id, review_status)
  where archived_at is null;

-- La coda del worker: quali elementi aspettano di essere letti.
create index if not exists idx_finance_pending
  on public.finance_items (processing_status, created_at)
  where processing_status in ('pending', 'processing');

-- Il duplicato sospetto: si cercano gli altri elementi con la stessa impronta
-- NELLA STESSA AZIENDA. Senza indice sarebbe una scansione per ogni riga della
-- lista.
create index if not exists idx_finance_dup
  on public.finance_items (company_id, dup_key)
  where dup_key is not null and archived_at is null;

-- Ricerca per fornitore e per numero di fattura (§26), sulla forma normalizzata.
create index if not exists idx_finance_supplier
  on public.finance_items (company_id, eff_supplier_norm);
create index if not exists idx_finance_invoice_no
  on public.finance_items (company_id, eff_invoice_number_norm);

-- Dal documento all'elemento finanziario: lo chiede il dettaglio del documento.
create index if not exists idx_finance_document
  on public.finance_items (document_id);

create index if not exists idx_finance_extractions_item
  on public.finance_extractions (finance_item_id, extraction_version desc);
create index if not exists idx_finance_corrections_item
  on public.finance_corrections (finance_item_id, corrected_at);
create index if not exists idx_finance_events_item
  on public.finance_events (finance_item_id, created_at desc);


-- ---------------------------------------------------------------------------
-- 9. Normalizzazione per il confronto
--
-- ⚠️ NORMALIZZARE NON È RIPULIRE. Queste funzioni producono una chiave di
-- CONFRONTO; il valore mostrato all'utente resta quello letto. «Swisscom (Svizzera) SA»
-- si mostra così com'è, e si confronta come «swisscom svizzera sa».
--
-- §157 avverte di non rimuovere caratteri significativi con leggerezza: in un
-- numero di fattura il trattino può separare l'anno dal progressivo, e togliere
-- tutto renderebbe «2026-1» uguale a «20261». Qui si tolgono solo spazi e
-- punteggiatura di contorno, non le cifre né le lettere.
-- ---------------------------------------------------------------------------
create or replace function public.finance_norm_supplier(p_name text)
returns text
language sql
immutable
set search_path = ''
as $$
  -- ⚠️ L'elenco delle lettere accentate è COMPLETO per le lingue che il prodotto
  -- incontra. Una versione parziale sarebbe peggio di nessuna: «é» resterebbe
  -- una lettera e «ê» diventerebbe un separatore, e due grafie dello stesso
  -- nome si normalizzerebbero in modi diversi a seconda dell'accento.
  select nullif(
    btrim(regexp_replace(
      regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9àáâäèéêëìíîïòóôöùúûüçñ]+', ' ', 'g'),
      '\s+', ' ', 'g')),
    '');
$$;

comment on function public.finance_norm_supplier(text) is
  'Chiave di confronto per il nome di un fornitore. NON è un''identità: '
  '«Swisscom» e «Swisscom SA» restano soggetti diversi finché nessuno dice il '
  'contrario (§32). Serve solo a sospettare un duplicato, mai a fondere.';

create or replace function public.finance_norm_invoice_number(p_number text)
returns text
language sql
immutable
set search_path = ''
as $$
  -- Si tolgono spazi e i separatori di contorno, si tengono lettere e cifre.
  -- «N. 847291», «847291» e «847 291» sono lo stesso numero; «2026-1» e «20261»
  -- restano distinti, perché il trattino lì porta informazione.
  select nullif(upper(regexp_replace(coalesce(p_number, ''), '[\s.#]+', '', 'g')), '');
$$;

-- L'impronta del duplicato sospetto (§70).
-- Torna NULL se manca uno qualsiasi dei quattro elementi: con due campi su
-- quattro il sospetto sarebbe casuale, e un falso sospetto insegna a ignorare
-- i sospetti.
create or replace function public.finance_dup_key(
  p_supplier_norm text,
  p_number_norm   text,
  p_gross         numeric,
  p_currency      text
)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_supplier_norm is null or p_number_norm is null
      or p_gross is null or p_currency is null then null
    else p_supplier_norm || '|' || p_number_norm || '|'
      || trim(to_char(p_gross, 'FM9999999999999990.0999999')) || '|' || upper(p_currency)
  end;
$$;


-- ---------------------------------------------------------------------------
-- 10. Il classificatore deterministico (§62)
--
-- Nessuna chiamata AI: il documento è GIÀ stato analizzato, e da quell'analisi
-- si capisce se è un documento finanziario. Dove il segnale non basta si torna
-- NULL, e il documento NON entra in Finance — §15: nel dubbio non si crea una
-- fattura certa. Chi vuole comunque metterlo dentro usa «Aggiungi a Finanze»,
-- che è un gesto umano ed esplicito.
--
-- ⚠️ Deliberatamente NON classificati: `payment_request` e `reminder` da enti
-- pubblici. Un sollecito dell'AFC è una richiesta di pagamento, ma non è una
-- fattura fornitore: metterlo fra le fatture da verificare mescolerebbe
-- imposte e acquisti, che è proprio la confusione che il modulo deve evitare.
-- Un sollecito PRIVATO invece riguarda quasi sempre una fattura già ricevuta,
-- e infatti la 0017 lo classifica già nella categoria «Fatture».
-- ---------------------------------------------------------------------------
create or replace function public.finance_type_from_analysis(
  p_document_type  text,
  p_authority_type text
)
returns public.finance_item_type
language sql
immutable
set search_path = ''
as $$
  select case
    -- Il segnale più forte: l'analisi dice che è una fattura.
    when p_document_type = 'invoice' then 'supplier_invoice'::public.finance_item_type
    -- Una richiesta di pagamento da un privato è una fattura fornitore.
    when p_document_type = 'payment_request' and p_authority_type = 'private'
      then 'supplier_invoice'::public.finance_item_type
    -- Un sollecito da un privato riguarda una fattura: si tratta come tale, e
    -- la verifica umana dirà se è un doppione di una già registrata.
    when p_document_type = 'reminder' and p_authority_type = 'private'
      then 'supplier_invoice'::public.finance_item_type
    else null
  end;
$$;

comment on function public.finance_type_from_analysis(text, text) is
  'Tipo finanziario dedotto dall''analisi. NULL quando il segnale non basta: '
  'un documento fuori da Finance è un fatto, una fattura inventata è un errore '
  'che qualcuno tratterà come vero.';


-- ---------------------------------------------------------------------------
-- 11. La cifra di controllo dell'IBAN, in SQL
--
-- ⚠️ È UN DOPPIONE DICHIARATO di `checkIban()` in
-- `supabase/functions/_shared/finance/checksums.ts`, e lo è per una ragione che
-- vale la pena scrivere: quando una PERSONA corregge a mano un IBAN (§152/§153,
-- il campo a rischio più alto del modulo), la correzione entra dal client e la
-- bandiera `invalid_iban` va RICALCOLATA. Farlo chiamando il TypeScript
-- vorrebbe dire far ripartire il worker — e quindi una chiamata AI a pagamento —
-- per una modifica che una persona ha già fatto a mano.
--
-- ⚠️ E COME PER `urgencyFrom` DELLE AUTOMAZIONI, LA COPIA NON È LASCIATA ALLA
-- BUONA FEDE: `test:finance` confronta questa funzione con quella TypeScript su
-- una matrice di IBAN validi e non validi, e fallisce se divergono su un caso.
-- ---------------------------------------------------------------------------
create or replace function public.finance_iban_valid(p_iban text)
returns boolean
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_clean     text;
  v_rearr     text;
  v_digits    text := '';
  v_ch        text;
  v_remainder integer := 0;
  i           integer;
begin
  v_clean := upper(regexp_replace(coalesce(p_iban, ''), '[\s\-.]', '', 'g'));
  if v_clean !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]+$' then return false; end if;
  if length(v_clean) < 15 or length(v_clean) > 34 then return false; end if;

  -- Le lunghezze note per paese: dove non si conosce il valore ufficiale non si
  -- inventa un limite, si verifica solo la cifra di controllo.
  if left(v_clean, 2) in ('CH', 'LI') and length(v_clean) <> 21 then return false; end if;
  if left(v_clean, 2) = 'DE' and length(v_clean) <> 22 then return false; end if;
  if left(v_clean, 2) = 'AT' and length(v_clean) <> 20 then return false; end if;
  if left(v_clean, 2) in ('FR', 'IT') and length(v_clean) <> 27 then return false; end if;

  v_rearr := substr(v_clean, 5) || left(v_clean, 4);
  for i in 1 .. length(v_rearr) loop
    v_ch := substr(v_rearr, i, 1);
    if v_ch ~ '[0-9]' then
      v_digits := v_digits || v_ch;
    else
      v_digits := v_digits || (ascii(v_ch) - 55)::text;
    end if;
  end loop;

  -- Modulo 97 a blocchi: il numero intero supererebbe qualunque tipo numerico.
  for i in 1 .. ceil(length(v_digits) / 7.0)::integer loop
    v_remainder := (v_remainder::text || substr(v_digits, (i - 1) * 7 + 1, 7))::bigint % 97;
  end loop;

  return v_remainder = 1;
end $$;

comment on function public.finance_iban_valid(text) is
  'Cifra di controllo IBAN (ISO 7064 MOD 97-10). Doppione DICHIARATO di '
  'checkIban() in _shared/finance/checksums.ts, confrontato dal test. Dice che '
  'il numero è trascritto bene, NON che il conto esista o sia del fornitore.';


-- ---------------------------------------------------------------------------
-- 12. Il guardiano di `finance_items`
--
-- Chi ha verificato, chi ha archiviato, chi ha scelto la categoria di spesa e
-- quando: lo scrive il database da `auth.uid()` e `now()`, mai il client (§85/§94).
-- Il client dichiara l'INTENZIONE — mette un `archived_at` qualsiasi — e il
-- valore vero lo mette qui.
--
-- Il worker gira con il service role e senza utente: `auth.uid()` è NULL, ed è
-- giusto che `reviewed_by` resti NULL invece di essere attribuito a qualcuno.
-- Attribuire a una persona un'azione della macchina è un dato inventato.
-- ---------------------------------------------------------------------------
create or replace function public.finance_items_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    -- Il documento deve essere dell'azienda dichiarata. La RLS lo impedirebbe
    -- comunque dal client, ma questa funzione è `security definer` e deve
    -- difendersi da sola: è la disciplina della 0017.
    if not exists (
      select 1 from public.documents d
      where d.id = new.document_id and d.company_id = new.company_id
    ) then
      raise exception 'finance_document_company_mismatch'
        using errcode = '23514',
              hint = 'Il documento non appartiene all''azienda indicata.';
    end if;

    new.created_by := auth.uid();

    -- ⚠️ CHI HA DECISO CHE QUESTO DOCUMENTO È UNA FATTURA lo stabilisce il
    -- database, non chi scrive. Il client non ha il permesso di colonna su
    -- `origin`, quindi un inserimento dall'interfaccia prenderebbe il valore
    -- predefinito `rule` — e l'elemento direbbe di essere stato riconosciuto
    -- dalla regola quando invece l'ha aggiunto una persona con «Aggiungi a
    -- Finanze». Sarebbe una provenienza falsa proprio sul campo che serve a
    -- distinguere le due cose.
    --
    -- La distinzione sistema/persona è la stessa di `documents_guard`:
    -- `auth.uid()` da solo non basta, perché in modalità deterministica è il
    -- BROWSER a inserire l'analisi, e la classificazione automatica che ne
    -- deriva scatta quindi con un utente in sessione. `pg_trigger_depth() > 1`
    -- dice che a scrivere è stato un trigger, cioè il prodotto.
    if auth.uid() is not null and pg_trigger_depth() <= 1 then
      new.origin := 'manual';
    end if;
    new.reviewed_at := null;
    new.reviewed_by := null;
    new.archived_by := null;
    if new.archived_at is not null then new.archived_at := now(); end if;
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;

  -- ---- UPDATE ------------------------------------------------------------
  new.company_id  := old.company_id;
  new.document_id := old.document_id;
  new.created_by  := old.created_by;
  new.created_at  := old.created_at;
  new.updated_at  := now();

  -- Verifica: il timbro si scrive alla transizione, e non si riscrive se lo
  -- stato non cambia. Riaprire cancella il timbro, perché non è più vero che
  -- qualcuno l'abbia verificata.
  if new.review_status is distinct from old.review_status then
    if new.review_status = 'ready' then
      new.reviewed_at := now();
      new.reviewed_by := auth.uid();
    else
      new.reviewed_at := null;
      new.reviewed_by := null;
    end if;
  else
    new.reviewed_at := old.reviewed_at;
    new.reviewed_by := old.reviewed_by;
  end if;

  -- Archiviazione: solo alla PRIMA, come su `documents`.
  if new.archived_at is not null and old.archived_at is null then
    new.archived_at := now();
    new.archived_by := auth.uid();
  elsif new.archived_at is null then
    new.archived_by := null;
  else
    new.archived_at := old.archived_at;
    new.archived_by := old.archived_by;
  end if;

  if new.expense_category is distinct from old.expense_category then
    new.expense_category_set_by := auth.uid();
    new.expense_category_set_at := now();
  else
    new.expense_category_set_by := old.expense_category_set_by;
    new.expense_category_set_at := old.expense_category_set_at;
  end if;

  -- ⚠️ La PROIEZIONE non è scrivibile da nessun percorso applicativo: la
  -- ricalcola `finance_refresh_effective`. Un update che la toccasse — anche
  -- per sbaglio, anche dal service role — viene annullato qui.
  --
  -- ⚠️ LA SENTINELLA È ESPLICITA E NON `pg_trigger_depth()`.
  -- La prima versione confrontava la profondità dei trigger, dando per scontato
  -- che il ricalcolo arrivasse sempre da un altro trigger. Ma
  -- `finance_refresh_effective` è chiamabile anche direttamente — dal worker
  -- con il service role, o da uno script di ripopolamento — e in quel caso il
  -- suo UPDATE fa scattare questo guardiano a profondità 1: la condizione
  -- sarebbe vera e la proiezione appena calcolata verrebbe RIMESSA COM'ERA,
  -- riga per riga, senza alcun errore. I totali della dashboard resterebbero
  -- vuoti e nessuno saprebbe perché. Una sentinella che dipende da COME si
  -- arriva a una funzione, invece che da CHE COSA la funzione sta facendo, è
  -- un difetto in attesa del primo chiamante diverso.
  if coalesce(current_setting('ai_swisse.finance_refresh', true), '') <> '1' then
    new.eff_supplier_name       := old.eff_supplier_name;
    new.eff_supplier_norm       := old.eff_supplier_norm;
    new.eff_invoice_number      := old.eff_invoice_number;
    new.eff_invoice_number_norm := old.eff_invoice_number_norm;
    new.eff_invoice_date        := old.eff_invoice_date;
    new.eff_due_date            := old.eff_due_date;
    new.eff_currency            := old.eff_currency;
    new.eff_gross_amount        := old.eff_gross_amount;
    new.eff_net_amount          := old.eff_net_amount;
    new.eff_vat_amount          := old.eff_vat_amount;
    new.eff_iban                := old.eff_iban;
    new.eff_reference_type      := old.eff_reference_type;
    new.eff_payment_reference   := old.eff_payment_reference;
    new.eff_merchant            := old.eff_merchant;
    new.eff_expense_date        := old.eff_expense_date;
    new.dup_key                 := old.dup_key;
    new.quality_flags           := old.quality_flags;
  end if;

  -- Rimettere in coda è un'azione legittima («Riprova estrazione», §111) e non
  -- richiede una Edge Function: il worker periodico la raccoglie. Ma si può
  -- ripartire solo da uno stato FERMO — rimettere in coda qualcosa che è già in
  -- lavorazione produrrebbe due estrazioni concorrenti sullo stesso documento.
  if new.processing_status = 'pending' and old.processing_status = 'processing' then
    new.processing_status := old.processing_status;
  end if;

  return new;
end $$;

drop trigger if exists trg_finance_items_guard on public.finance_items;
create trigger trg_finance_items_guard
  before insert or update on public.finance_items
  for each row execute function public.finance_items_guard();


-- ---------------------------------------------------------------------------
-- 13. La proiezione dei valori effettivi
--
-- Ricalcola `eff_*`, `dup_key` e le bandiere che dipendono dai valori
-- effettivi, a partire da: ultima estrazione riuscita + tutte le correzioni
-- umane in ordine cronologico (l'ultima di ogni campo vince). È la stessa
-- regola di `list_documents`, e averne una sola è il motivo per cui due
-- schermate non possono dire due importi diversi sulla stessa fattura.
--
-- ⚠️ QUALI BANDIERE SI RICALCOLANO QUI E QUALI NO, e perché.
--   · si RICALCOLANO quelle che sono un confronto fra valori effettivi:
--     importi che non tornano, scadenza prima della fattura, dati mancanti,
--     IBAN che non supera la cifra di controllo, duplicato sospetto.
--     Sono aritmetica e confronti, non algoritmi da duplicare, e devono
--     cambiare quando una persona corregge il dato.
--   · si CONSERVANO dall'estrazione quelle che descrivono COME è andata la
--     lettura: il codice QR in disaccordo col testo, la trascrizione poco
--     leggibile, la data ambigua, il codice QR non decodificato. Nessuna
--     correzione umana le rende false, e cancellarle significherebbe far
--     sparire la ragione per cui qualcuno deve guardare il documento.
-- ---------------------------------------------------------------------------
create or replace function public.finance_refresh_effective(p_item_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item    record;
  v_ex      record;
  v_corr    jsonb := '{}'::jsonb;
  v_flags   public.finance_quality_flag[] := '{}';
  v_keep    public.finance_quality_flag[];
  v_supplier text; v_number text; v_currency text;
  v_gross numeric; v_net numeric; v_vat numeric;
  v_invoice_date date; v_due_date date; v_expense_date date;
  v_iban text; v_reference text; v_ref_type public.finance_reference_type;
  v_merchant text;
  v_supplier_norm text; v_number_norm text; v_dup text;
  v_tolerance numeric;
  v_vat_lines integer;
  v_analysis_deadline date;
begin
  select * into v_item from public.finance_items where id = p_item_id;
  if v_item.id is null then return; end if;

  select * into v_ex from public.finance_extractions
   where id = v_item.current_extraction_id and company_id = v_item.company_id;

  -- Le correzioni, in ordine: l'ultima di ogni campo vince.
  select coalesce(jsonb_object_agg(c.field, c.corrected_value), '{}'::jsonb)
    into v_corr
    from (
      select c2.field, c2.corrected_value
        from public.finance_corrections c2
       where c2.finance_item_id = p_item_id and c2.company_id = v_item.company_id
       order by c2.corrected_at asc
    ) c;

  -- ⚠️ `try_date` / `try_numeric` (0017) e non un cast diretto: una correzione
  -- malformata farebbe fallire l'intero ricalcolo, e con esso ogni scrittura
  -- sulla fattura. Il guardiano delle correzioni rifiuta già i valori non
  -- convertibili, quindi qui non dovrebbero arrivarne — ma «non dovrebbero» non
  -- è una garanzia, e il costo di questa difesa è nullo.
  v_supplier      := coalesce(v_corr ->> 'supplier_name', v_ex.supplier_name);
  v_number        := coalesce(v_corr ->> 'invoice_number', v_ex.invoice_number);
  v_currency      := upper(coalesce(v_corr ->> 'currency', v_ex.currency));
  v_gross         := coalesce(public.try_numeric(v_corr ->> 'gross_amount'), v_ex.gross_amount);
  v_net           := coalesce(public.try_numeric(v_corr ->> 'net_amount'), v_ex.net_amount);
  v_vat           := coalesce(public.try_numeric(v_corr ->> 'vat_amount'), v_ex.vat_amount);
  v_invoice_date  := coalesce(public.try_date(v_corr ->> 'invoice_date'), v_ex.invoice_date);
  v_due_date      := coalesce(public.try_date(v_corr ->> 'due_date'), v_ex.due_date);
  v_expense_date  := coalesce(public.try_date(v_corr ->> 'expense_date'), v_ex.expense_date);
  v_iban          := upper(regexp_replace(
                       coalesce(v_corr ->> 'creditor_iban', v_ex.creditor_iban, ''), '[\s\-.]', '', 'g'));
  v_iban          := nullif(v_iban, '');
  v_reference     := coalesce(v_corr ->> 'payment_reference', v_ex.payment_reference);
  v_merchant      := coalesce(v_corr ->> 'merchant', v_ex.merchant);
  v_ref_type      := coalesce(
                       (case when v_corr ? 'reference_type'
                             and (v_corr ->> 'reference_type') in ('qrr', 'scor', 'non')
                             then (v_corr ->> 'reference_type')::public.finance_reference_type end),
                       v_ex.reference_type);

  v_supplier_norm := public.finance_norm_supplier(v_supplier);
  v_number_norm   := public.finance_norm_invoice_number(v_number);
  v_dup           := public.finance_dup_key(v_supplier_norm, v_number_norm, v_gross, v_currency);

  -- ---- Bandiere conservate dall'estrazione --------------------------------
  v_keep := coalesce(v_ex.quality_flags, '{}');
  v_flags := array(
    select f from unnest(v_keep) f
     where f in ('qr_text_mismatch', 'low_ocr_confidence', 'ambiguous_date',
                 'qr_not_read', 'vat_mismatch')
  );

  -- ---- Bandiere ricalcolate ------------------------------------------------
  if v_gross is null then v_flags := v_flags || 'missing_total'::public.finance_quality_flag; end if;
  if v_currency is null then v_flags := v_flags || 'missing_currency'::public.finance_quality_flag; end if;
  if v_supplier_norm is null and v_merchant is null then
    v_flags := v_flags || 'missing_supplier'::public.finance_quality_flag;
  end if;

  -- Coerenza degli importi. La tolleranza è di un centesimo per aliquota:
  -- l'arrotondamento di riga è reale e segnalare una fattura corretta
  -- insegnerebbe a ignorare le segnalazioni (§51).
  if v_gross is not null and v_net is not null and v_vat is not null then
    v_vat_lines := greatest(1, least(coalesce(jsonb_array_length(v_ex.vat_breakdown), 1), 10));
    v_tolerance := v_vat_lines * 0.01;
    if abs(v_gross - (v_net + v_vat)) > v_tolerance then
      v_flags := v_flags || 'amount_mismatch'::public.finance_quality_flag;
    end if;
  end if;

  -- Un importo negativo su una fattura non è una fattura: è una nota di
  -- credito che qualcuno ha classificato male.
  if v_gross is not null and v_gross < 0 and v_item.type <> 'credit_note' then
    v_flags := v_flags || 'negative_amount'::public.finance_quality_flag;
  end if;

  -- Scadenza prima della data di fattura: le due date si contraddicono.
  if v_invoice_date is not null and v_due_date is not null and v_due_date < v_invoice_date then
    v_flags := v_flags || 'inconsistent_due_date'::public.finance_quality_flag;
  end if;

  -- §47 — la scadenza letta dall'analisi amministrativa e quella della fattura
  -- descrivono la stessa cosa: se differiscono NON si sceglie in silenzio, si
  -- dichiara l'incoerenza e la decide una persona.
  if v_due_date is not null then
    select a.deadline into v_analysis_deadline
      from public.document_analyses a
     where a.document_id = v_item.document_id and a.company_id = v_item.company_id
       and a.analysis_status <> 'failed'
     order by a.created_at desc limit 1;
    if v_analysis_deadline is not null and v_analysis_deadline <> v_due_date then
      v_flags := v_flags || 'inconsistent_due_date'::public.finance_quality_flag;
    end if;
  end if;

  if v_iban is not null and not public.finance_iban_valid(v_iban) then
    v_flags := v_flags || 'invalid_iban'::public.finance_quality_flag;
  end if;

  -- ⚠️ IL DUPLICATO SOSPETTO NON SI MEMORIZZA, SI CALCOLA.
  -- Una prima versione lo scriveva fra le bandiere e aggiornava anche la
  -- controparte. Ma il sospetto dipende da CHE COSA C'È INTORNO, e cambia senza
  -- che questa riga venga toccata: basta archiviare l'altra fattura, o
  -- correggerne il numero, perché la bandiera memorizzata resti accesa su un
  -- duplicato che non esiste più. Si calcola dove serve — `list_finance_items`
  -- lo aggiunge alle bandiere di ogni riga — e così non può invecchiare.
  -- L'etichetta resta nell'enum perché è il vocabolario con cui l'interfaccia
  -- spiega perché una fattura va guardata.

  -- Da qui il guardiano sa che a scrivere la proiezione è il ricalcolo, e non
  -- la annulla. `true` = valido per la sola transazione corrente: non resta
  -- acceso e non può essere sfruttato da una scrittura successiva.
  perform set_config('ai_swisse.finance_refresh', '1', true);

  update public.finance_items set
    eff_supplier_name       = v_supplier,
    eff_supplier_norm       = v_supplier_norm,
    eff_invoice_number      = v_number,
    eff_invoice_number_norm = v_number_norm,
    eff_invoice_date        = v_invoice_date,
    eff_due_date            = v_due_date,
    eff_currency            = v_currency,
    eff_gross_amount        = v_gross,
    eff_net_amount          = v_net,
    eff_vat_amount          = v_vat,
    eff_iban                = v_iban,
    eff_reference_type      = v_ref_type,
    eff_payment_reference   = v_reference,
    eff_merchant            = v_merchant,
    eff_expense_date        = v_expense_date,
    dup_key                 = v_dup,
    quality_flags           = (select array(select distinct f from unnest(v_flags) f order by f))
  where id = p_item_id;

  perform set_config('ai_swisse.finance_refresh', '0', true);
end $$;

revoke all on function public.finance_refresh_effective(uuid) from public, anon, authenticated;


-- ---------------------------------------------------------------------------
-- 14. Le estrazioni sono IMMUTABILI
--
-- Stessa disciplina della 0010 sulle analisi. Non basta togliere il permesso al
-- client: il divieto vale anche per il service role, perché il worker gira
-- proprio con quello e un giorno qualcuno potrebbe pensare di «aggiornare»
-- un'estrazione invece di scriverne una nuova. Un verbale che si corregge non
-- è un verbale.
-- ---------------------------------------------------------------------------
create or replace function public.finance_extractions_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'finance_extraction_immutable'
    using errcode = '42501',
          hint = 'Un''estrazione non si modifica e non si cancella: se ne scrive una versione nuova.';
end $$;

drop trigger if exists trg_finance_extractions_immutable on public.finance_extractions;
create trigger trg_finance_extractions_immutable
  before update or delete on public.finance_extractions
  for each row execute function public.finance_extractions_immutable();


-- ---------------------------------------------------------------------------
-- 15. L'autore di una correzione è chi la scrive
--
-- ⚠️ RIFIUTA, non riscrive in silenzio. È la lezione dei commenti delle
-- attività (0016): la versione precedente sostituiva l'autore con `auth.uid()`
-- e restituiva «inserito». Il risultato era sicuro — nessuna firma falsa è mai
-- finita nel database — ma chi provava a firmare come un collega riceveva una
-- conferma. Un fallback silenzioso resta un fallback silenzioso anche quando il
-- suo esito è innocuo.
-- ---------------------------------------------------------------------------
create or replace function public.finance_corrections_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item record;
begin
  select f.id, f.company_id, f.document_id, f.current_extraction_id
    into v_item
    from public.finance_items f
   where f.id = new.finance_item_id;

  if v_item.id is null or v_item.company_id is distinct from new.company_id then
    raise exception 'finance_correction_company_mismatch'
      using errcode = '23514',
            hint = 'La correzione non appartiene all''azienda dell''elemento finanziario.';
  end if;

  if auth.uid() is not null and new.corrected_by is not null
     and new.corrected_by is distinct from auth.uid() then
    raise exception 'finance_correction_author_mismatch'
      using errcode = '42501',
            hint = 'Una correzione si firma con il proprio nome.';
  end if;

  -- ⚠️ IL VALORE VA VERIFICATO QUI, NON A VALLE.
  -- Il ricalcolo della proiezione converte con `try_date`/`try_numeric`, che
  -- tornano NULL su un testo non convertibile e fanno quindi ripiegare sul
  -- valore dell'estrazione. Conseguenza: una correzione con un valore
  -- malformato verrebbe SALVATA, comparirebbe fra i «campi corretti a mano», e
  -- la schermata continuerebbe a mostrare il valore vecchio — una persona
  -- convinta di aver corretto un importo, e un importo che non è cambiato.
  -- È esattamente il fallback silenzioso che questo progetto non ammette: si
  -- rifiuta all'ingresso, con un codice che l'interfaccia sa tradurre.
  if new.corrected_value is not null and jsonb_typeof(new.corrected_value) <> 'null' then
    if new.field in ('invoice_date', 'due_date', 'expense_date')
       and public.try_date(new.corrected_value #>> '{}') is null then
      raise exception 'finance_correction_bad_date'
        using errcode = '22007', hint = 'La data non è in un formato riconoscibile.';
    end if;
    if new.field in ('gross_amount', 'net_amount', 'vat_amount')
       and public.try_numeric(new.corrected_value #>> '{}') is null then
      raise exception 'finance_correction_bad_amount'
        using errcode = '22P02', hint = 'L''importo non è un numero.';
    end if;
    if new.field = 'currency'
       and upper(new.corrected_value #>> '{}') !~ '^[A-Z]{3}$' then
      raise exception 'finance_correction_bad_currency'
        using errcode = '22P02', hint = 'La valuta è un codice ISO di tre lettere.';
    end if;
    if new.field = 'reference_type'
       and lower(new.corrected_value #>> '{}') not in ('qrr', 'scor', 'non') then
      raise exception 'finance_correction_bad_reference_type'
        using errcode = '22P02', hint = 'Il tipo di riferimento non è previsto.';
    end if;
    -- L'IBAN corretto a mano deve almeno superare la propria cifra di
    -- controllo: è il campo a rischio più alto del modulo (§153), e un IBAN
    -- che non torna è quasi sempre un refuso di trascrizione.
    if new.field = 'creditor_iban'
       and not public.finance_iban_valid(new.corrected_value #>> '{}') then
      raise exception 'finance_correction_bad_iban'
        using errcode = '22P02', hint = 'L''IBAN non supera la cifra di controllo.';
    end if;
  end if;

  new.corrected_by := coalesce(auth.uid(), new.corrected_by);
  new.corrected_at := now();
  -- Il documento e il verbale di riferimento li stabilisce il database: sono
  -- deducibili dall'elemento, e farli dichiarare al client vorrebbe dire
  -- permettergli di agganciare una correzione al documento sbagliato.
  new.document_id  := v_item.document_id;
  new.extraction_id := v_item.current_extraction_id;
  return new;
end $$;

drop trigger if exists trg_finance_corrections_guard on public.finance_corrections;
create trigger trg_finance_corrections_guard
  before insert on public.finance_corrections
  for each row execute function public.finance_corrections_guard();

-- Una correzione non si modifica e non si cancella: append-only.
create or replace function public.finance_corrections_append_only()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'finance_correction_append_only'
    using errcode = '42501',
          hint = 'Le correzioni si aggiungono: per cambiare un valore se ne scrive una nuova.';
end $$;

drop trigger if exists trg_finance_corrections_append_only on public.finance_corrections;
create trigger trg_finance_corrections_append_only
  before update or delete on public.finance_corrections
  for each row execute function public.finance_corrections_append_only();


-- ---------------------------------------------------------------------------
-- 16. Il ricalcolo scatta da solo
--
-- Una nuova estrazione o una nuova correzione cambiano i valori effettivi: la
-- proiezione si aggiorna qui, non nel codice applicativo. Farlo dal servizio
-- coprirebbe solo i percorsi a cui qualcuno ha pensato — e i percorsi che
-- scrivono su queste tabelle sono già tre (worker, interfaccia, script).
-- ---------------------------------------------------------------------------
create or replace function public.finance_after_correction()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.finance_refresh_effective(new.finance_item_id);
  insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
  values (new.company_id, new.finance_item_id, new.corrected_by, 'corrected',
          jsonb_build_object('field', new.field));
  return new;
end $$;

drop trigger if exists trg_finance_after_correction on public.finance_corrections;
create trigger trg_finance_after_correction
  after insert on public.finance_corrections
  for each row execute function public.finance_after_correction();

create or replace function public.finance_after_extraction()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Solo un'estrazione RIUSCITA diventa quella corrente: un tentativo fallito
  -- non deve sostituire un verbale buono precedente. È la stessa regola di
  -- `markFailed()` per le analisi.
  if new.status = 'completed' then
    update public.finance_items
       set current_extraction_id = new.id,
           processing_status = 'completed',
           error_code = null
     where id = new.finance_item_id;
    perform public.finance_refresh_effective(new.finance_item_id);
  else
    -- ⚠️ ANCHE IL FALLIMENTO LO SCRIVE IL TRIGGER, non il worker.
    -- Una riga di estrazione con esito `failed` significa una cosa sola: si è
    -- provato e quel documento non si riesce a leggere. I guasti TRANSITORI —
    -- quota esaurita, tempo finito, provider irraggiungibile — non scrivono
    -- alcuna riga: l'elemento resta in coda e si ritenta. Se lo stato finale lo
    -- scrivesse il worker, ci sarebbero due posti in cui ricordarsene, e il
    -- giorno in cui uno dei due dimentica l'elemento resterebbe «in
    -- lavorazione» per sempre — indistinguibile da un lavoro in corso.
    update public.finance_items
       set processing_status = 'failed',
           error_code = new.error_code
     where id = new.finance_item_id;
  end if;

  insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
  values (new.company_id, new.finance_item_id, null,
          case when new.status = 'completed' then 'extraction_completed'
               else 'extraction_failed' end,
          jsonb_build_object('version', new.extraction_version, 'method', new.method));
  return new;
end $$;

drop trigger if exists trg_finance_after_extraction on public.finance_extractions;
create trigger trg_finance_after_extraction
  after insert on public.finance_extractions
  for each row execute function public.finance_after_extraction();


-- ---------------------------------------------------------------------------
-- 17. Lo storico degli stati
-- ---------------------------------------------------------------------------
create or replace function public.finance_items_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, new.created_by, 'created',
            jsonb_build_object('type', new.type, 'origin', new.origin));
    return new;
  end if;

  if new.review_status is distinct from old.review_status then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(),
            case when new.review_status = 'ready' then 'reviewed' else 'reopened' end, '{}'::jsonb);
  end if;

  if (new.archived_at is not null) is distinct from (old.archived_at is not null) then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(),
            case when new.archived_at is not null then 'archived' else 'restored' end, '{}'::jsonb);
  end if;

  if new.type is distinct from old.type then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'type_changed',
            jsonb_build_object('from', old.type, 'to', new.type));
  end if;

  if new.expense_category is distinct from old.expense_category then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'category_changed',
            jsonb_build_object('from', old.expense_category, 'to', new.expense_category));
  end if;

  if new.processing_status = 'pending' and old.processing_status in ('completed', 'failed') then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'retry_requested', '{}'::jsonb);
  end if;

  return new;
end $$;

drop trigger if exists trg_finance_items_events on public.finance_items;
create trigger trg_finance_items_events
  after insert or update on public.finance_items
  for each row execute function public.finance_items_events();


-- ---------------------------------------------------------------------------
-- 18. L'ingestione automatica (§14)
--
-- Quando arriva un'analisi valida e il classificatore deterministico riconosce
-- una fattura, l'elemento finanziario nasce da solo — in coda, non verificato.
-- Nessun elemento nasce «pronto»: la verifica è un gesto umano.
--
-- ⚠️ `on conflict do nothing`: una RIANALISI dello stesso documento non deve
-- creare un secondo elemento né azzerare il lavoro già fatto su quello che c'è.
-- Se il documento era già in Finance, resta com'è.
--
-- ⚠️ Il filename NON è un segnale (§14): `fattura.pdf` non fa di un documento
-- una fattura, e usarlo produrrebbe elementi finanziari a partire dal modo in
-- cui qualcuno ha salvato un file.
-- ---------------------------------------------------------------------------
create or replace function public.finance_autocreate()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_doc  record;
  v_type public.finance_item_type;
begin
  if new.analysis_status = 'failed' then return new; end if;

  select d.id, d.company_id, d.category_workflow_run_id
    into v_doc
    from public.documents d
   where d.id = new.document_id;

  -- Una funzione che scavalca la RLS si difende da sola (lezione della 0017).
  if v_doc.id is null or v_doc.company_id is distinct from new.company_id then
    return new;
  end if;

  v_type := public.finance_type_from_analysis(new.document_type, new.sender_authority_type);
  if v_type is null then return new; end if;

  insert into public.finance_items (
    company_id, document_id, type, origin, processing_status, workflow_run_id
  ) values (
    new.company_id, new.document_id, v_type, 'rule', 'pending',
    -- Se il documento è finito in questa categoria per via di una regola
    -- aziendale, l'elemento finanziario appartiene a quella stessa catena
    -- causale: senza questo filo, l'evento che segue ne aprirebbe una nuova e
    -- la protezione contro i cicli non avrebbe appiglio.
    v_doc.category_workflow_run_id
  )
  on conflict (company_id, document_id) do nothing;

  return new;
end $$;

drop trigger if exists trg_finance_autocreate on public.document_analyses;
create trigger trg_finance_autocreate
  after insert on public.document_analyses
  for each row execute function public.finance_autocreate();


-- ---------------------------------------------------------------------------
-- 19. L'emissione degli eventi per il motore delle automazioni
--
-- ⚠️ I DUE VALORI NUOVI DELL'ENUM COMPAIONO SOLO QUI DENTRO, e il corpo di una
-- funzione non viene eseguito quando la funzione viene creata: applicare questo
-- file non li valuta mai. Vedi il punto 2.
--
-- L'entità è il DOCUMENTO, non l'elemento finanziario: così una regola può
-- guardare insieme la fattura e il documento da cui viene, e non serve toccare
-- i vincoli di `automation_events`.
-- ---------------------------------------------------------------------------
create or replace function public.finance_emit_automation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payload jsonb;
begin
  v_payload := jsonb_build_object(
    'financeItemId', new.id, 'type', new.type, 'reviewStatus', new.review_status);

  -- (a) C'è una fattura nuova da guardare: la lettura è RIUSCITA e nessuno
  --     l'ha ancora verificata.
  --     ⚠️ Una lettura FALLITA non emette niente, come le analisi fallite della
  --     0020: un'estrazione non riuscita non descrive nulla, e far scattare una
  --     regola su di essa significherebbe creare lavoro o classificare sulla
  --     base di dati che non esistono. Il fallimento resta visibile nella
  --     schermata, che è il posto giusto per una persona.
  if new.processing_status = 'completed'
     and old.processing_status is distinct from 'completed'
     and new.review_status = 'needs_review' then
    perform public.automation_emit(
      new.company_id, 'finance_item_needs_review', 'document', new.document_id,
      v_payload, null, new.workflow_run_id);
  end if;

  -- (b) Una persona l'ha verificata: da qui in avanti i dati si possono usare
  --     per far nascere del lavoro.
  if new.review_status = 'ready' and old.review_status is distinct from 'ready' then
    perform public.automation_emit(
      new.company_id, 'finance_item_ready', 'document', new.document_id,
      v_payload, null, new.workflow_run_id);
  end if;

  return new;
end $$;

drop trigger if exists trg_finance_emit_automation on public.finance_items;
create trigger trg_finance_emit_automation
  after update on public.finance_items
  for each row execute function public.finance_emit_automation();


-- ---------------------------------------------------------------------------
-- 20. La lista: filtri, ricerca, ordinamento e paginazione nel database
--
-- Stessa forma di `list_documents` (0017) e per le stesse ragioni: una riga
-- mette insieme l'elemento finanziario, il documento, il sospetto di duplicato,
-- le attività collegate e la provenienza. Fatto dal browser sarebbe una query
-- per riga per relazione, e per sapere quali venticinque righe mostrare
-- bisognerebbe averle scaricate tutte (§27/§112).
--
-- `security invoker` (il default): la RLS di ogni tabella continua ad applicarsi
-- riga per riga. Il filtro esplicito su `company_id` e il controllo di
-- appartenenza NON la sostituiscono, la accompagnano — su una funzione che
-- restituisce IBAN e importi gli strati sono tre.
--
-- ORDINAMENTO PREDEFINITO (§24), e non è opaco: prima ciò che è già scaduto,
-- poi ciò che scade presto, poi ciò che nessuno ha ancora verificato, poi il
-- resto dal più recente. `id desc` chiude SEMPRE la catena: senza, due fatture
-- create nello stesso istante si scambierebbero di posto fra una pagina e
-- l'altra e una delle due non comparirebbe mai.
-- ---------------------------------------------------------------------------
create or replace function public.list_finance_items(
  p_company_id   uuid,
  -- 'invoices' (fatture fornitori e note di credito) | 'expenses' (ricevute).
  p_tab          text default null,
  p_query        text default null,
  p_review       text default null,      -- needs_review | ready
  p_processing   text default null,      -- pending | processing | completed | failed
  p_supplier     text default null,
  p_currency     text default null,
  p_date_from    date default null,      -- sulla data del documento finanziario
  p_date_to      date default null,
  p_due_from     date default null,
  p_due_to       date default null,
  p_source       public.document_source_type default null,
  p_category     public.finance_expense_category default null,
  p_duplicates   boolean default false,  -- solo i possibili duplicati
  p_flagged      boolean default false,  -- solo quelli con qualcosa che non torna
  p_archived     boolean default false,
  p_sort         text default 'default', -- default | due_date | amount | recent | supplier
  p_limit        integer default 25,
  p_offset       integer default 0,
  -- Un solo elemento, per il DETTAGLIO. Come nella 0017: la riga della lista e
  -- la testata del dettaglio devono dire la stessa cosa sullo stesso documento.
  p_item_id      uuid default null
)
returns table (
  id uuid,
  document_id uuid,
  type public.finance_item_type,
  processing_status public.finance_processing_status,
  review_status public.finance_review_status,
  origin public.finance_origin,
  error_code text,
  expense_category public.finance_expense_category,
  payment_method public.finance_payment_method,
  quality_flags public.finance_quality_flag[],
  duplicate_suspected boolean,
  duplicate_count bigint,
  supplier_name text,
  invoice_number text,
  invoice_date date,
  due_date date,
  expense_date date,
  merchant text,
  currency text,
  gross_amount numeric,
  net_amount numeric,
  vat_amount numeric,
  iban text,
  reference_type public.finance_reference_type,
  payment_reference text,
  -- Quali campi ha corretto una persona: senza questo la schermata mostrerebbe
  -- un valore scritto a mano come se l'avesse letto la macchina (§11).
  corrected_fields text[],
  reviewed_at timestamptz,
  reviewed_by uuid,
  archived_at timestamptz,
  created_at timestamptz,
  extraction_id uuid,
  extraction_version integer,
  -- Dal documento: il titolo che una persona riconosce, e da dove è arrivato.
  document_title text,
  document_source public.document_source_type,
  document_status public.document_status,
  storage_path text,
  mime_type text,
  open_task_count bigint,
  task_count bigint,
  email_count bigint,
  total_count bigint
)
language sql
stable
set search_path = ''
as $$
  with params as (
    select
      -- I caratteri jolly digitati da una persona devono cercare sé stessi.
      nullif(btrim(left(coalesce(p_query, ''), 120)), '') as q,
      replace(replace(replace(
        btrim(left(coalesce(p_query, ''), 120)), '\', '\\'), '%', '\%'), '_', '\_') as q_like
  ),
  base as (
    select
      f.*,
      d.title       as d_title,
      d.source_type as d_source,
      d.status      as d_status,
      d.storage_path as d_path,
      d.mime_type   as d_mime,
      ex.extraction_version as ex_version,
      corr.fields   as corr_fields,
      dup.n         as dup_n,
      count(*) over () as n_total
    from public.finance_items f
    -- Il confronto sull'azienda accompagna la chiave esterna: è la disciplina
    -- di questo progetto, e su un join verso i documenti evita che una riga
    -- agganciata per errore possa mai essere letta.
    join public.documents d on d.id = f.document_id and d.company_id = f.company_id
    left join lateral (
      select e.extraction_version
      from public.finance_extractions e
      where e.id = f.current_extraction_id and e.company_id = f.company_id
    ) ex on true
    left join lateral (
      select array_agg(distinct c.field) as fields
      from public.finance_corrections c
      where c.finance_item_id = f.id and c.company_id = f.company_id
    ) corr on true
    left join lateral (
      -- Il duplicato SOSPETTO, calcolato adesso e non memorizzato: dipende da
      -- che cosa c'è intorno, e archiviare la controparte lo fa sparire.
      select count(*) as n
      from public.finance_items f2
      where f.dup_key is not null
        and f2.company_id = f.company_id and f2.dup_key = f.dup_key
        and f2.id <> f.id and f2.archived_at is null
    ) dup on true
    where f.company_id = p_company_id
      -- Sottointerrogazione scalare: l'appartenenza si verifica UNA volta per
      -- interrogazione e non una volta per riga.
      and (select public.is_company_member(p_company_id))
      and (p_item_id is null or f.id = p_item_id)
      -- Chiedendo UN elemento non si applica il filtro di archiviazione: il suo
      -- indirizzo deve funzionare anche dopo, altrimenti «archivia» diventa
      -- indistinguibile da «fai sparire».
      and (p_item_id is not null
           or (case when p_archived then f.archived_at is not null else f.archived_at is null end))
      and (p_tab is null
           or (p_tab = 'invoices' and f.type in ('supplier_invoice', 'credit_note'))
           or (p_tab = 'expenses' and f.type = 'receipt'))
      and (p_review is null or f.review_status::text = p_review)
      and (p_processing is null or f.processing_status::text = p_processing)
      and (p_supplier is null
           or f.eff_supplier_norm = public.finance_norm_supplier(p_supplier))
      and (p_currency is null or f.eff_currency = upper(p_currency))
      and (p_category is null or f.expense_category = p_category)
      and (p_source is null or d.source_type = p_source)
      and (p_date_from is null
           or coalesce(f.eff_invoice_date, f.eff_expense_date, f.created_at::date) >= p_date_from)
      and (p_date_to is null
           or coalesce(f.eff_invoice_date, f.eff_expense_date, f.created_at::date) <= p_date_to)
      and (p_due_from is null or f.eff_due_date >= p_due_from)
      and (p_due_to is null or f.eff_due_date <= p_due_to)
      and (not p_duplicates or dup.n > 0)
      and (not p_flagged or array_length(f.quality_flags, 1) > 0 or dup.n > 0)
      and (
        (select q from params) is null
        or coalesce(f.eff_supplier_name, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(f.eff_merchant, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(f.eff_invoice_number, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(f.eff_payment_reference, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(d.title, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(d.original_filename, '') ilike '%' || (select q_like from params) || '%'
      )
    order by
      case when p_sort = 'due_date' then f.eff_due_date end asc nulls last,
      case when p_sort = 'amount' then f.eff_gross_amount end desc nulls last,
      case when p_sort = 'supplier' then lower(f.eff_supplier_name) end asc nulls last,
      case when p_sort = 'recent' then f.created_at end desc nulls last,
      -- L'ordinamento PREDEFINITO, in quattro gradini dichiarati.
      case when p_sort = 'default' then
        case
          when f.eff_due_date is not null and f.eff_due_date < current_date then 0
          when f.eff_due_date is not null and f.eff_due_date <= current_date + 7 then 1
          when f.review_status = 'needs_review' then 2
          else 3
        end
      end asc nulls last,
      case when p_sort = 'default' then f.eff_due_date end asc nulls last,
      case when p_sort in ('due_date', 'amount', 'supplier', 'recent')
           then null else f.created_at end desc nulls last,
      f.id desc
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    offset greatest(0, coalesce(p_offset, 0))
  )
  select
    b.id, b.document_id, b.type, b.processing_status, b.review_status, b.origin, b.error_code,
    b.expense_category, b.payment_method,
    -- Le bandiere memorizzate PIÙ il duplicato calcolato adesso: la schermata
    -- riceve un elenco solo di ragioni per cui guardare la fattura.
    (select array(select distinct x from unnest(
        b.quality_flags ||
        case when coalesce(b.dup_n, 0) > 0
             then array['duplicate_suspected']::public.finance_quality_flag[]
             else '{}'::public.finance_quality_flag[] end) x order by x)) as quality_flags,
    coalesce(b.dup_n, 0) > 0 as duplicate_suspected,
    coalesce(b.dup_n, 0) as duplicate_count,
    b.eff_supplier_name, b.eff_invoice_number, b.eff_invoice_date, b.eff_due_date,
    b.eff_expense_date, b.eff_merchant, b.eff_currency,
    b.eff_gross_amount, b.eff_net_amount, b.eff_vat_amount,
    b.eff_iban, b.eff_reference_type, b.eff_payment_reference,
    coalesce(b.corr_fields, '{}') as corrected_fields,
    b.reviewed_at, b.reviewed_by, b.archived_at, b.created_at,
    b.current_extraction_id, b.ex_version,
    b.d_title, b.d_source, b.d_status, b.d_path, b.d_mime,
    coalesce(tk.open_count, 0), coalesce(tk.all_count, 0), coalesce(em.n, 0),
    b.n_total
  from base b
  left join lateral (
    select
      count(*) filter (where t.status <> 'completed' and t.archived_at is null) as open_count,
      count(*) as all_count
    from public.tasks t where t.document_id = b.document_id and t.company_id = b.company_id
  ) tk on true
  left join lateral (
    select count(*) as n
    from public.email_message_documents m
    where m.document_id = b.document_id and m.company_id = b.company_id
  ) em on true
  -- Lo STESSO ordine della selezione interna, espressione per espressione:
  -- sceglierne venticinque con un criterio e mostrarle con un altro vorrebbe
  -- dire che la pagina due non viene dopo la pagina uno.
  order by
    case when p_sort = 'due_date' then b.eff_due_date end asc nulls last,
    case when p_sort = 'amount' then b.eff_gross_amount end desc nulls last,
    case when p_sort = 'supplier' then lower(b.eff_supplier_name) end asc nulls last,
    case when p_sort = 'recent' then b.created_at end desc nulls last,
    case when p_sort = 'default' then
      case
        when b.eff_due_date is not null and b.eff_due_date < current_date then 0
        when b.eff_due_date is not null and b.eff_due_date <= current_date + 7 then 1
        when b.review_status = 'needs_review' then 2
        else 3
      end
    end asc nulls last,
    case when p_sort = 'default' then b.eff_due_date end asc nulls last,
    case when p_sort in ('due_date', 'amount', 'supplier', 'recent')
         then null else b.created_at end desc nulls last,
    b.id desc;
$$;


-- ---------------------------------------------------------------------------
-- 21. Il cruscotto: quattro numeri, RAGGRUPPATI PER VALUTA
--
-- ⚠️ NON SI SOMMANO VALUTE DIVERSE (§22/§113). «CHF 12'400» e «EUR 3'100» sono
-- due fatti; «15'500» non è un fatto, è un'invenzione che richiederebbe un
-- tasso di cambio, una data e una fonte — nessuna delle quali il prodotto ha.
-- La funzione restituisce quindi UNA RIGA PER VALUTA, e l'interfaccia le mostra
-- una sotto l'altra.
--
-- ⚠️ LE NOTE DI CREDITO NON GONFIANO IL «DA PAGARE» (§74): sono escluse dai
-- totali in scadenza e scaduti. Compensarle sottraendole sarebbe peggio —
-- suggerirebbe che l'importo netto sia già stato concordato con il fornitore.
--
-- ⚠️ «Scaduta» qui significa SCADENZA SUPERATA, non «non pagata» (§114). Senza
-- dati bancari il prodotto non sa se una fattura è stata pagata, e dirlo
-- sarebbe la prima affermazione falsa di questo modulo.
-- ---------------------------------------------------------------------------
create or replace function public.finance_summary(
  p_company_id uuid,
  p_due_days   integer default 7
)
returns table (
  bucket text,          -- needs_review | due_soon | overdue | expenses_month
  currency text,        -- NULL sulla riga dei conteggi senza importo
  n bigint,
  total numeric
)
language sql
stable
set search_path = ''
as $$
  with mine as (
    select f.*
    from public.finance_items f
    where f.company_id = p_company_id
      and (select public.is_company_member(p_company_id))
      and f.archived_at is null
  ),
  payable as (
    -- Ciò che l'azienda deve ancora pagare: fatture fornitori, non note di
    -- credito, non ricevute (una ricevuta è una spesa già sostenuta).
    select * from mine where type = 'supplier_invoice'
  )
  -- (a) Quante fatture e spese aspettano una verifica. È un CONTEGGIO: non ha
  --     valuta, perché mettere insieme importi non verificati per farne un
  --     totale significherebbe dare per buoni proprio i numeri incerti.
  select 'needs_review'::text, null::text, count(*)::bigint, null::numeric
  from mine where review_status = 'needs_review'
  union all
  -- (b) In scadenza nei prossimi N giorni, per valuta.
  -- ⚠️ Un importo senza valuta NON è un importo, e sommarlo insieme agli altri
  --    ne inventerebbe una. La fattura resta CONTATA — è comunque in scadenza —
  --    ma il suo totale è `null`, e l'interfaccia dice «di cui una senza valuta»
  --    invece di farla sparire o di attribuirla ai franchi.
  select 'due_soon', p.eff_currency, count(*)::bigint,
         case when p.eff_currency is null then null::numeric else sum(p.eff_gross_amount) end
  from payable p
  where p.eff_due_date is not null
    and p.eff_due_date >= current_date
    and p.eff_due_date <= current_date + greatest(1, least(coalesce(p_due_days, 7), 90))
  group by p.eff_currency
  union all
  -- (c) Scadute, per valuta.
  select 'overdue', p.eff_currency, count(*)::bigint,
         case when p.eff_currency is null then null::numeric else sum(p.eff_gross_amount) end
  from payable p
  where p.eff_due_date is not null and p.eff_due_date < current_date
  group by p.eff_currency
  union all
  -- (d) Le spese del mese in corso, per valuta. La data è quella della spesa
  --     quando c'è: quando una spesa è stata SOSTENUTA non è quando il
  --     documento è stato caricato.
  select 'expenses_month', m.eff_currency, count(*)::bigint,
         case when m.eff_currency is null then null::numeric else sum(m.eff_gross_amount) end
  from mine m
  where m.type = 'receipt'
    and coalesce(m.eff_expense_date, m.eff_invoice_date, m.created_at::date)
        >= date_trunc('month', current_date)::date
  group by m.eff_currency;
$$;


-- ---------------------------------------------------------------------------
-- 22. Le controparti di un possibile duplicato (§71)
--
-- Serve al pulsante «Confronta». NON fonde e non cancella niente: restituisce
-- gli altri elementi con la stessa impronta perché una persona possa guardarli
-- accanto (§72).
-- ---------------------------------------------------------------------------
create or replace function public.finance_duplicates(p_item_id uuid)
returns table (
  id uuid, document_id uuid, supplier_name text, invoice_number text,
  invoice_date date, currency text, gross_amount numeric,
  review_status public.finance_review_status, created_at timestamptz
)
language sql
stable
set search_path = ''
as $$
  select f2.id, f2.document_id, f2.eff_supplier_name, f2.eff_invoice_number,
         f2.eff_invoice_date, f2.eff_currency, f2.eff_gross_amount,
         f2.review_status, f2.created_at
  from public.finance_items f1
  join public.finance_items f2
    on f2.company_id = f1.company_id and f2.dup_key = f1.dup_key and f2.id <> f1.id
  where f1.id = p_item_id
    and f1.dup_key is not null
    -- La ricerca è SEMPRE dentro l'azienda: che un'altra impresa abbia la
    -- stessa fattura non deve essere deducibile in alcun modo (§124).
    and (select public.is_company_member(f1.company_id))
    and f2.archived_at is null
  order by f2.created_at asc, f2.id asc
  limit 20;
$$;


-- ---------------------------------------------------------------------------
-- 23. RLS E PERMESSI
--
-- ⚠️⚠️ IL `revoke all` VIENE PRIMA DEI `grant`, E NON È UNA FORMALITÀ.
-- Su Supabase esiste `alter default privileges in schema public grant all on
-- tables to anon, authenticated, service_role`: ogni tabella NUOVA di `public`
-- nasce con i permessi di TABELLA COMPLETI per `authenticated`. Un `grant` di
-- colonna scritto dopo AGGIUNGE privilegi, non ne toglie.
--
-- È la lezione della 0014, e qui pesa il doppio: senza queste righe
-- `finance_extractions` sarebbe scrivibile e cancellabile dal browser da
-- chiunque sia autenticato — una tabella che contiene IBAN, riferimenti di
-- pagamento e importi.
--
-- ⚠️ `service_role` NON viene toccato: il worker deve poter scrivere.
--
-- Che cosa può fare il client, in una riga: LEGGERE tutto ciò che è della
-- propria azienda; CREARE un elemento finanziario da un documento («Aggiungi a
-- Finanze»); CAMBIARE lo stato operativo e l'organizzazione; AGGIUNGERE una
-- correzione. Nient'altro. I verbali non si scrivono, non si modificano e non
-- si cancellano dal browser.
-- ---------------------------------------------------------------------------
alter table public.finance_items       enable row level security;
alter table public.finance_extractions enable row level security;
alter table public.finance_corrections enable row level security;
alter table public.finance_events      enable row level security;
alter table public.finance_vat_rates   enable row level security;

revoke all on public.finance_items       from anon, authenticated, public;
revoke all on public.finance_extractions from anon, authenticated, public;
revoke all on public.finance_corrections from anon, authenticated, public;
revoke all on public.finance_events      from anon, authenticated, public;
revoke all on public.finance_vat_rates   from anon, authenticated, public;

-- Sull'elemento operativo il client scrive SOLO le colonne che descrivono una
-- decisione umana. Tutto il resto — proiezione, bandiere, timbri, estrazione
-- corrente, tentativi — è materia del database e del worker.
grant select on public.finance_items to authenticated;
grant insert (company_id, document_id, type) on public.finance_items to authenticated;
grant update (type, review_status, archived_at, expense_category, payment_method,
              processing_status) on public.finance_items to authenticated;

-- I verbali si leggono e basta. Nessun insert: li scrive il worker con il
-- service role, e nessun update né delete, che i trigger rifiutano comunque —
-- due difese, perché una sola è quella che manca il giorno in cui qualcuno
-- cambia un grant.
grant select on public.finance_extractions to authenticated;

-- Le correzioni si aggiungono e si leggono. Mai modificare, mai cancellare.
grant select, insert on public.finance_corrections to authenticated;

-- Lo storico e il catalogo delle aliquote: sola lettura.
grant select on public.finance_events    to authenticated;
grant select on public.finance_vat_rates to authenticated;

drop policy if exists finance_items_select on public.finance_items;
create policy finance_items_select on public.finance_items
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists finance_items_insert on public.finance_items;
create policy finance_items_insert on public.finance_items
  for insert to authenticated with check (public.is_company_member(company_id));

drop policy if exists finance_items_update on public.finance_items;
create policy finance_items_update on public.finance_items
  for update to authenticated
  using (public.is_company_member(company_id))
  with check (public.is_company_member(company_id));

-- ⚠️ Nessuna policy di DELETE, e nessun grant: un elemento finanziario non si
-- cancella (§91). Si archivia, oppure si cancella il DOCUMENTO — e allora la
-- cascata porta via anche questo. Un «cancella» che lasciasse il documento
-- senza la sua lettura finanziaria produrrebbe un archivio in cui una fattura
-- c'è e non c'è insieme.

drop policy if exists finance_extractions_select on public.finance_extractions;
create policy finance_extractions_select on public.finance_extractions
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists finance_corrections_select on public.finance_corrections;
create policy finance_corrections_select on public.finance_corrections
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists finance_corrections_insert on public.finance_corrections;
create policy finance_corrections_insert on public.finance_corrections
  for insert to authenticated with check (public.is_company_member(company_id));

drop policy if exists finance_events_select on public.finance_events;
create policy finance_events_select on public.finance_events
  for select to authenticated using (public.is_company_member(company_id));

-- Il catalogo delle aliquote è comune a tutte le aziende: si legge, non si
-- scrive. Nessun `company_id`, quindi la policy non filtra — dichiara solo che
-- serve un'identità.
drop policy if exists finance_vat_rates_select on public.finance_vat_rates;
create policy finance_vat_rates_select on public.finance_vat_rates
  for select to authenticated using (true);

revoke all on function public.list_finance_items(uuid, text, text, text, text, text, text, date, date, date, date, public.document_source_type, public.finance_expense_category, boolean, boolean, boolean, text, integer, integer, uuid) from public, anon;
grant execute on function public.list_finance_items(uuid, text, text, text, text, text, text, date, date, date, date, public.document_source_type, public.finance_expense_category, boolean, boolean, boolean, text, integer, integer, uuid) to authenticated;
revoke all on function public.finance_summary(uuid, integer) from public, anon;
grant execute on function public.finance_summary(uuid, integer) to authenticated;
revoke all on function public.finance_duplicates(uuid) from public, anon;
grant execute on function public.finance_duplicates(uuid) to authenticated;
revoke all on function public.finance_type_from_analysis(text, text) from public, anon;
grant execute on function public.finance_type_from_analysis(text, text) to authenticated;
revoke all on function public.finance_norm_supplier(text) from public, anon;
grant execute on function public.finance_norm_supplier(text) to authenticated;
revoke all on function public.finance_norm_invoice_number(text) from public, anon;
grant execute on function public.finance_norm_invoice_number(text) to authenticated;
revoke all on function public.finance_iban_valid(text) from public, anon;
grant execute on function public.finance_iban_valid(text) to authenticated;
revoke all on function public.finance_dup_key(text, text, numeric, text) from public, anon, authenticated;


-- ---------------------------------------------------------------------------
-- 24. Autoverifica: la migrazione controlla di aver ottenuto ciò che dichiara.
--
-- Non è un ornamento. La 0013 dichiarava nei commenti una garanzia che non
-- esisteva, e lo si è scoperto solo eseguendo i test sul database vero. Da
-- allora ogni migrazione che promette qualcosa la verifica prima di dirsi
-- riuscita.
--
-- ⚠️ Nessuna riga di questo blocco nomina i due valori enum aggiunti al punto 2
-- e nessuna chiama una funzione che li nomini: il blocco viene ESEGUITO, e
-- valutare qui un'etichetta nuova farebbe fallire l'intera applicazione.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
  v_type public.finance_item_type;
begin
  -- ⚠️ `information_schema` riporta il ruolo PUBLIC in MAIUSCOLO. Cercare solo
  --    'public' lascerebbe scoperto proprio il ruolo che vale per CHIUNQUE —
  --    un controllo che guarda dalla parte sbagliata e dichiara verde. Le
  --    migrazioni precedenti cercano solo la forma minuscola: qui si cercano
  --    entrambe, e se un giorno emergesse una differenza sarebbe questa
  --    migrazione a dirlo per prima.

  -- (a) I verbali NON devono essere scrivibili dal browser. È la garanzia più
  --     importante del modulo: se cade, un membro può riscrivere l'IBAN di una
  --     fattura senza lasciare traccia in nessuna correzione.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name in ('finance_extractions', 'finance_events', 'finance_vat_rates')
    and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
    and privilege_type in ('INSERT', 'UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'i verbali finanziari risultano scrivibili dal client: %', v_bad;
  end if;

  -- (b) Le correzioni si aggiungono, non si riscrivono.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name = 'finance_corrections'
    and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
    and privilege_type in ('UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'le correzioni finanziarie risultano modificabili o cancellabili: %', v_bad;
  end if;

  -- (c) Un elemento finanziario non si cancella dal browser.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name = 'finance_items'
    and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
    and privilege_type = 'DELETE';
  if v_bad is not null then
    raise exception 'gli elementi finanziari risultano cancellabili dal client: %', v_bad;
  end if;

  -- (d) Niente è raggiungibile senza autenticazione.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name like 'finance\_%'
    and grantee = 'anon';
  if v_bad is not null then
    raise exception 'le tabelle finanziarie risultano accessibili senza autenticazione: %', v_bad;
  end if;

  -- (e) La RLS è accesa su tutte e cinque.
  select string_agg(c.relname, ', ') into v_bad
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relname like 'finance\_%' and c.relkind = 'r'
    and not c.relrowsecurity;
  if v_bad is not null then
    raise exception 'RLS non attiva su: %', v_bad;
  end if;

  -- (f) Il classificatore fa quello che dice, sui casi che contano.
  v_type := public.finance_type_from_analysis('invoice', 'private');
  if v_type is distinct from 'supplier_invoice' then
    raise exception 'una fattura non viene riconosciuta come tale (ha detto %)', v_type;
  end if;
  v_type := public.finance_type_from_analysis('payment_request', 'federal');
  if v_type is not null then
    raise exception 'una richiesta di pagamento di un ente pubblico non è una fattura fornitore (ha detto %)', v_type;
  end if;
  v_type := public.finance_type_from_analysis('information', 'unknown');
  if v_type is not null then
    raise exception 'il classificatore inventa un tipo dove non ha elementi (ha detto %)', v_type;
  end if;

  -- (g) La cifra di controllo dell'IBAN funziona in entrambe le direzioni.
  if not public.finance_iban_valid('CH9300762011623852957') then
    raise exception 'finance_iban_valid rifiuta un IBAN valido';
  end if;
  if public.finance_iban_valid('CH9300762011623852958') then
    raise exception 'finance_iban_valid accetta un IBAN con cifra di controllo sbagliata';
  end if;
  if public.finance_iban_valid('DE89370400440532013000') is not true then
    raise exception 'finance_iban_valid rifiuta un IBAN estero valido';
  end if;

  -- (h) L'impronta del duplicato tace quando i dati non bastano.
  if public.finance_dup_key('acme', null, 100, 'CHF') is not null then
    raise exception 'l''impronta del duplicato si forma anche senza il numero di fattura';
  end if;
  if public.finance_dup_key('acme', 'F1', 100, 'CHF') is null then
    raise exception 'l''impronta del duplicato non si forma quando i dati ci sono tutti';
  end if;

  -- (i) La normalizzazione non butta via ciò che distingue due numeri diversi.
  --
  -- ⚠️ CHE COSA GARANTISCE E CHE COSA NO. Toglie spazi, punti e cancelletti —
  -- che sono ornamenti tipografici — e NON tocca lettere né trattini, che nei
  -- numeri di fattura portano informazione: `2026-1` e `20261` sono due numeri
  -- diversi, e anche `N847291` e `847291` potrebbero esserlo.
  --
  -- Conseguenza dichiarata: se un'estrazione legge «N. 847291» e un'altra
  -- «847291», il duplicato NON viene sospettato. È il prezzo della prudenza, ed
  -- è il verso giusto in cui sbagliare: un sospetto mancato costa una verifica
  -- in più, un sospetto sbagliato insegna a ignorare i sospetti.
  if public.finance_norm_invoice_number('2026-1')
     = public.finance_norm_invoice_number('20261') then
    raise exception 'la normalizzazione del numero di fattura confonde 2026-1 con 20261';
  end if;
  if public.finance_norm_invoice_number('847 291')
     is distinct from public.finance_norm_invoice_number('847291') then
    raise exception 'la normalizzazione non ignora gli spazi dentro un numero di fattura';
  end if;
  if public.finance_norm_invoice_number('N847291')
     = public.finance_norm_invoice_number('847291') then
    raise exception 'la normalizzazione toglie le lettere: due numeri diversi diventerebbero uguali';
  end if;
  if public.finance_norm_supplier('Swisscom (Svizzera) SA')
     is distinct from public.finance_norm_supplier('swisscom  svizzera   sa') then
    raise exception 'la normalizzazione del fornitore non ignora punteggiatura e spazi ripetuti';
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0022_finance_event_kind_cast  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0022 — LO STORICO DI FINANCE NON SI SCRIVEVA
--
-- ⚠️ IL DIFETTO. Tre trigger della 0021 scrivono `finance_events.kind` — che è
-- un enum — scegliendo l'etichetta con un `CASE`:
--
--     case when new.status = 'completed' then 'extraction_completed'
--          else 'extraction_failed' end
--
-- Quando TUTTI i rami di un `CASE` sono letterali senza tipo, Postgres risolve
-- l'espressione come `text` (è la regola documentata: se tutti gli ingressi sono
-- di tipo `unknown`, il risultato è `text`). E da `text` a un enum non esiste
-- conversione implicita:
--
--     42804: column "kind" is of type public.finance_event_kind
--            but expression is of type text
--
-- Un letterale NUDO — `'created'` — sarebbe passato senza problemi, perché resta
-- `unknown` e viene coercito alla colonna. Dentro un `CASE` no. È la differenza
-- che ha reso il difetto invisibile a occhio: nello stesso trigger, tre insert
-- funzionavano e due no.
--
-- ⚠️ QUANTO ERA GRAVE. Il trigger scrive DOPO l'inserimento di un'estrazione:
-- l'eccezione annullava l'intera transazione, quindi NON si poteva salvare
-- alcun verbale finanziario. Il modulo non funzionava affatto — ma la 0021 si
-- era applicata senza un errore, e nessuna verifica statica poteva accorgersene:
-- il corpo di una funzione plpgsql non viene analizzato alla creazione.
--
-- L'ha trovato la PRIMA esecuzione di `npm run test:finance` contro il database
-- vero, come per la 0010, la 0014, la 0016 e la 0018. Su questo progetto è
-- successo cinque volte su sei: ciò che non è provato contro la cosa reale non
-- è vero, è solo scritto.
--
-- ⚠️ PERCHÉ UNA MIGRAZIONE NUOVA E NON UNA CORREZIONE DELLA 0021.
-- La 0021 è già applicata. Riscriverla significherebbe che il file non descrive
-- più ciò che è stato eseguito. È lo stesso caso della 0019, che ha corretto la
-- 0018 dopo l'applicazione invece di riaprirla.
--
-- Requisiti: 0021 applicata.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- 1. Il trigger che promuove un'estrazione e ne registra l'esito
--
-- Identico a quello della 0021 tranne i due `::public.finance_event_kind`.
-- ---------------------------------------------------------------------------
create or replace function public.finance_after_extraction()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Solo un'estrazione RIUSCITA diventa quella corrente: un tentativo fallito
  -- non deve sostituire un verbale buono precedente.
  if new.status = 'completed' then
    update public.finance_items
       set current_extraction_id = new.id,
           processing_status = 'completed',
           error_code = null
     where id = new.finance_item_id;
    perform public.finance_refresh_effective(new.finance_item_id);
  else
    -- ⚠️ ANCHE IL FALLIMENTO LO SCRIVE IL TRIGGER, non il worker.
    -- Una riga di estrazione con esito `failed` significa una cosa sola: si è
    -- provato e quel documento non si riesce a leggere. I guasti TRANSITORI —
    -- quota esaurita, tempo finito, provider irraggiungibile — non scrivono
    -- alcuna riga: l'elemento resta in coda e si ritenta.
    update public.finance_items
       set processing_status = 'failed',
           error_code = new.error_code
     where id = new.finance_item_id;
  end if;

  insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
  values (new.company_id, new.finance_item_id, null,
          -- ⚠️ IL CAST È IL PUNTO DI QUESTA MIGRAZIONE. Senza, l'intera
          -- transazione fallisce e nessun verbale può essere salvato.
          case when new.status = 'completed'
               then 'extraction_completed'::public.finance_event_kind
               else 'extraction_failed'::public.finance_event_kind end,
          jsonb_build_object('version', new.extraction_version, 'method', new.method));
  return new;
end $$;

drop trigger if exists trg_finance_after_extraction on public.finance_extractions;
create trigger trg_finance_after_extraction
  after insert on public.finance_extractions
  for each row execute function public.finance_after_extraction();


-- ---------------------------------------------------------------------------
-- 2. Il trigger che registra i cambi di stato
--
-- Stesso difetto in due punti: «verificata / riaperta» e «archiviata /
-- ripristinata». Gli altri quattro insert di questa funzione usano letterali
-- nudi e funzionavano già — ed è precisamente ciò che rendeva il difetto
-- difficile da vedere rileggendo.
-- ---------------------------------------------------------------------------
create or replace function public.finance_items_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, new.created_by, 'created',
            jsonb_build_object('type', new.type, 'origin', new.origin));
    return new;
  end if;

  if new.review_status is distinct from old.review_status then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(),
            case when new.review_status = 'ready'
                 then 'reviewed'::public.finance_event_kind
                 else 'reopened'::public.finance_event_kind end, '{}'::jsonb);
  end if;

  if (new.archived_at is not null) is distinct from (old.archived_at is not null) then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(),
            case when new.archived_at is not null
                 then 'archived'::public.finance_event_kind
                 else 'restored'::public.finance_event_kind end, '{}'::jsonb);
  end if;

  if new.type is distinct from old.type then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'type_changed',
            jsonb_build_object('from', old.type, 'to', new.type));
  end if;

  if new.expense_category is distinct from old.expense_category then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'category_changed',
            jsonb_build_object('from', old.expense_category, 'to', new.expense_category));
  end if;

  if new.processing_status = 'pending' and old.processing_status in ('completed', 'failed') then
    insert into public.finance_events (company_id, finance_item_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'retry_requested', '{}'::jsonb);
  end if;

  return new;
end $$;

drop trigger if exists trg_finance_items_events on public.finance_items;
create trigger trg_finance_items_events
  after insert or update on public.finance_items
  for each row execute function public.finance_items_events();


-- ---------------------------------------------------------------------------
-- 3. ⚠️ PERCHÉ QUESTA MIGRAZIONE NON SI AUTOVERIFICA
--
-- Ogni migrazione di questo progetto controlla, in fondo, di aver ottenuto ciò
-- che dichiara. Questa NO, e la ragione va scritta perché è la stessa trappola
-- che ha già colpito due volte.
--
-- Il controllo naturale sarebbe: creare un'estrazione di prova ed esigere che lo
-- storico la registri — cioè ESEGUIRE il percorso che falliva. Ma inserire
-- un'estrazione fa scattare `trg_finance_after_extraction`, che promuove
-- l'elemento a `completed`, che a sua volta fa scattare
-- `trg_finance_emit_automation`, il cui corpo NOMINA
-- `finance_item_needs_review` — uno dei due valori che la 0021 aggiunge ad
-- `automation_event_type`.
--
-- Su un database esistente non succede nulla: quei valori sono committati da
-- tempo. Ma `full-setup.sql` concatena 0021 e 0022 in un'UNICA transazione, e
-- lì l'etichetta è stata aggiunta pochi istanti prima e non è ancora
-- utilizzabile: Postgres solleverebbe
--
--     55P04: unsafe use of new value of enum type
--
-- e OGNI INSTALLAZIONE DA ZERO fallirebbe. È esattamente il guasto della 0015 —
-- invisibile a chi ha già il database, che applica una migrazione alla volta, e
-- visibile solo al primo cliente nuovo.
--
-- `npm run db:bundle` non lo vedrebbe: il suo controllo riconosce l'etichetta
-- dentro il corpo di una funzione (dove è innocua) e dentro un blocco `do`
-- (dove non lo è), ma non può seguire una CHIAMATA da un `do` a una funzione
-- che la nomina. È il limite dichiarato in cima a quel controllo.
--
-- La verifica esiste, e sta dove può girare senza questo vincolo: la sezione 4
-- di `npm run test:finance` scrive un'estrazione vera contro il database vero,
-- DOPO il commit, e pretende di ritrovare la riga nello storico. È l'esecuzione
-- che ha trovato questo difetto, ed è l'esecuzione che lo tiene chiuso.
-- ---------------------------------------------------------------------------

-- >>>>>>>>>>>>>>>>>>>>  0023_finance_immutable_allows_cascade  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0023 — UN VERBALE IMMUTABILE DEVE POTER MORIRE CON IL SUO DOCUMENTO
--
-- ⚠️ IL DIFETTO. La 0021 rende immutabili i verbali finanziari e le correzioni
-- con due trigger che sollevano su `update or delete`. Il divieto di UPDATE è
-- giusto e resta. Il divieto di DELETE no, e rompeva due cose insieme:
--
--   1. **un documento con una fattura non si poteva più cancellare.** La
--      cancellazione di un documento porta via per cascata analisi, estrazioni,
--      correzioni e storico (§90/§91): arrivata a `finance_extractions` il
--      trigger sollevava, e l'intera cancellazione falliva. Un documento
--      finanziario diventava indistruttibile — che non è una garanzia, è un
--      guasto: nessuno può più togliere dal sistema una fattura caricata per
--      sbaglio, e nessuna politica di conservazione può funzionare.
--
--   2. **la pulizia dei dati di prova non girava.** `npm run test:finance`
--      cancella le aziende create e verifica che siano sparite: sette aziende
--      di prova sono rimaste nel database di PRODUZIONE. È esattamente
--      l'incidente del 2026-07-26 con l'Inbox, per una causa diversa.
--
-- ⚠️ ALLORA CHE COSA PROTEGGE L'IMMUTABILITÀ, ADESSO?
-- I PERMESSI, che è dove doveva stare fin dall'inizio. Il client autenticato ha
-- `select` su `finance_extractions` e `select, insert` su `finance_corrections`:
-- non ha `delete` su nessuna delle due, e non esiste alcuna policy che glielo
-- conceda. Dal browser un verbale non si cancella, punto.
--
-- Ciò che si può fare è cancellare il DOCUMENTO — che è un'azione riservata ad
-- amministratori e titolari (`documents_delete_admin_or_owner`, 0017) e che
-- porta via tutto quanto insieme. È una scelta diversa e dichiarata: non si
-- cancella il verbale di una fattura tenendo la fattura, si cancella la fattura.
--
-- ⚠️ La lezione generalizzabile: un divieto scritto in un trigger vale anche per
-- la cascata, che non è una scrittura di qualcuno — è la conseguenza di una
-- cancellazione già autorizzata a monte. Prima di vietare in un trigger, chiedersi
-- chi altro passa di lì.
--
-- Trovato da `npm run test:finance` alla SECONDA esecuzione contro il database
-- vero, nella sezione che verifica la cascata tabella per tabella invece di
-- dichiararla.
--
-- Requisiti: 0021 e 0022 applicate.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- 1. I verbali: non si modificano. Si cancellano solo con il documento.
-- ---------------------------------------------------------------------------
create or replace function public.finance_extractions_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'finance_extraction_immutable'
    using errcode = '42501',
          hint = 'Un''estrazione non si modifica: se ne scrive una versione nuova.';
end $$;

drop trigger if exists trg_finance_extractions_immutable on public.finance_extractions;
create trigger trg_finance_extractions_immutable
  -- ⚠️ SOLO `update`. Il `delete` era qui e impediva alla cascata di
  -- funzionare, rendendo indistruttibile ogni documento con una fattura.
  before update on public.finance_extractions
  for each row execute function public.finance_extractions_immutable();


-- ---------------------------------------------------------------------------
-- 2. Le correzioni: si aggiungono. Stesso ragionamento.
-- ---------------------------------------------------------------------------
create or replace function public.finance_corrections_append_only()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'finance_correction_append_only'
    using errcode = '42501',
          hint = 'Le correzioni si aggiungono: per cambiare un valore se ne scrive una nuova.';
end $$;

drop trigger if exists trg_finance_corrections_append_only on public.finance_corrections;
create trigger trg_finance_corrections_append_only
  before update on public.finance_corrections
  for each row execute function public.finance_corrections_append_only();


-- ---------------------------------------------------------------------------
-- 3. Autoverifica: i permessi devono reggere da soli
--
-- Ora che il trigger non vieta più il `delete`, l'unica difesa contro una
-- cancellazione dal browser sono i permessi. Se un giorno qualcuno concedesse
-- `delete` a `authenticated` su queste tabelle, la garanzia sparirebbe in
-- silenzio: qui la migrazione si rifiuta di dirsi riuscita.
--
-- ⚠️ Nessuna riga di questo blocco esegue codice che nomini i valori enum
-- aggiunti dalla 0021: si interroga solo il catalogo dei permessi. Vedi la
-- sezione 3 della 0022 per il motivo.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
begin
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name in ('finance_extractions', 'finance_corrections')
    and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
    and privilege_type = 'DELETE';
  if v_bad is not null then
    raise exception 'senza il divieto nel trigger, i permessi devono reggere: %', v_bad;
  end if;

  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name in ('finance_extractions', 'finance_corrections')
    and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
    and privilege_type = 'UPDATE';
  if v_bad is not null then
    raise exception 'i verbali e le correzioni risultano modificabili dal client: %', v_bad;
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0024_contract_manager  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0024 — CONTRACT MANAGER
--
-- Contratti e accordi aziendali: capire con chi si è legati, da quando, fino a
-- quando, a quali condizioni, e trasformare le date che ne derivano in lavoro
-- concreto. NON è uno studio legale, e la differenza non è di ambizione ma di
-- competenza: uno studio legale AFFERMA che cosa il diritto impone, questo
-- modulo RIPORTA che cosa il documento dice.
--
-- ⚠️ CIÒ CHE QUESTA MIGRAZIONE NON FA, E NON PER MANCANZA DI TEMPO:
-- non giudica se una clausola sia valida, nulla, abusiva, opponibile o
-- contestabile; non applica il Codice delle obbligazioni né alcuna norma
-- cantonale; non colma con la legge i termini che il contratto tace; non invia
-- disdette, non firma, non accetta né rifiuta rinnovi, non scrive alla
-- controparte. Un contratto si legge e si organizza, non si esegue.
--
-- ⚠️ NON CREA UNA SECONDA VERITÀ SUI DOCUMENTI.
-- Il file resta del documento (Storage), il testo resta dell'estrazione, la
-- lettura amministrativa resta dell'analisi immutabile, il lavoro resta delle
-- attività, il promemoria resta del calendario e delle notifiche. Qui si
-- aggiunge SOLO la lettura contrattuale specializzata, i termini che una
-- persona ha verificato e le date che ne derivano.
--
--   DOCUMENTI → ESTRAZIONE CONTRATTUALE → VERIFICA UMANA → TERMINI VERIFICATI
--             → MILESTONE → ATTIVITÀ → CALENDARIO → NOTIFICA → DECISIONE UMANA
--
-- ⚠️ LA REGOLA CHE GOVERNA TUTTO IL FILE: EVIDENZA > FIDUCIA > AUTOMAZIONE.
-- Se una clausola è ambigua si mostra; se una data non si può derivare non si
-- inventa; se arriva una modifica non si sovrascrive; se un termine è
-- verificato allora — e solo allora — può diventare lavoro.
--
-- Requisiti: 0001–0023 applicate.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- 1. I tipi
--
-- Tutti con `create type … as enum (…)`: i valori dichiarati alla creazione
-- sono utilizzabili SUBITO, anche nella stessa transazione. È la differenza con
-- `alter type … add value` del punto 2, che rende l'etichetta inservibile fino
-- al commit (55P04).
-- ---------------------------------------------------------------------------

-- Che cosa è il contratto. §2 — undici valori, e nessuno di essi è una
-- categoria giuridica: sono i rapporti che una PMI riconosce guardando la
-- propria cartella. `other` è una scelta esplicita, non un ripiego per l'ignoto:
-- quando il tipo non si sa, la colonna resta al suo default e il documento
-- porta la propria bandiera di qualità.
do $$ begin
  create type public.contract_type as enum (
    'insurance',              -- polizze
    'leasing',
    'rent',                   -- locazione di locali, magazzini, posteggi
    'telecom',
    'software_subscription',
    'supplier',               -- fornitura di beni
    'maintenance',            -- manutenzione e assistenza
    'service',                -- prestazione di servizi
    'licensing',
    'nda',
    'other'
  );
exception when duplicate_object then null; end $$;

-- §9 — che cosa deve fare una PERSONA. Tre valori, e il terzo è il cuore del
-- modulo: `review_required_again` non è «da verificare» — è «era verificato, poi
-- è arrivato un documento che sembra cambiare i termini». Fonderli farebbe
-- sparire proprio l'informazione per cui esiste la gestione degli amendment.
do $$ begin
  create type public.contract_review_status as enum
    ('needs_review', 'verified', 'review_required_again');
exception when duplicate_object then null; end $$;

-- §10 — lo stato operativo del rapporto. `unknown` è il default e non è una
-- lacuna: finché nessuno ha verificato le date, dire «attivo» sarebbe
-- un'affermazione che nessun dato sostiene.
-- ⚠️ NON SI DERIVA AUTOMATICAMENTE (§118). Una data passata non basta a
-- dichiarare finito un contratto che prevede rinnovo tacito, e sbagliare in
-- questa direzione significa smettere di sorvegliare un impegno ancora in
-- vigore. Il prodotto può SUGGERIRE «possibilmente scaduto» in lettura; a
-- scrivere questa colonna è solo una persona.
do $$ begin
  create type public.contract_lifecycle_status as enum
    ('unknown', 'upcoming', 'active', 'ended', 'terminated');
exception when duplicate_object then null; end $$;

-- §5 — che ruolo ha un documento dentro il contratto. Un contratto reale non è
-- un PDF: è un accordo, i suoi allegati, le condizioni generali richiamate, le
-- modifiche successive e — se arriva — la disdetta.
do $$ begin
  create type public.contract_document_relation as enum (
    'main_agreement',
    'amendment',            -- modifica i termini: è l'unico che apre una revisione
    'annex',                -- allegato, incluse le condizioni generali allegate
    'renewal',
    'termination_notice',
    'other'
  );
exception when duplicate_object then null; end $$;

-- Chi ha collegato il documento o creato il contratto. §78 chiede audit sul
-- collegamento: `rule` è la regola deterministica del prodotto, `manual` una
-- persona, `workflow` una regola scritta dall'azienda.
do $$ begin
  create type public.contract_origin as enum ('manual', 'rule', 'workflow');
exception when duplicate_object then null; end $$;

-- §81 — a che punto è la MACCHINA su un singolo documento. Deliberatamente
-- separato dallo stato di revisione: «l'estrazione è fallita» e «i dati vanno
-- verificati» sono due cose diverse.
do $$ begin
  create type public.contract_processing_status as enum
    ('pending', 'processing', 'completed', 'failed');
exception when duplicate_object then null; end $$;

-- Esito di un tentativo di lettura. Due valori: o ha prodotto un verbale
-- leggibile o non l'ha prodotto. Un'estrazione con campi mancanti è `completed`
-- con le sue incertezze — «incompleto» non è «fallito».
do $$ begin
  create type public.contract_extraction_status as enum ('completed', 'failed');
exception when duplicate_object then null; end $$;

-- §25 — lo stato di una versione dei termini. `draft` è ciò che il sistema
-- propone, `verified` ciò che una persona ha confermato e che da quel momento è
-- immutabile, `superseded` una versione precedente che resta leggibile.
do $$ begin
  create type public.contract_term_version_status as enum
    ('draft', 'verified', 'superseded');
exception when duplicate_object then null; end $$;

-- §33 — che cosa sappiamo della fine del contratto. Tre stati, e il terzo non è
-- il secondo: `none` è «il documento dice che non c'è una fine fissa» (contratto
-- a tempo indeterminato), `unknown` è «non l'ho trovata». Confonderli
-- trasformerebbe un'ignoranza in un'affermazione.
do $$ begin
  create type public.contract_end_kind as enum ('explicit', 'none', 'unknown');
exception when duplicate_object then null; end $$;

-- §35 — il rinnovo automatico. TRE valori e mai un booleano: un documento che
-- non parla di rinnovo non dice «no», dice niente. Un `false` scritto al posto
-- di `unclear` è la bugia più costosa che questo modulo possa raccontare, perché
-- spegne la sorveglianza proprio dove serve.
do $$ begin
  create type public.contract_auto_renewal as enum ('yes', 'no', 'unclear');
exception when duplicate_object then null; end $$;

-- §37 — l'unità di un periodo (preavviso, rinnovo, durata minima).
do $$ begin
  create type public.contract_period_unit as enum ('days', 'weeks', 'months', 'years');
exception when duplicate_object then null; end $$;

-- ⚠️⚠️ §38 — L'ANCORAGGIO DEL PREAVVISO, ED È IL TIPO PIÙ IMPORTANTE DEL FILE.
-- «Tre mesi» non è un termine: è un numero in cerca di una data. Tre mesi prima
-- della scadenza, tre mesi per la fine del mese, tre mesi per la fine del
-- trimestre e tre mesi in qualsiasi momento producono quattro date diverse — e
-- soltanto per i primi due il prodotto sa fare un calcolo di cui rispondere.
--
-- I valori che NON producono alcuna data sono qui perché ESISTONO nei contratti
-- veri, non perché il prodotto sappia trattarli: dichiararli permette di dire
-- «il preavviso è indicato, ma non è possibile derivare con sicurezza una data»
-- invece di tacere o, peggio, di calcolare.
do $$ begin
  create type public.contract_notice_anchor as enum (
    'before_fixed_end',     -- CALCOLABILE: N prima di una fine esplicita
    'before_renewal_date',  -- CALCOLABILE: N prima della data di rinnovo
    'to_month_end',         -- «auf Monatsende» — semantica non univoca
    'to_quarter_end',
    'to_year_end',
    'anytime',              -- nessuna scadenza a cui ancorare
    'other',
    'unclear'               -- il documento indica un preavviso senza dire a che cosa
  );
exception when duplicate_object then null; end $$;

-- §49 — come il contratto dice che la disdetta va comunicata. Si estrae SOLO se
-- esplicito, e l'interfaccia lo presenta come «il contratto indica: …», mai come
-- «devi usare». Che quel modo sia giuridicamente necessario è una domanda di
-- diritto, e questo modulo non la pone.
do $$ begin
  create type public.contract_termination_method as enum
    ('written_notice', 'email', 'registered_mail', 'portal', 'other');
exception when duplicate_object then null; end $$;

-- §53 — con quale cadenza il costo si ripete. `unknown` non è `one_time`.
do $$ begin
  create type public.contract_cost_frequency as enum
    ('one_time', 'monthly', 'quarterly', 'yearly', 'other', 'unknown');
exception when duplicate_object then null; end $$;

-- §40 — le date che meritano attenzione.
do $$ begin
  create type public.contract_milestone_kind as enum (
    'contract_start', 'contract_end', 'renewal_date', 'notice_deadline',
    'review_date', 'other'
  );
exception when duplicate_object then null; end $$;

-- §41 — da dove viene una data. `explicit` è scritta nel contratto, `derived` è
-- calcolata dal prodotto, `manual` l'ha messa una persona. Tenerle distinte è
-- ciò che permette di non trattare un calcolo come una lettura.
do $$ begin
  create type public.contract_milestone_source as enum ('explicit', 'derived', 'manual');
exception when duplicate_object then null; end $$;

-- ⚠️ §43/§44 — LA DISTINZIONE FONDAMENTALE DEL MODULO.
-- `candidate` è una data che il sistema propone; `verified` è una data che una
-- persona ha confermato. Solo la seconda può generare lavoro (§87), perché solo
-- della seconda qualcuno risponde. `dismissed` è una data scartata da una
-- persona; `superseded` una data resa obsoleta da una nuova versione dei
-- termini — e le due non si confondono, perché la prima è un giudizio e la
-- seconda un fatto.
do $$ begin
  create type public.contract_milestone_status as enum
    ('candidate', 'verified', 'dismissed', 'superseded');
exception when duplicate_object then null; end $$;

-- §140 — le bandiere di qualità. Sono CHIAVI: la frase la scrive l'interfaccia
-- nella lingua di chi legge. Ognuna corrisponde a una verifica che il codice
-- esegue davvero — non esiste una bandiera che nessuno alza.
do $$ begin
  create type public.contract_quality_flag as enum (
    'missing_counterparty',
    'ambiguous_start_date',
    'ambiguous_end_date',
    'renewal_unclear',            -- §35: il documento non chiarisce il rinnovo
    'notice_anchor_unclear',      -- §38: c'è un preavviso, non si sa da quando
    'notice_not_derivable',       -- §39: preavviso noto, data NON calcolabile
    'conflicting_terms',          -- due documenti dicono cose diverse
    'missing_referenced_annex',   -- §115: richiama allegati che non ci sono
    'low_extraction_confidence',
    'amendment_requires_review',  -- §26: una modifica attende una persona
    'partially_analysed',         -- §113: documento più lungo del limite
    'out_of_scope_contract_kind', -- §3: lavoro, M&A, contenzioso…
    'cost_unclear',
    'multiple_currencies'         -- §55: importi in valute diverse, mai sommati
  );
exception when duplicate_object then null; end $$;

-- §85 — lo storico. Lo scrivono i trigger; non si registra la lettura.
do $$ begin
  create type public.contract_event_kind as enum (
    'created', 'document_added', 'document_removed', 'extraction_completed',
    'extraction_failed', 'corrected', 'verified', 'review_reopened',
    'owner_changed', 'term_version_verified', 'milestone_verified',
    'milestone_dismissed', 'milestone_added', 'amendment_added',
    'archived', 'restored', 'lifecycle_changed', 'retry_requested'
  );
exception when duplicate_object then null; end $$;


-- ---------------------------------------------------------------------------
-- 2. I quattro inneschi nuovi del motore delle automazioni
--
-- ⚠️⚠️ LEGGERE PRIMA DI TOCCARE QUESTE QUATTRO RIGHE.
--
-- `alter type … add value` si esegue dentro una transazione, ma l'etichetta NON
-- è utilizzabile finché quella transazione non è chiusa (Postgres 55P04). Il SQL
-- editor di Supabase esegue tutto in un'unica transazione, e `full-setup.sql`
-- concatena TUTTE le migrazioni: basta una riga che VALUTI l'etichetta appena
-- aggiunta per far fallire ogni installazione da zero. È successo con la 0015.
--
-- In questo file i quattro valori compaiono altrove SOLTANTO dentro il corpo di
-- `create function`. Un corpo plpgsql viene depositato come TESTO: Postgres non
-- risolve le etichette che vi compaiono finché la funzione non viene chiamata,
-- cioè dopo il commit. È la stessa scelta della 0021, e `npm run db:bundle` la
-- riconosce (con autoverifica in entrambe le direzioni).
--
-- ⚠️ Il blocco di autoverifica in fondo NON nomina questi valori e NON chiama
-- alcuna funzione che li nomini: quel blocco viene eseguito davvero.
-- ---------------------------------------------------------------------------
alter type public.automation_event_type add value if not exists 'contract_verified';
alter type public.automation_event_type add value if not exists 'contract_review_required';
alter type public.automation_event_type add value if not exists 'contract_milestone_verified';
alter type public.automation_event_type add value if not exists 'contract_milestone_window_opened';


-- ---------------------------------------------------------------------------
-- 3. `contract` diventa un'entità del motore delle automazioni
--
-- ⚠️ PERCHÉ QUI SI ALLARGA IL VINCOLO MENTRE FINANCE NON L'AVEVA FATTO.
-- La 0021 lasciò `document`, e per una buona ragione: una fattura È la lettura
-- di un documento, e una regola che parla di fatture vuole poter guardare anche
-- la categoria e il mittente di quel documento.
-- Un contratto no. Un contratto ha PIÙ documenti (§5), può esistere senza
-- averne nessuno, e le sue milestone non appartengono ad alcuno di essi.
-- Agganciare l'evento all'accordo principale significherebbe dire una cosa
-- falsa — «questo fatto riguarda quel PDF» — proprio nel campo che serve al
-- motore per ritrovare l'entità.
--
-- Si allarga l'elenco, non si toglie il controllo: un `entity_type` libero
-- lascerebbe entrare qualunque stringa, e la 0020 lo evitava di proposito.
-- ---------------------------------------------------------------------------
alter table public.automation_events drop constraint if exists automation_events_entity_type_check;
alter table public.automation_events
  add constraint automation_events_entity_type_check
  check (entity_type in ('document', 'email_message', 'task', 'contract'));

alter table public.workflow_runs drop constraint if exists workflow_runs_entity_type_check;
alter table public.workflow_runs
  add constraint workflow_runs_entity_type_check
  check (entity_type in ('document', 'email_message', 'task', 'contract'));

-- Una notifica può ora riferirsi a un contratto: «il preavviso di X si avvicina»
-- non ha altro referente sensato.
alter table public.notifications drop constraint if exists notifications_entity_type_check;
alter table public.notifications
  add constraint notifications_entity_type_check
  check (entity_type in ('task', 'calendar_connection', 'document', 'email_message', 'contract'));


-- ---------------------------------------------------------------------------
-- 4. contracts — IL RAPPORTO CONTRATTUALE
--
-- Che cosa sta qui e che cosa no: qui sta ciò che una PERSONA decide (come si
-- chiama, chi è il responsabile, l'ho verificato, l'ho archiviato) e ciò che
-- serve per FILTRARE e ORDINARE. I TERMINI stanno in `contract_term_versions`,
-- i FATTI LETTI in `contract_extractions` (immutabile), i DOCUMENTI restano
-- documenti.
--
-- ⚠️ `display_name` È METADATO ORGANIZZATIVO, NON UNA CORREZIONE (§31).
-- «Swisscom — Internet sede Lugano» non è un dato del contratto: è il modo in
-- cui l'azienda lo chiama. Cambiarlo non produce alcuna correzione dei termini e
-- non tocca lo stato di verifica.
-- ---------------------------------------------------------------------------
create table if not exists public.contracts (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies(id) on delete cascade,

  display_name      text not null,
  contract_type     public.contract_type not null default 'other',
  -- §29/§30 — la controparte è METADATO CONTRATTUALE, non un'anagrafica. Nessun
  -- riferimento a una tabella di clienti o fornitori: quella tabella non esiste,
  -- e crearla qui significherebbe cominciare un CRM di straforo (§136).
  counterparty_name text,

  -- §7 — il responsabile interno del rapporto. ⚠️ NON è l'assegnatario di
  -- un'attività (§8): l'uno risponde del contratto, l'altro di un compito. Un
  -- trigger verifica che sia membro della stessa azienda (§102).
  owner_user_id     uuid references auth.users(id) on delete set null,

  review_status     public.contract_review_status not null default 'needs_review',
  lifecycle_status  public.contract_lifecycle_status not null default 'unknown',
  origin            public.contract_origin not null default 'manual',

  -- La versione dei termini attualmente IN VIGORE, cioè verificata da una
  -- persona. `null` finché nessuno ha verificato nulla: in quel caso
  -- l'interfaccia mostra la bozza dichiarandola tale, e non la spaccia per un
  -- termine accertato. La chiave esterna si aggiunge più sotto.
  current_term_version_id uuid,

  quality_flags     public.contract_quality_flag[] not null default '{}',
  -- Nota interna dell'azienda. Non è un dato del contratto e non entra in
  -- nessuna estrazione: è il posto dove scrivere «rinegoziare a settembre».
  internal_note     text,

  verified_at       timestamptz,
  verified_by       uuid references auth.users(id) on delete set null,
  archived_at       timestamptz,
  archived_by       uuid references auth.users(id) on delete set null,

  created_by        uuid references auth.users(id) on delete set null,
  workflow_run_id   uuid references public.workflow_runs(id) on delete set null,

  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),

  constraint contract_display_name_not_blank check (btrim(display_name) <> '')
);

comment on table public.contracts is
  'Il rapporto contrattuale. I TERMINI stanno in contract_term_versions (una '
  'versione verificata è immutabile), i fatti letti in contract_extractions, i '
  'documenti restano in documents: qui c''è ciò che una persona decide.';
comment on column public.contracts.lifecycle_status is
  'Stato operativo. NON si deriva da una data passata (§118): un contratto con '
  'rinnovo tacito e scadenza superata non è finito, e dichiararlo tale '
  'spegnerebbe la sorveglianza su un impegno ancora in vigore.';


-- ---------------------------------------------------------------------------
-- 5. contract_documents — UN CONTRATTO, PIÙ DOCUMENTI
--
-- §5, ed è il punto in cui questo modulo si distingue da una cartella di PDF.
-- Il documento NON viene copiato (§4/§76): qui c'è un riferimento e il RUOLO che
-- quel documento ha nel rapporto.
--
-- ⚠️ Lo stato di lavorazione sta QUI e non sul contratto: ogni documento si
-- legge per conto proprio, e un allegato che non si riesce a leggere non deve
-- far sembrare guasto l'intero contratto.
-- ---------------------------------------------------------------------------
create table if not exists public.contract_documents (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies(id) on delete cascade,
  contract_id       uuid not null references public.contracts(id) on delete cascade,
  -- `cascade`: se il documento sparisce non deve restare un collegamento al
  -- nulla. Il contratto sopravvive — un contratto senza documenti è uno stato
  -- legittimo (creato a mano, in attesa che il PDF arrivi).
  document_id       uuid not null references public.documents(id) on delete cascade,

  relation          public.contract_document_relation not null default 'other',
  origin            public.contract_origin not null default 'manual',

  processing_status public.contract_processing_status not null default 'pending',
  current_extraction_id uuid,
  extraction_attempts   integer not null default 0,
  error_code        text,

  -- §77 — un suggerimento accettato resta tracciato come tale: «l'ha collegato
  -- una persona» e «l'ha proposto il sistema e una persona ha detto sì» sono due
  -- storie diverse, e la seconda va ricostruibile.
  suggested         boolean not null default false,
  added_by          uuid references auth.users(id) on delete set null,
  added_at          timestamptz not null default now(),

  constraint uq_contract_document unique (contract_id, document_id)
);

comment on table public.contract_documents is
  'Il ruolo di un documento dentro un contratto. Il file NON viene copiato: '
  'resta del documento. Un amendment collegato apre una revisione (§26).';


-- ---------------------------------------------------------------------------
-- 6. contract_extractions — IL VERBALE, IMMUTABILE E VERSIONATO
--
-- §11/§13 — stessa disciplina di `document_analyses` (0010) e di
-- `finance_extractions` (0021): uno snapshot non si corregge, si affianca. Un
-- secondo tentativo produce la versione 2 e la 1 resta leggibile.
--
-- ⚠️ L'ESTRAZIONE È PER DOCUMENTO, NON PER CONTRATTO, e non è un dettaglio:
-- l'accordo principale dice preavviso 3 mesi, l'amendment dice 6. Se
-- l'estrazione fosse del contratto, la seconda lettura cancellerebbe la prima e
-- con essa la possibilità di rispondere a «da dove viene questo termine?».
-- I TERMINI IN VIGORE sono un'altra cosa e stanno nel punto 7.
--
-- ⚠️ PERCHÉ NON SI ESTENDE `document_analyses` CON QUARANTA COLONNE (§12).
-- Quella tabella descrive un documento amministrativo — mittente, scadenza,
-- importo, azioni — ed è letta da Admin AI, dal Document Hub, dalle Attività,
-- dalle Automazioni e da Finance. Aggiungerle «ancoraggio del preavviso» e
-- «modalità di disdetta» significherebbe far portare a tutti il peso di un
-- dominio che riguarda un documento su venti, e obbligare ogni lettore a sapere
-- quali colonne sono nulle perché il documento non è un contratto.
-- ---------------------------------------------------------------------------
create table if not exists public.contract_extractions (
  id                 uuid primary key default gen_random_uuid(),
  company_id         uuid not null references public.companies(id) on delete cascade,
  contract_id        uuid not null references public.contracts(id) on delete cascade,
  document_id        uuid not null references public.documents(id) on delete cascade,
  extraction_version integer not null default 1,
  status             public.contract_extraction_status not null default 'completed',

  method             text not null default 'ai',
  provider           text,
  model              text,
  prompt_version     text,
  schema_version     integer not null default 1,

  -- ---- Che cosa sembra essere ---------------------------------------------
  detected_type      public.contract_type,
  -- §3 — i contratti fuori perimetro. Testo LIBERO e non un enum: qui non si
  -- classifica, si RIPORTA che cosa il documento sembra essere, perché la sola
  -- decisione che il prodotto prende è «non me ne occupo io».
  out_of_scope_kind  text,

  -- ---- Le parti (§29) ------------------------------------------------------
  company_party      text,
  counterparty       text,
  counterparty_address text,

  -- ---- Le date (§32/§33) ---------------------------------------------------
  -- ⚠️ TRE DATE DIVERSE E NON UNA. La data stampata sul documento, la data della
  -- firma e la data da cui il contratto ha effetto sono tre fatti distinti che
  -- coincidono spesso e non sempre; fonderli renderebbe impossibile accorgersi
  -- di un contratto firmato a marzo con effetto da luglio.
  document_date      date,
  signature_date     date,
  start_date         date,
  end_date           date,
  end_date_kind      public.contract_end_kind not null default 'unknown',

  -- §34 — la durata minima si estrae SE indicata. ⚠️ Non si trasforma in una
  -- data di fine quando la data d'inizio non è certa: sommare mesi a una data
  -- incerta produce una scadenza che sembra un fatto.
  minimum_term_value integer,
  minimum_term_unit  public.contract_period_unit,

  -- ---- Rinnovo e disdetta (§35–§38, §49, §50) ------------------------------
  auto_renewal       public.contract_auto_renewal not null default 'unclear',
  renewal_period_value integer,
  renewal_period_unit  public.contract_period_unit,

  notice_period_value  integer,
  notice_period_unit   public.contract_period_unit,
  notice_anchor        public.contract_notice_anchor,
  -- Il testo dell'ancoraggio COSÌ COM'È SCRITTO. È ciò che si mostra quando il
  -- calcolo non è possibile: «auf Monatsende» detto in tedesco vale più di
  -- qualunque nostra parafrasi.
  notice_anchor_text   text,

  termination_method   public.contract_termination_method,
  -- §50 — l'indirizzo per la disdetta si estrae, e non diventa MAI il
  -- destinatario di un invio: in questo modulo non esiste alcun invio.
  termination_address  text,

  -- ---- Costi (§52–§56) -----------------------------------------------------
  -- `numeric` senza precisione dichiarata: esatto, come in Finance. Un
  -- `numeric(18,2)` arrotonderebbe in silenzio.
  cost_amount        numeric,
  cost_currency      text,
  cost_frequency     public.contract_cost_frequency not null default 'unknown',
  -- Solo se il documento lo dichiara: `null` è «non lo dice», non «no».
  cost_vat_included  boolean,
  -- §56 — esiste una clausola di adeguamento prezzi. Si segnala la CLAUSOLA, non
  -- si prevede l'importo futuro.
  price_adjustment   boolean not null default false,

  -- ---- Elenchi con citazione (§16/§57/§59/§61) -----------------------------
  -- [{ "party": "…", "text": "…", "cadence": "…", "confidence": 0.8,
  --    "evidence": { "quote": "…", "start": 0, "end": 0, "page": 1 } }]
  obligations        jsonb not null default '[]'::jsonb,
  -- [{ "kind": "exclusivity", "text": "…", "evidence": {…} }] — RILEVAZIONI
  -- FATTUALI, non giudizi: «è presente una clausola di esclusiva» (§60).
  attention_clauses  jsonb not null default '[]'::jsonb,
  -- [{ "text": "…", "amount": "…", "currency": "CHF", "evidence": {…} }]
  penalties          jsonb not null default '[]'::jsonb,
  -- §115 — allegati e condizioni generali RICHIAMATI dal testo.
  referenced_annexes jsonb not null default '[]'::jsonb,

  -- ---- Solo se scritto (§12) -----------------------------------------------
  governing_law      text,
  jurisdiction       text,
  -- §117 — indicazione di firma riconoscibile nel testo. Nessuna verifica
  -- crittografica: non esiste infrastruttura per farla, e affermarla sarebbe
  -- una garanzia inventata.
  signed             boolean,

  -- ---- Provenienza, fiducia, citazioni, incertezze -------------------------
  field_sources      jsonb not null default '{}'::jsonb,
  field_confidence   jsonb not null default '{}'::jsonb,
  evidence           jsonb not null default '{}'::jsonb,
  uncertainties      jsonb not null default '[]'::jsonb,
  quality_flags      public.contract_quality_flag[] not null default '{}',
  document_language  text,
  -- §113 — il documento non ci stava per intero. Non è un dettaglio tecnico: è
  -- la ragione per cui una clausola importante può mancare, e va detto.
  truncated          boolean not null default false,

  -- §112 — impronta del testo letto. Rileggere due volte lo stesso identico
  -- documento è spesa pura: se l'impronta coincide con quella dell'ultima
  -- estrazione riuscita, non si richiama il modello.
  content_hash       text,

  error_code         text,
  input_tokens       integer,
  output_tokens      integer,
  duration_ms        integer,
  created_at         timestamptz not null default now(),

  constraint uq_contract_extraction_version
    unique (contract_id, document_id, extraction_version)
);

-- I collegamenti all'estrazione corrente si dichiarano QUI: le tabelle si
-- riferiscono a vicenda e alla creazione della prima la seconda non esiste.
-- `set null` e non `cascade`: se un giorno si potassero i verbali vecchi, il
-- collegamento deve sopravvivere alla potatura invece di sparire con essa.
do $$ begin
  alter table public.contract_documents
    add constraint contract_documents_current_extraction_fkey
    foreign key (current_extraction_id) references public.contract_extractions(id)
    on delete set null;
exception when duplicate_object then null; end $$;

comment on table public.contract_extractions is
  'Verbale IMMUTABILE della lettura contrattuale di UN documento. L''accordo e '
  'il suo amendment hanno estrazioni distinte: è ciò che permette di dire da '
  'quale documento viene un termine.';


-- ---------------------------------------------------------------------------
-- 7. contract_term_versions — I TERMINI, VERSIONATI
--
-- ⚠️⚠️ IL CUORE DEL MODULO. LEGGERE PRIMA DI CAMBIARE QUALUNQUE COSA QUI.
--
-- §24/§25 — «l'accordo dice preavviso 3 mesi, l'amendment dice 6» non si risolve
-- sovrascrivendo. Qui una versione è una FOTOGRAFIA dei termini in vigore a
-- partire da una certa data, e le versioni si accumulano.
--
-- LE DUE FACCE DI QUESTA TABELLA:
--   · una BOZZA (`draft`) è ciò che il sistema PROPONE. Si ricalcola da sola —
--     versione verificata precedente, più le estrazioni, più le correzioni
--     umane — e non è mai un termine in vigore. Ne esiste al massimo una per
--     contratto (indice unico parziale più sotto).
--   · una versione VERIFICATA è ciò che una PERSONA ha confermato. Da quel
--     momento è IMMUTABILE (trigger), diventa `contracts.current_term_version_id`
--     e la precedente passa a `superseded` restando leggibile.
--
-- ⚠️ PERCHÉ NON BASTAVA «CORREZIONE VINCE SULL'ESTRAZIONE» COME IN FINANCE.
-- Su una fattura il valore giusto è uno solo e il tempo non lo cambia: l'importo
-- letto male oggi era sbagliato anche ieri. Un contratto no — il preavviso di
-- tre mesi ERA vero fino all'amendment, e resta la risposta giusta alla domanda
-- «che cosa valeva a gennaio?». Una proiezione a valore unico cancellerebbe
-- quella risposta ogni volta che arriva un documento nuovo.
--
-- ⚠️ UN AMENDMENT NON CAMBIA I TERMINI DA SOLO (§28). Produce una bozza e mette
-- il contratto in `review_required_again`: fino alla verifica umana, i termini
-- in vigore restano quelli di prima. Questa riga è la ragione per cui la
-- gestione degli amendment non è una funzione, ma una tabella.
-- ---------------------------------------------------------------------------
create table if not exists public.contract_term_versions (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies(id) on delete cascade,
  contract_id       uuid not null references public.contracts(id) on delete cascade,
  version           integer not null,
  status            public.contract_term_version_status not null default 'draft',

  -- Da quando questi termini valgono, SE il documento lo dice. Non si deduce
  -- dalla data di caricamento: un amendment firmato a giugno con effetto da
  -- gennaio non ha effetto da giugno.
  effective_from    date,

  -- ---- I termini (gli stessi campi dell'estrazione, per confronto diretto) --
  counterparty_name text,
  company_party     text,
  start_date        date,
  end_date          date,
  end_date_kind     public.contract_end_kind not null default 'unknown',
  minimum_term_value integer,
  minimum_term_unit  public.contract_period_unit,
  auto_renewal      public.contract_auto_renewal not null default 'unclear',
  renewal_period_value integer,
  renewal_period_unit  public.contract_period_unit,
  notice_period_value  integer,
  notice_period_unit   public.contract_period_unit,
  notice_anchor        public.contract_notice_anchor,
  notice_anchor_text   text,
  termination_method   public.contract_termination_method,
  termination_address  text,
  cost_amount       numeric,
  cost_currency     text,
  cost_frequency    public.contract_cost_frequency not null default 'unknown',
  cost_vat_included boolean,
  price_adjustment  boolean not null default false,

  -- ---- Provenienza ---------------------------------------------------------
  -- §25 — da quali documenti vengono questi termini. Un array e non una singola
  -- chiave: una versione può nascere dall'accordo più il suo amendment.
  source_extraction_ids uuid[] not null default '{}',
  -- La versione verificata da cui questa bozza è partita. È ciò che permette il
  -- confronto «prima / adesso» (§27) senza ricostruirlo a mano.
  based_on_version_id uuid references public.contract_term_versions(id) on delete set null,

  verified_at       timestamptz,
  verified_by       uuid references auth.users(id) on delete set null,
  superseded_at     timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),

  constraint uq_contract_term_version unique (contract_id, version),
  -- Una versione verificata ha sempre il suo timbro: «verificata da nessuno» non
  -- è uno stato, è un difetto.
  constraint contract_term_verified_stamped
    check (status <> 'verified' or verified_at is not null)
);

-- ⚠️ UNA SOLA BOZZA PER CONTRATTO. Due bozze significherebbero due proposte
-- diverse sugli stessi termini, e nessun modo di dire quale l'interfaccia stia
-- mostrando. L'indice unico parziale lo rende impossibile invece di improbabile.
create unique index if not exists uq_contract_single_draft
  on public.contract_term_versions (contract_id)
  where status = 'draft';

do $$ begin
  alter table public.contracts
    add constraint contracts_current_term_version_fkey
    foreign key (current_term_version_id) references public.contract_term_versions(id)
    on delete set null;
exception when duplicate_object then null; end $$;

comment on table public.contract_term_versions is
  'I termini contrattuali, versionati. Una bozza è ciò che il sistema propone e '
  'si ricalcola; una versione verificata è ciò che una persona ha confermato ed '
  'è immutabile. Un amendment non cambia i termini in vigore: crea una bozza.';


-- ---------------------------------------------------------------------------
-- 8. contract_corrections — LE CORREZIONI UMANE, IN AGGIUNTA
--
-- §21/§22 — append-only, come `finance_corrections`. L'estrazione non si tocca:
-- il valore originariamente letto resta sempre visibile e auditabile.
--
-- ⚠️ LA CORREZIONE SI APPLICA ALLA BOZZA, NON AL CONTRATTO.
-- È la conseguenza del punto 7: correggere «il preavviso» senza dire di QUALE
-- versione si parla vorrebbe dire riscrivere anche il passato. La bozza a cui la
-- correzione appartiene resta scritta nella riga, e quando quella bozza viene
-- verificata la correzione diventa parte di una versione immutabile.
-- ---------------------------------------------------------------------------
create table if not exists public.contract_corrections (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  contract_id     uuid not null references public.contracts(id) on delete cascade,
  term_version_id uuid not null references public.contract_term_versions(id) on delete cascade,
  -- Quale verbale era in vigore quando la persona ha corretto. `set null`: la
  -- correzione sopravvive comunque.
  extraction_id   uuid references public.contract_extractions(id) on delete set null,
  field           text not null,
  original_value  jsonb,
  corrected_value jsonb,
  corrected_by    uuid references auth.users(id) on delete set null,
  corrected_at    timestamptz not null default now(),

  -- Elenco CHIUSO, come in Finance: un campo fuori elenco non è «un campo che
  -- non conosciamo», è una scrittura che non deve avvenire, perché il ricalcolo
  -- non saprebbe che farsene e il dato resterebbe invisibile.
  constraint contract_correction_field_known check (field in (
    'counterparty_name', 'company_party',
    'start_date', 'end_date', 'end_date_kind',
    'minimum_term_value', 'minimum_term_unit',
    'auto_renewal', 'renewal_period_value', 'renewal_period_unit',
    'notice_period_value', 'notice_period_unit', 'notice_anchor', 'notice_anchor_text',
    'termination_method', 'termination_address',
    'cost_amount', 'cost_currency', 'cost_frequency', 'cost_vat_included',
    'price_adjustment', 'effective_from'
  ))
);

comment on table public.contract_corrections is
  'Correzioni umane, append-only, riferite a UNA bozza di termini. '
  'L''estrazione resta intatta e il valore letto dalla macchina resta visibile.';


-- ---------------------------------------------------------------------------
-- 9. contract_milestones — LE DATE CHE MERITANO ATTENZIONE
--
-- §40–§44. Una milestone è una DATA, non un momento: `date` e non `timestamptz`.
-- «Il preavviso scade il 30 settembre» non ha un'ora, e dargliela obbligherebbe
-- a scegliere un fuso — cioè a inventare un dato per far tornare un tipo.
--
-- ⚠️ CANDIDATA ≠ VERIFICATA, ED È LA DISTINZIONE PIÙ IMPORTANTE DEL MODULO.
-- Una data derivata da una clausola di preavviso è una PROPOSTA: nasce
-- `candidate` e non può generare lavoro (§87). Solo dopo che una persona l'ha
-- guardata diventa `verified`, e da lì in poi è materia di attività, calendario
-- e automazioni.
-- ---------------------------------------------------------------------------
create table if not exists public.contract_milestones (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies(id) on delete cascade,
  contract_id       uuid not null references public.contracts(id) on delete cascade,
  -- Da quale versione dei termini discende. `null` per le date messe a mano, che
  -- non discendono da nessun termine ma da una decisione.
  term_version_id   uuid references public.contract_term_versions(id) on delete set null,

  kind              public.contract_milestone_kind not null,
  due_date          date not null,
  -- Il default è `manual` perché il client non ha il permesso di scrivere questa
  -- colonna: quando una persona aggiunge una data dall'interfaccia, il valore
  -- che arriva è questo. Il prodotto, che scrive dal trigger, lo dichiara sempre
  -- esplicitamente.
  source            public.contract_milestone_source not null default 'manual',
  status            public.contract_milestone_status not null default 'candidate',

  -- §42 — la provenienza di un CALCOLO. Senza questi campi una data derivata
  -- sarebbe indistinguibile da una letta, e nessuno potrebbe rispondere a
  -- «perché il 30 settembre?».
  calculation       text,
  calculation_version integer,
  calculation_inputs jsonb not null default '{}'::jsonb,

  -- Etichetta libera, per `other` e per le date manuali.
  label             text,

  -- §95 — quando la finestra di attenzione si è aperta. Serve a emettere
  -- l'evento UNA volta sola: senza, ogni passaggio del worker lo riemetterebbe e
  -- il motore creerebbe un'attività ogni cinque minuti.
  window_opened_at  timestamptz,

  verified_at       timestamptz,
  verified_by       uuid references auth.users(id) on delete set null,
  dismissed_at      timestamptz,
  dismissed_by      uuid references auth.users(id) on delete set null,

  created_by        uuid references auth.users(id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),

  -- Una data verificata porta sempre il suo timbro.
  constraint contract_milestone_verified_stamped
    check (status <> 'verified' or verified_at is not null),
  -- Una data DERIVATA dichiara sempre da quale calcolo viene (§42). Senza questo
  -- vincolo, un giorno qualcuno inserirebbe una derivata senza provenienza e
  -- nessuno saprebbe più distinguerla da una letta nel documento.
  constraint contract_milestone_derived_has_provenance
    check (source <> 'derived' or (calculation is not null and calculation_version is not null))
);

comment on table public.contract_milestones is
  'Date del contratto. `candidate` è una proposta del sistema e NON può '
  'generare lavoro; `verified` è una data che una persona ha confermato. Una '
  'data derivata dichiara sempre il calcolo da cui viene.';


-- ---------------------------------------------------------------------------
-- 10. contract_events — LO STORICO
--
-- Lo scrivono i trigger. Il client non può inserirlo: uno storico che una
-- schermata può fabbricare non è uno storico.
-- ---------------------------------------------------------------------------
create table if not exists public.contract_events (
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid not null references public.companies(id) on delete cascade,
  contract_id   uuid not null references public.contracts(id) on delete cascade,
  actor_user_id uuid references auth.users(id) on delete set null,
  kind          public.contract_event_kind not null,
  -- ⚠️ SOLO IDENTIFICATIVI E CHIAVI (§110). Nel dettaglio di un evento non entra
  -- il testo di una clausola, un indirizzo, un importo o il nome di una parte:
  -- lo storico è leggibile da ogni membro dell'azienda e non deve diventare una
  -- seconda copia del contratto.
  detail        jsonb not null default '{}'::jsonb,
  created_at    timestamptz not null default now()
);


-- ---------------------------------------------------------------------------
-- 11. Le attività sanno a quale contratto appartengono
--
-- §88 — «NON mettere contract ID nella description». Una descrizione non è un
-- riferimento: non si può interrogare, non regge una chiave esterna e diventa
-- falsa il giorno in cui il contratto viene rinominato.
--
-- ⚠️ QUI SERVE UN GUARDIANO, NON UN GRANT DI COLONNA.
-- Su `tasks` la 0004 concede `select, insert, update, delete` di TABELLA a
-- `authenticated`. Un `grant (contract_id)` scritto ora non toglierebbe nulla —
-- è la lezione della 0014, dove i permessi di colonna dichiarati nei commenti
-- non restringevano niente. L'unica difesa possibile è un trigger che confronti
-- le aziende (§105), ed è quello che c'è al punto 16.
-- ---------------------------------------------------------------------------
alter table public.tasks
  add column if not exists contract_id uuid references public.contracts(id) on delete set null,
  add column if not exists contract_milestone_id uuid
    references public.contract_milestones(id) on delete set null;

comment on column public.tasks.contract_id is
  'Il contratto da cui l''attività nasce. Chiave esterna e non testo nella '
  'descrizione: un riferimento deve reggere una rinomina e una interrogazione.';


-- ---------------------------------------------------------------------------
-- 12. Indici
--
-- §160 — ognuno corrisponde a una clausola che le funzioni di questo file
-- scrivono davvero. Nessun indice «per sicurezza»: un indice che nessuna query
-- usa è solo scrittura più lenta.
-- ---------------------------------------------------------------------------

-- La lista predefinita: contratti non archiviati di un'azienda.
create index if not exists idx_contracts_active
  on public.contracts (company_id, updated_at desc)
  where archived_at is null;

-- La vista rapida «Da verificare» e il KPI omonimo.
create index if not exists idx_contracts_review
  on public.contracts (company_id, review_status)
  where archived_at is null;

create index if not exists idx_contracts_lifecycle
  on public.contracts (company_id, lifecycle_status)
  where archived_at is null;

create index if not exists idx_contracts_type
  on public.contracts (company_id, contract_type)
  where archived_at is null;

-- «Senza responsabile» è un KPI (§67): l'indice parziale lo rende un accesso
-- diretto invece di una scansione di tutti i contratti dell'azienda.
create index if not exists idx_contracts_owner
  on public.contracts (company_id, owner_user_id)
  where archived_at is null;

create index if not exists idx_contracts_archived
  on public.contracts (company_id, archived_at desc)
  where archived_at is not null;

-- La ricerca per nome e controparte (§68). Stessa forma degli indici trigram del
-- Document Hub (0017), su un'espressione: un `coalesce` evita che una
-- controparte non ancora nota escluda la riga dall'indice.
create index if not exists idx_contracts_text_trgm
  on public.contracts using gin (
    (coalesce(display_name, '') || ' ' || coalesce(counterparty_name, '')) gin_trgm_ops
  );

create index if not exists idx_contract_documents_contract
  on public.contract_documents (contract_id, relation);
-- Da un documento ai suoi contratti: serve al Document Hub («questo documento
-- appartiene al contratto X») e al riconoscimento dei suggerimenti.
create index if not exists idx_contract_documents_document
  on public.contract_documents (document_id);
-- La coda del worker: i documenti da leggere, i più vecchi per primi.
create index if not exists idx_contract_documents_pending
  on public.contract_documents (processing_status, added_at)
  where processing_status in ('pending', 'processing');

create index if not exists idx_contract_extractions_doc
  on public.contract_extractions (contract_id, document_id, extraction_version desc);
create index if not exists idx_contract_extractions_hash
  on public.contract_extractions (document_id, content_hash)
  where status = 'completed';

create index if not exists idx_contract_terms_contract
  on public.contract_term_versions (contract_id, version desc);

create index if not exists idx_contract_corrections_version
  on public.contract_corrections (term_version_id, corrected_at);

-- Le milestone che contano: quelle ancora in gioco, per data. È l'interrogazione
-- di «Rinnovi prossimi», di «Preavvisi prossimi» e del worker che apre le
-- finestre.
create index if not exists idx_contract_milestones_open
  on public.contract_milestones (company_id, due_date, status)
  where status in ('candidate', 'verified');
create index if not exists idx_contract_milestones_contract
  on public.contract_milestones (contract_id, due_date);
-- Il worker cerca le verificate la cui finestra non è ancora stata aperta.
create index if not exists idx_contract_milestones_window
  on public.contract_milestones (due_date)
  where status = 'verified' and window_opened_at is null;

create index if not exists idx_contract_events_contract
  on public.contract_events (contract_id, created_at desc);

-- Le attività di un contratto (§90) e il controllo di deduplicazione (§93).
create index if not exists idx_tasks_contract
  on public.tasks (contract_id)
  where contract_id is not null;
create index if not exists idx_tasks_contract_milestone
  on public.tasks (contract_milestone_id)
  where contract_milestone_id is not null;


-- ---------------------------------------------------------------------------
-- 13. L'ARITMETICA DELLE DATE
--
-- ⚠️⚠️ §47 — L'AI NON CALCOLA MAI UNA DATA. Il modello può leggere «tre mesi
-- prima della scadenza»; la data la fa questo codice, che è deterministico,
-- ripetibile e messo alla prova sui casi difficili da `npm run test:contracts`.
--
-- ⚠️ PERCHÉ IL CALCOLO STA IN SQL E NON IN TYPESCRIPT.
-- Perché deve stare in UN POSTO SOLO, e il posto in cui le date NASCONO è qui:
-- le milestone le scrive un trigger, nella stessa transazione della verifica dei
-- termini, così una persona che verifica vede subito le date invece di
-- aspettare un worker. Scriverlo anche in TypeScript creerebbe il doppione che
-- questo progetto ha già pagato con `urgencyFrom`, e su una data un doppione
-- che diverge è una scadenza sbagliata.
--
-- ⚠️ SEMANTICA DI POSTGRES, VERIFICATA E NON SUPPOSTA: sottrarre mesi da una
-- data «aggancia» la fine del mese quando il giorno non esiste
-- (31.03 − 1 mese → 28.02, e in un anno bisestile → 29.02). È il comportamento
-- che serve, ed è quello che `test:contracts` verifica contro il database vero
-- invece di fidarsi di questo commento.
-- ---------------------------------------------------------------------------
create or replace function public.contract_period_interval(
  p_value integer,
  p_unit  public.contract_period_unit
)
returns interval
language sql
immutable
set search_path = ''
as $$
  select case
    when p_value is null or p_unit is null or p_value <= 0 then null
    when p_unit = 'days'   then make_interval(days   => p_value)
    when p_unit = 'weeks'  then make_interval(weeks  => p_value)
    when p_unit = 'months' then make_interval(months => p_value)
    when p_unit = 'years'  then make_interval(years  => p_value)
  end
$$;

comment on function public.contract_period_interval(integer, public.contract_period_unit) is
  'Un periodo contrattuale come intervallo. NULL su valori non positivi o unità '
  'assente: un periodo che non si sa non è un periodo di zero giorni.';

/*
 * Il termine ultimo di disdetta, SE è derivabile.
 *
 * ⚠️⚠️ §39/§45/§46 — QUESTA FUNZIONE RESTITUISCE NULL PIÙ SPESSO DI QUANTO
 * SEMBRI RAGIONEVOLE, ED È IL SUO SCOPO.
 *
 * CHE COSA SI CALCOLA (e di cui il prodotto risponde):
 *   · preavviso ancorato a una FINE ESPLICITA         → fine − periodo
 *   · preavviso ancorato a una DATA DI RINNOVO nota   → rinnovo − periodo
 *
 * CHE COSA NON SI CALCOLA, E NON PER MANCANZA DI TEMPO:
 *   · «auf Monatsende» / «per fine mese» — servirebbe sapere a quale scadenza il
 *     preavviso si riferisce e come le due regole si compongono. Due letture
 *     legittime della stessa clausola danno due date diverse, e sceglierne una
 *     significherebbe che il prodotto ha deciso una questione di
 *     interpretazione del contratto.
 *   · fine trimestre, fine anno — stessa ragione.
 *   · «in qualsiasi momento» — non esiste una scadenza a cui ancorare.
 *   · ancoraggio ignoto o assente — §39 alla lettera.
 *   · durata minima senza data d'inizio certa (§34) — sommare mesi a una data
 *     incerta produce una scadenza che sembra un fatto.
 *
 * In tutti questi casi l'interfaccia mostra il preavviso, mostra la clausola da
 * cui viene, e dichiara che una data non è derivabile. È la risposta onesta, e
 * l'unica che non produce una scadenza sbagliata su cui qualcuno agirebbe.
 */
create or replace function public.contract_notice_deadline(
  p_notice_value  integer,
  p_notice_unit   public.contract_period_unit,
  p_anchor        public.contract_notice_anchor,
  p_reference_date date
)
returns date
language sql
immutable
set search_path = ''
as $$
  select case
    when p_reference_date is null then null
    when p_anchor is null or p_anchor not in ('before_fixed_end', 'before_renewal_date') then null
    when public.contract_period_interval(p_notice_value, p_notice_unit) is null then null
    else (p_reference_date - public.contract_period_interval(p_notice_value, p_notice_unit))::date
  end
$$;

comment on function public.contract_notice_deadline(integer, public.contract_period_unit, public.contract_notice_anchor, date) is
  'Il termine ultimo di disdetta, SOLO per gli ancoraggi di cui il prodotto '
  'risponde (fine esplicita, data di rinnovo). NULL su «per fine mese», fine '
  'trimestre, «in qualsiasi momento» e ancoraggio ignoto: là la semantica non è '
  'univoca e una data calcolata sarebbe un''interpretazione travestita da fatto.';

/** La versione del calcolo, scritta su ogni data derivata (§42). */
create or replace function public.contract_calculation_version()
returns integer language sql immutable set search_path = '' as $$ select 1 $$;


-- ---------------------------------------------------------------------------
-- 14. Il guardiano del contratto
--
-- Chi ha verificato, chi ha archiviato e quando: lo scrive il database da
-- `auth.uid()` e `now()`, mai il client (§107). Il client dichiara l'INTENZIONE,
-- il valore vero lo mette qui.
--
-- ⚠️ §102 — IL RESPONSABILE DEVE ESSERE MEMBRO DELL'AZIENDA, e il controllo sta
-- qui e non nel servizio: un servizio ben educato non è una garanzia. Vale anche
-- per il worker e per gli script, che passano di qui come tutti.
-- ---------------------------------------------------------------------------
create or replace function public.contracts_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Il responsabile, se indicato, è membro di QUESTA azienda (§102/§154).
  if new.owner_user_id is not null and (
       tg_op = 'INSERT' or new.owner_user_id is distinct from old.owner_user_id
     ) then
    if not exists (
      select 1 from public.company_members m
      where m.company_id = new.company_id and m.user_id = new.owner_user_id
    ) then
      raise exception 'contract_owner_not_member'
        using errcode = '23514',
              hint = 'Il responsabile di un contratto deve essere membro dell''azienda.';
    end if;
  end if;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    -- Chi ha creato il contratto lo stabilisce il database. Il client non ha il
    -- permesso di colonna su `origin`, quindi un inserimento dall'interfaccia
    -- prenderebbe il default e direbbe di essere nato da una regola. Stessa
    -- distinzione sistema/persona di `documents_guard` e `finance_items_guard`:
    -- `auth.uid()` da solo non basta, perché un trigger può scattare mentre una
    -- persona è in sessione; `pg_trigger_depth() > 1` dice che a scrivere è
    -- stato il prodotto.
    if auth.uid() is not null and pg_trigger_depth() <= 1 then
      new.origin := 'manual';
    end if;
    -- Nessun contratto nasce verificato: la verifica è un gesto umano (§82).
    new.review_status := 'needs_review';
    new.verified_at := null;
    new.verified_by := null;
    new.archived_by := null;
    new.current_term_version_id := null;
    new.quality_flags := '{}';
    if new.archived_at is not null then new.archived_at := now(); end if;
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;

  -- ---- UPDATE ------------------------------------------------------------
  new.company_id := old.company_id;
  new.created_by := old.created_by;
  new.created_at := old.created_at;
  new.origin     := old.origin;
  new.updated_at := now();

  -- ⚠️ IL TIMBRO DI VERIFICA E LA VERSIONE CORRENTE NON SI SCRIVONO DAL CLIENT.
  -- Verificare un contratto significa verificare una VERSIONE DEI TERMINI, e
  -- quel percorso è `contract_verify_terms` (punto 24), che è l'unico posto in
  -- cui questi tre campi cambiano insieme e in modo coerente. Un client che
  -- scrivesse `review_status = 'verified'` da solo otterrebbe un contratto
  -- «verificato» senza alcuna versione verificata dietro: la dichiarazione
  -- senza il fatto.
  --
  -- ⚠️ DUE SENTINELLE E NON UNA, e la differenza è sostanziale.
  -- `contract_verify` è il gesto umano completo: cambia stato, timbro e versione
  -- in vigore. `contract_review` è la RIAPERTURA che un amendment provoca: tocca
  -- SOLO lo stato, e lascia deliberatamente in piedi `verified_at`/`verified_by`
  -- della verifica precedente — §84 chiede di non cancellare la storia delle
  -- verifiche, e «era stato verificato il 3 marzo, poi è arrivata una modifica»
  -- è proprio ciò che si vuole poter dire.
  --
  -- ⚠️ Senza la seconda sentinella la riapertura sarebbe stata annullata QUI, in
  -- silenzio: l'amendment sarebbe arrivato, la bozza si sarebbe formata, e il
  -- contratto avrebbe continuato a dichiararsi verificato. Il difetto peggiore
  -- di questo modulo, evitato per un soffio.
  if coalesce(current_setting('ai_swisse.contract_verify', true), '') = '1' then
    null;   -- il percorso di verifica scrive tutto ciò che gli serve
  elsif coalesce(current_setting('ai_swisse.contract_review', true), '') = '1' then
    new.verified_at := old.verified_at;
    new.verified_by := old.verified_by;
    new.current_term_version_id := old.current_term_version_id;
  else
    new.review_status  := old.review_status;
    new.verified_at    := old.verified_at;
    new.verified_by    := old.verified_by;
    new.current_term_version_id := old.current_term_version_id;
  end if;

  -- La proiezione delle bandiere la ricalcola `contract_refresh_flags`.
  if coalesce(current_setting('ai_swisse.contract_refresh', true), '') <> '1' then
    new.quality_flags := old.quality_flags;
  end if;

  -- Archiviazione: solo alla PRIMA, come su `documents` e `finance_items`.
  if new.archived_at is not null and old.archived_at is null then
    new.archived_at := now();
    new.archived_by := auth.uid();
  elsif new.archived_at is null then
    new.archived_by := null;
  else
    new.archived_at := old.archived_at;
    new.archived_by := old.archived_by;
  end if;

  return new;
end $$;

drop trigger if exists trg_contracts_guard on public.contracts;
create trigger trg_contracts_guard
  before insert or update on public.contracts
  for each row execute function public.contracts_guard();


-- ---------------------------------------------------------------------------
-- 15. Il guardiano dei documenti collegati
--
-- §104 — UN CONTRATTO DELL'AZIENDA A NON PUÒ PUNTARE A UN DOCUMENTO DI B.
-- La RLS lo impedirebbe dal client, ma questa funzione è `security definer` e
-- deve difendersi da sola: è la disciplina imparata con la 0017, dove una
-- policy scritta altrove non bastava a proteggere un trigger che la scavalca.
-- ---------------------------------------------------------------------------
create or replace function public.contract_documents_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_contract_company uuid;
  v_doc_company      uuid;
begin
  select c.company_id into v_contract_company
    from public.contracts c where c.id = new.contract_id;
  select d.company_id into v_doc_company
    from public.documents d where d.id = new.document_id;

  if v_contract_company is null or v_doc_company is null
     or v_contract_company is distinct from v_doc_company
     or v_contract_company is distinct from new.company_id then
    raise exception 'contract_document_company_mismatch'
      using errcode = '23514',
            hint = 'Il documento e il contratto devono appartenere alla stessa azienda.';
  end if;

  if tg_op = 'INSERT' then
    new.added_by := auth.uid();
    new.added_at := now();
    if auth.uid() is not null and pg_trigger_depth() <= 1 then
      new.origin := 'manual';
    end if;
    new.current_extraction_id := null;
    new.extraction_attempts := 0;
    new.error_code := null;
    -- Ogni documento nuovo va letto: nasce in coda. Il worker lo prenderà.
    new.processing_status := 'pending';
    return new;
  end if;

  new.company_id  := old.company_id;
  new.contract_id := old.contract_id;
  new.document_id := old.document_id;
  new.added_by    := old.added_by;
  new.added_at    := old.added_at;

  -- Rimettere in coda è legittimo («Riprova lettura», §131), ma solo da uno
  -- stato FERMO: rimettere in coda ciò che è già in lavorazione produrrebbe due
  -- letture concorrenti sullo stesso documento.
  if new.processing_status = 'pending' and old.processing_status = 'processing' then
    new.processing_status := old.processing_status;
  end if;
  return new;
end $$;

drop trigger if exists trg_contract_documents_guard on public.contract_documents;
create trigger trg_contract_documents_guard
  before insert or update on public.contract_documents
  for each row execute function public.contract_documents_guard();


-- ---------------------------------------------------------------------------
-- 16. Il guardiano del legame fra attività e contratto
--
-- §105 — stessa difesa del punto 15, dall'altra parte. È l'UNICA difesa
-- possibile: su `tasks` il ruolo `authenticated` ha i permessi di tabella
-- completi dalla 0004, e nessun grant di colonna scritto oggi li restringerebbe
-- (lezione della 0014).
-- ---------------------------------------------------------------------------
create or replace function public.tasks_contract_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company   uuid;
  v_ms_contract uuid;
  v_ms_company  uuid;
begin
  if new.contract_id is not null then
    select c.company_id into v_company from public.contracts c where c.id = new.contract_id;
    if v_company is null or v_company is distinct from new.company_id then
      raise exception 'task_contract_company_mismatch'
        using errcode = '23514',
              hint = 'L''attività e il contratto devono appartenere alla stessa azienda.';
    end if;
  end if;

  if new.contract_milestone_id is not null then
    select m.contract_id, m.company_id into v_ms_contract, v_ms_company
      from public.contract_milestones m where m.id = new.contract_milestone_id;
    if v_ms_company is null or v_ms_company is distinct from new.company_id then
      raise exception 'task_milestone_company_mismatch'
        using errcode = '23514',
              hint = 'L''attività e la data del contratto devono appartenere alla stessa azienda.';
    end if;
    -- Una data appartiene a un contratto: agganciare l'attività alla data di un
    -- contratto e al riferimento di un altro produrrebbe una schermata che dice
    -- due cose diverse sulla stessa riga.
    if new.contract_id is not null and new.contract_id is distinct from v_ms_contract then
      raise exception 'task_milestone_contract_mismatch'
        using errcode = '23514',
              hint = 'La data indicata appartiene a un altro contratto.';
    end if;
    if new.contract_id is null then new.contract_id := v_ms_contract; end if;
  end if;

  return new;
end $$;

drop trigger if exists trg_tasks_contract_guard on public.tasks;
create trigger trg_tasks_contract_guard
  before insert or update of contract_id, contract_milestone_id, company_id on public.tasks
  for each row execute function public.tasks_contract_guard();


-- ---------------------------------------------------------------------------
-- 17. Le estrazioni sono IMMUTABILI (§13)
--
-- Stessa disciplina della 0010 e della 0021. Il divieto vale anche per il
-- service role, perché il worker gira proprio con quello e un giorno qualcuno
-- potrebbe pensare di «aggiornare» un verbale invece di scriverne uno nuovo.
--
-- ⚠️ SOLO `update`, MAI `delete` — è la lezione della 0023, pagata cara: un
-- trigger che vietava anche la cancellazione rendeva INDISTRUTTIBILE il
-- documento a monte, perché la cascata passa di qui ed è la conseguenza di una
-- cancellazione già autorizzata altrove. La cancellazione la impediscono i
-- PERMESSI (il client non ne ha), che è dove deve stare.
-- ---------------------------------------------------------------------------
create or replace function public.contract_extractions_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'contract_extraction_immutable'
    using errcode = '42501',
          hint = 'Un''estrazione non si modifica: se ne scrive una versione nuova.';
end $$;

drop trigger if exists trg_contract_extractions_immutable on public.contract_extractions;
create trigger trg_contract_extractions_immutable
  before update on public.contract_extractions
  for each row execute function public.contract_extractions_immutable();


-- ---------------------------------------------------------------------------
-- 18. Una versione VERIFICATA dei termini è immutabile
--
-- §25 — è ciò che rende vera la frase «l'amendment non sovrascrive». Una bozza
-- si può riscrivere quante volte serve; dal momento in cui una persona la
-- verifica, quei termini sono un fatto storico.
--
-- ⚠️ Anche qui `update` e non `delete`, per la ragione della 0023.
-- ---------------------------------------------------------------------------
create or replace function public.contract_term_versions_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    -- Nessuna versione nasce verificata: la si verifica con
    -- `contract_verify_terms`, che è l'unico percorso in cui il timbro, la
    -- versione corrente del contratto e le date restano coerenti fra loro.
    if new.status <> 'draft' then
      raise exception 'contract_term_version_must_start_draft'
        using errcode = '23514',
              hint = 'Una versione dei termini nasce come bozza e viene verificata da una persona.';
    end if;
    new.verified_at := null;
    new.verified_by := null;
    new.superseded_at := null;
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;

  -- ---- UPDATE ------------------------------------------------------------
  if old.status = 'verified' then
    -- L'unica transizione ammessa su una versione verificata è il passaggio a
    -- `superseded`, che non tocca i termini: dice soltanto che ne esiste una più
    -- recente. Tutto il resto sarebbe riscrivere la storia.
    if new.status = 'superseded'
       and new.start_date is not distinct from old.start_date
       and new.end_date is not distinct from old.end_date
       and new.notice_period_value is not distinct from old.notice_period_value
       and new.notice_period_unit is not distinct from old.notice_period_unit
       and new.notice_anchor is not distinct from old.notice_anchor
       and new.auto_renewal is not distinct from old.auto_renewal
       and new.renewal_period_value is not distinct from old.renewal_period_value
       and new.cost_amount is not distinct from old.cost_amount
       and new.cost_currency is not distinct from old.cost_currency
       and new.cost_frequency is not distinct from old.cost_frequency
       and new.verified_at is not distinct from old.verified_at
       and new.verified_by is not distinct from old.verified_by then
      new.superseded_at := coalesce(old.superseded_at, now());
      new.updated_at := now();
      return new;
    end if;
    raise exception 'contract_term_version_immutable'
      using errcode = '42501',
            hint = 'Una versione verificata dei termini non si modifica: se ne verifica una nuova.';
  end if;

  if old.status = 'superseded' then
    raise exception 'contract_term_version_immutable'
      using errcode = '42501',
            hint = 'Una versione superata resta com''era.';
  end if;

  new.company_id  := old.company_id;
  new.contract_id := old.contract_id;
  new.version     := old.version;
  new.created_at  := old.created_at;
  new.updated_at  := now();
  return new;
end $$;

drop trigger if exists trg_contract_term_versions_guard on public.contract_term_versions;
create trigger trg_contract_term_versions_guard
  before insert or update on public.contract_term_versions
  for each row execute function public.contract_term_versions_guard();


-- ---------------------------------------------------------------------------
-- 19. L'autore di una correzione è chi la scrive
--
-- §106 — RIFIUTA, non riscrive in silenzio. È la lezione dei commenti delle
-- attività (0016): sostituire l'autore e restituire «inserito» produce un
-- risultato sicuro e una conferma falsa.
--
-- ⚠️ SI CORREGGE SOLO UNA BOZZA. Correggere una versione verificata
-- significherebbe cambiare che cosa valeva l'anno scorso: se i termini sono
-- cambiati si verifica una versione nuova, che è esattamente il percorso degli
-- amendment.
-- ---------------------------------------------------------------------------
create or replace function public.contract_corrections_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_version record;
  v_text    text;
begin
  select v.id, v.company_id, v.contract_id, v.status
    into v_version
    from public.contract_term_versions v
   where v.id = new.term_version_id;

  if v_version.id is null
     or v_version.company_id is distinct from new.company_id
     or v_version.contract_id is distinct from new.contract_id then
    raise exception 'contract_correction_company_mismatch'
      using errcode = '23514',
            hint = 'La correzione non appartiene all''azienda o al contratto indicato.';
  end if;

  if v_version.status <> 'draft' then
    raise exception 'contract_correction_version_not_draft'
      using errcode = '42501',
            hint = 'Si corregge la versione in preparazione: quelle verificate restano com''erano.';
  end if;

  if auth.uid() is not null and new.corrected_by is not null
     and new.corrected_by is distinct from auth.uid() then
    raise exception 'contract_correction_author_mismatch'
      using errcode = '42501',
            hint = 'Una correzione si firma con il proprio nome.';
  end if;

  -- ⚠️ IL VALORE VA VERIFICATO QUI, NON A VALLE (lezione della 0021).
  -- Il ricalcolo della bozza converte con `try_date`/`try_numeric`, che tornano
  -- NULL su un testo non convertibile e fanno quindi ripiegare sul valore
  -- precedente: una correzione malformata verrebbe SALVATA, comparirebbe fra i
  -- campi corretti a mano, e la schermata continuerebbe a mostrare il valore
  -- vecchio. Una persona convinta di aver corretto una scadenza, e una scadenza
  -- che non è cambiata.
  if new.corrected_value is not null and jsonb_typeof(new.corrected_value) <> 'null' then
    v_text := new.corrected_value #>> '{}';

    if new.field in ('start_date', 'end_date', 'effective_from')
       and public.try_date(v_text) is null then
      raise exception 'contract_correction_bad_date'
        using errcode = '22007', hint = 'La data non è in un formato riconoscibile.';
    end if;

    if new.field in ('minimum_term_value', 'renewal_period_value', 'notice_period_value') then
      if public.try_numeric(v_text) is null or public.try_numeric(v_text) <= 0
         or public.try_numeric(v_text) <> trunc(public.try_numeric(v_text)) then
        raise exception 'contract_correction_bad_period'
          using errcode = '22P02', hint = 'Un periodo è un numero intero di unità, maggiore di zero.';
      end if;
    end if;

    if new.field in ('minimum_term_unit', 'renewal_period_unit', 'notice_period_unit')
       and lower(v_text) not in ('days', 'weeks', 'months', 'years') then
      raise exception 'contract_correction_bad_period_unit'
        using errcode = '22P02', hint = 'L''unità di un periodo non è fra quelle previste.';
    end if;

    if new.field = 'auto_renewal' and lower(v_text) not in ('yes', 'no', 'unclear') then
      raise exception 'contract_correction_bad_renewal'
        using errcode = '22P02', hint = 'Il rinnovo automatico ammette: sì, no, non chiaro.';
    end if;

    if new.field = 'notice_anchor' and lower(v_text) not in (
         'before_fixed_end', 'before_renewal_date', 'to_month_end', 'to_quarter_end',
         'to_year_end', 'anytime', 'other', 'unclear') then
      raise exception 'contract_correction_bad_anchor'
        using errcode = '22P02', hint = 'L''ancoraggio del preavviso non è fra quelli previsti.';
    end if;

    if new.field = 'end_date_kind' and lower(v_text) not in ('explicit', 'none', 'unknown') then
      raise exception 'contract_correction_bad_end_kind'
        using errcode = '22P02', hint = 'Il tipo di scadenza non è fra quelli previsti.';
    end if;

    if new.field = 'termination_method' and lower(v_text) not in (
         'written_notice', 'email', 'registered_mail', 'portal', 'other') then
      raise exception 'contract_correction_bad_termination'
        using errcode = '22P02', hint = 'La modalità di disdetta non è fra quelle previste.';
    end if;

    if new.field = 'cost_amount' and public.try_numeric(v_text) is null then
      raise exception 'contract_correction_bad_amount'
        using errcode = '22P02', hint = 'L''importo non è un numero.';
    end if;

    if new.field = 'cost_currency' and upper(v_text) !~ '^[A-Z]{3}$' then
      raise exception 'contract_correction_bad_currency'
        using errcode = '22P02', hint = 'La valuta è un codice ISO di tre lettere.';
    end if;

    if new.field = 'cost_frequency' and lower(v_text) not in (
         'one_time', 'monthly', 'quarterly', 'yearly', 'other', 'unknown') then
      raise exception 'contract_correction_bad_frequency'
        using errcode = '22P02', hint = 'La cadenza del costo non è fra quelle previste.';
    end if;

    if new.field in ('cost_vat_included', 'price_adjustment')
       and lower(v_text) not in ('true', 'false') then
      raise exception 'contract_correction_bad_boolean'
        using errcode = '22P02', hint = 'Il valore ammette solo sì o no.';
    end if;
  end if;

  new.corrected_by := coalesce(auth.uid(), new.corrected_by);
  new.corrected_at := now();
  -- Il verbale di riferimento lo stabilisce il database: farlo dichiarare al
  -- client vorrebbe dire permettergli di agganciare la correzione al documento
  -- sbagliato.
  select cd.current_extraction_id into new.extraction_id
    from public.contract_documents cd
   where cd.contract_id = new.contract_id
     and cd.current_extraction_id is not null
   order by (case cd.relation when 'amendment' then 0 when 'renewal' then 0
                              when 'main_agreement' then 1 else 2 end),
            cd.added_at desc
   limit 1;
  return new;
end $$;

drop trigger if exists trg_contract_corrections_guard on public.contract_corrections;
create trigger trg_contract_corrections_guard
  before insert on public.contract_corrections
  for each row execute function public.contract_corrections_guard();

create or replace function public.contract_corrections_append_only()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'contract_correction_append_only'
    using errcode = '42501',
          hint = 'Le correzioni si aggiungono: per cambiare un valore se ne scrive una nuova.';
end $$;

drop trigger if exists trg_contract_corrections_append_only on public.contract_corrections;
create trigger trg_contract_corrections_append_only
  before update on public.contract_corrections
  for each row execute function public.contract_corrections_append_only();


-- ---------------------------------------------------------------------------
-- 20. Il guardiano delle date
--
-- Il timbro di verifica e quello di rifiuto li scrive il database (§107), e una
-- data non cambia di natura: quello che è stato derivato resta derivato anche
-- dopo che una persona l'ha confermato — «verificata» dice che qualcuno l'ha
-- guardata, non che il prodotto l'abbia letta nel documento.
-- ---------------------------------------------------------------------------
create or replace function public.contract_milestones_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
begin
  select c.company_id into v_company from public.contracts c where c.id = new.contract_id;
  if v_company is null or v_company is distinct from new.company_id then
    raise exception 'contract_milestone_company_mismatch'
      using errcode = '23514',
            hint = 'La data non appartiene all''azienda del contratto.';
  end if;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
    new.updated_at := now();
    new.window_opened_at := null;
    -- ⚠️ Una data inserita da una PERSONA è `manual` e nasce già verificata: è
    -- una decisione, non una proposta del sistema, e chiederle una conferma
    -- separata sarebbe chiedere a qualcuno di confermare sé stesso. Le date che
    -- il prodotto propone nascono invece `candidate` e restano tali.
    if auth.uid() is not null and pg_trigger_depth() <= 1 then
      new.source := 'manual';
      new.calculation := null;
      new.calculation_version := null;
      new.calculation_inputs := '{}'::jsonb;
      new.status := 'verified';
      new.verified_at := now();
      new.verified_by := auth.uid();
    else
      new.verified_at := null;
      new.verified_by := null;
    end if;
    new.dismissed_at := null;
    new.dismissed_by := null;
    return new;
  end if;

  -- ---- UPDATE ------------------------------------------------------------
  new.company_id  := old.company_id;
  new.contract_id := old.contract_id;
  new.term_version_id := old.term_version_id;
  new.source      := old.source;
  new.kind        := old.kind;
  new.calculation := old.calculation;
  new.calculation_version := old.calculation_version;
  new.calculation_inputs  := old.calculation_inputs;
  new.created_by  := old.created_by;
  new.created_at  := old.created_at;
  new.updated_at  := now();

  -- ⚠️ LA DATA DI UNA MILESTONE DERIVATA NON SI MODIFICA A MANO.
  -- Cambiarla lascerebbe accanto una provenienza che dice «calcolata così» e un
  -- valore che quel calcolo non produce: la spiegazione smetterebbe di spiegare.
  -- Chi non è d'accordo con una data derivata la scarta e ne aggiunge una
  -- manuale, che dichiara di essere una decisione.
  if new.source = 'derived' and new.due_date is distinct from old.due_date then
    raise exception 'contract_milestone_derived_date_immutable'
      using errcode = '42501',
            hint = 'Una data calcolata non si modifica: si scarta e se ne aggiunge una manuale.';
  end if;

  if new.status is distinct from old.status then
    if new.status = 'verified' then
      new.verified_at := now();
      new.verified_by := auth.uid();
      new.dismissed_at := null;
      new.dismissed_by := null;
    elsif new.status = 'dismissed' then
      new.dismissed_at := now();
      new.dismissed_by := auth.uid();
    elsif new.status = 'candidate' then
      new.verified_at := null;
      new.verified_by := null;
      new.dismissed_at := null;
      new.dismissed_by := null;
    end if;
  else
    new.verified_at := old.verified_at;
    new.verified_by := old.verified_by;
    new.dismissed_at := old.dismissed_at;
    new.dismissed_by := old.dismissed_by;
  end if;

  -- La finestra la apre il worker, non il client: è ciò che impedisce di far
  -- emettere l'evento di automazione dall'esterno.
  if coalesce(current_setting('ai_swisse.contract_window', true), '') <> '1' then
    new.window_opened_at := old.window_opened_at;
  end if;

  return new;
end $$;

drop trigger if exists trg_contract_milestones_guard on public.contract_milestones;
create trigger trg_contract_milestones_guard
  before insert or update on public.contract_milestones
  for each row execute function public.contract_milestones_guard();


-- ---------------------------------------------------------------------------
-- 21. La derivazione delle date da una versione dei termini
--
-- §41/§42/§43 — ogni data prodotta qui nasce `candidate` e dichiara da dove
-- viene. Una data LETTA nel contratto è `explicit`; una data CALCOLATA è
-- `derived` e porta con sé il nome del calcolo, la sua versione e gli
-- ingredienti: senza quelli, nessuno potrebbe rispondere a «perché proprio il
-- 30 settembre?».
--
-- ⚠️ SI RIGENERANO SOLO LE CANDIDATE DI QUESTA VERSIONE. Le date che qualcuno ha
-- verificato o scartato sono giudizi umani e non si toccano; quelle manuali non
-- discendono da termini e non c'entrano.
-- ---------------------------------------------------------------------------
create or replace function public.contract_derive_milestones(p_version_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v      record;
  v_ref  date;
  v_notice date;
  v_kind public.contract_milestone_kind;
  v_count integer := 0;
begin
  select * into v from public.contract_term_versions where id = p_version_id;
  if v.id is null then return 0; end if;

  delete from public.contract_milestones
   where term_version_id = p_version_id
     and status = 'candidate'
     and source in ('explicit', 'derived');

  -- (a) L'inizio, se il contratto lo dice.
  if v.start_date is not null then
    insert into public.contract_milestones
      (company_id, contract_id, term_version_id, kind, due_date, source, status)
    values (v.company_id, v.contract_id, p_version_id, 'contract_start', v.start_date,
            'explicit', 'candidate');
    v_count := v_count + 1;
  end if;

  -- (b) La fine — oppure il RINNOVO, che è un'altra cosa.
  --     ⚠️ Con rinnovo automatico dichiarato, quel giorno il contratto non
  --     finisce: si rinnova. Chiamare «scadenza» la data in cui un impegno si
  --     prolunga di dodici mesi è il modo più diretto per far perdere un
  --     termine di disdetta.
  if v.end_date is not null and v.end_date_kind = 'explicit' then
    v_kind := case when v.auto_renewal = 'yes' then 'renewal_date' else 'contract_end' end;
    insert into public.contract_milestones
      (company_id, contract_id, term_version_id, kind, due_date, source, status)
    values (v.company_id, v.contract_id, p_version_id, v_kind, v.end_date,
            'explicit', 'candidate');
    v_count := v_count + 1;
  end if;

  -- (c) Il termine ultimo di disdetta, SE derivabile (§39/§45/§46).
  --     La data di riferimento è la fine esplicita: è anche la data in cui un
  --     rinnovo tacito scatta, e per questo serve a entrambi gli ancoraggi
  --     calcolabili.
  if v.end_date_kind = 'explicit' then v_ref := v.end_date; else v_ref := null; end if;
  v_notice := public.contract_notice_deadline(
    v.notice_period_value, v.notice_period_unit, v.notice_anchor, v_ref);

  if v_notice is not null then
    insert into public.contract_milestones
      (company_id, contract_id, term_version_id, kind, due_date, source, status,
       calculation, calculation_version, calculation_inputs)
    values (v.company_id, v.contract_id, p_version_id, 'notice_deadline', v_notice,
            'derived', 'candidate',
            'notice_before_reference', public.contract_calculation_version(),
            jsonb_build_object(
              'noticeValue', v.notice_period_value,
              'noticeUnit',  v.notice_period_unit,
              'anchor',      v.notice_anchor,
              'referenceDate', v_ref,
              'referenceKind', case when v.auto_renewal = 'yes' then 'renewal_date'
                                    else 'contract_end' end));
    v_count := v_count + 1;
  end if;

  return v_count;
end $$;

revoke all on function public.contract_derive_milestones(uuid) from public, anon, authenticated;


-- ---------------------------------------------------------------------------
-- 22. Il ricalcolo delle bandiere di qualità
--
-- §140/§141 — che cosa una persona deve guardare, e perché. Le bandiere sono
-- una PROIEZIONE: si ricalcolano per intero dalle estrazioni correnti e dai
-- termini in preparazione, e il guardiano del contratto le protegge da qualunque
-- altra scrittura.
-- ---------------------------------------------------------------------------
create or replace function public.contract_refresh_flags(p_contract_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_contract record;
  v_terms    record;
  v_flags    public.contract_quality_flag[] := '{}';
  v_from_ex  public.contract_quality_flag[];
  v_currencies integer;
  v_conflicts integer;
begin
  select * into v_contract from public.contracts where id = p_contract_id;
  if v_contract.id is null then return; end if;

  -- I termini che contano sono quelli in vigore; se nessuno ha ancora
  -- verificato, la bozza — dichiarata come tale dall'interfaccia.
  select * into v_terms from public.contract_term_versions
   where contract_id = p_contract_id
     and id = coalesce(v_contract.current_term_version_id,
                       (select id from public.contract_term_versions
                         where contract_id = p_contract_id and status = 'draft' limit 1));

  -- (a) Le bandiere che le letture hanno alzato: descrivono COME è andata, e
  --     nessuna correzione umana le rende false.
  select coalesce(array_agg(distinct fl.flag), '{}')
    into v_from_ex
    from public.contract_extractions e
    join public.contract_documents cd
      on cd.contract_id = e.contract_id and cd.current_extraction_id = e.id
   cross join lateral unnest(e.quality_flags) as fl(flag)
   where e.contract_id = p_contract_id and e.status = 'completed'
     and fl.flag in ('partially_analysed', 'low_extraction_confidence',
                     'out_of_scope_contract_kind', 'missing_referenced_annex',
                     'ambiguous_start_date', 'ambiguous_end_date');
  v_flags := v_from_ex;

  -- (b) Le bandiere che dipendono dai termini EFFETTIVI e che quindi devono
  --     spegnersi quando una persona corregge il dato.
  if v_terms.id is not null then
    if v_terms.counterparty_name is null and v_contract.counterparty_name is null then
      v_flags := v_flags || 'missing_counterparty'::public.contract_quality_flag;
    end if;

    if v_terms.auto_renewal = 'unclear' then
      v_flags := v_flags || 'renewal_unclear'::public.contract_quality_flag;
    end if;

    -- §38 — c'è un preavviso, ma non si sa a che cosa si riferisca.
    if v_terms.notice_period_value is not null
       and (v_terms.notice_anchor is null or v_terms.notice_anchor = 'unclear') then
      v_flags := v_flags || 'notice_anchor_unclear'::public.contract_quality_flag;
    end if;

    -- §39 — il preavviso c'è, l'ancoraggio anche, e ciò nonostante una data non
    -- si può derivare. È il caso di «per fine mese» e di una scadenza che non
    -- conosciamo: va DETTO, perché il posto vuoto accanto a «Preavviso: 3 mesi»
    -- verrebbe letto come «nessuna scadenza».
    if v_terms.notice_period_value is not null
       and public.contract_notice_deadline(
             v_terms.notice_period_value, v_terms.notice_period_unit, v_terms.notice_anchor,
             case when v_terms.end_date_kind = 'explicit' then v_terms.end_date end) is null then
      v_flags := v_flags || 'notice_not_derivable'::public.contract_quality_flag;
    end if;

    if v_terms.cost_amount is not null and v_terms.cost_frequency = 'unknown' then
      v_flags := v_flags || 'cost_unclear'::public.contract_quality_flag;
    end if;
  end if;

  -- (c) §26 — una modifica in attesa di una persona.
  if v_contract.review_status = 'review_required_again' then
    v_flags := v_flags || 'amendment_requires_review'::public.contract_quality_flag;
  end if;

  -- (d) §55 — valute diverse fra i documenti dello stesso contratto. Non si
  --     sommano e non si convertono: si dichiara che ce ne sono più di una.
  select count(distinct upper(e.cost_currency)) into v_currencies
    from public.contract_extractions e
    join public.contract_documents cd
      on cd.contract_id = e.contract_id and cd.current_extraction_id = e.id
   where e.contract_id = p_contract_id and e.cost_currency is not null;
  if coalesce(v_currencies, 0) > 1 then
    v_flags := v_flags || 'multiple_currencies'::public.contract_quality_flag;
  end if;

  -- (e) Due documenti che dicono cose diverse sullo stesso termine, senza che
  --     nessuno dei due sia una modifica dichiarata. Un amendment che cambia il
  --     preavviso NON è un conflitto: è il suo mestiere.
  select count(*) into v_conflicts
    from (
      select count(distinct e.notice_period_value) filter (where e.notice_period_value is not null) as n_notice,
             count(distinct e.end_date) filter (where e.end_date is not null) as n_end
        from public.contract_extractions e
        join public.contract_documents cd
          on cd.contract_id = e.contract_id and cd.current_extraction_id = e.id
       where e.contract_id = p_contract_id and e.status = 'completed'
         and cd.relation in ('main_agreement', 'annex')
    ) t
   where t.n_notice > 1 or t.n_end > 1;
  if coalesce(v_conflicts, 0) > 0 then
    v_flags := v_flags || 'conflicting_terms'::public.contract_quality_flag;
  end if;

  perform set_config('ai_swisse.contract_refresh', '1', true);
  update public.contracts
     set quality_flags = (select array(select distinct f from unnest(v_flags) f order by f))
   where id = p_contract_id;
  perform set_config('ai_swisse.contract_refresh', '0', true);
end $$;

revoke all on function public.contract_refresh_flags(uuid) from public, anon, authenticated;


-- ---------------------------------------------------------------------------
-- 23. IL RICALCOLO DELLA BOZZA DEI TERMINI
--
-- ⚠️⚠️ LA FUNZIONE PIÙ IMPORTANTE DEL FILE. Compone ciò che il prodotto PROPONE
-- come termini correnti, e l'ordine in cui compone è tutto:
--
--   1. si parte dalla VERSIONE VERIFICATA in vigore, se esiste. È la verità
--      corrente dell'azienda, corretta a mano dove serviva, e nessuna rilettura
--      della macchina deve poterla disfare.
--   2. si sovrascrive con le estrazioni dei documenti che quella versione NON
--      aveva ancora considerato, in ordine di autorità: altro < accordo
--      principale < allegato < rinnovo < modifica. Una modifica successiva pesa
--      più dell'accordo, ed è esattamente il caso «preavviso 3 mesi → 6 mesi».
--   3. si sovrascrive con le CORREZIONI UMANE di questa bozza, in ordine
--      cronologico: l'ultima di ogni campo vince (§22).
--
-- ⚠️ SOLO I VALORI NON NULLI SOVRASCRIVONO. Un amendment che parla soltanto del
-- preavviso non deve cancellare la controparte e il costo: il silenzio di un
-- documento non è una dichiarazione di assenza.
--
-- ⚠️ QUESTA FUNZIONE NON CAMBIA NIENTE DI CIÒ CHE È IN VIGORE (§28).
-- Scrive una BOZZA. I termini del contratto restano quelli verificati finché una
-- persona non verifica anche questa. È la riga che rende vera la frase «un
-- amendment non modifica silenziosamente i termini».
-- ---------------------------------------------------------------------------
create or replace function public.contract_refresh_draft(p_contract_id uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_contract record;
  v_base     record;
  v_draft_id uuid;
  v_ex       record;
  v_corr     record;
  v_text     text;
  v_sources  uuid[] := '{}';
  -- I termini in composizione.
  t_counterparty text; t_company_party text;
  t_start date; t_end date; t_end_kind public.contract_end_kind := 'unknown';
  t_min_v integer; t_min_u public.contract_period_unit;
  t_renewal public.contract_auto_renewal := 'unclear';
  t_renewal_v integer; t_renewal_u public.contract_period_unit;
  t_notice_v integer; t_notice_u public.contract_period_unit;
  t_anchor public.contract_notice_anchor; t_anchor_text text;
  t_term_method public.contract_termination_method; t_term_address text;
  t_cost numeric; t_currency text; t_frequency public.contract_cost_frequency := 'unknown';
  t_vat boolean; t_price_adj boolean := false;
  t_effective date;
begin
  select * into v_contract from public.contracts where id = p_contract_id;
  if v_contract.id is null then return null; end if;

  -- ---- 1. La base: la versione verificata in vigore -----------------------
  -- ⚠️ IL `select into` SI ESEGUE SEMPRE, anche quando non c'è nulla da
  -- cercare. In plpgsql un `record` a cui non è mai stata assegnata una riga NON
  -- è un record vuoto: leggerne un campo solleva «record is not assigned yet».
  -- Scritto dentro un `if`, questo blocco avrebbe fatto fallire il ricalcolo di
  -- ogni contratto non ancora verificato — cioè di tutti, al primo giro.
  select * into v_base from public.contract_term_versions
   where contract_id = p_contract_id
     and v_contract.current_term_version_id is not null
     and id = v_contract.current_term_version_id;

  if v_base.id is not null then
    t_counterparty := v_base.counterparty_name;  t_company_party := v_base.company_party;
    t_start := v_base.start_date;                t_end := v_base.end_date;
    t_end_kind := v_base.end_date_kind;
    t_min_v := v_base.minimum_term_value;        t_min_u := v_base.minimum_term_unit;
    t_renewal := v_base.auto_renewal;
    t_renewal_v := v_base.renewal_period_value;  t_renewal_u := v_base.renewal_period_unit;
    t_notice_v := v_base.notice_period_value;    t_notice_u := v_base.notice_period_unit;
    t_anchor := v_base.notice_anchor;            t_anchor_text := v_base.notice_anchor_text;
    t_term_method := v_base.termination_method;  t_term_address := v_base.termination_address;
    t_cost := v_base.cost_amount;                t_currency := v_base.cost_currency;
    t_frequency := v_base.cost_frequency;        t_vat := v_base.cost_vat_included;
    t_price_adj := v_base.price_adjustment;
    v_sources := coalesce(v_base.source_extraction_ids, '{}');
  end if;

  -- ---- 2. Le estrazioni non ancora incorporate ---------------------------
  for v_ex in
    select e.*, cd.relation
      from public.contract_extractions e
      join public.contract_documents cd
        on cd.contract_id = e.contract_id and cd.current_extraction_id = e.id
     where e.contract_id = p_contract_id
       and e.status = 'completed'
       and not (e.id = any(v_sources))
     order by (case cd.relation
                 when 'other' then 0 when 'termination_notice' then 0
                 when 'main_agreement' then 1 when 'annex' then 2
                 when 'renewal' then 3 when 'amendment' then 4 end) asc,
              coalesce(e.document_date, e.signature_date, e.created_at::date) asc,
              e.created_at asc
  loop
    t_counterparty := coalesce(v_ex.counterparty, t_counterparty);
    t_company_party := coalesce(v_ex.company_party, t_company_party);
    t_start := coalesce(v_ex.start_date, t_start);
    if v_ex.end_date is not null or v_ex.end_date_kind <> 'unknown' then
      t_end := coalesce(v_ex.end_date, t_end);
      t_end_kind := v_ex.end_date_kind;
    end if;
    t_min_v := coalesce(v_ex.minimum_term_value, t_min_v);
    t_min_u := coalesce(v_ex.minimum_term_unit, t_min_u);
    -- ⚠️ `unclear` non sovrascrive: un documento che non chiarisce il rinnovo non
    -- rende meno chiaro ciò che un altro aveva detto.
    if v_ex.auto_renewal <> 'unclear' then t_renewal := v_ex.auto_renewal; end if;
    t_renewal_v := coalesce(v_ex.renewal_period_value, t_renewal_v);
    t_renewal_u := coalesce(v_ex.renewal_period_unit, t_renewal_u);
    t_notice_v := coalesce(v_ex.notice_period_value, t_notice_v);
    t_notice_u := coalesce(v_ex.notice_period_unit, t_notice_u);
    t_anchor := coalesce(v_ex.notice_anchor, t_anchor);
    t_anchor_text := coalesce(v_ex.notice_anchor_text, t_anchor_text);
    t_term_method := coalesce(v_ex.termination_method, t_term_method);
    t_term_address := coalesce(v_ex.termination_address, t_term_address);
    t_cost := coalesce(v_ex.cost_amount, t_cost);
    t_currency := coalesce(upper(v_ex.cost_currency), t_currency);
    if v_ex.cost_frequency <> 'unknown' then t_frequency := v_ex.cost_frequency; end if;
    t_vat := coalesce(v_ex.cost_vat_included, t_vat);
    -- Una clausola di adeguamento vista una volta resta vista: `false` è il
    -- default della colonna, non un'affermazione del documento.
    t_price_adj := t_price_adj or v_ex.price_adjustment;
    -- Da quando valgono: la data di firma di una modifica è il segnale migliore
    -- che il documento offre, e resta comunque correggibile a mano.
    if v_ex.relation in ('amendment', 'renewal') then
      t_effective := coalesce(v_ex.start_date, v_ex.signature_date, v_ex.document_date, t_effective);
    end if;
    v_sources := v_sources || v_ex.id;
  end loop;

  -- ---- 3. La bozza: si riusa quella aperta, o se ne apre una -------------
  select id into v_draft_id from public.contract_term_versions
   where contract_id = p_contract_id and status = 'draft';

  if v_draft_id is null then
    insert into public.contract_term_versions (
      company_id, contract_id, version, status, based_on_version_id
    ) values (
      v_contract.company_id, p_contract_id,
      coalesce((select max(version) from public.contract_term_versions
                 where contract_id = p_contract_id), 0) + 1,
      'draft', v_base.id
    )
    returning id into v_draft_id;
  end if;

  -- ---- 4. Le correzioni umane vincono su tutto ---------------------------
  for v_corr in
    select field, corrected_value from public.contract_corrections
     where term_version_id = v_draft_id
     order by corrected_at asc, id asc
  loop
    v_text := v_corr.corrected_value #>> '{}';
    -- Una correzione a `null` è una cancellazione voluta: «questo campo il
    -- contratto non lo dice», ed è un'informazione, non un valore mancante.
    if v_corr.field = 'counterparty_name'    then t_counterparty := v_text;
    elsif v_corr.field = 'company_party'     then t_company_party := v_text;
    elsif v_corr.field = 'start_date'        then t_start := public.try_date(v_text);
    elsif v_corr.field = 'end_date'          then t_end := public.try_date(v_text);
    elsif v_corr.field = 'end_date_kind'     then t_end_kind := coalesce(lower(v_text)::public.contract_end_kind, t_end_kind);
    elsif v_corr.field = 'minimum_term_value' then t_min_v := public.try_numeric(v_text)::integer;
    elsif v_corr.field = 'minimum_term_unit' then t_min_u := lower(v_text)::public.contract_period_unit;
    elsif v_corr.field = 'auto_renewal'      then t_renewal := coalesce(lower(v_text)::public.contract_auto_renewal, t_renewal);
    elsif v_corr.field = 'renewal_period_value' then t_renewal_v := public.try_numeric(v_text)::integer;
    elsif v_corr.field = 'renewal_period_unit'  then t_renewal_u := lower(v_text)::public.contract_period_unit;
    elsif v_corr.field = 'notice_period_value'  then t_notice_v := public.try_numeric(v_text)::integer;
    elsif v_corr.field = 'notice_period_unit'   then t_notice_u := lower(v_text)::public.contract_period_unit;
    elsif v_corr.field = 'notice_anchor'     then t_anchor := lower(v_text)::public.contract_notice_anchor;
    elsif v_corr.field = 'notice_anchor_text' then t_anchor_text := v_text;
    elsif v_corr.field = 'termination_method' then t_term_method := lower(v_text)::public.contract_termination_method;
    elsif v_corr.field = 'termination_address' then t_term_address := v_text;
    elsif v_corr.field = 'cost_amount'       then t_cost := public.try_numeric(v_text);
    elsif v_corr.field = 'cost_currency'     then t_currency := upper(v_text);
    elsif v_corr.field = 'cost_frequency'    then t_frequency := coalesce(lower(v_text)::public.contract_cost_frequency, t_frequency);
    elsif v_corr.field = 'cost_vat_included' then t_vat := (lower(v_text) = 'true');
    elsif v_corr.field = 'price_adjustment'  then t_price_adj := (lower(v_text) = 'true');
    elsif v_corr.field = 'effective_from'    then t_effective := public.try_date(v_text);
    end if;
  end loop;

  -- ---- 5. Si scrive la bozza --------------------------------------------
  update public.contract_term_versions set
    counterparty_name = t_counterparty,
    company_party     = t_company_party,
    start_date        = t_start,
    end_date          = t_end,
    end_date_kind     = t_end_kind,
    minimum_term_value = t_min_v,
    minimum_term_unit  = t_min_u,
    auto_renewal      = t_renewal,
    renewal_period_value = t_renewal_v,
    renewal_period_unit  = t_renewal_u,
    notice_period_value  = t_notice_v,
    notice_period_unit   = t_notice_u,
    notice_anchor        = t_anchor,
    notice_anchor_text   = t_anchor_text,
    termination_method   = t_term_method,
    termination_address  = t_term_address,
    cost_amount       = t_cost,
    cost_currency     = t_currency,
    cost_frequency    = t_frequency,
    cost_vat_included = t_vat,
    price_adjustment  = t_price_adj,
    effective_from    = t_effective,
    source_extraction_ids = v_sources,
    based_on_version_id   = coalesce(based_on_version_id, v_base.id)
  where id = v_draft_id;

  -- Le date che ne discendono, e le bandiere che ne derivano.
  perform public.contract_derive_milestones(v_draft_id);
  perform public.contract_refresh_flags(p_contract_id);

  return v_draft_id;
end $$;

revoke all on function public.contract_refresh_draft(uuid) from public, anon, authenticated;


-- ---------------------------------------------------------------------------
-- 24. LA VERIFICA DEI TERMINI — l'unico percorso che rende un termine «in vigore»
--
-- §82/§83 — «Segna i dati come verificati», mai «approva legalmente». Qui non si
-- approva niente: si dichiara di aver guardato ciò che il sistema ha letto.
--
-- ⚠️ È UNA FUNZIONE E NON UN `update` DAL CLIENT perché cinque cose devono
-- accadere insieme o non accadere affatto: la bozza diventa verificata, la
-- versione precedente passa a superata, il contratto punta alla nuova, le date
-- della vecchia versione smettono di valere e lo storico registra il gesto.
-- Lasciarle a cinque scritture separate significherebbe che una schermata
-- interrotta a metà lascia un contratto «verificato» senza termini verificati.
--
-- ⚠️ `security definer` con controllo di appartenenza scritto DENTRO: è la
-- lezione della 0019, dove una funzione `security invoker` non poteva scrivere
-- perché al ruolo `authenticated` mancava il permesso che mancava anche a lei.
-- ---------------------------------------------------------------------------
create or replace function public.contract_verify_terms(p_version_id uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_version  record;
  v_contract record;
  v_previous uuid;
begin
  select * into v_version from public.contract_term_versions where id = p_version_id;
  if v_version.id is null then
    raise exception 'contract_term_version_not_found' using errcode = 'P0002';
  end if;

  -- L'appartenenza è l'UNICA difesa di una funzione che scavalca la RLS.
  if not public.is_company_member(v_version.company_id) then
    raise exception 'contract_forbidden' using errcode = '42501';
  end if;

  if v_version.status <> 'draft' then
    raise exception 'contract_term_version_not_draft'
      using errcode = '23514',
            hint = 'Solo la versione in preparazione può essere verificata.';
  end if;

  select * into v_contract from public.contracts where id = v_version.contract_id;
  v_previous := v_contract.current_term_version_id;

  update public.contract_term_versions
     set status = 'verified', verified_at = now(), verified_by = auth.uid()
   where id = p_version_id;

  if v_previous is not null and v_previous <> p_version_id then
    update public.contract_term_versions
       set status = 'superseded'
     where id = v_previous;
    -- Le date della versione superata smettono di essere in gioco. ⚠️ NON si
    -- cancellano: una data che ha generato un'attività deve restare
    -- ricostruibile, e «superata» è un fatto, non un giudizio.
    update public.contract_milestones
       set status = 'superseded'
     where term_version_id = v_previous
       and status in ('candidate', 'verified');
  end if;

  perform set_config('ai_swisse.contract_verify', '1', true);
  update public.contracts
     set current_term_version_id = p_version_id,
         review_status = 'verified',
         verified_at = now(),
         verified_by = auth.uid()
   where id = v_version.contract_id;
  perform set_config('ai_swisse.contract_verify', '0', true);

  insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
  values (v_version.company_id, v_version.contract_id, auth.uid(), 'term_version_verified',
          jsonb_build_object('versionId', p_version_id, 'version', v_version.version,
                             'previousVersionId', v_previous));

  perform public.contract_refresh_flags(v_version.contract_id);
  return p_version_id;
end $$;


/*
 * Riaprire i termini per correggerli.
 *
 * ⚠️ SERVE PERCHÉ UNA VERSIONE VERIFICATA È IMMUTABILE. Dopo la verifica non
 * esiste più alcuna bozza (l'indice unico parziale si libera), e senza questa
 * funzione un contratto verificato sarebbe un contratto che nessuno può più
 * correggere: ci si accorgerebbe di un preavviso sbagliato e non ci sarebbe
 * dove scriverlo. La bozza nuova parte dai termini in vigore e non li tocca —
 * lo stato resta `verified` finché una persona non verifica anche questa.
 */
create or replace function public.contract_open_draft(p_contract_id uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
begin
  select company_id into v_company from public.contracts where id = p_contract_id;
  if v_company is null then
    raise exception 'contract_not_found' using errcode = 'P0002';
  end if;
  if not public.is_company_member(v_company) then
    raise exception 'contract_forbidden' using errcode = '42501';
  end if;
  return public.contract_refresh_draft(p_contract_id);
end $$;


-- ---------------------------------------------------------------------------
-- 25. Quando arriva una lettura nuova
--
-- ⚠️ §26/§28 — UN AMENDMENT NON CAMBIA I TERMINI: APRE UNA REVISIONE.
-- Se il contratto era verificato e arriva la lettura di una modifica, lo stato
-- torna `review_required_again` e la bozza mostra che cosa cambierebbe. I
-- termini in vigore restano quelli di prima finché una persona non decide.
-- ---------------------------------------------------------------------------
create or replace function public.contract_after_extraction()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_relation public.contract_document_relation;
begin
  select cd.relation into v_relation
    from public.contract_documents cd
   where cd.contract_id = new.contract_id and cd.document_id = new.document_id;

  if new.status = 'completed' then
    update public.contract_documents
       set current_extraction_id = new.id,
           processing_status = 'completed',
           error_code = null
     where contract_id = new.contract_id and document_id = new.document_id;

    -- ⚠️ ANCHE IL FALLIMENTO LO SCRIVE IL TRIGGER, non il worker (lezione della
    -- 0021): due posti in cui ricordarsene sono uno di troppo, e il giorno in
    -- cui uno dei due dimentica, il documento resta «in lavorazione» per sempre.
  else
    update public.contract_documents
       set processing_status = 'failed', error_code = new.error_code
     where contract_id = new.contract_id and document_id = new.document_id;
  end if;

  insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
  values (new.company_id, new.contract_id, null,
          case when new.status = 'completed' then 'extraction_completed'
               else 'extraction_failed' end,
          jsonb_build_object('documentId', new.document_id,
                             'version', new.extraction_version,
                             'relation', v_relation));

  if new.status = 'completed' then
    perform public.contract_refresh_draft(new.contract_id);

    -- La revisione si riapre solo se c'era qualcosa da riaprire: su un contratto
    -- mai verificato lo stato è già `needs_review` e riscriverlo direbbe che è
    -- successo qualcosa che non è successo.
    if v_relation in ('amendment', 'renewal') then
      perform set_config('ai_swisse.contract_review', '1', true);
      update public.contracts
         set review_status = 'review_required_again'
       where id = new.contract_id and review_status = 'verified';
      perform set_config('ai_swisse.contract_review', '0', true);

      insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
      values (new.company_id, new.contract_id, null, 'amendment_added',
              jsonb_build_object('documentId', new.document_id, 'relation', v_relation));
    end if;

    perform public.contract_refresh_flags(new.contract_id);
  end if;

  return new;
end $$;

drop trigger if exists trg_contract_after_extraction on public.contract_extractions;
create trigger trg_contract_after_extraction
  after insert on public.contract_extractions
  for each row execute function public.contract_after_extraction();


-- ---------------------------------------------------------------------------
-- 26. La bozza esiste da subito
--
-- §132 — un contratto si può creare in un istante e l'estrazione arriva dopo.
-- La bozza nasce con il contratto, vuota: è il posto in cui una persona può
-- scrivere i termini a mano quando il PDF non c'è ancora, ed è lo stesso posto
-- in cui la lettura li scriverà. Due percorsi diversi per lo stesso dato
-- avrebbero prodotto due schermate che si contraddicono.
-- ---------------------------------------------------------------------------
create or replace function public.contract_after_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
  values (new.company_id, new.id, new.created_by, 'created',
          jsonb_build_object('type', new.contract_type, 'origin', new.origin));
  perform public.contract_refresh_draft(new.id);
  return new;
end $$;

drop trigger if exists trg_contract_after_insert on public.contracts;
create trigger trg_contract_after_insert
  after insert on public.contracts
  for each row execute function public.contract_after_insert();


-- ---------------------------------------------------------------------------
-- 27. Lo storico degli stati
-- ---------------------------------------------------------------------------
create or replace function public.contracts_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.review_status is distinct from old.review_status then
    if new.review_status = 'review_required_again' then
      insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
      values (new.company_id, new.id, auth.uid(), 'review_reopened', '{}'::jsonb);
    elsif new.review_status = 'verified' then
      insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
      values (new.company_id, new.id, auth.uid(), 'verified', '{}'::jsonb);
    end if;
  end if;

  if new.owner_user_id is distinct from old.owner_user_id then
    -- ⚠️ Nel dettaglio va l'IDENTIFICATIVO, non il nome: lo storico lo legge
    -- ogni membro e i nomi si risolvono al render dalla rubrica (§110).
    insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'owner_changed',
            jsonb_build_object('ownerUserId', new.owner_user_id));
  end if;

  if new.lifecycle_status is distinct from old.lifecycle_status then
    insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'lifecycle_changed',
            jsonb_build_object('status', new.lifecycle_status));
  end if;

  if new.archived_at is not null and old.archived_at is null then
    insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'archived', '{}'::jsonb);
  elsif new.archived_at is null and old.archived_at is not null then
    insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
    values (new.company_id, new.id, auth.uid(), 'restored', '{}'::jsonb);
  end if;

  return new;
end $$;

drop trigger if exists trg_contracts_events on public.contracts;
create trigger trg_contracts_events
  after update on public.contracts
  for each row execute function public.contracts_events();

create or replace function public.contract_documents_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
    values (new.company_id, new.contract_id, new.added_by, 'document_added',
            jsonb_build_object('documentId', new.document_id, 'relation', new.relation,
                               'suggested', new.suggested));
    return new;
  end if;

  insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
  values (old.company_id, old.contract_id, auth.uid(), 'document_removed',
          jsonb_build_object('documentId', old.document_id, 'relation', old.relation));
  return old;
end $$;

drop trigger if exists trg_contract_documents_events on public.contract_documents;
create trigger trg_contract_documents_events
  after insert or delete on public.contract_documents
  for each row execute function public.contract_documents_events();

-- Togliere un documento cambia i termini che se ne possono comporre: la bozza va
-- rifatta, altrimenti resterebbe a raccontare un documento che non c'è più.
create or replace function public.contract_documents_after_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Solo se il contratto esiste ancora: durante la cascata di una cancellazione
  -- del contratto non c'è più niente da ricalcolare, e provarci solleverebbe.
  if exists (select 1 from public.contracts where id = old.contract_id) then
    perform public.contract_refresh_draft(old.contract_id);
  end if;
  return old;
end $$;

drop trigger if exists trg_contract_documents_after_delete on public.contract_documents;
create trigger trg_contract_documents_after_delete
  after delete on public.contract_documents
  for each row execute function public.contract_documents_after_delete();

-- Una correzione ridisegna la bozza e lascia traccia.
create or replace function public.contract_after_correction()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.contract_refresh_draft(new.contract_id);
  insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
  values (new.company_id, new.contract_id, new.corrected_by, 'corrected',
          jsonb_build_object('field', new.field));
  return new;
end $$;

drop trigger if exists trg_contract_after_correction on public.contract_corrections;
create trigger trg_contract_after_correction
  after insert on public.contract_corrections
  for each row execute function public.contract_after_correction();

create or replace function public.contract_milestones_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if new.source = 'manual' then
      insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
      values (new.company_id, new.contract_id, new.created_by, 'milestone_added',
              jsonb_build_object('milestoneId', new.id, 'kind', new.kind));
    end if;
    return new;
  end if;

  if new.status is distinct from old.status then
    if new.status = 'verified' then
      insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
      values (new.company_id, new.contract_id, new.verified_by, 'milestone_verified',
              jsonb_build_object('milestoneId', new.id, 'kind', new.kind,
                                 'source', new.source));
    elsif new.status = 'dismissed' then
      insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
      values (new.company_id, new.contract_id, new.dismissed_by, 'milestone_dismissed',
              jsonb_build_object('milestoneId', new.id, 'kind', new.kind));
    end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_contract_milestones_events on public.contract_milestones;
create trigger trg_contract_milestones_events
  after insert or update on public.contract_milestones
  for each row execute function public.contract_milestones_events();


-- ---------------------------------------------------------------------------
-- 28. Gli eventi per il motore delle automazioni
--
-- ⚠️ I QUATTRO VALORI NUOVI DELL'ENUM COMPAIONO SOLO QUI DENTRO, e il corpo di
-- una funzione non viene eseguito quando la funzione viene creata: applicare
-- questo file non li valuta mai. Vedi il punto 2.
--
-- ⚠️ NESSUN EVENTO NASCE DA UNA PROPOSTA. `contract_milestone_verified` si emette
-- quando una PERSONA ha confermato una data (§87): una candidata che facesse
-- scattare una regola trasformerebbe un calcolo in un'attività, ed è
-- esattamente ciò che questo modulo non deve fare.
-- ---------------------------------------------------------------------------
create or replace function public.contract_emit_automation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payload jsonb;
begin
  v_payload := jsonb_build_object(
    'contractId', new.id, 'type', new.contract_type,
    'reviewStatus', new.review_status, 'ownerUserId', new.owner_user_id);

  if new.review_status = 'verified' and old.review_status is distinct from 'verified' then
    perform public.automation_emit(
      new.company_id, 'contract_verified', 'contract', new.id,
      v_payload, null, new.workflow_run_id);
  end if;

  if new.review_status = 'review_required_again'
     and old.review_status is distinct from 'review_required_again' then
    perform public.automation_emit(
      new.company_id, 'contract_review_required', 'contract', new.id,
      v_payload, null, new.workflow_run_id);
  end if;

  return new;
end $$;

drop trigger if exists trg_contract_emit_automation on public.contracts;
create trigger trg_contract_emit_automation
  after update on public.contracts
  for each row execute function public.contract_emit_automation();

create or replace function public.contract_milestone_emit_automation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_contract record;
begin
  if new.status <> 'verified' or old.status = 'verified' then return new; end if;

  select c.company_id, c.contract_type, c.owner_user_id, c.workflow_run_id
    into v_contract
    from public.contracts c where c.id = new.contract_id;

  perform public.automation_emit(
    v_contract.company_id, 'contract_milestone_verified', 'contract', new.contract_id,
    jsonb_build_object('contractId', new.contract_id, 'milestoneId', new.id,
                       'milestoneKind', new.kind, 'milestoneDate', new.due_date,
                       'milestoneSource', new.source,
                       'type', v_contract.contract_type,
                       'ownerUserId', v_contract.owner_user_id),
    null, v_contract.workflow_run_id);
  return new;
end $$;

drop trigger if exists trg_contract_milestone_emit on public.contract_milestones;
create trigger trg_contract_milestone_emit
  after update on public.contract_milestones
  for each row execute function public.contract_milestone_emit_automation();


-- ---------------------------------------------------------------------------
-- 29. L'apertura delle finestre di attenzione
--
-- §95 — «la finestra si apre» è un fatto che dipende dal TEMPO, non da una
-- scrittura: nessun trigger può accorgersene. Lo chiede lo scheduler già
-- esistente, esattamente come `automation_emit_overdue` della 0020 — non si
-- crea un secondo sistema di cron.
--
-- ⚠️ SI EMETTE UNA VOLTA SOLA (`window_opened_at`). Senza, ogni passaggio del
-- worker riemetterebbe l'evento e una regola creerebbe un'attività ogni cinque
-- minuti: è la stessa ragione per cui «scaduta» si emette una volta sola.
--
-- ⚠️ SOLO DATE VERIFICATE. Una candidata non apre nessuna finestra (§87).
-- ---------------------------------------------------------------------------
create or replace function public.contract_open_milestone_windows(
  p_window_days integer default 60,
  p_limit       integer default 200
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ms    record;
  v_count integer := 0;
begin
  for v_ms in
    select m.id, m.company_id, m.contract_id, m.kind, m.due_date, m.source,
           c.contract_type, c.owner_user_id, c.workflow_run_id
      from public.contract_milestones m
      join public.contracts c on c.id = m.contract_id
     where m.status = 'verified'
       and m.window_opened_at is null
       and c.archived_at is null
       and m.due_date >= current_date
       and m.due_date <= current_date + make_interval(days => greatest(p_window_days, 0))
     order by m.due_date asc
     limit greatest(p_limit, 0)
  loop
    perform set_config('ai_swisse.contract_window', '1', true);
    update public.contract_milestones set window_opened_at = now() where id = v_ms.id;
    perform set_config('ai_swisse.contract_window', '0', true);

    perform public.automation_emit(
      v_ms.company_id, 'contract_milestone_window_opened', 'contract', v_ms.contract_id,
      jsonb_build_object('contractId', v_ms.contract_id, 'milestoneId', v_ms.id,
                         'milestoneKind', v_ms.kind, 'milestoneDate', v_ms.due_date,
                         'milestoneSource', v_ms.source,
                         'type', v_ms.contract_type, 'ownerUserId', v_ms.owner_user_id,
                         'windowDays', p_window_days),
      null, v_ms.workflow_run_id);
    v_count := v_count + 1;
  end loop;

  return v_count;
end $$;

revoke all on function public.contract_open_milestone_windows(integer, integer) from public, anon, authenticated;


-- ---------------------------------------------------------------------------
-- 30. La lista: filtri, ricerca, ordinamento e paginazione nel database
--
-- Stessa forma di `list_documents` (0017) e `list_finance_items` (0021), e per
-- le stesse ragioni: una riga mette insieme il contratto, i termini in vigore,
-- la prossima data e i conteggi. Fatto dal browser sarebbe una interrogazione
-- per riga per relazione, e per sapere quali venticinque righe mostrare
-- bisognerebbe averle scaricate tutte (§70/§159).
--
-- ⚠️ `terms_are_draft` NON È UN DETTAGLIO TECNICO. Dice se ciò che la riga
-- mostra è un termine verificato o una proposta del sistema. Senza quel
-- booleano l'interfaccia mostrerebbe «Preavviso: 3 mesi» con la stessa faccia in
-- entrambi i casi, e la distinzione su cui è costruito tutto il modulo
-- sparirebbe proprio nel punto in cui una persona guarda.
--
-- `security invoker` (il default): la RLS di ogni tabella continua ad applicarsi
-- riga per riga. Il filtro esplicito su `company_id` non la sostituisce, la
-- accompagna.
-- ---------------------------------------------------------------------------
create or replace function public.list_contracts(
  p_company_id   uuid,
  -- all | needs_review | active | renewals | notices | archived
  p_view         text default 'all',
  p_query        text default null,
  p_type         public.contract_type default null,
  p_lifecycle    public.contract_lifecycle_status default null,
  p_review       public.contract_review_status default null,
  p_owner        uuid default null,
  p_auto_renewal public.contract_auto_renewal default null,
  p_without_owner boolean default false,
  -- §66 — la finestra delle viste «prossimi». Novanta giorni è il default
  -- ragionevole per un contratto: un preavviso di tre mesi va visto prima che
  -- scada, e tre mesi è la durata più diffusa.
  p_window_days  integer default 90,
  p_archived     boolean default false,
  p_sort         text default 'default',
  p_limit        integer default 25,
  p_offset       integer default 0,
  p_contract_id  uuid default null
)
returns table (
  id uuid,
  display_name text,
  contract_type public.contract_type,
  counterparty_name text,
  owner_user_id uuid,
  review_status public.contract_review_status,
  lifecycle_status public.contract_lifecycle_status,
  origin public.contract_origin,
  quality_flags public.contract_quality_flag[],
  internal_note text,
  archived_at timestamptz,
  verified_at timestamptz,
  created_at timestamptz,
  updated_at timestamptz,
  -- I termini effettivi e la loro natura
  term_version_id uuid,
  term_version integer,
  terms_are_draft boolean,
  start_date date,
  end_date date,
  end_date_kind public.contract_end_kind,
  auto_renewal public.contract_auto_renewal,
  renewal_period_value integer,
  renewal_period_unit public.contract_period_unit,
  notice_period_value integer,
  notice_period_unit public.contract_period_unit,
  notice_anchor public.contract_notice_anchor,
  notice_anchor_text text,
  termination_method public.contract_termination_method,
  cost_amount numeric,
  cost_currency text,
  cost_frequency public.contract_cost_frequency,
  price_adjustment boolean,
  -- Le prossime date, con il loro stato: una candidata non è una scadenza
  next_renewal_date date,
  next_renewal_status public.contract_milestone_status,
  next_notice_date date,
  next_notice_status public.contract_milestone_status,
  -- Una bozza in attesa quando i termini in vigore sono altri (§27)
  pending_draft_id uuid,
  document_count bigint,
  amendment_count bigint,
  open_task_count bigint,
  processing_pending_count bigint,
  processing_failed_count bigint,
  total_count bigint
)
language sql
stable
set search_path = ''
as $$
with base as (
  select c.*
    from public.contracts c
   where c.company_id = p_company_id
     and public.is_company_member(c.company_id)
     and (p_contract_id is null or c.id = p_contract_id)
     -- La vista «Archiviati» è una vista, non un filtro in più: o si guardano i
     -- contratti correnti o quelli archiviati, mai un miscuglio dei due.
     and (case when p_view = 'archived' or p_archived then c.archived_at is not null
               else c.archived_at is null end)
     and (p_type is null or c.contract_type = p_type)
     and (p_lifecycle is null or c.lifecycle_status = p_lifecycle)
     and (p_review is null or c.review_status = p_review)
     and (p_owner is null or c.owner_user_id = p_owner)
     and (not p_without_owner or c.owner_user_id is null)
     and (p_query is null or btrim(p_query) = '' or
          (coalesce(c.display_name, '') || ' ' || coalesce(c.counterparty_name, ''))
            ilike '%' || btrim(p_query) || '%'
          -- §68 — la ricerca guarda anche il titolo dei documenti collegati:
          -- chi cerca «Swisscom» può averlo letto sul PDF e non nel nome che
          -- l'azienda ha dato al contratto.
          or exists (
            select 1 from public.contract_documents cd
              join public.documents d on d.id = cd.document_id
             where cd.contract_id = c.id
               and d.title ilike '%' || btrim(p_query) || '%'))
), composed as (
  select b.*,
         t.id as t_id, t.version as t_version, t.status as t_status,
         t.start_date as t_start, t.end_date as t_end, t.end_date_kind as t_end_kind,
         t.auto_renewal as t_renewal, t.renewal_period_value as t_ren_v,
         t.renewal_period_unit as t_ren_u, t.notice_period_value as t_not_v,
         t.notice_period_unit as t_not_u, t.notice_anchor as t_anchor,
         t.notice_anchor_text as t_anchor_text, t.termination_method as t_method,
         t.cost_amount as t_cost, t.cost_currency as t_currency,
         t.cost_frequency as t_freq, t.price_adjustment as t_price_adj,
         t.counterparty_name as t_counterparty,
         ren.due_date as ren_date, ren.status as ren_status,
         nod.due_date as not_date, nod.status as not_status,
         draft.id as draft_id,
         dc.n_documents, dc.n_amendments, dc.n_pending, dc.n_failed,
         tk.n_open_tasks
    from base b
    -- I termini in vigore; se nessuno ha verificato, la bozza — e la riga lo
    -- dichiara con `terms_are_draft`.
    left join lateral (
      select v.* from public.contract_term_versions v
       where v.contract_id = b.id
         and v.id = coalesce(b.current_term_version_id,
                             (select v2.id from public.contract_term_versions v2
                               where v2.contract_id = b.id and v2.status = 'draft' limit 1))
       limit 1
    ) t on true
    -- La bozza in attesa, SOLO se non è già ciò che stiamo mostrando: è il
    -- segnale «c'è una modifica da guardare» (§27).
    left join lateral (
      select v.id from public.contract_term_versions v
       where v.contract_id = b.id and v.status = 'draft'
         and b.current_term_version_id is not null
       limit 1
    ) draft on true
    left join lateral (
      select m.due_date, m.status from public.contract_milestones m
       where m.contract_id = b.id
         and m.kind in ('renewal_date', 'contract_end')
         and m.status in ('candidate', 'verified')
         and m.due_date >= current_date
       order by m.due_date asc, (m.status = 'verified') desc
       limit 1
    ) ren on true
    left join lateral (
      select m.due_date, m.status from public.contract_milestones m
       where m.contract_id = b.id
         and m.kind = 'notice_deadline'
         and m.status in ('candidate', 'verified')
         and m.due_date >= current_date
       order by m.due_date asc, (m.status = 'verified') desc
       limit 1
    ) nod on true
    left join lateral (
      select count(*) as n_documents,
             count(*) filter (where cd.relation in ('amendment', 'renewal')) as n_amendments,
             count(*) filter (where cd.processing_status in ('pending', 'processing')) as n_pending,
             count(*) filter (where cd.processing_status = 'failed') as n_failed
        from public.contract_documents cd where cd.contract_id = b.id
    ) dc on true
    left join lateral (
      select count(*) as n_open_tasks from public.tasks tk2
       where tk2.contract_id = b.id and tk2.status <> 'completed' and tk2.archived_at is null
    ) tk on true
), filtered as (
  select * from composed c
   where case p_view
     when 'needs_review' then c.review_status in ('needs_review', 'review_required_again')
     when 'active'       then c.lifecycle_status = 'active'
     when 'renewals'     then c.ren_date is not null
                              and c.ren_date <= current_date + make_interval(days => greatest(p_window_days, 0))
     when 'notices'      then c.not_date is not null
                              and c.not_date <= current_date + make_interval(days => greatest(p_window_days, 0))
     else true
   end
     and (p_auto_renewal is null or c.t_renewal = p_auto_renewal)
)
select
  f.id, f.display_name, f.contract_type,
  -- La controparte dei termini vince su quella scritta sul contratto: la prima
  -- viene dal documento o da una correzione, la seconda è un'etichetta.
  coalesce(f.t_counterparty, f.counterparty_name),
  f.owner_user_id, f.review_status, f.lifecycle_status, f.origin,
  f.quality_flags, f.internal_note, f.archived_at, f.verified_at,
  f.created_at, f.updated_at,
  f.t_id, f.t_version, (f.t_status = 'draft'),
  f.t_start, f.t_end, f.t_end_kind, f.t_renewal, f.t_ren_v, f.t_ren_u,
  f.t_not_v, f.t_not_u, f.t_anchor, f.t_anchor_text, f.t_method,
  f.t_cost, f.t_currency, f.t_freq, f.t_price_adj,
  f.ren_date, f.ren_status, f.not_date, f.not_status,
  f.draft_id,
  coalesce(f.n_documents, 0), coalesce(f.n_amendments, 0), coalesce(f.n_open_tasks, 0),
  coalesce(f.n_pending, 0), coalesce(f.n_failed, 0),
  count(*) over () as total_count
from filtered f
-- ORDINAMENTO PREDEFINITO (§120): prima ciò che richiede una DECISIONE — un
-- preavviso che si avvicina, un rinnovo che scatta — poi ciò che nessuno ha
-- ancora verificato, poi il resto. `id` chiude sempre la catena: senza, due
-- contratti con la stessa data si scambierebbero di posto fra una pagina e
-- l'altra e uno dei due non comparirebbe mai.
order by
  case when p_sort = 'default' then
    case when f.not_date is not null and f.not_date <= current_date + interval '30 days' then 0
         when f.ren_date is not null and f.ren_date <= current_date + interval '30 days' then 1
         when f.review_status <> 'verified' then 2
         else 3 end
  end asc nulls last,
  case when p_sort = 'default' then coalesce(f.not_date, f.ren_date) end asc nulls last,
  case when p_sort = 'renewal' then f.ren_date end asc nulls last,
  case when p_sort = 'notice' then f.not_date end asc nulls last,
  case when p_sort = 'name' then lower(f.display_name) end asc,
  case when p_sort in ('recent', 'default') then f.updated_at end desc,
  f.id desc
limit greatest(coalesce(p_limit, 25), 1)
offset greatest(coalesce(p_offset, 0), 0)
$$;


-- ---------------------------------------------------------------------------
-- 31. I numeri del cruscotto
--
-- §67 — POCHI, e ognuno risponde a una domanda che porta a un'azione. Non
-- quindici numeri: quattro, e sono quelli che dicono che cosa richiede una
-- decisione (§120).
-- ---------------------------------------------------------------------------
create or replace function public.contract_summary(
  p_company_id  uuid,
  p_window_days integer default 90
)
returns table (
  needs_review    bigint,
  renewals_soon   bigint,
  notices_soon    bigint,
  without_owner   bigint,
  -- Non è un KPI da mostrare: serve alla schermata per sapere se esiste una
  -- lettura in corso, e distinguere «non c'è niente» da «non è ancora pronto».
  processing      bigint
)
language sql
stable
set search_path = ''
as $$
  select
    count(*) filter (where c.review_status in ('needs_review', 'review_required_again')),
    count(*) filter (where exists (
      select 1 from public.contract_milestones m
       where m.contract_id = c.id and m.kind in ('renewal_date', 'contract_end')
         and m.status in ('candidate', 'verified')
         and m.due_date between current_date
             and current_date + make_interval(days => greatest(p_window_days, 0)))),
    count(*) filter (where exists (
      select 1 from public.contract_milestones m
       where m.contract_id = c.id and m.kind = 'notice_deadline'
         and m.status in ('candidate', 'verified')
         and m.due_date between current_date
             and current_date + make_interval(days => greatest(p_window_days, 0)))),
    count(*) filter (where c.owner_user_id is null),
    count(*) filter (where exists (
      select 1 from public.contract_documents cd
       where cd.contract_id = c.id and cd.processing_status in ('pending', 'processing')))
  from public.contracts c
 where c.company_id = p_company_id
   and public.is_company_member(c.company_id)
   and c.archived_at is null
$$;


-- ---------------------------------------------------------------------------
-- 32. I documenti che POTREBBERO appartenere a un contratto
--
-- §77 — si SUGGERISCE, non si collega. Il criterio è deliberatamente povero e
-- verificabile: un documento di categoria «contratti», non ancora collegato a
-- nessun contratto, il cui titolo o il cui mittente somigli alla controparte.
--
-- ⚠️ NON ESISTE UN COLLEGAMENTO AUTOMATICO IN CASI INCERTI, e questa funzione
-- non ne crea: restituisce righe che una persona guarda. Un allegato agganciato
-- al contratto sbagliato cambierebbe i termini di due contratti insieme.
-- ---------------------------------------------------------------------------
create or replace function public.contract_document_suggestions(
  p_contract_id uuid,
  p_limit       integer default 10
)
returns table (
  document_id uuid,
  title text,
  created_at timestamptz,
  category public.document_category,
  reason text
)
language sql
stable
set search_path = ''
as $$
  select d.id, d.title, d.created_at, d.category,
         case when c.counterparty_name is not null
                   and d.title ilike '%' || c.counterparty_name || '%'
              then 'counterparty_in_title' else 'contract_category' end
    from public.contracts c
    join public.documents d on d.company_id = c.company_id
   where c.id = p_contract_id
     and public.is_company_member(c.company_id)
     and d.category = 'contracts'
     and d.archived_at is null
     and not exists (
       select 1 from public.contract_documents cd where cd.document_id = d.id)
     and (c.counterparty_name is null
          or d.title ilike '%' || c.counterparty_name || '%'
          or d.created_at >= c.created_at - interval '30 days')
   order by (case when c.counterparty_name is not null
                       and d.title ilike '%' || c.counterparty_name || '%'
                  then 0 else 1 end),
            d.created_at desc
   limit greatest(coalesce(p_limit, 10), 1)
$$;


-- ---------------------------------------------------------------------------
-- 33. RLS e permessi
--
-- ⚠️ `revoke all` PRIMA dei grant, su ogni tabella nuova. Su Supabase una
-- tabella di `public` nasce con i permessi di TABELLA completi per
-- `authenticated` (`alter default privileges … grant all on tables`), quindi un
-- grant scritto dopo AGGIUNGE privilegi invece di restringerli: è la lezione
-- della 0014, dove i permessi di colonna dichiarati nei commenti non
-- restringevano nulla e il difetto emerse solo ESEGUENDO i test.
--
-- CHE COSA UN MEMBRO PUÒ FARE: leggere i contratti della propria azienda;
-- crearne uno; cambiarne l'organizzazione (nome, tipo, responsabile, stato
-- operativo, nota, archiviazione); collegare e scollegare documenti; aggiungere
-- correzioni; aggiungere date manuali e verificare o scartare quelle proposte.
-- Nient'altro. I verbali non si scrivono, i termini verificati non si toccano,
-- lo stato di verifica passa da `contract_verify_terms` e da nessun'altra parte.
-- ---------------------------------------------------------------------------
alter table public.contracts             enable row level security;
alter table public.contract_documents    enable row level security;
alter table public.contract_extractions  enable row level security;
alter table public.contract_term_versions enable row level security;
alter table public.contract_corrections  enable row level security;
alter table public.contract_milestones   enable row level security;
alter table public.contract_events       enable row level security;

revoke all on public.contracts             from anon, authenticated, public;
revoke all on public.contract_documents    from anon, authenticated, public;
revoke all on public.contract_extractions  from anon, authenticated, public;
revoke all on public.contract_term_versions from anon, authenticated, public;
revoke all on public.contract_corrections  from anon, authenticated, public;
revoke all on public.contract_milestones   from anon, authenticated, public;
revoke all on public.contract_events       from anon, authenticated, public;

grant select on public.contracts to authenticated;
grant insert (company_id, display_name, contract_type, counterparty_name, owner_user_id)
  on public.contracts to authenticated;
-- ⚠️ `review_status`, `verified_at/by`, `current_term_version_id`,
-- `quality_flags`, `origin` NON sono qui, di proposito. Il guardiano li
-- ripristinerebbe comunque, ma senza il permesso un tentativo FALLISCE invece di
-- essere ignorato in silenzio — e un fallimento silenzioso è ciò che questo
-- progetto non ammette.
grant update (display_name, contract_type, counterparty_name, owner_user_id,
              lifecycle_status, internal_note, archived_at)
  on public.contracts to authenticated;

grant select on public.contract_documents to authenticated;
grant insert (company_id, contract_id, document_id, relation, suggested)
  on public.contract_documents to authenticated;
-- `processing_status` è scrivibile per un motivo solo: «Riprova lettura» (§131).
-- Il guardiano impedisce di rimettere in coda ciò che è già in lavorazione.
grant update (relation, processing_status) on public.contract_documents to authenticated;
-- §75 — scollegare un documento è un gesto legittimo: il documento resta nel
-- Document Hub, cambia solo il fatto che appartenga a questo contratto.
grant delete on public.contract_documents to authenticated;

-- I verbali e i termini si leggono e basta. Le versioni le scrivono
-- `contract_refresh_draft` e `contract_verify_terms`, che sono `security
-- definer` e non hanno bisogno di alcun permesso del chiamante.
grant select on public.contract_extractions to authenticated;
grant select on public.contract_term_versions to authenticated;

grant select, insert on public.contract_corrections to authenticated;

grant select on public.contract_milestones to authenticated;
-- Una persona può aggiungere una data e decidere di una data proposta. Non può
-- dichiararne la provenienza né il calcolo: quelli li scrive il database.
grant insert (company_id, contract_id, kind, due_date, label)
  on public.contract_milestones to authenticated;
grant update (status, label) on public.contract_milestones to authenticated;

grant select on public.contract_events to authenticated;

drop policy if exists contracts_select on public.contracts;
create policy contracts_select on public.contracts
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists contracts_insert on public.contracts;
create policy contracts_insert on public.contracts
  for insert to authenticated with check (public.is_company_member(company_id));

drop policy if exists contracts_update on public.contracts;
create policy contracts_update on public.contracts
  for update to authenticated
  using (public.is_company_member(company_id))
  with check (public.is_company_member(company_id));

-- ⚠️ Nessuna policy di DELETE e nessun grant sui contratti (§109): un contratto
-- non si cancella, si ARCHIVIA (§108). Archiviare non tocca i documenti, le
-- attività né lo storico — toglie dalla vista corrente. La cancellazione vera
-- appartiene a una politica di conservazione dei dati che questo prodotto non
-- ha ancora, e inventarla qui significherebbe dare a chiunque il potere di far
-- sparire la memoria di un impegno.

drop policy if exists contract_documents_select on public.contract_documents;
create policy contract_documents_select on public.contract_documents
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists contract_documents_insert on public.contract_documents;
create policy contract_documents_insert on public.contract_documents
  for insert to authenticated with check (public.is_company_member(company_id));

drop policy if exists contract_documents_update on public.contract_documents;
create policy contract_documents_update on public.contract_documents
  for update to authenticated
  using (public.is_company_member(company_id))
  with check (public.is_company_member(company_id));

drop policy if exists contract_documents_delete on public.contract_documents;
create policy contract_documents_delete on public.contract_documents
  for delete to authenticated using (public.is_company_member(company_id));

drop policy if exists contract_extractions_select on public.contract_extractions;
create policy contract_extractions_select on public.contract_extractions
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists contract_term_versions_select on public.contract_term_versions;
create policy contract_term_versions_select on public.contract_term_versions
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists contract_corrections_select on public.contract_corrections;
create policy contract_corrections_select on public.contract_corrections
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists contract_corrections_insert on public.contract_corrections;
create policy contract_corrections_insert on public.contract_corrections
  for insert to authenticated with check (public.is_company_member(company_id));

drop policy if exists contract_milestones_select on public.contract_milestones;
create policy contract_milestones_select on public.contract_milestones
  for select to authenticated using (public.is_company_member(company_id));

drop policy if exists contract_milestones_insert on public.contract_milestones;
create policy contract_milestones_insert on public.contract_milestones
  for insert to authenticated with check (public.is_company_member(company_id));

drop policy if exists contract_milestones_update on public.contract_milestones;
create policy contract_milestones_update on public.contract_milestones
  for update to authenticated
  using (public.is_company_member(company_id))
  with check (public.is_company_member(company_id));

drop policy if exists contract_events_select on public.contract_events;
create policy contract_events_select on public.contract_events
  for select to authenticated using (public.is_company_member(company_id));

revoke all on function public.list_contracts(uuid, text, text, public.contract_type, public.contract_lifecycle_status, public.contract_review_status, uuid, public.contract_auto_renewal, boolean, integer, boolean, text, integer, integer, uuid) from public, anon;
grant execute on function public.list_contracts(uuid, text, text, public.contract_type, public.contract_lifecycle_status, public.contract_review_status, uuid, public.contract_auto_renewal, boolean, integer, boolean, text, integer, integer, uuid) to authenticated;
revoke all on function public.contract_summary(uuid, integer) from public, anon;
grant execute on function public.contract_summary(uuid, integer) to authenticated;
revoke all on function public.contract_verify_terms(uuid) from public, anon;
grant execute on function public.contract_verify_terms(uuid) to authenticated;
revoke all on function public.contract_open_draft(uuid) from public, anon;
grant execute on function public.contract_open_draft(uuid) to authenticated;
revoke all on function public.contract_document_suggestions(uuid, integer) from public, anon;
grant execute on function public.contract_document_suggestions(uuid, integer) to authenticated;
-- Le funzioni di calcolo sono leggibili: servono all'interfaccia per spiegare
-- una data derivata, e non scrivono niente.
revoke all on function public.contract_period_interval(integer, public.contract_period_unit) from public, anon;
grant execute on function public.contract_period_interval(integer, public.contract_period_unit) to authenticated;
revoke all on function public.contract_notice_deadline(integer, public.contract_period_unit, public.contract_notice_anchor, date) from public, anon;
grant execute on function public.contract_notice_deadline(integer, public.contract_period_unit, public.contract_notice_anchor, date) to authenticated;
revoke all on function public.contract_calculation_version() from public, anon;
grant execute on function public.contract_calculation_version() to authenticated;


-- ---------------------------------------------------------------------------
-- 34. Autoverifica: la migrazione controlla di aver ottenuto ciò che dichiara.
--
-- Non è un ornamento. La 0013 dichiarava nei commenti una garanzia che non
-- esisteva, e lo si scoprì solo eseguendo i test sul database vero. Da allora
-- ogni migrazione che promette qualcosa la verifica prima di dirsi riuscita.
--
-- ⚠️ Nessuna riga di questo blocco nomina i quattro valori enum aggiunti al
-- punto 2 e nessuna chiama una funzione che li nomini: il blocco viene ESEGUITO,
-- e valutare qui un'etichetta nuova farebbe fallire l'intera applicazione con
-- 55P04. È la trappola della 0015, ed è al quarto giro che la si conosce.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
  v_date date;
begin
  -- ⚠️ `information_schema` riporta il ruolo PUBLIC in MAIUSCOLO: cercare solo
  -- 'public' lascerebbe scoperto proprio il ruolo che vale per CHIUNQUE.

  -- (a) I verbali e i termini NON devono essere scrivibili dal browser. È la
  --     garanzia più importante del modulo: se cade, un membro può riscrivere il
  --     preavviso di un contratto senza lasciare traccia in nessuna correzione,
  --     e la distinzione fra ciò che il documento dice e ciò che qualcuno ha
  --     deciso sparisce.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name in ('contract_extractions', 'contract_term_versions', 'contract_events')
    and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
    and privilege_type in ('INSERT', 'UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'i verbali e i termini risultano scrivibili dal client: %', v_bad;
  end if;

  -- (b) Un contratto non si cancella dal client (§109).
  select string_agg(format('%s.%s', table_name, privilege_type), ', ')
    into v_bad
  from information_schema.table_privileges
  where table_schema = 'public'
    and table_name = 'contracts'
    and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
    and privilege_type = 'DELETE';
  if v_bad is not null then
    raise exception 'i contratti risultano cancellabili dal client: %', v_bad;
  end if;

  -- (c) Lo stato di verifica non è scrivibile colonna per colonna.
  select string_agg(format('contracts.%s', column_name), ', ')
    into v_bad
  from information_schema.column_privileges
  where table_schema = 'public'
    and table_name = 'contracts'
    and column_name in ('review_status', 'verified_at', 'verified_by',
                        'current_term_version_id', 'quality_flags', 'origin')
    and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
    and privilege_type in ('INSERT', 'UPDATE');
  if v_bad is not null then
    raise exception 'lo stato di verifica di un contratto risulta scrivibile dal client: %', v_bad;
  end if;

  -- (d) La RLS è accesa su tutte e sette le tabelle.
  select string_agg(c.relname, ', ') into v_bad
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public'
     and c.relname in ('contracts', 'contract_documents', 'contract_extractions',
                       'contract_term_versions', 'contract_corrections',
                       'contract_milestones', 'contract_events')
     and c.relrowsecurity = false;
  if v_bad is not null then
    raise exception 'RLS non attiva su: %', v_bad;
  end if;

  -- (e) ⚠️ L'ARITMETICA DELLE DATE FA QUELLO CHE IL FILE DICHIARA.
  --     Non si verifica la sintassi: si verifica il RISULTATO, perché la
  --     semantica di fine mese di Postgres è un'affermazione di questo file e
  --     un'affermazione non provata è solo scritta. Tre casi che devono tornare,
  --     e uno che deve NON produrre una data.
  v_date := public.contract_notice_deadline(3, 'months', 'before_fixed_end', date '2026-12-31');
  if v_date is distinct from date '2026-09-30' then
    raise exception 'preavviso 3 mesi da 31.12.2026 atteso 30.09.2026, ottenuto %', v_date;
  end if;

  -- 31 marzo meno un mese: il 31 febbraio non esiste e Postgres aggancia la fine
  -- del mese. In un anno bisestile diventa il 29.
  v_date := public.contract_notice_deadline(1, 'months', 'before_fixed_end', date '2024-03-31');
  if v_date is distinct from date '2024-02-29' then
    raise exception 'preavviso 1 mese da 31.03.2024 atteso 29.02.2024, ottenuto %', v_date;
  end if;
  v_date := public.contract_notice_deadline(1, 'months', 'before_fixed_end', date '2026-03-31');
  if v_date is distinct from date '2026-02-28' then
    raise exception 'preavviso 1 mese da 31.03.2026 atteso 28.02.2026, ottenuto %', v_date;
  end if;

  -- §46 — «per fine mese» NON produce una data, ed è il caso che conta di più:
  -- se un giorno qualcuno aggiungesse quell'ancoraggio all'elenco dei
  -- calcolabili, questa riga fallirebbe prima che una scadenza sbagliata
  -- raggiunga un cliente.
  v_date := public.contract_notice_deadline(3, 'months', 'to_month_end', date '2026-12-31');
  if v_date is not null then
    raise exception 'un preavviso «per fine mese» non deve produrre una data, ottenuto %', v_date;
  end if;
  v_date := public.contract_notice_deadline(3, 'months', 'before_fixed_end', null);
  if v_date is not null then
    raise exception 'senza data di riferimento non si deriva alcuna scadenza, ottenuto %', v_date;
  end if;

  raise notice '0024 applicata: 7 tabelle, RLS attiva, permessi verificati, aritmetica delle date provata.';
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0025_contract_fixes  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0025 — DUE CORREZIONI ALLA 0024
--
-- Trovate da `npm run test:contracts` alla PRIMA esecuzione sul database vero,
-- e non da una rilettura. Sono entrambe la ripetizione di una trappola già
-- pagata da questo progetto e già scritta in chiaro nelle migrazioni
-- precedenti: averle riprodotte dice quanto poco basti, e quanto valga
-- eseguire invece di ragionare.
--
-- (a) Il `CASE` che sceglie un'etichetta enum si risolve come `text` (0022).
--     Conseguenza: NESSUN VERBALE POTEVA ESSERE SCRITTO. Il worker avrebbe
--     fallito su ogni documento, e il modulo sarebbe stato inutilizzabile.
--
-- (b) Un trigger che INSERISCE durante una cancellazione a cascata la fa
--     fallire (parente stretto della 0023, dove era un trigger che SOLLEVAVA).
--     Conseguenza: un'azienda con contratti era indistruttibile, e la pulizia
--     dei test lasciava residui in produzione — è già successo due volte.
--
-- Requisiti: 0001–0024 applicate.
-- ============================================================================


-- ---------------------------------------------------------------------------
-- (a) ⚠️⚠️ L'ENUM DENTRO UN `CASE` VUOLE IL CAST SU OGNI RAMO
--
-- Quando TUTTI i rami di un `CASE` sono letterali senza tipo, Postgres risolve
-- l'espressione come `text`, e da `text` a un enum non esiste conversione
-- implicita: 42804. Un letterale NUDO (`'created'`) passa, perché resta
-- `unknown` e viene coercito alla colonna — ed è per questo che nello stesso
-- file quattro insert funzionavano e uno no, e che rileggendo non si vedeva.
--
-- È ESATTAMENTE il difetto della 0022, riprodotto due migrazioni dopo, nella
-- stessa forma e nello stesso tipo di trigger.
--
-- ⚠️ Nessuna verifica statica può vederlo: il corpo di una funzione plpgsql non
-- viene analizzato alla creazione. Lo vede solo chi ESEGUE.
-- ---------------------------------------------------------------------------
create or replace function public.contract_after_extraction()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_relation public.contract_document_relation;
  v_kind     public.contract_event_kind;
begin
  select cd.relation into v_relation
    from public.contract_documents cd
   where cd.contract_id = new.contract_id and cd.document_id = new.document_id;

  if new.status = 'completed' then
    update public.contract_documents
       set current_extraction_id = new.id,
           processing_status = 'completed',
           error_code = null
     where contract_id = new.contract_id and document_id = new.document_id;
  else
    -- ⚠️ ANCHE IL FALLIMENTO LO SCRIVE IL TRIGGER, non il worker (lezione della
    -- 0021): due posti in cui ricordarsene sono uno di troppo.
    update public.contract_documents
       set processing_status = 'failed', error_code = new.error_code
     where contract_id = new.contract_id and document_id = new.document_id;
  end if;

  -- ⚠️ L'ETICHETTA SI SCEGLIE IN UNA VARIABILE TIPIZZATA, non dentro l'insert.
  -- È la forma che non può sbagliare: il tipo lo dichiara la variabile, e un
  -- valore fuori enum fallirebbe qui, dove si vede, invece che in un `case`
  -- che si risolve in silenzio come testo.
  if new.status = 'completed' then
    v_kind := 'extraction_completed';
  else
    v_kind := 'extraction_failed';
  end if;

  insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
  values (new.company_id, new.contract_id, null, v_kind,
          jsonb_build_object('documentId', new.document_id,
                             'version', new.extraction_version,
                             'relation', v_relation));

  if new.status = 'completed' then
    perform public.contract_refresh_draft(new.contract_id);

    -- La revisione si riapre solo se c'era qualcosa da riaprire: su un contratto
    -- mai verificato lo stato è già `needs_review`.
    if v_relation in ('amendment', 'renewal') then
      perform set_config('ai_swisse.contract_review', '1', true);
      update public.contracts
         set review_status = 'review_required_again'
       where id = new.contract_id and review_status = 'verified';
      perform set_config('ai_swisse.contract_review', '0', true);

      insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
      values (new.company_id, new.contract_id, null, 'amendment_added',
              jsonb_build_object('documentId', new.document_id, 'relation', v_relation));
    end if;

    perform public.contract_refresh_flags(new.contract_id);
  end if;

  return new;
end $$;


-- ---------------------------------------------------------------------------
-- (b) ⚠️⚠️ UN TRIGGER CHE SCRIVE DURANTE UNA CASCATA LA FA FALLIRE
--
-- Cancellando un'AZIENDA, la cascata arriva a `contract_documents`; il trigger
-- di storico inseriva allora una riga in `contract_events`, la cui chiave
-- esterna punta a un'azienda che sta sparendo nella stessa transazione:
-- 23503, e la cancellazione fallisce PER INTERO.
--
-- È il parente stretto della 0023 — là un trigger SOLLEVAVA durante la cascata,
-- qui SCRIVE — e la regola generale è la stessa, con una parola cambiata:
--   «prima di scrivere in un trigger, chiedersi chi altro passa di lì».
--
-- La correzione non indebolisce lo storico: si registra la rimozione di un
-- documento SE il contratto esiste ancora, cioè quando è davvero un gesto di
-- qualcuno. Se sta sparendo anche il contratto, non c'è alcuno storico da
-- tenere — sparisce con lui.
-- ---------------------------------------------------------------------------
create or replace function public.contract_documents_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
    values (new.company_id, new.contract_id, new.added_by, 'document_added',
            jsonb_build_object('documentId', new.document_id, 'relation', new.relation,
                               'suggested', new.suggested));
    return new;
  end if;

  -- ⚠️ Il controllo è su AZIENDA e CONTRATTO insieme: durante la cascata di una
  -- cancellazione l'ordine con cui le righe spariscono non è garantito, e
  -- bastava che una delle due fosse già andata per far fallire l'insert.
  if exists (select 1 from public.contracts c where c.id = old.contract_id)
     and exists (select 1 from public.companies co where co.id = old.company_id) then
    insert into public.contract_events (company_id, contract_id, actor_user_id, kind, detail)
    values (old.company_id, old.contract_id, auth.uid(), 'document_removed',
            jsonb_build_object('documentId', old.document_id, 'relation', old.relation));
  end if;
  return old;
end $$;

-- Stessa difesa sul ricalcolo della bozza: durante la cascata non c'è più nulla
-- da ricalcolare, e provarci solleverebbe. Il controllo c'era già sul
-- contratto; qui si aggiunge l'azienda, per la ragione appena detta.
create or replace function public.contract_documents_after_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (select 1 from public.contracts c where c.id = old.contract_id)
     and exists (select 1 from public.companies co where co.id = old.company_id) then
    perform public.contract_refresh_draft(old.contract_id);
  end if;
  return old;
end $$;

-- Le milestone hanno la stessa forma: il loro trigger di storico scrive in
-- `contract_events` anche su UPDATE, e un update a cascata non esiste — ma
-- `contracts_events` sì, e scrive su ogni update del contratto. Durante la
-- cancellazione di un'azienda nessuno aggiorna un contratto, quindi lì il
-- problema non si pone: si lascia com'è invece di aggiungere difese a un caso
-- che non esiste.


-- ---------------------------------------------------------------------------
-- Autoverifica: le due correzioni fanno ciò che dichiarano.
--
-- ⚠️ Si CREANO davvero un'azienda, un documento, un contratto e un'estrazione,
-- e poi si cancella tutto. È l'unico modo di provare (a): il corpo di una
-- funzione plpgsql non viene analizzato alla creazione, quindi solo una
-- chiamata vera fa emergere il 42804.
--
-- ⚠️ Nessuna riga di questo blocco nomina i quattro valori enum aggiunti dalla
-- 0024 a `automation_event_type` (55P04): l'estrazione qui sotto NON fa
-- scattare `contract_emit_automation`, che si attiva sugli update di
-- `contracts` e solo quando una regola attiva ascolta — e qui non ce ne sono.
-- ---------------------------------------------------------------------------
do $$
declare
  v_company uuid;
  v_doc     uuid;
  v_contract uuid;
  v_events  integer;
begin
  insert into public.companies (legal_name) values ('__verifica 0025__')
  returning id into v_company;

  insert into public.documents (company_id, title, source_type, status)
  values (v_company, '__verifica 0025__', 'upload', 'completed')
  returning id into v_doc;

  insert into public.contracts (company_id, display_name)
  values (v_company, '__verifica 0025__')
  returning id into v_contract;

  insert into public.contract_documents (company_id, contract_id, document_id, relation)
  values (v_company, v_contract, v_doc, 'main_agreement');

  -- (a) Se il `CASE` fosse ancora lì, questa riga fallirebbe con 42804.
  insert into public.contract_extractions
    (company_id, contract_id, document_id, extraction_version, status,
     notice_period_value, notice_period_unit, notice_anchor, end_date, end_date_kind)
  values (v_company, v_contract, v_doc, 1, 'completed',
          3, 'months', 'before_fixed_end', date '2026-12-31', 'explicit');

  select count(*) into v_events from public.contract_events
   where contract_id = v_contract and kind = 'extraction_completed';
  if v_events <> 1 then
    raise exception 'lo storico dell''estrazione non è stato scritto (atteso 1, trovato %)', v_events;
  end if;

  -- La bozza si è ricalcolata e la data è stata derivata.
  if not exists (
    select 1 from public.contract_milestones
     where contract_id = v_contract and kind = 'notice_deadline'
       and due_date = date '2026-09-30' and source = 'derived'
  ) then
    raise exception 'la data di disdetta non è stata derivata dall''estrazione';
  end if;

  -- (b) Se il trigger scrivesse ancora durante la cascata, questa riga
  --     fallirebbe con 23503 e l'azienda sarebbe indistruttibile.
  delete from public.companies where id = v_company;

  if exists (select 1 from public.contracts where id = v_contract) then
    raise exception 'il contratto è sopravvissuto alla cancellazione dell''azienda';
  end if;
  if exists (select 1 from public.contract_events where contract_id = v_contract) then
    raise exception 'lo storico è sopravvissuto alla cancellazione dell''azienda';
  end if;

  raise notice '0025 applicata: verbale scrivibile, date derivate, cascata pulita.';
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0026_crm_light  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0026 — CRM LIGHT: CLIENTI E CONTROPARTI
--
-- Con chi stiamo lavorando? È l'unica domanda che questo modulo aggiunge.
-- Fino alla 0025 il prodotto sapeva che cosa è arrivato (Inbox), che cosa
-- sappiamo (Documenti), che cosa dobbiamo fare (Attività), quando (Calendario),
-- che cosa non dimenticare (Notifiche), che cosa può fare da sé (Automazioni),
-- quali operazioni finanziarie richiedono attenzione (Finanze) e a quali
-- obblighi siamo legati (Contratti). Mancava il soggetto di tutte quelle frasi.
--
-- ⚠️ QUESTA MIGRAZIONE SUPERA UNA DECISIONE SCRITTA, E LO DICE.
-- La 0024, righe 332-335, sul campo `contracts.counterparty_name`:
--   «la controparte è METADATO CONTRATTUALE, non un'anagrafica. Nessun
--    riferimento a una tabella di clienti o fornitori: quella tabella non
--    esiste, e crearla qui significherebbe cominciare un CRM di straforo».
-- E docs/finance-operations.md riga 63: «nessuna anagrafica fornitori: il
-- fornitore è un nome letto sul documento».
-- Erano affermazioni giuste FINCHÉ la tabella non esisteva. Qui esiste, e il
-- modo in cui quelle scelte vengono superate è il punto: NESSUN NOME ESTRATTO
-- VIENE RISCRITTO. `contracts.counterparty_name`, `contract_extractions.
-- counterparty`, `finance_items.eff_supplier_name`, `email_messages.
-- sender_email` restano esattamente ciò che erano. Accanto compare una colonna
-- di collegamento FACOLTATIVA e ANNULLABILE. Un contratto con
-- `counterparty_organization_id = null` è uno stato legittimo e resta tale.
--
-- ⚠️ COLLEGARE, NON COPIARE. Nessuna tabella di questo file contiene una copia
-- del corpo di una email, del testo di un documento, di una clausola, di un
-- importo estratto o di un commento. La timeline COMPONE riferimenti.
--
-- ⚠️ SUGGERIRE, NON INVENTARE. Nessuna organizzazione nasce da sola.
-- Misurato sulle 117 email vere della casella collegata (2026-07-29):
-- 54 mittenti distinti, 44 domini, 57 messaggi `is_bulk`, 40 mittenti
-- noreply/newsletter, 55 messaggi `clearly_irrelevant`. Creare un'anagrafica
-- per mittente avrebbe prodotto 44 righe fatte di stripe.com, amazon.it,
-- mail.adobe.com. Con il filtro di questo modulo i 54 mittenti diventano 6 —
-- e fra quei 6 restano ancora amazon.it e info.interdiscount.ch. Perciò quelle
-- righe sono SUGGERIMENTI (crm_link_suggestions), non clienti.
--
-- ⚠️ VERIFICARE, NON FONDERE. Due nomi simili non sono la stessa impresa.
-- L'unico abbinamento automatico ammesso è su identità forte (IDI valido o
-- indirizzo email identico). Tutto il resto si propone a una persona.
--
--   COMUNICAZIONE → CONTROPARTE → PERSONE → DOCUMENTI → OPPORTUNITÀ
--                 → ATTIVITÀ → CONTRATTI → FINANZE → STORICO DELLA RELAZIONE
--
-- Requisiti: 0001–0025 applicate.
-- Documento di modulo: docs/crm-light.md
-- ============================================================================


-- ---------------------------------------------------------------------------
-- 1. I tipi
--
-- Tutti con `create type … as enum (…)`: i valori dichiarati alla creazione
-- sono utilizzabili SUBITO, anche nella stessa transazione. È la differenza con
-- `alter type … add value` della sezione 2, che rende l'etichetta inservibile
-- fino al commit (55P04, lezione della 0015 e poi della 0022).
-- ---------------------------------------------------------------------------

-- Che rapporto abbiamo con questa organizzazione. §8 — sono RUOLI, non stati, e
-- sono MULTIPLI: la stessa impresa può essere insieme cliente, fornitore e
-- partner. Un campo unico `type = 'customer'` avrebbe reso quel caso — comune in
-- una PMI — inesprimibile.
do $$ begin
  create type public.crm_organization_role as enum (
    'lead',            -- un nome arrivato, nessun rapporto ancora
    'prospect',        -- ci stiamo parlando
    'customer',
    'former_customer', -- è stato cliente: non è un lead, e non è un cliente
    'supplier',
    'partner',
    'authority',       -- comune, cantone, Confederazione, cassa, assicurazione sociale
    'other'
  );
exception when duplicate_object then null; end $$;

-- Lo stato del rapporto. §10 — DUE valori, non tre.
-- ⚠️ «archived» NON è qui: l'archiviazione è `archived_at` / `archived_by`,
-- come in documents, tasks, contracts, finance_items. Uno stato che duplica un
-- timestamp finisce per divergere dal timestamp, e allora nessuno dei due si
-- può più credere.
do $$ begin
  create type public.crm_relationship_status as enum ('active', 'inactive');
exception when duplicate_object then null; end $$;

-- Da dove viene questa riga. §19 — la provenienza NON è una verifica: una
-- controparte suggerita da una fattura non è per questo un'anagrafica
-- verificata, ed è la ragione per cui `source` e i suggerimenti convivono.
do $$ begin
  create type public.crm_source as enum (
    'manual',     -- l'ha scritta una persona
    'email',      -- proposta da un mittente, e poi confermata
    'document',
    'contract',
    'finance',
    'registry',   -- importata da Zefix, con il disclaimer di non vincolatività
    'import'
  );
exception when duplicate_object then null; end $$;

-- Un recapito. §14 — una persona non ha UN indirizzo: ne ha quanti ne ha.
do $$ begin
  create type public.crm_contact_method_type as enum (
    'email', 'phone', 'mobile', 'website', 'other'
  );
exception when duplicate_object then null; end $$;

-- La fase di una TRATTATIVA. §9 e §41 — non è il ruolo dell'organizzazione:
-- `customer` descrive un rapporto, `negotiation` descrive una singola pratica.
-- Confonderli produrrebbe un cliente che «torna lead» perché una seconda
-- trattativa è appena cominciata.
do $$ begin
  create type public.crm_opportunity_stage as enum (
    'lead', 'contacted', 'proposal', 'negotiation', 'won', 'lost'
  );
exception when duplicate_object then null; end $$;

-- Un contatto avvenuto che nessun altro modulo registra. §63 e §64 — le email
-- NON entrano qui: restano in `email_messages` e si collegano. Copiarle
-- produrrebbe due verità sulla stessa conversazione.
do $$ begin
  create type public.crm_interaction_type as enum ('note', 'call', 'meeting', 'other');
exception when duplicate_object then null; end $$;

-- Che ruolo ha un documento rispetto a questa organizzazione. §34.
do $$ begin
  create type public.crm_document_relation as enum (
    'sender', 'recipient', 'counterparty', 'customer', 'supplier', 'other'
  );
exception when duplicate_object then null; end $$;

-- Perché due cose sono state avvicinate. §22-§25 — il motivo NON è decorativo:
-- decide se il collegamento può avvenire da solo o deve passare da una persona.
-- `uid_exact` ed `email_exact` sono identità; `domain_match` e `name_normalized`
-- sono sospetti, e restano suggerimenti.
do $$ begin
  create type public.crm_match_reason as enum (
    'uid_exact',
    'email_exact',
    'domain_match',
    'name_normalized',
    'manual'
  );
exception when duplicate_object then null; end $$;

-- Che fine ha fatto un suggerimento. §21.
-- `ignored` non è `rejected`: «non ora» e «no» sono risposte diverse, e la
-- seconda non va riproposta.
do $$ begin
  create type public.crm_link_status as enum ('pending', 'accepted', 'rejected', 'ignored');
exception when duplicate_object then null; end $$;

-- Lo storico. §85 — append-only, scritto SOLO da trigger. Non c'è un valore per
-- «qualcuno ha aperto la scheda»: registrare le visualizzazioni sarebbe
-- sorveglianza, non storia.
do $$ begin
  create type public.crm_event_kind as enum (
    'organization_created',
    'organization_updated',
    'role_added',
    'role_removed',
    'owner_changed',
    'contact_added',
    'contact_linked',
    'contact_unlinked',
    'opportunity_created',
    'opportunity_stage_changed',
    'opportunity_won',
    'opportunity_lost',
    'interaction_created',
    'entity_linked',
    'entity_unlinked',
    'archived',
    'restored',
    'merged'
  );
exception when duplicate_object then null; end $$;

-- Che cosa è stato collegato. Serve allo storico per dire «documento» invece di
-- un id nudo, e ai suggerimenti per sapere da dove sono nati.
do $$ begin
  create type public.crm_linked_entity as enum (
    'document', 'email_message', 'task', 'contract', 'finance_item', 'opportunity'
  );
exception when duplicate_object then null; end $$;


-- ---------------------------------------------------------------------------
-- 2. I valori aggiunti a enum ESISTENTI
--
-- ⚠️⚠️ REGOLA CHE VALE PER TUTTO IL RESTO DEL FILE, E CHE È GIÀ COSTATA DUE
-- MIGRAZIONI (0015, 0022): un valore aggiunto con `alter type … add value` NON
-- è utilizzabile in nessun'altra ISTRUZIONE di questo file. Non in un indice
-- parziale, non in un insert, non in un default, non in un check, non in un
-- blocco anonimo `do`. Postgres lo rifiuta con 55P04 finché la transazione non
-- è chiusa, e `supabase/full-setup.sql` concatena TUTTE le migrazioni in una
-- transazione sola: spezzare in due file non risolverebbe, romperebbe soltanto
-- le installazioni da zero, cioè il prossimo cliente.
-- (Nota di forma: in questo file nessun commento contiene la coppia di dollari
-- che delimita un corpo, così il bilanciamento dei delimitatori si può
-- verificare contandoli — un controllo che altrimenti darebbe un falso allarme.)
--
-- L'ECCEZIONE, ed è quella che rende possibile questo modulo: il letterale PUÒ
-- comparire dentro il CORPO di una `create function`, perché Postgres deposita
-- il corpo come testo e risolve l'etichetta alla prima ESECUZIONE. Tutti i
-- trigger di questo file che emettono eventi o notifiche usano quell'eccezione.
-- `scripts/bundle-migrations.mjs` conosce la differenza e la verifica.
-- ---------------------------------------------------------------------------

-- §131 — sei inneschi, e solo quelli che hanno davvero una sorgente in questo
-- file. `crm_follow_up_due` non ne ha una propria: riusa lo scanner periodico
-- della sezione 20, che a sua volta gira dentro il worker già acceso. Nessun
-- cron nuovo (regola scritta nella 0024 riga 2553).
alter type public.automation_event_type add value if not exists 'crm_organization_created';
alter type public.automation_event_type add value if not exists 'crm_role_added';
alter type public.automation_event_type add value if not exists 'crm_opportunity_created';
alter type public.automation_event_type add value if not exists 'crm_opportunity_stage_changed';
alter type public.automation_event_type add value if not exists 'crm_opportunity_won';
alter type public.automation_event_type add value if not exists 'crm_follow_up_due';

-- §141 — NON si crea `crm_notifications`. `public.notifications` è già per
-- utente, ha già RLS per persona, grant di sola select, guardiano di
-- membership e funzioni di marcatura. Una seconda campanella sarebbe una
-- seconda campanella.
alter type public.notification_type add value if not exists 'crm_opportunity_assigned';

-- §50 — un'attività può nascere dal CRM, e allora lo dice.
-- ⚠️ Va aggiunto anche allo switch esaustivo `sourceLabelKey()` in
-- src/features/tasks/taskFormat.ts con le tre traduzioni, altrimenti il
-- typecheck fallisce — ed è voluto che fallisca.
alter type public.task_source add value if not exists 'crm';


-- ---------------------------------------------------------------------------
-- 3. Le funzioni di normalizzazione
--
-- Sono PURE e `immutable`: servono agli indici, alle colonne generate e al
-- confronto. Ognuna ha un gemello in TypeScript, e `test:crm-unit` legge QUESTO
-- FILE per verificare che le due copie non siano divergenti — è l'unico
-- controllo che può vederlo, perché il typecheck non guarda dentro l'SQL.
--
-- ⚠️ NESSUNA DI QUESTE FUNZIONI È UN'IDENTITÀ, tranne quella dell'IDI.
-- Normalizzare serve a SOSPETTARE, non a decidere.
-- ---------------------------------------------------------------------------

-- §15 — l'email si confronta in minuscolo e senza spazi, e NIENT'ALTRO.
-- ⚠️ Non si tolgono i punti di Gmail e non si taglia il `+tag`: sono regole di
-- un fornitore, non del protocollo, e applicarle significa DECIDERE che due
-- indirizzi diversi sono la stessa persona. Se sbaglia, sbaglia unendo persone.
-- Nota utile: `email_messages.sender_email` è GIÀ minuscolo alla sorgente
-- (parseAddress in _shared/email/normalize.ts), quindi il confronto con questa
-- funzione è esatto senza ulteriore lavoro.
create or replace function public.crm_norm_email(p_value text)
returns text
language sql
immutable
set search_path = ''
as $$
  select nullif(lower(btrim(coalesce(p_value, ''))), '');
$$;

comment on function public.crm_norm_email(text) is
  'Minuscolo e spazi tolti. Nessuna regola di provider: togliere i punti di '
  'Gmail o il +tag significherebbe inventare un''identità (§15).';

-- Il dominio di un indirizzo o di un sito, per il confronto del §23.
-- Accetta sia `laura@rossi.ch` sia `https://www.rossi.ch/chi-siamo`.
create or replace function public.crm_norm_domain(p_value text)
returns text
language sql
immutable
set search_path = ''
as $$
  select nullif(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          lower(btrim(coalesce(p_value, ''))),
          '^[a-z][a-z0-9+.-]*://', ''            -- via lo schema
        ),
        '^[^@/]*@', ''                            -- se è un indirizzo, via la parte locale
      ),
      '^(www\.)?([^/:?#]*).*$', '\2'              -- via www., via percorso/porta/query
    ),
    ''
  );
$$;

comment on function public.crm_norm_domain(text) is
  'Il dominio di un indirizzo o di un URL, in minuscolo, senza schema, senza '
  '«www.» e senza percorso. Serve al suggerimento del §23, mai a un '
  'collegamento automatico.';

-- §24 — un dominio pubblico NON prova che due persone lavorino insieme.
-- ⚠️ Questo elenco esiste in DUE posti: qui e in `src/features/crm/crmMatch.ts`.
-- La duplicazione è deliberata (l'SQL deve poter filtrare senza chiamare il
-- browser) e sorvegliata: `test:crm-unit` legge questo file, estrae l'array e
-- lo confronta con la costante TypeScript. È l'unico modo di accorgersi che
-- divergono — la lezione degli ancoraggi dei contratti, che vivevano in due
-- posti e in uno solo erano giusti.
create or replace function public.crm_is_public_domain(p_domain text)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select coalesce(lower(btrim(p_domain)), '') = any (array[
    'gmail.com',
    'googlemail.com',
    'outlook.com',
    'hotmail.com',
    'hotmail.ch',
    'live.com',
    'msn.com',
    'yahoo.com',
    'yahoo.it',
    'icloud.com',
    'me.com',
    'proton.me',
    'protonmail.com',
    'gmx.ch',
    'gmx.net',
    'bluewin.ch',
    'sunrise.ch',
    'hispeed.ch',
    'tiscali.it',
    'libero.it',
    'aol.com'
  ]);
$$;

comment on function public.crm_is_public_domain(text) is
  'Vero per i domini di posta pubblici. §24 — «bluewin.ch» non è un''impresa: '
  'due indirizzi su un dominio pubblico non collegano nessuno. L''elenco è '
  'duplicato in src/features/crm/crmMatch.ts e test:crm-unit confronta le copie.';

-- L'IDI, in forma canonica per il confronto: `CHE` + 9 cifre, senza punti.
-- ⚠️ Ritorna NULL se la CIFRA DI CONTROLLO non torna, e questo è il punto:
-- un IDI non verificato non identifica nessuno, quindi non deve poter
-- collegare niente da solo (§25 grado 1). L'algoritmo mod-11 è lo stesso di
-- `uidDigits/isValidUid` in src/lib/uid.ts e di `checkUid` in
-- supabase/functions/_shared/finance/checksums.ts: la terza copia è dichiarata,
-- e `test:crm` la confronta con la seconda su una serie di IDI veri.
create or replace function public.crm_norm_uid(p_value text)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_digits text;
  v_weights integer[] := array[5, 4, 3, 2, 7, 6, 5, 4];
  v_sum     integer := 0;
  v_check   integer;
  i         integer;
begin
  v_digits := regexp_replace(coalesce(p_value, ''), '\D', '', 'g');
  if length(v_digits) <> 9 then
    return null;
  end if;

  for i in 1..8 loop
    v_sum := v_sum + (substr(v_digits, i, 1))::integer * v_weights[i];
  end loop;

  v_check := 11 - (v_sum % 11);
  -- 10 non è una cifra e 11 si riscrive 0: sono i due casi che una lettura
  -- distratta della norma perde, e sono esattamente quelli che fanno passare
  -- un IDI inventato.
  if v_check = 11 then
    v_check := 0;
  elsif v_check = 10 then
    return null;
  end if;

  if v_check <> (substr(v_digits, 9, 1))::integer then
    return null;
  end if;

  return 'CHE' || v_digits;
end $$;

comment on function public.crm_norm_uid(text) is
  'L''IDI in forma canonica CHE+9 cifre, oppure NULL se la cifra di controllo '
  'mod-11 non torna. §25 — un IDI non verificato non identifica nessuno e non '
  'deve poter collegare niente da solo.';

-- §16 — il telefono si normalizza con prudenza, per cercare e per sospettare un
-- doppione. Non si costruisce un sistema telefonico: non si indovina il
-- prefisso internazionale mancante, perché indovinarlo significa attribuire un
-- paese a un numero che non lo dichiara. Il valore ORIGINALE resta sempre.
create or replace function public.crm_norm_phone(p_value text)
returns text
language sql
immutable
set search_path = ''
as $$
  select nullif(
    case
      when btrim(coalesce(p_value, '')) like '+%'
        then '+' || regexp_replace(p_value, '\D', '', 'g')
      else regexp_replace(coalesce(p_value, ''), '\D', '', 'g')
    end,
    ''
  );
$$;

comment on function public.crm_norm_phone(text) is
  'Solo cifre, con il + iniziale se c''era. Non si indovina il prefisso '
  'internazionale mancante: sarebbe attribuire un paese a un numero che non lo '
  'dichiara (§16). Il valore originale resta in `value`.';


-- ---------------------------------------------------------------------------
-- 4. crm_organizations — LA CONTROPARTE
--
-- §5. È il centro del modulo: un'impresa, un ente, uno studio, un comune.
--
-- ⚠️ NON È `public.companies`. Quella è il TENANT — l'impresa che USA
-- AI-Swisse, una riga per cliente, creata solo dalla RPC
-- `create_company_with_owner`. Qui c'è chi sta DALL'ALTRA PARTE. Metterle nella
-- stessa tabella con una bandierina avrebbe reso possibile, con un errore di
-- filtro, mostrare a un cliente l'elenco degli altri clienti del prodotto.
-- Conseguenza da tenere a mente: `companies.uid_che` è l'IDI di chi usa il
-- prodotto, `crm_organizations.uid_che` è l'IDI di una controparte. Non sono
-- la stessa cosa e non vanno confrontati fra loro.
--
-- ⚠️ NIENTE `primary_email` / `primary_phone` QUI (deviazione dichiarata dal
-- §5, che chiede di adattare il modello alle convenzioni reali). Sarebbero una
-- seconda verità accanto a `crm_contact_methods`, dove `is_primary` esiste già
-- e vale sia per le persone sia per le organizzazioni. Il recapito principale
-- è un valore COMPOSTO IN LETTURA, non una colonna scritta due volte: è la
-- stessa disciplina per cui Documenti compone il mittente effettivo invece di
-- ricopiarlo.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_organizations (
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid not null references public.companies(id) on delete cascade,

  -- §6 — due nomi, perché servono a due cose. `display_name` è come la
  -- chiamiamo noi e compare in ogni schermata; `legal_name` è la ragione
  -- sociale. «Swisscom» e «Swisscom (Svizzera) SA» sono la stessa impresa, e
  -- costringere l'una a fare da titolo dell'altra rende le liste illeggibili.
  display_name  text not null,
  legal_name    text,

  -- §7 — identificativi, MAI obbligatori: non tutte le controparti sono
  -- svizzere, non tutte sono iscritte, e una persona fisica non ha un IDI.
  -- `uid_che` è l'unica identità forte del modello (vedi l'indice unico della
  -- sezione 15); `uid_norm` è la sua forma canonica ed è scritta dal database,
  -- non dal client.
  uid_che       text,
  uid_norm      text,
  vat_number    text,

  website       text,
  -- Scritto dal guardiano da `website`. Serve al suggerimento del §23, e per
  -- questo NON è nei grant: un dominio scritto a mano diverso dal sito
  -- renderebbe il suggerimento una bugia con l'aria di un calcolo.
  website_domain text,

  -- §5 — l'indirizzo sta qui e non in una tabella a parte: nel repository non
  -- esiste alcun modello di indirizzo riutilizzabile (`public.companies` ha
  -- soltanto canton e municipality) e inventarne uno per una riga sola
  -- sarebbe una tabella in più senza un secondo utente.
  street        text,
  postal_code   text,
  city          text,
  -- ⚠️ Sigla cantonale a due lettere (`TI`, `LU`, `SG`), NON l'etichetta a sei
  -- valori di `programs.ts`: quella è il perimetro del catalogo incentivi, non
  -- della Svizzera, e un cliente di Lucerna registrato come «Altro» sarebbe un
  -- dato perso. La ricerca Zefix per nome NON restituisce il cantone: quando
  -- manca resta null, e null vuol dire «non lo sappiamo».
  canton        text,
  country_code  text,

  relationship_status public.crm_relationship_status not null default 'active',
  account_owner_user_id uuid references auth.users(id) on delete set null,

  source        public.crm_source not null default 'manual',
  -- §19 — da dove è arrivato il suggerimento che ha prodotto questa riga.
  -- Non è una verifica: dice solo chi l'ha proposta.
  source_detail text,

  notes         text,

  -- §67 — COPIA DENORMALIZZATA DICHIARATA, come `email_messages.
  -- analysis_deadline`. La verità sono le email collegate e le interazioni; qui
  -- c'è il massimo delle loro date, ricalcolato dal database
  -- (`crm_refresh_last_contact`) e MAI scrivibile dal client. Un campo manuale
  -- «ultimo contatto» avrebbe finito per contraddire la timeline che gli sta
  -- sotto, ed è esattamente il tipo di divergenza che questo progetto paga caro.
  last_contact_at timestamptz,

  archived_at   timestamptz,
  archived_by   uuid references auth.users(id) on delete set null,

  -- §31 — dopo una fusione il record secondario non sparisce: resta archiviato
  -- e punta al principale, così i vecchi collegamenti e i vecchi indirizzi
  -- continuano a portare da qualche parte invece che nel vuoto.
  merged_into_id uuid references public.crm_organizations(id) on delete set null,

  -- §140 — protezione dai cicli: se questa riga è nata da un'automazione, si sa
  -- quale. Senza, «quando nasce un cliente, crea un cliente» girerebbe per
  -- sempre. Precedenti: tasks.workflow_run_id (0020), contracts.workflow_run_id (0024).
  workflow_run_id uuid references public.workflow_runs(id) on delete set null,

  created_by    uuid references auth.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  constraint crm_org_display_name_not_blank check (btrim(display_name) <> ''),
  constraint crm_org_canton_len check (canton is null or length(canton) = 2),
  constraint crm_org_country_len check (country_code is null or length(country_code) = 2),
  constraint crm_org_not_merged_into_self check (merged_into_id is null or merged_into_id <> id)
);

comment on table public.crm_organizations is
  'Una controparte: cliente, fornitore, partner, ente. NON è public.companies, '
  'che è il tenant. Il nome estratto dai documenti non viene mai riscritto qui: '
  'questa tabella aggiunge un''identità, non sostituisce un fatto.';

comment on column public.crm_organizations.last_contact_at is
  'Copia denormalizzata dichiarata (§67): il massimo fra le date delle email '
  'collegate e delle interazioni. La scrive crm_refresh_last_contact, non il '
  'client. Fonte di verità: crm_organization_emails e crm_interactions.';

comment on column public.crm_organizations.uid_norm is
  'Forma canonica dell''IDI (CHE + 9 cifre) oppure NULL se la cifra di '
  'controllo non torna. Scritta dal guardiano. È l''unica identità forte del '
  'modello e regge l''indice unico.';


-- ---------------------------------------------------------------------------
-- 5. crm_organization_roles — I RUOLI, AL PLURALE
--
-- §3 e §8. Il caso che una colonna sola rendeva inesprimibile: l'officina che
-- ci ripara i furgoni (fornitore) e a cui vendiamo il gestionale (cliente).
-- Una riga per ruolo, `unique (organization_id, role)`.
--
-- ⚠️ §42 — quando un'opportunità è vinta si AGGIUNGE il ruolo `customer` e NON
-- si toglie `prospect`: cancellare il passato per aggiornare il presente è il
-- modo più rapido di perdere la storia di come è nato un cliente.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_organization_roles (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  organization_id uuid not null references public.crm_organizations(id) on delete cascade,
  role            public.crm_organization_role not null,
  created_by      uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),

  constraint uq_crm_org_role unique (organization_id, role)
);

comment on table public.crm_organization_roles is
  'I ruoli di un''organizzazione, multipli per scelta (§3): la stessa impresa '
  'può essere cliente, fornitore e partner nello stesso momento.';


-- ---------------------------------------------------------------------------
-- 6. crm_contacts — LE PERSONE
--
-- §4 e §13. «Laura Bianchi» è una riga; «Rossi SA» è un'altra; il legame è la
-- sezione 8. Salvare «Laura Bianchi — Rossi SA» come stringa unica avrebbe
-- reso impossibile la cosa che succede davvero: Laura cambia azienda.
--
-- ⚠️ Nome e cognome NON sono obbligatori separatamente (§13): di molti
-- contatti si conosce solo «Studio Bernasconi» o un nome di battesimo. Ciò che
-- è obbligatorio è `display_name`, perché una riga senza un modo di chiamarla
-- non serve a nessuno.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_contacts (
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid not null references public.companies(id) on delete cascade,

  first_name    text,
  last_name     text,
  display_name  text not null,

  -- Serve a scrivere alla persona nella sua lingua. Le tre del prodotto, e
  -- null quando non si sa: un default 'it' sarebbe un'ipotesi travestita da dato.
  preferred_language text,

  notes         text,

  archived_at   timestamptz,
  archived_by   uuid references auth.users(id) on delete set null,

  created_by    uuid references auth.users(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  constraint crm_contact_display_name_not_blank check (btrim(display_name) <> ''),
  constraint crm_contact_language_known
    check (preferred_language is null or preferred_language in ('it', 'de', 'fr'))
);

comment on table public.crm_contacts is
  'Le persone di contatto. §119 — solo dati professionali: nessuna data di '
  'nascita, nessun documento d''identità, nessun profilo social, nessuna '
  'categoria sensibile. Non sono utenti dell''applicazione.';


-- ---------------------------------------------------------------------------
-- 7. crm_contact_methods — I RECAPITI
--
-- §14. Una riga appartiene a UNA PERSONA oppure a UN'ORGANIZZAZIONE, mai a
-- entrambe e mai a nessuna: il check `crm_method_owner_xor` lo impone.
-- `info@rossi.ch` è dell'organizzazione, `laura@rossi.ch` è di Laura — ed è
-- proprio questa distinzione che evita di attribuire a una persona la casella
-- generale dell'azienda.
--
-- ⚠️ `normalized_value` la scrive il guardiano, non il client: è la chiave con
-- cui si riconosce un mittente, e lasciarla scrivere significherebbe permettere
-- di dichiarare che un indirizzo è un altro.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_contact_methods (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,

  contact_id      uuid references public.crm_contacts(id) on delete cascade,
  organization_id uuid references public.crm_organizations(id) on delete cascade,

  type            public.crm_contact_method_type not null,
  value           text not null,
  normalized_value text,
  label           text,
  is_primary      boolean not null default false,

  created_by      uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),

  constraint crm_method_owner_xor
    check ((contact_id is not null) <> (organization_id is not null)),
  constraint crm_method_value_not_blank check (btrim(value) <> '')
);

comment on table public.crm_contact_methods is
  'Email, telefoni e siti di una persona OPPURE di un''organizzazione (mai di '
  'entrambe). normalized_value è scritta dal database ed è la chiave del match '
  'esatto del §22.';


-- ---------------------------------------------------------------------------
-- 8. crm_contact_organizations — DOVE LAVORA, E DOVE LAVORAVA
--
-- §17 e §18. Quando Laura passa da Rossi SA a Bianchi SA non si riscrive il
-- passato: la riga vecchia riceve `active_until` e ne nasce una nuova. Le email
-- di due anni fa restano email scambiate con Rossi SA, perché è quello che sono
-- state.
--
-- Per la versione 1 basta una relazione principale attiva — ed è ciò che l'
-- interfaccia mostra — ma la forma della tabella non impedisce di conservarne
-- la storia, e questa è l'unica cosa che davvero non si può aggiungere dopo.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_contact_organizations (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  contact_id      uuid not null references public.crm_contacts(id) on delete cascade,
  organization_id uuid not null references public.crm_organizations(id) on delete cascade,

  job_title       text,
  department      text,
  is_primary      boolean not null default false,

  active_from     date,
  active_until    date,

  created_by      uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),

  constraint uq_crm_contact_org unique (contact_id, organization_id, active_from),
  constraint crm_contact_org_period
    check (active_until is null or active_from is null or active_until >= active_from)
);

comment on table public.crm_contact_organizations is
  'Chi lavora dove, con la storia: un rapporto finito riceve active_until e '
  'non viene cancellato (§18).';


-- ---------------------------------------------------------------------------
-- 9. crm_opportunities — LE TRATTATIVE
--
-- §40. Una pratica commerciale con una fase, un responsabile, un prossimo passo.
--
-- ⚠️ §44 — NESSUNA PROBABILITÀ. Non c'è una colonna `probability`, e non è una
-- dimenticanza: «Offerta = 50%» ha l'aria di una misura e non deriva da niente.
-- Sommata su venti trattative produce un numero che qualcuno userà per decidere.
-- ⚠️ §47 — nessuna previsione, nessun ponderato, nessun obiettivo raggiunto.
-- ⚠️ §45 — il valore porta la SUA valuta e non si somma con le altre. Il totale
-- di pipeline è per valuta, e lo calcola il database (sezione 21) proprio per
-- non farlo fare a JavaScript in virgola mobile.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_opportunities (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  organization_id uuid not null references public.crm_organizations(id) on delete cascade,
  -- §177 — se c'è, deve essere una persona DI QUELLA organizzazione: il
  -- guardiano lo verifica. Collegare il referente di Rossi SA a una trattativa
  -- con Bianchi SA è l'errore che si fa scegliendo dalla tendina sbagliata, e
  -- sarebbe invisibile.
  primary_contact_id uuid references public.crm_contacts(id) on delete set null,

  title           text not null,
  stage           public.crm_opportunity_stage not null default 'lead',
  owner_user_id   uuid references auth.users(id) on delete set null,

  -- §46 — facoltativo: molte trattative non hanno un valore stimato, e
  -- obbligarlo produrrebbe cifre inventate. `numeric(14,2)` e non `numeric`
  -- nudo come in Finanze: là l'importo è LETTO da un documento e la scala la
  -- decide il documento, qui lo scrive una persona e due decimali sono la
  -- forma giusta di un importo scritto a mano.
  value_amount    numeric(14,2),
  value_currency  text,

  expected_close_date date,

  -- §49 e §50 — la sintesi commerciale, non il lavoro. Il lavoro è un'attività,
  -- e il pulsante «Crea attività dal prossimo passo» le collega senza
  -- duplicarle.
  next_step       text,
  next_step_due_date date,

  lost_reason     text,
  won_at          timestamptz,
  lost_at         timestamptz,

  archived_at     timestamptz,
  archived_by     uuid references auth.users(id) on delete set null,

  workflow_run_id uuid references public.workflow_runs(id) on delete set null,

  created_by      uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  constraint crm_opp_title_not_blank check (btrim(title) <> ''),
  -- §175 — il timbro esiste se e solo se la fase lo prevede. Un `won_at` su una
  -- trattativa in negoziazione sarebbe una data di vittoria mai avvenuta.
  constraint crm_opp_won_stamp check ((stage = 'won') = (won_at is not null)),
  constraint crm_opp_lost_stamp check ((stage = 'lost') = (lost_at is not null)),
  -- §45 — se c'è un importo c'è la valuta. Un numero senza valuta finirebbe
  -- sommato a qualunque cosa: è la finzione tolta dal prodotto il 2026-07-29,
  -- e non si rientra dalla finestra.
  constraint crm_opp_currency_with_amount
    check (value_amount is null or (value_currency is not null and length(value_currency) = 3)),
  constraint crm_opp_amount_not_negative check (value_amount is null or value_amount >= 0)
);

comment on table public.crm_opportunities is
  'Le trattative commerciali. Nessuna probabilità di chiusura e nessuna '
  'previsione (§44, §47): sarebbero numeri decorativi. Il valore porta sempre '
  'la sua valuta e non si somma con le altre (§45).';


-- ---------------------------------------------------------------------------
-- 10. crm_interactions — I CONTATTI CHE NESSUN ALTRO MODULO REGISTRA
--
-- §63. Una telefonata, una visita, una nota.
--
-- ⚠️ §64 — LE EMAIL NON ENTRANO QUI. Restano in `email_messages` e si
-- collegano: copiarle produrrebbe due verità sulla stessa conversazione, e la
-- copia invecchierebbe.
-- ⚠️ §65 — una nota «riunione» dice che una riunione c'è stata. Non è un
-- appuntamento e non parla con il calendario: per fissare qualcosa si crea
-- un'attività con una scadenza, e il calendario arriva da lì.
-- ⚠️ §66 — testo semplice. Nessun HTML, nessuna formattazione: il corpo di
-- queste note viene mostrato come testo e non c'è alcun percorso in cui
-- diventi markup.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_interactions (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  organization_id uuid not null references public.crm_organizations(id) on delete cascade,
  contact_id      uuid references public.crm_contacts(id) on delete set null,
  opportunity_id  uuid references public.crm_opportunities(id) on delete set null,

  type            public.crm_interaction_type not null default 'note',
  occurred_at     timestamptz not null default now(),
  subject         text,
  notes           text,

  created_by      uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  -- §66 — una lunghezza dichiarata invece di un troncamento silenzioso: chi
  -- scrive un romanzo riceve un rifiuto, non una nota tagliata a metà senza
  -- che nessuno glielo dica.
  constraint crm_interaction_subject_len check (subject is null or length(subject) <= 200),
  constraint crm_interaction_notes_len check (notes is null or length(notes) <= 5000)
);

comment on table public.crm_interactions is
  'Note, telefonate e incontri: ciò che è successo e che nessun altro modulo '
  'registra. Le email NON si copiano qui (§64), si collegano.';


-- ---------------------------------------------------------------------------
-- 11. crm_events — LO STORICO
--
-- §85 e §86. Append-only, scritto SOLO da trigger: il client non ha alcun
-- permesso di scrittura, quindi non può firmare un'azione a nome di un collega.
-- È la stessa disciplina di `task_events` e `contract_events`.
--
-- ⚠️ Nel `detail` entrano ID e valori di enum, MAI ragioni sociali o nomi di
-- persone: un jsonb di storico che contenesse i nomi diventerebbe una seconda
-- copia dell'anagrafica, invecchierebbe, e non si potrebbe cancellare quando
-- una persona chiede di essere cancellata.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_events (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,

  organization_id uuid references public.crm_organizations(id) on delete cascade,
  contact_id      uuid references public.crm_contacts(id) on delete cascade,
  opportunity_id  uuid references public.crm_opportunities(id) on delete cascade,

  kind            public.crm_event_kind not null,
  detail          jsonb not null default '{}'::jsonb,

  actor_user_id   uuid references auth.users(id) on delete set null,
  occurred_at     timestamptz not null default now()
);

comment on table public.crm_events is
  'Storico append-only del CRM, scritto solo dai trigger (§86). Nel detail '
  'entrano identificativi e valori di enum, mai nomi: sarebbe una seconda '
  'copia dell''anagrafica.';


-- ---------------------------------------------------------------------------
-- 12. I COLLEGAMENTI — quattro tabelle ponte
--
-- §32 e §33. Non un JSON polimorfico senza chiavi esterne: quattro tabelle con
-- integrità vera, sul modello di `public.contract_documents` (0024) e di
-- `public.email_message_documents` (0013), che sono i due ponti già collaudati
-- del repository.
--
-- ⚠️ PERCHÉ NON UNA COLONNA SULLE TABELLE ESISTENTI:
-- (a) su `email_messages` il client ha `grant update (seen_at, attention_status)`
--     e nient'altro — una colonna nuova là non sarebbe scrivibile dal browser;
-- (b) su `documents` i grant sono di TABELLA dalla 0002, quindi una colonna
--     nuova sarebbe scrivibile da chiunque con qualunque valore;
-- (c) la relazione è molti-a-molti nei fatti: una email può riguardare due
--     controparti, e lo stesso documento può appartenere a più email
--     (deduplicazione per file_hash in createOrReuseDocument).
--
-- ⚠️ `company_id` è RIDONDANTE in tutte e quattro, ed è voluto: permette alla
-- RLS di filtrare senza join e al guardiano di confrontare tre valori invece
-- di dedurne uno.
-- ---------------------------------------------------------------------------

-- §34 — un documento può riguardare più controparti, e con ruoli diversi:
-- il mittente di una fattura e il cliente a cui si riferisce non sono la stessa
-- organizzazione.
create table if not exists public.crm_organization_documents (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  organization_id uuid not null references public.crm_organizations(id) on delete cascade,
  document_id     uuid not null references public.documents(id) on delete cascade,

  relation        public.crm_document_relation not null default 'counterparty',
  -- §77 della 0024, ripreso qui: «l'ha collegato una persona» e «l'ha proposto
  -- il sistema e una persona ha detto sì» sono due storie diverse.
  match_reason    public.crm_match_reason not null default 'manual',
  confirmed_by    uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),

  constraint uq_crm_org_document unique (organization_id, document_id)
);

comment on table public.crm_organization_documents is
  'Quali documenti riguardano questa controparte. Il documento non viene '
  'copiato e la sua analisi non viene toccata (§4 del modulo).';

-- §33 e §73 — l'aggancio si fa sul MESSAGGIO, non sul thread: `provider_thread_id`
-- è un identificativo opaco del provider e non tutte le caselle lo valorizzano.
-- La timeline raggruppa per thread in LETTURA («Conversazione email — 4
-- messaggi»), che è il posto giusto per un raggruppamento: se lo si scrivesse
-- nel dato, collegare un thread collegherebbe anche i messaggi futuri che
-- nessuno ha ancora letto.
create table if not exists public.crm_organization_emails (
  id               uuid primary key default gen_random_uuid(),
  company_id       uuid not null references public.companies(id) on delete cascade,
  organization_id  uuid not null references public.crm_organizations(id) on delete cascade,
  email_message_id uuid not null references public.email_messages(id) on delete cascade,

  match_reason     public.crm_match_reason not null default 'manual',
  confirmed_by     uuid references auth.users(id) on delete set null,
  created_at       timestamptz not null default now(),

  constraint uq_crm_org_email unique (organization_id, email_message_id)
);

comment on table public.crm_organization_emails is
  'Quali comunicazioni riguardano questa controparte. Il corpo della email non '
  'viene mai copiato qui (§61): la timeline mostra oggetto, mittente e data '
  'leggendoli da email_messages.';

-- §33 — la stessa email può essere collegata sia all'organizzazione sia alla
-- persona che l'ha scritta. Due tabelle e non una con due colonne nullable: un
-- vincolo unico su una coppia con un NULL non impedisce i doppioni, perché due
-- NULL non sono uguali fra loro.
create table if not exists public.crm_contact_emails (
  id               uuid primary key default gen_random_uuid(),
  company_id       uuid not null references public.companies(id) on delete cascade,
  contact_id       uuid not null references public.crm_contacts(id) on delete cascade,
  email_message_id uuid not null references public.email_messages(id) on delete cascade,

  match_reason     public.crm_match_reason not null default 'manual',
  confirmed_by     uuid references auth.users(id) on delete set null,
  created_at       timestamptz not null default now(),

  constraint uq_crm_contact_email unique (contact_id, email_message_id)
);

-- §89 — il capitolato, la richiesta d'offerta, la proposta. Un collegamento,
-- non un generatore di offerte: quello non esiste e non è in programma.
create table if not exists public.crm_opportunity_documents (
  id             uuid primary key default gen_random_uuid(),
  company_id     uuid not null references public.companies(id) on delete cascade,
  opportunity_id uuid not null references public.crm_opportunities(id) on delete cascade,
  document_id    uuid not null references public.documents(id) on delete cascade,

  added_by       uuid references auth.users(id) on delete set null,
  created_at     timestamptz not null default now(),

  constraint uq_crm_opportunity_document unique (opportunity_id, document_id)
);


-- ---------------------------------------------------------------------------
-- 13. crm_link_suggestions — CIÒ CHE IL SISTEMA SOSPETTA
--
-- §20 e §21, ed è la tabella che decide se questo CRM sarà usabile.
--
-- Il numero che giustifica questa tabella, misurato sul database vero il
-- 2026-07-29: 117 email, 54 mittenti distinti, 44 domini. Creando
-- un'organizzazione per mittente si otterrebbero 44 anagrafiche fatte in
-- maggioranza di stripe.com, amazon.it, mail.adobe.com, newsletter e noreply.
-- Con il filtro del §20 (non massiva, rilevanza azionabile, mittente non di
-- servizio) i 54 mittenti scendono a 6 — e fra quei 6 restano amazon.it e
-- info.interdiscount.ch. Cioè: NEMMENO IL FILTRO MIGLIORE AUTORIZZA UN'
-- ANAGRAFICA AUTOMATICA. Perciò quelle righe finiscono qui, in attesa di un sì.
--
-- ⚠️ `suggested_name` e `suggested_email` sono una COPIA, e sono l'unica di
-- tutto il file. È voluto: un suggerimento deve poter essere mostrato anche se
-- l'entità d'origine nel frattempo è stata archiviata, e deve poter essere
-- rifiutato senza lasciare tracce dell'entità. È una copia con una scadenza,
-- non una seconda anagrafica.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_link_suggestions (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,

  source_entity_type public.crm_linked_entity not null,
  source_entity_id   uuid not null,

  -- Se il suggerimento è «questa email è di un'organizzazione che conosci già»,
  -- qui c'è quale. Se è «questa sembra una controparte nuova», resta null e
  -- valgono suggested_name / suggested_email.
  suggested_organization_id uuid references public.crm_organizations(id) on delete cascade,
  suggested_contact_id      uuid references public.crm_contacts(id) on delete cascade,

  suggested_name  text,
  suggested_email text,

  reason          public.crm_match_reason not null,
  -- Il perché in chiaro, per la schermata: non un punteggio, una FRASE
  -- verificabile («il dominio del mittente coincide con il sito»). §153 — la
  -- preferenza è per il deterministico, e un numero fra 0 e 1 qui non
  -- misurerebbe niente.
  reason_detail   text,

  status          public.crm_link_status not null default 'pending',
  resolved_at     timestamptz,
  resolved_by     uuid references auth.users(id) on delete set null,
  created_at      timestamptz not null default now(),

  -- Idempotenza: la stessa proposta non si ripresenta a ogni passaggio del
  -- worker. È la chiave che rende ripetibile il candidato del §171.
  dedupe_key      text not null,

  constraint uq_crm_suggestion_dedupe unique (company_id, dedupe_key),
  constraint crm_suggestion_resolved_stamp
    check ((status = 'pending') = (resolved_at is null)),
  constraint crm_suggestion_has_target
    check (suggested_organization_id is not null
           or suggested_contact_id is not null
           or nullif(btrim(coalesce(suggested_name, '')), '') is not null)
);

comment on table public.crm_link_suggestions is
  'Ciò che il sistema sospetta e che una persona deve confermare (§21). '
  'Nessuna organizzazione nasce da qui senza un gesto umano.';


-- ---------------------------------------------------------------------------
-- 14. LE COLONNE DI COLLEGAMENTO SUI MODULI ESISTENTI
--
-- §35, §36, §37. Tre colonne facoltative, annullabili, che NON sostituiscono
-- nulla. §169 — i record esistenti continuano a funzionare senza: un contratto
-- con `counterparty_organization_id = null` è valido e resta valido.
--
-- ⚠️⚠️ LA DIFESA DI QUESTE TRE COLONNE NON PUÒ ESSERE UN GRANT.
-- Su `public.tasks` i grant sono di TABELLA dalla 0004 (`grant select, insert,
-- update, delete … to authenticated`) e nessuna migrazione li ha mai revocati:
-- un `grant (colonna)` scritto oggi AGGIUNGE privilegi, non ne toglie. È la
-- lezione misurata della 0013/0014. L'unica difesa possibile è un TRIGGER, ed è
-- quello che la sezione 16 fa — per tutte e tre, anche dove i grant di colonna
-- funzionerebbero, perché una difesa che vale in un posto solo si dimentica.
-- ---------------------------------------------------------------------------

-- §35 e §81 — un'attività riguarda normalmente UNA controparte principale,
-- quindi una chiave esterna e non una tabella di relazione. La verifica:
-- `list_tasks` elenca le proprie colonne una per una, quindi una colonna nuova
-- non la rompe — è già successo due volte senza toccarla (tasks.workflow_run_id
-- nella 0020, tasks.contract_id nella 0024).
alter table public.tasks
  add column if not exists crm_organization_id uuid references public.crm_organizations(id) on delete set null;
alter table public.tasks
  add column if not exists crm_opportunity_id uuid references public.crm_opportunities(id) on delete set null;

comment on column public.tasks.crm_organization_id is
  'La controparte a cui questa attività si riferisce. Facoltativa: '
  'un''attività interna non ne ha una. Difesa da trg_tasks_crm_guard, non da un '
  'grant — su tasks i grant sono di tabella dalla 0004.';

-- §36 — ACCANTO a counterparty_name, non al suo posto.
-- `contracts.counterparty_name` resta l'etichetta scrivibile a mano,
-- `contract_extractions.counterparty` resta il nome LETTO e immutabile, e
-- `list_contracts` continua a restituire `coalesce(t_counterparty,
-- counterparty_name)`: i termini verificati continuano a vincere. Il CRM
-- aggiunge un riferimento, non cambia ciò che la schermata mostra.
alter table public.contracts
  add column if not exists counterparty_organization_id uuid references public.crm_organizations(id) on delete set null;

comment on column public.contracts.counterparty_organization_id is
  'Collegamento facoltativo alla controparte nel CRM. NON sostituisce '
  'counterparty_name né il nome estratto: scollegare non cancella nulla (§26).';

-- §37 — il fornitore letto sulla fattura resta `eff_supplier_name`.
-- Qui c'è solo «e quel fornitore è questa organizzazione».
alter table public.finance_items
  add column if not exists supplier_organization_id uuid references public.crm_organizations(id) on delete set null;
-- La coppia timbrata dal database, sul modello già presente in questa stessa
-- tabella (`expense_category_set_by` / `expense_category_set_at`): chi ha
-- deciso che quel fornitore è quell'organizzazione, e quando.
alter table public.finance_items
  add column if not exists supplier_organization_set_by uuid references auth.users(id) on delete set null;
alter table public.finance_items
  add column if not exists supplier_organization_set_at timestamptz;

comment on column public.finance_items.supplier_organization_id is
  'Collegamento facoltativo del fornitore al CRM. eff_supplier_name e '
  'finance_extractions.supplier_name restano intatti: il CRM aggiunge '
  'un''identità, non riscrive un fatto (§27).';


-- ---------------------------------------------------------------------------
-- 15. GLI INDICI
--
-- Ognuno serve un'interrogazione che questo modulo fa davvero. §111 chiede di
-- controllare quelli esistenti e di non duplicarli: l'unico indice che manca
-- fuori dal CRM è quello su `email_messages (company_id, sender_email)`, che
-- oggi non esiste — `isKnownAdministrativeSender` fa già quella ricerca senza.
-- ---------------------------------------------------------------------------

-- La lista: per azienda, non archiviate, in ordine di nome.
create index if not exists idx_crm_org_company_name
  on public.crm_organizations (company_id, display_name)
  where archived_at is null;

create index if not exists idx_crm_org_company_updated
  on public.crm_organizations (company_id, updated_at desc);

-- §69 — «nessun contatto da 30 giorni». `nulls first` perché un'organizzazione
-- mai contattata viene PRIMA di una contattata sei mesi fa: è il caso più
-- urgente, non il meno.
create index if not exists idx_crm_org_last_contact
  on public.crm_organizations (company_id, last_contact_at nulls first)
  where archived_at is null;

create index if not exists idx_crm_org_owner
  on public.crm_organizations (company_id, account_owner_user_id)
  where archived_at is null and account_owner_user_id is not null;

-- ⚠️ §29 — L'IDI È UN'IDENTITÀ, e due righe con lo stesso IDI nella stessa
-- azienda sono sempre un duplicato. Su `public.companies` questo vincolo NON
-- esiste e la duplicazione è possibile: il CRM non ripete quella lacuna.
-- L'indice è sulla forma NORMALIZZATA e verificata, quindi «CHE-107.721.785» e
-- «CHE107721785» collidono come devono, mentre un IDI con la cifra di
-- controllo sbagliata (uid_norm = null) non blocca niente — non identifica
-- nessuno, quindi non può impedire un inserimento.
create unique index if not exists uq_crm_org_uid
  on public.crm_organizations (company_id, uid_norm)
  where uid_norm is not null;

-- §23 — il sospetto per dominio, e il §29 per i duplicati.
create index if not exists idx_crm_org_domain
  on public.crm_organizations (company_id, website_domain)
  where website_domain is not null;

-- §103 — la ricerca. Trigram sull'espressione che la funzione di lista
-- interroga davvero: è la trappola annotata su `idx_tasks_search`, dove
-- l'indice è su un'espressione e il filtro su tre colonne separate, e quindi
-- l'indice non serve la ricerca che dice di servire.
create index if not exists idx_crm_org_text_trgm
  on public.crm_organizations
  using gin ((coalesce(display_name, '') || ' ' || coalesce(legal_name, '') || ' ' || coalesce(city, '')) gin_trgm_ops);

create index if not exists idx_crm_org_roles_role
  on public.crm_organization_roles (company_id, role);
create index if not exists idx_crm_org_roles_org
  on public.crm_organization_roles (organization_id);

create index if not exists idx_crm_contacts_company_name
  on public.crm_contacts (company_id, display_name)
  where archived_at is null;
create index if not exists idx_crm_contacts_text_trgm
  on public.crm_contacts
  using gin ((coalesce(display_name, '') || ' ' || coalesce(first_name, '') || ' ' || coalesce(last_name, '')) gin_trgm_ops);

-- §22 — la chiave del match esatto: dato un `sender_email`, chi è.
create index if not exists idx_crm_methods_normalized
  on public.crm_contact_methods (company_id, normalized_value)
  where normalized_value is not null;
create index if not exists idx_crm_methods_contact
  on public.crm_contact_methods (contact_id) where contact_id is not null;
create index if not exists idx_crm_methods_org
  on public.crm_contact_methods (organization_id) where organization_id is not null;

-- §127 — un indirizzo email appartiene a UN solo soggetto dentro l'azienda.
-- Se `info@rossi.ch` è già dell'organizzazione, non può diventare anche di una
-- persona: è la regola che spinge a metterlo dove sta davvero, invece di
-- duplicarlo. Il rifiuto è un 23505, che `toUserMessage` traduce già.
create unique index if not exists uq_crm_method_email
  on public.crm_contact_methods (company_id, normalized_value)
  where type = 'email' and normalized_value is not null;

create index if not exists idx_crm_contact_orgs_org
  on public.crm_contact_organizations (organization_id)
  where active_until is null;
create index if not exists idx_crm_contact_orgs_contact
  on public.crm_contact_organizations (contact_id);

-- §17 — un solo rapporto PRINCIPALE attivo per persona. Il vincolo è parziale
-- perché un rapporto concluso può benissimo essere stato il principale a suo
-- tempo, e riscrivere quel flag sarebbe riscrivere la storia.
create unique index if not exists uq_crm_contact_primary_org
  on public.crm_contact_organizations (contact_id)
  where is_primary and active_until is null;

create index if not exists idx_crm_opp_company_stage
  on public.crm_opportunities (company_id, stage)
  where archived_at is null;
create index if not exists idx_crm_opp_org
  on public.crm_opportunities (organization_id)
  where archived_at is null;
create index if not exists idx_crm_opp_owner
  on public.crm_opportunities (company_id, owner_user_id)
  where archived_at is null;
-- §100 — «follow-up scaduti» e «senza prossimo passo» sono due delle quattro
-- misure della pagina iniziale, e sono interrogazioni, non conteggi in memoria.
create index if not exists idx_crm_opp_next_step_due
  on public.crm_opportunities (company_id, next_step_due_date)
  where archived_at is null and next_step_due_date is not null
        and stage not in ('won', 'lost');

create index if not exists idx_crm_interactions_org
  on public.crm_interactions (organization_id, occurred_at desc);
create index if not exists idx_crm_interactions_contact
  on public.crm_interactions (contact_id, occurred_at desc)
  where contact_id is not null;

-- §109 — la timeline si pagina con `occurred_at desc, id desc`: l'indice porta
-- entrambe le colonne, altrimenti la seconda chiave d'ordine costerebbe un
-- ordinamento in memoria proprio sulla query che deve restare leggera.
create index if not exists idx_crm_events_org
  on public.crm_events (organization_id, occurred_at desc, id desc)
  where organization_id is not null;
create index if not exists idx_crm_events_opp
  on public.crm_events (opportunity_id, occurred_at desc, id desc)
  where opportunity_id is not null;

create index if not exists idx_crm_org_docs_org
  on public.crm_organization_documents (organization_id);
create index if not exists idx_crm_org_docs_doc
  on public.crm_organization_documents (document_id);
create index if not exists idx_crm_org_emails_org
  on public.crm_organization_emails (organization_id);
create index if not exists idx_crm_org_emails_msg
  on public.crm_organization_emails (email_message_id);
create index if not exists idx_crm_contact_emails_contact
  on public.crm_contact_emails (contact_id);
create index if not exists idx_crm_opp_docs_opp
  on public.crm_opportunity_documents (opportunity_id);

create index if not exists idx_crm_suggestions_pending
  on public.crm_link_suggestions (company_id, created_at desc)
  where status = 'pending';
create index if not exists idx_crm_suggestions_source
  on public.crm_link_suggestions (company_id, source_entity_type, source_entity_id);

-- I collegamenti sui moduli esistenti: parziali, perché la stragrande
-- maggioranza delle righe non li userà mai.
create index if not exists idx_tasks_crm_org
  on public.tasks (crm_organization_id) where crm_organization_id is not null;
create index if not exists idx_tasks_crm_opp
  on public.tasks (crm_opportunity_id) where crm_opportunity_id is not null;
create index if not exists idx_contracts_crm_org
  on public.contracts (counterparty_organization_id) where counterparty_organization_id is not null;
create index if not exists idx_finance_items_crm_org
  on public.finance_items (company_id, supplier_organization_id) where supplier_organization_id is not null;

-- §22 — l'indice che MANCAVA fuori dal CRM. `isKnownAdministrativeSender`
-- (_shared/email/store.ts) fa già `eq(company_id) + eq(sender_email)` senza
-- indice dedicato; il CRM aggiunge un secondo chiamante su una tabella che oggi
-- ha 117 righe ma che cresce a ogni sincronizzazione.
create index if not exists idx_email_msg_sender
  on public.email_messages (company_id, sender_email)
  where sender_email is not null;


-- ---------------------------------------------------------------------------
-- 16. I GUARDIANI
--
-- §39, §86, §115, §174, §176, §177. Qui vive tutto ciò che il browser non deve
-- poter decidere: chi è l'autore, a quale azienda appartiene ciò che si
-- collega, quando si scrivono i timbri.
--
-- ⚠️ PERCHÉ NON BASTA LA RLS, e vale per ognuna delle funzioni che seguono.
-- La RLS impedisce di scrivere una riga che DICHIARA un'azienda altrui. Non
-- impedisce di dichiarare la PROPRIA azienda e agganciare l'entità di un'altra:
-- quel caso passa la policy e va fermato qui. È la disciplina imparata con la
-- 0017, dove una policy scritta altrove non bastava a proteggere un trigger che
-- la scavalca — e queste funzioni sono `security definer`, quindi devono
-- difendersi da sole.
--
-- ⚠️ IL SENTINELLA `ai_swisse.crm_internal`.
-- Due colonne — `last_contact_at` e `merged_into_id` — non appartengono a
-- nessuno se non al database: la prima la calcola `crm_refresh_last_contact`, la
-- seconda la scrive `crm_merge_organizations`. Il guardiano le ripristina da
-- `old` SEMPRE, tranne quando quel parametro di sessione è acceso. Così restano
-- inattaccabili anche se un giorno qualcuno aggiungesse un grant per sbaglio:
-- la difesa non dipende dai permessi. È la forma di `ai_swisse.contract_review`
-- della 0024, che il suo autore chiama «il difetto peggiore di quel modulo,
-- evitato per un soffio».
-- ---------------------------------------------------------------------------

create or replace function public.crm_organizations_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_merge_company uuid;
begin
  -- §11 e §176 — il responsabile della relazione deve essere della stessa
  -- azienda. Non è una formalità: l'elenco «i miei clienti» si costruisce su
  -- questa colonna, e un id estraneo produrrebbe una riga che non appartiene a
  -- nessuno e che nessuno vede.
  if new.account_owner_user_id is not null
     and (tg_op = 'INSERT' or new.account_owner_user_id is distinct from old.account_owner_user_id) then
    if not exists (select 1 from public.company_members m
                    where m.company_id = new.company_id
                      and m.user_id = new.account_owner_user_id) then
      raise exception 'crm_owner_not_member'
        using errcode = '23514',
              hint = 'Il responsabile deve essere un membro di questa azienda.';
    end if;
  end if;

  -- Le forme canoniche le calcola il database, sempre, da ciò che è stato
  -- scritto. Se le calcolasse il client, un dominio dichiarato diverso dal sito
  -- renderebbe il suggerimento del §23 una bugia con l'aria di un calcolo.
  new.uid_norm       := public.crm_norm_uid(new.uid_che);
  new.website_domain := public.crm_norm_domain(new.website);
  new.canton         := nullif(upper(btrim(coalesce(new.canton, ''))), '');
  new.country_code   := nullif(upper(btrim(coalesce(new.country_code, ''))), '');
  new.display_name   := btrim(new.display_name);
  new.legal_name     := nullif(btrim(coalesce(new.legal_name, '')), '');

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
    new.updated_at := now();
    new.last_contact_at := null;   -- non esiste un contatto prima della riga
    new.merged_into_id  := null;
    new.archived_by := null;
    if new.archived_at is not null then new.archived_at := now(); end if;
    -- §19 e §96 — la provenienza la dichiara chi inserisce, ma dal browser si
    -- possono dichiarare solo le provenienze che un browser può davvero avere:
    -- l'ha scritta una persona, l'ha importata dal registro, è arrivata da un
    -- file. «Nata da una email» o «da una fattura» le può affermare solo il
    -- codice server-side, che quelle cose le ha davvero viste — altrimenti una
    -- riga scritta a mano potrebbe presentarsi come dedotta da un documento.
    if auth.uid() is not null and pg_trigger_depth() <= 1
       and new.source not in ('manual', 'registry', 'import') then
      new.source := 'manual';
    end if;
    return new;
  end if;

  -- UPDATE — ciò che non cambia mai.
  new.company_id := old.company_id;
  new.created_by := old.created_by;
  new.created_at := old.created_at;
  new.source     := old.source;   -- da dove è arrivata è un fatto, non un'opinione
  new.updated_at := now();

  -- §124 — archiviare e ripristinare, con il timbro scritto dal database.
  if new.archived_at is not null and old.archived_at is null then
    new.archived_at := now();
    new.archived_by := auth.uid();
  elsif new.archived_at is null then
    new.archived_by := null;
  else
    new.archived_at := old.archived_at;
    new.archived_by := old.archived_by;
  end if;

  -- Le due colonne del database. Vedi il sentinella in testa alla sezione.
  if coalesce(current_setting('ai_swisse.crm_internal', true), '') <> 'on' then
    new.last_contact_at := old.last_contact_at;
    new.merged_into_id  := old.merged_into_id;
  end if;

  if new.merged_into_id is not null then
    if new.merged_into_id = new.id then
      raise exception 'crm_merge_into_self'
        using errcode = '23514', hint = 'Un''organizzazione non si fonde con sé stessa.';
    end if;
    select o.company_id into v_merge_company
      from public.crm_organizations o where o.id = new.merged_into_id;
    if v_merge_company is null or v_merge_company is distinct from new.company_id then
      raise exception 'crm_merge_company_mismatch'
        using errcode = '23514',
              hint = 'Le due organizzazioni devono appartenere alla stessa azienda.';
    end if;
  end if;

  return new;
end $$;

drop trigger if exists trg_crm_organizations_guard on public.crm_organizations;
create trigger trg_crm_organizations_guard
  before insert or update on public.crm_organizations
  for each row execute function public.crm_organizations_guard();


-- Il ruolo appartiene all'organizzazione, e l'organizzazione all'azienda: tre
-- valori che devono coincidere, non due.
create or replace function public.crm_org_child_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org_company uuid;
begin
  select o.company_id into v_org_company
    from public.crm_organizations o where o.id = new.organization_id;
  if v_org_company is null or v_org_company is distinct from new.company_id then
    raise exception 'crm_organization_company_mismatch'
      using errcode = '23514',
            hint = 'L''organizzazione deve appartenere alla stessa azienda.';
  end if;
  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
  end if;
  return new;
end $$;

drop trigger if exists trg_crm_org_roles_guard on public.crm_organization_roles;
create trigger trg_crm_org_roles_guard
  before insert or update on public.crm_organization_roles
  for each row execute function public.crm_org_child_guard();


create or replace function public.crm_contacts_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.display_name := btrim(new.display_name);
  new.first_name := nullif(btrim(coalesce(new.first_name, '')), '');
  new.last_name  := nullif(btrim(coalesce(new.last_name, '')), '');

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
    new.updated_at := now();
    new.archived_by := null;
    if new.archived_at is not null then new.archived_at := now(); end if;
    return new;
  end if;

  new.company_id := old.company_id;
  new.created_by := old.created_by;
  new.created_at := old.created_at;
  new.updated_at := now();

  if new.archived_at is not null and old.archived_at is null then
    new.archived_at := now();
    new.archived_by := auth.uid();
  elsif new.archived_at is null then
    new.archived_by := null;
  else
    new.archived_at := old.archived_at;
    new.archived_by := old.archived_by;
  end if;

  return new;
end $$;

drop trigger if exists trg_crm_contacts_guard on public.crm_contacts;
create trigger trg_crm_contacts_guard
  before insert or update on public.crm_contacts
  for each row execute function public.crm_contacts_guard();


-- §14 e §15. Il recapito appartiene a una persona OPPURE a un'organizzazione, e
-- quel soggetto deve essere della stessa azienda. `normalized_value` la scrive
-- il database: è la chiave con cui si riconosce un mittente, e permettere di
-- scriverla significherebbe permettere di dichiarare che un indirizzo è un altro.
create or replace function public.crm_contact_methods_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_owner_company uuid;
begin
  if new.contact_id is not null then
    select c.company_id into v_owner_company
      from public.crm_contacts c where c.id = new.contact_id;
  else
    select o.company_id into v_owner_company
      from public.crm_organizations o where o.id = new.organization_id;
  end if;

  if v_owner_company is null or v_owner_company is distinct from new.company_id then
    raise exception 'crm_method_company_mismatch'
      using errcode = '23514',
            hint = 'Il recapito e il suo intestatario devono appartenere alla stessa azienda.';
  end if;

  new.value := btrim(new.value);
  new.normalized_value := case new.type
    when 'email' then public.crm_norm_email(new.value)
    when 'phone' then public.crm_norm_phone(new.value)
    when 'mobile' then public.crm_norm_phone(new.value)
    when 'website' then public.crm_norm_domain(new.value)
    else public.crm_norm_email(new.value)
  end;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
  else
    new.company_id := old.company_id;
    new.created_by := old.created_by;
    new.created_at := old.created_at;
    -- L'intestatario di un recapito non cambia con un update… tranne durante
    -- una fusione, che è l'unico gesto legittimo che sposta le righe da
    -- un'organizzazione a un'altra. Vedi il sentinella della sezione 16.
    if coalesce(current_setting('ai_swisse.crm_internal', true), '') <> 'on' then
      new.contact_id := old.contact_id;
      new.organization_id := old.organization_id;
    end if;
  end if;

  return new;
end $$;

drop trigger if exists trg_crm_contact_methods_guard on public.crm_contact_methods;
create trigger trg_crm_contact_methods_guard
  before insert or update on public.crm_contact_methods
  for each row execute function public.crm_contact_methods_guard();


-- Un solo recapito principale per tipo e per intestatario. Si toglie il flag
-- agli altri invece di rifiutare: chi dice «questo è il principale» sta
-- affermando qualcosa di completo, non chiedendo un permesso.
create or replace function public.crm_contact_methods_primary()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not new.is_primary then return new; end if;

  update public.crm_contact_methods m
     set is_primary = false
   where m.id <> new.id
     and m.type = new.type
     and m.is_primary
     and ((new.contact_id is not null and m.contact_id = new.contact_id)
       or (new.organization_id is not null and m.organization_id = new.organization_id));

  return new;
end $$;

drop trigger if exists trg_crm_contact_methods_primary on public.crm_contact_methods;
create trigger trg_crm_contact_methods_primary
  after insert or update of is_primary on public.crm_contact_methods
  for each row execute function public.crm_contact_methods_primary();


-- §17 — la persona e l'organizzazione, entrambe della stessa azienda.
create or replace function public.crm_contact_organizations_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_contact_company uuid;
  v_org_company     uuid;
begin
  select c.company_id into v_contact_company
    from public.crm_contacts c where c.id = new.contact_id;
  select o.company_id into v_org_company
    from public.crm_organizations o where o.id = new.organization_id;

  if v_contact_company is null or v_org_company is null
     or v_contact_company is distinct from new.company_id
     or v_org_company is distinct from new.company_id then
    raise exception 'crm_contact_org_company_mismatch'
      using errcode = '23514',
            hint = 'La persona e l''organizzazione devono appartenere alla stessa azienda.';
  end if;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
  else
    new.company_id := old.company_id;
    new.contact_id := old.contact_id;
    new.created_by := old.created_by;
    new.created_at := old.created_at;
    if coalesce(current_setting('ai_swisse.crm_internal', true), '') <> 'on' then
      new.organization_id := old.organization_id;
    end if;
  end if;

  return new;
end $$;

drop trigger if exists trg_crm_contact_orgs_guard on public.crm_contact_organizations;
create trigger trg_crm_contact_orgs_guard
  before insert or update on public.crm_contact_organizations
  for each row execute function public.crm_contact_organizations_guard();


-- §48, §175, §177. Il guardiano più denso del file: qui vivono la validazione
-- del responsabile, quella del referente e i due timbri di vittoria e perdita.
create or replace function public.crm_opportunities_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org_company     uuid;
  v_contact_company uuid;
  v_contact_linked  boolean;
begin
  select o.company_id into v_org_company
    from public.crm_organizations o where o.id = new.organization_id;
  if v_org_company is null or v_org_company is distinct from new.company_id then
    raise exception 'crm_opportunity_company_mismatch'
      using errcode = '23514',
            hint = 'L''opportunità e l''organizzazione devono appartenere alla stessa azienda.';
  end if;

  -- §48 — il responsabile della trattativa è un membro dell'azienda.
  if new.owner_user_id is not null
     and (tg_op = 'INSERT' or new.owner_user_id is distinct from old.owner_user_id) then
    if not exists (select 1 from public.company_members m
                    where m.company_id = new.company_id and m.user_id = new.owner_user_id) then
      raise exception 'crm_opportunity_owner_not_member'
        using errcode = '23514',
              hint = 'Il responsabile deve essere un membro di questa azienda.';
    end if;
  end if;

  -- §177 — il referente principale deve essere una persona DI QUELLA
  -- organizzazione. È l'errore che si fa scegliendo dalla tendina sbagliata, e
  -- sarebbe invisibile: la scheda mostrerebbe il nome di Laura sotto una
  -- trattativa con un'altra impresa, e nessuno lo noterebbe finché non le si
  -- scrive.
  if new.primary_contact_id is not null
     and (tg_op = 'INSERT' or new.primary_contact_id is distinct from old.primary_contact_id) then
    select c.company_id into v_contact_company
      from public.crm_contacts c where c.id = new.primary_contact_id;
    if v_contact_company is null or v_contact_company is distinct from new.company_id then
      raise exception 'crm_opportunity_contact_company_mismatch'
        using errcode = '23514',
              hint = 'La persona di contatto deve appartenere alla stessa azienda.';
    end if;
    select exists (
      select 1 from public.crm_contact_organizations co
       where co.contact_id = new.primary_contact_id
         and co.organization_id = new.organization_id
    ) into v_contact_linked;
    if not v_contact_linked then
      raise exception 'crm_opportunity_contact_not_in_organization'
        using errcode = '23514',
              hint = 'La persona di contatto non lavora per questa organizzazione.';
    end if;
  end if;

  new.title := btrim(new.title);
  new.value_currency := nullif(upper(btrim(coalesce(new.value_currency, ''))), '');

  -- §175 — i due timbri. La fase la decide una persona; la data la scrive il
  -- database. Riaprire una trattativa vinta azzera il timbro ma NON cancella lo
  -- storico: il passaggio resta scritto in crm_events, che è append-only.
  if new.stage = 'won' then
    if tg_op = 'INSERT' or old.stage is distinct from 'won' then
      new.won_at := now();
    else
      new.won_at := old.won_at;
    end if;
  else
    new.won_at := null;
  end if;

  if new.stage = 'lost' then
    if tg_op = 'INSERT' or old.stage is distinct from 'lost' then
      new.lost_at := now();
    else
      new.lost_at := old.lost_at;
    end if;
  else
    new.lost_at := null;
    -- §43 — il motivo appartiene alla perdita. Riaprendo, resta senza oggetto.
    new.lost_reason := null;
  end if;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
    new.updated_at := now();
    new.archived_by := null;
    if new.archived_at is not null then new.archived_at := now(); end if;
    return new;
  end if;

  new.company_id      := old.company_id;
  new.created_by      := old.created_by;
  new.created_at      := old.created_at;
  new.updated_at      := now();
  -- L'organizzazione non cambia con un update… tranne durante una fusione,
  -- che è l'unico gesto legittimo che sposta righe fra due anagrafiche.
  if coalesce(current_setting('ai_swisse.crm_internal', true), '') <> 'on' then
    new.organization_id := old.organization_id;
  end if;

  if new.archived_at is not null and old.archived_at is null then
    new.archived_at := now();
    new.archived_by := auth.uid();
  elsif new.archived_at is null then
    new.archived_by := null;
  else
    new.archived_at := old.archived_at;
    new.archived_by := old.archived_by;
  end if;

  return new;
end $$;

drop trigger if exists trg_crm_opportunities_guard on public.crm_opportunities;
create trigger trg_crm_opportunities_guard
  before insert or update on public.crm_opportunities
  for each row execute function public.crm_opportunities_guard();


-- §63 — l'autore di un'interazione è chi scrive, e il database non si fida
-- della firma che arriva dal browser. È la stessa correzione della 0016 sui
-- commenti delle attività, dove il trigger RISCRIVEVA in silenzio l'autore e
-- chi provava a firmare come un collega riceveva «inserito»: qui si RIFIUTA.
create or replace function public.crm_interactions_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org_company     uuid;
  v_contact_company uuid;
  v_opp_org         uuid;
begin
  select o.company_id into v_org_company
    from public.crm_organizations o where o.id = new.organization_id;
  if v_org_company is null or v_org_company is distinct from new.company_id then
    raise exception 'crm_interaction_company_mismatch'
      using errcode = '23514',
            hint = 'L''interazione e l''organizzazione devono appartenere alla stessa azienda.';
  end if;

  if new.contact_id is not null then
    select c.company_id into v_contact_company
      from public.crm_contacts c where c.id = new.contact_id;
    if v_contact_company is null or v_contact_company is distinct from new.company_id then
      raise exception 'crm_interaction_contact_company_mismatch'
        using errcode = '23514',
              hint = 'La persona deve appartenere alla stessa azienda.';
    end if;
  end if;

  if new.opportunity_id is not null then
    select p.organization_id into v_opp_org
      from public.crm_opportunities p
     where p.id = new.opportunity_id and p.company_id = new.company_id;
    if v_opp_org is null then
      raise exception 'crm_interaction_opportunity_company_mismatch'
        using errcode = '23514',
              hint = 'L''opportunità deve appartenere alla stessa azienda.';
    end if;
    if v_opp_org is distinct from new.organization_id then
      raise exception 'crm_interaction_opportunity_organization_mismatch'
        using errcode = '23514',
              hint = 'L''opportunità appartiene a un''altra organizzazione.';
    end if;
  end if;

  new.subject := nullif(btrim(coalesce(new.subject, '')), '');
  new.notes   := nullif(btrim(coalesce(new.notes, '')), '');

  if tg_op = 'INSERT' then
    if auth.uid() is not null and new.created_by is not null and new.created_by <> auth.uid() then
      raise exception 'crm_interaction_author_mismatch'
        using errcode = '23514',
              hint = 'L''autore di un''interazione è chi la registra.';
    end if;
    new.created_by := coalesce(auth.uid(), new.created_by);
    new.created_at := now();
    new.updated_at := now();
    return new;
  end if;

  new.company_id      := old.company_id;
  new.created_by      := old.created_by;
  new.created_at      := old.created_at;
  new.updated_at      := now();
  -- L'organizzazione non cambia con un update… tranne durante una fusione,
  -- che è l'unico gesto legittimo che sposta righe fra due anagrafiche.
  if coalesce(current_setting('ai_swisse.crm_internal', true), '') <> 'on' then
    new.organization_id := old.organization_id;
  end if;
  return new;
end $$;

drop trigger if exists trg_crm_interactions_guard on public.crm_interactions;
create trigger trg_crm_interactions_guard
  before insert or update on public.crm_interactions
  for each row execute function public.crm_interactions_guard();


-- ---------------------------------------------------------------------------
-- 16-bis. I GUARDIANI DEI COLLEGAMENTI
--
-- §39 e §115 — la regola che vale per tutti: TRE company_id devono coincidere,
-- quello dichiarato nella riga di collegamento, quello dell'entità CRM e quello
-- dell'entità collegata. Confrontarne due su tre lascia aperto proprio il caso
-- che si vuole chiudere.
-- ---------------------------------------------------------------------------

create or replace function public.crm_org_document_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org_company uuid;
  v_doc_company uuid;
begin
  select o.company_id into v_org_company from public.crm_organizations o where o.id = new.organization_id;
  select d.company_id into v_doc_company from public.documents d where d.id = new.document_id;

  if v_org_company is null or v_doc_company is null
     or v_org_company is distinct from v_doc_company
     or v_org_company is distinct from new.company_id then
    raise exception 'crm_document_company_mismatch'
      using errcode = '23514',
            hint = 'Il documento e l''organizzazione devono appartenere alla stessa azienda.';
  end if;

  if tg_op = 'INSERT' then
    new.confirmed_by := auth.uid();
    new.created_at := now();
    -- Dal browser un collegamento è sempre un gesto: solo il codice
    -- server-side può dichiarare un altro motivo.
    if auth.uid() is not null and pg_trigger_depth() <= 1 then
      new.match_reason := 'manual';
    end if;
  else
    new.company_id := old.company_id;
    new.document_id := old.document_id;
    if coalesce(current_setting('ai_swisse.crm_internal', true), '') <> 'on' then
      new.organization_id := old.organization_id;
    end if;
    new.confirmed_by := old.confirmed_by;
    new.created_at := old.created_at;
  end if;
  return new;
end $$;

drop trigger if exists trg_crm_org_document_guard on public.crm_organization_documents;
create trigger trg_crm_org_document_guard
  before insert or update on public.crm_organization_documents
  for each row execute function public.crm_org_document_guard();


