-- ---------------------------------------------------------------------------
-- 42. I PERMESSI
--
-- ⚠️⚠️ PRIMA IL `REVOKE`, POI I `GRANT`. Su Supabase ogni tabella nuova di
--    `public` nasce con i permessi di TABELLA completi per `authenticated`
--    (`alter default privileges … grant all`), quindi un `grant select (…)`
--    scritto da solo AGGIUNGE privilegi invece di toglierne. È il difetto più
--    serio mai trovato in questo progetto (0013 → 0014), e la sezione 43 lo
--    verifica interrogando `information_schema`.
-- ---------------------------------------------------------------------------
revoke all on public.subsidy_sources                 from anon, authenticated, public;
revoke all on public.subsidy_source_fetches          from anon, authenticated, public;
revoke all on public.subsidy_source_snapshots        from anon, authenticated, public;
revoke all on public.subsidy_program_versions        from anon, authenticated, public;
revoke all on public.subsidy_program_rules           from anon, authenticated, public;
revoke all on public.subsidy_calls                   from anon, authenticated, public;
revoke all on public.subsidy_catalog_reviews         from anon, authenticated, public;
revoke all on public.subsidy_projects                from anon, authenticated, public;
revoke all on public.subsidy_project_documents       from anon, authenticated, public;
revoke all on public.subsidy_project_partners        from anon, authenticated, public;
revoke all on public.subsidy_project_interpretations from anon, authenticated, public;
revoke all on public.subsidy_answers                 from anon, authenticated, public;
revoke all on public.subsidy_opportunities           from anon, authenticated, public;
revoke all on public.subsidy_assessments             from anon, authenticated, public;
revoke all on public.subsidy_criterion_results       from anon, authenticated, public;
revoke all on public.subsidy_case_documents          from anon, authenticated, public;
revoke all on public.subsidy_case_events             from anon, authenticated, public;
-- ⚠️ Le tre tabelle della 0003 avevano `grant select, insert, update, delete`
--    di TABELLA. Si rifà tutto: `subsidy_matches` diventa sola lettura (§165),
--    e su pratiche e checklist si passa ai permessi di COLONNA, perché adesso
--    ci sono colonne che deve timbrare il database.
revoke all on public.subsidy_matches    from anon, authenticated, public;
revoke all on public.subsidy_cases      from anon, authenticated, public;
revoke all on public.subsidy_case_items from anon, authenticated, public;

-- ⚠️⚠️ E `subsidy_programs`, CHE ERA SCRIVIBILE DAL 25 LUGLIO.
--
-- La 0007 scriveva `grant select on subsidy_programs to authenticated` senza
-- alcun `revoke` che lo precedesse, quindi quel grant AGGIUNGEVA una lettura a
-- privilegi di tabella che Supabase aveva già concesso per intero: al
-- 2026-07-30 `information_schema.table_privileges` mostrava INSERT, UPDATE e
-- DELETE su `subsidy_programs` sia per `anon` sia per `authenticated`.
--
-- ⚠️ NON ERA UNA FUGA SFRUTTABILE: la tabella ha una sola policy, `for select`,
--    e senza policy di scrittura la RLS respingeva comunque ogni tentativo. Ma
--    il permesso c'era, e sarebbe bastata una policy aggiunta in futuro «per
--    comodità» perché un cliente potesse riscrivere i requisiti che il prodotto
--    presenta a tutti gli altri.
--
-- È ESATTAMENTE IL DIFETTO DELLA 0013, chiuso dalla 0014, ripetuto su una
-- tabella che nessuno aveva ricontrollato. L'ha trovato l'autoverifica di
-- QUESTO file al primo tentativo di applicazione: la migrazione si è rifiutata
-- di applicarsi, come la 0026 davanti alla propria contraddizione interna.
revoke all on public.subsidy_programs   from anon, authenticated, public;
grant select on public.subsidy_programs to authenticated;

-- ---- Catalogo: SOLA LETTURA per il client (§28, §143) ----
grant select on public.subsidy_sources          to authenticated;
grant select on public.subsidy_source_snapshots to authenticated;
grant select on public.subsidy_program_versions to authenticated;
grant select on public.subsidy_program_rules    to authenticated;
grant select on public.subsidy_calls            to authenticated;
-- ⚠️ NIENTE su `subsidy_source_fetches` e `subsidy_catalog_reviews`, nemmeno la
--    lettura: vedi la nota nella sezione 41.

-- ---- Progetti ----
grant select on public.subsidy_projects to authenticated;
grant insert (company_id, title, description, stage, owner_user_id, location_canton,
              location_country, sector, estimated_start_date, estimated_end_date,
              budget_amount, budget_currency, employee_impact, has_research_partner,
              has_innovation_partner, has_international_partners, project_types, goals, status)
  on public.subsidy_projects to authenticated;
grant update (title, description, stage, owner_user_id, location_canton, location_country,
              sector, estimated_start_date, estimated_end_date, budget_amount, budget_currency,
              employee_impact, has_research_partner, has_innovation_partner,
              has_international_partners, project_types, goals, status)
  on public.subsidy_projects to authenticated;
-- ⚠️ NESSUN `delete`: un progetto si ARCHIVIA. Cancellarlo porterebbe via con
--    sé opportunità, valutazioni e — a cascata — il collegamento delle pratiche
--    che ne sono nate. È la stessa scelta di documenti, attività, contratti e
--    controparti.

grant select, insert, delete on public.subsidy_project_documents to authenticated;
grant select, insert, delete on public.subsidy_project_partners  to authenticated;

-- Le interpretazioni le scrive la Edge Function con il ruolo di servizio: sono
-- il risultato di una chiamata al modello, e un client che potesse inserirle
-- scriverebbe un'interpretazione che nessun modello ha prodotto.
grant select on public.subsidy_project_interpretations to authenticated;

-- Le risposte: si inseriscono, non si modificano (append-only).
grant select on public.subsidy_answers to authenticated;
grant insert (company_id, project_id, program_version_id, rule_key, value, note)
  on public.subsidy_answers to authenticated;

-- ---- Opportunità: il client può fare TRE cose ----
-- ⚠️ Salvare, mettere da parte, riaprire. Le sei misure, i conteggi e la
--    valutazione corrente le scrive il MOTORE: un'opportunità la cui rilevanza
--    si può cambiare dal browser non è una valutazione, è un'opinione.
grant select on public.subsidy_opportunities to authenticated;
grant update (saved_at, dismissed_reason, dismissed_note) on public.subsidy_opportunities to authenticated;

grant select on public.subsidy_assessments       to authenticated;
grant select on public.subsidy_criterion_results to authenticated;

-- ---- Pratiche ----
grant select on public.subsidy_cases to authenticated;
grant insert (company_id, created_by, opportunity_id, project_id, program_id, program_name,
              authority, program_version_id, call_id, owner_user_id, status,
              official_deadline, official_deadline_at, internal_deadline,
              amount_requested, currency, program_snapshot, snapshot_hash,
              eligibility_status_at_creation, relevance_score, source_last_checked_at,
              eligibility_snapshot)
  on public.subsidy_cases to authenticated;
grant update (status, owner_user_id, internal_deadline, amount_requested, amount_awarded,
              currency, decision_at, outcome, outcome_document_id, archived_at, archived_by,
              source_changed_at)
  on public.subsidy_cases to authenticated;
-- ⚠️ NESSUN `delete` e NESSUN update su `program_snapshot`/`snapshot_hash`:
--    l'istantanea è tutto il valore della pratica (§109, §188).

grant select on public.subsidy_case_items to authenticated;
grant insert (subsidy_case_id, title, completed, sort_order, kind, document_id, task_id,
              due_date, required, source_requirement_key)
  on public.subsidy_case_items to authenticated;
grant update (title, completed, sort_order, kind, document_id, task_id, due_date, required)
  on public.subsidy_case_items to authenticated;
grant delete on public.subsidy_case_items to authenticated;

grant select on public.subsidy_case_documents to authenticated;
grant insert (company_id, subsidy_case_id, document_id, requirement_key, relation_type, status)
  on public.subsidy_case_documents to authenticated;
grant update (requirement_key, relation_type, status) on public.subsidy_case_documents to authenticated;
grant delete on public.subsidy_case_documents to authenticated;

-- ⚠️ Solo lettura: lo storico lo scrivono i trigger.
grant select on public.subsidy_case_events    to authenticated;

-- ---- Legacy: sola lettura ----
grant select on public.subsidy_matches to authenticated;

-- ---- Le funzioni ----
revoke all on function public.list_subsidy_opportunities(uuid, uuid, text, integer, integer) from public, anon;
grant execute on function public.list_subsidy_opportunities(uuid, uuid, text, integer, integer) to authenticated;

revoke all on function public.subsidy_assessment_criteria(uuid) from public, anon;
grant execute on function public.subsidy_assessment_criteria(uuid) to authenticated;

revoke all on function public.list_subsidy_projects(uuid, boolean) from public, anon;
grant execute on function public.list_subsidy_projects(uuid, boolean) to authenticated;

revoke all on function public.list_subsidy_cases(uuid, boolean) from public, anon;
grant execute on function public.list_subsidy_cases(uuid, boolean) to authenticated;

revoke all on function public.subsidy_home_summary(uuid, integer) from public, anon;
grant execute on function public.subsidy_home_summary(uuid, integer) to authenticated;

-- ⚠️ NON concesse ad `authenticated`, e non è una dimenticanza: emettono eventi
--    di automazione e leggono l'intero catalogo scavalcando la RLS. È la stessa
--    ragione per cui `automation_emit` e `crm_emit_follow_up_due` sono revocate,
--    ed è la lezione della 0029 — dove `assistant_purge_expired`, revocata a
--    `public` ma non ad `authenticated`, restava invocabile da chiunque.
revoke all on function public.subsidy_emit_deadline_approaching(integer, integer) from public, anon, authenticated;
revoke all on function public.subsidy_emit_stale_assessments(integer)              from public, anon, authenticated;
revoke all on function public.subsidy_emit_source_critical_change(integer)         from public, anon, authenticated;
revoke all on function public.subsidy_sources_due(integer)                         from public, anon, authenticated;
revoke all on function public.subsidy_refresh_readiness(uuid)                      from public, anon, authenticated;


-- ---------------------------------------------------------------------------
-- 43. AUTOVERIFICA
--
-- Il file non si limita a dichiarare le proprie garanzie: le prova, e se non
-- tornano l'applicazione FALLISCE invece di riuscire a metà. È la disciplina
-- della 0014, della 0024 e della 0026 — e la 0026 ha guadagnato il proprio
-- costo prima ancora di arrivare in produzione, rifiutandosi di applicarsi su
-- una contraddizione interna.
--
-- ⚠️⚠️ QUESTO BLOCCO NON NOMINA NESSUNA DELLE SEDICI ETICHETTE AGGIUNTE AGLI
--    ENUM ESISTENTI NELLA SEZIONE 1 — nemmeno dentro un commento, perché il
--    controllo che sorveglia questa promessa cerca il letterale fra apici e non
--    distingue un commento da un'istruzione. Nominarle qui produrrebbe 55P04 su
--    ogni installazione da zero, dato che `full-setup.sql` concatena tutte le
--    migrazioni in una transazione sola. Quelle verifiche stanno in
--    `test:subsidy-unit` e `test:subsidy`.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad text;
  v_n   integer;
begin
  -- (a) La RLS è accesa su tutte e diciassette le tabelle nuove.
  select string_agg(c.relname, ', ') into v_bad
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public'
     and c.relname in ('subsidy_sources', 'subsidy_source_fetches', 'subsidy_source_snapshots',
                       'subsidy_program_versions', 'subsidy_program_rules', 'subsidy_calls',
                       'subsidy_catalog_reviews', 'subsidy_projects', 'subsidy_project_documents',
                       'subsidy_project_partners', 'subsidy_project_interpretations',
                       'subsidy_answers', 'subsidy_opportunities', 'subsidy_assessments',
                       'subsidy_criterion_results', 'subsidy_case_documents', 'subsidy_case_events')
     and c.relrowsecurity = false;
  if v_bad is not null then
    raise exception 'RLS non attiva su: %', v_bad;
  end if;

  -- (b) ⚠️ IL CATALOGO NON È SCRIVIBILE DAL CLIENT (§28, §143, §195).
  --     È la garanzia più importante del file: se un giorno qualcuno
  --     concedesse un insert su una di queste tabelle, un cliente potrebbe
  --     riscrivere i requisiti che il prodotto presenta a tutti gli altri.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ') into v_bad
    from information_schema.table_privileges
   where table_schema = 'public'
     and table_name in ('subsidy_sources', 'subsidy_source_fetches', 'subsidy_source_snapshots',
                        'subsidy_program_versions', 'subsidy_program_rules', 'subsidy_calls',
                        'subsidy_catalog_reviews', 'subsidy_programs')
     and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
     and privilege_type in ('INSERT', 'UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'il catalogo incentivi risulta scrivibile dal client: %', v_bad;
  end if;

  -- (c) ⚠️ LO STORICO E LE VALUTAZIONI NON SONO SCRIVIBILI DAL CLIENT.
  --     Senza, si potrebbe firmare un'azione a nome di un collega o scriversi
  --     una valutazione che nessun motore ha prodotto (§146).
  select string_agg(format('%s.%s', table_name, privilege_type), ', ') into v_bad
    from information_schema.table_privileges
   where table_schema = 'public'
     and table_name in ('subsidy_case_events', 'subsidy_assessments',
                        'subsidy_criterion_results', 'subsidy_project_interpretations')
     and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
     and privilege_type in ('INSERT', 'UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'storico o valutazioni risultano scrivibili dal client: %', v_bad;
  end if;

  -- (d) Le risposte sono APPEND-ONLY: nessun update, nessun delete.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ') into v_bad
    from information_schema.table_privileges
   where table_schema = 'public'
     and table_name = 'subsidy_answers'
     and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
     and privilege_type in ('UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'le risposte ai criteri risultano modificabili: %', v_bad;
  end if;

  -- (e) `subsidy_matches` è sola lettura (§165).
  select string_agg(privilege_type, ', ') into v_bad
    from information_schema.table_privileges
   where table_schema = 'public' and table_name = 'subsidy_matches'
     and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
     and privilege_type in ('INSERT', 'UPDATE', 'DELETE');
  if v_bad is not null then
    raise exception 'subsidy_matches (legacy) risulta ancora scrivibile: %', v_bad;
  end if;

  -- (f) Le colonne che il database timbra non sono scrivibili colonna per
  --     colonna. È il controllo che rende vera la promessa della sezione 42.
  --     ⚠️ Due controlli DISTINTI e non uno solo, per la lezione della 0026:
  --     `company_id` di un progetto DEVE essere inseribile (è `not null` senza
  --     default, e senza insert nessuno potrebbe creare un progetto); ciò che
  --     non deve essere possibile è CAMBIARLO dopo.
  select string_agg(format('%s.%s', table_name, column_name), ', ') into v_bad
    from information_schema.column_privileges
   where table_schema = 'public'
     and ((table_name = 'subsidy_projects'
           and column_name in ('created_by', 'created_at', 'updated_at', 'archived_at', 'archived_by'))
       or (table_name = 'subsidy_opportunities'
           and column_name in ('relevance_level', 'relevance_score', 'eligibility_status',
                               'completeness', 'timing', 'source_freshness', 'readiness',
                               'missing_fact_count', 'open_criteria_count',
                               'current_assessment_id', 'assessment_version', 'last_fingerprint',
                               'assessment_stale', 'dismissed_at', 'dismissed_by',
                               'first_matched_at', 'last_assessed_at', 'program_version_id',
                               'call_id', 'kind', 'workflow_run_id'))
       or (table_name = 'subsidy_answers'
           and column_name in ('answered_by', 'answered_at', 'created_at'))
       or (table_name = 'subsidy_cases'
           and column_name in ('submitted_at', 'submitted_by', 'legacy_snapshot',
                               'created_at', 'updated_at'))
       or (table_name = 'subsidy_case_items'
           and column_name in ('completed_at', 'completed_by', 'company_id')))
     and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
     and privilege_type in ('INSERT', 'UPDATE');
  if v_bad is not null then
    raise exception 'colonne timbrate dal database risultano scrivibili dal client: %', v_bad;
  end if;

  -- (g) Le colonne di APPARTENENZA di un progetto e di un'opportunità sono
  --     inseribili ma non aggiornabili: spostare un'opportunità da un'azienda
  --     all'altra dopo la creazione non deve essere possibile.
  select string_agg(format('%s.%s', table_name, column_name), ', ') into v_bad
    from information_schema.column_privileges
   where table_schema = 'public'
     and ((table_name = 'subsidy_projects' and column_name = 'company_id')
       or (table_name = 'subsidy_opportunities' and column_name in ('company_id', 'program_id', 'project_id')))
     and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
     and privilege_type = 'UPDATE';
  if v_bad is not null then
    raise exception 'colonne di appartenenza risultano aggiornabili: %', v_bad;
  end if;

  -- (h) ⚠️ LE FUNZIONI DEL WORKER NON SONO INVOCABILI DA UN UTENTE
  --     AUTENTICATO. È esattamente il difetto che la 0029 ha dovuto chiudere:
  --     `revoke … from public` non basta, perché Supabase concede i privilegi
  --     sulle FUNZIONI anche direttamente ad `anon` e `authenticated`.
  select string_agg(p.proname, ', ') into v_bad
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname in ('subsidy_emit_deadline_approaching', 'subsidy_emit_stale_assessments',
                       'subsidy_emit_source_critical_change', 'subsidy_sources_due',
                       'subsidy_refresh_readiness')
     and (has_function_privilege('authenticated', p.oid, 'EXECUTE')
       or has_function_privilege('anon', p.oid, 'EXECUTE'));
  if v_bad is not null then
    raise exception 'funzioni del worker invocabili da un utente autenticato: %', v_bad;
  end if;

  -- (i) L'unicità della versione pubblicata esiste davvero. Senza quell'indice,
  --     «la versione corrente» sarebbe una domanda con più risposte.
  select count(*) into v_n
    from pg_indexes
   where schemaname = 'public' and indexname = 'uq_subsidy_version_published';
  if v_n <> 1 then
    raise exception 'manca l''indice che garantisce una sola versione pubblicata per programma';
  end if;

  -- (l) L'unicità dell'impronta di valutazione: due valutazioni identiche sulla
  --     stessa opportunità non si scrivono due volte (§60, §181).
  select count(*) into v_n
    from pg_indexes
   where schemaname = 'public' and indexname = 'uq_subsidy_assessments_fingerprint';
  if v_n <> 1 then
    raise exception 'manca l''indice di idempotenza delle valutazioni';
  end if;

  -- (m) ⚠️ IL GIRO VERO, e serve perché il corpo di una plpgsql NON viene
  --     analizzato alla creazione: il 42804 della 0022 e della 0025 si è visto
  --     solo eseguendo. Qui si crea una fonte, una versione, un criterio e una
  --     call, si verifica che l'immutabilità morda, e si cancella tutto.
  declare
    v_src  uuid;
    v_ver  uuid;
    v_prog text := '__selftest_0032__';
    v_ok   boolean;
  begin
    insert into public.subsidy_sources (authority, source_type, canonical_url, allowed_host,
                                        jurisdiction, adapter_key)
    values ('Autoverifica', 'official_program_page', 'https://example.invalid/selftest',
            'example.invalid', 'CH', 'selftest')
    returning id into v_src;

    insert into public.subsidy_programs (id, name, authority, official_source_url, primary_source_id)
    values (v_prog, 'Autoverifica 0032', 'Autoverifica', 'https://example.invalid/selftest', v_src);

    insert into public.subsidy_program_versions (program_id, version_number, status, content_hash)
    values (v_prog, 1, 'published', 'selftest-hash')
    returning id into v_ver;

    -- La colonna denormalizzata si è allineata da sé?
    if (select current_version_id from public.subsidy_programs where id = v_prog) is distinct from v_ver then
      raise exception 'autoverifica: current_version_id non si allinea alla versione pubblicata';
    end if;

    -- L'immutabilità morde davvero?
    v_ok := false;
    begin
      update public.subsidy_program_versions set content_hash = 'altro' where id = v_ver;
    exception when others then
      v_ok := true;
    end;
    if not v_ok then
      raise exception 'autoverifica: una versione pubblicata risulta modificabile';
    end if;

    -- Un criterio su una versione non in bozza dev'essere rifiutato.
    v_ok := false;
    begin
      insert into public.subsidy_program_rules (program_version_id, rule_key, label, hardness, evaluability)
      values (v_ver, 'selftest', 'Autoverifica', 'hard', 'auto');
    exception when others then
      v_ok := true;
    end;
    if not v_ok then
      raise exception 'autoverifica: i criteri di una versione pubblicata risultano modificabili';
    end if;

    -- La cancellazione a cascata funziona? È il controllo che la 0023, la 0025
    -- e la 0028 hanno dovuto imparare tre volte.
    delete from public.subsidy_programs where id = v_prog;
    delete from public.subsidy_sources  where id = v_src;

    if exists (select 1 from public.subsidy_program_versions where program_id = v_prog) then
      raise exception 'autoverifica: la cascata non ha rimosso le versioni';
    end if;
  end;
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0033_subsidy_answers_cascade  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0033 · LA RISPOSTA APPEND-ONLY RENDEVA L'AZIENDA INDISTRUTTIBILE
--
-- IL DIFETTO, RIPRODOTTO PRIMA DI ESSERE CORRETTO (2026-07-30):
--   1. azienda usa-e-getta senza risposte  → `delete from companies` → 204, va via;
--   2. stessa azienda con UNA riga in `subsidy_answers` → `delete` → **23514**,
--      `subsidy_answers_append_only`, e l'azienda resta in produzione.
--
-- La causa: `subsidy_answers_guard()` solleva su `tg_op <> 'INSERT'`, e il suo
-- trigger è `before insert or update or delete`. Durante la cancellazione di
-- un'azienda la cascata prova a togliere le risposte, il trigger la respinge, e
-- l'intera transazione fallisce.
--
-- ⚠️ È LA STESSA CLASSE DI DIFETTO DELLA 0023, DELLA 0025 E DELLA 0028, e la
--    0032 la dichiara nella propria intestazione: «I TRIGGER DI QUESTO FILE
--    DEVONO SOPRAVVIVERE ALLA CASCATA. Un trigger che SOLLEVA o che INSERISCE
--    durante la cancellazione di un'azienda rende quell'azienda
--    indistruttibile.» La regola era scritta; su questa tabella non era
--    applicata. `subsidy_program_rules` la applica correttamente (verifica che
--    il genitore esista ancora), `subsidy_assessments` e
--    `subsidy_project_interpretations` non sono esposte perché il loro trigger
--    non copre il DELETE: `subsidy_answers` era l'unica.
--
-- ⚠️ NON SI INDEBOLISCE L'APPEND-ONLY. §187 resta intero: una risposta non si
--    modifica e non si cancella A MANO. Ciò che si distingue è la
--    CANCELLAZIONE DIRETTA — che va ancora rifiutata — dalla CASCATA, che è la
--    conseguenza di una cancellazione già autorizzata a monte e che nessuno sta
--    «modificando». La distinzione si fa come nella 0032 sezione 26: si guarda
--    se il GENITORE esiste ancora. Se l'azienda non c'è più, siamo dentro la
--    sua cascata.
--
-- ⚠️ Perché non basta togliere `delete` dal trigger: `answered_by` e
--    `answered_at` li timbra questo guardiano, e l'UPDATE va ancora respinto.
--    Serve il ramo, non l'assenza del trigger.
--
-- Idempotente per costruzione: `create or replace` + `drop trigger if exists`.
-- ============================================================================

create or replace function public.subsidy_answers_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  -- ⚠️ `old` si legge SOLO nel ramo che le appartiene. In plpgsql
  --    l'espressione viene preparata per intero, quindi nominare `old` insieme
  --    a `tg_op` la farebbe valutare anche su INSERT, dove non è assegnata:
  --    è la trappola annotata undici volte nella 0032 e prima nella 0026.
  v_parent_gone boolean := false;
begin
  if tg_op = 'DELETE' then
    -- La cancellazione DIRETTA di una risposta resta vietata: §187 dice che se
    -- un criterio è stato dichiarato soddisfatto a marzo e non soddisfatto a
    -- giugno, quel cambiamento è un fatto che riguarda una pratica in corso.
    -- Ma se l'azienda non esiste più non c'è alcuna storia da proteggere: c'è
    -- una cancellazione già autorizzata a monte, e opporsi la fa fallire tutta.
    select not exists (
      select 1 from public.companies c where c.id = old.company_id
    ) into v_parent_gone;

    if v_parent_gone then
      return old;
    end if;

    raise exception 'subsidy_answers_append_only: una risposta non si cancella; se ne registra un''altra'
      using errcode = 'check_violation';
  end if;

  if tg_op = 'UPDATE' then
    raise exception 'subsidy_answers_append_only: una risposta non si modifica; se ne registra un''altra'
      using errcode = 'check_violation';
  end if;

  if auth.uid() is not null then
    if new.answered_by is not null and new.answered_by is distinct from auth.uid() then
      raise exception 'subsidy_answer_author_mismatch: non si può rispondere a nome di un collega'
        using errcode = 'check_violation';
    end if;
    new.answered_by := auth.uid();
  end if;
  new.answered_at := now();

  if new.project_id is not null then
    select company_id into v_company
      from public.subsidy_projects where id = new.project_id;
    if not found or v_company is distinct from new.company_id then
      raise exception 'subsidy_project_cross_tenant: il progetto non appartiene a questa azienda'
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end $$;

drop trigger if exists trg_subsidy_answers_guard on public.subsidy_answers;
create trigger trg_subsidy_answers_guard
  before insert or update or delete on public.subsidy_answers
  for each row execute function public.subsidy_answers_guard();

comment on function public.subsidy_answers_guard() is
  'Append-only sulle risposte: insert sì, update mai, delete solo dentro la cascata di un''azienda già cancellata (0033). Un trigger che solleva durante la cascata rende l''azienda indistruttibile — 0023, 0025, 0028.';


-- ---------------------------------------------------------------------------
-- AUTOVERIFICA
--
-- Il file non si limita a dichiarare la garanzia: la prova su un'azienda
-- usa-e-getta, e se non torna l'applicazione FALLISCE invece di riuscire a
-- metà. È la disciplina della 0032 sezione 43 e della 0026.
--
-- ⚠️ Riproduce ENTRAMBI i lati: la cancellazione diretta deve ancora essere
--    respinta, e la cascata deve passare. Un controllo che provasse solo il
--    secondo non vedrebbe un append-only smontato per sbaglio.
-- ---------------------------------------------------------------------------
do $$
declare
  v_company uuid;
  v_version uuid;
  v_answer  uuid;
  v_blocked boolean := false;
begin
  select id into v_version
    from public.subsidy_program_versions where status = 'published' limit 1;
  if v_version is null then
    raise notice '0033: nessuna versione pubblicata, autoverifica saltata';
    return;
  end if;

  insert into public.companies (legal_name, canton)
    values ('ZZ autoverifica 0033', 'TI')
    returning id into v_company;

  insert into public.subsidy_answers (company_id, program_version_id, rule_key, value)
    values (v_company, v_version, 'autoverifica_0033', 'no')
    returning id into v_answer;

  -- (a) la cancellazione DIRETTA resta vietata
  begin
    delete from public.subsidy_answers where id = v_answer;
  exception when check_violation then
    v_blocked := true;
  end;
  if not v_blocked then
    raise exception '0033: l''append-only è stato smontato — una risposta si cancella a mano';
  end if;

  -- (b) la cascata dell'azienda deve passare
  delete from public.companies where id = v_company;

  if exists (select 1 from public.companies where id = v_company) then
    raise exception '0033: l''azienda è ancora indistruttibile';
  end if;
  if exists (select 1 from public.subsidy_answers where id = v_answer) then
    raise exception '0033: la risposta è sopravvissuta alla cascata';
  end if;

  raise notice '0033: autoverifica superata — cancellazione diretta respinta, cascata passata';
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0034_subsidy_answers_project_cascade  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0034 · LA STESSA REGOLA, UN LIVELLO PIÙ SOTTO
--
-- La 0033 ha esentato dalla guardia append-only la cascata di un'AZIENDA
-- cancellata. Applicandola si è visto subito che il trapping restava un livello
-- più sotto: `subsidy_answers.project_id` è `on delete cascade`, quindi un
-- PROGETTO con anche una sola risposta non si cancella — nemmeno con il ruolo
-- di servizio.
--
-- ⚠️ NON È UN PROBLEMA DEL PRODOTTO NORMALE, e va detto: al client non è
--    concesso alcun `delete` su `subsidy_projects` — un progetto si ARCHIVIA,
--    perché cancellarlo porterebbe via opportunità, valutazioni e il legame
--    delle pratiche che ne sono nate. Il caso che questo file chiude è quello
--    del ruolo di servizio: la pulizia di una suite di test e la rimozione di
--    dati di prova. È esattamente la pena che `test:crm` ha pagato prima della
--    0028, quando la pulizia falliva e lasciava aziende di prova in produzione.
--
-- LA REGOLA, ORA SCRITTA UNA VOLTA SOLA: una risposta non si cancella A MANO;
-- si cancella soltanto DENTRO la cascata di un genitore che non esiste più —
-- l'azienda o il progetto. In entrambi i casi la cancellazione è già stata
-- autorizzata a monte e non c'è alcuna storia da proteggere: le opportunità e
-- le valutazioni di quel progetto se ne sono andate con lui.
--
-- ⚠️ L'append-only NON si indebolisce: la cancellazione diretta di una risposta
--    resta rifiutata, e l'autoverifica lo prova prima di ogni altra cosa.
--
-- Idempotente per costruzione.
-- ============================================================================

create or replace function public.subsidy_answers_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  -- ⚠️ `old` si legge SOLO nel ramo che le appartiene: in plpgsql l'espressione
  --    viene preparata per intero, e nominarla altrove la farebbe valutare
  --    anche su INSERT, dove non è assegnata.
  v_cascade boolean := false;
begin
  if tg_op = 'DELETE' then
    -- Il genitore da cui arriva la cascata non esiste più? Allora questa non è
    -- la modifica di qualcuno: è la conseguenza di una cancellazione già
    -- autorizzata, e opporsi la fa fallire tutta (0023, 0025, 0028, 0033).
    select not exists (select 1 from public.companies c where c.id = old.company_id)
        or (old.project_id is not null
            and not exists (select 1 from public.subsidy_projects p where p.id = old.project_id))
      into v_cascade;

    if v_cascade then
      return old;
    end if;

    raise exception 'subsidy_answers_append_only: una risposta non si cancella; se ne registra un''altra'
      using errcode = 'check_violation';
  end if;

  if tg_op = 'UPDATE' then
    raise exception 'subsidy_answers_append_only: una risposta non si modifica; se ne registra un''altra'
      using errcode = 'check_violation';
  end if;

  if auth.uid() is not null then
    if new.answered_by is not null and new.answered_by is distinct from auth.uid() then
      raise exception 'subsidy_answer_author_mismatch: non si può rispondere a nome di un collega'
        using errcode = 'check_violation';
    end if;
    new.answered_by := auth.uid();
  end if;
  new.answered_at := now();

  if new.project_id is not null then
    select company_id into v_company
      from public.subsidy_projects where id = new.project_id;
    if not found or v_company is distinct from new.company_id then
      raise exception 'subsidy_project_cross_tenant: il progetto non appartiene a questa azienda'
        using errcode = 'check_violation';
    end if;
  end if;

  return new;
end $$;

comment on function public.subsidy_answers_guard() is
  'Append-only sulle risposte: insert sì, update mai, delete solo dentro la cascata di un genitore già cancellato — azienda (0033) o progetto (0034). Un trigger che solleva durante la cascata rende il genitore indistruttibile.';


-- ---------------------------------------------------------------------------
-- AUTOVERIFICA — TRE LATI, non uno
--
-- (a) la cancellazione diretta resta respinta;
-- (b) la cascata del PROGETTO passa;
-- (c) la cascata dell'AZIENDA continua a passare (la garanzia della 0033 non
--     deve essersi rotta riscrivendo la funzione).
-- Se uno dei tre non torna, questa migrazione FALLISCE invece di applicarsi.
-- ---------------------------------------------------------------------------
do $$
declare
  v_company uuid;
  v_project uuid;
  v_version uuid;
  v_answer  uuid;
  v_blocked boolean := false;
begin
  select id into v_version
    from public.subsidy_program_versions where status = 'published' limit 1;
  if v_version is null then
    raise notice '0034: nessuna versione pubblicata, autoverifica saltata';
    return;
  end if;

  insert into public.companies (legal_name, canton)
    values ('ZZ autoverifica 0034', 'TI') returning id into v_company;
  insert into public.subsidy_projects (company_id, title)
    values (v_company, 'ZZ autoverifica 0034') returning id into v_project;
  insert into public.subsidy_answers (company_id, project_id, program_version_id, rule_key, value)
    values (v_company, v_project, v_version, 'autoverifica_0034', 'no')
    returning id into v_answer;

  -- (a)
  begin
    delete from public.subsidy_answers where id = v_answer;
  exception when check_violation then
    v_blocked := true;
  end;
  if not v_blocked then
    raise exception '0034: l''append-only è stato smontato — una risposta si cancella a mano';
  end if;

  -- (b)
  delete from public.subsidy_projects where id = v_project;
  if exists (select 1 from public.subsidy_projects where id = v_project) then
    raise exception '0034: il progetto è ancora indistruttibile';
  end if;
  if exists (select 1 from public.subsidy_answers where id = v_answer) then
    raise exception '0034: la risposta è sopravvissuta alla cascata del progetto';
  end if;

  -- (c) — la garanzia della 0033, riprovata su una risposta SENZA progetto
  insert into public.subsidy_answers (company_id, program_version_id, rule_key, value)
    values (v_company, v_version, 'autoverifica_0034_azienda', 'no')
    returning id into v_answer;
  delete from public.companies where id = v_company;
  if exists (select 1 from public.companies where id = v_company) then
    raise exception '0034: l''azienda è tornata indistruttibile — la 0033 si è rotta';
  end if;

  raise notice '0034: autoverifica superata — diretta respinta, cascata di progetto e di azienda passate';
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0035_calendar_notification_schedulers  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0035 — I DUE SCHEDULER DEL CALENDARIO E DELLE NOTIFICHE ENTRANO NEL REPOSITORY
--
-- ⚠️ PERCHÉ ESISTE, e non è la stessa cosa che «accenderli».
-- Il 2026-07-31 `calendar-sync-drain` e `notifications-worker` sono stati
-- creati A MANO dal SQL editor, incollando il blocco di
-- docs/calendar-notifications.md §11.4. Da quel momento funzionano: sono in
-- `cron.job`, sono attivi, hanno le cadenze giuste. Ma esistono in DUE posti —
-- un documento e un database — e in nessuno dei due sono un artefatto tracciato.
--
-- Il costo di questa differenza è scritto, parola per parola, nel testo di
-- aiuto di `scripts/verify-deploy.mjs`: «se il database va rifatto non
-- torneranno». Un progetto Supabase ricostruito, un ambiente di prova, un
-- cliente installato da zero con `full-setup.sql` ottengono oggi undici moduli
-- e nessun promemoria — senza che un solo test diventi rosso, perché nessun
-- test può vedere un job che non è mai stato creato. È esattamente il difetto
-- che `test:operations` è nato per intercettare, e che intercettava a metà:
-- l'inventario accetta una dichiarazione scritta in un `.md`, e un blocco di
-- codice dentro un documento non lo esegue nessuno. Da questa migrazione
-- l'inventario pretende una MIGRAZIONE (controllo 5 di `test:operations`).
--
-- Questa migrazione non cambia il comportamento dei due worker. Non tocca il
-- loro codice, non tocca il loro contratto, non tocca i loro segreti. Rende
-- RIPRODUCIBILE ciò che oggi è stato battuto a mano una volta sola.
--
-- ---------------------------------------------------------------------------
-- ⚠️⚠️ L'ORIGINE DEL PROGETTO NON È SCRITTA QUI, E NON È UN VEZZO
--
-- I sei job HTTP già in esercizio portano l'origine scritta in chiaro nel
-- comando («https://<ref>.supabase.co/…»), perché sono stati creati a mano su
-- QUEL progetto e non sono mai passati da una migrazione. Una migrazione è
-- un'altra cosa: finisce in `supabase/full-setup.sql`, che la CI applica a un
-- database effimero a ogni pull request e che il README dà a chi installa da
-- zero. Con l'origine scritta dentro, OGNI installazione nuova programmerebbe
-- due chiamate ogni 10 e 15 minuti verso la NOSTRA produzione, autenticate con
-- un segreto che non ha — cioè un carico costante di 403 verso di noi, prodotto
-- dal database di qualcun altro.
--
-- L'origine si risolve quindi A OGNI ESECUZIONE, dal VAULT.
--
-- ⚠️ È lo stesso identico idioma che il repository usa già per il SEGRETO, e la
-- ragione scritta nel comando di `automation-worker` vale parola per parola
-- anche qui: «non è scritto nel job: si legge a ogni esecuzione, così ruotarlo
-- non richiede di riscrivere il job». Non è un secondo sistema di
-- configurazione: è lo STESSO, applicato all'altro dato che dipende
-- dall'ambiente.
--
-- ⚠️ PERCHÉ IL VAULT E NON UN PARAMETRO DI DATABASE, che era la prima scelta:
-- perché su Supabase ospitato NON SI PUÒ. Provato contro il progetto vero:
--     alter database postgres set app.settings.functions_base_url = '…'
--     → ERROR 42501: permission denied to set parameter
-- e lo stesso `alter role postgres set`. Il ruolo `postgres` possiede il
-- database ma non è superutente, e un parametro personalizzato a livello di
-- database o di ruolo richiede il superutente. Funziona solo `set` di sessione,
-- che a pg_cron — che apre la propria — non serve a niente. Il Vault invece è
-- scrivibile da noi: i sette segreti dei worker sono lì da giorni.
--
-- ⚠️ E SE NON È CONFIGURATO, SI VEDE. `public.functions_base_url()` SOLLEVA
-- invece di restituire NULL. Un database che non sa a quale progetto appartiene
-- non compone un URL sbagliato e non fa finta di niente: ogni esecuzione finisce
-- `failed` in `cron.job_run_details` con il messaggio che dice cosa manca e come
-- si rimedia. Un guasto registrato, non un risultato plausibile. Questa
-- migrazione lo annuncia inoltre con un WARNING quando viene applicata.
--
-- Perché un WARNING e non un'eccezione al momento dell'applicazione: un'
-- eccezione renderebbe inapplicabile l'intero elenco delle migrazioni a un
-- database vuoto, che è proprio il percorso che la CI prova a ogni pull request
-- (`supabase start` applica le migrazioni PRIMA che qualcuno possa configurare
-- alcunché). Il guasto non viene ammorbidito: viene spostato dove è
-- verificabile — a ogni esecuzione del job, e in `npm run verify:deploy`, che
-- dalla stessa data legge anche l'ESITO dell'ultima esecuzione di ogni job.
--
-- ⚠️ Una configurazione SBAGLIATA, invece, fa fallire questa migrazione: una
-- mezza configurazione è peggio di nessuna, perché somiglia a una buona.
--
-- Da eseguire UNA VOLTA sul progetto, prima o dopo questa migrazione:
--
--   select vault.create_secret('https://<ref>.supabase.co', 'project_functions_base_url');
--
-- ---------------------------------------------------------------------------
-- Requisiti: 0018 (calendario e notifiche) applicata; le Edge Function
-- `calendar-sync` e `notifications-worker` deployate; nel Vault
-- `calendar_worker_secret`, `notifications_worker_secret` e
-- `project_functions_base_url`.
-- Documento di modulo: docs/calendar-notifications.md §11.4
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Le estensioni
--
-- `pg_cron` la crea già la 0031; ripeterla è innocuo e rende questa migrazione
-- leggibile da sola. `pg_net` non la crea NESSUNA migrazione: i sei job che la
-- usano sono nati a mano su un progetto dove Supabase l'aveva già attivata, e
-- un'installazione da zero non ce l'avrebbe. È la prima volta che il
-- repository la dichiara.
-- ---------------------------------------------------------------------------
create extension if not exists pg_cron with schema cron;
create extension if not exists pg_net  with schema extensions;

-- ---------------------------------------------------------------------------
-- 2. Da dove chiamare — l'unica funzione di questa migrazione
--
-- ⚠️ SOLLEVA invece di restituire NULL, ed è tutto il punto. Un `select` che
-- torna NULL comporrebbe `NULL || '/functions/v1/…'` = NULL, e
-- `net.http_post(url := null)` è un guasto che nessuno legge. Qui il messaggio
-- dice che cosa manca e quale comando lo rimedia, e finisce in
-- `cron.job_run_details.return_message`.
--
-- ⚠️ `security invoker` (il predefinito) DI PROPOSITO. Con `security definer`
-- questa funzione leggerebbe il Vault per conto di chiunque possa eseguirla, e
-- basterebbe un `grant` distratto per farne una finestra sul Vault. Così invece
-- chi non ha i privilegi sul Vault ottiene «permission denied for schema vault»
-- anche riuscendo a chiamarla. pg_cron esegue come `postgres`, che quei
-- privilegi ce li ha.
--
-- ⚠️ `search_path = ''` e ogni nome qualificato: senza, chi controlla il
-- `search_path` della sessione chiamante potrebbe interporre un proprio
-- `decrypted_secrets`.
-- ---------------------------------------------------------------------------
create or replace function public.functions_base_url()
returns text
language plpgsql
stable
set search_path = ''
as $fn$
declare
  v_raw text;
begin
  select s.decrypted_secret into v_raw
    from vault.decrypted_secrets s
   where s.name = 'project_functions_base_url';

  if v_raw is null then
    raise exception
      'project_functions_base_url non è nel Vault: questo database non sa a quale progetto appartiene, e gli scheduler non possono chiamare nessuna Edge Function. Rimedio: select vault.create_secret(''https://<ref>.supabase.co'', ''project_functions_base_url'');';
  end if;

  v_raw := btrim(v_raw);
  if v_raw = '' then
    raise exception 'project_functions_base_url è nel Vault ma VUOTO: comporrebbe un URL relativo.';
  end if;

  v_raw := rtrim(v_raw, '/');
  if v_raw !~ '^https?://[^[:space:]/]+$' then
    raise exception
      'project_functions_base_url non è utilizzabile: %. Serve la sola origine, senza percorso, per esempio https://abcdefgh.supabase.co',
      v_raw;
  end if;

  return v_raw;
end $fn$;

comment on function public.functions_base_url() is
  'Origine del progetto per gli scheduler, letta dal Vault a ogni esecuzione. Solleva se manca o non è utilizzabile: un URL composto male darebbe un cron eternamente fallito e silenzioso.';

-- ⚠️ Su `public` Supabase concede i privilegi pieni per default (la lezione del
-- preambolo di `full-setup.sql`): senza questo `revoke`, `anon` e
-- `authenticated` potrebbero eseguirla — e `public` è lo schema che PostgREST
-- espone, quindi sarebbe una `rpc` raggiungibile dal browser.
revoke all on function public.functions_base_url() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. La configurazione, se c'è, dev'essere SANA
--
-- Non si pretende che esista (vedi l'intestazione). Si pretende che, se
-- esiste, sia utilizzabile — e lo si verifica CHIAMANDO la funzione, non
-- ripetendone le regole qui: due copie della stessa validazione divergono.
-- ---------------------------------------------------------------------------
do $mig$
declare
  v_esiste boolean;
  v_base   text;
begin
  select exists (
    select 1 from vault.secrets where name = 'project_functions_base_url'
  ) into v_esiste;

  if not v_esiste then
    return;   -- il WARNING lo emette il blocco 5, dopo aver creato i job
  end if;

  v_base := public.functions_base_url();   -- solleva se è configurata male
  raise notice 'origine degli scheduler: %', v_base;
end $mig$;

-- ---------------------------------------------------------------------------
-- 4. I due job
--
-- ⚠️ Si toglie PRIMA di rimettere, per la ragione già scritta nella 0031:
-- `cron.schedule` con lo stesso nome aggiorna il job sulle versioni recenti di
-- pg_cron ma non su tutte, e senza la rimozione riapplicare questa migrazione
-- su una versione più vecchia fallirebbe con una violazione di unicità
-- lasciandola a metà. `cron.unschedule` su un nome inesistente solleva, quindi
-- si guarda prima se c'è.
--
-- ⚠️ `timeout_milliseconds := 150000` NON è facoltativo: pg_net chiude la
-- connessione dopo 5 secondi predefiniti, e i due worker hanno un budget di
-- 150. Senza, OGNI esecuzione risulterebbe fallita anche facendo il proprio
-- lavoro. È la trappola già pagata con l'Inbox.
--
-- ⚠️ I due comandi sono COSTANTI: non c'è un solo valore interpolato qui
-- dentro. Né l'origine né il segreto finiscono nel testo del job — si leggono
-- entrambi a ogni esecuzione. Chi legge `cron.job` non trova nulla da
-- proteggere.
-- ---------------------------------------------------------------------------
do $mig$
begin
  -- 4.1 La coda del calendario: ogni 10 minuti, perché è ciò che tiene
  --     allineati gli eventi. Payload `{"action":"drain"}`, che è il contratto
  --     di `calendar-sync` (le altre due azioni sono `sync`, di una persona, e
  --     `reconcile`, della diagnostica).
  if exists (select 1 from cron.job where jobname = 'calendar-sync-drain') then
    perform cron.unschedule('calendar-sync-drain');
  end if;

  perform cron.schedule(
    'calendar-sync-drain',
    '*/10 * * * *',
    $job$select net.http_post(
      url := public.functions_base_url() || '/functions/v1/calendar-sync',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-calendar-worker-secret',
        (select decrypted_secret from vault.decrypted_secrets where name = 'calendar_worker_secret')
      ),
      body := jsonb_build_object('action', 'drain'),
      timeout_milliseconds := 150000
    );$job$
  );

  -- 4.2 I promemoria: ogni quarto d'ora. La finestra è «dalle otto locali in
  --     poi», quindi girare spesso serve a coprire tutti i fusi e a
  --     recuperare un'esecuzione saltata. Corpo vuoto: il worker non prende
  --     parametri.
  if exists (select 1 from cron.job where jobname = 'notifications-worker') then
    perform cron.unschedule('notifications-worker');
  end if;

  perform cron.schedule(
    'notifications-worker',
    '*/15 * * * *',
    $job$select net.http_post(
      url := public.functions_base_url() || '/functions/v1/notifications-worker',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-notifications-worker-secret',
        (select decrypted_secret from vault.decrypted_secrets where name = 'notifications_worker_secret')
      ),
      body := '{}'::jsonb,
      timeout_milliseconds := 150000
    );$job$
  );
end $mig$;

-- ---------------------------------------------------------------------------
-- 5. Autoverifica
--
-- Come la 0031 e la 0034: uno scheduler che si spera sia stato creato non è
-- stato creato. Ogni proprietà su cui poggia il funzionamento viene RILETTA da
-- `cron.job`, non dedotta dal fatto che le istruzioni sopra non abbiano
-- sollevato.
--
-- ⚠️ Compreso ciò che NON deve esserci: nessuna origine scritta in chiaro e
-- nessun segreto nel testo del comando. Un controllo che guarda solo ciò che
-- deve esserci non vede arrivare ciò che non deve.
-- ---------------------------------------------------------------------------
do $mig$
declare
  r        record;
  v_atteso record;
  v_quanti integer;
  v_esiste boolean;
begin
  for v_atteso in
    select * from (values
      ('calendar-sync-drain',  '*/10 * * * *', '/functions/v1/calendar-sync',        'calendar_worker_secret'),
      ('notifications-worker', '*/15 * * * *', '/functions/v1/notifications-worker', 'notifications_worker_secret')
    ) as t(nome, cadenza, bersaglio, segreto)
  loop
    -- (a) esiste, ed esiste UNA volta sola
    select count(*) into v_quanti from cron.job where jobname = v_atteso.nome;
    if v_quanti = 0 then
      raise exception 'il job % non è stato creato', v_atteso.nome;
    end if;
    if v_quanti > 1 then
      raise exception 'il job % è duplicato: % righe in cron.job', v_atteso.nome, v_quanti;
    end if;

    select * into r from cron.job where jobname = v_atteso.nome;

    -- (b) è attivo
    if not r.active then
      raise exception 'il job % esiste ma non è attivo', v_atteso.nome;
    end if;

    -- (c) la cadenza è quella dichiarata nell'inventario di test:operations
    if r.schedule <> v_atteso.cadenza then
      raise exception 'il job % ha cadenza «%», attesa «%»', v_atteso.nome, r.schedule, v_atteso.cadenza;
    end if;

    -- (d) punta alla funzione giusta
    if position(v_atteso.bersaglio in r.command) = 0 then
      raise exception 'il job % non punta a %', v_atteso.nome, v_atteso.bersaglio;
    end if;

    -- (e) dichiara il timeout, e quello giusto: la trappola dei 5 secondi
    if position('timeout_milliseconds := 150000' in r.command) = 0 then
      raise exception 'il job % non dichiara timeout_milliseconds := 150000', v_atteso.nome;
    end if;

    -- (f) legge il segreto dal Vault invece di portarselo dentro
    if position('vault.decrypted_secrets' in r.command) = 0
       or position(v_atteso.segreto in r.command) = 0 then
      raise exception 'il job % non legge % dal Vault', v_atteso.nome, v_atteso.segreto;
    end if;

    -- (g) e non porta un'origine scritta in chiaro
    if r.command ~ 'https?://' then
      raise exception
        'il job % contiene un URL in chiaro: l''origine va risolta da public.functions_base_url() a ogni esecuzione',
        v_atteso.nome;
    end if;
    if position('public.functions_base_url()' in r.command) = 0 then
      raise exception 'il job % non risolve l''origine da public.functions_base_url()', v_atteso.nome;
    end if;
  end loop;

  -- (h) la funzione non è raggiungibile da chi non deve
  if has_function_privilege('anon', 'public.functions_base_url()', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.functions_base_url()', 'EXECUTE') then
    raise exception 'public.functions_base_url() è eseguibile da anon o authenticated: il revoke non ha avuto effetto';
  end if;

  -- (i) e infine: questo database sa a quale progetto appartiene?
  --     Non è una condizione per creare i job — è una condizione perché
  --     SERVANO. Detto qui, con accanto il comando esatto.
  select exists (select 1 from vault.secrets where name = 'project_functions_base_url') into v_esiste;
  if not v_esiste then
    raise warning
      'i due scheduler sono stati creati ma «project_functions_base_url» NON è nel Vault: ogni esecuzione fallirà, e lo dirà in cron.job_run_details. Da eseguire una volta: select vault.create_secret(''https://<ref>.supabase.co'', ''project_functions_base_url'');';
  end if;
end $mig$;

-- ---------------------------------------------------------------------------
-- 6. Il commento dell'estensione resta la mappa di ciò che il repository
--    programma DAVVERO, e non di ciò che qualcuno ha battuto a mano.
-- ---------------------------------------------------------------------------
comment on extension pg_cron is
  'Pianificazione dentro il database. Job creati da una migrazione: assistant-purge (0031), '
  'retention delle conversazioni dell''assistente; calendar-sync-drain e notifications-worker (0035), '
  'coda del calendario e promemoria. Gli altri job presenti nel progetto sono stati creati a mano '
  'dai blocchi SQL della documentazione di modulo (docs/ai-inbox.md, workflow-automation.md, '
  'finance-operations.md, contract-manager.md, incentivi.md) e NON tornerebbero se il database venisse rifatto.';

-- >>>>>>>>>>>>>>>>>>>>  0036_assistant_empty_group_citation  <<<<<<<<<<<<<<<<<<<<

-- ===========================================================================
-- 0036 — UN INSIEME VUOTO SI PUÒ CITARE
--
-- PERCHÉ. `eval:assistant` era instabile sul caso «Quali automazioni stanno
-- fallendo?», e la causa non era il modello: era che quella domanda è l'unica
-- la cui risposta corretta è «nessuna».
--
-- I riferimenti `f1, f2…` che il modello può scrivere li conia `allocRef()`,
-- un contatore che avanza SOLO quando uno strumento produce una fonte. Ma
-- `emptyResult()` restituiva `sources: []`: un esito legittimamente vuoto non
-- coniava niente, e il registro poteva restare del tutto vuoto. Intanto il
-- prompt dichiara che `f1, f2…` sono «gli UNICI identificativi che puoi
-- scrivere» e chiede di citare il riferimento dell'ELENCO per le affermazioni
-- aggregate. Il modello doveva dire «non c'è nulla» senza avere nulla da
-- citare: a volte scriveva `f1`, il primo nome plausibile, e la guardia delle
-- citazioni lo scartava — correttamente. Il buco era a monte.
--
-- ⚠️ L'ASIMMETRIA È LA PROVA: un elenco NON vuoto alloca sempre un riferimento
-- di gruppo; uno vuoto non allocava niente. Perciò «non c'è nulla» era l'unica
-- risposta che il prodotto strutturalmente non sapeva ancorare, ed è la
-- risposta più importante che un assistente amministrativo debba saper dare.
--
-- CHE COSA CAMBIA QUI. Solo il vincolo. La 0027 ammetteva due forme di
-- citazione — una fonte singola, oppure un gruppo con `group_size > 0` — e la
-- ragione scritta là resta valida: «confonderle produrrebbe pastiglie che non
-- si sa se aprono un record o un elenco». Un insieme vuoto NON è una terza
-- forma ambigua: è un gruppo, apre un elenco, e la sua dimensione è zero.
-- L'unica cosa che il vincolo vietava era proprio dire zero.
--
-- ⚠️ `source_ids` resta OBBLIGATORIO anche a zero, e deve valere `'{}'` e non
-- `null`: la differenza fra «ho guardato e non c'era niente» e «non so che cosa
-- ci fosse» è esattamente ciò che questa citazione esiste per registrare.
--
-- ⚠️ NESSUN valore enum nuovo, nessuna colonna nuova, nessun indice nuovo:
-- niente 55P04, e il file è ripetibile per costruzione (`drop … if exists`).
-- ===========================================================================

alter table public.assistant_citations
  drop constraint if exists assistant_citations_single_or_group;

alter table public.assistant_citations
  add constraint assistant_citations_single_or_group check (
    (source_id is not null and group_size is null)
    or (source_id is null and group_size is not null and group_size >= 0 and source_ids is not null)
  );

comment on column public.assistant_citations.group_size is
  '§57 — citazione aggregata: quanti elementi, con la rotta che apre l''elenco già filtrato. ZERO è ammesso e significa «ho consultato questo insieme ed era vuoto»: è ciò che ancora una risposta negativa. Un insieme non consultato non produce alcuna citazione.';

-- ---------------------------------------------------------------------------
-- Autoverifica.
--
-- ⚠️ Verifica il vincolo REALMENTE INSTALLATO leggendo `pg_constraint`, non la
-- copia dell'espressione scritta qui sopra: un blocco che rileggesse il proprio
-- testo guarderebbe sé stesso e sarebbe verde per costruzione. È la trappola
-- già pagata dal test del registro delle automazioni, che confrontava due
-- costanti dello stesso file TypeScript credendo di confrontarsi con l'enum del
-- database.
--
-- ⚠️ La prova di COMPORTAMENTO — che una riga a zero entri davvero e che le
-- forme vietate restino vietate — non sta qui ma in `npm run test:assistant`,
-- sezione «citazione di un insieme vuoto», dove c'è un'azienda usa-e-getta su
-- cui inserire per davvero. Una `insert` di prova qui dentro avrebbe avuto
-- bisogno di un messaggio e di un'azienda veri, cioè di lasciare residui in
-- produzione per verificare un `check`.
-- ---------------------------------------------------------------------------
do $$
declare
  def text;
begin
  select pg_get_constraintdef(c.oid) into def
  from pg_constraint c
  join pg_class t on t.oid = c.conrelid
  join pg_namespace n on n.oid = t.relnamespace
  where n.nspname = 'public'
    and t.relname = 'assistant_citations'
    and c.conname = 'assistant_citations_single_or_group'
    and c.contype = 'c';

  if def is null then
    raise exception '0036: il vincolo assistant_citations_single_or_group non risulta installato';
  end if;

  -- La soglia nuova c'è…
  if position('>= 0' in def) = 0 then
    raise exception '0036: il vincolo non ammette group_size = 0 (definizione: %)', def;
  end if;

  -- …e la vecchia non è rimasta accanto. `> 0` compare come sottostringa anche
  -- dentro `>= 0`, quindi si cerca la forma con lo spazio che solo la vecchia
  -- soglia produce.
  if position('group_size > 0' in def) > 0 then
    raise exception '0036: la vecchia soglia group_size > 0 è ancora nel vincolo (definizione: %)', def;
  end if;

  -- La garanzia che NON si sta allentando: una fonte singola non può portare
  -- una dimensione di gruppo, e un gruppo deve avere i propri identificativi.
  --
  -- ⚠️ I LETTERALI VANNO IN MAIUSCOLO perché il confronto è contro `upper(def)`.
  -- La prima stesura cercava `'source_ids IS NOT NULL'` — minuscolo — dentro una
  -- stringa già alzata a maiuscolo: non poteva combaciare, e la migrazione
  -- falliva su sé stessa. L'ha trovata la CI applicandola da zero, che è l'unico
  -- posto dove questo blocco viene ESEGUITO: in locale non c'è Postgres, quindi
  -- l'autoverifica era scritta e mai provata. `test:assistant-unit` ora sorveglia
  -- che ogni letterale confrontato con `upper()` sia maiuscolo.
  if position('SOURCE_IDS IS NOT NULL' in upper(def)) = 0 then
    raise exception '0036: il vincolo non richiede più source_ids sui gruppi (definizione: %)', def;
  end if;
  if position('SOURCE_ID IS NOT NULL' in upper(def)) = 0 then
    raise exception '0036: il vincolo non distingue più la fonte singola (definizione: %)', def;
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0037_subsidy_catalog_review  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0037 — La revisione del catalogo incentivi: chi può deciderla, e come.
--
-- IL PROBLEMA. `subsidy_catalog_reviews` accumula le schede che il rilevatore di
-- cambiamenti produce quando una fonte ufficiale si muove. Al 2026-08-05 ce ne
-- sono SETTE, ferme dal 2026-07-30, e nessuno le ha mai potute guardare da
-- dentro il prodotto: la 0032 le ha lasciate con `revoke all` e senza policy, di
-- proposito, perché contengono proposte non verificate.
--
-- ⚠️⚠️ PERCHÉ NON BASTAVA APRIRLE A `authenticated`, ed è la decisione centrale
-- di questa migrazione. **Il catalogo è GLOBALE**: non ha `company_id`, e ciò
-- che dice vale per tutti i tenant insieme. `member_role` (owner/admin/member)
-- è invece per AZIENDA, quindi non può esprimere «può modificare il catalogo
-- condiviso». Concedere la lettura o la scrittura a `authenticated` avrebbe
-- significato che il cliente di un'azienda approva modifiche che TUTTI gli altri
-- clienti vedono — un'escalation fra tenant, e l'esatto contrario della ragione
-- per cui quel `revoke all` esiste.
--
-- LA SCELTA: un elenco esplicito di operatori del catalogo. Non è un ruolo, non
-- è un permesso per azienda: è un elenco di persone che possono decidere sul
-- catalogo del prodotto. Chi non c'è dentro non vede niente di diverso da oggi.
--
-- ⚠️ NESSUNA POLICY, NEMMENO QUI. Le due tabelle restano irraggiungibili dal
-- client: si passa SOLO dalle due funzioni qui sotto, che sono `security
-- definer` e controllano l'appartenenza PRIMA di qualsiasi cosa. Una policy in
-- più sarebbe una seconda porta da sorvegliare.
--
-- ⚠️ NON C'È NIENTE DA «APPLICARE» IN QUESTE SETTE SCHEDE, e il disegno lo
-- rispecchia. I loro `proposed_values` non sono campi di catalogo: sono impronte
-- della fonte (`textLength`, `contentHash`, `declaredUpdatedAt`,
-- `deadlineCandidateCount`). Dicono «la pagina è cambiata», non «il nome del
-- programma adesso è X». Quindi approvare significa «ho guardato la fonte, ciò
-- che diciamo resta vero» → si aggiorna `last_checked_at`; respingere significa
-- «il catalogo è sbagliato» → serve una nota che dica cosa, e la correzione vera
-- resta nel seed, che è come questo catalogo è scritto oggi. Nessun editor di
-- catalogo dentro l'app: sarebbe un sistema di redazione, e non è ciò che serve.
--
-- ⚠️ RIPETIBILE PER COSTRUZIONE: `if not exists`, `create or replace`, `revoke`,
-- `do $$`. Applicarla due volte non cambia nulla.
-- ============================================================================

-- ---- Chi può decidere sul catalogo -----------------------------------------

create table if not exists public.subsidy_catalog_editors (
  user_id  uuid primary key references auth.users (id) on delete cascade,
  added_at timestamptz not null default now(),
  -- Perché questa persona è qui. Un elenco di uuid senza motivo diventa un
  -- elenco che nessuno osa più toccare.
  note     text
);

comment on table public.subsidy_catalog_editors is
  'Le persone che possono revisionare il catalogo incentivi. NON è un ruolo per azienda: il catalogo è globale. Si legge e si scrive solo via funzioni security definer.';

alter table public.subsidy_catalog_editors enable row level security;

-- ⚠️ Su `public` un grant non restringe nulla senza un `revoke all` che lo
-- preceda: Supabase concede i privilegi pieni per default.
revoke all on public.subsidy_catalog_editors from anon, authenticated, public;
revoke all on public.subsidy_catalog_reviews from anon, authenticated, public;

/**
 * `true` se chi sta chiamando è un operatore del catalogo.
 *
 * ⚠️ `security definer` perché deve poter leggere una tabella che nessun client
 * può leggere. `stable`, non `volatile`: dentro una stessa istruzione la
 * risposta non cambia.
 * ⚠️ Con `auth.uid()` nullo — service role, o SQL editor — torna `false`, e va
 * bene così: i worker non passano di qui, usano il service role sulle tabelle.
 */
create or replace function public.subsidy_is_catalog_editor()
returns boolean
language sql
security definer
stable
set search_path = ''
as $$
  select exists (
    select 1 from public.subsidy_catalog_editors e
     where e.user_id = auth.uid()
  );
$$;

-- ---- Leggere la coda -------------------------------------------------------

/**
 * Le revisioni del catalogo, con accanto ciò che il catalogo dice OGGI.
 *
 * ⚠️ Chi non è operatore riceve un ERRORE, non un elenco vuoto. Un elenco vuoto
 * è una risposta plausibile a «non ci sono revisioni», e usarlo per dire «non
 * puoi guardare» significherebbe rispondere il falso a chi ha diritto di sapere
 * che esiste qualcosa che non può vedere.
 */
create or replace function public.list_subsidy_catalog_reviews(
  p_include_resolved boolean default false,
  p_limit integer default 100
)
returns table (
  id                 uuid,
  program_id         text,
  program_name       text,
  program_authority  text,
  last_checked_at    date,
  data_status        text,
  change_type        public.subsidy_review_change_type,
  risk_level         public.subsidy_review_risk,
  status             public.subsidy_review_status,
  previous_values    jsonb,
  proposed_values    jsonb,
  source_url         text,
  created_at         timestamptz,
  reviewed_at        timestamptz,
  reviewed_by        uuid,
  notes              text
)
language plpgsql
security definer
stable
set search_path = ''
as $$
begin
  if not public.subsidy_is_catalog_editor() then
    raise exception 'NOT_CATALOG_EDITOR'
      using errcode = '42501',
            hint = 'Solo gli operatori del catalogo possono leggere le revisioni.';
  end if;

  return query
    select r.id,
           r.program_id,
           p.name,
           p.authority,
           p.last_checked_at,
           p.data_status::text,
           r.change_type,
           r.risk_level,
           r.status,
           r.previous_values,
           r.proposed_values,
           s.url,
           r.created_at,
           r.reviewed_at,
           r.reviewed_by,
           r.notes
      from public.subsidy_catalog_reviews r
      left join public.subsidy_programs p on p.id = r.program_id
      left join public.subsidy_source_fetches f on f.id = r.source_fetch_id
      left join public.subsidy_sources s on s.id = f.source_id
     where p_include_resolved or r.status = 'pending'
     -- Le più rischiose e le più vecchie per prime: è l'ordine in cui una
     -- persona le smaltisce, non l'ordine in cui sono arrivate.
     order by (r.status = 'pending') desc,
              case r.risk_level when 'high' then 0 when 'medium' then 1 else 2 end,
              r.created_at
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

-- ---- Decidere --------------------------------------------------------------

/**
 * Chiude una revisione, e scrive CHI ha deciso e QUANDO.
 *
 * `p_decision`:
 *   · `accepted` — «ho guardato la fonte, ciò che il catalogo dice resta vero».
 *     Aggiorna `subsidy_programs.last_checked_at` a oggi: è il solo effetto
 *     sul catalogo, ed è quello che serve perché la freschezza riparta.
 *   · `rejected` — «il catalogo è sbagliato». RICHIEDE una nota: una revisione
 *     respinta senza dire cosa non va lascia il lavoro esattamente dov'era.
 *   · `ignored`  — «cambiamento irrilevante, non riguarda ciò che pubblichiamo».
 *     Non tocca `last_checked_at`, perché nessuno ha verificato il contenuto.
 *
 * ⚠️ Una revisione GIÀ DECISA non si ridecide: `raise`, non un aggiornamento
 * silenzioso. Due persone sulla stessa coda devono accorgersi di essersi
 * pestate i piedi, non sovrascriversi a vicenda.
 */
create or replace function public.resolve_subsidy_catalog_review(
  p_id       uuid,
  p_decision text,
  p_note     text default null
)
returns table (
  id              uuid,
  status          public.subsidy_review_status,
  reviewed_at     timestamptz,
  reviewed_by     uuid,
  last_checked_at date
)
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  v_actor   uuid := auth.uid();
  v_program text;
  v_status  public.subsidy_review_status;
  v_checked date;
begin
  if not public.subsidy_is_catalog_editor() then
    raise exception 'NOT_CATALOG_EDITOR'
      using errcode = '42501',
            hint = 'Solo gli operatori del catalogo possono decidere una revisione.';
  end if;

  if p_decision not in ('accepted', 'rejected', 'ignored') then
    raise exception 'INVALID_DECISION'
      using errcode = '22023',
            hint = 'Ammessi: accepted, rejected, ignored.';
  end if;

  -- ⚠️ La nota è obbligatoria solo per il rifiuto, ed è la ragione per cui
  -- questa funzione esiste invece di un semplice update: è una regola, e le
  -- regole stanno dove non si possono aggirare.
  if p_decision = 'rejected' and coalesce(btrim(p_note), '') = '' then
    raise exception 'NOTE_REQUIRED'
      using errcode = '22023',
            hint = 'Respingere senza dire che cosa non va lascia il lavoro dov''era.';
  end if;

  -- Si blocca la riga PRIMA di leggerne lo stato: senza, due decisioni
  -- simultanee leggerebbero entrambe «pending» e passerebbero entrambe.
  select r.program_id, r.status into v_program, v_status
    from public.subsidy_catalog_reviews r
   where r.id = p_id
     for update;

  if not found then
    raise exception 'REVIEW_NOT_FOUND' using errcode = 'P0002';
  end if;

  if v_status <> 'pending' then
    raise exception 'REVIEW_ALREADY_RESOLVED'
      using errcode = '55000',
            hint = 'Questa revisione è già stata decisa da qualcuno.';
  end if;

  update public.subsidy_catalog_reviews r
     set status      = p_decision::public.subsidy_review_status,
         reviewed_by = v_actor,
         reviewed_at = now(),
         notes       = nullif(btrim(coalesce(p_note, '')), '')
   where r.id = p_id;

  -- Solo l'approvazione tocca il catalogo, e tocca UNA cosa sola.
  if p_decision = 'accepted' and v_program is not null then
    update public.subsidy_programs p
       set last_checked_at = current_date
     where p.id = v_program;
  end if;

  select p.last_checked_at into v_checked
    from public.subsidy_programs p where p.id = v_program;

  return query
    select p_id, p_decision::public.subsidy_review_status, now(), v_actor, v_checked;
end;
$$;

-- ---- Superficie concessa ---------------------------------------------------
-- ⚠️ Si concede l'ESECUZIONE delle tre funzioni, non l'accesso alle tabelle. Il
-- cancello è dentro le funzioni: `execute` a `authenticated` significa «puoi
-- chiedere», non «puoi vedere».
revoke all on function public.subsidy_is_catalog_editor() from public;
revoke all on function public.list_subsidy_catalog_reviews(boolean, integer) from public;
revoke all on function public.resolve_subsidy_catalog_review(uuid, text, text) from public;

grant execute on function public.subsidy_is_catalog_editor() to authenticated;
grant execute on function public.list_subsidy_catalog_reviews(boolean, integer) to authenticated;
grant execute on function public.resolve_subsidy_catalog_review(uuid, text, text) to authenticated;

-- ---- Autoverifica ----------------------------------------------------------
-- ⚠️ Una migrazione che si limita a creare oggetti prova soltanto che il DDL è
-- sintatticamente valido. Qui si verifica ciò che conta: che il cancello sia
-- CHIUSO. Nel contesto di una migrazione `auth.uid()` è nullo, quindi chi
-- esegue non è un operatore — ed è esattamente il caso che deve essere respinto.
do $$
declare
  v_ok boolean;
begin
  -- 1. Senza identità non si è operatori.
  if public.subsidy_is_catalog_editor() then
    raise exception '0037: autoverifica fallita — senza auth.uid() risulta operatore';
  end if;

  -- 2. La lettura deve SOLLEVARE, non tornare vuota.
  begin
    perform * from public.list_subsidy_catalog_reviews();
    raise exception '0037: autoverifica fallita — la lettura non ha sollevato per un non-operatore';
  exception
    when insufficient_privilege then null;  -- 42501: atteso
  end;

  -- 3. Anche la decisione deve sollevare, e PRIMA di guardare se la riga esiste:
  --    un non-operatore non deve poter scoprire quali id esistono.
  begin
    perform * from public.resolve_subsidy_catalog_review(
      '00000000-0000-0000-0000-000000000000'::uuid, 'accepted', null);
    raise exception '0037: autoverifica fallita — la decisione non ha sollevato per un non-operatore';
  exception
    when insufficient_privilege then null;  -- 42501: atteso
  end;

  -- 4. Le due tabelle NON devono essere raggiungibili da `authenticated`.
  -- ⚠️ `lower(grantee)`: in `information_schema` il grant a PUBLIC compare come
  -- «PUBLIC», maiuscolo. Un confronto con 'public' minuscolo non lo troverebbe
  -- MAI, e questo controllo direbbe sempre di sì — un verde falso che nasconde
  -- esattamente la concessione più pericolosa delle tre.
  select count(*) = 0 into v_ok
    from information_schema.role_table_grants
   where table_schema = 'public'
     and table_name in ('subsidy_catalog_editors', 'subsidy_catalog_reviews')
     and lower(grantee) in ('anon', 'authenticated', 'public');
  if not v_ok then
    raise exception '0037: autoverifica fallita — le tabelle sono ancora concesse al client';
  end if;

  raise notice '0037: autoverifica superata (cancello chiuso, tabelle non concesse)';
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>  0038_subsidy_review_source_url  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0038 — `list_subsidy_catalog_reviews` interrogava una colonna che non esiste.
--
-- IL DIFETTO. La 0037 faceva `left join public.subsidy_sources s … select s.url`.
-- `subsidy_sources` non ha una colonna `url`: ha **`canonical_url`**. Alla prima
-- chiamata vera la funzione rispondeva `42703 column s.url does not exist`.
--
-- ⚠️⚠️ E LA PARTE CHE VALE LA PENA RICORDARE NON È IL REFUSO: È PERCHÉ
-- L'AUTOVERIFICA DELLA 0037 NON POTEVA VEDERLO. Quel blocco provava che il
-- cancello fosse CHIUSO — chiamava la funzione senza `auth.uid()` e verificava
-- che sollevasse 42501. Ma il controllo sull'operatore sta in cima al corpo:
-- sollevando lì, l'esecuzione **non arriva mai al `return query`**. E il corpo di
-- una funzione plpgsql non viene pianificato alla creazione, solo alla prima
-- esecuzione. Quindi quella query non è mai stata né pianificata né eseguita, e
-- l'autoverifica è passata senza toccare la cosa che doveva proteggere.
-- **Un controllo che si ferma prima del codice che verifica è un verde falso.**
--
-- LA CORREZIONE, che toglie il problema invece di correggere la riga. La query
-- diventa una **VISTA**, e una vista PostgreSQL la valida alla creazione: una
-- colonna inesistente fa fallire la migrazione, subito, senza bisogno che
-- qualcuno la chiami. La funzione resta il cancello e non fa altro che leggere
-- dalla vista, così la query esiste in un posto solo.
--
-- ⚠️ La 0037 NON viene modificata: è già applicata, e riscriverla farebbe
-- divergere il file dallo stato reale del database senza che nessuno se ne
-- accorga — `db push` non la rieseguirebbe.
--
-- ⚠️ Ripetibile per costruzione (`create or replace`, `revoke`, `do $$`).
-- ============================================================================

-- ---- La query, in un posto solo e validata alla creazione -------------------

create or replace view public.subsidy_catalog_reviews_expanded as
  select r.id,
         r.program_id,
         p.name              as program_name,
         p.authority         as program_authority,
         p.last_checked_at,
         p.data_status::text as data_status,
         r.change_type,
         r.risk_level,
         r.status,
         r.previous_values,
         r.proposed_values,
         -- ⚠️ `canonical_url`, non `url`: è il nome vero della colonna, e il
         -- fatto che questa vista non si crei se sbaglio è tutta la ragione per
         -- cui la query sta qui e non dentro un corpo plpgsql.
         s.canonical_url     as source_url,
         r.created_at,
         r.reviewed_at,
         r.reviewed_by,
         r.notes
    from public.subsidy_catalog_reviews r
    left join public.subsidy_programs p on p.id = r.program_id
    left join public.subsidy_source_fetches f on f.id = r.source_fetch_id
    left join public.subsidy_sources s on s.id = f.source_id;

comment on view public.subsidy_catalog_reviews_expanded is
  'Uso interno: la query di list_subsidy_catalog_reviews, isolata perché una vista viene validata alla creazione. NON concessa al client.';

-- ⚠️ La vista eredita le colonne di tabelle che il client non può leggere:
-- concederla equivarrebbe a concedere quelle. Resta interna.
revoke all on public.subsidy_catalog_reviews_expanded from anon, authenticated, public;

-- ---- Il cancello, che ora non contiene più la query ------------------------

create or replace function public.list_subsidy_catalog_reviews(
  p_include_resolved boolean default false,
  p_limit integer default 100
)
returns table (
  id                 uuid,
  program_id         text,
  program_name       text,
  program_authority  text,
  last_checked_at    date,
  data_status        text,
  change_type        public.subsidy_review_change_type,
  risk_level         public.subsidy_review_risk,
  status             public.subsidy_review_status,
  previous_values    jsonb,
  proposed_values    jsonb,
  source_url         text,
  created_at         timestamptz,
  reviewed_at        timestamptz,
  reviewed_by        uuid,
  notes              text
)
language plpgsql
security definer
stable
set search_path = ''
as $$
begin
  if not public.subsidy_is_catalog_editor() then
    raise exception 'NOT_CATALOG_EDITOR'
      using errcode = '42501',
            hint = 'Solo gli operatori del catalogo possono leggere le revisioni.';
  end if;

  return query
    select v.id, v.program_id, v.program_name, v.program_authority,
           v.last_checked_at, v.data_status, v.change_type, v.risk_level,
           v.status, v.previous_values, v.proposed_values, v.source_url,
           v.created_at, v.reviewed_at, v.reviewed_by, v.notes
      from public.subsidy_catalog_reviews_expanded v
     where p_include_resolved or v.status = 'pending'
     order by (v.status = 'pending') desc,
              case v.risk_level when 'high' then 0 when 'medium' then 1 else 2 end,
              v.created_at
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end;
$$;

revoke all on function public.list_subsidy_catalog_reviews(boolean, integer) from public;
grant execute on function public.list_subsidy_catalog_reviews(boolean, integer) to authenticated;

-- ---- Autoverifica ----------------------------------------------------------
-- ⚠️ Questa volta ESEGUE la query, che è precisamente ciò che la 0037 non
-- faceva. La vista è già stata validata dalla `create view` qui sopra; qui la
-- si legge davvero, così anche un errore che si manifesta solo in esecuzione
-- (un cast, un tipo) fa fallire la migrazione invece di aspettare un utente.
do $$
declare
  v_n bigint;
  v_ok boolean;
begin
  -- 1. La query si risolve E si esegue.
  select count(*) into v_n from public.subsidy_catalog_reviews_expanded;
  raise notice '0038: la vista si legge — % righe', v_n;

  -- 2. Le colonne che il difetto riguardava esistono e arrivano fino in fondo.
  select count(*) > 0 into v_ok
    from information_schema.columns
   where table_schema = 'public'
     and table_name = 'subsidy_catalog_reviews_expanded'
     and column_name = 'source_url';
  if not v_ok then
    raise exception '0038: autoverifica fallita — la vista non espone source_url';
  end if;

  -- 3. Il cancello è ancora chiuso: la correzione non lo ha allargato.
  begin
    perform * from public.list_subsidy_catalog_reviews();
    raise exception '0038: autoverifica fallita — la lettura non ha sollevato per un non-operatore';
  exception
    when insufficient_privilege then null;  -- 42501: atteso
  end;

  -- 4. Né la vista né le due tabelle sono concesse al client.
  select count(*) = 0 into v_ok
    from information_schema.role_table_grants
   where table_schema = 'public'
     and table_name in ('subsidy_catalog_editors', 'subsidy_catalog_reviews',
                        'subsidy_catalog_reviews_expanded')
     and lower(grantee) in ('anon', 'authenticated', 'public');
  if not v_ok then
    raise exception '0038: autoverifica fallita — qualcosa è concesso al client';
  end if;

  raise notice '0038: autoverifica superata';
end;
$$;

-- >>>>>>>>>>>>>>>>>>>>  0039_audit_logs  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0039 REGISTRO ATTIVITÀ (audit_logs)
--
-- ⚠️ CHE COSA CHIUDE. La vetrina promette che si possa risalire a che cosa il
-- sistema aveva letto e a chi ha corretto che cosa. Oggi quella promessa è vera
-- solo per le analisi documento, grazie alla 0010 (`analysis_corrections` è
-- append-only e attribuita) e per l'Inbox (`email_audit_log`, 0013). Per tutto
-- il resto non esiste un posto in cui leggere, in ordine di tempo, che cosa è
-- successo in azienda e per mano di chi.
--
-- ⚠️⚠️ NON È UNA SECONDA FONTE DI VERITÀ, ED È LA DECISIONE CHE GOVERNA TUTTO
-- IL FILE. `task_events`, `contract_events`, `crm_events`, `email_audit_log`,
-- `analysis_corrections` continuano a esistere e restano i proprietari dei loro
-- fatti: là c'è il DETTAGLIO (i valori corretti, il verbale, la cronologia di
-- una scheda). Qui c'è l'INDICE TRASVERSALE: chi, quando, che cosa, su quale
-- entità — una riga per fatto, la stessa forma per tutti i moduli. Perché non
-- diverga da ciò che indicizza, questo registro NON viene scritto da un
-- servizio: lo scrivono i TRIGGER delle tabelle che possiedono il fatto, nella
-- stessa transazione della scrittura che lo produce.
--
-- È la regola già scritta nella 0020 e qui applicata di nuovo:
--   «Ognuno emette dalla TABELLA che possiede il fatto, e non da un servizio:
--    così l'evento e il fatto stanno nella stessa transazione qualunque sia il
--    percorso che ha scritto il fatto — l'interfaccia, una Edge Function, uno
--    script di manutenzione o una migrazione. Un evento emesso dal codice
--    applicativo avrebbe coperto solo i percorsi a cui qualcuno ha pensato.»
-- Ed è anche il modo in cui «scrittura solo lato server» smette di essere una
-- promessa del client: il client non ha alcun permesso di scrittura su questa
-- tabella, e non può né saltare la registrazione né fabbricarne una.
--
-- ⚠️ CHE COSA NON ENTRA MAI QUI. Niente token, niente password, niente segreti,
-- niente contenuto di documenti. Il payload `changes` non è costruito da un
-- ciclo sulle colonne ma campo per campo, a mano, in ogni trigger: è una LISTA
-- DI AMMESSI e non una lista di vietati. La differenza conta il giorno che
-- qualcuno aggiunge una colonna `access_token` a una tabella sorvegliata — con
-- una lista di vietati finirebbe nel registro finché nessuno se ne accorge, con
-- una lista di ammessi non ci finisce perché nessuno l'ha ammessa.
--
-- ⚠️ IMMUTABILITÀ: DOVE STA DAVVERO. L'UPDATE è vietato da un trigger, e vale
-- per chiunque — service role compreso. Il DELETE NO, ed è una lezione già
-- pagata: la 0023 ha dovuto togliere un divieto di DELETE identico perché
-- rendeva un documento con una fattura INDISTRUTTIBILE (la cascata di
-- cancellazione di un'azienda passa di lì) e perché faceva restare in
-- produzione le aziende dei test. Qui il DELETE è vietato dai PERMESSI: nessun
-- ruolo applicativo — né `anon` né `authenticated` — ha `delete` su questa
-- tabella, e non esiste policy che glielo conceda. Una riga muore solo con la
-- sua azienda, per cascata.
--   Detto senza girarci intorno: la garanzia è «nessun UTENTE può modificare o
--   cancellare una riga». Il service role, che è il server stesso, può
--   cancellare — e affermare il contrario sarebbe falso.
--
-- Requisiti: 0001 (ruoli e helper RLS), 0002 (documenti e analisi), 0006
-- (correzioni e `ai_request_log`), 0016 (attività).
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Il vocabolario: che cosa può essere registrato, e nient'altro
--
-- Enum e non `text`: l'elenco degli eventi è una decisione, e un enum la rende
-- verificabile dal database invece che dalla buona volontà di chi scrive il
-- prossimo trigger. Un'azione non prevista non entra: solleva.
--
-- ⚠️ «Esito analisi» sono DUE azioni e non una con un campo dentro, perché la
-- domanda che le persone fanno al registro è «che cosa è fallito»: un filtro
-- deve poterci rispondere senza aprire il payload di ogni riga.
--
-- ⚠️ Trappola già pagata (0027): un valore aggiunto a un enum NON è usabile
-- nella stessa transazione che lo aggiunge. Qui gli enum NASCONO, e i loro
-- valori compaiono solo dentro corpi di funzione — che vengono analizzati
-- all'esecuzione, non alla creazione. Chi un giorno aggiungerà un'azione ricordi
-- che l'`alter type` va in una migrazione PROPRIA, prima di quella che la usa.
-- ---------------------------------------------------------------------------
do $$ begin
  create type public.audit_action as enum (
    'document_uploaded',
    'document_deleted',
    'analysis_started',
    'analysis_completed',
    'analysis_failed',
    'correction_saved',
    'reply_generated',
    'task_created',
    'task_updated',
    'member_added',
    'member_removed',
    'member_role_changed'
  );
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.audit_entity_type as enum (
    'document',
    'analysis',
    'correction',
    'reply',
    'task',
    'membership'
  );
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 2. La tabella
--
-- ⚠️ NESSUNA CHIAVE ESTERNA SU `entity_id`, `correlation_id` E `actor_user_id`,
-- e non è una dimenticanza. Un registro conserva FATTI STORICI, non puntatori
-- vivi: l'evento «documento eliminato» deve sopravvivere al documento, o
-- registra esattamente l'unica cosa che non potrà più raccontare. Con una
-- chiave esterna la riga sparirebbe in cascata insieme a ciò che descrive.
-- Per la stessa ragione l'autore è l'identificativo che AVEVA chi ha agito:
-- resta leggibile anche se quell'utenza viene cancellata.
--
-- `company_id` invece la chiave esterna ce l'ha, con cascata: il registro è
-- dato del tenant e muore con il tenant. È anche l'unico modo di cancellare
-- davvero un'azienda (§ la lezione della 0023).
--
-- ⚠️ `actor_user_id` NULL significa UNA COSA SOLA: ha scritto il sistema, cioè
-- nessun utente autenticato era in sessione (un worker, una Edge Function con
-- service role, una manutenzione). Non significa «non lo sappiamo». È la stessa
-- disciplina di `action_progress.done_by` nella 0010: un valore di ripiego
-- sarebbe un dato inventato.
-- ---------------------------------------------------------------------------
create table if not exists public.audit_logs (
  id             uuid primary key default gen_random_uuid(),
  company_id     uuid not null references public.companies (id) on delete cascade,
  actor_user_id  uuid,
  action         public.audit_action not null,
  entity_type    public.audit_entity_type not null,
  entity_id      uuid not null,
  -- Forma UNIFORME per ogni evento: { "campo": { "before": …, "after": … } }.
  -- Un campo comparso ha `before` nullo, uno sparito ha `after` nullo — la
  -- stessa convenzione che la schermata di revisione del catalogo già usa per
  -- dire «comparso» e «sparito». Uniforme perché la pagina possa renderlo senza
  -- conoscere l'evento: dodici forme diverse sarebbero dodici rami da tenere
  -- allineati con i trigger.
  changes        jsonb not null default '{}'::jsonb,
  -- Il filo a cui l'evento appartiene: il documento per tutta la sua catena
  -- (caricato → analisi avviata → esito → correzione → risposta → eliminato),
  -- l'attività per la sua, la persona per i cambi di membership. Serve a
  -- leggere una storia invece di una lista, ed è anche la destinazione del
  -- collegamento nella pagina.
  correlation_id uuid not null,
  created_at     timestamptz not null default now()
);

-- La lettura vera della pagina: un'azienda, in ordine di tempo, eventualmente
-- filtrata per azione e per periodo.
create index if not exists idx_audit_company_time on public.audit_logs (company_id, created_at desc);
create index if not exists idx_audit_company_action_time on public.audit_logs (company_id, action, created_at desc);
create index if not exists idx_audit_correlation on public.audit_logs (correlation_id, created_at);

comment on table public.audit_logs is
  'Registro attività trasversale, append-only. Indice dei fatti: il dettaglio resta nelle tabelle che li possiedono (analysis_corrections, task_events, email_audit_log…). Scritto SOLO dai trigger delle tabelle sorgente, mai dal client.';
comment on column public.audit_logs.actor_user_id is
  'Chi ha agito. NULL = il sistema (nessun utente autenticato), mai «non lo sappiamo». Nessuna chiave esterna: è un fatto storico, non un puntatore vivo.';
comment on column public.audit_logs.changes is
  'Solo campi AMMESSI esplicitamente da ciascun trigger, nella forma {campo:{before,after}}. Mai segreti, mai contenuto di documenti.';
comment on column public.audit_logs.correlation_id is
  'Il filo dell''evento: documento, attività o persona. Lega fra loro avvio e esito di una stessa analisi.';

-- ---------------------------------------------------------------------------
-- 3. Non si modifica. Per chiunque, service role compreso.
--
-- Il divieto di UPDATE sta in un trigger e non nei permessi perché deve valere
-- anche per il server: un registro che il server può riscrivere non è un
-- registro. Il DELETE invece NON è qui — vedi l'intestazione: un divieto di
-- DELETE in un trigger vale anche per la cascata, che non è la scrittura di
-- qualcuno ma la conseguenza di una cancellazione già autorizzata a monte
-- (0023). Il DELETE lo fermano i permessi del punto 4.
-- ---------------------------------------------------------------------------
create or replace function public.audit_logs_immutable()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  raise exception 'audit_log_immutable'
    using errcode = '42501',
          hint = 'Una riga del registro non si modifica: se un fatto nuovo accade, se ne scrive uno nuovo.';
end $$;

drop trigger if exists trg_audit_logs_immutable on public.audit_logs;
create trigger trg_audit_logs_immutable
  before update on public.audit_logs
  for each row execute function public.audit_logs_immutable();

-- ---------------------------------------------------------------------------
-- 4. Permessi e RLS — leggono solo titolari e amministratori
--
-- ⚠️⚠️ `revoke all` PRIMA dei grant, e non è una formalità: su Supabase lo
-- schema `public` ha privilegi predefiniti che concedono tutto ad `anon` e
-- `authenticated`, quindi una `grant select` da sola NON toglie insert, update
-- e delete — li lascia dov'erano. È la trappola del 2026-07-26, e l'unico modo
-- di sapere che è chiusa è provare a scrivere con la chiave anon (lo fa
-- `npm run test:audit`).
--
-- La lettura è di owner e admin, non di ogni membro: il registro dice chi ha
-- fatto che cosa, ed è una informazione sulle PERSONE. `is_company_admin`
-- risponde vero per 'owner' e 'admin' (0001).
-- ---------------------------------------------------------------------------
alter table public.audit_logs enable row level security;

revoke all on public.audit_logs from public;
revoke all on public.audit_logs from anon;
revoke all on public.audit_logs from authenticated;
grant select on public.audit_logs to authenticated;

drop policy if exists audit_select_admin on public.audit_logs;
create policy audit_select_admin on public.audit_logs
  for select to authenticated
  using (public.is_company_admin(company_id));

comment on policy audit_select_admin on public.audit_logs is
  'Solo titolari e amministratori dell''azienda leggono il registro: dice chi ha fatto che cosa, ed è informazione sulle persone.';

-- ---------------------------------------------------------------------------
-- 5. L'unico punto di scrittura
--
-- ⚠️ `security invoker` (predefinito) e `revoke all` dal pubblico: la funzione
-- NON deve essere raggiungibile via PostgREST, o il registro diventerebbe
-- scrivibile dal browser — cioè falsificabile. Funziona lo stesso perché la
-- chiamano solo i trigger del punto 6, che sono `security definer` e quindi
-- girano come proprietario.
--
-- ⚠️⚠️ LA GUARDIA SULLA CASCATA, che è il difetto che questo file avrebbe avuto
-- senza la 0023. Quando si cancella un'AZIENDA, la riga di `companies` sparisce
-- PRIMA che le cascate cancellino documenti, attività e membership: i trigger
-- di quelle tabelle scattano quando l'azienda non c'è più, e il loro insert qui
-- violerebbe la chiave esterna facendo FALLIRE l'intera cancellazione. Il
-- risultato sarebbe un'azienda indistruttibile e, di nuovo, aziende di prova
-- lasciate in produzione. Quindi: se l'azienda non esiste più, non si registra
-- niente — il registro sta morendo con lei in questa stessa transazione.
--   Questa guardia sta QUI, in un posto solo, e non nei sette trigger: la stessa
--   condizione ripetuta sette volte è la stessa condizione dimenticata all'ottavo.
-- ---------------------------------------------------------------------------
create or replace function public.audit_log_write(
  p_company_id     uuid,
  p_actor_user_id  uuid,
  p_action         public.audit_action,
  p_entity_type    public.audit_entity_type,
  p_entity_id      uuid,
  p_changes        jsonb,
  p_correlation_id uuid
)
returns void
language plpgsql
set search_path = ''
as $$
begin
  if p_company_id is null or p_entity_id is null or p_correlation_id is null then
    return;                                  -- un fatto senza soggetto non è un fatto
  end if;

  if not exists (select 1 from public.companies c where c.id = p_company_id) then
    return;                                  -- l'azienda si sta cancellando: vedi sopra
  end if;

  insert into public.audit_logs
    (company_id, actor_user_id, action, entity_type, entity_id, changes, correlation_id)
  values
    (p_company_id, p_actor_user_id, p_action, p_entity_type, p_entity_id,
     coalesce(p_changes, '{}'::jsonb), p_correlation_id);
end $$;

revoke all on function public.audit_log_write(uuid, uuid, public.audit_action, public.audit_entity_type, uuid, jsonb, uuid) from public;

comment on function public.audit_log_write(uuid, uuid, public.audit_action, public.audit_entity_type, uuid, jsonb, uuid) is
  'Unico punto di scrittura del registro. Non eseguibile dai ruoli applicativi: la chiamano i trigger, che girano come proprietario.';

-- Coppia prima/dopo nella forma uniforme. Il testo viene TRONCATO: un registro
-- si legge a colpo d'occhio, e una descrizione di duemila caratteri dentro una
-- riga non la legge nessuno. Il valore corrente resta sulla sua tabella.
create or replace function public.audit_pair(p_before text, p_after text)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select jsonb_build_object(
    'before', case when p_before is null then null::jsonb else to_jsonb(left(p_before, 160)) end,
    'after',  case when p_after  is null then null::jsonb else to_jsonb(left(p_after,  160)) end
  );
$$;

comment on function public.audit_pair(text, text) is
  'Coppia {before,after} troncata a 160 caratteri: il registro racconta il cambiamento, non conserva il contenuto.';

-- ---------------------------------------------------------------------------
-- 6. I trigger, uno per fatto
--
-- Tutti `security definer`: il ruolo che scrive il fatto (`authenticated` dal
-- browser, `service_role` da una Edge Function) non ha e non deve avere
-- permessi su `audit_logs`. Tutti con `set search_path = ''`, e ognuno
-- costruisce a mano il proprio payload.
--
-- ⚠️ Perché non un unico trigger generico su tutte le tabelle: un trigger
-- generico dovrebbe decidere a runtime quali colonne sono pubblicabili, cioè
-- proprio la decisione che qui si vuole scritta e leggibile una per una.
-- ---------------------------------------------------------------------------

-- (a) Documento caricato.
--     Autore: chi è in sessione; se scrive il sistema (sincronizzazione email),
--     l'autore è quello che il documento stesso dichiara.
create or replace function public.audit_on_document_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.audit_log_write(
    new.company_id,
    coalesce(auth.uid(), new.uploaded_by),
    'document_uploaded'::public.audit_action,
    'document'::public.audit_entity_type,
    new.id,
    jsonb_build_object(
      'title',       public.audit_pair(null, new.title),
      'filename',    public.audit_pair(null, new.original_filename),
      'mime_type',   public.audit_pair(null, new.mime_type),
      'file_size',   public.audit_pair(null, new.file_size::text),
      'source_type', public.audit_pair(null, new.source_type::text)
    ),
    new.id
  );
  return new;
end $$;

drop trigger if exists trg_audit_document_insert on public.documents;
create trigger trg_audit_document_insert
  after insert on public.documents
  for each row execute function public.audit_on_document_insert();

-- (b) Documento eliminato. È l'evento per cui il registro NON può avere una
--     chiave esterna verso i documenti: il soggetto non esiste più.
create or replace function public.audit_on_document_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.audit_log_write(
    old.company_id,
    auth.uid(),
    'document_deleted'::public.audit_action,
    'document'::public.audit_entity_type,
    old.id,
    jsonb_build_object(
      'title',    public.audit_pair(old.title, null),
      'filename', public.audit_pair(old.original_filename, null)
    ),
    old.id
  );
  return old;
end $$;

drop trigger if exists trg_audit_document_delete on public.documents;
create trigger trg_audit_document_delete
  after delete on public.documents
  for each row execute function public.audit_on_document_delete();

-- (c) Analisi AVVIATA.
--     La riga di `ai_request_log` prenotata da `try_consume_ai_quota` (0009) è
--     il momento in cui l'analisi comincia, e porta con sé chi l'ha chiesta:
--     quella funzione rifiuta se `auth.uid()` è nullo, quindi l'autore c'è
--     sempre. L'entità è il DOCUMENTO e non l'analisi, perché in questo istante
--     l'analisi non esiste ancora e non ha identità: darle quella della riga di
--     log significherebbe indicare un oggetto che nella pagina non si può aprire.
--
--     ⚠️ CONFINE DICHIARATO: il motore locale deterministico (§60) NON passa da
--     qui — calcola nel browser e scrive direttamente l'analisi. Per quel
--     percorso esiste l'esito e non l'avvio, e i due istanti coincidono. Meglio
--     dirlo che inventare un avvio che nessuno ha registrato.
create or replace function public.audit_on_ai_request_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.kind is distinct from 'analysis' or new.document_id is null then
    return new;
  end if;

  perform public.audit_log_write(
    new.company_id,
    new.user_id,
    'analysis_started'::public.audit_action,
    'document'::public.audit_entity_type,
    new.document_id,
    jsonb_build_object(
      'provider', public.audit_pair(null, new.provider),
      'model',    public.audit_pair(null, new.model)
    ),
    new.document_id
  );
  return new;
end $$;

drop trigger if exists trg_audit_ai_request_insert on public.ai_request_log;
create trigger trg_audit_ai_request_insert
  after insert on public.ai_request_log
  for each row execute function public.audit_on_ai_request_insert();

-- (d) ESITO dell'analisi — riuscita o fallita.
--     Qui l'entità è l'analisi, che ora esiste. Copre ENTRAMBI i motori, perché
--     entrambi scrivono su questa tabella: è di nuovo la regola della 0020.
--     L'autore è nullo quando scrive la Edge Function con service role: chi
--     aveva chiesto l'analisi sta nell'evento di avvio, legato dallo stesso
--     `correlation_id`.
create or replace function public.audit_on_analysis_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.audit_log_write(
    new.company_id,
    auth.uid(),
    case when new.analysis_status = 'failed'::public.analysis_status
      then 'analysis_failed'::public.audit_action
      else 'analysis_completed'::public.audit_action
    end,
    'analysis'::public.audit_entity_type,
    new.id,
    jsonb_build_object(
      'status',     public.audit_pair(null, new.analysis_status::text),
      'engine',     public.audit_pair(null, new.engine),
      'provider',   public.audit_pair(null, new.provider),
      'model',      public.audit_pair(null, new.model),
      -- Il CODICE dell'errore, non il messaggio: il codice è un vocabolario
      -- chiuso e traducibile, il messaggio è testo che nessuno ha sanificato.
      'error_code', public.audit_pair(null, new.error_code)
    ),
    new.document_id
  );
  return new;
end $$;

drop trigger if exists trg_audit_analysis_insert on public.document_analyses;
create trigger trg_audit_analysis_insert
  after insert on public.document_analyses
  for each row execute function public.audit_on_analysis_insert();

-- (e) Correzione manuale.
--     ⚠️ SI REGISTRA QUALE CAMPO È STATO CORRETTO, NON I DUE VALORI. I valori
--     di una correzione sono dati LETTI DAL DOCUMENTO — mittente, scadenza,
--     importo — e questo registro non conserva contenuto di documenti. Restano
--     dove sono sempre stati e dove la scheda del documento li mostra già:
--     `analysis_corrections`, append-only e attribuita dalla 0010. Il registro
--     dice chi, quando e su che cosa; il «da → a» si legge un clic più in là.
create or replace function public.audit_on_correction_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.audit_log_write(
    new.company_id,
    coalesce(auth.uid(), new.corrected_by),
    'correction_saved'::public.audit_action,
    'correction'::public.audit_entity_type,
    new.id,
    jsonb_build_object('field', public.audit_pair(null, new.field)),
    new.document_id
  );
  return new;
end $$;

drop trigger if exists trg_audit_correction_insert on public.analysis_corrections;
create trigger trg_audit_correction_insert
  after insert on public.analysis_corrections
  for each row execute function public.audit_on_correction_insert();

-- (f) Risposta generata. Mai il testo: solo come è stata prodotta.
--     Le modifiche a mano di una bozza NON sono in elenco e non producono
--     eventi: l'elenco degli eventi è quello deciso, e allargarlo di nascosto
--     sarebbe la stessa cosa che restringerlo.
create or replace function public.audit_on_reply_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.audit_log_write(
    new.company_id,
    coalesce(auth.uid(), new.created_by),
    'reply_generated'::public.audit_action,
    'reply'::public.audit_entity_type,
    new.id,
    jsonb_build_object(
      'language', public.audit_pair(null, new.language),
      'tone',     public.audit_pair(null, new.tone),
      'provider', public.audit_pair(null, new.provider),
      'model',    public.audit_pair(null, new.model)
    ),
    new.document_id
  );
  return new;
end $$;

drop trigger if exists trg_audit_reply_insert on public.document_replies;
create trigger trg_audit_reply_insert
  after insert on public.document_replies
  for each row execute function public.audit_on_reply_insert();

-- (g) Attività creata.
create or replace function public.audit_on_task_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.audit_log_write(
    new.company_id,
    coalesce(auth.uid(), new.created_by),
    'task_created'::public.audit_action,
    'task'::public.audit_entity_type,
    new.id,
    jsonb_build_object(
      'title',    public.audit_pair(null, new.title),
      'status',   public.audit_pair(null, new.status::text),
      'priority', public.audit_pair(null, new.priority::text),
      'due_date', public.audit_pair(null, new.due_date::text),
      'assignee', public.audit_pair(null, new.assignee_user_id::text)
    ),
    new.id
  );
  return new;
end $$;

drop trigger if exists trg_audit_task_insert on public.tasks;
create trigger trg_audit_task_insert
  after insert on public.tasks
  for each row execute function public.audit_on_task_insert();

-- (h) Attività modificata.
--     ⚠️ SOLO SE È CAMBIATO QUALCOSA CHE SI SORVEGLIA. Un update che tocca solo
--     `updated_at` non è un fatto, e registrarlo riempirebbe il registro di
--     righe che non raccontano niente — che è il modo in cui un registro smette
--     di essere letto.
--     ⚠️ `description` NON è sorvegliata, ed è una scelta: è testo libero e
--     lungo, illeggibile dentro una riga di registro. Il testo corrente sta
--     sull'attività.
create or replace function public.audit_on_task_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_changes jsonb := '{}'::jsonb;
begin
  if new.title is distinct from old.title then
    v_changes := v_changes || jsonb_build_object('title', public.audit_pair(old.title, new.title));
  end if;
  if new.status is distinct from old.status then
    v_changes := v_changes || jsonb_build_object('status', public.audit_pair(old.status::text, new.status::text));
  end if;
  if new.priority is distinct from old.priority then
    v_changes := v_changes || jsonb_build_object('priority', public.audit_pair(old.priority::text, new.priority::text));
  end if;
  if new.due_date is distinct from old.due_date then
    v_changes := v_changes || jsonb_build_object('due_date', public.audit_pair(old.due_date::text, new.due_date::text));
  end if;
  if new.assignee_user_id is distinct from old.assignee_user_id then
    v_changes := v_changes || jsonb_build_object('assignee', public.audit_pair(old.assignee_user_id::text, new.assignee_user_id::text));
  end if;
  if new.archived_at is distinct from old.archived_at then
    v_changes := v_changes || jsonb_build_object('archived_at', public.audit_pair(old.archived_at::text, new.archived_at::text));
  end if;

  if v_changes = '{}'::jsonb then
    return new;
  end if;

  perform public.audit_log_write(
    new.company_id,
    auth.uid(),
    'task_updated'::public.audit_action,
    'task'::public.audit_entity_type,
    new.id,
    v_changes,
    new.id
  );
  return new;
end $$;

drop trigger if exists trg_audit_task_update on public.tasks;
create trigger trg_audit_task_update
  after update on public.tasks
  for each row execute function public.audit_on_task_update();

-- (i) Membership e ruoli.
--     Il filo (`correlation_id`) è la PERSONA e non la riga di membership:
--     chi viene tolto e poi rimesso ha una riga nuova ma è la stessa persona, e
--     la storia che interessa è la sua.
create or replace function public.audit_on_member_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform public.audit_log_write(
      new.company_id, auth.uid(),
      'member_added'::public.audit_action,
      'membership'::public.audit_entity_type,
      new.id,
      jsonb_build_object(
        'user', public.audit_pair(null, new.user_id::text),
        'role', public.audit_pair(null, new.role::text)
      ),
      new.user_id
    );
    return new;
  end if;

  if tg_op = 'DELETE' then
    perform public.audit_log_write(
      old.company_id, auth.uid(),
      'member_removed'::public.audit_action,
      'membership'::public.audit_entity_type,
      old.id,
      jsonb_build_object(
        'user', public.audit_pair(old.user_id::text, null),
        'role', public.audit_pair(old.role::text, null)
      ),
      old.user_id
    );
    return old;
  end if;

  -- UPDATE: solo il ruolo è un fatto. Cambiare azienda o persona a una riga di
  -- membership non è previsto da nessun percorso, e se accadesse non sarebbe un
  -- «cambio di ruolo»: non si registra sotto un nome che non gli appartiene.
  if new.role is distinct from old.role then
    perform public.audit_log_write(
      new.company_id, auth.uid(),
      'member_role_changed'::public.audit_action,
      'membership'::public.audit_entity_type,
      new.id,
      jsonb_build_object(
        'user', public.audit_pair(new.user_id::text, new.user_id::text),
        'role', public.audit_pair(old.role::text, new.role::text)
      ),
      new.user_id
    );
  end if;
  return new;
end $$;

drop trigger if exists trg_audit_member_change on public.company_members;
create trigger trg_audit_member_change
  after insert or update or delete on public.company_members
  for each row execute function public.audit_on_member_change();

-- >>>>>>>>>>>>>>>>>>>>  0040_deadline_nature  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0040 — UNA DATA DICHIARA CHE COSA È
--
-- ⚠️⚠️ IL CASO. «Comune di Lugano — Controllo tassa rifiuti» mostrava
-- «Scadenza 10.09.2026 · fra 26 giorni · affidabilità ALTA». La citazione a
-- supporto era esatta e verificata: «Il sopralluogo è previsto per il
-- 10.09.2026 presso la vostra sede». La data era giusta, la citazione era
-- giusta, il campo era sbagliato — una data di sopralluogo è il giorno in cui
-- un evento ACCADE, non il termine entro cui l'azienda deve agire. Da quel
-- campo sono nate tre attività, tutte datate 10.09.2026.
--
-- Le due guardie esistenti non potevano vederlo: "deadline_type" dice che
-- FORMA ha la data (assoluta/relativa), "obligesCompany" (2026-08-11) dice CHI
-- è obbligato — e da un sopralluogo l'azienda è coinvolta davvero. Mancava la
-- terza domanda: CHE COSA è quella data.
--
--   deadline_kind      term | event | reference | none  — null = mai dichiarato
--   appointment_date   la data in cui accade l'evento, in una colonna SUA
--
-- ⚠️ PERCHÉ UNA COLONNA SUA E NON UN FLAG ACCANTO A "deadline": un flag lo si
-- dimentica. "deadline" è letta da list_documents, dalle automazioni
-- (analysis.deadline), da Finanze, dall'assistente e da chi crea un'attività da
-- un documento: basta un lettore che ignori il flag perché la data
-- dell'appuntamento torni a essere un termine. Una colonna diversa non si
-- legge per sbaglio.
--
-- ⚠️ NESSUN AGGIORNAMENTO DELLE RIGHE ESISTENTI, ED È DELIBERATO. L'analisi è
-- un verbale immutabile (0010): scrivere oggi deadline_kind = 'event' su una
-- riga del 26 luglio metterebbe in bocca al modello una risposta che il modello
-- non ha mai dato. Le righe anteriori restano con deadline_kind NULL, e la
-- LETTURA sa che cosa farne: deadlineNature.ts dichiara «da verificare» ogni
-- scadenza la cui natura non è mai stata stabilita. È la lezione già pagata due
-- volte — una regola applicata solo in scrittura non protegge i dati già
-- scritti.
--
-- ⚠️⚠️ ORDINE DI APPLICAZIONE — PRIMA QUESTA, POI LA FUNZIONE.
-- `analyze-document` è l'unica Edge Function che scrive un'analisi, e da questo
-- lavoro in poi la sua riga contiene `deadline_kind` e `appointment_date`.
-- Deployarla PRIMA di applicare questa migrazione fa fallire OGNI analisi con
-- un errore di colonna inesistente (verificato il 2026-08-15: la colonna oggi
-- non c'è, e PostgREST risponde 42703). Non è un guasto silenzioso — l'analisi
-- si dichiara fallita e il documento resta — ma è un fermo evitabile.
-- Il frontend invece regge in entrambi gli ordini: legge con `select *` e con
-- `list_documents`, e una colonna assente vale «natura non dichiarata», cioè
-- «da verificare».
-- ============================================================================

alter table public.document_analyses add column if not exists deadline_kind text;              -- term | event | reference | none
alter table public.document_analyses add column if not exists appointment_date date;
alter table public.document_analyses add column if not exists appointment_evidence jsonb;
alter table public.document_analyses add column if not exists appointment_source_text text;

comment on column public.document_analyses.deadline_kind is
  'Natura della data estratta: term | event | reference | none. NULL = analisi anteriore al 2026-08-15, natura mai dichiarata: in lettura vale «da verificare», non «termine».';
comment on column public.document_analyses.appointment_date is
  'Data in cui accade un evento che coinvolge l''azienda (sopralluogo, udienza, ritiro). NON è una scadenza e non deve mai alimentare un termine.';

-- Un appuntamento si cerca come si cerca una scadenza: per data.
create index if not exists idx_analyses_appointment on public.document_analyses (appointment_date);

-- ---------------------------------------------------------------------------
-- list_documents — due colonne in più.
--
-- ⚠️ "drop" e non "create or replace": cambia la RETURNS TABLE, e Postgres non
-- sostituisce una funzione che cambia tipo di ritorno. I permessi se ne vanno
-- col drop e vanno riassegnati sotto — dimenticarlo lascerebbe la lista
-- documenti muta per chiunque.
--
-- ⚠️ QUI SI PORTANO GLI INGREDIENTI, NON SI CALCOLA LA REGOLA.
-- "deadline_requires_verification" resta il flag GREZZO scritto dal validatore;
-- il «da verificare» effettivo (grezzo OPPURE natura mai dichiarata) lo calcola
-- deadlineNature.ts, in un posto solo, per tutti i lettori. Riscriverlo anche
-- qui creerebbe una seconda fonte di verità, e due copie della stessa regola
-- col tempo divergono.
-- ---------------------------------------------------------------------------
drop function if exists public.list_documents(uuid, text, public.document_category, boolean, public.document_source_type, text, uuid[], date, date, boolean, boolean, text, integer, integer, uuid);

create or replace function public.list_documents(
  p_company_id      uuid,
  p_query           text default null,
  p_category        public.document_category default null,
  p_uncategorized   boolean default false,
  p_source          public.document_source_type default null,
  p_state           text default null,      -- to_verify | analyzed | failed | processing | none
  p_tag_ids         uuid[] default null,
  p_date_from       date default null,
  p_date_to         date default null,
  p_has_deadline    boolean default false,
  p_archived        boolean default false,
  p_sort            text default 'recent',  -- recent | oldest | document_date | title | deadline
  p_limit           integer default 25,
  p_offset          integer default 0,
  -- Un solo documento. Serve al DETTAGLIO, e non è una comodità: la riga della
  -- lista e la testata del dettaglio devono dire la stessa cosa sullo stesso
  -- documento — stessa analisi scelta, stesse correzioni applicate. Con due
  -- implementazioni diverse prima o poi divergono, e a divergere sarebbero
  -- proprio mittente e scadenza.
  p_document_id     uuid default null
)
returns table (
  id uuid,
  title text,
  original_filename text,
  mime_type text,
  file_size bigint,
  storage_path text,
  source_type public.document_source_type,
  status public.document_status,
  page_count integer,
  created_at timestamptz,
  archived_at timestamptz,
  category public.document_category,
  category_source public.document_category_source,
  analysis_id uuid,
  analysis_status public.analysis_status,
  last_attempt_failed boolean,
  error_code text,
  document_type text,
  document_type_corrected boolean,
  sender text,
  sender_corrected boolean,
  sender_authority_type text,
  document_date date,
  deadline date,
  deadline_corrected boolean,
  deadline_requires_verification boolean,
  deadline_kind text,
  appointment_date date,
  amount numeric,
  amount_currency text,
  amount_corrected boolean,
  confidence text,
  tags jsonb,
  open_task_count bigint,
  task_count bigint,
  email_count bigint,
  snippet text,
  total_count bigint
)
language sql
stable
set search_path = ''
as $$
  with params as (
    select
      -- I caratteri jolly digitati da una persona devono cercare sé stessi:
      -- un `%` in una ricerca è un per cento, non «qualsiasi cosa».
      nullif(btrim(left(coalesce(p_query, ''), 120)), '') as q,
      replace(replace(replace(
        btrim(left(coalesce(p_query, ''), 120)), '\', '\\'), '%', '\%'), '_', '\_') as q_like
  ),
  base as (
    select
      d.*,
      -- L'ULTIMO tentativo: dice lo STATO, anche quando è un fallimento.
      last_try.id            as try_id,
      last_try.analysis_status as try_status,
      last_try.error_code    as try_error,
      -- L'ultima analisi VALIDA: dice il CONTENUTO. Se l'ultimo tentativo è
      -- fallito ma prima esisteva un risultato buono, quel risultato non
      -- scompare — è la stessa regola di `analysisService.getForDocument`,
      -- e averne due diverse farebbe dire due cose alla stessa schermata.
      good.id                as good_id,
      good.document_type     as a_document_type,
      good.sender            as a_sender,
      good.sender_authority_type as a_authority,
      good.document_date     as a_document_date,
      good.deadline          as a_deadline,
      good.deadline_requires_verification as a_deadline_verify,
      good.deadline_kind     as a_deadline_kind,
      good.appointment_date  as a_appointment,
      good.amount            as a_amount,
      good.amount_currency   as a_currency,
      good.confidence        as a_confidence,
      corr.v                 as corrections,
      count(*) over ()       as n_total
    from public.documents d
    left join lateral (
      select a.id, a.analysis_status, a.error_code
      from public.document_analyses a
      -- Il confronto sull'azienda accompagna la RLS, non la sostituisce: è la
      -- disciplina di questo progetto, e qui evita anche che un'analisi
      -- agganciata per errore a un documento altrui possa mai essere letta.
      where a.document_id = d.id and a.company_id = d.company_id
      order by a.created_at desc, a.id desc
      limit 1
    ) last_try on true
    left join lateral (
      select a.*
      from public.document_analyses a
      where a.document_id = d.id and a.company_id = d.company_id
        and a.analysis_status <> 'failed'
      order by a.created_at desc, a.id desc
      limit 1
    ) good on true
    left join lateral (
      -- Un solo passaggio sulle correzioni del documento: le più recenti
      -- sovrascrivono le precedenti perché `jsonb_object_agg` tiene l'ultimo
      -- valore di ogni chiave.
      select jsonb_object_agg(c.field, c.corrected_value) as v
      from (
        select c2.field, c2.corrected_value
        from public.analysis_corrections c2
        where c2.document_id = d.id and c2.company_id = d.company_id
        order by c2.corrected_at asc
      ) c
    ) corr on true
    where d.company_id = p_company_id
      -- Sottointerrogazione scalare: l'appartenenza si verifica UNA volta per
      -- interrogazione e non una volta per riga.
      and (select public.is_company_member(p_company_id))
      and (p_document_id is null or d.id = p_document_id)
      -- Chiedendo UN documento non si applica il filtro di archiviazione: il suo
      -- indirizzo deve funzionare anche dopo che è stato archiviato, altrimenti
      -- «archivia» diventerebbe indistinguibile da «fai sparire».
      and (p_document_id is not null
           or (case when p_archived then d.archived_at is not null else d.archived_at is null end))
      and (p_category is null or d.category = p_category)
      and (not p_uncategorized or d.category is null)
      and (p_source is null or d.source_type = p_source)
      and (p_tag_ids is null or array_length(p_tag_ids, 1) is null or exists (
            select 1 from public.document_tag_links l
            where l.document_id = d.id and l.company_id = d.company_id
              and l.tag_id = any (p_tag_ids)
          ))
      and (not p_has_deadline or coalesce(
            public.try_date(corr.v ->> 'deadline'), good.deadline) is not null)
      and (p_date_from is null or coalesce(
            public.try_date(corr.v ->> 'document_date'), good.document_date,
            d.created_at::date) >= p_date_from)
      and (p_date_to is null or coalesce(
            public.try_date(corr.v ->> 'document_date'), good.document_date,
            d.created_at::date) <= p_date_to)
      and (
        p_state is null
        or (p_state = 'failed'     and last_try.analysis_status = 'failed')
        or (p_state = 'to_verify'  and last_try.analysis_status = 'needs_review')
        or (p_state = 'analyzed'   and last_try.analysis_status = 'completed')
        -- «In elaborazione» è uno stato del DOCUMENTO, non dell'analisi: fra il
        -- caricamento e la prima riga di analisi non esiste ancora nulla da
        -- interrogare, ed è proprio il momento in cui una persona si chiede
        -- dove sia finito il suo file.
        or (p_state = 'processing' and d.status in ('extracting', 'analyzing', 'processing'))
        or (p_state = 'none'       and last_try.id is null
              and d.status not in ('extracting', 'analyzing', 'processing'))
      )
      and (
        (select q from params) is null
        or d.title ilike '%' || (select q_like from params) || '%'
        or coalesce(d.original_filename, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.sender, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.subject, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.recipient, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.document_type, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(good.reference_numbers::text, '') ilike '%' || (select q_like from params) || '%'
        or coalesce(corr.v::text, '') ilike '%' || (select q_like from params) || '%'
        or exists (
             select 1 from public.document_tag_links l
             join public.document_tags g on g.id = l.tag_id and g.company_id = l.company_id
             where l.document_id = d.id and l.company_id = d.company_id
               and g.name ilike '%' || (select q_like from params) || '%'
           )
        or exists (
             select 1 from public.document_extractions e
             where e.document_id = d.id and e.company_id = d.company_id
               and e.search_tsv @@ plainto_tsquery('simple'::regconfig, (select q from params))
           )
      )
    order by
      case when p_sort = 'oldest' then d.created_at end asc nulls last,
      case when p_sort = 'title' then lower(d.title) end asc nulls last,
      case when p_sort = 'document_date'
           then coalesce(public.try_date(corr.v ->> 'document_date'), good.document_date) end desc nulls last,
      case when p_sort = 'deadline'
           then coalesce(public.try_date(corr.v ->> 'deadline'), good.deadline) end asc nulls last,
      case when p_sort in ('oldest', 'title', 'document_date', 'deadline')
           then null else d.created_at end desc nulls last,
      -- Ultimo criterio SEMPRE presente: senza, due righe uguali possono
      -- scambiarsi di posto fra una pagina e l'altra.
      d.id desc
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    offset greatest(0, coalesce(p_offset, 0))
  )
  select
    b.id, b.title, b.original_filename, b.mime_type, b.file_size, b.storage_path,
    b.source_type, b.status, b.page_count, b.created_at, b.archived_at,
    b.category, b.category_source,
    coalesce(b.good_id, b.try_id) as analysis_id,
    b.try_status as analysis_status,
    -- `coalesce` fino in fondo: senza analisi queste espressioni valgono NULL, e
    -- un NULL che arriva al posto di un «no» diventa, nel browser, un «forse».
    coalesce(b.try_status = 'failed' and b.good_id is not null, false) as last_attempt_failed,
    b.try_error as error_code,
    -- Valore EFFETTIVO: la correzione umana se c'è, altrimenti il dato
    -- dell'analisi. Il valore originale dell'AI non viene toccato e resta
    -- leggibile nel dettaglio: qui si mostra ciò che l'azienda ritiene vero.
    coalesce(b.corrections ->> 'document_type', b.a_document_type) as document_type,
    coalesce(b.corrections ? 'document_type', false) as document_type_corrected,
    coalesce(b.corrections ->> 'sender', b.a_sender) as sender,
    coalesce(b.corrections ? 'sender', false) as sender_corrected,
    b.a_authority as sender_authority_type,
    coalesce(public.try_date(b.corrections ->> 'document_date'), b.a_document_date) as document_date,
    coalesce(public.try_date(b.corrections ->> 'deadline'), b.a_deadline) as deadline,
    coalesce(b.corrections ? 'deadline', false) as deadline_corrected,
    coalesce(b.a_deadline_verify, false) as deadline_requires_verification,
    b.a_deadline_kind as deadline_kind,
    b.a_appointment   as appointment_date,
    coalesce(public.try_numeric(b.corrections ->> 'amount'), b.a_amount) as amount,
    b.a_currency as amount_currency,
    coalesce(b.corrections ? 'amount', false) as amount_corrected,
    b.a_confidence as confidence,
    coalesce(tg.v, '[]'::jsonb) as tags,
    coalesce(tk.open_count, 0) as open_task_count,
    coalesce(tk.all_count, 0) as task_count,
    coalesce(em.n, 0) as email_count,
    -- L'estratto si calcola SOLO sulle righe che si mostrano davvero, ed è
    -- testo semplice: i due delimitatori li interpreta React costruendo
    -- elementi, non inserendo HTML. Nel Document Hub non esiste markup
    -- proveniente da un documento.
    case
      when (select q from params) is null then null
      else (
        -- I delimitatori sono fra virgolette perché l'elenco delle opzioni è
        -- separato da virgole: un valore non quotato che contiene caratteri
        -- speciali verrebbe interpretato male.
        select ts_headline('simple'::regconfig, left(coalesce(e.full_text, ''), 500000),
                 plainto_tsquery('simple'::regconfig, (select q from params)),
                 'StartSel="[[", StopSel="]]", MaxWords=22, MinWords=8, MaxFragments=1')
        from public.document_extractions e
        where e.document_id = b.id and e.company_id = b.company_id
          and e.search_tsv @@ plainto_tsquery('simple'::regconfig, (select q from params))
        limit 1
      )
    end as snippet,
    b.n_total as total_count
  from base b
  left join lateral (
    select jsonb_agg(jsonb_build_object('id', g.id, 'name', g.name) order by g.name) as v
    from public.document_tag_links l
    join public.document_tags g on g.id = l.tag_id and g.company_id = l.company_id
    where l.document_id = b.id and l.company_id = b.company_id
  ) tg on true
  left join lateral (
    select
      count(*) filter (where t.status <> 'completed' and t.archived_at is null) as open_count,
      count(*) as all_count
    from public.tasks t where t.document_id = b.id and t.company_id = b.company_id
  ) tk on true
  left join lateral (
    select count(*) as n
    from public.email_message_documents m
    where m.document_id = b.id and m.company_id = b.company_id
  ) em on true
  -- Lo stesso ordine della selezione, espressione per espressione. Ordinare
  -- l'esterno in modo diverso dall'interno vorrebbe dire scegliere venticinque
  -- righe secondo un criterio e mostrarle secondo un altro: la pagina due non
  -- verrebbe dopo la pagina uno.
  order by
    case when p_sort = 'oldest' then b.created_at end asc nulls last,
    case when p_sort = 'title' then lower(b.title) end asc nulls last,
    case when p_sort = 'document_date'
         then coalesce(public.try_date(b.corrections ->> 'document_date'), b.a_document_date) end desc nulls last,
    case when p_sort = 'deadline'
         then coalesce(public.try_date(b.corrections ->> 'deadline'), b.a_deadline) end asc nulls last,
    case when p_sort in ('oldest', 'title', 'document_date', 'deadline')
         then null else b.created_at end desc nulls last,
    b.id desc;
$$;
revoke all on function public.list_documents(uuid, text, public.document_category, boolean, public.document_source_type, text, uuid[], date, date, boolean, boolean, text, integer, integer, uuid) from public, anon;
grant execute on function public.list_documents(uuid, text, public.document_category, boolean, public.document_source_type, text, uuid[], date, date, boolean, boolean, text, integer, integer, uuid) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  0041_task_appointment  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0041 — UN'ATTIVITÀ PUÒ AVERE UN APPUNTAMENTO SENZA AVERE UN TERMINE
--
-- ⚠️⚠️ IL SEGUITO DELLA 0040. Là si è stabilito che la data di un sopralluogo
-- non è una scadenza e le si è dato un posto suo sull'ANALISI. Restava scoperto
-- il pezzo di mondo in cui il difetto si era manifestato davvero: le ATTIVITÀ.
-- Dal sopralluogo del Comune di Lugano ne erano nate tre, tutte datate
-- 10.09.2026, che è la data in cui il Comune si presenta — non il giorno entro
-- cui l'azienda deve aver preparato i giustificativi.
--
-- Tolta quella data (2026-08-15), le tre attività sono diventate «Nessuna
-- scadenza»: non mentivano più, e avevano perso un'informazione vera. Un lavoro
-- che va fatto PRIMA del 10.09.2026 non è un lavoro senza tempo.
--
--   appointment_date   il giorno dell'evento a cui il lavoro si riferisce.
--                      NON è un termine e non deve mai comportarsi come tale.
--
-- ⚠️ NON POPOLA LE FASCE DELLO SCADENZIARIO. «Entro 30 giorni», «In scadenza
-- oggi», l'ordinamento per termine e il conto dei ritardi continuano a leggere
-- SOLO "due_date". Se questa colonna vi entrasse anche solo per comodità di
-- ordinamento, avremmo rifatto il difetto con un nome nuovo.
--
-- ⚠️ IL CALENDARIO RESTA FUORI, per scelta e non per dimenticanza.
-- "calendar_tasks" seleziona, ordina e raggruppa per "due_date": farvi entrare
-- gli appuntamenti vuol dire decidere come una casella-giorno mostri due
-- generi di data, ed è una decisione sul calendario, non una correzione di
-- questo difetto. Oggi quelle attività nel calendario non compaiono affatto —
-- il che è corretto: non hanno un termine.
--
-- ⚠️ UNA COPIA, NON UNA SECONDA FONTE. Il valore arriva da
-- "document_analyses.appointment_date" al momento in cui l'attività nasce, ed è
-- una derivazione UNA TANTUM esattamente come "due_date" lo è già da
-- "document_analyses.deadline": da lì in poi le due liste non si inseguono. È
-- il disegno che questo prodotto ha scelto per le attività, non una deroga
-- introdotta qui.
-- ============================================================================

alter table public.tasks add column if not exists appointment_date date;

comment on column public.tasks.appointment_date is
  'Giorno dell''evento a cui il lavoro si riferisce (sopralluogo, udienza, ritiro). NON è un termine: non entra nelle fasce dello scadenziario né nel conto dei ritardi.';

-- Si cerca come si cerca un termine: per data.
create index if not exists idx_tasks_appointment on public.tasks (appointment_date)
  where appointment_date is not null;

-- ---------------------------------------------------------------------------
-- Il registro sorveglia anche questa data.
--
-- ⚠️ Se non la sorvegliasse, spostare un appuntamento sarebbe l'unico modo di
-- cambiare quando un lavoro va fatto senza lasciare traccia — e le tre righe
-- del Comune sono già state corrette una volta a mano.
-- "create or replace" basta: la firma non cambia, il trigger resta agganciato.
-- ---------------------------------------------------------------------------
create or replace function public.audit_on_task_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_changes jsonb := '{}'::jsonb;
begin
  if new.title is distinct from old.title then
    v_changes := v_changes || jsonb_build_object('title', public.audit_pair(old.title, new.title));
  end if;
  if new.status is distinct from old.status then
    v_changes := v_changes || jsonb_build_object('status', public.audit_pair(old.status::text, new.status::text));
  end if;
  if new.priority is distinct from old.priority then
    v_changes := v_changes || jsonb_build_object('priority', public.audit_pair(old.priority::text, new.priority::text));
  end if;
  if new.due_date is distinct from old.due_date then
    v_changes := v_changes || jsonb_build_object('due_date', public.audit_pair(old.due_date::text, new.due_date::text));
  end if;
  if new.appointment_date is distinct from old.appointment_date then
    v_changes := v_changes || jsonb_build_object('appointment_date', public.audit_pair(old.appointment_date::text, new.appointment_date::text));
  end if;
  if new.assignee_user_id is distinct from old.assignee_user_id then
    v_changes := v_changes || jsonb_build_object('assignee', public.audit_pair(old.assignee_user_id::text, new.assignee_user_id::text));
  end if;
  if new.archived_at is distinct from old.archived_at then
    v_changes := v_changes || jsonb_build_object('archived_at', public.audit_pair(old.archived_at::text, new.archived_at::text));
  end if;

  if v_changes = '{}'::jsonb then
    return new;
  end if;

  perform public.audit_log_write(
    new.company_id,
    auth.uid(),
    'task_updated'::public.audit_action,
    'task'::public.audit_entity_type,
    new.id,
    v_changes,
    new.id
  );
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- list_tasks — una colonna in più.
--
-- ⚠️ "drop" e non "create or replace": cambia la RETURNS TABLE. I permessi se
-- ne vanno col drop e vanno riassegnati sotto — dimenticarlo lascerebbe muto
-- l'elenco delle attività per chiunque.
--
-- ⚠️ NESSUN FILTRO E NESSUN ORDINAMENTO usa la colonna nuova: entra solo fra i
-- valori restituiti. "p_view = 'overdue'", l'ordinamento per termine e il
-- conteggio continuano a guardare "due_date", che è l'unica data che obbliga.
-- ---------------------------------------------------------------------------
drop function if exists public.list_tasks(uuid, text, public.task_status, public.task_priority, public.task_source, uuid, text, integer, integer);

create or replace function public.list_tasks(
  p_company_id  uuid,
  p_view        text default 'todo',      -- todo | mine | overdue | completed | archived | all
  p_status      public.task_status default null,
  p_priority    public.task_priority default null,
  p_source      public.task_source default null,
  p_assignee    uuid default null,
  p_search      text default null,
  p_limit       integer default 25,
  p_offset      integer default 0
)
returns table (
  id uuid, company_id uuid, created_by uuid, document_id uuid, subsidy_case_id uuid,
  title text, description text, authority text, due_date date, appointment_date date,
  priority public.task_priority, status public.task_status, source public.task_source,
  assignee_user_id uuid, completed_at timestamptz, completed_by uuid,
  archived_at timestamptz, archived_by uuid, created_at timestamptz, updated_at timestamptz,
  assignee_name text, email_message_id uuid, total_count bigint
)
language sql
stable
set search_path = ''
as $$
  with filtered as (
    select t.*
    from public.tasks t
    where t.company_id = p_company_id
      -- Le viste. «archived» è l'unica che mostra le archiviate: ovunque
      -- altrove restano fuori, che è il senso dell'archiviazione.
      and case p_view
            when 'todo'      then t.status <> 'completed' and t.archived_at is null
            when 'mine'      then t.assignee_user_id = auth.uid() and t.status <> 'completed' and t.archived_at is null
            when 'overdue'   then t.status <> 'completed' and t.archived_at is null
                                  and t.due_date is not null and t.due_date < current_date
            when 'completed' then t.status = 'completed' and t.archived_at is null
            when 'archived'  then t.archived_at is not null
            else t.archived_at is null
          end
      and (p_status   is null or t.status = p_status)
      and (p_priority is null or t.priority = p_priority)
      and (p_source   is null or t.source = p_source)
      and (p_assignee is null or t.assignee_user_id = p_assignee)
      and (
        p_search is null or btrim(p_search) = ''
        or t.title ilike '%' || btrim(p_search) || '%'
        or coalesce(t.description, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(t.authority, '') ilike '%' || btrim(p_search) || '%'
      )
  )
  select
    f.id, f.company_id, f.created_by, f.document_id, f.subsidy_case_id,
    f.title, f.description, f.authority, f.due_date, f.appointment_date,
    f.priority, f.status, f.source,
    f.assignee_user_id, f.completed_at, f.completed_by,
    f.archived_at, f.archived_by, f.created_at, f.updated_at,
    nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), '') as assignee_name,
    -- La comunicazione da cui nasce, quando il documento collegato viene dalla
    -- posta. Non serve una colonna su `tasks`: la relazione esiste già.
    (select d.email_message_id
       from public.email_message_documents d
      where d.document_id = f.document_id
      order by d.created_at asc
      limit 1) as email_message_id,
    count(*) over () as total_count
  from filtered f
  left join public.profiles p on p.id = f.assignee_user_id
  order by
    -- 1. scadute
    case when f.status <> 'completed' and f.due_date is not null and f.due_date < current_date
         then 0 else 1 end,
    -- 2. priorità alta
    case f.priority when 'high' then 0 when 'medium' then 1 else 2 end,
    -- 3. scadenza più vicina, 4. senza scadenza in fondo
    f.due_date asc nulls last,
    -- 5. a parità di tutto, le più recenti
    f.created_at desc
  limit greatest(1, least(coalesce(p_limit, 25), 100))
  offset greatest(0, coalesce(p_offset, 0));
$$;
revoke all on function public.list_tasks(uuid, text, public.task_status, public.task_priority, public.task_source, uuid, text, integer, integer) from public, anon;
grant execute on function public.list_tasks(uuid, text, public.task_status, public.task_priority, public.task_source, uuid, text, integer, integer) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  0042_calendar_appointments  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0042 — IL CALENDARIO SA CHE UN APPUNTAMENTO NON È UNA SCADENZA
--
-- ⚠️⚠️ IL TERZO PEZZO. La 0040 ha dato una natura alle date estratte, la 0041
-- ha dato alle attività un appuntamento che non è un termine. Restava il
-- calendario, che è il posto in cui un riferimento temporale dovrebbe vedersi
-- più che altrove — e dove invece le tre attività del sopralluogo del Comune di
-- Lugano non comparivano affatto, perché `calendar_tasks` selezionava,
-- ordinava e raggruppava per "due_date" e loro non ne hanno.
--
-- ⚠️ LA DECISIONE CHE QUESTA MIGRAZIONE PRENDE, e va detta: una riga per
-- (attività, genere di data). Un'attività che ha un termine il 5 e un
-- sopralluogo il 10 compare DUE volte, una per giorno, ciascuna col proprio
-- segno. Un calendario risponde a «che cosa succede questo giorno», e in quei
-- due giorni succedono due cose vere e diverse. Sceglierne una avrebbe
-- significato nascondere l'altra proprio nella schermata fatta per vederla.
--
--   on_date     il giorno in cui la riga va collocata
--   date_kind   'deadline' | 'appointment' — PERCHÉ è finita in quel giorno
--
-- ⚠️ Il chiamante non deve dedurre il genere confrontando le date: lo riceve
-- scritto. Dedurlo vorrebbe dire riscrivere questa scelta in ogni lettore, e
-- due copie della stessa deduzione col tempo divergono.
--
-- ⚠️ GLI APPUNTAMENTI NON HANNO RITARDO, e la differenza sta nella clausola:
-- il ramo dei termini raccoglie anche le scadute fuori finestra (è la ragione
-- per cui "p_include_overdue" esiste), quello degli appuntamenti no. Un
-- sopralluogo passato è passato, non mancato: tirarlo dentro la finestra come
-- si fa con una scadenza lo trasformerebbe nell'allarme che non è.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Le attività del calendario, per giorno e per genere di data.
--
-- ⚠️ "drop" e non "create or replace": cambia la RETURNS TABLE. I permessi se
-- ne vanno col drop e vanno riassegnati sotto.
-- ---------------------------------------------------------------------------
drop function if exists public.calendar_tasks(uuid, date, date, boolean, public.task_status, public.task_priority, uuid, boolean, integer);

create or replace function public.calendar_tasks(
  p_company_id      uuid,
  p_from            date,
  p_to              date,
  p_mine            boolean default false,
  p_status          public.task_status default null,
  p_priority        public.task_priority default null,
  p_assignee        uuid default null,
  p_include_overdue boolean default true,
  p_limit           integer default 500
)
returns table (
  id uuid, title text, due_date date, appointment_date date,
  on_date date, date_kind text,
  priority public.task_priority, status public.task_status, source public.task_source,
  assignee_user_id uuid, assignee_name text, document_id uuid
)
language sql
stable
set search_path = ''
as $$
  with base as (
    select
      t.id, t.title, t.due_date, t.appointment_date, t.priority, t.status, t.source,
      t.assignee_user_id, t.document_id, t.created_at,
      nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), '') as assignee_name
    from public.tasks t
    left join public.profiles p on p.id = t.assignee_user_id
    where t.company_id = p_company_id
      and t.archived_at is null
      and (not coalesce(p_mine, false) or t.assignee_user_id = auth.uid())
      and (p_status   is null or t.status = p_status)
      and (p_priority is null or t.priority = p_priority)
      and (p_assignee is null or t.assignee_user_id = p_assignee)
  ),
  placed as (
    -- I TERMINI: la finestra, più le scadute che restano pertinenti.
    select b.*, b.due_date as on_date, 'deadline'::text as date_kind
    from base b
    where b.due_date is not null
      and (
        (b.due_date >= p_from and b.due_date <= p_to)
        -- ⚠️ "<=" e non "<". Il database vive in UTC, l'utente in Europe/Zurich:
        -- alle 00:30 locali di giovedì, per Postgres è ancora mercoledì, e
        -- un'attività scaduta mercoledì non rientrerebbe in "due_date <
        -- current_date". Un giorno di margine costa una riga in più e chiude la
        -- finestra. Qui si SELEZIONA soltanto: che cosa sia «in ritardo» lo
        -- decide "isOverdue()" in taskFormat, la stessa funzione che usano
        -- Attività e Panoramica. Due definizioni di «scaduta» sono due
        -- schermate che prima o poi si contraddicono.
        or (coalesce(p_include_overdue, true)
            and b.status <> 'completed'
            and b.due_date <= current_date)
      )

    union all

    -- GLI APPUNTAMENTI: la finestra e basta. Nessun recupero del passato.
    select b.*, b.appointment_date as on_date, 'appointment'::text as date_kind
    from base b
    where b.appointment_date is not null
      and b.appointment_date >= p_from
      and b.appointment_date <= p_to
  )
  select
    u.id, u.title, u.due_date, u.appointment_date,
    u.on_date, u.date_kind,
    u.priority, u.status, u.source,
    u.assignee_user_id, u.assignee_name, u.document_id
  from placed u
  order by u.on_date asc,
    case u.priority when 'high' then 0 when 'medium' then 1 else 2 end,
    u.created_at desc
  limit greatest(1, least(coalesce(p_limit, 500), 1000));
$$;

revoke all on function public.calendar_tasks(uuid, date, date, boolean, public.task_status, public.task_priority, uuid, boolean, integer) from public, anon;
grant execute on function public.calendar_tasks(uuid, date, date, boolean, public.task_status, public.task_priority, uuid, boolean, integer) to authenticated;

-- ---------------------------------------------------------------------------
-- «Senza data» vuol dire senza NESSUNA delle due.
--
-- ⚠️ Il pannello che usa questo conteggio dice «N attività senza scadenza, non
-- compaiono nel calendario» e rimanda ad Attività. Da adesso un'attività con un
-- appuntamento nel calendario ci compare eccome: continuare a contarla qui
-- farebbe dire alla stessa schermata due cose incompatibili, e quella scritta
-- vincerebbe su quella disegnata.
-- ---------------------------------------------------------------------------
create or replace function public.calendar_undated_count(
  p_company_id uuid,
  p_mine       boolean default true
)
returns integer
language sql
stable
set search_path = ''
as $$
  select count(*)::integer
  from public.tasks t
  where t.company_id = p_company_id
    and t.archived_at is null
    and t.due_date is null
    and t.appointment_date is null
    and t.status <> 'completed'
    and (not coalesce(p_mine, false) or t.assignee_user_id = auth.uid());
$$;

-- >>>>>>>>>>>>>>>>>>>>  0043_inbox_admin_domains  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0043 LA POSTA È DEL CLIENTE: chi entra, e chi decide «Da gestire»
--
-- ⚠️ CHE COSA CHIUDE, misurato sulla casella reale il 2026-08-23 (148 messaggi,
-- una sola casella `@gmail.com` personale):
--
--   · 22 messaggi stavano in «Da gestire». Venivano da `stripe.com` (15) e
--     `mail.anthropic.com` (7): 22 su 22 da domini fornitore, ZERO da un
--     dominio amministrativo. «Da gestire» non descriveva il lavoro
--     dell'azienda, descriveva le fatture del titolare;
--   · 130 messaggi su 148 non hanno mai prodotto niente, e non lo produrranno:
--     sono newsletter, spedizioni, promozioni. Finché la casella porta quel
--     rumore, la scelta manuale non è selezione — è lavoro di scarto.
--
-- LE DUE DECISIONI, che questa migrazione rende regole del database:
--
--   A1  Entra in `email_messages` solo chi proviene da un dominio dichiarato
--       amministrativo. L'elenco è una TABELLA — si interroga, si corregge
--       aggiungendo una riga, e si può mostrare a un revisore. Non è
--       un'inferenza sul testo, non è un punteggio, non è una soglia.
--
--   A2  Nessun messaggio finisce in «Da gestire» per mano del classificatore.
--       Lo stato di attenzione lo decide una persona. `likely_actionable`
--       porta a `to_verify`: «qualcuno deve guardarla», che è la verità —
--       non «l'azienda deve occuparsene», che il classificatore non sa.
--
-- ⚠️⚠️ IL FILTRO NON PUÒ ESSERE MUTO, e questa è la parte che costa. Un
-- messaggio scartato alla radice non lascerebbe alcuna traccia: la lettera del
-- nuovo assicuratore, mai vista, sarebbe indistinguibile da una lettera mai
-- spedita. Perciò `email_excluded_senders` tiene il DOMINIO e un contatore —
-- mai l'oggetto, mai il mittente per esteso, mai il corpo. È strettamente MENO
-- dato di quello che si conserva oggi (oggi il messaggio intero entra), ed è
-- abbastanza per rispondere a «che cosa sto perdendo?».
--
-- ⚠️ PERCHÉ NON SI TOCCA LA CASELLA REMOTA. Niente qui cancella, archivia o
-- etichetta su Gmail: un messaggio escluso resta nella casella del cliente,
-- intatto. AI-Swisse decide solo che cosa acquisisce (§2.2).
--
-- Requisiti: 0001 (helper RLS), 0013 (Inbox), 0014 (la regola del `revoke all`).
-- Idempotente: si può rieseguire senza danni.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. L'ELENCO CHIUSO
--
-- ⚠️ `company_id` NULLABILE, e i due valori dicono due cose diverse:
--     NULL          catalogo GLOBALE — vale per ogni azienda del prodotto.
--                   Ci sta solo ciò che è amministrativo per CHIUNQUE in
--                   Svizzera, e nient'altro.
--     un'azienda    la riga vale per quella sola: il suo comune, la sua banca,
--                   la sua fiduciaria, il suo assicuratore. Sono dati suoi e
--                   muoiono con lei (cascata).
--
-- ⚠️⚠️ DUE INDICI UNICI PARZIALI, NON UN `unique (company_id, domain)`: in SQL
-- due NULL non sono uguali, quindi quel vincolo NON impedirebbe affatto due
-- righe globali per lo stesso dominio. È la stessa trappola già pagata dalla
-- 0013 su `email_message_documents`, e si evita nello stesso modo.
--
-- ⚠️ `archived_at` E NON UNA `delete`: togliere un dominio dall'elenco è una
-- decisione che cambia che cosa entra, e va potuta leggere dopo. È la stessa
-- grammatica di 0016/0017 — mettere via non è cancellare.
--
-- ⚠️ `note` NON È UN ORNAMENTO. «Verificabile» significa che un revisore deve
-- poter capire PERCHÉ un dominio è in elenco senza chiederlo a chi ce l'ha
-- messo. Un catalogo di domini senza motivazioni, fra sei mesi, è un elenco di
-- stringhe che nessuno osa toccare.
-- ---------------------------------------------------------------------------
create table if not exists public.email_admin_domains (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid references public.companies (id) on delete cascade,
  domain      text not null,
  note        text,
  added_by    uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now(),
  archived_at timestamptz,

  -- ⚠️⚠️ ALMENO DUE ETICHETTE. Una riga `ch` ammetterebbe l'intera Svizzera,
  -- cioè trasformerebbe l'elenco chiuso in nessun filtro — e lo farebbe in
  -- silenzio, che è il modo peggiore. Un elenco che può contenere la propria
  -- negazione non è chiuso. La stessa regola vive in `adminDomains.ts`
  -- (`dominioUtilizzabile`): qui è il vincolo, là la seconda serratura.
  constraint email_admin_domain_shape check (
    domain = lower(domain)
    and domain !~ '\s'
    and domain ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$'
    and position('.' in domain) > 0
  )
);

create unique index if not exists uq_email_admin_domain_global
  on public.email_admin_domains (domain) where company_id is null;
create unique index if not exists uq_email_admin_domain_company
  on public.email_admin_domains (company_id, domain) where company_id is not null;
create index if not exists idx_email_admin_domain_live
  on public.email_admin_domains (company_id) where archived_at is null;

comment on table public.email_admin_domains is
  'Elenco CHIUSO dei domini ammessi in Inbox. company_id NULL = catalogo globale. Un messaggio il cui mittente non corrisponde a nessuna riga viva non viene acquisito.';
comment on column public.email_admin_domains.note is
  'Perché questo dominio è amministrativo. Obbligatorio nella pratica: un catalogo senza motivazioni non è verificabile.';

-- ---------------------------------------------------------------------------
-- 2. IL REGISTRO DEGLI ESCLUSI — perché il filtro non sia muto
--
-- ⚠️ SOLO IL DOMINIO E UN CONTATORE. Non l'oggetto, non l'indirizzo completo,
-- non il corpo, non l'identificativo del provider. È la stessa disciplina di
-- `email_sync_runs` (0013 §8): si registra abbastanza per rispondere a una
-- domanda di esercizio, e non abbastanza per leggere la posta di qualcuno.
--
-- ⚠️ E RESTA MENO DI PRIMA. Fino a oggi quei messaggi entravano INTERI —
-- oggetto, mittente, corpo, allegati. Da qui in avanti di un messaggio escluso
-- resta un dominio e un numero. Il filtro riduce i dati conservati, non li
-- aumenta.
-- ---------------------------------------------------------------------------
create table if not exists public.email_excluded_senders (
  id            uuid primary key default gen_random_uuid(),
  company_id    uuid not null references public.companies (id) on delete cascade,
  connection_id uuid not null references public.email_connections (id) on delete cascade,
  domain        text not null,
  message_count integer not null default 0,
  first_seen_at timestamptz not null default now(),
  last_seen_at  timestamptz not null default now(),

  -- ⚠️ Il dominio NON leggibile del mittente si registra come stringa vuota e
  -- non si scarta: «da un indirizzo che non si è potuto leggere» è un fatto, e
  -- se diventasse frequente vorrebbe dire che la normalizzazione è rotta.
  -- Perciò qui NON c'è il vincolo di forma della tabella qui sopra.
  unique (connection_id, domain)
);
create index if not exists idx_email_excluded_company
  on public.email_excluded_senders (company_id, last_seen_at desc);

comment on table public.email_excluded_senders is
  'Che cosa il filtro dei domini ha scartato: dominio e contatore, mai contenuto. Esiste perché un''esclusione senza traccia è indistinguibile da una lettera mai spedita.';

-- ⚠️ E ANCHE NEL REGISTRO DELLE SINCRONIZZAZIONI. `email_excluded_senders` dice
-- QUALI domini vengono scartati, e cresce nel tempo; questa colonna dice quanti
-- ne ha scartati QUELLA esecuzione. Sono due domande diverse: «da chi non
-- ricevo?» e «questa sincronizzazione ha portato poco perché è arrivato poco o
-- perché il filtro ha stretto?». Senza, una casella improvvisamente muta —
-- catalogo archiviato per sbaglio, dominio che cambia — sembrerebbe soltanto
-- una casella tranquilla.
alter table public.email_sync_runs
  add column if not exists messages_excluded integer not null default 0;

comment on column public.email_sync_runs.messages_excluded is
  'Messaggi visti dal provider e NON acquisiti perché il mittente non è in email_admin_domains.';

-- ---------------------------------------------------------------------------
-- 3. Registrare un'esclusione, in modo ATOMICO
--
-- ⚠️ Una funzione e non un `upsert` dal codice: il conteggio si INCREMENTA, e
-- `supabase-js` non sa esprimere «+1» in un upsert. Farlo in due passi —
-- leggi, somma, scrivi — perderebbe conteggi appena due sincronizzazioni si
-- sovrappongono, che è precisamente quello che succede quando arriva un
-- webhook mentre la riconciliazione periodica sta girando.
--
-- `security definer` perché la chiama il service role delle Edge Function e
-- nessun ruolo applicativo deve poter scrivere in questo registro.
-- ---------------------------------------------------------------------------
create or replace function public.email_record_excluded_sender(
  p_company_id    uuid,
  p_connection_id uuid,
  p_domain        text
)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into public.email_excluded_senders
    (company_id, connection_id, domain, message_count, first_seen_at, last_seen_at)
  values (p_company_id, p_connection_id, coalesce(lower(trim(p_domain)), ''), 1, now(), now())
  on conflict (connection_id, domain) do update
    set message_count = public.email_excluded_senders.message_count + 1,
        last_seen_at  = now();
$$;

revoke all on function public.email_record_excluded_sender(uuid, uuid, text) from public;

-- ---------------------------------------------------------------------------
-- 4. A2 — «Da gestire» non lo assegna più una macchina
--
-- ⚠️ SI SOSTITUISCE LA FUNZIONE, non si aggiunge un secondo posto in cui
-- decidere. Questa funzione è già l'unica strada per DUE percorsi — la
-- pipeline che classifica e il ripristino di un messaggio «messo via»
-- (trigger `set_email_message_handled_actor`, 0013) — e la 0013 dichiara
-- esplicitamente che le due non devono poter divergere. La copia lato server
-- (`attentionForRelevance` in `_shared/email/contract.ts`) cambia nello stesso
-- commit, e `test:inbox-unit` verifica che le due tabelle coincidano.
--
-- ⚠️ `needs_attention` RESTA NELL'ENUM, e non è un residuo: dalla PARTE B sarà
-- lo stato che una PERSONA produce promuovendo. Toglierlo ora significherebbe
-- rifarlo fra due giorni, e un `alter type ... drop value` in PostgreSQL non
-- esiste.
-- ---------------------------------------------------------------------------
create or replace function public.email_attention_for_relevance(p_rel public.email_relevance)
returns public.email_attention_status
language sql
immutable
as $$
  select case p_rel
    -- ⚠️ ERA `needs_attention`. Un classificatore può dire «questa sembra
    -- azionabile»; non può dire «la tua azienda deve occuparsene», perché non
    -- sa di chi sia il documento né se riguardi l'azienda. `to_verify` è
    -- l'affermazione vera: qualcuno deve guardarla.
    when 'likely_actionable'   then 'to_verify'
    when 'possibly_actionable' then 'to_verify'
    when 'informational'       then 'informational'
    when 'clearly_irrelevant'  then 'ignored'
    else 'to_verify'                       -- non ancora classificata: si mostra
  end::public.email_attention_status;
$$;

comment on function public.email_attention_for_relevance(public.email_relevance) is
  'Dove va un messaggio che non è stato messo via. Dal 2026-08-23 non produce mai "needs_attention": quello stato lo genera una persona, promuovendo (D-13).';

-- ---------------------------------------------------------------------------
-- 5. Le righe che il vecchio classificatore aveva già promosso
--
-- ⚠️ NON È UNA RISCRITTURA DELLA STORIA. `relevance`, `relevance_reason`,
-- `classifier_version` e `classified_at` restano intatti: che cosa il
-- classificatore avesse concluso resta leggibile per intero. Qui si corregge
-- soltanto la CONSEGUENZA che quella conclusione non era autorizzata a trarre.
--
-- ⚠️ SOLO LE RIGHE MAI TOCCATE DA UNA PERSONA (`handled_by is null`). Una
-- riga che qualcuno ha messo via e poi ripristinato porta una decisione umana,
-- e non si sovrascrive una decisione umana con una migrazione. In pratica, sui
-- dati del 2026-08-23, sono 22 righe su 22 — nessuna era stata toccata.
--
-- ⚠️ Il trigger `set_email_message_handled_actor` NON blocca questa update:
-- sta nel ramo `elsif auth.uid() is not null`, e in una migrazione
-- `auth.uid()` è NULL. Verificato leggendo la 0013, non supposto.
-- ---------------------------------------------------------------------------
update public.email_messages
   set attention_status = public.email_attention_for_relevance(relevance)
 where attention_status = 'needs_attention'
   and handled_by is null;

-- ---------------------------------------------------------------------------
-- 6. IL CATALOGO GLOBALE — deliberatamente MINIMO
--
-- ⚠️⚠️ QUI CI STA SOLO CIÒ CHE È AMMINISTRATIVO PER CHIUNQUE IN SVIZZERA, e
-- nient'altro. La tentazione è riempire questa lista di ventisei domini
-- cantonali, di banche e di assicuratori scritti a memoria: sarebbe un elenco
-- non verificato spacciato per catalogo, cioè esattamente ciò che questo
-- progetto chiama un racconto. Un dominio in più scritto a caso apre una porta
-- che nessuno ha deciso di aprire; un dominio in meno si aggiunge con una riga
-- quando serve, e il registro degli esclusi dice QUANDO serve.
--
-- Il comune, il cantone, la banca, la fiduciaria e l'assicuratore di
-- un'azienda sono suoi: vanno in righe con `company_id`, decise da chi quella
-- azienda la conosce. Non da questa migrazione.
--
-- `on conflict do nothing`: rieseguire non duplica, e non riporta in vita un
-- dominio che qualcuno avesse archiviato.
-- ---------------------------------------------------------------------------
insert into public.email_admin_domains (company_id, domain, note) values
  (null, 'admin.ch', 'Confederazione svizzera: tutti gli uffici federali sono sottodomini (estv.admin.ch, bj.admin.ch, zefix.admin.ch, …).'),
  (null, 'suva.ch',  'SUVA — assicurazione infortuni obbligatoria per ogni datore di lavoro.'),
  (null, 'ahv-iv.ch','AVS/AI — assicurazioni sociali obbligatorie.'),
  (null, 'post.ch',  'La Posta Svizzera: raccomandate, notifiche di recapito, fatturazione.')
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- 7. PERMESSI — prima si toglie tutto (la regola della 0014)
--
-- ⚠️ Su `public`, un grant di colonna non restringe nulla senza un `revoke
-- all` che lo preceda: Supabase concede i privilegi pieni per default a ogni
-- tabella nuova dello schema. Questa è la terza tabella del progetto a
-- ricordarselo, e il commento resta perché la quarta non se ne dimentichi.
-- ---------------------------------------------------------------------------
revoke all on public.email_admin_domains   from anon, authenticated, public;
revoke all on public.email_excluded_senders from anon, authenticated, public;

alter table public.email_admin_domains    enable row level security;
alter table public.email_excluded_senders enable row level security;

-- LETTURA — un membro vede il catalogo globale e le righe della sua azienda.
-- Il catalogo globale è leggibile da chiunque sia autenticato: è la regola in
-- base alla quale la sua posta viene filtrata, e una regola che decide che cosa
-- si vede non può essere segreta per chi la subisce.
grant select on public.email_admin_domains to authenticated;
grant select on public.email_excluded_senders to authenticated;

drop policy if exists email_admin_domains_read on public.email_admin_domains;
create policy email_admin_domains_read on public.email_admin_domains
  for select to authenticated
  using (company_id is null or public.is_company_member(company_id));

-- SCRITTURA — solo owner/admin, e solo sulle righe della PROPRIA azienda.
-- ⚠️ Il catalogo globale NON è scrivibile da nessun ruolo applicativo: cambia
-- il comportamento del prodotto per tutti i clienti, quindi si cambia con una
-- migrazione, che è un fatto tracciato e revisionato.
grant insert (company_id, domain, note, added_by), update (note, archived_at)
  on public.email_admin_domains to authenticated;

drop policy if exists email_admin_domains_write on public.email_admin_domains;
create policy email_admin_domains_write on public.email_admin_domains
  for insert to authenticated
  with check (company_id is not null and public.is_company_admin(company_id));

drop policy if exists email_admin_domains_edit on public.email_admin_domains;
create policy email_admin_domains_edit on public.email_admin_domains
  for update to authenticated
  using (company_id is not null and public.is_company_admin(company_id))
  with check (company_id is not null and public.is_company_admin(company_id));

-- REGISTRO DEGLI ESCLUSI — sola lettura, e solo per chi amministra l'azienda:
-- dice quali domini scrivono alla casella, ed è un'informazione della casella.
drop policy if exists email_excluded_senders_read on public.email_excluded_senders;
create policy email_excluded_senders_read on public.email_excluded_senders
  for select to authenticated
  using (public.is_company_admin(company_id));

-- >>>>>>>>>>>>>>>>>>>>  0044_inbox_dismissed_value  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0044 «IGNORA» È UNO STATO SUO — solo il valore dell'enum
--
-- ⚠️⚠️ QUESTA MIGRAZIONE FA UNA COSA SOLA, E IL PERCHÉ È UNA TRAPPOLA GIÀ
-- PAGATA (0027, dichiarata in testa alla 0039): in PostgreSQL un valore
-- aggiunto a un enum NON è utilizzabile nella stessa transazione che lo
-- aggiunge. Un `alter type … add value` seguito, nello stesso file, da un
-- `update … set stato = 'nuovo_valore'` fallisce. Perciò il valore nasce qui e
-- lo usa la 0045.
--
-- PERCHÉ SERVE UN VALORE NUOVO invece di riusare `ignored`.
-- `ignored` esiste dalla 0013 e significa una cosa precisa, scritta nel suo
-- commento: «il classificatore l'ha giudicata non amministrativa». Sui dati
-- veri del 2026-08-23 lo portano 72 messaggi su 148, e NESSUNO di quei 72 è
-- stato messo lì da una persona.
--
-- Se l'«Ignora» dell'utente scrivesse lo stesso valore, due affermazioni
-- diverse diventerebbero indistinguibili:
--   · «una macchina ha concluso che questa non è amministrativa»  — rivedibile;
--   · «una persona ha deciso che questa non la riguarda»          — una scelta.
-- E la seconda verrebbe cancellata dalla prima al primo riclassificatore che
-- passa. Uno stato che non sa dire chi lo ha scritto non è uno stato: è
-- un'etichetta.
--
-- Requisiti: 0013 (l'enum). Idempotente.
-- ============================================================================

alter type public.email_attention_status add value if not exists 'dismissed';

-- >>>>>>>>>>>>>>>>>>>>  0045_inbox_promozione  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0045 IL GESTO DI PROMOZIONE (D-13, PARTE B)
--
-- È il punto preciso in cui la posta diventa un dato aziendale: prima non
-- conta, dopo è tracciabile. Tre cose, e nient'altro:
--
--   1. «Ignora» diventa una decisione UMANA registrata (chi, quando), distinta
--      dal giudizio della macchina — il valore è nato nella 0044;
--   2. il trigger che sorveglia `attention_status` impara le due decisioni
--      nuove, e continua a rifiutare tutto il resto;
--   3. la promozione stessa: `email_promote_message`, che crea il legame che
--      il client NON può scrivere.
--
-- ⚠️⚠️ PERCHÉ LA PROMOZIONE È UNA FUNZIONE DEL DATABASE E NON TRE SCRITTURE
-- DAL SERVIZIO. Il client ha `grant select` e basta su
-- `email_message_documents` (0014): il legame non può scriverlo, ed è giusto
-- così — quella tabella è il verbale di che cosa è entrato in azienda. Ma
-- soprattutto le tre scritture devono stare in UNA transazione: un documento
-- creato e un legame mancante è precisamente il caso che rende la promozione
-- non idempotente, perché il secondo clic non troverebbe niente e creerebbe un
-- secondo documento.
--
-- ⚠️ L'IDEMPOTENZA (B3) NON È UN `if` NEL CODICE: è l'indice unico parziale
-- `uq_email_msg_doc_body` della 0013. Due clic simultanei arrivano entrambi
-- all'insert; uno vince, l'altro prende 23505, rilegge e restituisce lo stesso
-- identificativo. Un controllo «esiste già?» prima dell'insert non basterebbe,
-- perché fra la lettura e la scrittura ci sta un'altra richiesta.
--
-- ⚠️ IL REGISTRO NON SI SCRIVE QUI. `audit_logs` lo scrive il trigger
-- `trg_audit_document_insert` (0039) sulla tabella che possiede il fatto, con
-- `coalesce(auth.uid(), new.uploaded_by)` come autore. Scrivere una seconda
-- riga da questa funzione creerebbe due verbali dello stesso evento — ed è la
-- regola che la 0039 dichiara in testa. Questa funzione si limita a valorizzare
-- `uploaded_by`, così l'autore c'è anche quando a chiamare è il service role.
--
-- Requisiti: 0002 (documents), 0013 (Inbox), 0014 (permessi), 0039 (registro),
-- 0044 (il valore `dismissed`). Idempotente.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Chi ha ignorato, e quando
--
-- ⚠️ COLONNE PROPRIE E NON `handled_by`/`handled_at`. «L'ho messa via» e «non
-- ci riguarda» sono due decisioni diverse, e un domani si vorrà sapere quante
-- comunicazioni una casella produce che l'azienda dichiara non sue — che è la
-- misura di quanto il filtro dei domini (0043) sia tarato bene. Con una colonna
-- sola quella domanda non ha risposta.
-- ---------------------------------------------------------------------------
alter table public.email_messages
  add column if not exists dismissed_at timestamptz,
  add column if not exists dismissed_by uuid references auth.users (id) on delete set null;

comment on column public.email_messages.dismissed_at is
  'Quando una PERSONA ha dichiarato che questa comunicazione non riguarda l''azienda. Distinto da handled_at: «messa via» e «non ci riguarda» non sono la stessa decisione.';

-- ---------------------------------------------------------------------------
-- 2. Il trigger impara le decisioni umane nuove
--
-- ⚠️ LA FORMA RESTA QUELLA DELLA 0013: dal client si può solo DICHIARARE una
-- decisione, mai riscrivere una conclusione della pipeline. Cambia l'elenco
-- delle decisioni ammesse, non il principio — e ogni altro cambio continua a
-- sollevare.
--
-- ⚠️ IL RIPRISTINO DA `dismissed` NON RICALCOLA DA `relevance`, e questa è la
-- differenza che conta rispetto a `handled`. Rimettere in lista una messa via è
-- un ANNULLAMENTO, e la classificazione è l'unica cosa che resta da cui
-- ripartire. Ma un messaggio ignorato da una persona che torna in lista non
-- deve ripresentarsi con l'etichetta che la macchina gli aveva dato prima che
-- qualcuno la contraddicesse: torna a «da verificare», cioè «qualcuno lo
-- guardi», che è l'unica affermazione vera dopo un ripensamento.
-- ---------------------------------------------------------------------------
create or replace function public.set_email_message_handled_actor()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();

  if new.attention_status is distinct from old.attention_status then
    if new.attention_status = 'handled' then
      -- «Metti via»: chi e quando li scrive il database, non la richiesta.
      if auth.uid() is not null then
        new.handled_by := auth.uid();
        new.handled_at := now();
      end if;

    elsif new.attention_status = 'dismissed' then
      -- «Ignora»: una decisione della persona, non un giudizio della macchina.
      -- Non cancella niente — né qui né sulla casella remota.
      if auth.uid() is not null then
        new.dismissed_by := auth.uid();
        new.dismissed_at := now();
      end if;

    elsif old.attention_status = 'handled' then
      -- «Rimetti in lista»: il messaggio torna dove lo aveva messo la
      -- classificazione. Il valore inviato dal client viene IGNORATO — un
      -- ripristino è un annullamento, non l'occasione per riscrivere una
      -- conclusione dell'analisi.
      new.attention_status := public.email_attention_for_relevance(new.relevance);
      new.handled_by := null;
      new.handled_at := null;

    elsif old.attention_status = 'dismissed' then
      -- Ripensamento su un «Ignora»: vedi il commento qui sopra.
      new.attention_status := 'to_verify';
      new.dismissed_by := null;
      new.dismissed_at := null;

    elsif auth.uid() is not null then
      raise exception 'attention_status: dal client sono ammessi solo "handled", "dismissed" e il ripristino'
        using errcode = '22023';
    end if;
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- 3. LA PROMOZIONE
--
-- Dato un messaggio e un documento appena creato (o già esistente), scrive il
-- legame e porta il messaggio a «Da gestire». Restituisce l'identificativo del
-- documento in vigore per quel messaggio — lo stesso a ogni chiamata.
--
-- ⚠️ IL DOCUMENTO NON LO CREA QUESTA FUNZIONE, e non è una divisione arbitraria:
-- un documento senza il suo file in Storage è «una promessa non mantenuta»
-- (parole di `createOrReuseDocument`, che per questo cancella la riga se il
-- caricamento fallisce), e da SQL lo Storage non si tocca. Chi chiama crea il
-- documento con il file, poi passa di qui per il legame. Se il legame c'è già,
-- questa funzione lo dice PRIMA che il chiamante crei alcunché.
--
-- ⚠️ `p_document_id` NULL = «dimmi solo se è già promosso». È la lettura che
-- rende B3 possibile senza sprecare un caricamento su Storage a ogni clic.
-- ---------------------------------------------------------------------------
create or replace function public.email_promote_message(
  p_message_id  uuid,
  p_document_id uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_existing uuid;
begin
  select company_id into v_company
    from public.email_messages where id = p_message_id;
  if v_company is null then
    raise exception 'messaggio non trovato' using errcode = 'P0002';
  end if;

  -- ⚠️ L'AUTORIZZAZIONE NON LA EREDITA `security definer`. La funzione salta la
  -- RLS per poter scrivere il legame; l'appartenenza all'azienda va quindi
  -- chiesta esplicitamente. `auth.uid()` NULL = service role, che è il server e
  -- ha già autenticato a monte.
  if auth.uid() is not null and not public.is_company_member(v_company) then
    raise exception 'non autorizzato' using errcode = '42501';
  end if;

  select document_id into v_existing
    from public.email_message_documents
   where email_message_id = p_message_id and relation = 'body';
  if v_existing is not null then
    return v_existing;                         -- B3: già promosso, stesso esito
  end if;
  if p_document_id is null then
    return null;                               -- sola lettura: non c'è ancora
  end if;

  begin
    insert into public.email_message_documents
      (company_id, email_message_id, document_id, relation)
    values (v_company, p_message_id, p_document_id, 'body');
  exception when unique_violation then
    -- Due clic simultanei: l'altro ha vinto. Non è un errore, è l'esito voluto.
    select document_id into v_existing
      from public.email_message_documents
     where email_message_id = p_message_id and relation = 'body';
    return v_existing;
  end;

  -- «Da gestire» lo produce una PERSONA promuovendo (A2, 0043): è l'unico
  -- modo in cui quello stato può nascere da qui in avanti.
  update public.email_messages
     set attention_status = 'needs_attention'
   where id = p_message_id
     and attention_status not in ('handled', 'dismissed');

  return p_document_id;
end $$;

revoke all on function public.email_promote_message(uuid, uuid) from public;
grant execute on function public.email_promote_message(uuid, uuid) to authenticated;

comment on function public.email_promote_message(uuid, uuid) is
  'D-13: scrive il legame messaggio→documento e porta il messaggio a «Da gestire». Idempotente per costruzione (uq_email_msg_doc_body). Con p_document_id NULL è una sola lettura: «è già promosso?».';

-- >>>>>>>>>>>>>>>>>>>>  0046_subsidy_recheck_review  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0046 LA RIVERIFICA UMANA HA UN PERCORSO — solo il valore dell'enum
--
-- ⚠️⚠️ QUESTA MIGRAZIONE FA UNA COSA SOLA, come la 0044 e per la stessa trappola
-- già pagata (0027): in PostgreSQL un valore aggiunto a un enum NON è
-- utilizzabile nella stessa transazione che lo aggiunge — neppure per
-- VERIFICARLO, perché un controllo che nomina l'etichetta nuova è già un uso.
-- Il valore nasce qui e lo usa `_shared/subsidy/sourceCheck.ts`, che scrive le
-- schede `recheck_due` dal prossimo deploy di `subsidy-worker`.
--
-- PERCHÉ SERVE UN VALORE NUOVO. La verifica UMANA di un programma
-- (`subsidy_programs.last_checked_at`) si muove soltanto con la decisione
-- `accepted` di `resolve_subsidy_catalog_review` (0037) — ed è giusto così. Ma
-- fino a qui una revisione nasceva solo quando una FONTE si muoveva: a coda
-- vuota, misurato in produzione il 2026-08-28, sette programmi erano fermi al
-- 2026-07-25 e `subsidy:health` usciva 1 senza che esistesse un gesto per
-- chiuderlo. `recheck_due` è la scheda che il rilevatore apre quando non è la
-- fonte ad essersi mossa ma la verifica ad essere vecchia: `previousValues`
-- porta la data e i giorni, `proposedValues` è vuoto perché non c'è niente da
-- applicare — c'è una pagina ufficiale da riaprire e un «ciò che pubblichiamo
-- è ancora vero» da dire di nuovo.
--
-- ⚠️ RIUSARE `other` SAREBBE STATO PIÙ SEMPLICE E SBAGLIATO: il tipo di
-- cambiamento governa il rischio (§23) e chi smaltisce la coda deve distinguere
-- «la fonte è cambiata» da «nessuno ha guardato troppo a lungo» senza leggere
-- la nota — sono due lavori diversi, con due urgenze diverse.
--
-- Requisiti: 0032 (l'enum), 0037 (la coda e il cancello). Idempotente.
-- ============================================================================

alter type public.subsidy_review_change_type add value if not exists 'recheck_due';

-- >>>>>>>>>>>>>>>>>>>>  0047_crm_custom_fields  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0047 CAMPI PERSONALIZZATI DEL CRM (Fase 0.4)
--
-- Fino a qui il CRM sapeva rispondere a «con chi stiamo lavorando?» solo con i
-- campi decisi dalla 0026: identificativi, indirizzo, recapiti, ruoli, note.
-- Ogni azienda però tiene la propria contabilità di relazione — il numero
-- cliente nel gestionale precedente, la data del prossimo rinnovo, la fascia
-- di fatturato — e un elenco di colonne fissato dal fornitore non la copre.
-- Questa migrazione aggiunge i campi personalizzati: definizioni decise
-- DALL'AZIENDA (non dal tenant, non dal codice), valori su organizzazioni e
-- opportunità, tipo controllato dal database.
--
-- IL MODELLO, in tre affermazioni:
--
-- 1. LA DEFINIZIONE È DELL'AZIENDA. `crm_field_definitions` porta `company_id`
--    come ogni altra tabella del modulo: i campi di un'azienda non esistono
--    per un'altra, né in lettura né in scrittura.
--
-- 2. UN VALORE È UNA RIGA, E IL TIPO È UN FATTO DEL DATABASE. Niente colonna
--    `value jsonb` da interpretare a schermo: `value_text`, `value_number` e
--    `value_date` sono tre colonne e il guardiano pretende che sia piena
--    ESATTAMENTE quella del tipo dichiarato dalla definizione. Un numero che
--    non si può sommare, una data che non si può ordinare, un'opzione che la
--    lista non contiene: non entrano. Chi tenta riceve un rifiuto esplicito
--    (23514 con sentinella), non un dato plausibile.
--
-- 3. I CAMPI PERSONALIZZATI SONO ATTRIBUTI, NON IDENTITÀ. Non entrano nella
--    deduplicazione (`crm_duplicate_candidates`), non entrano nell'abbinamento
--    (`crm_match_email`, `crm_scan_link_suggestions`), non entrano nella
--    normalizzazione. Un «numero cliente» identico su due schede NON le rende
--    doppioni: l'identità restano l'IDI e l'email, come da §25 del modello.
--    Questo file non tocca quelle funzioni proprio per questo, e
--    `docs/crm-light.md` lo dichiara.
--
-- CHE COSA NON FA, per scelta:
--   · nessuna cancellazione dura delle definizioni: si archiviano
--     (`archived_at`), come ogni anagrafica del modulo (§123/§125). I valori
--     di un campo archiviato restano nel database e tornano visibili se il
--     campo viene ripristinato;
--   · l'obbligatorietà (`is_required`) è una promessa della SCHERMATA, non un
--     vincolo del database: il database non può pretendere una riga che non
--     esiste su un'entità che nasce senza valori, e un vincolo del genere
--     impedirebbe di creare un'organizzazione finché il campo non è compilato.
--     Ciò che il database garantisce è che nessun valore salvato sia vuoto o
--     del tipo sbagliato — il resto lo dichiara la documentazione;
--   · nessuno storico in `crm_events`: un campo personalizzato è un attributo
--     corrente, non un passaggio di relazione. Se un giorno servirà, sarà una
--     migrazione a sé.
--
-- ⚠️ I DUE ENUM SONO CREATI QUI, non estesi: i valori dichiarati alla
-- creazione sono utilizzabili subito, anche nella stessa transazione (è la
-- differenza con `alter type … add value`, che renderebbe l'etichetta
-- inservibile fino al commit — 55P04, lezione della 0015, della 0022 e della
-- 0046). L'autoverifica in coda può quindi nominarli, e lo fa.
--
-- Requisiti: 0026 (il modulo, le guardie, `is_company_member`,
-- `is_company_admin`, la fusione). Idempotente dove il linguaggio lo consente.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. I TIPI
-- ---------------------------------------------------------------------------

-- Su quale entità il campo è definito. Due sole: persone e contatti restano
-- fuori per scelta (Fase 0.4: organizzazioni e opportunità, nient'altro).
do $$ begin
  create type public.crm_field_entity as enum ('organization', 'opportunity');
exception when duplicate_object then null; end $$;

-- Il tipo del valore. Quattro e non cinque: niente «sì/no» (è una lista a due
-- opzioni), niente «collegamento» (un URL è testo, e la scheda decide se
-- mostrarlo come link), niente multi-selezione (un elenco di righe per valore
-- è un modello che questa fase non apre).
do $$ begin
  create type public.crm_field_type as enum ('text', 'number', 'date', 'select');
exception when duplicate_object then null; end $$;


-- ---------------------------------------------------------------------------
-- 2. crm_field_definitions — I CAMPI DECISI DALL'AZIENDA
--
-- Una riga per campo: «Fascia di fatturato, lista, obbligatorio, terzo».
-- Il NOME è l'etichetta mostrata; i valori puntano all'`id`, quindi rinominare
-- un campo non stacca niente. `position` decide l'ordine di comparsa fra i
-- campi nativi e non ha bisogno di essere unico: i pareggi si sciolgono in
-- lettura (position, created_at, id) e lo spostamento li riscrive a coppie.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_field_definitions (
  id          uuid primary key default gen_random_uuid(),
  company_id  uuid not null references public.companies(id) on delete cascade,
  entity      public.crm_field_entity not null,
  name        text not null,
  field_type  public.crm_field_type not null,
  -- Le opzioni della lista, array jsonb di stringhe. NULL per gli altri tipi:
  -- il legame fra tipo e presenza è il vincolo sotto, la FORMA (stringhe non
  -- vuote, nessun doppione) la pretende il guardiano — un check su jsonb la
  -- scriverebbe in una sola riga illeggibile e con un messaggio muto.
  options     jsonb,
  is_required boolean not null default false,
  position    integer not null default 0,

  archived_at timestamptz,
  archived_by uuid references auth.users(id) on delete set null,

  created_by  uuid references auth.users(id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),

  constraint crm_field_def_name_not_blank check (btrim(name) <> ''),
  -- Le opzioni esistono SE E SOLO SE il tipo è una lista. Il guardiano arriva
  -- prima e dà il messaggio leggibile; questo è il secondo argine.
  constraint crm_field_def_options_belong_to_select
    check ((field_type = 'select') = (options is not null))
);

comment on table public.crm_field_definitions is
  'I campi personalizzati decisi dall''azienda (0047): nome, tipo, opzioni, '
  'obbligatorietà, ordine. Attributi, non identità: non entrano in '
  'deduplicazione né abbinamento. Si archiviano, non si cancellano.';


-- ---------------------------------------------------------------------------
-- 3. crm_field_values — I VALORI, UNO PER RIGA
--
-- ⚠️ TRE COLONNE TIPATE, NON UN JSONB. Un `value jsonb` rimanderebbe il
-- controllo del tipo alla schermata, e ciò che controlla solo la schermata non
-- è controllato: basta un client diverso per scrivere «abc» nel campo
-- «dipendenti». Qui il database rifiuta il tipo sbagliato, e il rifiuto è lo
-- stesso per il browser, per uno script e per il service role.
--
-- ⚠️ LA RIGA ESISTE SOLO SE PORTA UN VALORE. Svuotare un campo CANCELLA la
-- riga: un valore vuoto salvato («  ») e l'assenza del valore direbbero la
-- stessa cosa in due modi, e le due forme finirebbero per divergere.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_field_values (
  id              uuid primary key default gen_random_uuid(),
  company_id      uuid not null references public.companies(id) on delete cascade,
  field_id        uuid not null references public.crm_field_definitions(id) on delete cascade,

  -- L'entità a cui il valore appartiene: ESATTAMENTE una delle due. Quale sia
  -- quella giusta lo decide la definizione, e il guardiano la confronta.
  organization_id uuid references public.crm_organizations(id) on delete cascade,
  opportunity_id  uuid references public.crm_opportunities(id) on delete cascade,

  value_text      text,
  value_number    numeric,
  value_date      date,

  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  constraint crm_field_values_one_entity
    check (num_nonnulls(organization_id, opportunity_id) = 1),
  constraint crm_field_values_one_value
    check (num_nonnulls(value_text, value_number, value_date) = 1)
);

comment on table public.crm_field_values is
  'Un valore di un campo personalizzato su una controparte o una trattativa '
  '(0047). La riga esiste solo se porta un valore: svuotare il campo la '
  'cancella. Il tipo lo pretende il guardiano, non la schermata.';


-- ---------------------------------------------------------------------------
-- 4. GLI INDICI
-- ---------------------------------------------------------------------------

-- La schermata delle impostazioni e la scheda dell'entità leggono le
-- definizioni attive di un'azienda, in ordine di comparsa.
create index if not exists idx_crm_field_defs_company
  on public.crm_field_definitions (company_id, entity, position)
  where archived_at is null;

-- ⚠️ Il nome è unico per azienda ed entità FRA I CAMPI ATTIVI: due «Cliente
-- dal» sulla stessa scheda sarebbero indistinguibili a schermo. Archiviato il
-- nome si libera, e un campo nuovo può prenderlo senza ambiguità.
create unique index if not exists uq_crm_field_def_name
  on public.crm_field_definitions (company_id, entity, lower(name))
  where archived_at is null;

-- Un valore per campo ed entità: la seconda riga sullo stesso campo sarebbe
-- una doppia risposta alla stessa domanda. Parziali, come ogni indice di
-- questo modulo che vale solo per metà delle righe.
create unique index if not exists uq_crm_field_values_org
  on public.crm_field_values (field_id, organization_id)
  where organization_id is not null;
create unique index if not exists uq_crm_field_values_opp
  on public.crm_field_values (field_id, opportunity_id)
  where opportunity_id is not null;

create index if not exists idx_crm_field_values_org
  on public.crm_field_values (organization_id) where organization_id is not null;
create index if not exists idx_crm_field_values_opp
  on public.crm_field_values (opportunity_id) where opportunity_id is not null;
create index if not exists idx_crm_field_values_field
  on public.crm_field_values (field_id);


-- ---------------------------------------------------------------------------
-- 5. LA CONVALIDA PURA
--
-- Due funzioni `immutable` che rispondono con la SENTINELLA dell'errore o con
-- NULL: il guardiano le chiama e solleva ciò che ricevono. Stanno fuori dal
-- guardiano per lo stesso motivo per cui la cifra di controllo dell'IDI sta
-- fuori dal suo: ciò che si può sbagliare in silenzio deve poter essere
-- provato senza scrivere una riga — e infatti l'autoverifica in coda le prova
-- sul RISULTATO, non sulla sintassi.
-- ---------------------------------------------------------------------------

-- Le opzioni di una lista, normalizzate: btrim a ogni voce, ordine conservato.
-- Si chiama solo dopo aver verificato che la forma sia un array.
create or replace function public.crm_field_options_norm(p_options jsonb)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select coalesce(jsonb_agg(btrim(e) order by o), '[]'::jsonb)
    from jsonb_array_elements_text(p_options) with ordinality as u(e, o);
$$;

-- NULL se le opzioni sono valide per il tipo, altrimenti il sentinella.
create or replace function public.crm_field_options_problem(
  p_type    public.crm_field_type,
  p_options jsonb
)
returns text
language plpgsql
immutable
set search_path = ''
as $$
declare
  v_len integer;
begin
  if p_type <> 'select' then
    -- Le opzioni non appartengono agli altri tipi: il guardiano le azzera, e
    -- arrivare qui con un valore sarebbe già il sintomo di un chiamante
    -- diverso.
    return case when p_options is null then null else 'crm_field_options_invalid' end;
  end if;
  if p_options is null or jsonb_typeof(p_options) <> 'array' then
    return 'crm_field_options_invalid';
  end if;
  select count(*) into v_len from jsonb_array_elements(p_options);
  if v_len = 0 or v_len > 200 then
    return 'crm_field_options_invalid';
  end if;
  -- Ogni voce è una stringa non vuota…
  if exists (select 1 from jsonb_array_elements(p_options) e
              where jsonb_typeof(e) <> 'string' or btrim(e #>> '{}') = '') then
    return 'crm_field_options_invalid';
  end if;
  -- …e non ce n'è due volte la stessa: due voci uguali renderebbero il valore
  -- salvato ambiguo a schermo («Altro» e «Altro» sono una scelta sola).
  if (select count(distinct e) from jsonb_array_elements_text(p_options) e) <> v_len then
    return 'crm_field_options_duplicate';
  end if;
  return null;
end $$;

-- NULL se il valore è quello del tipo, altrimenti il sentinella. Le colonne
-- che non c'entrano devono essere NULL — non «ignorate»: un numero scritto
-- nella colonna di un campo testo è un dato che qualcuno leggerebbe sbagliato.
create or replace function public.crm_field_value_problem(
  p_type    public.crm_field_type,
  p_options jsonb,
  p_text    text,
  p_number  numeric,
  p_date    date
)
returns text
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_type = 'text' or p_type = 'select' then
    if p_number is not null or p_date is not null then
      return 'crm_field_type_mismatch';
    end if;
    if p_text is null or btrim(p_text) = '' then
      return 'crm_field_value_empty';
    end if;
    -- La lista accetta solo ciò che elenca: un'opzione scritta a mano fuori
    -- dall'elenco renderebbe il filtro futuro una bugia.
    if p_type = 'select'
       and (p_options is null or jsonb_typeof(p_options) <> 'array'
            or not exists (select 1 from jsonb_array_elements_text(p_options) o
                            where o = p_text)) then
      return 'crm_field_option_not_allowed';
    end if;
    return null;
  end if;
  if p_type = 'number' then
    if p_text is not null or p_date is not null then
      return 'crm_field_type_mismatch';
    end if;
    if p_number is null then
      return 'crm_field_value_empty';
    end if;
    return null;
  end if;
  -- date
  if p_text is not null or p_number is not null then
    return 'crm_field_type_mismatch';
  end if;
  if p_date is null then
    return 'crm_field_value_empty';
  end if;
  return null;
end $$;

comment on function public.crm_field_value_problem(public.crm_field_type, jsonb, text, numeric, date) is
  'NULL se il valore è quello dichiarato dal tipo, altrimenti il sentinella '
  'dell''errore (0047). Pura e immutable: il guardiano la chiama, '
  'l''autoverifica la prova sul risultato.';


-- ---------------------------------------------------------------------------
-- 6. I GUARDIANI
--
-- Stessa disciplina della sezione 16 della 0026: `security definer`, sentinella
-- con `errcode 23514`, tre `company_id` a confronto su ogni valore. La sola RLS
-- lascerebbe passare chi dichiara la propria azienda e aggancia un'entità
-- altrui; il trigger si difende da sé, senza contare su una policy scritta
-- altrove — e `test:crm` lo prova anche con il service role.
-- ---------------------------------------------------------------------------

create or replace function public.crm_field_definitions_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_problem text;
begin
  new.name := btrim(new.name);

  -- Le opzioni si normalizzano PRIMA di misurarle: «Verde » e «Verde» sono la
  -- stessa voce, e contarle due volte renderebbe il doppione un falso allarme.
  if new.field_type = 'select' then
    if new.options is null or jsonb_typeof(new.options) <> 'array' then
      raise exception 'crm_field_options_invalid'
        using errcode = '23514',
              hint = 'Un campo a lista richiede le opzioni: un elenco di voci.';
    end if;
    new.options := public.crm_field_options_norm(new.options);
  else
    new.options := null;
  end if;

  v_problem := public.crm_field_options_problem(new.field_type, new.options);
  if v_problem is not null then
    raise exception '%', v_problem
      using errcode = '23514',
            hint = 'Le opzioni devono essere voci di testo, non vuote, senza doppioni.';
  end if;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.created_at := now();
    new.updated_at := now();
    new.archived_at := null;   -- un campo nasce attivo: archiviarlo è un gesto
    new.archived_by := null;
    return new;
  end if;

  -- UPDATE — ciò che non cambia mai. Il TIPO e l'ENTITÀ sono congelati alla
  -- nascita: cambiare «numero» in «testo» con i valori già scritti renderebbe
  -- quelle righe false, e spostare un campo dalle organizzazioni alle
  -- opportunità lo staccerebbe dai suoi valori. Un campo diverso è un campo
  -- nuovo. (I grant già non concedono l'update di quelle colonne: questo è il
  -- secondo argine, perché una difesa che vale in un posto solo si dimentica.)
  new.company_id := old.company_id;
  new.entity     := old.entity;
  new.field_type := old.field_type;
  new.created_by := old.created_by;
  new.created_at := old.created_at;
  new.updated_at := now();

  -- Archiviare e ripristinare, con il timbro scritto dal database (§124).
  if new.archived_at is not null and old.archived_at is null then
    new.archived_at := now();
    new.archived_by := auth.uid();
  elsif new.archived_at is null then
    new.archived_by := null;
  else
    new.archived_at := old.archived_at;
    new.archived_by := old.archived_by;
  end if;

  return new;
end $$;

drop trigger if exists trg_crm_field_definitions_guard on public.crm_field_definitions;
create trigger trg_crm_field_definitions_guard
  before insert or update on public.crm_field_definitions
  for each row execute function public.crm_field_definitions_guard();


create or replace function public.crm_field_values_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_def            public.crm_field_definitions%rowtype;
  v_entity_company uuid;
  v_problem        text;
  v_internal       boolean;
begin
  -- Il sentinella interno della fusione: sposta i valori sul record principale
  -- e solo quello può riscrivere il collegamento (è la disciplina di
  -- `ai_swisse.crm_internal` su `last_contact_at`, stessa migrazione madre).
  v_internal := coalesce(current_setting('ai_swisse.crm_internal', true), '') = 'on';

  if tg_op = 'INSERT' then
    new.created_at := now();
    new.updated_at := now();
  else
    -- L'appartenenza non si riscrive: un valore che cambiasse campo o entità
    -- sarebbe un altro valore, con un'altra storia.
    if not v_internal then
      new.company_id      := old.company_id;
      new.field_id        := old.field_id;
      new.organization_id := old.organization_id;
      new.opportunity_id  := old.opportunity_id;
    end if;
    new.created_at := old.created_at;
    new.updated_at := now();
  end if;

  select * into v_def from public.crm_field_definitions d where d.id = new.field_id;
  if not found then
    raise exception 'crm_field_unknown'
      using errcode = '23514', hint = 'Il campo a cui si scrive non esiste.';
  end if;

  -- TRE company_id a confronto: quello dichiarato dalla riga, quello della
  -- definizione, quello dell'entità collegata. Uno solo diverso basta.
  if v_def.company_id is distinct from new.company_id then
    raise exception 'crm_field_value_company_mismatch'
      using errcode = '23514',
            hint = 'Il campo appartiene a un''altra azienda.';
  end if;

  -- UNA entità sola, e del tipo che la definizione dichiara: un campo nato
  -- per le organizzazioni non accetta una trattativa. (Il check
  -- `crm_field_values_one_entity` farebbe lo stesso lavoro DOPO di qui, con un
  -- messaggio muto: il guardiano arriva prima e dice perché.)
  if num_nonnulls(new.organization_id, new.opportunity_id) <> 1
     or (v_def.entity = 'organization') <> (new.organization_id is not null) then
    raise exception 'crm_field_entity_mismatch'
      using errcode = '23514',
            hint = 'Il campo non è definito per questo tipo di scheda.';
  end if;

  if new.organization_id is not null then
    select o.company_id into v_entity_company
      from public.crm_organizations o where o.id = new.organization_id;
  else
    select o.company_id into v_entity_company
      from public.crm_opportunities o where o.id = new.opportunity_id;
  end if;
  if v_entity_company is null or v_entity_company is distinct from new.company_id then
    raise exception 'crm_field_value_company_mismatch'
      using errcode = '23514',
            hint = 'La scheda a cui si scrive appartiene a un''altra azienda.';
  end if;

  -- Un campo archiviato è CONGELATO: i valori esistenti restano leggibili e si
  -- possono cancellare, ma nessuno se ne aggiunge e nessuno si riscrive. La
  -- fusione è l'unica eccezione: sposta la storia, non la riscrive.
  if v_def.archived_at is not null and not v_internal then
    raise exception 'crm_field_archived'
      using errcode = '23514',
            hint = 'Il campo è archiviato: i suoi valori non si modificano.';
  end if;

  -- Normalizza prima di misurare: «  » non è un valore, è l'assenza di un
  -- valore, e l'assenza è una riga cancellata.
  if v_def.field_type = 'text' or v_def.field_type = 'select' then
    new.value_text := nullif(btrim(coalesce(new.value_text, '')), '');
  end if;

  v_problem := public.crm_field_value_problem(
    v_def.field_type, v_def.options, new.value_text, new.value_number, new.value_date);
  if v_problem is not null then
    raise exception '%', v_problem
      using errcode = '23514',
            hint = 'Il valore non è quello che il campo dichiara.';
  end if;

  return new;
end $$;

drop trigger if exists trg_crm_field_values_guard on public.crm_field_values;
create trigger trg_crm_field_values_guard
  before insert or update on public.crm_field_values
  for each row execute function public.crm_field_values_guard();


-- ---------------------------------------------------------------------------
-- 7. LA FUSIONE IMPARA I CAMPI PERSONALIZZATI
--
-- `crm_merge_organizations` (0026, sezione 22) trasferisce ruoli, persone,
-- recapiti, opportunità, interazioni, collegamenti e storico sul record
-- principale. Da oggi anche i VALORI dei campi personalizzati: una fusione che
-- li lasciasse sul secondario li seppellirebbe dentro una scheda archiviata.
-- Dove il principale ha già un valore per lo stesso campo vince il principale,
-- come per i ruoli e i recapiti; il resto sparisce con il secondario.
--
-- ⚠️ IL CORPO È QUELLO DELLA 0026, VERBATIM, con un solo blocco in più — la
-- funzione si riscrive intera perché `create or replace` non conosce le patch.
-- ---------------------------------------------------------------------------
create or replace function public.crm_merge_organizations(
  p_target_id uuid,
  p_source_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid;
  v_source_company uuid;
begin
  if p_target_id = p_source_id then
    raise exception 'crm_merge_into_self'
      using errcode = '23514', hint = 'Un''organizzazione non si fonde con sé stessa.';
  end if;

  select o.company_id into v_company from public.crm_organizations o where o.id = p_target_id;
  select o.company_id into v_source_company from public.crm_organizations o where o.id = p_source_id;

  if v_company is null or v_source_company is null or v_company is distinct from v_source_company then
    raise exception 'crm_merge_company_mismatch'
      using errcode = '23514',
            hint = 'Le due organizzazioni devono appartenere alla stessa azienda.';
  end if;

  -- §118 — la fusione è irreversibile nei fatti: la decide chi amministra.
  if not public.is_company_admin(v_company) then
    raise exception 'crm_merge_not_admin'
      using errcode = '42501',
            hint = 'Solo un amministratore dell''azienda può unire due anagrafiche.';
  end if;

  perform set_config('ai_swisse.crm_internal', 'on', true);

  -- I ruoli: si sommano, senza duplicarsi.
  insert into public.crm_organization_roles (company_id, organization_id, role, created_by)
  select v_company, p_target_id, r.role, r.created_by
    from public.crm_organization_roles r where r.organization_id = p_source_id
  on conflict (organization_id, role) do nothing;
  delete from public.crm_organization_roles where organization_id = p_source_id;

  -- Le persone: chi lavorava per il secondario lavora per il principale.
  update public.crm_contact_organizations co
     set organization_id = p_target_id
   where co.organization_id = p_source_id
     and not exists (
       select 1 from public.crm_contact_organizations t
        where t.organization_id = p_target_id
          and t.contact_id = co.contact_id
          and t.active_from is not distinct from co.active_from);
  delete from public.crm_contact_organizations where organization_id = p_source_id;

  -- I recapiti: quelli già presenti sul principale non si ripetono.
  delete from public.crm_contact_methods m
   where m.organization_id = p_source_id
     and exists (select 1 from public.crm_contact_methods t
                  where t.organization_id = p_target_id
                    and t.type = m.type
                    and t.normalized_value is not distinct from m.normalized_value);
  update public.crm_contact_methods
     set organization_id = p_target_id, is_primary = false
   where organization_id = p_source_id;

  update public.crm_opportunities set organization_id = p_target_id where organization_id = p_source_id;
  update public.crm_interactions   set organization_id = p_target_id where organization_id = p_source_id;

  -- 0047 — i campi personalizzati: passano al principale, e dove il principale
  -- ha già un valore per lo stesso campo vince il principale (è la semantica
  -- dei recapiti qui sopra). Il guardiano lascia riscrivere il collegamento
  -- perché il sentinella `ai_swisse.crm_internal` è acceso, e accetta anche i
  -- campi archiviati: la fusione sposta la storia, non la riscrive.
  update public.crm_field_values v
     set organization_id = p_target_id
   where v.organization_id = p_source_id
     and not exists (select 1 from public.crm_field_values t
                      where t.field_id = v.field_id
                        and t.organization_id = p_target_id);
  delete from public.crm_field_values where organization_id = p_source_id;

  update public.crm_organization_documents k
     set organization_id = p_target_id
   where k.organization_id = p_source_id
     and not exists (select 1 from public.crm_organization_documents t
                      where t.organization_id = p_target_id and t.document_id = k.document_id);
  delete from public.crm_organization_documents where organization_id = p_source_id;

  update public.crm_organization_emails k
     set organization_id = p_target_id
   where k.organization_id = p_source_id
     and not exists (select 1 from public.crm_organization_emails t
                      where t.organization_id = p_target_id
                        and t.email_message_id = k.email_message_id);
  delete from public.crm_organization_emails where organization_id = p_source_id;

  -- I collegamenti sugli altri moduli.
  update public.tasks set crm_organization_id = p_target_id where crm_organization_id = p_source_id;
  update public.contracts set counterparty_organization_id = p_target_id
   where counterparty_organization_id = p_source_id;
  update public.finance_items set supplier_organization_id = p_target_id
   where supplier_organization_id = p_source_id;

  -- Lo storico si conserva e si sposta: la storia della relazione è una sola,
  -- anche se per un po' è stata scritta su due schede.
  update public.crm_events set organization_id = p_target_id where organization_id = p_source_id;

  update public.crm_organizations
     set archived_at = now(),
         archived_by = auth.uid(),
         merged_into_id = p_target_id,
         relationship_status = 'inactive'
   where id = p_source_id;

  perform set_config('ai_swisse.crm_internal', '', true);

  perform public.crm_refresh_last_contact(p_target_id);

  insert into public.crm_events (company_id, organization_id, kind, detail, actor_user_id)
  values (v_company, p_target_id, 'merged',
          jsonb_build_object('from', p_source_id), auth.uid());
end $$;

comment on function public.crm_merge_organizations(uuid, uuid) is
  'Unisce due anagrafiche: ruoli, persone, recapiti, opportunità, interazioni, '
  'collegamenti, storico e (dal 0047) i valori dei campi personalizzati '
  'passano al principale; il secondario resta archiviato con merged_into_id '
  '(§31). Solo amministratori. Nessuna fusione automatica.';


-- ---------------------------------------------------------------------------
-- 8. RLS
--
-- §112-§117, la stessa condizione del resto del modulo. Con due distinzioni
-- dichiarate:
--   · LE DEFINIZIONI LE SCRIVE CHI AMMINISTRA. Cambiano la forma dei dati di
--     tutta l'azienda, come la fusione (§118): `is_company_admin`. Un membro
--     le legge — deve poter vedere che cosa la scheda gli chiede — ma non le
--     cambia, e la schermata glielo dice invece di offrirgli campi che al
--     salvataggio verrebbero rifiutati;
--   · I VALORI li scrive OGNI MEMBRO, come ogni altro dato del CRM: il modulo
--     non ha permessi granulari per scelta, e i campi personalizzati non
--     inventano un'eccezione.
-- Nessuna policy di DELETE sulle definizioni: si archiviano.
-- ---------------------------------------------------------------------------
alter table public.crm_field_definitions enable row level security;
alter table public.crm_field_values      enable row level security;

drop policy if exists crm_field_defs_select on public.crm_field_definitions;
create policy crm_field_defs_select on public.crm_field_definitions
  for select to authenticated using (public.is_company_member(company_id));
drop policy if exists crm_field_defs_insert on public.crm_field_definitions;
create policy crm_field_defs_insert on public.crm_field_definitions
  for insert to authenticated with check (public.is_company_admin(company_id));
drop policy if exists crm_field_defs_update on public.crm_field_definitions;
create policy crm_field_defs_update on public.crm_field_definitions
  for update to authenticated
  using (public.is_company_admin(company_id))
  with check (public.is_company_admin(company_id));

drop policy if exists crm_field_values_select on public.crm_field_values;
create policy crm_field_values_select on public.crm_field_values
  for select to authenticated using (public.is_company_member(company_id));
drop policy if exists crm_field_values_insert on public.crm_field_values;
create policy crm_field_values_insert on public.crm_field_values
  for insert to authenticated with check (public.is_company_member(company_id));
drop policy if exists crm_field_values_update on public.crm_field_values;
create policy crm_field_values_update on public.crm_field_values
  for update to authenticated
  using (public.is_company_member(company_id))
  with check (public.is_company_member(company_id));
drop policy if exists crm_field_values_delete on public.crm_field_values;
create policy crm_field_values_delete on public.crm_field_values
  for delete to authenticated using (public.is_company_member(company_id));


-- ---------------------------------------------------------------------------
-- 9. I PERMESSI
--
-- ⚠️⚠️ `REVOKE ALL` PRIMA DI OGNI GRANT, come ovunque dal 0014 in poi: su
-- `public` ogni tabella nuova nasce con i privilegi di TABELLA completi, e un
-- grant di colonna scritto dopo AGGIUNGE privilegi invece di toglierli.
--
-- Le colonne timbrate dal database NON compaiono in nessun grant: created_by,
-- created_at, updated_at, archived_by. E nelle definizioni non sono concessi
-- in update nemmeno entity e field_type — congelati alla nascita (guardiano,
-- sezione 6) — né in insert archived_at: un campo nasce attivo.
-- ---------------------------------------------------------------------------
revoke all on public.crm_field_definitions from anon, authenticated, public;
revoke all on public.crm_field_values      from anon, authenticated, public;

grant select on public.crm_field_definitions to authenticated;
grant insert (company_id, entity, name, field_type, options, is_required, position)
  on public.crm_field_definitions to authenticated;
grant update (name, options, is_required, position, archived_at)
  on public.crm_field_definitions to authenticated;

grant select on public.crm_field_values to authenticated;
grant insert (company_id, field_id, organization_id, opportunity_id,
              value_text, value_number, value_date)
  on public.crm_field_values to authenticated;
grant update (value_text, value_number, value_date)
  on public.crm_field_values to authenticated;
grant delete on public.crm_field_values to authenticated;

-- La fusione si richiama dal browser: il revoke/grant va rifatto, perché
-- `create or replace` conserva i permessi MA la dichiarazione qui è ciò che
-- l'autoverifica legge.
revoke all on function public.crm_merge_organizations(uuid, uuid) from public, anon;
grant execute on function public.crm_merge_organizations(uuid, uuid) to authenticated;

-- Le funzioni di convalida NON sono concesse al client: le chiamano i
-- guardiani, che sono `security definer` e non hanno bisogno del permesso del
-- chiamante. Come `crm_refresh_last_contact`: nessun uso dal browser, nessun
-- grant.
revoke all on function public.crm_field_options_norm(jsonb) from public, anon, authenticated;
revoke all on function public.crm_field_options_problem(public.crm_field_type, jsonb) from public, anon, authenticated;
revoke all on function public.crm_field_value_problem(public.crm_field_type, jsonb, text, numeric, date) from public, anon, authenticated;


-- ---------------------------------------------------------------------------
-- 10. AUTOVERIFICA
--
-- Il file prova le proprie garanzie, e se non tornano FALLISCE invece di
-- riuscire a metà (disciplina della 0014 e della 0026). I due enum sono nati
-- in QUESTO file con `create type`, quindi nominarne i valori è lecito: il
-- divieto della 0026 riguardava i valori aggiunti con `alter type` nella
-- stessa transazione.
-- ---------------------------------------------------------------------------
do $$
declare
  v_bad  text;
  v_n    integer;
begin
  -- (a) La RLS è accesa su entrambe le tabelle.
  select string_agg(c.relname, ', ') into v_bad
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public'
     and c.relname in ('crm_field_definitions', 'crm_field_values')
     and c.relrowsecurity = false;
  if v_bad is not null then
    raise exception 'RLS non attiva su: %', v_bad;
  end if;

  -- (b) Le definizioni non sono cancellabili dal client: si archiviano.
  select string_agg(format('%s.%s', table_name, privilege_type), ', ') into v_bad
    from information_schema.table_privileges
   where table_schema = 'public'
     and table_name = 'crm_field_definitions'
     and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
     and privilege_type = 'DELETE';
  if v_bad is not null then
    raise exception 'le definizioni dei campi risultano cancellabili dal client: %', v_bad;
  end if;

  -- (c) Le colonne timbrate dal database non sono scrivibili.
  select string_agg(format('%s.%s', table_name, column_name), ', ') into v_bad
    from information_schema.column_privileges
   where table_schema = 'public'
     and ((table_name = 'crm_field_definitions'
           and column_name in ('created_by', 'created_at', 'updated_at', 'archived_by'))
       or (table_name = 'crm_field_values'
           and column_name in ('created_at', 'updated_at')))
     and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
     and privilege_type in ('INSERT', 'UPDATE');
  if v_bad is not null then
    raise exception 'colonne dei campi personalizzati che il database deve timbrare risultano scrivibili: %', v_bad;
  end if;

  -- (d) Appartenenza e natura non si riscrivono: nessun UPDATE concesso su
  --     company_id, entity, field_type (definizioni) e company_id, field_id,
  --     organization_id, opportunity_id (valori). È il (d-bis) della 0026:
  --     quelle colonne servono all'INSERT e non devono poter cambiare dopo.
  select string_agg(format('%s.%s', table_name, column_name), ', ') into v_bad
    from information_schema.column_privileges
   where table_schema = 'public'
     and ((table_name = 'crm_field_definitions'
           and column_name in ('company_id', 'entity', 'field_type', 'archived_at'))
       or (table_name = 'crm_field_values'
           and column_name in ('company_id', 'field_id', 'organization_id', 'opportunity_id')))
     and grantee in ('anon', 'authenticated', 'public', 'PUBLIC')
     and privilege_type = 'UPDATE'
     -- archived_at è l'eccezione voluta: archiviare/ripristinare è il gesto
     -- ordinario, e va concesso in update. Si esclude dal controllo, non dai
     -- grant.
     and not (table_name = 'crm_field_definitions' and column_name = 'archived_at');
  if v_bad is not null then
    raise exception 'colonne di appartenenza dei campi personalizzati risultano MODIFICABILI dal client: %', v_bad;
  end if;

  -- (e) I guardiani sono `security definer`: un `create or replace` che
  --     dimenticasse la parola riporterebbe il difetto chiuso dalla 0019.
  select string_agg(p.proname, ', ') into v_bad
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname in ('crm_field_definitions_guard', 'crm_field_values_guard',
                       'crm_merge_organizations')
     and p.prosecdef = false;
  if v_bad is not null then
    raise exception 'funzioni dei campi personalizzati che devono essere security definer non lo sono: %', v_bad;
  end if;

  -- (f) La fusione conosce i valori: la sezione 7 riscrive la funzione INTERA,
  --     e una ricopia a memoria che dimenticasse il blocco nuovo passerebbe
  --     ogni altro controllo seppellendo i valori nelle schede fuse.
  if pg_get_functiondef('public.crm_merge_organizations(uuid, uuid)'::regprocedure)
       not like '%crm_field_values%' then
    raise exception 'crm_merge_organizations non trasferisce i valori dei campi personalizzati';
  end if;

  -- (g) I tre indici unici esistono: nome fra gli attivi, un valore per campo
  --     ed entità, nelle due metà.
  select count(*) into v_n
    from pg_indexes
   where schemaname = 'public'
     and indexname in ('uq_crm_field_def_name', 'uq_crm_field_values_org', 'uq_crm_field_values_opp');
  if v_n <> 3 then
    raise exception 'gli indici unici dei campi personalizzati sono %, attesi 3', v_n;
  end if;

  -- (h) ⚠️ LA CONVALIDA FA QUELLO CHE IL FILE DICHIARA — provata sul
  --     RISULTATO, come la cifra di controllo dell'IDI nella 0026. Ogni caso
  --     è una controprova: se la funzione rispondesse NULL dove deve rispondere
  --     un sentinella, un valore falso entrerebbe nel database.
  if public.crm_field_value_problem('text', null, 'una nota', null, null) is not null then
    raise exception 'un testo pieno deve essere accettato';
  end if;
  if public.crm_field_value_problem('text', null, '   ', null, null) is distinct from 'crm_field_value_empty' then
    raise exception 'un testo di soli spazi NON è un valore';
  end if;
  if public.crm_field_value_problem('number', null, '18000', null, null) is distinct from 'crm_field_type_mismatch' then
    raise exception 'un testo dentro un campo numero deve essere rifiutato';
  end if;
  if public.crm_field_value_problem('number', null, null, 18000.5, null) is not null then
    raise exception 'un numero nella sua colonna deve essere accettato';
  end if;
  if public.crm_field_value_problem('date', null, null, null, date '2026-08-29') is not null then
    raise exception 'una data nella sua colonna deve essere accettata';
  end if;
  if public.crm_field_value_problem('date', null, null, 5, null) is distinct from 'crm_field_type_mismatch' then
    raise exception 'un numero dentro un campo data deve essere rifiutato';
  end if;
  if public.crm_field_value_problem('select', '["Piccola","Media","Grande"]'::jsonb, 'Media', null, null) is not null then
    raise exception 'una voce della lista deve essere accettata';
  end if;
  if public.crm_field_value_problem('select', '["Piccola","Media"]'::jsonb, 'Enorme', null, null) is distinct from 'crm_field_option_not_allowed' then
    raise exception 'una voce fuori lista deve essere rifiutata';
  end if;

  -- (i) Le opzioni: la stessa disciplina, sulla definizione.
  if public.crm_field_options_problem('select', '["una","due"]'::jsonb) is not null then
    raise exception 'un elenco sano deve essere accettato';
  end if;
  if public.crm_field_options_problem('select', '["una","una"]'::jsonb) is distinct from 'crm_field_options_duplicate' then
    raise exception 'due voci uguali devono essere rifiutate';
  end if;
  if public.crm_field_options_problem('select', '[]'::jsonb) is distinct from 'crm_field_options_invalid' then
    raise exception 'una lista senza voci deve essere rifiutata';
  end if;
  if public.crm_field_options_problem('select', '["una",5]'::jsonb) is distinct from 'crm_field_options_invalid' then
    raise exception 'una voce che non è testo deve essere rifiutata';
  end if;
  if public.crm_field_options_problem('text', '["una"]'::jsonb) is distinct from 'crm_field_options_invalid' then
    raise exception 'le opzioni non appartengono a un campo testo';
  end if;
  if public.crm_field_options_norm('["  una ","due"]'::jsonb) is distinct from '["una","due"]'::jsonb then
    raise exception 'la normalizzazione deve togliere gli spazi e tenere l''ordine';
  end if;

  raise notice '0047 applicata: 2 tabelle, RLS attiva, permessi verificati, convalida dei valori provata sul risultato, fusione aggiornata.';
end $$;

-- >>>>>>>>>>>>>>>>>>>>  0048_crm_send_email  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- AI-Swisse — 0048 INVIO EMAIL DAL CRM (Fase 1.1)
--
-- La casella collegata resta un'integrazione di SOLA LETTURA: le righe `in`
-- arrivano soltanto dalla sincronizzazione Gmail/Microsoft. Questa migrazione
-- aggiunge invece le righe `out`, inviate dal provider transazionale del
-- progetto. Non esiste, e non viene richiesto, alcuno scope Gmail di invio.
--
-- Un destinatario uscente è sempre un recapito email già registrato nel CRM.
-- Non è possibile scrivere a un indirizzo libero: una relazione commerciale
-- deve prima avere un'anagrafica verificabile e cancellabile.
-- ============================================================================

do $$ begin
  create type public.email_direction as enum ('in', 'out');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.crm_email_delivery_status as enum ('sent', 'delivered', 'failed');
exception when duplicate_object then null; end $$;

-- Le email importate mantengono la loro connessione readonly; le uscenti non
-- provengono da una casella OAuth e quindi non ne hanno una.
alter table public.email_messages alter column connection_id drop not null;
alter table public.email_messages
  add column if not exists direction public.email_direction not null default 'in',
  add column if not exists delivery_status public.crm_email_delivery_status,
  add column if not exists delivery_error_safe text,
  add column if not exists delivery_provider_id text,
  add column if not exists delivery_event_at timestamptz,
  add column if not exists send_idempotency_key uuid,
  add column if not exists sent_by uuid references auth.users(id) on delete set null;

alter table public.email_messages
  drop constraint if exists email_messages_direction_source;
alter table public.email_messages
  add constraint email_messages_direction_source check (
    (direction = 'in' and connection_id is not null and delivery_status is null)
    or (direction = 'out' and connection_id is null and delivery_status is not null)
  );

create unique index if not exists uq_email_messages_outgoing_idempotency
  on public.email_messages (company_id, send_idempotency_key)
  where direction = 'out';
create index if not exists idx_email_messages_outgoing_delivery
  on public.email_messages (company_id, delivery_status, sent_at desc, id desc)
  where direction = 'out';
create unique index if not exists uq_email_messages_outgoing_provider_id
  on public.email_messages (delivery_provider_id)
  where direction = 'out' and delivery_provider_id is not null;

comment on column public.email_messages.direction is
  'in = importata dalla casella OAuth readonly; out = inviata dal CRM via provider transazionale, mai Gmail API.';
comment on column public.email_messages.delivery_status is
  'Solo email CRM uscenti: sent (accettata dal provider), delivered (webhook provider), failed. last_contact_at usa solo delivered.';
comment on column public.email_messages.delivery_event_at is
  'Istante dichiarato dal provider per l’ultimo evento di consegna applicato; impedisce a webhook fuori ordine di regredire lo stato.';

-- Resend consegna i webhook almeno una volta, non esattamente una volta. Il
-- relativo svix-id viene conservato separatamente dal messaggio: un retry deve
-- ricevere 200 senza applicare una seconda transizione o un secondo contatto.
create table if not exists public.crm_email_webhook_events (
  event_id text primary key,
  event_type text not null,
  provider_email_id text not null,
  occurred_at timestamptz not null,
  received_at timestamptz not null default now()
);

alter table public.crm_email_webhook_events enable row level security;
revoke all on public.crm_email_webhook_events from anon, authenticated, public;

-- Un solo punto atomico applica idempotenza, ordinamento e transizione. Il
-- browser non può chiamarlo: è riservato al service role della Edge Function.
create or replace function public.crm_apply_email_delivery_event(
  p_event_id text,
  p_provider_email_id text,
  p_event_type text,
  p_occurred_at timestamptz,
  p_error_safe text default null
) returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_inserted integer;
  v_status public.crm_email_delivery_status;
begin
  if p_event_id is null or btrim(p_event_id) = ''
     or p_provider_email_id is null or btrim(p_provider_email_id) = ''
     or p_occurred_at is null then
    raise exception 'crm_email_webhook_invalid_event' using errcode = '22023';
  end if;

  insert into public.crm_email_webhook_events(event_id, event_type, provider_email_id, occurred_at)
  values (p_event_id, p_event_type, p_provider_email_id, p_occurred_at)
  on conflict (event_id) do nothing;
  get diagnostics v_inserted = row_count;
  if v_inserted = 0 then return false; end if;

  v_status := case p_event_type
    when 'email.sent' then 'sent'::public.crm_email_delivery_status
    when 'email.delivered' then 'delivered'::public.crm_email_delivery_status
    when 'email.failed' then 'failed'::public.crm_email_delivery_status
    when 'email.bounced' then 'failed'::public.crm_email_delivery_status
    else null
  end;

  if v_status is not null then
    update public.email_messages
       set delivery_status = v_status,
           delivery_error_safe = case when v_status = 'failed' then p_error_safe else null end,
           delivery_event_at = p_occurred_at
     where direction = 'out'
       and delivery_provider_id = p_provider_email_id
       and (
         delivery_event_at is null or delivery_event_at < p_occurred_at
         or (delivery_event_at = p_occurred_at and
           case v_status when 'failed' then 3 when 'delivered' then 2 else 1 end
           > case delivery_status when 'failed' then 3 when 'delivered' then 2 else 1 end)
       );
  end if;

  return true;
end $$;

revoke all on function public.crm_apply_email_delivery_event(text, text, text, timestamptz, text) from public, anon, authenticated;
grant execute on function public.crm_apply_email_delivery_event(text, text, text, timestamptz, text) to service_role;

-- Una trattativa ha il suo collegamento, distinto dai documenti: una email non
-- e' un documento e non va forzata nel ponte crm_opportunity_documents.
create table if not exists public.crm_opportunity_emails (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  opportunity_id uuid not null references public.crm_opportunities(id) on delete cascade,
  email_message_id uuid not null references public.email_messages(id) on delete cascade,
  created_at timestamptz not null default now(),
  constraint uq_crm_opportunity_email unique (opportunity_id, email_message_id)
);

create table if not exists public.crm_outgoing_email_recipients (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  email_message_id uuid not null references public.email_messages(id) on delete cascade,
  contact_method_id uuid not null references public.crm_contact_methods(id) on delete restrict,
  email_address text not null,
  created_at timestamptz not null default now(),
  constraint uq_crm_outgoing_recipient unique (email_message_id, contact_method_id)
);

create table if not exists public.crm_outgoing_email_attachments (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  email_message_id uuid not null references public.email_messages(id) on delete cascade,
  document_id uuid not null references public.documents(id) on delete restrict,
  created_at timestamptz not null default now(),
  constraint uq_crm_outgoing_attachment unique (email_message_id, document_id)
);

-- Un modello e' una famiglia con una variante per lingua; cancellarlo
-- distruggerebbe i riferimenti, quindi si archivia come le altre anagrafiche.
create table if not exists public.crm_email_templates (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  name text not null check (btrim(name) <> ''),
  archived_at timestamptz,
  archived_by uuid references auth.users(id) on delete set null,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists uq_crm_email_template_name_active
  on public.crm_email_templates(company_id, lower(name)) where archived_at is null;

create table if not exists public.crm_email_template_translations (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  template_id uuid not null references public.crm_email_templates(id) on delete cascade,
  locale text not null check (locale in ('it', 'de', 'fr')),
  subject text not null check (btrim(subject) <> ''),
  body_text text not null check (btrim(body_text) <> ''),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint uq_crm_email_template_locale unique(template_id, locale)
);

create table if not exists public.crm_user_email_signatures (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  locale text not null check (locale in ('it', 'de', 'fr')),
  body_text text not null default '',
  updated_at timestamptz not null default now(),
  constraint uq_crm_user_email_signature unique(company_id, user_id, locale)
);

-- Il mittente è scelto per azienda, ma il dominio è verificato dal provider e
-- dichiarato nel secret del runtime. Una riga non basta a far partire un invio.
create table if not exists public.crm_email_senders (
  company_id uuid primary key references public.companies(id) on delete cascade,
  display_name text not null check (btrim(display_name) <> ''),
  from_address text not null check (position('@' in from_address) > 1),
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now()
);

-- Ogni ponte dichiara i tre tenant coinvolti: la RLS protegge il browser, il
-- guardiano protegge anche l'Edge Function e il service role da un id errato.
create or replace function public.crm_guard_outgoing_email_link()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_email_company uuid; v_method_company uuid; v_method_type public.crm_contact_method_type;
begin
  select company_id into v_email_company from public.email_messages where id = new.email_message_id;
  if v_email_company is distinct from new.company_id then raise exception 'crm_email_company_mismatch' using errcode = '23514'; end if;
  if tg_table_name = 'crm_opportunity_emails' then
    if not exists (select 1 from public.crm_opportunities where id = new.opportunity_id and company_id = new.company_id)
    then raise exception 'crm_opportunity_email_company_mismatch' using errcode = '23514'; end if;
  elsif tg_table_name = 'crm_outgoing_email_recipients' then
    select company_id, type into v_method_company, v_method_type from public.crm_contact_methods where id = new.contact_method_id;
    if v_method_company is distinct from new.company_id or v_method_type is distinct from 'email'::public.crm_contact_method_type
    then raise exception 'crm_email_recipient_not_registered' using errcode = '23514'; end if;
  elsif tg_table_name = 'crm_outgoing_email_attachments' then
    if not exists (select 1 from public.documents where id = new.document_id and company_id = new.company_id)
    then raise exception 'crm_email_attachment_company_mismatch' using errcode = '23514'; end if;
  end if;
  return new;
end $$;

drop trigger if exists trg_crm_opportunity_emails_guard on public.crm_opportunity_emails;
create trigger trg_crm_opportunity_emails_guard before insert or update on public.crm_opportunity_emails for each row execute function public.crm_guard_outgoing_email_link();
drop trigger if exists trg_crm_outgoing_email_recipients_guard on public.crm_outgoing_email_recipients;
create trigger trg_crm_outgoing_email_recipients_guard before insert or update on public.crm_outgoing_email_recipients for each row execute function public.crm_guard_outgoing_email_link();
drop trigger if exists trg_crm_outgoing_email_attachments_guard on public.crm_outgoing_email_attachments;
create trigger trg_crm_outgoing_email_attachments_guard before insert or update on public.crm_outgoing_email_attachments for each row execute function public.crm_guard_outgoing_email_link();

-- Contatto = email importata, chiamata/incontro, oppure una CONSEGNA riuscita.
-- Un'accettazione dal provider ('sent') non basta: puo' ancora fallire dopo.
create or replace function public.crm_refresh_last_contact(p_organization_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare v_last timestamptz;
begin
  select max(d) into v_last from (
    select max(coalesce(e.sent_at, e.received_at)) as d
      from public.crm_organization_emails l join public.email_messages e on e.id = l.email_message_id
     where l.organization_id = p_organization_id
       and (e.direction = 'in' or e.delivery_status = 'delivered')
    union all
    select max(i.occurred_at) from public.crm_interactions i
     where i.organization_id = p_organization_id and i.type in ('call', 'meeting')
  ) s;
  perform set_config('ai_swisse.crm_internal', 'on', true);
  update public.crm_organizations set last_contact_at = v_last where id = p_organization_id and last_contact_at is distinct from v_last;
  perform set_config('ai_swisse.crm_internal', '', true);
end $$;

-- L'esito di una mail uscente puo' cambiare dopo l'inserimento; ricalcola tutte
-- le organizzazioni a cui e' collegata senza scrivere contenuto in crm_events.
create or replace function public.crm_touch_last_contact_from_email()
returns trigger language plpgsql security definer set search_path = '' as $$
declare r record;
begin
  for r in select organization_id from public.crm_organization_emails where email_message_id = new.id loop
    perform public.crm_refresh_last_contact(r.organization_id);
  end loop;
  return null;
end $$;
drop trigger if exists trg_crm_outgoing_email_delivery_touch on public.email_messages;
create trigger trg_crm_outgoing_email_delivery_touch after update of delivery_status on public.email_messages
  for each row when (new.direction = 'out') execute function public.crm_touch_last_contact_from_email();

alter table public.crm_opportunity_emails enable row level security;
alter table public.crm_outgoing_email_recipients enable row level security;
alter table public.crm_outgoing_email_attachments enable row level security;
alter table public.crm_email_templates enable row level security;
alter table public.crm_email_template_translations enable row level security;
alter table public.crm_user_email_signatures enable row level security;
alter table public.crm_email_senders enable row level security;

drop policy if exists crm_opp_emails_select on public.crm_opportunity_emails;
create policy crm_opp_emails_select on public.crm_opportunity_emails for select using (public.is_company_member(company_id));
drop policy if exists crm_outgoing_recipients_select on public.crm_outgoing_email_recipients;
create policy crm_outgoing_recipients_select on public.crm_outgoing_email_recipients for select using (public.is_company_member(company_id));
drop policy if exists crm_outgoing_attachments_select on public.crm_outgoing_email_attachments;
create policy crm_outgoing_attachments_select on public.crm_outgoing_email_attachments for select using (public.is_company_member(company_id));
drop policy if exists crm_email_templates_select on public.crm_email_templates;
create policy crm_email_templates_select on public.crm_email_templates for select using (public.is_company_member(company_id));
drop policy if exists crm_email_template_translations_select on public.crm_email_template_translations;
create policy crm_email_template_translations_select on public.crm_email_template_translations for select using (public.is_company_member(company_id));
drop policy if exists crm_email_signatures_select on public.crm_user_email_signatures;
create policy crm_email_signatures_select on public.crm_user_email_signatures for select using (public.is_company_member(company_id));
drop policy if exists crm_email_signatures_write on public.crm_user_email_signatures;
create policy crm_email_signatures_write on public.crm_user_email_signatures for all using (user_id = auth.uid() and public.is_company_member(company_id)) with check (user_id = auth.uid() and public.is_company_member(company_id));
drop policy if exists crm_email_templates_admin on public.crm_email_templates;
create policy crm_email_templates_admin on public.crm_email_templates for all using (public.is_company_admin(company_id)) with check (public.is_company_admin(company_id));
drop policy if exists crm_email_senders_select on public.crm_email_senders;
create policy crm_email_senders_select on public.crm_email_senders for select using (public.is_company_member(company_id));
drop policy if exists crm_email_senders_admin on public.crm_email_senders;
create policy crm_email_senders_admin on public.crm_email_senders for all using (public.is_company_admin(company_id)) with check (public.is_company_admin(company_id));
drop policy if exists crm_email_template_translations_admin on public.crm_email_template_translations;
create policy crm_email_template_translations_admin on public.crm_email_template_translations for all using (public.is_company_admin(company_id)) with check (public.is_company_admin(company_id));

revoke all on public.crm_opportunity_emails, public.crm_outgoing_email_recipients, public.crm_outgoing_email_attachments, public.crm_email_templates, public.crm_email_template_translations, public.crm_user_email_signatures, public.crm_email_senders from anon, authenticated, public;
grant select on public.crm_opportunity_emails, public.crm_outgoing_email_recipients, public.crm_outgoing_email_attachments, public.crm_email_templates, public.crm_email_template_translations, public.crm_user_email_signatures, public.crm_email_senders to authenticated;
grant insert, update on public.crm_user_email_signatures to authenticated;
grant insert, update on public.crm_email_templates, public.crm_email_template_translations to authenticated;
grant insert, update on public.crm_email_senders to authenticated;

-- Il client non puo' creare un'uscente o manipolarne l'esito: passa sempre per
-- send-crm-email, che autorizza l'utente e possiede la chiave del provider.
revoke insert, update, delete on public.email_messages from authenticated;
-- La revoca sopra chiude la nuova superficie di invio, ma conserva le sole due
-- decisioni umane dell'Inbox gia' concesse dalla 0014.
grant update (seen_at, attention_status) on public.email_messages to authenticated;

-- >>>>>>>>>>>>>>>>>>>>  0049_crm_quotes  <<<<<<<<<<<<<<<<<<<<

-- ============================================================================
-- 0049 — PREVENTIVI PDF DAL CRM (FASE 1.2)
--
-- Un preventivo appartiene a una trattativa, ha un numero progressivo per
-- azienda e versioni. Una versione inviata non si riscrive: la successiva
-- nasce con `crm_new_quote_version`, sul modello di contract_term_versions.
--
-- Il PDF è un Documento generato e la sua provenienza è dichiarata dalla
-- coppia `documents.source_type = generated` + `crm_quote_documents`.
-- L'invio resta quello della 0048: Resend, gesto umano, nessuna Gmail API.
-- ============================================================================

alter type public.document_source_type add value if not exists 'generated';

-- Tra la creazione idempotente della riga e la risposta di Resend una email
-- uscente è intenzionalmente senza esito. La 0048 pretendeva subito `sent`,
-- che in caso di crash avrebbe trasformato un tentativo in un invio riuscito.
-- `null` significa soltanto "in corso"; i tre esiti visibili restano invariati.
alter table public.email_messages
  drop constraint if exists email_messages_direction_source;
alter table public.email_messages
  add constraint email_messages_direction_source check (
    (direction = 'in' and connection_id is not null and delivery_status is null)
    or (direction = 'out' and connection_id is null)
  );
comment on column public.email_messages.delivery_status is
  'Email CRM uscente: null durante il tentativo idempotente; sent quando il provider accetta, delivered al webhook, failed in caso di rifiuto. last_contact_at usa solo delivered.';

do $$ begin
  create type public.crm_quote_status as enum (
    'draft', 'sent', 'accepted', 'rejected', 'expired'
  );
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.crm_quote_language as enum ('it', 'de', 'fr');
exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- 1. Dati dell'azienda che devono comparire sul documento.
--
-- Sono sull'azienda, non sulla preferenza dell'utente: il preventivo deve
-- restare uguale per chiunque lo generi. La versione ne salva poi uno snapshot,
-- così un trasloco non cambia retroattivamente un PDF già inviato.
-- ---------------------------------------------------------------------------
alter table public.companies add column if not exists street text;
alter table public.companies add column if not exists postal_code text;
alter table public.companies add column if not exists city text;
alter table public.companies add column if not exists country_code text;
alter table public.companies add column if not exists logo_storage_path text;
alter table public.companies add column if not exists logo_mime_type text;

create or replace function public.companies_quote_identity_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.street := nullif(btrim(new.street), '');
  new.postal_code := nullif(btrim(new.postal_code), '');
  new.city := nullif(btrim(new.city), '');
  new.country_code := upper(nullif(btrim(new.country_code), ''));
  if new.country_code is not null and length(new.country_code) <> 2 then
    raise exception 'company_country_invalid' using errcode = '23514';
  end if;
  if new.logo_storage_path is not null then
    if new.logo_storage_path <> (new.id::text || '/company/logo') then
      raise exception 'company_logo_path_invalid' using errcode = '23514';
    end if;
    if new.logo_mime_type not in ('image/png', 'image/jpeg') then
      raise exception 'company_logo_type_invalid' using errcode = '23514';
    end if;
  else
    new.logo_mime_type := null;
  end if;
  return new;
end $$;

drop trigger if exists trg_companies_quote_identity_guard on public.companies;
create trigger trg_companies_quote_identity_guard
  before insert or update of street, postal_code, city, country_code,
    logo_storage_path, logo_mime_type on public.companies
  for each row execute function public.companies_quote_identity_guard();

-- ---------------------------------------------------------------------------
-- 2. Numero, versioni, righe e provenienza del PDF.
-- ---------------------------------------------------------------------------
create table if not exists public.crm_quotes (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies(id) on delete cascade,
  opportunity_id    uuid not null references public.crm_opportunities(id) on delete cascade,
  organization_id   uuid not null references public.crm_organizations(id) on delete cascade,
  sequence_number   integer not null,
  quote_number      text not null,
  created_by        uuid references auth.users(id) on delete set null,
  created_at        timestamptz not null default now(),
  constraint crm_quote_sequence_positive check (sequence_number > 0),
  constraint crm_quote_number_not_blank check (btrim(quote_number) <> ''),
  constraint uq_crm_quote_sequence unique (company_id, sequence_number),
  constraint uq_crm_quote_number unique (company_id, quote_number)
);

create table if not exists public.crm_quote_versions (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies(id) on delete cascade,
  quote_id          uuid not null references public.crm_quotes(id) on delete cascade,
  opportunity_id    uuid not null references public.crm_opportunities(id) on delete cascade,
  organization_id   uuid not null references public.crm_organizations(id) on delete cascade,
  version           integer not null,
  status            public.crm_quote_status not null default 'draft',
  language          public.crm_quote_language not null,
  issued_on         date not null default current_date,
  valid_until       date not null,
  currency          text not null,
  title             text not null,
  introduction      text,
  notes             text,

  -- Totali scritti solo da crm_quote_refresh_totals(), mai dal browser.
  subtotal_amount   numeric(14,2) not null default 0,
  vat_amount        numeric(14,2) not null default 0,
  total_amount      numeric(14,2) not null default 0,

  -- Snapshot dell'emittente.
  company_legal_name text not null,
  company_uid_che    text,
  company_street     text,
  company_postal_code text,
  company_city       text,
  company_country_code text,
  company_logo_storage_path text,
  company_logo_mime_type text,

  -- Snapshot del destinatario.
  customer_display_name text not null,
  customer_legal_name text,
  customer_vat_number text,
  customer_street text,
  customer_postal_code text,
  customer_city text,
  customer_country_code text,

  based_on_version_id uuid references public.crm_quote_versions(id) on delete set null,
  document_id       uuid references public.documents(id) on delete set null,
  pdf_generated_at  timestamptz,
  sent_at           timestamptz,
  sent_by           uuid references auth.users(id) on delete set null,
  sent_email_id     uuid references public.email_messages(id) on delete set null,
  accepted_at       timestamptz,
  accepted_by       uuid references auth.users(id) on delete set null,
  rejected_at       timestamptz,
  rejected_by       uuid references auth.users(id) on delete set null,
  expired_at        timestamptz,
  expired_by        uuid references auth.users(id) on delete set null,
  created_by        uuid references auth.users(id) on delete set null,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),

  constraint uq_crm_quote_version unique (quote_id, version),
  constraint crm_quote_version_positive check (version > 0),
  constraint crm_quote_currency_iso check (currency ~ '^[A-Z]{3}$'),
  constraint crm_quote_title_not_blank check (btrim(title) <> ''),
  constraint crm_quote_validity check (valid_until >= issued_on),
  constraint crm_quote_totals_nonnegative check (
    subtotal_amount >= 0 and vat_amount >= 0 and total_amount >= 0
    and total_amount = subtotal_amount + vat_amount
  ),
  -- Una bozza modificata conserva il riferimento al file da SOVRASCRIVERE ma
  -- perde `pdf_generated_at`: quel file è obsoleto e send-crm-email lo rifiuta.
  constraint crm_quote_pdf_pair check (
    pdf_generated_at is null or document_id is not null
  ),
  constraint crm_quote_sent_stamp check (
    (status = 'draft') = (sent_at is null)
  ),
  constraint crm_quote_accepted_stamp check (
    (status = 'accepted') = (accepted_at is not null)
  ),
  constraint crm_quote_rejected_stamp check (
    (status = 'rejected') = (rejected_at is not null)
  ),
  constraint crm_quote_expired_stamp check (
    (status = 'expired') = (expired_at is not null)
  )
);

create table if not exists public.crm_quote_items (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies(id) on delete cascade,
  quote_id          uuid not null references public.crm_quotes(id) on delete cascade,
  quote_version_id  uuid not null references public.crm_quote_versions(id) on delete cascade,
  line_number       integer not null,
  description       text not null,
  quantity          numeric(14,3) not null,
  unit_price        numeric(14,2) not null,
  vat_rate_id       uuid not null references public.finance_vat_rates(id),
  vat_rate          numeric not null,
  vat_source_url    text not null,
  vat_source_title  text,
  vat_checked_at    date not null,
  net_amount        numeric(14,2) generated always as (
    round(quantity * unit_price, 2)
  ) stored,
  vat_amount        numeric(14,2) generated always as (
    round(round(quantity * unit_price, 2) * vat_rate / 100, 2)
  ) stored,
  total_amount      numeric(14,2) generated always as (
    round(quantity * unit_price, 2)
    + round(round(quantity * unit_price, 2) * vat_rate / 100, 2)
  ) stored,
  created_at        timestamptz not null default now(),
  constraint uq_crm_quote_line unique (quote_version_id, line_number),
  constraint crm_quote_line_positive check (line_number > 0),
  constraint crm_quote_item_description check (btrim(description) <> ''),
  constraint crm_quote_item_quantity check (quantity > 0),
  constraint crm_quote_item_price check (unit_price >= 0),
  constraint crm_quote_item_vat check (vat_rate >= 0 and vat_rate <= 100)
);

create table if not exists public.crm_quote_documents (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies(id) on delete cascade,
  quote_id          uuid not null references public.crm_quotes(id) on delete cascade,
  quote_version_id  uuid not null references public.crm_quote_versions(id) on delete cascade,
  document_id       uuid not null references public.documents(id) on delete cascade,
  created_at        timestamptz not null default now(),
  constraint uq_crm_quote_version_document unique (quote_version_id),
  constraint uq_crm_quote_document unique (document_id)
);

create index if not exists idx_crm_quotes_opportunity
  on public.crm_quotes (company_id, opportunity_id, created_at desc);
create index if not exists idx_crm_quote_versions_quote
  on public.crm_quote_versions (quote_id, version desc);
create index if not exists idx_crm_quote_items_version
  on public.crm_quote_items (quote_version_id, line_number);
create index if not exists idx_crm_quote_documents_document
  on public.crm_quote_documents (document_id);

comment on table public.crm_quotes is
  'Preventivo CRM: numero progressivo stabile per azienda e collegamento alla trattativa.';
comment on table public.crm_quote_versions is
  'Versioni del preventivo. Dopo l invio i contenuti e il PDF sono immutabili; una modifica crea una nuova versione.';
comment on table public.crm_quote_items is
  'Voci del preventivo. La valuta vive sulla versione: due valute non possono entrare nello stesso totale.';
comment on table public.crm_quote_documents is
  'Provenienza dichiarata dei PDF generati dal CRM dentro Documenti.';

-- ---------------------------------------------------------------------------
-- 3. Guardiani cross-tenant e immutabilità.
-- ---------------------------------------------------------------------------
create or replace function public.crm_quotes_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_opp record;
begin
  if tg_op = 'UPDATE' then
    raise exception 'crm_quote_immutable' using errcode = '42501';
  end if;
  select o.company_id, o.organization_id into v_opp
    from public.crm_opportunities o where o.id = new.opportunity_id;
  if v_opp.company_id is null
     or v_opp.company_id is distinct from new.company_id
     or v_opp.organization_id is distinct from new.organization_id then
    raise exception 'crm_quote_cross_tenant' using errcode = '23514';
  end if;
  if auth.uid() is not null then new.created_by := auth.uid(); end if;
  return new;
end $$;

drop trigger if exists trg_crm_quotes_guard on public.crm_quotes;
create trigger trg_crm_quotes_guard before insert or update on public.crm_quotes
  for each row execute function public.crm_quotes_guard();

create or replace function public.crm_quote_versions_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_quote record;
  v_mode text := coalesce(current_setting('ai_swisse.quote_write', true), '');
begin
  select q.company_id, q.opportunity_id, q.organization_id into v_quote
    from public.crm_quotes q where q.id = new.quote_id;
  if v_quote.company_id is null
     or v_quote.company_id is distinct from new.company_id
     or v_quote.opportunity_id is distinct from new.opportunity_id
     or v_quote.organization_id is distinct from new.organization_id then
    raise exception 'crm_quote_version_cross_tenant' using errcode = '23514';
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'crm_quote_version_must_start_draft' using errcode = '23514';
    end if;
    if auth.uid() is not null then new.created_by := auth.uid(); end if;
    new.sent_at := null; new.sent_by := null; new.sent_email_id := null;
    new.accepted_at := null; new.accepted_by := null;
    new.rejected_at := null; new.rejected_by := null;
    new.expired_at := null; new.expired_by := null;
    new.created_at := now(); new.updated_at := now();
    return new;
  end if;

  new.company_id := old.company_id;
  new.quote_id := old.quote_id;
  new.opportunity_id := old.opportunity_id;
  new.organization_id := old.organization_id;
  new.version := old.version;
  new.created_by := old.created_by;
  new.created_at := old.created_at;

  if v_mode in ('totals', 'pdf') then
    if old.status <> 'draft' then
      raise exception 'crm_quote_version_immutable' using errcode = '42501';
    end if;
    new.updated_at := now();
    return new;
  end if;

  if v_mode = 'send' then
    if old.status = 'sent' and new.status = 'sent' then return old; end if;
    if old.status <> 'draft' or new.status <> 'sent' or old.pdf_generated_at is null then
      raise exception 'crm_quote_cannot_send' using errcode = '42501';
    end if;
    new.updated_at := now();
    return new;
  end if;

  if v_mode = 'lifecycle' then
    if old.status <> 'sent' or new.status not in ('accepted', 'rejected', 'expired') then
      raise exception 'crm_quote_status_transition_invalid' using errcode = '42501';
    end if;
    new.updated_at := now();
    return new;
  end if;

  if old.status <> 'draft' then
    raise exception 'crm_quote_version_immutable'
      using errcode = '42501', hint = 'Un preventivo inviato non si modifica: si crea una nuova versione.';
  end if;
  if new.status <> 'draft' then
    raise exception 'crm_quote_status_path_required' using errcode = '42501';
  end if;
  -- Qualunque modifica commerciale rende il PDF precedente obsoleto.
  new.pdf_generated_at := null;
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists trg_crm_quote_versions_guard on public.crm_quote_versions;
create trigger trg_crm_quote_versions_guard
  before insert or update on public.crm_quote_versions
  for each row execute function public.crm_quote_versions_guard();

create or replace function public.crm_quote_items_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_version record;
begin
  select v.company_id, v.quote_id, v.status into v_version
    from public.crm_quote_versions v where v.id = new.quote_version_id;
  if v_version.company_id is null or v_version.status <> 'draft' then
    raise exception 'crm_quote_item_version_immutable' using errcode = '42501';
  end if;
  if tg_op <> 'DELETE' and (
    new.company_id is distinct from v_version.company_id
    or new.quote_id is distinct from v_version.quote_id
  ) then
    raise exception 'crm_quote_item_cross_tenant' using errcode = '23514';
  end if;
  return new;
end $$;

drop trigger if exists trg_crm_quote_items_guard on public.crm_quote_items;
create trigger trg_crm_quote_items_guard
  -- DELETE resta protetta dai privilegi (authenticated ha solo SELECT) e deve
  -- poter avvenire per cascata quando si elimina l'azienda o il preventivo.
  before insert or update on public.crm_quote_items
  for each row execute function public.crm_quote_items_guard();

create or replace function public.crm_quote_documents_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_version record;
  v_doc_company uuid;
  v_source text;
begin
  if tg_op = 'UPDATE' then
    raise exception 'crm_quote_document_immutable' using errcode = '42501';
  end if;
  select v.company_id, v.quote_id into v_version
    from public.crm_quote_versions v where v.id = new.quote_version_id;
  select d.company_id, d.source_type::text into v_doc_company, v_source
    from public.documents d where d.id = new.document_id;
  if v_version.company_id is null or v_doc_company is null or v_source <> 'generated'
     or new.company_id is distinct from v_version.company_id
     or new.quote_id is distinct from v_version.quote_id
     or new.company_id is distinct from v_doc_company then
    raise exception 'crm_quote_document_cross_tenant' using errcode = '23514';
  end if;
  return new;
end $$;

drop trigger if exists trg_crm_quote_documents_guard on public.crm_quote_documents;
create trigger trg_crm_quote_documents_guard
  before insert or update on public.crm_quote_documents
  for each row execute function public.crm_quote_documents_guard();

-- Totali SQL decimali, mai JavaScript in virgola mobile.
create or replace function public.crm_quote_refresh_totals(p_version_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform set_config('ai_swisse.quote_write', 'totals', true);
  update public.crm_quote_versions v set
    subtotal_amount = x.subtotal,
    vat_amount = x.vat,
    total_amount = x.total
  from (
    select coalesce(sum(i.net_amount), 0)::numeric(14,2) as subtotal,
           coalesce(sum(i.vat_amount), 0)::numeric(14,2) as vat,
           coalesce(sum(i.total_amount), 0)::numeric(14,2) as total
      from public.crm_quote_items i where i.quote_version_id = p_version_id
  ) x
  where v.id = p_version_id;
end $$;

create or replace function public.crm_quote_items_refresh_totals()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform public.crm_quote_refresh_totals(coalesce(new.quote_version_id, old.quote_version_id));
  return coalesce(new, old);
end $$;

drop trigger if exists trg_crm_quote_items_refresh_totals on public.crm_quote_items;
create trigger trg_crm_quote_items_refresh_totals
  after insert or update or delete on public.crm_quote_items
  for each row execute function public.crm_quote_items_refresh_totals();

-- ---------------------------------------------------------------------------
-- 4. RPC: crea/aggiorna bozza e crea una nuova versione.
-- ---------------------------------------------------------------------------
create or replace function public.crm_save_quote_draft(
  p_company_id uuid,
  p_opportunity_id uuid,
  p_quote_id uuid,
  p_language public.crm_quote_language,
  p_valid_until date,
  p_currency text,
  p_title text,
  p_introduction text,
  p_notes text,
  p_items jsonb
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_quote public.crm_quotes%rowtype;
  v_version public.crm_quote_versions%rowtype;
  v_opp record;
  v_company public.companies%rowtype;
  v_org public.crm_organizations%rowtype;
  v_item jsonb;
  v_rate public.finance_vat_rates%rowtype;
  v_line integer := 0;
  v_sequence integer;
  v_currency text := upper(btrim(coalesce(p_currency, '')));
begin
  if auth.uid() is null then raise exception 'crm_quote_unauthenticated' using errcode = '28000'; end if;
  if not public.is_company_member(p_company_id) then raise exception 'crm_quote_forbidden' using errcode = '42501'; end if;
  if btrim(coalesce(p_title, '')) = '' or v_currency !~ '^[A-Z]{3}$'
     or p_valid_until is null or p_valid_until < current_date
     or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) < 1
     or jsonb_array_length(p_items) > 100 then
    raise exception 'crm_quote_invalid' using errcode = '22023';
  end if;

  select o.*, g.display_name as organization_name into v_opp
    from public.crm_opportunities o
    join public.crm_organizations g on g.id = o.organization_id
   where o.id = p_opportunity_id and o.company_id = p_company_id;
  if v_opp.id is null then raise exception 'crm_quote_cross_tenant' using errcode = '23514'; end if;
  select * into v_company from public.companies where id = p_company_id;
  select * into v_org from public.crm_organizations where id = v_opp.organization_id;

  if p_quote_id is null then
    perform pg_advisory_xact_lock(hashtextextended(p_company_id::text, 0));
    select coalesce(max(q.sequence_number), 0) + 1 into v_sequence
      from public.crm_quotes q where q.company_id = p_company_id;
    insert into public.crm_quotes (
      company_id, opportunity_id, organization_id, sequence_number, quote_number, created_by
    ) values (
      p_company_id, p_opportunity_id, v_opp.organization_id, v_sequence,
      'P-' || lpad(v_sequence::text, 6, '0'), auth.uid()
    ) returning * into v_quote;
    insert into public.crm_quote_versions (
      company_id, quote_id, opportunity_id, organization_id, version, language,
      issued_on, valid_until, currency, title, introduction, notes,
      company_legal_name, company_uid_che, company_street, company_postal_code,
      company_city, company_country_code, company_logo_storage_path, company_logo_mime_type,
      customer_display_name, customer_legal_name, customer_vat_number, customer_street,
      customer_postal_code, customer_city, customer_country_code, created_by
    ) values (
      p_company_id, v_quote.id, p_opportunity_id, v_opp.organization_id, 1, p_language,
      current_date, p_valid_until, v_currency, btrim(p_title), nullif(btrim(p_introduction), ''),
      nullif(btrim(p_notes), ''), v_company.legal_name, v_company.uid_che,
      v_company.street, v_company.postal_code, coalesce(v_company.city, v_company.municipality),
      coalesce(v_company.country_code, 'CH'), v_company.logo_storage_path, v_company.logo_mime_type,
      v_org.display_name, v_org.legal_name, v_org.vat_number, v_org.street,
      v_org.postal_code, v_org.city, v_org.country_code, auth.uid()
    ) returning * into v_version;
  else
    select * into v_quote from public.crm_quotes q
      where q.id = p_quote_id and q.company_id = p_company_id
        and q.opportunity_id = p_opportunity_id;
    if v_quote.id is null then raise exception 'crm_quote_cross_tenant' using errcode = '23514'; end if;
    select * into v_version from public.crm_quote_versions v
      where v.quote_id = v_quote.id order by v.version desc limit 1 for update;
    if v_version.status <> 'draft' then
      raise exception 'crm_quote_new_version_required' using errcode = '42501';
    end if;
    update public.crm_quote_versions set
      language = p_language, issued_on = current_date, valid_until = p_valid_until,
      currency = v_currency, title = btrim(p_title),
      introduction = nullif(btrim(p_introduction), ''), notes = nullif(btrim(p_notes), ''),
      company_legal_name = v_company.legal_name, company_uid_che = v_company.uid_che,
      company_street = v_company.street, company_postal_code = v_company.postal_code,
      company_city = coalesce(v_company.city, v_company.municipality),
      company_country_code = coalesce(v_company.country_code, 'CH'),
      company_logo_storage_path = v_company.logo_storage_path,
      company_logo_mime_type = v_company.logo_mime_type,
      customer_display_name = v_org.display_name, customer_legal_name = v_org.legal_name,
      customer_vat_number = v_org.vat_number, customer_street = v_org.street,
      customer_postal_code = v_org.postal_code, customer_city = v_org.city,
      customer_country_code = v_org.country_code
    where id = v_version.id returning * into v_version;
    delete from public.crm_quote_items where quote_version_id = v_version.id;
  end if;

  for v_item in select value from jsonb_array_elements(p_items) loop
    v_line := v_line + 1;
    if btrim(coalesce(v_item->>'description', '')) = ''
       or coalesce((v_item->>'quantity')::numeric, 0) <= 0
       or coalesce((v_item->>'unitPrice')::numeric, -1) < 0 then
      raise exception 'crm_quote_item_invalid' using errcode = '22023';
    end if;
    select * into v_rate from public.finance_vat_rates r
      where r.id = (v_item->>'vatRateId')::uuid and r.country_code = 'CH'
        and r.valid_from <= current_date and (r.valid_to is null or r.valid_to >= current_date);
    if v_rate.id is null then raise exception 'crm_quote_vat_rate_invalid' using errcode = '22023'; end if;
    insert into public.crm_quote_items (
      company_id, quote_id, quote_version_id, line_number, description,
      quantity, unit_price, vat_rate_id, vat_rate, vat_source_url,
      vat_source_title, vat_checked_at
    ) values (
      p_company_id, v_quote.id, v_version.id, v_line,
      left(btrim(v_item->>'description'), 500), (v_item->>'quantity')::numeric,
      (v_item->>'unitPrice')::numeric, v_rate.id, v_rate.rate,
      v_rate.source_url, v_rate.source_title, v_rate.checked_at
    );
  end loop;
  return v_version.id;
exception when invalid_text_representation or numeric_value_out_of_range then
  raise exception 'crm_quote_item_invalid' using errcode = '22023';
end $$;

create or replace function public.crm_new_quote_version(p_company_id uuid, p_quote_id uuid)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old public.crm_quote_versions%rowtype;
  v_new_id uuid;
begin
  if auth.uid() is null or not public.is_company_member(p_company_id) then
    raise exception 'crm_quote_forbidden' using errcode = '42501';
  end if;
  select v.* into v_old from public.crm_quote_versions v
    join public.crm_quotes q on q.id = v.quote_id
   where v.quote_id = p_quote_id and q.company_id = p_company_id
   order by v.version desc limit 1 for update;
  if v_old.id is null then raise exception 'crm_quote_not_found' using errcode = 'P0002'; end if;
  if v_old.status = 'draft' then return v_old.id; end if;

  insert into public.crm_quote_versions (
    company_id, quote_id, opportunity_id, organization_id, version, language,
    issued_on, valid_until, currency, title, introduction, notes,
    company_legal_name, company_uid_che, company_street, company_postal_code,
    company_city, company_country_code, company_logo_storage_path, company_logo_mime_type,
    customer_display_name, customer_legal_name, customer_vat_number, customer_street,
    customer_postal_code, customer_city, customer_country_code,
    based_on_version_id, created_by
  ) select
    company_id, quote_id, opportunity_id, organization_id, version + 1, language,
    current_date, greatest(current_date, valid_until), currency, title, introduction, notes,
    company_legal_name, company_uid_che, company_street, company_postal_code,
    company_city, company_country_code, company_logo_storage_path, company_logo_mime_type,
    customer_display_name, customer_legal_name, customer_vat_number, customer_street,
    customer_postal_code, customer_city, customer_country_code,
    id, auth.uid()
  from public.crm_quote_versions where id = v_old.id
  returning id into v_new_id;

  insert into public.crm_quote_items (
    company_id, quote_id, quote_version_id, line_number, description, quantity,
    unit_price, vat_rate_id, vat_rate, vat_source_url, vat_source_title, vat_checked_at
  ) select company_id, quote_id, v_new_id, line_number, description, quantity,
      unit_price, vat_rate_id, vat_rate, vat_source_url, vat_source_title, vat_checked_at
    from public.crm_quote_items where quote_version_id = v_old.id order by line_number;
  return v_new_id;
end $$;

create or replace function public.crm_set_quote_status(
  p_company_id uuid, p_quote_version_id uuid, p_status public.crm_quote_status
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null or not public.is_company_member(p_company_id) then
    raise exception 'crm_quote_forbidden' using errcode = '42501';
  end if;
  if p_status not in ('accepted', 'rejected', 'expired') then
    raise exception 'crm_quote_status_transition_invalid' using errcode = '22023';
  end if;
  perform set_config('ai_swisse.quote_write', 'lifecycle', true);
  update public.crm_quote_versions set
    status = p_status,
    accepted_at = case when p_status = 'accepted' then now() else null end,
    accepted_by = case when p_status = 'accepted' then auth.uid() else null end,
    rejected_at = case when p_status = 'rejected' then now() else null end,
    rejected_by = case when p_status = 'rejected' then auth.uid() else null end,
    expired_at = case when p_status = 'expired' then now() else null end,
    expired_by = case when p_status = 'expired' then auth.uid() else null end
  where id = p_quote_version_id and company_id = p_company_id and status = 'sent';
  if not found then raise exception 'crm_quote_status_transition_invalid' using errcode = '42501'; end if;
end $$;

-- Payload unico letto dalla Edge Function attraverso il JWT della persona.
create or replace function public.crm_quote_pdf_payload(
  p_company_id uuid, p_quote_version_id uuid
)
returns jsonb
language sql
security invoker
set search_path = ''
stable
as $$
  select jsonb_build_object(
    'quoteId', q.id, 'quoteNumber', q.quote_number,
    'versionId', v.id, 'version', v.version, 'status', v.status,
    'opportunityId', v.opportunity_id, 'organizationId', v.organization_id,
    'language', v.language, 'issuedOn', v.issued_on, 'validUntil', v.valid_until,
    'currency', v.currency, 'title', v.title, 'introduction', v.introduction,
    'notes', v.notes, 'subtotal', v.subtotal_amount, 'vatTotal', v.vat_amount,
    'total', v.total_amount, 'documentId', v.document_id,
    'company', jsonb_build_object(
      'legalName', v.company_legal_name, 'uidChe', v.company_uid_che,
      'street', v.company_street, 'postalCode', v.company_postal_code,
      'city', v.company_city, 'countryCode', v.company_country_code,
      'logoStoragePath', v.company_logo_storage_path, 'logoMimeType', v.company_logo_mime_type
    ),
    'customer', jsonb_build_object(
      'displayName', v.customer_display_name, 'legalName', v.customer_legal_name,
      'vatNumber', v.customer_vat_number, 'street', v.customer_street,
      'postalCode', v.customer_postal_code, 'city', v.customer_city,
      'countryCode', v.customer_country_code
    ),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'lineNumber', i.line_number, 'description', i.description,
        'quantity', i.quantity, 'unitPrice', i.unit_price, 'vatRate', i.vat_rate,
        'vatSourceUrl', i.vat_source_url, 'vatSourceTitle', i.vat_source_title,
        'vatCheckedAt', i.vat_checked_at, 'netAmount', i.net_amount,
        'vatAmount', i.vat_amount, 'totalAmount', i.total_amount
      ) order by i.line_number)
      from public.crm_quote_items i where i.quote_version_id = v.id
    ), '[]'::jsonb)
  )
  from public.crm_quote_versions v
  join public.crm_quotes q on q.id = v.quote_id
  where v.id = p_quote_version_id and v.company_id = p_company_id
    and v.status = 'draft' and public.is_company_member(p_company_id);
$$;

-- Solo la funzione server registra il file realmente caricato nello Storage.
create or replace function public.crm_register_quote_pdf(
  p_company_id uuid, p_quote_version_id uuid, p_document_id uuid
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_version record;
begin
  select qv.quote_id, qv.opportunity_id, qv.organization_id, qv.status,
         d.company_id as document_company, d.source_type::text as source_type
    into v_version
    from public.crm_quote_versions qv
    join public.documents d on d.id = p_document_id
   where qv.id = p_quote_version_id and qv.company_id = p_company_id;
  if v_version.quote_id is null or v_version.document_company is distinct from p_company_id
     or v_version.source_type <> 'generated' or v_version.status <> 'draft' then
    raise exception 'crm_quote_document_cross_tenant' using errcode = '23514';
  end if;
  insert into public.crm_quote_documents (
    company_id, quote_id, quote_version_id, document_id
  ) values (p_company_id, v_version.quote_id, p_quote_version_id, p_document_id)
  on conflict (quote_version_id) do nothing;
  if not exists (
    select 1 from public.crm_quote_documents qd
     where qd.quote_version_id = p_quote_version_id and qd.document_id = p_document_id
  ) then
    raise exception 'crm_quote_document_version_mismatch' using errcode = '23514';
  end if;
  insert into public.crm_organization_documents (
    company_id, organization_id, document_id, relation, match_reason
  ) values (p_company_id, v_version.organization_id, p_document_id, 'customer', 'manual')
  on conflict (organization_id, document_id) do nothing;
  insert into public.crm_opportunity_documents (
    company_id, opportunity_id, document_id
  ) values (p_company_id, v_version.opportunity_id, p_document_id)
  on conflict (opportunity_id, document_id) do nothing;
  perform set_config('ai_swisse.quote_write', 'pdf', true);
  update public.crm_quote_versions set document_id = p_document_id, pdf_generated_at = now()
    where id = p_quote_version_id;
end $$;

-- Chiamata da send-crm-email DOPO l'accettazione del provider. I documenti
-- arrivano dalla tabella allegati della email registrata, non dal body del
-- browser: riusare una chiave idempotente con altri id non può marcare preventivi.
create or replace function public.crm_mark_attached_quotes_sent(
  p_company_id uuid, p_email_message_id uuid
)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_count integer;
begin
  if not exists (
    select 1 from public.email_messages m
     where m.id = p_email_message_id and m.company_id = p_company_id
       and m.direction = 'out' and m.delivery_status = 'sent'
  ) then raise exception 'crm_quote_email_not_sent' using errcode = '23514'; end if;
  perform set_config('ai_swisse.quote_write', 'send', true);
  update public.crm_quote_versions v set
    status = 'sent', sent_at = now(), sent_by = m.sent_by, sent_email_id = m.id
  from public.crm_quote_documents qd
  join public.crm_outgoing_email_attachments a on a.document_id = qd.document_id
  join public.email_messages m on m.id = a.email_message_id
  where v.id = qd.quote_version_id and v.company_id = p_company_id
    and a.email_message_id = p_email_message_id and v.status = 'draft'
    and v.pdf_generated_at is not null and v.document_id = qd.document_id;
  get diagnostics v_count = row_count;
  return v_count;
end $$;

-- ---------------------------------------------------------------------------
-- 5. RLS, permessi minimi e autoverifica.
-- ---------------------------------------------------------------------------
alter table public.crm_quotes enable row level security;
alter table public.crm_quote_versions enable row level security;
alter table public.crm_quote_items enable row level security;
alter table public.crm_quote_documents enable row level security;

revoke all on public.crm_quotes from anon, authenticated, public;
revoke all on public.crm_quote_versions from anon, authenticated, public;
revoke all on public.crm_quote_items from anon, authenticated, public;
revoke all on public.crm_quote_documents from anon, authenticated, public;

grant select on public.crm_quotes to authenticated;
grant select on public.crm_quote_versions to authenticated;
grant select on public.crm_quote_items to authenticated;
grant select on public.crm_quote_documents to authenticated;

drop policy if exists crm_quotes_select_member on public.crm_quotes;
create policy crm_quotes_select_member on public.crm_quotes for select to authenticated
  using ((select public.is_company_member(company_id)));
drop policy if exists crm_quote_versions_select_member on public.crm_quote_versions;
create policy crm_quote_versions_select_member on public.crm_quote_versions for select to authenticated
  using ((select public.is_company_member(company_id)));
drop policy if exists crm_quote_items_select_member on public.crm_quote_items;
create policy crm_quote_items_select_member on public.crm_quote_items for select to authenticated
  using ((select public.is_company_member(company_id)));
drop policy if exists crm_quote_documents_select_member on public.crm_quote_documents;
create policy crm_quote_documents_select_member on public.crm_quote_documents for select to authenticated
  using ((select public.is_company_member(company_id)));

revoke all on function public.crm_quote_refresh_totals(uuid) from public, anon, authenticated;
revoke all on function public.crm_save_quote_draft(uuid, uuid, uuid, public.crm_quote_language, date, text, text, text, text, jsonb) from public, anon;
revoke all on function public.crm_new_quote_version(uuid, uuid) from public, anon;
revoke all on function public.crm_set_quote_status(uuid, uuid, public.crm_quote_status) from public, anon;
revoke all on function public.crm_quote_pdf_payload(uuid, uuid) from public, anon;
revoke all on function public.crm_register_quote_pdf(uuid, uuid, uuid) from public, anon, authenticated;
revoke all on function public.crm_mark_attached_quotes_sent(uuid, uuid) from public, anon, authenticated;

grant execute on function public.crm_save_quote_draft(uuid, uuid, uuid, public.crm_quote_language, date, text, text, text, text, jsonb) to authenticated;
grant execute on function public.crm_new_quote_version(uuid, uuid) to authenticated;
grant execute on function public.crm_set_quote_status(uuid, uuid, public.crm_quote_status) to authenticated;
grant execute on function public.crm_quote_pdf_payload(uuid, uuid) to authenticated;
grant execute on function public.crm_register_quote_pdf(uuid, uuid, uuid) to service_role;
grant execute on function public.crm_mark_attached_quotes_sent(uuid, uuid) to service_role;

do $$
declare
  v_bad text;
begin
  select string_agg(c.relname, ', ') into v_bad
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public'
     and c.relname in ('crm_quotes', 'crm_quote_versions', 'crm_quote_items', 'crm_quote_documents')
     and not c.relrowsecurity;
  if v_bad is not null then raise exception '0049: RLS non attiva su %', v_bad; end if;

  select string_agg(p.table_name || ':' || p.privilege_type, ', ') into v_bad
    from information_schema.role_table_grants p
   where p.table_schema = 'public'
     and p.table_name in ('crm_quotes', 'crm_quote_versions', 'crm_quote_items', 'crm_quote_documents')
     and lower(p.grantee) in ('anon', 'public');
  if v_bad is not null then raise exception '0049: privilegi anon/public inattesi: %', v_bad; end if;

  select string_agg(p.table_name || ':' || p.privilege_type, ', ') into v_bad
    from information_schema.role_table_grants p
   where p.table_schema = 'public'
     and p.table_name in ('crm_quotes', 'crm_quote_versions', 'crm_quote_items', 'crm_quote_documents')
     and lower(p.grantee) = 'authenticated' and p.privilege_type <> 'SELECT';
  if v_bad is not null then raise exception '0049: il client può scrivere le tabelle preventivi: %', v_bad; end if;
end $$;

